const ENRICHED_PATH = [process.env.PATH, "/opt/homebrew/bin", "/usr/local/bin", "/usr/bin"].filter(Boolean).join(":");
const EXEC_TIMEOUT_MS = 10_000;
// Hold references to spawned children so they can't be GC'd before exit/reaping
const _activeChildren = new Set<ReturnType<typeof exec>>();
const execAsync = (cmd: string, opts?: any): Promise<{ stdout: string; stderr: string }> => {
  return new Promise((resolve, reject) => {
    const child = exec(cmd, {
      encoding: "utf8",
      timeout: EXEC_TIMEOUT_MS,
      ...opts,
      env: { ...process.env, PATH: ENRICHED_PATH, ...(opts?.env || {}) },
    }, (err, stdout, stderr) => {
      _activeChildren.delete(child);
      if (err) return reject(err);
      resolve({ stdout: String(stdout), stderr: String(stderr) });
    });
    _activeChildren.add(child);
  });
};


// Drop inherited Claude session markers before SAFE_ENV is captured (see agentEnv.ts).
scrubAgentEnv(process.env);

const SAFE_ENV = { ...process.env, PATH: ENRICHED_PATH };

// tmux clients can wedge in a busy loop when their server dies mid-protocol,
// and a wedged client ignores SIGTERM — leaving 100%-CPU zombies that survive
// Node's exec timeout. Default to SIGKILL so a timeout actually reaps the process.
function tmuxExecSync(args: string[], opts?: { timeout?: number; killSignal?: string; env?: Record<string, string | undefined> }): string {
  return execFileSync("tmux", args, {
    timeout: opts?.timeout ?? EXEC_TIMEOUT_MS,
    killSignal: (opts?.killSignal ?? "SIGKILL") as any,
    encoding: "utf-8",
    env: { ...SAFE_ENV, ...opts?.env },
  }).toString();
}

async function tmuxExec(args: string[], opts?: { timeout?: number; killSignal?: string; env?: Record<string, string | undefined> }): Promise<{ stdout: string; stderr: string }> {
  return _execFileAsync("tmux", args, {
    timeout: opts?.timeout ?? EXEC_TIMEOUT_MS,
    killSignal: (opts?.killSignal ?? "SIGKILL") as any,
    env: { ...SAFE_ENV, ...opts?.env },
  });
}

async function getTmuxSessionOption(sessionName: string, optionName: string): Promise<string | null> {
  try {
    const { stdout } = await tmuxExec(["show-options", "-qv", "-t", sessionName, optionName]);
    const value = stdout.trim();
    return value || null;
  } catch {
    return null;
  }
}

async function setTmuxSessionOption(sessionName: string, optionName: string, value: string): Promise<void> {
  await tmuxExec(["set-option", "-q", "-t", sessionName, optionName, value]);
}

export function isTmuxSessionMetadataMatch(storedSessionId: string | null | undefined, sessionId: string): boolean {
  return typeof storedSessionId === "string" && storedSessionId === sessionId;
}

async function tmuxSessionMatchesFullSessionId(sessionName: string, sessionId: string): Promise<boolean> {
  const stored = await getTmuxSessionOption(sessionName, "@codecast_session_id");
  return isTmuxSessionMetadataMatch(stored, sessionId);
}

// Map a (possibly foreign) recorded path to a local checkout by convention.
// Pure resolution lives in resolveLocalRepoPath (projectPathResolver) so it's
// unit-testable; this wires in the daemon's config/learned maps, $HOME, logging,
// and the learn-on-hit side effect. The pure resolver walks ancestors of the
// path so a SUBDIR recorded on another machine
// (/Users/m1/work/codecast/packages/cli) resolves via its repo ancestor
// ("codecast") even though the leaf ("cli") names no repo — see
// resolveLocalRepoPath for the rationale.
function resolveLocalRepo(remotePath: string): string | null {
  const resolved = resolveLocalRepoPath({
    remotePath,
    home: process.env.HOME || "/tmp",
    userMap: readConfig()?.project_mappings ?? null,
    learnedMap: readProjectMap(),
    onLearn: (name, localDir) => recordProjectMapping(name, localDir),
  });
  if (resolved && resolved !== remotePath) {
    log(`Resolved remote CWD ${remotePath} -> ${resolved}`);
  }
  return resolved;
}

// Claude indexes a session by the slug of the cwd it runs in:
// ~/.claude/projects/<cwd-slug>/<sessionId>.jsonl. When we reconstitute a session
// whose origin path lives on another machine (a fork, or any cross-host resume),
// the JSONL must land under the *locally-resolved* repo path — the same cwd
// `claude --resume` will actually use — or Claude reports "No conversation found
// with session ID" and the resume crashes, poisoning the fatal-reason cache and
// falling back to a blank session. Resolve the write dir the same way we resolve
// the resume cwd so the two always agree.
function localSessionDir(remotePath?: string): string | undefined {
  if (!remotePath) return undefined;
  return resolveLocalRepo(remotePath) ?? remotePath;
}

// Resolve the cwd a resume/reconstitute must run in, or null to REFUSE. Wires the
// daemon's resolveLocalRepo + (when a conversation is known) a git-remote remap
// through the sync service. Mirrors the start_session contract so a resume that
// lands on a machine without the checkout never silently runs in $HOME (which
// mislabels the project as the home dir — see resolveResumeCwd).
async function resolveResumeCwdOrRefuse(opts: {
  recordedCwd?: string;
  cwdOverride?: string;
  conversationId?: string;
}): Promise<string | null> {
  const conversationId = opts.conversationId;
  return resolveResumeCwd({
    cwdOverride: opts.cwdOverride,
    recordedCwd: opts.recordedCwd,
    resolveLocalRepo,
    remapViaRemote: (conversationId && syncServiceRef)
      ? async () => {
          const svc = syncServiceRef!;
          const info = await svc.getProjectInfo(conversationId).catch(() => null);
          const resolved = await resolveLocalProjectPath({
            projectPath: info?.project_path ?? opts.recordedCwd ?? null,
            gitRoot: info?.git_root ?? null,
            gitRemoteUrl: info?.git_remote_url ?? null,
            findCandidates: (url) => svc.findLocalCheckouts(url).catch(() => []),
          });
          return resolved?.path ?? null;
        }
      : undefined,
  });
}

// "Clone it first" is only an actionable banner when there is a git remote to
// clone. This predicate is consulted ONLY after every resolution attempt has
// already failed (recorded path absent here, no git-remote checkout, and no
// convention/ancestor match via resolveLocalRepo). At that point a recorded path
// alone gives the user nothing to act on — they can't recreate another machine's
// home dir, and "No local checkout for <unknown remote> (recorded path
// /Users/m1/…)" is a dead end. So a foreign path with no remote is suppressed
// (stay silent, clear any stale banner); only a nameable remote earns the banner.
export function noLocalCheckoutBannerActionable(args: {
  remote: string | null | undefined;
  recordedPath?: string | null | undefined;
}): boolean {
  return !!args.remote;
}

// When a resume can't be placed in a real local checkout, mirror start_session:
// stay silent if another device owns the conversation (it will run it), else
// surface "clone it first" on the conversation. Never falls back to $HOME.
async function refuseResumeNoLocalCheckout(
  sessionId: string,
  conversationId: string | undefined,
  recordedCwd: string | undefined,
): Promise<void> {
  const short = sessionId.slice(0, 8);
  if (conversationId && syncServiceRef) {
    const owner = await syncServiceRef.getConversationOwner(conversationId).catch(() => null);
    if (owner && owner !== deviceId()) {
      log(`[REMOTE] resume ${short}: no local checkout for ${recordedCwd ?? "<unknown>"}, owned by ${owner.slice(0, 8)} — staying silent`);
      return;
    }
    const info = await syncServiceRef.getProjectInfo(conversationId).catch(() => null);
    const remote = info?.git_remote_url ?? null;
    // Nothing to clone, nothing to point at → clear any stale banner and stay
    // silent rather than scaring the user with a dead-end "clone it first".
    if (!noLocalCheckoutBannerActionable({ remote, recordedPath: recordedCwd })) {
      syncServiceRef.setSessionError(conversationId).catch(() => {});
      log(`[REMOTE] resume ${short}: no local checkout and no remote/path to act on — staying silent (cleared any stale banner)`);
      return;
    }
    const err = `No local checkout for ${remote ?? "<unknown remote>"} (recorded path ${recordedCwd ?? "unknown"} doesn't exist here). Clone it first.`;
    syncServiceRef.setSessionError(conversationId, err).catch(() => {});
    log(`[REMOTE] resume refused for ${short}: ${err}`);
  } else {
    log(`Cannot auto-resume ${short}: recorded cwd ${recordedCwd ?? "<unknown>"} not found locally; refusing (no $HOME fallback)`);
  }
}

// Deterministic per-remote checkout dir for a reparented session. Keyed by a
// hash of the remote so two repos with the same basename never collide.
/** A source-published working tree replayed into a reparent checkout. */
interface RestoredWork {
  /** The session's real branch, from the snapshot — not the remote's default. */
  branch: string;
  /** True when uncommitted work was reproduced here. */
  appliedWork: boolean;
  applyError?: string;
}

/** What ensureReparentedCheckout prepared for a reparented session to resume in. */
interface ReparentedCheckout {
  path: string;
  /** True when this machine cloned the repo just now; false when a checkout was already here. */
  cloned: boolean;
  remote?: string;
  branch?: string;
  /** Set when the source's working-tree snapshot was found and replayed. */
  restored?: RestoredWork;
}

function reparentCheckoutDir(remote: string): string {
  const home = process.env.HOME || "/tmp";
  const name = (remote.split("/").pop() || "repo").replace(/\.git$/, "").replace(/[^A-Za-z0-9._-]/g, "-");
  const hash = createHash("sha1").update(remote).digest("hex").slice(0, 8);
  return path.join(home, ".codecast", "reparented", `${name}-${hash}`);
}

// A session reparented onto THIS machine (cast pull / reparentSessionToDevice)
// may have its repo checked out on the SOURCE machine only. When no local
// checkout resolves, clone the git remote into a deterministic dir and learn the
// mapping, so the resume — and its reconstruct-from-Convex JSONL write, which
// lands under the resolved cwd — has a real directory to run in. Returns the
// local checkout path, or undefined if nothing could be prepared (the caller
// then falls through to the normal refuse-with-banner path). Idempotent: never
// re-clones an existing checkout. The clone is ASYNC (execFileAsync) so a large
// repo never blocks the daemon's event loop and stalls other live sessions.
//
// Reports WHAT it prepared, not just where: a fresh clone and a reused local
// checkout are different worlds for the resuming agent (a clone holds only
// pushed work and sits on the remote's default branch), and the reorientation
// notice has to tell them apart to stay honest. See sessionMoveNotice.ts.
async function ensureReparentedCheckout(
  conversationId: string | undefined,
  recordedPath: string | undefined,
  remoteHint?: string,
): Promise<ReparentedCheckout | undefined> {
  // Already resolvable locally (a prior reparent clone, or the repo happens to
  // be here)? Reuse it — don't clone twice.
  const existing = await resolveResumeCwdOrRefuse({
    recordedCwd: recordedPath,
    cwdOverride: recordedPath,
    conversationId,
  }).catch(() => null);
  if (existing) {
    log(`[REPARENT] checkout already resolvable locally: ${existing}`);
    return { path: existing, cloned: false, branch: readBranch(existing) };
  }
  if (!conversationId || !syncServiceRef) return undefined;

  // The mutation resolves the remote at pull time and embeds it in the command
  // (conversation git_remote_url stamping is unreliable — ct-38666); fall back
  // to the conversation record for older commands.
  let remote = remoteHint;
  if (!remote) {
    const info = await syncServiceRef.getProjectInfo(conversationId).catch(() => null);
    remote = info?.git_remote_url ?? undefined;
  }
  if (!remote) {
    log(`[REPARENT] no local checkout and no git remote known for ${conversationId.slice(0, 12)} — cannot clone; falling through to the normal refuse path`);
    return undefined;
  }

  const dest = reparentCheckoutDir(remote);
  let cloned = false;
  try {
    if (!fs.existsSync(path.join(dest, ".git"))) {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      log(`[REPARENT] cloning ${remote} → ${dest}`);
      try {
        // Uses the machine's own git credentials (SSH/helper) — the destination
        // user must have access to the repo, which mirrors the ownership model.
        await _execFileAsync("git", ["clone", remote, dest], {
          timeout: 10 * 60_000,
          maxBuffer: 64 * 1024 * 1024,
        });
        cloned = true;
      } catch (cloneErr: any) {
        log(`[REPARENT] clone failed: ${(cloneErr?.stderr || cloneErr?.message || String(cloneErr)).slice(0, 200)}`);
        // Remove a partial clone so a retry starts clean.
        try { if (fs.existsSync(dest)) fs.rmSync(dest, { recursive: true, force: true }); } catch {}
        return undefined;
      }
    }
    // Learn the mapping so subsequent resolves (and re-resumes) find it directly.
    recordProjectMapping(path.basename(dest), dest);

    // The clone above is only what was PUSHED, on the remote's default branch.
    // If the source published a working-tree snapshot (sweepWipSnapshots), replay
    // it: land on the session's real branch and restore its uncommitted work.
    // Best-effort — a source on an older CLI simply has no snapshot, and the
    // clone stands on its own (the notice then says only pushed work is here).
    let restored: RestoredWork | undefined;
    if (conversationId) {
      try {
        const r = await restoreWipSnapshot(dest, { remote: "origin", conversationId });
        if (r) {
          restored = { branch: r.branch, appliedWork: r.appliedWork, applyError: r.applyError };
          log(
            `[REPARENT] restored snapshot for ${conversationId.slice(0, 12)}: branch=${r.branch} work=${r.appliedWork ? "reapplied" : "none"}${r.applyError ? ` applyError=${r.applyError}` : ""}`,
          );
        }
      } catch (e) {
        log(`[REPARENT] snapshot restore failed: ${(e as Error)?.message ?? e}`);
      }
    }
    return { path: dest, cloned, remote, branch: readBranch(dest), restored };
  } catch (e) {
    log(`[REPARENT] checkout prep error: ${e instanceof Error ? e.message : String(e)}`);
    return undefined;
  }
}

/** Best-effort branch name for a checkout — never throws; the notice simply
 * omits the branch when it can't be read rather than blocking a resume. */
function readBranch(cwd: string): string | undefined {
  try {
    return currentBranch(cwd) || undefined;
  } catch {
    return undefined;
  }
}

/**
 * Tell a reparented agent what changed underneath it.
 *
 * `cast pull` hands a session to a machine that clones the repo itself, so the
 * agent can wake in a cwd it has never seen, on the remote's default branch
 * rather than its own, without any work that was never pushed — and, when the
 * session crossed accounts, under a different user's agent config entirely.
 * Nothing else told it: the SSH move path has sent a notice since it shipped,
 * the reparent path never has.
 *
 * Composed here, on the destination, because this is the machine that can
 * actually check these things (see sessionMoveNotice.ts). Rides the normal
 * pending-message rail, which waits for a live session, so it lands as the
 * agent's first turn after the resume. Best-effort throughout: a resume that
 * worked must never fail because its notice didn't send.
 */
async function sendReparentNotice(opts: {
  conversationId: string;
  sessionId: string;
  priorCwd?: string;
  checkout?: ReparentedCheckout;
  /** Raw parsed resume_session args — coerced by reparentNotice. */
  command: ReparentCommandFacts;
}): Promise<void> {
  if (!syncServiceRef) return;
  const notice = reparentNotice({
    destinationLabel: deviceLabel(),
    priorCwd: opts.priorCwd,
    checkout: opts.checkout
      ? {
          cwd: opts.checkout.path,
          cloned: opts.checkout.cloned,
          remote: opts.checkout.remote,
          // With a restored snapshot the branch IS the session's own, so prefer
          // the snapshot's over whatever the clone happened to check out.
          branch: opts.checkout.restored?.branch ?? opts.checkout.branch,
          restored: opts.checkout.restored
            ? {
                appliedWork: opts.checkout.restored.appliedWork,
                applyError: opts.checkout.restored.applyError,
              }
            : undefined,
        }
      : undefined,
    command: opts.command,
  });
  if (!notice) return;
  try {
    await syncServiceRef.enqueueUserMessage(
      opts.conversationId,
      notice,
      `reparent-notice-${opts.conversationId}`,
    );
    log(`[REPARENT] reorientation notice queued for ${opts.sessionId.slice(0, 8)}`);
  } catch (e) {
    log(
      `[REPARENT] reorientation notice not sent for ${opts.sessionId.slice(0, 8)}: ${e instanceof Error ? e.message : String(e)}`,
    );
  }
}

function validatePath(p: string): string | null {
  if (!p || typeof p !== "string") return null;
  if (!path.isAbsolute(p)) return null;
  if (/[;|&`$(){}<>"\r\n\0]/.test(p)) return null;
  const resolved = path.resolve(p);
  if (resolved !== p && resolved !== p.replace(/\/+$/, "")) return null;
  if (!fs.existsSync(resolved)) return null;
  return resolved;
}

const SAFE_ARG_RE = /^[a-zA-Z0-9_.\/=:@%+, -]+$/;
function sanitizeBinaryArgs(args: string[]): string[] {
  return args.filter(a => {
    if (!SAFE_ARG_RE.test(a)) {
      log(`[SECURITY] Rejected unsafe binary arg: ${a}`);
      return false;
    }
    return true;
  });
}

function validateTmuxTarget(target: string): boolean {
  return /^[a-zA-Z0-9_.:-]+$/.test(target);
}

// SIGKILL a process AND every descendant. `tmux kill-session` only SIGHUPs the
// pane's foreground group, so claude's children — MCP servers, `caffeinate`,
// tool subprocesses in their own process groups — routinely survive, orphaned to
// init. Walk the parent→child tree with `pgrep -P` and kill leaves-first so a
// dying parent can't reparent a child out from under us before we reach it.
async function reapPidTree(rootPid: number): Promise<number> {
  if (!Number.isInteger(rootPid) || rootPid <= 1 || rootPid === process.pid) return 0;
  const ordered: number[] = [];
  const queue = [rootPid];
  const seen = new Set<number>([rootPid]);
  while (queue.length) {
    const pid = queue.shift()!;
    ordered.push(pid);
    try {
      const { stdout } = await execAsync(`pgrep -P ${pid}`, { timeout: 3000, killSignal: "SIGKILL" });
      for (const tok of stdout.trim().split(/\s+/)) {
        const child = parseInt(tok, 10);
        if (Number.isInteger(child) && child > 1 && child !== process.pid && !seen.has(child)) {
          seen.add(child);
          queue.push(child);
        }
      }
    } catch {}
  }
  let killed = 0;
  for (const pid of ordered.reverse()) {
    try { process.kill(pid, "SIGKILL"); killed++; } catch {}
  }
  return killed;
}

// Fully terminate a tmux session: reap each pane's whole process tree (so no
// orphaned claude/MCP/caffeinate survives), THEN kill the session. Order matters
// — once the session is gone we can't enumerate its pane pids.
async function killTmuxSessionAndTree(tmuxSession: string): Promise<void> {
  if (!validateTmuxTarget(tmuxSession)) return;
  try {
    const { stdout } = await tmuxExec(
      ["list-panes", "-t", tmuxSession, "-F", "#{pane_pid}"],
      { timeout: 3000, killSignal: "SIGKILL" },
    );
    for (const tok of stdout.trim().split(/\s+/)) {
      const panePid = parseInt(tok, 10);
      if (Number.isInteger(panePid)) await reapPidTree(panePid);
    }
  } catch {}
  try { await tmuxExec(["kill-session", "-t", tmuxSession]); } catch {}
}

// A long gap between timer ticks has two very different causes: the MACHINE slept
// (the process consumed ~no CPU during the gap) or the EVENT LOOP was pinned by
// synchronous work (the process burned CPU the whole time). They demand opposite
// responses: a real wake needs recovery (watcher restart + unsynced sweep), while a
// busy stall must NOT trigger recovery — the sweep it fires is itself the kind of
// work that pins the loop, so recovery-on-stall becomes a self-sustaining freeze
// loop (observed 2026-08-14: stall → "Sleep detected" → sweep → stall → …).
// Threshold is deliberately low: a truly suspended process accrues ~zero CPU, so
// anything above 20% of wall time can only be a busy process.
export function classifyTickGap(elapsedMs: number, cpuMs: number): "sleep" | "stall" {
  return cpuMs >= elapsedMs * 0.2 ? "stall" : "sleep";
}

// Backend outage clock behind the self-heal restart. It must count only time the
// backend was unreachable while the machine was AWAKE. A closed lid on battery
// yields short maintenance wakes with no network: each one fails the heartbeat
// and starts the clock, and the first real wake then reads "recovered after
// 1701s down" and restarts a healthy daemon (2026-08-16, mid-delivery). A
// suspend therefore clears the clock; a still-dead backend after wake restarts
// it from the wake, and the 3-minute threshold applies from there.
export class BackendOutageClock {
  private downSince = 0;
  markFailure(now = Date.now()): void { if (this.downSince === 0) this.downSince = now; }
  /** Length of the outage that just ended, in ms; 0 when there was none. */
  markSuccess(now = Date.now()): number {
    if (this.downSince === 0) return 0;
    const downFor = now - this.downSince;
    this.downSince = 0;
    return downFor;
  }
  noteSuspend(): void { this.downSince = 0; }
}
const backendOutage = new BackendOutageClock();

// Sleep/wake detection: if the last tick was more than 30s ago, we probably just woke from sleep.
// During the wake grace period, skip polling to let tmux recover and avoid zombie accumulation.
// The grace period applies to stalls too — after the loop unfreezes, a short polling
// pause helps drain the backlog before piling new work on.
let lastTickTime = Date.now();
let lastTickCpu = process.cpuUsage();
const SLEEP_DETECTION_THRESHOLD_MS = 30_000;
const WAKE_GRACE_PERIOD_MS = 5_000;
let wakeGraceUntil = 0;
setInterval(() => {
  const now = Date.now();
  const elapsed = now - lastTickTime;
  const cpuDelta = process.cpuUsage(lastTickCpu);
  lastTickCpu = process.cpuUsage();
  if (elapsed > SLEEP_DETECTION_THRESHOLD_MS) {
    const cpuMs = (cpuDelta.user + cpuDelta.system) / 1000;
    wakeGraceUntil = now + WAKE_GRACE_PERIOD_MS;
    if (classifyTickGap(elapsed, cpuMs) === "stall") {
      log(`Event-loop stall (${Math.round(elapsed / 1000)}s gap, ${Math.round(cpuMs / 1000)}s CPU), grace period until ${new Date(wakeGraceUntil).toISOString()}`);
    } else {
      log(`Sleep detected (${Math.round(elapsed / 1000)}s gap), grace period until ${new Date(wakeGraceUntil).toISOString()}`);
      backendOutage.noteSuspend();
    }
  }
  lastTickTime = now;
}, 5_000);
function isInWakeGrace(): boolean { return Date.now() < wakeGraceUntil; }


const CONFIG_DIR = process.env.HOME + "/.codecast";
const CONFIG_FILE = path.join(CONFIG_DIR, "config.json");
// Under `bun test` (which sets NODE_ENV=test) every log() from imported daemon
