const AUTH_FAILURE_THRESHOLD = 5;
const WATCHDOG_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes
const RECONCILIATION_INTERVAL_MS = 60 * 60 * 1000; // 1 hour
const WATCHDOG_STALE_THRESHOLD_MS = 10 * 60 * 1000; // 10 minutes
const VERSION_CHECK_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes
const LOG_FLUSH_INTERVAL_MS = 15 * 1000; // 15 seconds - flush more frequently
const MAX_LOG_QUEUE_SIZE = 500;
const LOG_QUEUE_FILE = path.join(process.env.HOME || "", ".codecast", "log-queue.json");
const EVENT_LOOP_CHECK_INTERVAL_MS = 30 * 1000; // 30 seconds
const EVENT_LOOP_LAG_THRESHOLD_MS = 60 * 1000; // 1 minute of lag = frozen
// External-watchdog staleness threshold lives in supervision.ts
// (DAEMON_HEARTBEAT_STALE_MS) so the shell script and the compiled pass agree.
const STUCK_CONNECTION_THRESHOLD_MS = 3 * 60 * 1000; // 3 min disconnected = stuck, trigger self-heal
const SELF_HEAL_COOLDOWN_MS = 10 * 60 * 1000; // 10 min between self-heal restarts

type LogLevel = "debug" | "info" | "warn" | "error";

interface RemoteLog {
  level: LogLevel;
  message: string;
  metadata?: {
    session_id?: string;
    error_code?: string;
    stack?: string;
  };
  timestamp: number;
}

let remoteLogQueue: RemoteLog[] = [];
let syncServiceRef: SyncService | null = null;
let retryQueueRef: RetryQueue | null = null;
let conversationCacheRef: ConversationCache | null = null;
let daemonVersion: string | undefined;
let activeConfig: Config | null = null;
const platform = process.platform;

function loadPersistedLogQueue(): void {
  try {
    if (fs.existsSync(LOG_QUEUE_FILE)) {
      const data = JSON.parse(fs.readFileSync(LOG_QUEUE_FILE, "utf-8"));
      if (Array.isArray(data) && data.length > 0) {
        remoteLogQueue = [...data, ...remoteLogQueue].slice(-MAX_LOG_QUEUE_SIZE);
        fs.unlinkSync(LOG_QUEUE_FILE);
      }
    }
  } catch {}
}

function persistLogQueue(): void {
  if (remoteLogQueue.length === 0) return;
  try {
    fs.writeFileSync(LOG_QUEUE_FILE, JSON.stringify(remoteLogQueue), { mode: 0o600 });
  } catch {}
}

function getSiteUrl(): string | null {
  const config = activeConfig || readConfig();
  if (!config?.convex_url) return null;
  return config.convex_url.replace(".cloud", ".site");
}

function getAuthToken(): string | null {
  const config = activeConfig || readConfig();
  return config?.auth_token || null;
}

async function flushRemoteLogsViaHttp(): Promise<void> {
  if (remoteLogQueue.length === 0) return;
  const siteUrl = getSiteUrl();
  const token = getAuthToken();
  if (!siteUrl || !token) return;

  const logsToSend = remoteLogQueue.splice(0, 100);
  const logsWithMeta = logsToSend.map(l => ({
    ...l,
    daemon_version: daemonVersion,
    platform,
  }));

  try {
    const response = await fetch(`${siteUrl}/cli/log-batch`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ api_token: token, logs: logsWithMeta }),
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
      remoteLogQueue.unshift(...logsToSend);
      persistLogQueue();
    }
  } catch {
    remoteLogQueue.unshift(...logsToSend);
    persistLogQueue();
  }
}

function sendLogImmediate(level: LogLevel, message: string, metadata?: RemoteLog["metadata"]): void {
  const siteUrl = getSiteUrl();
  const token = getAuthToken();
  if (!siteUrl || !token) return;

  fetch(`${siteUrl}/cli/log`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      api_token: token,
      level,
      message: message.slice(0, 2000),
      metadata,
      cli_version: daemonVersion,
      platform,
    }),
    signal: AbortSignal.timeout(10_000),
  }).catch(() => {});
}

const IDLE_DEBOUNCE_MS = 5_000;
// Coalesce a streaming agent's rapid JSONL appends into fewer, fatter addMessages
// batches. Each batch is a server mutation that reads+patches the conversation
// hot-doc and schedules side-effects, so cutting batch count is the cheapest way to
// relieve a saturated backend when many sessions sync at once. 300ms keeps the web
// view feeling near-live; maxWait flushes a session that never pauses.
const MESSAGE_SYNC_DEBOUNCE: InvalidateSyncOptions = { debounceMs: 300, maxWaitMs: 2_000 };
const idleTimers = new Map<string, ReturnType<typeof setTimeout>>();
const lastIdleNotifiedSize = new Map<string, number>();
const lastWorkingStatusSent = new Map<string, number>();
const WORKING_STATUS_THROTTLE_MS = 10_000;
const lastSentAgentStatus = new Map<string, AgentStatus>();
// When each session's CURRENT turn began. A `cast state --status dormant|done`
// stamp counts as a settle verdict only if written after this, so a declaration
// never outlives the turn that made it (see declaredSettleVerdict). Empty after
// a daemon boot, where the boot time stands in: a stamp older than the daemon
// has an unknown turn and is NOT trusted — needs-input is the safe side.
//
// A turn starts when INPUT is delivered to the agent — a typed prompt, an
// injected message, or a harness wake (task notification), all of which land in
// the transcript as a user turn and move the mark via markTurnStarted. A status
// flip is only a fallback signal (statusFlipStartsTurn): activity hooks also
// fire for work the session generates itself — a workflow subagent's tool
// calls, a Stop-hook continuation — and a flip off a declared "dormant"/"done"
// used to spend the declaration seconds after it was made (jx71a1g,
// 2026-08-20: the agent declared dormant, a workflow subagent's hook flipped
// the status to working 2s later, and the next settle read the stamp as an
// older turn's and filed the parked session under needs-input).
const turnStartedAt = new Map<string, number>();

// Advance a session's turn-start mark, monotonic. Timestamps come from the
// transcript (the user turn's own clock), so a lagging sync can never spend a
// stamp that was written later in real time.
export function markTurnStarted(sessionId: string, ts: number): void {
  if (ts > (turnStartedAt.get(sessionId) ?? 0)) turnStartedAt.set(sessionId, ts);
}

// The newest turn-starting message in a synced batch: a user turn that is not a
// tool_result reply (those ride INSIDE a turn — a permissioned tool finishing,
// an AskUserQuestion answer). Meta/system entries never reach ParsedMessage.
export function latestTurnStartTs(
  messages: Array<{ role: string; timestamp: number; toolResults?: unknown[] }>,
): number | null {
  let latest: number | null = null;
  for (const m of messages) {
    if (m.role !== "user") continue;
    if (m.toolResults && m.toolResults.length > 0) continue;
    if (typeof m.timestamp === "number" && (latest === null || m.timestamp > latest)) latest = m.timestamp;
  }
  return latest;
}

// Whether a status transition is evidence of a NEW turn. Settled → active
// counts — except off a declared "dormant"/"done", where hook activity is
// routinely self-generated (a workflow subagent's tool calls, a Stop-hook
// continuation) and the genuine wake announces itself as a delivered user
// turn (markTurnStarted) anyway.
export function statusFlipStartsTurn(prevStatus: AgentStatus | undefined, status: AgentStatus): boolean {
  if (!ACTIVE_AGENT_STATUSES.has(status)) return false;
  if (prevStatus && ACTIVE_AGENT_STATUSES.has(prevStatus)) return false;
  if (prevStatus && DECLARED_VERDICT_STATUSES.has(prevStatus)) return false;
  return true;
}
const DAEMON_BOOTED_AT = Date.now();
const lastHeartbeatLogged = new Map<string, { status: string; ts: number; since: number }>();
const HEARTBEAT_LOG_THROTTLE_MS = 5 * 60 * 1000;

// AgentStatus is imported from @codecast/shared/contracts (the single source of
// truth). The old local union here was missing "starting", which would have made
