const closedSyntheticPrompts = new Map<string, number>();
// Exported for tests (daemon.synthetic-prompt-close.test.ts) — the closure
// lifecycle is otherwise only reachable through live tmux scrapes.
export const syntheticPromptTestSeam = { lastEmittedSyntheticPrompt, closedSyntheticPrompts };
const AGENT_STATUS_DIR = path.join(process.env.HOME || "", ".codecast", "agent-status");
// Where codecast-status.sh drops a pending AskUserQuestion's full tool_input, keyed by
// session id. The buffered turn isn't in the JSONL yet, so this sidecar is the only
// full-fidelity source for the question while it waits to be answered.
const ASK_INPUT_DIR = path.join(process.env.HOME || "", ".codecast", "ask-input");
const skillsSyncedConversations = new Set<string>();

// Post-compaction message recovery: CC sometimes goes idle after compacting instead of
// continuing to process the user's message. Track compaction events and recent injections
// so we can detect this pattern and re-inject the dropped message.
const recentCompactionTs = new Map<string, number>(); // sessionId -> when compaction was detected
const recentSessionInjections = new Map<string, { messageId: string; content: string; ts: number }>(); // conversationId -> last injection
const postCompactionRecoveryTimers = new Map<string, ReturnType<typeof setTimeout>>(); // sessionId -> pending recovery
const compactionRedeliveryBypass = new Set<string>(); // messageIds that should bypass injection dedup

// Message delivery dedup/in-flight tracking. Module-scoped so kill_session can clear entries
// for a conversation when its tmux pane is killed mid-delivery — otherwise the daemon's
// 60s dedup window would skip re-delivery of the message Convex just reset back to pending.
// Each entry stores the conversation_id so kill_session can find matching ids without
// maintaining a reverse index.
//
// `confirmed` = the "injected" status write reached Convex. Until then the row is still
// "pending" server-side, so the pending scanner sees the message on every pass and ONLY the
// local dedup entry stands between the agent and a duplicate. Confirmed entries expire on
// the short TTL (the 120s retry cron re-pending a stale "injected" row is the intended
// lost-injection recovery); unconfirmed entries must outlive any backend brownout, because
// during one BOTH the mark and the JSONL echo ack stall past the TTL (2026-07-13 storm:
// 'gogo' processed 7x, ct-38507). The hard cap is the last-resort redelivery deadline when
// confirmation never arrives.
const messagesInFlight = new Map<string, { ts: number; conversationId: string }>();
const injectedMessageTs = new Map<string, { ts: number; conversationId: string; confirmed: boolean }>();
const IN_FLIGHT_HARD_TTL_MS = 240_000; // > DELIVERY_TIMEOUT_MS (180s)
const INJECTION_DEDUP_TTL_MS = 60_000;
const UNCONFIRMED_INJECTION_DEDUP_MAX_MS = 30 * 60_000;

export function injectionDedupWindowMs(entry: { confirmed: boolean }): number {
  return entry.confirmed ? INJECTION_DEDUP_TTL_MS : UNCONFIRMED_INJECTION_DEDUP_MAX_MS;
}
// Per-conversation delivery lock: prevents multiple messages targeting the same tmux pane
// from being injected concurrently (which causes an interrupt storm where each injection
// Escapes the previous, none complete, and the retry cron resets them all to pending).
const conversationDeliveryActive = new Set<string>();

// A web message's whole point is the local tmux paste; that must never be blocked by a Convex
// round-trip. The "injected" status is only an intermediate UI signal — the durable ack is the
// content-matched promote-to-delivered in addMessages when the agent echoes the message to its
// JSONL. So mark injected best-effort with a hard timeout and swallow failures: an un-timed
// updateMessageStatus before the paste was wedging deliverMessage for the full 180s timeout
// under Convex load, so the send-keys never ran and the message never reached the agent.
const MARK_INJECTED_TIMEOUT_MS = 8_000;
// Backoff for re-attempting an unconfirmed mark. Total ~2.5min of persistence covers a
// transient stall; anything longer is a real brownout, where the unconfirmed dedup entry
// (not the mark) is what holds redelivery back.
const MARK_INJECTED_RETRY_DELAYS_MS: readonly number[] = [5_000, 15_000, 45_000, 90_000];
const markInjectedRetryActive = new Set<string>();

export function markInjectedBestEffort(
  syncService: Pick<SyncService, "updateMessageStatus">,
  messageId: string,
  timeoutMs: number = MARK_INJECTED_TIMEOUT_MS,
  opts?: { conversationId?: string; retryDelaysMs?: readonly number[] },
): Promise<void> {
  // Register the dedup entry BEFORE the first attempt: the paste follows within ms of this
  // call, so from here on a pending-scanner pass must treat the message as injected. The
  // delivery result handler restamps ts on success and deletes the entry on failure.
  if (opts?.conversationId) {
    const prior = injectedMessageTs.get(messageId);
    injectedMessageTs.set(messageId, {
      ts: Date.now(),
      conversationId: opts.conversationId,
      confirmed: prior?.confirmed ?? false,
    });
  }
  const attempt = (): Promise<boolean> => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    return Promise.race([
      syncService.updateMessageStatus({ messageId, status: "injected" }).then(() => true),
      new Promise<boolean>((_, reject) => {
        timer = setTimeout(() => reject(new Error("mark_injected_timeout")), timeoutMs);
      }),
    ]).catch(err => {
      logDelivery(`mark-injected best-effort skipped for msg=${messageId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
      return false;
    }).finally(() => { if (timer) clearTimeout(timer); });
  };
  const confirm = () => {
    const entry = injectedMessageTs.get(messageId);
    if (entry) entry.confirmed = true;
  };
  return attempt().then(ok => {
    if (ok) { confirm(); return; }
    // Retry detached until the write lands: while unconfirmed, the row stays "pending"
    // server-side and only the local dedup entry prevents redelivery — so persistence here
    // directly shortens the storm window (ct-38507). Abort when the dedup entry disappears:
    // a kill/crash clear deliberately re-pended the message for a new pane, and a late
    // "injected" write would strand it un-redelivered.
    if (!opts?.conversationId || markInjectedRetryActive.has(messageId)) return;
    markInjectedRetryActive.add(messageId);
    void (async () => {
      try {
        for (const delayMs of opts.retryDelaysMs ?? MARK_INJECTED_RETRY_DELAYS_MS) {
          await new Promise<void>(resolve => {
            const t = setTimeout(resolve, delayMs);
            (t as unknown as { unref?: () => void }).unref?.();
          });
          const entry = injectedMessageTs.get(messageId);
          if (!entry || entry.confirmed) return;
          if (await attempt()) {
            confirm();
            logDelivery(`mark-injected confirmed on retry for msg=${messageId.slice(0, 8)}`);
            return;
          }
        }
      } finally {
        markInjectedRetryActive.delete(messageId);
      }
    })();
  });
}

// DEC-01: the rows THIS process pasted into a live pane for a conversation —
// an injectedMessageTs entry whose delivery has resolved (not in-flight; failed
// deliveries delete their entry). This is what scopes the injected-ack: the
// server only terminalizes rows the daemon can vouch for, so a stranded
// injected row (paste never landed, or a previous daemon process died) is left
// for the heal cron to re-pend and re-deliver instead of being falsely marked
// delivered by an unrelated (or historical, resync-from-0) user-turn echo.
export function collectPastedInjectedIds(conversationId: string): string[] {
  const ids: string[] = [];
  for (const [id, entry] of injectedMessageTs) {
    if (entry.conversationId !== conversationId) continue;
    if (messagesInFlight.has(id)) continue;
    ids.push(id);
  }
  return ids;
}

export function clearMessageDeliveryStateForConversation(conversationId: string): { inFlight: number; dedup: number; preserved: number } {
  let inFlight = 0;
  let dedup = 0;
  let preserved = 0;
  for (const [id, entry] of messagesInFlight) {
    if (entry.conversationId === conversationId) {
      messagesInFlight.delete(id);
      inFlight++;
    }
  }
  for (const [id, entry] of injectedMessageTs) {
    if (entry.conversationId === conversationId) {
      // An injected-but-unconfirmed message survives the clear: its row is still "pending"
      // server-side (the mark never landed), so dropping the entry would hand the pending
      // scanner an immediate duplicate — the exact 2026-07-13 storm ([HEARTBEAT-HEALTH]
      // clears during the brownout re-sent already-injected messages, ct-38507). The entry
      // releases on confirmation (then the normal 120s-cron re-pend + expired TTL path
      // redelivers if the agent never echoed) or on the unconfirmed hard cap.
      if (!entry.confirmed) {
        preserved++;
        continue;
      }
      injectedMessageTs.delete(id);
      dedup++;
    }
  }
  conversationDeliveryActive.delete(conversationId);
  return { inFlight, dedup, preserved };
}

// Single source of truth for "this session/conversation just lost its tmux pane".
// Every kill path (user-triggered kill_session, auto-kill on dismissed-idle, crash
// reconstitution) must call this — otherwise the next pending message Convex re-fires
// hits the 60s injection-dedup branch ("injected Ns ago, updating status only") and
// never reaches the freshly-resumed tmux. Mirrored Convex state (injected→pending) is
// reset here too so the message becomes eligible for redelivery from the subscription.
async function clearConversationDeliveryAndResumeState(
  conversationId: string | undefined,
  sessionId: string | undefined,
  context: string,
): Promise<void> {
  if (sessionId) {
    resumeFatalReasons.delete(sessionId);
    sessionDeliveryFailures.delete(sessionId);
    repairAttempts.delete(sessionId);
  }
  if (!conversationId) return;
  conversationResumeFailures.delete(conversationId);
  repairAttempts.delete(conversationId);

  if (syncServiceRef) {
    syncServiceRef.resetInjectedMessages(conversationId).catch(logConvexFailure);
  }

  const cleared = clearMessageDeliveryStateForConversation(conversationId);
  if (cleared.inFlight || cleared.dedup || cleared.preserved) {
    log(`[${context}] Cleared delivery state for conversation ${conversationId.slice(0, 12)}: ${cleared.inFlight} in-flight, ${cleared.dedup} dedup, ${cleared.preserved} unconfirmed-injected preserved`);
  }
  recentSessionInjections.delete(conversationId);
}

export function mapCodexAppServerThreadStatusToAgentStatus(status: AppServerThreadStatus | null | undefined): AgentStatus | null {
  if (!status?.type) return null;
  switch (status.type) {
    case "idle":
      return "idle";
    case "active":
      return status.activeFlags?.includes("waitingOnApproval") || status.activeFlags?.includes("waitingOnUserInput")
        ? "permission_blocked"
        : "working";
    case "systemError":
      return "stopped";
    default:
      return null;
  }
}

/**
 * The `/` menu inventory: skills + commands, project over user on a name clash.
 *
 * Delegates to the capability scanner, which reads the same directories plus
 * everything else a machine has (plugins, MCP, codex, cursor). The bespoke
 * walker that lived here was the scanner's ancestor; `toInvocableList` was
 * verified byte-identical against it on a real machine before the repoint, and
 * keeping both meant every frontmatter quirk had to be fixed twice.
 */
export function readAvailableSkills(projectPath?: string): Array<{ name: string; description: string }> {
  return toInvocableList(readInventory(process.env.HOME || "", projectPath));
}

function syncSkillsForConversation(conversationId: string, projectPath: string | undefined, syncService: SyncService): void {
  if (skillsSyncedConversations.has(conversationId)) return;
  skillsSyncedConversations.add(conversationId);
  const allSkills = readAvailableSkills(projectPath);
  if (allSkills.length === 0) return;
  syncService.setAvailableSkills(conversationId, JSON.stringify(allSkills)).catch(logConvexFailure);
  if (projectPath) {
    const globalSkills = readAvailableSkills();
    const globalNames = new Set(globalSkills.map(s => s.name));
    const projectOnly = allSkills.filter(s => !globalNames.has(s.name));
    if (projectOnly.length > 0) {
      syncService.setAvailableSkills(undefined, JSON.stringify(projectOnly), projectPath).catch(logConvexFailure);
    }
  }
}

// Idle/needs-input notifications are NOT sent from here: the server owns them
// (notifications.checkNeedsInput, scheduled off the status write this makes),
// because "needs input" is a composite verdict — status + idle grace + queued
// messages + open polls — that only the server can evaluate, and doing it
// there covers every path (hook, watcher fallback, codex app-server) exactly
// when the web inbox's idle sound fires. The daemon still sends
// permission_request notifications where it detects the prompt (it holds the
// tool context the server lacks).
function sendAgentStatus(
  syncService: SyncService,
  conversationId: string,
  sessionId: string,
  status: AgentStatus,
  clientTs?: number,
  permissionMode?: PermissionMode,
): void {
  const prevStatus = lastSentAgentStatus.get(sessionId);
  const isTransition = prevStatus !== status;
  if (status === "working" && !permissionMode && !isTransition) {
    const last = lastWorkingStatusSent.get(sessionId) ?? 0;
    if (Date.now() - last < WORKING_STATUS_THROTTLE_MS) return;
  }
  if (status === "working") {
    lastWorkingStatusSent.set(sessionId, Date.now());
  }
  // Settled → active spends every settle verdict from before it — except off a
  // declared "dormant"/"done" (see statusFlipStartsTurn), where the flip may be
  // the session's own background machinery and the genuine wake moves the mark
  // as a delivered user turn instead. Only the transition counts, so the 10s
  // working re-sends inside a turn never move the mark.
  if (statusFlipStartsTurn(prevStatus, status)) {
    markTurnStarted(sessionId, Date.now());
  }
  lastSentAgentStatus.set(sessionId, status);
  // The open-task report a settle just computed rides along with its verdict;
  // any other status drops it (a turn start makes the parked picture moot).
  const openTasks = pendingOpenTaskReports.get(sessionId);
  pendingOpenTaskReports.delete(sessionId);
  const withTasks = openTasks !== undefined && SETTLE_STATUSES_WITH_TASKS.has(status);
  if (withTasks) {
    lastOpenTasksSentAt.set(sessionId, Date.now());
    lastOpenTasksSentJson.set(sessionId, JSON.stringify(openTasks));
  }
  syncService.updateSessionAgentStatus(conversationId, status, clientTs, permissionMode, withTasks ? openTasks : undefined).catch((err) => { log(`[sendAgentStatus] error: ${err?.message || err}`); });
}

// One-shot handoff from resolveTurnEndStatus / the reconciles to sendAgentStatus:
// the verified open tasks behind the verdict about to be sent.
const pendingOpenTaskReports = new Map<string, OpenTaskReport[]>();
const lastOpenTasksSentAt = new Map<string, number>();
const lastOpenTasksSentJson = new Map<string, string>();
// True when the report a settle just computed differs from the last one sent
// for this session — a settle whose STATUS is unchanged (idle → idle again,
// a re-declared "done") still has to publish a report that moved, or the
// server keeps drawing a watch that has since ended.
function pendingOpenTasksChanged(sessionId: string): boolean {
  const pending = pendingOpenTaskReports.get(sessionId);
  if (pending === undefined) return false;
  return JSON.stringify(pending) !== lastOpenTasksSentJson.get(sessionId);
}
const SETTLE_STATUSES_WITH_TASKS: ReadonlySet<string> = new Set(["idle", "waiting", "dormant", "done"]);
// A parked "waiting" re-publishes its (re-verified) tasks this often so the
// server's report stays fresh enough to vouch for the status past the
// quiet-time decay (OPEN_TASKS_FRESH_MS is 10 min; the reconciles run ~90s).
const OPEN_TASKS_REFRESH_MS = 4 * 60_000;
function openTasksRefreshDue(sessionId: string, now: number): boolean {
  return now - (lastOpenTasksSentAt.get(sessionId) ?? 0) >= OPEN_TASKS_REFRESH_MS;
}

// Log the status carried on a heartbeat. Throttled per-session to once every
// 5 minutes for same-status heartbeats; always logs on status change. The
// "stuck=<seconds>" field is the dwell time in the current status — if we see
// "status=working stuck=61234" in logs, that's the "session stuck in working"
// bug. If we see status transitions in the log but the server still shows
// stale status, the fault is in the transport, not the daemon's state tracking.
function logHeartbeatStatus(sessionId: string, status: AgentStatus | undefined): void {
  if (!status) return;
  const now = Date.now();
  const prev = lastHeartbeatLogged.get(sessionId);
  const since = prev && prev.status === status ? prev.since : now;
  if (prev && prev.status === status && now - prev.ts < HEARTBEAT_LOG_THROTTLE_MS) return;
  lastHeartbeatLogged.set(sessionId, { status, ts: now, since });
  const stuckSec = Math.round((now - since) / 1000);
  log(`[HEARTBEAT] session=${sessionId.slice(0, 8)} status=${status} stuck=${stuckSec}s`);
}

// --- HTTP Hook Server ---
// Provides a push endpoint for agent status events at localhost:{port}/hook/status.
// The hook script (codecast-status.sh) sends events here via curl for instant delivery.
// The file-based chokidar watcher on ~/.codecast/agent-status/ remains as a fallback
// when the HTTP server is unreachable (e.g. daemon restart, port contention).
//
// Permission flow via HTTP: when status=permission_blocked arrives, handleStatusData
// processes it identically to the file path. The filePath parameter is only used for
// unlinkSync on "stopped" events; findTranscriptForSession uses sessionId to locate
// JSONL files independently, so permission handling works without a filePath.

let hookServer: http.Server | null = null;
let hookServerPort = 0;
// Per-boot secret for the integrated terminal. The web fetches it through the
// authenticated get_terminal_endpoint daemon command, then presents it on the
// loopback WebSocket — an unauthenticated socket that spawns shells would be
// remote code execution for any page the user visits.
const terminalToken = generateTerminalToken();
let terminalServerHandle: { close(): void } | null = null;
let vaultServerHandle: { close(): void } | null = null;
let watchServerHandle: { close(): void } | null = null;
let vaultMirror: VaultMirror | null = null;

function terminalServerOptions(): TerminalServerOptions {
  return { token: terminalToken, log };
}

// The vault routes ride the same loopback server and the same per-boot token;
// they only additionally need to know where the vault registry lives.
function vaultServerOptions(): VaultServerOptions {
  return { ...terminalServerOptions(), configDir: CONFIG_DIR };
}

// Remote mirror pusher. Opt-in per vault and off by default, so on a machine
// where nobody ran `cast vault mirror --on` this starts, finds nothing, and
// costs nothing. It subscribes to the SAME watch hub the browser uses rather
// than opening a second watcher on the same tree.
function startVaultMirror(): void {
  const siteUrl = getSiteUrl();
  const token = getAuthToken();
  if (!siteUrl || !token) return;

  vaultMirror = new VaultMirror({
    configDir: CONFIG_DIR,
    deviceId: deviceId(),
    transport: httpMirrorTransport(siteUrl, token),
    // Subscribing also keeps the vault's watcher warm, which is exactly right:
    // a mirrored vault is being watched on the user's behalf whether or not a
    // browser tab happens to be open on it.
    watch: (vault, onChange) => vaultWatchHub()?.subscribe(vault, onChange) ?? (() => {}),
    log,
  });
  vaultMirror.start();
}

function startHookServer(
  handleStatus: (sessionId: string, data: HookStatusData) => void,
): http.Server {
  const server = http.createServer((req, res) => {
    if (req.method === "GET" && req.url?.startsWith("/hook/status")) {
      const url = new URL(req.url, `http://localhost`);
      const sessionId = url.searchParams.get("session_id");
      const status = url.searchParams.get("status") as AgentStatus | null;
      const ts = url.searchParams.get("ts");
      const permissionMode = url.searchParams.get("permission_mode") as PermissionMode | undefined;
      const message = url.searchParams.get("message") || undefined;
      const transcriptPath = url.searchParams.get("transcript_path") || undefined;

      if (!sessionId || !status || !ts) {
        res.writeHead(400);
        res.end("missing params");
        return;
      }

      const data: HookStatusData = {
        status,
        ts: parseInt(ts, 10),
        ...(permissionMode && { permission_mode: permissionMode }),
        ...(message && { message }),
        ...(transcriptPath && { transcript_path: transcriptPath }),
      };

      handleStatus(sessionId, data);

      res.writeHead(200, { "Content-Type": "text/plain" });
      res.end("ok");
      return;
    }

    if (req.method === "GET" && req.url === "/health") {
      res.writeHead(200, { "Content-Type": "text/plain" });
      res.end("ok");
      return;
    }

    if (handleTerminalHttp(req, res, terminalServerOptions())) return;
    if (handleVaultHttp(req, res, vaultServerOptions())) return;
    if (handleBrowserFocusHttp(req, res, terminalServerOptions())) return;

    res.writeHead(404);
    res.end();
  });

  terminalServerHandle = attachTerminalServer(server, terminalServerOptions());
  vaultServerHandle = attachVaultServer(server, vaultServerOptions());
  // Browser watch rides the same server, token and origin rules — a viewer
  // that can reach the terminal can watch the managed browser's tabs.
  watchServerHandle = attachWatchServer(server, terminalServerOptions());
  startVaultMirror();

  // Reap idle panel terminals on boot and periodically (see terminalServer.ts).
  setTimeout(() => reapStaleTerminalSessions(log), 30_000).unref?.();
  const terminalReapTimer = setInterval(() => reapStaleTerminalSessions(log), 6 * 60 * 60 * 1000);
  terminalReapTimer.unref?.();
  // Agent windows left squeezed by a viewer the previous daemon took down
  // with it (see healSqueezedAgentWindows).
  setTimeout(() => { void healSqueezedAgentWindows(); }, 15_000).unref?.();
  const squeezeHealTimer = setInterval(() => { void healSqueezedAgentWindows(); }, 5 * 60 * 1000);
  squeezeHealTimer.unref?.();
  // Bounce unprovoked raises by agent-driven Chromes (see focusSentinel.ts).
  void startFocusSentinel(log).then((t) => t?.unref?.());

  server.listen(0, "127.0.0.1", () => {
    const addr = server.address();
    if (addr && typeof addr === "object") {
      hookServerPort = addr.port;
      try {
        fs.writeFileSync(HOOK_PORT_FILE, String(hookServerPort));
      } catch {}
      try {
        // Not unlinked on stop: unit D reads it back at boot. Readers detect a
        // stale file through the port in hook-port and the pid.
        fs.writeFileSync(
          LOOPBACK_IDENTITY_FILE,
          JSON.stringify({ port: hookServerPort, token: terminalToken, pid: process.pid }),
          { mode: 0o600 },
        );
        // writeFileSync applies mode only when it creates the file.
        fs.chmodSync(LOOPBACK_IDENTITY_FILE, 0o600);
      } catch {}
      log(`Hook server listening on 127.0.0.1:${hookServerPort}`);
    }
  });

  server.on("error", (err) => {
    log(`Hook server error: ${err.message}`);
  });

  return server;
}

function stopHookServer(): void {
  if (vaultMirror) {
    vaultMirror.stop();
    vaultMirror = null;
  }
  if (terminalServerHandle) {
    terminalServerHandle.close();
    terminalServerHandle = null;
  }
  if (vaultServerHandle) {
    vaultServerHandle.close();
    vaultServerHandle = null;
  }
  if (watchServerHandle) {
    watchServerHandle.close();
    watchServerHandle = null;
  }
  if (hookServer) {
    hookServer.close();
    hookServer = null;
  }
  try { fs.unlinkSync(HOOK_PORT_FILE); } catch {}
}

function truncateForNotification(text: string, maxLen = 200): string {
  let result = text
    .replace(/```[\s\S]*?```/g, "[code]")
    .replace(/\n+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (result.length > maxLen) {
    result = result.slice(0, maxLen) + "...";
  }
  return result;
}

// Find the tool_use the session is genuinely *blocked* on (has no matching
// tool_result yet). Returns null when the newest tool_use already completed —
// that tool is not pending, so reporting it would spawn a phantom Approve/Deny
// footer. This matters because Claude Code buffers the AskUserQuestion tool_use
// and doesn't flush it to the transcript until it's answered: while the session
// waits on a question, the newest tool_use physically present in the JSONL is
// the previous (already-resolved) Read/Bash. Without the completed-id guard that
// finished tool gets mis-reported as a pending permission.
export function extractPendingToolUseFromTail(tailContent: string): { tool_name: string; arguments_preview: string } | null {
  const lines = tailContent.trim().split("\n");
  const tail = lines.slice(-20);

  let lastToolUse: { name: string; input: any; id?: string } | null = null;
  const completedToolIds = new Set<string>();

  for (const line of tail) {
    try {
      const entry = JSON.parse(line);
      const msg = entry.message || entry;
      const blocks = Array.isArray(msg.content) ? msg.content : [];
      for (const block of blocks) {
        if (block.type === "tool_result") completedToolIds.add(block.tool_use_id);
        if (block.type === "tool_use") lastToolUse = { name: block.name, input: block.input, id: block.id };
      }
    } catch {}
  }

  if (!lastToolUse) return null;
  if (lastToolUse.id && completedToolIds.has(lastToolUse.id)) return null;

  let preview = "";
  if (lastToolUse.input) {
    if (typeof lastToolUse.input.command === "string") {
      preview = lastToolUse.input.command;
    } else if (typeof lastToolUse.input.file_path === "string") {
      preview = lastToolUse.input.file_path;
    } else if (typeof lastToolUse.input.pattern === "string") {
      preview = lastToolUse.input.pattern;
    } else {
      preview = JSON.stringify(lastToolUse.input).slice(0, 300);
    }
  }
  if (lastToolUse.input?.description) {
    preview = `${lastToolUse.input.description}\n${preview}`;
  }

  return { tool_name: lastToolUse.name, arguments_preview: preview.slice(0, 500) };
}

function extractPendingToolUseFromTranscript(transcriptPath: string): { tool_name: string; arguments_preview: string } | null {
  try {
    if (!transcriptPath || !fs.existsSync(transcriptPath)) return null;
    return extractPendingToolUseFromTail(readFileTail(transcriptPath, 32768));
  } catch {
    return null;
  }
}

const permissionRecordPending = new Set<string>();
const permissionJustResolved = new Set<string>();
// One-shot cleanup tracking: when a session is first observed in
// bypassPermissions mode (post-daemon-restart or post-upgrade), sweep any
// stale pending_permissions records left over from before the phantom-suppression
// fix shipped. After the first sweep per session we leave it alone.
const bypassPermissionsCleaned = new Set<string>();
// Sessions currently blocked on an AskUserQuestion. A PreToolUse AskUserQuestion hook
// is the one timely, reliable signal that the agent is waiting for input: Claude Code
// buffers the tool_use so the JSONL stays empty until answered, and a raw-iTerm
// (non-tmux) session has no pane to scrape. The follow-up Notification events that
// arrive during the wait are context-free (no tool name) and look identical to a
// phantom bypass auto-approve, so without this memory they downgrade the honest
// permission_blocked status back to "working" — leaving the web showing "working/stuck"
// for the entire wait. We hold the block until a non-blocked status arrives (the answer
// landed and the agent moved on). See classifyBypassBlock.
const awaitingAskUserQuestion = new Set<string>();

const syncStats = {
  messagesSynced: 0,
  conversationsCreated: 0,
  sessionsActive: new Set<string>(),
  lastReportTime: Date.now(),
  errors: 0,
  warnings: 0,
};

let lastWatcherEventTime = Date.now();

// Wired up once startDaemon has built config + caches + the watcher. The event-loop
// monitor (which starts before those exist) calls wakeRecoveryHandler on a detected
// wake; reconciliation calls pushUnsyncedFilesHandler after it rewinds positions.
// Both drive a real byte-pushing sweep that does NOT depend on the file watcher —
// the watcher's FSEvents stream can go silent across a sleep without erroring.
let wakeRecoveryHandler: (() => void) | null = null;
let pushUnsyncedFilesHandler: ((reason: string) => Promise<void>) | null = null;

const HEALTH_REPORT_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes

// Only actionable levels are worth uploading. debug/info (dominated by the
// [HEARTBEAT] firehose) bloated the server's daemon_logs table, so they stay
// local-only. The server also drops them on insert; this just avoids the upload.
function shouldUploadLog(level: LogLevel): boolean {
  return level === "warn" || level === "error";
}

function enqueueRemoteLog(entry: RemoteLog): void {
  if (!shouldUploadLog(entry.level)) return;
  remoteLogQueue.push(entry);
  if (remoteLogQueue.length > MAX_LOG_QUEUE_SIZE) {
    remoteLogQueue.shift();
  }
}

// The most recent log line, kept so a freeze report can name what the loop was
// doing when it stopped — the last thing that logged is the best available
// witness for what blocked it (see startLoopFreezeProbe).
let lastLogLine = "";

// Debug-level lines (per-session resource dumps, per-pane "no prompt found"
// probes) are the bulk of daemon.log by bytes — ~70% on 2026-08-15 — and only
// useful when chasing one specific session. They are dropped unless enabled.
const DEBUG_LOG_ENABLED = process.env.CODECAST_DAEMON_DEBUG === "1";

// info/debug lines are buffered and flushed on a short timer; warn/error still
// write synchronously. At ~4k lines/hour, one appendFileSync per line was a
// steady stream of blocking disk writes on the main thread. The buffer is also
// flushed synchronously on process "exit" (which process.exit() fires) so the
// last lines before a crash or self-restart are never lost.
const LOG_FILE_FLUSH_INTERVAL_MS = 250;
let logBuffer: string[] = [];
let logFlushTimer: NodeJS.Timeout | null = null;
function flushLogBuffer(): void {
  if (logBuffer.length === 0) return;
  const chunk = logBuffer.join("");
  logBuffer = [];
  try { fs.appendFileSync(LOG_FILE, chunk); } catch {}
}
function scheduleLogFlush(): void {
  if (logFlushTimer) return;
  logFlushTimer = setTimeout(() => { logFlushTimer = null; flushLogBuffer(); }, LOG_FILE_FLUSH_INTERVAL_MS);
  logFlushTimer.unref?.();
}

function log(message: string, level: LogLevel = "info", metadata?: RemoteLog["metadata"]): void {
  if (level === "debug" && !DEBUG_LOG_ENABLED) return;
  const timestamp = new Date().toISOString();
  const levelTag = level === "info" ? "" : `[${level.toUpperCase()}] `;
  const line = `[${timestamp}] ${levelTag}${message}\n`;
  if (level === "warn" || level === "error") {
    // Keep ordering: anything buffered goes out first, then this line.
    flushLogBuffer();
    fs.appendFileSync(LOG_FILE, line);
  } else {
    logBuffer.push(line);
    scheduleLogFlush();
  }
  lastLogLine = `${timestamp} ${message.slice(0, 160)}`;

  enqueueRemoteLog({
    level,
    message: message.slice(0, 2000),
    metadata,
    timestamp: Date.now(),
  });
}

function logError(message: string, error?: Error, sessionId?: string): void {
  const errMsg = error ? `${message}: ${error.message}` : message;
  log(errMsg, "error", {
    session_id: sessionId,
    error_code: error?.name,
    stack: error?.stack?.slice(0, 1000),
  });
}

function logWarn(message: string, sessionId?: string): void {
  log(message, "warn", { session_id: sessionId });
}

function logDelivery(message: string, metadata?: RemoteLog["metadata"]): void {
  log(message, "info", metadata);
  enqueueRemoteLog({
    level: "info",
    message: `[DELIVERY] ${message.slice(0, 2000)}`,
    metadata,
    timestamp: Date.now(),
  });
}

// Standard catch handler for fire-and-forget Convex calls. Previously these used
// `.catch(() => {})` and silently swallowed errors, which hid Convex outages,
// auth-token expiry, and stuck mutations. Logs at info level to keep noise reasonable
// while still leaving a breadcrumb when the sync layer fails.
function logConvexFailure(err: unknown): void {
  const msg = err instanceof Error ? err.message : String(err);
  log(`[convex-bg] mutation failed: ${msg}`);
}

// The one write that repoints conversations.session_id at the live session
// uuid. It historically fired once, fire-and-forget, at link/resume time — and
// a lost call permanently stranded the conversation on its spawn-time stub id:
// every session-bound `cast` write from the agent then failed "Conversation
// not found" while message sync (keyed by conversation _id) stayed healthy, so
// nothing surfaced the break (union-mobile fleet, 2026-08-29). Ride the durable
// retry queue instead: never rejects, so callers may await it or drop it.
async function pushSessionIdBinding(conversationId: string, sessionId: string, projectPath?: string, gitRoot?: string): Promise<void> {
  try {
    await syncServiceRef?.updateSessionId(conversationId, sessionId, projectPath, gitRoot);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log(`updateSessionId failed for ${conversationId.slice(0, 12)} <- ${sessionId.slice(0, 8)}: ${msg}; queuing for retry`, "warn");
    retryQueueRef?.add("updateSessionId", { conversationId, sessionId, projectPath, gitRoot }, msg);
  }
}

function logLifecycle(event: string, details?: string): void {
  const message = details ? `[LIFECYCLE] ${event}: ${details}` : `[LIFECYCLE] ${event}`;
  log(message, "info");
  enqueueRemoteLog({
    level: "info",
    message,
    metadata: { error_code: event },
    timestamp: Date.now(),
  });
}

// On macOS, RSS counts clean file-backed and already-freed-but-still-mapped
// pages (bun's allocator returns memory as clean pages that stay in RSS), so it
// overstates real use badly — 1.34GB RSS was 119MB phys_footprint on 2026-08-15.
// The kernel's phys_footprint is the honest number but isn't reachable from JS;
// `footprint` is (slow, ~seconds), so we only shell out to it when RSS crosses
// the warn threshold — turning a would-be false alarm into a real measurement.
export function parseFootprintMb(out: string): number | null {
  const m = out.match(/phys_footprint:\s+([\d.]+)\s*([KMG])B/);
  if (!m) return null;
  const v = parseFloat(m[1]);
  return Math.round(m[2] === "G" ? v * 1024 : m[2] === "K" ? v / 1024 : v);
}
async function readPhysFootprintMb(): Promise<number | null> {
  if (process.platform !== "darwin") return null;
  try {
    const { stdout } = await _execFileAsync("footprint", [String(process.pid)], { timeout: 15_000 });
    return parseFootprintMb(stdout);
  } catch {
    return null;
  }
}

// Async: the fd count and its lsof fallback run on the 5 minute health tick,
// and a sync lsof under load held the loop for its whole 5s budget. The two
// primitives are injectable so the lsof branch (never taken where /dev/fd
// exists) is testable.
export type SystemMetricsIO = {
  readdir: (dir: string) => Promise<string[]>;
  execFile: (cmd: string, args: string[], opts: { timeout: number; maxBuffer: number }) => Promise<{ stdout: string }>;
};
const defaultSystemMetricsIO: SystemMetricsIO = {
  readdir: (dir) => fs.promises.readdir(dir),
  execFile: (cmd, args, opts) => _execFileAsync(cmd, args, opts),
};
export async function getSystemMetrics(io: SystemMetricsIO = defaultSystemMetricsIO): Promise<{ rss_mb: number; heap_mb: number; heap_total_mb: number; ext_mb: number; uptime_min: number; fds: number; cpu_user_ms: number; cpu_system_ms: number }> {
  const mem = process.memoryUsage();
  const cpu = process.cpuUsage();
  let fds = 0;
  try {
    fds = (await io.readdir(`/dev/fd`)).length;
  } catch {
    try {
      // The full listing, not a count: node's default 1MB buffer overflows
      // near 10k open files, which is the case the fd warning exists for.
      const { stdout } = await io.execFile("lsof", ["-p", String(process.pid)], { timeout: 5000, maxBuffer: 16 * 1024 * 1024 });
      fds = stdout.split("\n").filter(Boolean).length;
    } catch {}
  }
  return {
    rss_mb: Math.round(mem.rss / 1024 / 1024),
    heap_mb: Math.round(mem.heapUsed / 1024 / 1024),
    heap_total_mb: Math.round(mem.heapTotal / 1024 / 1024),
    // Buffers/ArrayBuffers/other off-heap allocations bun tracks — where a
    // whole-file read shows up. Small heap + big ext = transient file churn.
    ext_mb: Math.round((mem.external + mem.arrayBuffers) / 1024 / 1024),
    uptime_min: Math.round(process.uptime() / 60),
    fds,
    cpu_user_ms: Math.round(cpu.user / 1000),
    cpu_system_ms: Math.round(cpu.system / 1000),
  };
}

const FD_WARN_THRESHOLD = 5000;
const RSS_WARN_THRESHOLD_MB = 1500;

async function logHealthSummary(): Promise<void> {
  const now = Date.now();
  const periodMinutes = Math.round((now - syncStats.lastReportTime) / 60000);
  const sessionsCount = syncStats.sessionsActive.size;
  const metrics = await getSystemMetrics();

  const metricStr = `rss=${metrics.rss_mb}MB heap=${metrics.heap_mb}/${metrics.heap_total_mb}MB ext=${metrics.ext_mb}MB fds=${metrics.fds} cpu=${metrics.cpu_user_ms}+${metrics.cpu_system_ms}ms uptime=${metrics.uptime_min}min`;
  const syncStr = `${syncStats.messagesSynced}msgs ${syncStats.conversationsCreated}convos ${sessionsCount}sessions ${syncStats.errors}errs`;
  const summary = `Health: ${syncStr} | ${metricStr} (${periodMinutes}min)`;

  log(summary, "info");

  enqueueRemoteLog({
    level: "info",
    message: summary,
    metadata: {
      error_code: syncStats.errors > 0 ? `${syncStats.errors} errors` : undefined,
    },
    timestamp: now,
  });

  if (metrics.fds > FD_WARN_THRESHOLD) {
    const msg = `HIGH FD COUNT: ${metrics.fds} open file descriptors (threshold: ${FD_WARN_THRESHOLD})`;
    logWarn(msg);
    sendLogImmediate("warn", msg, { error_code: "high_fd_count" });
  }

  if (metrics.rss_mb > RSS_WARN_THRESHOLD_MB) {
    // RSS over the line is a prompt to MEASURE, not a verdict (see
    // readPhysFootprintMb). Only warn on the real footprint; if we can't
    // read it, fall back to the RSS warning so the signal is never silently lost.
    const footprintMb = await readPhysFootprintMb();
    if (footprintMb === null) {
      const msg = `HIGH MEMORY: ${metrics.rss_mb}MB RSS (threshold: ${RSS_WARN_THRESHOLD_MB}MB; footprint unavailable)`;
      logWarn(msg);
      sendLogImmediate("warn", msg, { error_code: "high_memory" });
    } else if (footprintMb > RSS_WARN_THRESHOLD_MB) {
      const msg = `HIGH MEMORY: ${footprintMb}MB phys_footprint (rss=${metrics.rss_mb}MB, threshold: ${RSS_WARN_THRESHOLD_MB}MB)`;
      logWarn(msg);
      sendLogImmediate("warn", msg, { error_code: "high_memory" });
    } else {
      log(`Memory: rss=${metrics.rss_mb}MB over threshold but phys_footprint=${footprintMb}MB — clean/reclaimable pages, not real pressure`);
    }
  }

  syncStats.messagesSynced = 0;
  syncStats.conversationsCreated = 0;
  syncStats.sessionsActive.clear();
  syncStats.errors = 0;
  syncStats.warnings = 0;
  syncStats.lastReportTime = now;
}

function isAutostartEnabled(): boolean {
  const home = process.env.HOME || "";
  if (platform === "darwin") {
    const plistPath = path.join(home, "Library", "LaunchAgents", "sh.codecast.daemon.plist");
    return fs.existsSync(plistPath);
  } else if (platform === "linux") {
    const servicePath = path.join(home, ".config", "systemd", "user", "codecast.service");
    return fs.existsSync(servicePath);
  }
  return false;
}

const processedPollCommandIds = new Set<string>();


async function pollDaemonCommands(): Promise<void> {
  const config = readConfig();
  if (!config?.auth_token || !config?.convex_url) return;
  try {
    const siteUrl = config.convex_url.replace(".cloud", ".site");
    const response = await fetch(`${siteUrl}/cli/heartbeat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        api_token: config.auth_token,
        version: daemonVersion || "unknown",
        platform,
        pid: process.pid,
        autostart_enabled: isAutostartEnabled(),
        has_tmux: hasTmux(),
        // Identify the device on this path too: it hits the same heartbeat
        // mutation as sendHeartbeat, and a device-less beat is a legacy writer
        // there (per-machine user fields, command visibility). Label rides
        // along (cached, no I/O) so this beat never reads as label-less.
        device_id: deviceId(),
        device_label: deviceLabel(),
        ...syncHealthFields(),
      }),
    });
    if (!response.ok) {
      backendOutage.markFailure();
      return;
    }
    const downFor = backendOutage.markSuccess();
    if (downFor > 0) {
      if (downFor > STUCK_CONNECTION_THRESHOLD_MS) {
        const state = readDaemonState();
        const lastHeal = state.lastSelfHealRestart || 0;
        if (Date.now() - lastHeal > SELF_HEAL_COOLDOWN_MS) {
          const downSec = Math.round(downFor / 1000);
          logLifecycle("self_heal_restart", `Backend recovered after ${downSec}s down, restarting`);
          sendLogImmediate("warn", `[LIFECYCLE] self_heal_restart: backend recovered after ${downSec}s down`, { error_code: "self_heal_restart" });
          saveDaemonState({ lastSelfHealRestart: Date.now() });
          flushRemoteLogs()
            .then(() => restartDaemonProcess("backend recovered after outage"))
            .catch(() => restartDaemonProcess("backend recovered after outage"));
          return;
        }
      }
    }
    const data = await response.json();
    if (data.commands && data.commands.length > 0) {
      log(`[POLL] Received ${data.commands.length} command(s): ${data.commands.map((c: any) => c.command).join(", ")}`);
      for (const cmd of data.commands) {
        if (processedPollCommandIds.has(cmd.id)) continue;
        processedPollCommandIds.add(cmd.id);
        await executeRemoteCommand(cmd.id, cmd.command, config, cmd.args);
      }
    }
  } catch {
    backendOutage.markFailure();
  }
}

// Enumerate first-level children of the conventional project parent dirs
// ("src", "dev", "projects", "repos", "code"). The server accepts both these
// roots and projects nested below them, so monorepo-style layouts such as
// ~/dev/union/union-mobile remain available in the recent-project picker.
// Bounded scan: only directories that actually exist on this host.
function computeLocalProjectRootsNow(): string[] {
  const roots = new Set<string>([...enumerateProjectRoots(), ...enumerateAgentHomeDirs()]);
  // Also include any project_paths we've actually started a session in — covers
  // non-conventional locations the user has used recently.
  for (const info of startedSessionTmux.values()) {
    if (info.projectPath) {
      try {
        if (fs.statSync(info.projectPath).isDirectory()) roots.add(info.projectPath);
      } catch {}
    }
  }
  return Array.from(roots).slice(0, MAX_PROJECT_ROOTS);
}
// The heartbeat asks every 30s. A readdir of six parents plus a stat per
// started session each beat was one of the sync hogs on the loop; a new
// project under a conventional parent bumps that parent's mtime, so a dozen
// directory stats answer the common beat, and the TTL covers a path that only
// a started session names.
const localProjectRootsCache = createMtimeGatedCache<string[]>(
  () => {
    const home = process.env.HOME || "";
    return [...PROJECT_PARENT_DIRS, ...AGENT_HOME_DIRS].map((d) => path.join(home, d));
  },
  computeLocalProjectRootsNow,
  { ttlMs: 5 * 60_000 },
);
export function computeLocalProjectRoots(): string[] {
  return localProjectRootsCache.get();
}
export function invalidateLocalProjectRoots(): void {
  localProjectRootsCache.invalidate();
}

// Sync-backlog fields published on every heartbeat so the web can show a
// "sync stalled" warning while the daemon is still alive (fresh heartbeat but
// data isn't flowing). Reads the live retry queue, not the persisted state
// snapshot (which only refreshes inside the retry executor).
function syncHealthFields(): {
  pending_sync_count: number;
  oldest_pending_ms: number;
  pending_sync_messages: number;
  pending_sync_conversations: number;
  daemon_started_at: number;
  loop_freeze_ms: number;
} {
  const health = retryQueueRef?.getHealth();
  return {
    pending_sync_count: health?.pending ?? 0,
    oldest_pending_ms: health?.oldestPendingMs ?? 0,
    pending_sync_messages: health?.messages ?? 0,
    pending_sync_conversations: health?.conversations ?? 0,
    // Boot time and recent loop-freeze budget: the web reads these as
    // "restarted, catching up" and "under load" (see LoopFreezeLedger).
    daemon_started_at: daemonStartedAt,
    loop_freeze_ms: loopFreezes.recentMs(),
  };
}

// Remote credential refresh: the remote Mac's claude runs on a COPY of this
// machine's credential and cannot /login itself. The copy is pushed at move
// time, but between moves it expires and every session on the remote starts
// answering 401. This machine's credential stays fresh (CC self-refreshes
// locally), so push it whenever a remote host is registered: a fast tick that
// pushes only when the blob CHANGED (a /login, an account switch, CC's own
// self-refresh — propagates within ~a minute), plus a slow forced push as the
// safety net against remote-side drift the hash can't see.
// One-way by design: the laptop is canonical — the remote must never refresh
// itself, or its rotated refresh token would invalidate the local one.
// copyCredentialToRemoteAsync only ships a blob with a LIVE access token, so a
// logged-out stub or expired credential skips instead of replicating the
// outage to the remote (which cannot /login itself); the fast tick then
// delivers the healthy blob within a minute of the local login recovering.
const REMOTE_CRED_REFRESH_INTERVAL_MS = 30 * 60 * 1000;
const REMOTE_CRED_CHANGE_TICK_MS = 60 * 1000;
let remoteCredPushInFlight = false;
let lastPushedCredHash: string | null = null;
let lastCredSkipReason: string | null = null;

/**
 * Every transfer host worth pushing to right now: the Scaleway Macs plus any
 * cloud (AWS) box that is actually AWAKE. Reachability is a TCP probe of port
 * 22, never an AWS call and never a wake — a box that put itself to sleep must
 * not be booted (and billed) just to receive a credential it will re-receive
 * at the next move anyway (refreshRemoteCredential runs at move time, and
 * provisioning pushes one too).
 */
async function reachableTransferHosts(): Promise<RemoteHost[]> {
  const candidates = [...listScalewayHosts(), ...listCloudRemoteHosts()];
  if (!candidates.length) return [];
  const probes = await Promise.all(candidates.map((h) => sshReachable(h)));
  return candidates.filter((_, i) => probes[i]);
}

async function pushCredentialToRemoteHosts(
  reason: string,
  opts: { onlyIfChanged?: boolean } = {},
): Promise<void> {
  if (isRemoteDevice() || remoteCredPushInFlight) return;
  remoteCredPushInFlight = true;
  try {
    if (opts.onlyIfChanged) {
      const gate = await readPushableCredentialAsync();
      const hash = gate.cred ? createHash("sha256").update(gate.cred).digest("hex") : null;
      if (hash !== null && hash === lastPushedCredHash) return; // in step — the common case
    }
    const hosts = await reachableTransferHosts();
    if (!hosts.length) return;
    let res: Awaited<ReturnType<typeof copyCredentialToRemoteAsync>> | null = null;
    for (const host of hosts) {
      res = await copyCredentialToRemoteAsync(host);
      if (!res.pushed) break; // an unpushable credential is unpushable everywhere
      log(`[REMOTE-AUTH] pushed fresh credential to ${host.user}@${host.address} (${reason})`);
    }
    if (!res) return;
    if (!res.pushed) {
      // Log a skip once per distinct reason, not every 60s tick: the state is
      // what matters ("local login is down"), not the polling.
      if (res.reason !== lastCredSkipReason) {
        log(`[REMOTE-AUTH] push skipped (${reason}): ${res.reason}`);
        lastCredSkipReason = res.reason ?? "unknown";
      }
      return;
    }
    lastCredSkipReason = null;
    const hash = createHash("sha256").update(res.cred!).digest("hex");
    const changed = hash !== lastPushedCredHash;
    lastPushedCredHash = hash;
    // A changed credential is the recovery event for remote sessions parked on
    // "Login expired" (CC re-reads the store on its next turn) — nudge them.
    if (changed && syncServiceRef) {
      syncServiceRef
        .reviveRemoteAuthBlocked()
        .then((n) => { if (n > 0) log(`[REMOTE-AUTH] queued continue for ${n} auth-blocked remote session(s)`); })
        .catch((err) => log(`[REMOTE-AUTH] remote auth revive failed: ${err instanceof Error ? err.message : String(err)}`));
    }
  } catch (err) {
    log(`[REMOTE-AUTH] credential push failed (${reason}): ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    remoteCredPushInFlight = false;
  }
}

// Provider-key store fan-out (pl-207): the same one-way primary→remote push as the
// CC credential. The primary is canonical; a remote never originates keys. Deduped
// by content hash so an unchanged store is a no-op. An absent local store pushes
// `null`, which removes the remote file — clearing a key here clears it there.
let remoteKeysPushInFlight = false;
let lastPushedKeysHash: string | null = null;

function readLocalProviderKeysBlob(): string | null {
  try { return fs.readFileSync(providerKeyStorePath(CONFIG_DIR), "utf-8"); } catch { return null; }
}

async function pushProviderKeysToRemoteHosts(reason: string, opts: { onlyIfChanged?: boolean } = {}): Promise<void> {
  if (isRemoteDevice() || remoteKeysPushInFlight) return;
  remoteKeysPushInFlight = true;
  try {
    const blob = readLocalProviderKeysBlob();
    const hash = blob === null ? "∅" : createHash("sha256").update(blob).digest("hex");
    if (opts.onlyIfChanged && hash === lastPushedKeysHash) return; // in step — the common case
    const hosts = await reachableTransferHosts();
    if (!hosts.length) return;
    for (const host of hosts) {
      await copyProviderKeysToRemoteAsync(host, blob);
    }
    const changed = hash !== lastPushedKeysHash;
    lastPushedKeysHash = hash;
    if (changed) {
      log(`[REMOTE-KEYS] pushed provider keys to ${hosts.map((h) => `${h.user}@${h.address}`).join(", ")} (${reason}${blob === null ? ", cleared" : ""})`);
    }
  } catch (err) {
    log(`[REMOTE-KEYS] provider-key push failed (${reason}): ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    remoteKeysPushInFlight = false;
  }
}

// ---------------------------------------------------------------------------
// Setup-token mint flow (switch_account {mint}): per-session accounts pin a
// session to a profile's `claude setup-token` (see accountSourcePrefix), so
// every saved login needs one. The CLI's own `setup-token` runs the OAuth
// flow and prints the token; this block (1) runs it in a utility pane with
// $BROWSER pointed at a hook that RECORDS the sign-in URL instead of opening
// it, (2) drives the one-button approval in the agent browser — a clone of the
// human's Chrome, so signed into the same claude.ai account — falling back to
// the default browser for a human click, (3) reads the token off the pane,
// (4) proves it belongs to the machine's login by comparing rate-limit
// fingerprints with the keychain credential (the browser may be signed into
// another account; the token itself can't say whose it is), (5) stores it
// under that profile. Outcome goes back through reportMintFlow, the web's
// reactive state channel — the same shape as the login flow below.
// ---------------------------------------------------------------------------

const MINT_FLOW_TMUX = "cc-mint-flow";
const MINT_FLOW_TIMEOUT_MS = 5 * 60 * 1000;
const MINT_FLOW_POLL_MS = 2000;
// Re-mint this close to the one-year expiry: CC never warns, and a dead token
// silently drops every pinned session onto the keychain login.
const MINT_RENEW_BEFORE_MS = 7 * 24 * 60 * 60 * 1000;
let mintFlowActive = false;
let mintFlowGeneration = 0;
// The heartbeat reads the web-set device flag back; off until the first beat.
let sessionTokensEnabled = false;
// One auto-mint attempt per account per daemon lifetime — a rejected mint
// (wrong browser account, closed tab) is not nagged; the web's "try again"
// relaunches explicitly. Attempts are also stamped on disk so a daemon
// restart (deploys, watchdog) doesn't re-open the consent tab within hours.
const autoMintDecidedAccounts = new Set<string>();
const AUTO_MINT_RETRY_MS = 6 * 60 * 60 * 1000;

function autoMintAttemptsPath(): string {
  return path.join(CONFIG_DIR, "cc-mint-attempts.json");
}

function readAutoMintAttempts(): Record<string, number> {
  try {
    const parsed = JSON.parse(fs.readFileSync(autoMintAttemptsPath(), "utf-8"));
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

function stampAutoMintAttempt(key: string): void {
  try {
    const attempts = readAutoMintAttempts();
    attempts[key] = Date.now();
    fs.writeFileSync(autoMintAttemptsPath(), JSON.stringify(attempts), { mode: 0o600 });
  } catch {}
}

function mintUrlPath(): string {
  return path.join(CONFIG_DIR, "mint-flow.url");
}

/** The $BROWSER hook: CC hands it the OAuth URL as its one argument. */
function writeMintBrowserHook(): string {
  const hook = path.join(CONFIG_DIR, "mint-browser-hook.sh");
  fs.writeFileSync(hook, `#!/bin/sh\nprintf '%s\\n' "$1" > ${shellEscapeForSh(mintUrlPath())}\n`, { mode: 0o700 });
  return hook;
}

// Same PATH rule as the login flow (the pane inherits launchd's PATH); the
// trailing sleep keeps a dying CLI's last words capturable.
export function buildMintFlowCommand(hookPath: string): string {
  return `PATH=${shellEscapeForSh(agentSpawnPath())} BROWSER=${shellEscapeForSh(hookPath)} claude setup-token; sleep 4`;
}

async function approveMintInBrowser(url: string): Promise<"agent" | "opened"> {
  const res = await runCastCommand(["browser", "do", `open ${url}`, "find Authorize", "click"], { timeoutMs: 60 * 1000 });
  if (res.code === 0) return "agent";
  const why = (res.stderr.trim() || res.stdout.trim()).split("\n").pop()?.slice(0, 160) ?? `exit ${res.code}`;
  log(`[MINT-FLOW] agent-browser approval failed (${why}) — opening the default browser for a manual approve`);
  spawn(process.platform === "darwin" ? "open" : "xdg-open", [url], { stdio: "ignore", detached: true }).unref();
  return "opened";
}

async function startMintFlow(profile: string, force = false): Promise<string> {
  if (isRemoteDevice()) {
    throw new Error("Remote devices run a pushed copy of the primary's credential — mint on the primary machine");
  }
  if (mintFlowActive && !force) return "mint_flow_already_running";
  const gen = ++mintFlowGeneration;
  mintFlowActive = true;
  try {
    // Only the ACTIVE login can be minted for: that is the account the
    // browser is signed into, and the one we can fingerprint-check against.
    const active = activeAccountSummary();
    const covering = listProfiles().find((p) => p.active);
    if (!covering) throw new Error("the machine's current login isn't saved as a profile yet");
    if (covering.name !== profile) {
      throw new Error(
        `"${profile}" is not the machine's current login (${active?.email ?? "unknown"}, saved as "${covering.name}") — switch to it first`,
      );
    }
    fs.rmSync(mintUrlPath(), { force: true });
    const hook = writeMintBrowserHook();
    await killTmuxSessionAndTree(MINT_FLOW_TMUX).catch(() => {});
    tmuxExecSync(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", MINT_FLOW_TMUX, buildMintFlowCommand(hook)], { timeout: 5000 });
    log(`[MINT-FLOW] started setup-token mint for "${profile}"${active?.email ? ` (${active.email})` : ""}${force ? " [forced relaunch]" : ""}`);
    void watchMintFlow(profile, active?.email, gen)
      .catch((err) => log(`[MINT-FLOW] watcher failed: ${err instanceof Error ? err.message : String(err)}`))
      .finally(() => { if (gen === mintFlowGeneration) mintFlowActive = false; });
    return "mint_flow_started";
  } catch (err) {
    if (gen === mintFlowGeneration) mintFlowActive = false;
    throw err;
  }
}

async function watchMintFlow(profile: string, email: string | undefined, gen: number): Promise<void> {
  const deadline = Date.now() + MINT_FLOW_TIMEOUT_MS;
  let lastPane = "";
  let urlHandled = false;

  // `storedFor` is the profile the token actually landed under — the active
  // login's profile in the common case, another saved profile when the browser
  // was signed into that account instead (see attributeFingerprint).
  const finish = async (status: "confirmed" | "rejected", rawReason?: string, storedFor?: string): Promise<void> => {
    // The reason renders inline on the Settings page — keep it one line.
    const reason = rawReason?.replace(/\s+/g, " ").trim().slice(0, 200);
    await killTmuxSessionAndTree(MINT_FLOW_TMUX).catch(() => {});
    fs.rmSync(mintUrlPath(), { force: true });
    const owner = storedFor ?? profile;
    log(`[MINT-FLOW] ${status}${reason ? `: ${reason}` : ` — token stored for "${owner}"`}`);
    // The token's metadata reaches the web on the inventory beat; push it now.
    if (status === "confirmed") sendHeartbeat().catch(() => {});
    const ownerEmail = owner === profile ? email : listProfiles().find((p) => p.name === owner)?.email;
    await syncServiceRef?.reportMintFlow(status, owner, ownerEmail, reason).catch((err) => {
      log(`[MINT-FLOW] outcome report failed: ${err instanceof Error ? err.message : String(err)}`);
    });
  };

  const storeMinted = async (token: string): Promise<void> => {
    let owner: string | null = null;
    try {
      // Keep the comparison credential usable: an idle login may have lapsed.
      if (((await activeCredentialExpiresAt()) ?? 0) <= Date.now() + 60_000) {
        await refreshActiveCredential().catch(() => null);
      }
      const activeToken = readActiveOauth()?.accessToken;
      const [mineRes, minted] = await Promise.all([
        typeof activeToken === "string" && activeToken
          ? fetchRateLimitFingerprint(activeToken).then((fp) => ({ fp }), (err) => ({ err }))
          : Promise.resolve({ err: new Error("no usable keychain login") }),
        fetchRateLimitFingerprint(token),
      ]);
      if ("fp" in mineRes && sameAccountFingerprint(mineRes.fp, minted)) {
        owner = profile;
      } else {
        // Not the machine's login — the browser was signed into another
        // account. If it is one we have saved, the token is still worth
        // keeping: file it there.
        owner = attributeFingerprintToProfile(minted);
        if (owner === profile) owner = null; // the direct comparison already said no
      }
      if (!owner) {
        return finish(
          "rejected",
          `the browser is signed into a Claude account that matches no saved profile (this machine's login is ${email ?? "unknown"}) — sign into a saved account at claude.ai and try again`,
        );
      }
      writeAccountToken(owner, token);
    } catch (err) {
      return finish("rejected", `could not verify or store the token: ${err instanceof Error ? err.message : String(err)}`);
    }
    return finish("confirmed", undefined, owner);
  };

  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, MINT_FLOW_POLL_MS));
    if (gen !== mintFlowGeneration) return;
    if (!urlHandled) {
      let url = "";
      try { url = fs.readFileSync(mintUrlPath(), "utf-8").trim(); } catch {}
      if (url.startsWith("http")) {
        urlHandled = true;
        void approveMintInBrowser(url)
          .then((how) => log(`[MINT-FLOW] sign-in URL handed to ${how === "agent" ? "the agent browser (auto-approved)" : "the default browser"}`))
          .catch((err) => log(`[MINT-FLOW] browser hand-off failed: ${err instanceof Error ? err.message : String(err)}`));
      }
    }
    let pane: string;
    try {
      // -J joins wrapped lines: the token is ~100 chars and the pane is narrower.
      pane = tmuxExecSync(["capture-pane", "-p", "-J", "-t", MINT_FLOW_TMUX], { timeout: 3000 });
    } catch {
      // A capture can fail because tmux was slow under load (2026-09-01: a 3s
      // timeout mid-flow was read as "CLI exited" and killed a live approval).
      // Only a missing session means the CLI is gone.
      try {
        tmuxExecSync(["has-session", "-t", MINT_FLOW_TMUX], { timeout: 3000 });
        continue;
      } catch {}
      // Pane gone = the CLI exited; its last capture may still hold the token.
      const late = extractSetupToken(lastPane);
      if (late) return storeMinted(late);
      const tail = summarizeLoginPaneTail(lastPane);
      return finish(
        "rejected",
        tail && !/paste code here/i.test(tail)
          ? tail
          : "claude setup-token exited before the browser approval completed",
      );
    }
    lastPane = pane;
    const token = extractSetupToken(pane);
    if (token) return storeMinted(token);
  }
  return finish("rejected", "timed out waiting for the browser approval (5 min)");
}

// With per-session accounts on, the active login needs a live token (only the
// active one can be minted — see startMintFlow). Runs on every beat that
// carries the flag; acts once per account per daemon lifetime, and again a
// week before a token's expiry.
function maybeAutoMintToken(): void {
  if (!sessionTokensEnabled || isRemoteDevice() || mintFlowActive) return;
  try {
    const active = listProfiles().find((p) => p.active);
    if (!active) return;
    const key = active.uuid || active.email || active.name;
    if (autoMintDecidedAccounts.has(key)) return;
    const tok = accountTokenInfo(active.name);
    if (tok && tok.expires_at > Date.now() + MINT_RENEW_BEFORE_MS) return;
    autoMintDecidedAccounts.add(key);
    const lastAttempt = readAutoMintAttempts()[key] ?? 0;
    if (Date.now() - lastAttempt < AUTO_MINT_RETRY_MS) {
      log(`[MINT-FLOW] auto-mint for "${active.name}" skipped — attempted ${Math.round((Date.now() - lastAttempt) / 60000)}m ago (retry after 6h, or "mint now" in Settings)`);
      return;
    }
    stampAutoMintAttempt(key);
    syncServiceRef?.reportMintFlow("pending", active.name, active.email).catch(() => {});
    startMintFlow(active.name)
      .then((r) => log(`[MINT-FLOW] auto-mint for "${active.name}": ${r}`))
      .catch((err) => {
        const msg = err instanceof Error ? err.message : String(err);
        log(`[MINT-FLOW] auto-mint launch failed: ${msg}`);
        syncServiceRef?.reportMintFlow("rejected", active.name, active.email, msg).catch(() => {});
      });
  } catch (err) {
    log(`[MINT-FLOW] auto-mint check failed: ${err instanceof Error ? err.message : String(err)}`);
  }
}

// ---------------------------------------------------------------------------
// Browser sign-in flow (start_login): the web banner's "Sign in as <email>"
// CTA. `claude auth login` is a first-class CLI subcommand that opens the
// machine's browser on the OAuth page (pre-filled via --email) and writes the
// fresh credential to the keychain on completion — so the flow needs no TUI
// injection at all. It runs in a utility tmux pane (the CLI wants a TTY, and
// a stuck flow stays attachable), and the watcher below decides the outcome
// from the credential store itself: a CHANGED, healthy blob is the one signal
// that cannot lie. Outcome goes back through completeLoginFlow, which flips
// the device row's cc_login_flow (the web's reactive state channel) and, on
// confirmed, kicks the auth-blocked revive server-side.
// ---------------------------------------------------------------------------

const LOGIN_FLOW_TMUX = "cc-login-flow";
const LOGIN_FLOW_TIMEOUT_MS = 5 * 60 * 1000;
const LOGIN_FLOW_POLL_MS = 2000;
let loginFlowActive = false;
// Bumped by every launch; a watcher whose generation fell behind was
// superseded by a forced relaunch and must exit silently — its pane is gone
// (the relaunch killed it) and any outcome it reported would clobber the
// fresh flow's pending stamp.
let loginFlowGeneration = 0;

function credentialHashOf(raw: string | null): string | null {
  return raw ? createHash("sha256").update(raw).digest("hex") : null;
}

// The last meaningful line of the dying pane — the CLI's own error is the most
// honest "why" we can report ("Login cancelled", a network error, …).
export function summarizeLoginPaneTail(pane: string): string | null {
  const lines = pane
    .split("\n")
    .map((l) => l.replace(/\s+/g, " ").trim())
    .filter((l) => l.length > 0);
  const tail = lines[lines.length - 1];
  return tail ? tail.slice(0, 160) : null;
}

// The pane inherits the daemon's launchd PATH (no ~/.local/bin, where the
// claude binary lives), so the command must carry a full PATH itself. The
// trailing sleep keeps a dead CLI's pane alive past the watcher's next 2s
// poll — an instantly-dying pane vanishes before the first capture and
// reduces the failure report to the generic fallback.
export function buildLoginFlowCommand(email: string | undefined): string {
  const login = `PATH=${shellEscapeForSh(agentSpawnPath())} claude auth login --claudeai${email ? ` --email ${shellEscapeForSh(email)}` : ""}`;
  return `${login}; sleep 4`;
}

async function startLoginFlow(email: string | undefined, force = false): Promise<string> {
  // A second click while a flow is live joins it — the browser tab is already
  // open, and a second `claude auth login` would fight it for the callback
  // port. A FORCED relaunch (the banner's "reopen" action) supersedes it
  // instead: bump the generation (silences the old watcher), kill its pane,
  // start fresh.
  if (loginFlowActive && !force) return "login_flow_already_running";
  const gen = ++loginFlowGeneration;
  loginFlowActive = true;
  try {
    const baselineHash = credentialHashOf(readActiveCredential());
    await killTmuxSessionAndTree(LOGIN_FLOW_TMUX).catch(() => {});
    const cmd = buildLoginFlowCommand(email);
    tmuxExecSync(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", LOGIN_FLOW_TMUX, cmd], { timeout: 5000 });
    log(`[LOGIN-FLOW] started browser sign-in${email ? ` for ${email}` : ""} (tmux ${LOGIN_FLOW_TMUX})${force ? " [forced relaunch]" : ""}`);
    void watchLoginFlow(baselineHash, email, gen)
      .catch((err) => log(`[LOGIN-FLOW] watcher failed: ${err instanceof Error ? err.message : String(err)}`))
      .finally(() => { if (gen === loginFlowGeneration) loginFlowActive = false; });
    return "login_flow_started";
  } catch (err) {
    if (gen === loginFlowGeneration) loginFlowActive = false;
    throw err;
  }
}

// Poll until the credential store proves the sign-in (hash changed + healthy),
// the pane dies (the CLI exited — success or failure, the grace re-check
// tells them apart), or the timeout lapses (abandoned browser tab).
async function watchLoginFlow(baselineHash: string | null, requestedEmail: string | undefined, gen: number): Promise<void> {
  const deadline = Date.now() + LOGIN_FLOW_TIMEOUT_MS;
  let lastPane = "";

  const confirmedNow = (): boolean => {
    const raw = readActiveCredential();
    if (!raw) return false;
    const health = credentialHealth(raw, Date.now());
    return credentialHashOf(raw) !== baselineHash && health.pushable;
  };

  const finishConfirmed = async (): Promise<void> => {
    const email = activeAccountSummary()?.email ?? requestedEmail;
    log(`[LOGIN-FLOW] confirmed${email ? ` — signed in as ${email}` : ""}`);
    await killTmuxSessionAndTree(LOGIN_FLOW_TMUX).catch(() => {});
    // Fold the fresh login into its saved profile + the web's inventory now,
    // not on the next beat.
    await resnapshotIfActiveFresher().catch(() => {});
    sendHeartbeat().catch(() => {});
    // Remote Macs ride the push rail: a CHANGED blob push triggers the
    // remote auth-blocked revive on its own.
    pushCredentialToRemoteHosts("login_flow").catch(() => {});
    const revived = await syncServiceRef?.completeLoginFlow("confirmed", email).catch((err) => {
      log(`[LOGIN-FLOW] outcome report failed: ${err instanceof Error ? err.message : String(err)}`);
      return 0;
    });
    if (revived) log(`[LOGIN-FLOW] server queued revive for ${revived} auth-blocked session(s)`);
  };

  const finishRejected = async (reason: string): Promise<void> => {
    log(`[LOGIN-FLOW] rejected: ${reason}`);
    await killTmuxSessionAndTree(LOGIN_FLOW_TMUX).catch(() => {});
    await syncServiceRef?.completeLoginFlow("rejected", requestedEmail, reason).catch((err) => {
      log(`[LOGIN-FLOW] outcome report failed: ${err instanceof Error ? err.message : String(err)}`);
      return 0;
    });
  };

  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, LOGIN_FLOW_POLL_MS));
    // Superseded by a forced relaunch — the pane under our name is the NEW
    // flow's; touching or reporting anything now would sabotage it.
    if (gen !== loginFlowGeneration) return;
    if (confirmedNow()) return finishConfirmed();
    // Keep the freshest pane content so a dying CLI still leaves us its last
    // words; a capture failure means the pane (= the CLI) is gone.
    try {
      lastPane = tmuxExecSync(["capture-pane", "-p", "-t", LOGIN_FLOW_TMUX], { timeout: 3000 });
    } catch {
      // The CLI exited. The credential store is the arbiter now — and not by
      // the changed-hash test alone: a re-login into the SAME still-valid
      // account can leave the blob byte-identical (verified live 2026-08-11 —
      // the CLI printed "Login successful." and exited with an unchanged
      // keychain item). A healthy pushable credential after a clean exit
      // means the machine is signed in, whatever the hash says.
      const health = credentialHealth(readActiveCredential(), Date.now());
      if (health.pushable) return finishConfirmed();
      const tail = summarizeLoginPaneTail(lastPane);
      return finishRejected(tail ?? "the sign-in window closed before completing");
    }
  }
  if (gen !== loginFlowGeneration) return;
  return finishRejected("timed out waiting for the browser sign-in");
}

// Keep THIS machine's Claude Code login from lapsing. A running `claude`
// self-refreshes its ~8h access token from the stored refresh token; nothing
// does when no session runs, so an idle grant eventually expires ("Login
// expired · run /login"). On a slow tick, if the active login is near/past
// expiry, mint a fresh token from the refresh token and write it back — then
// re-snapshot the covering saved profile so a manual /login (or this refresh)
// never leaves a dormant profile carrying stale tokens.
//
// Primary devices only (same gate as the remote push): remotes run a pushed
// COPY of this credential and must never rotate the shared refresh token, or
// they'd invalidate the laptop's. The expiry threshold is itself the idle
// detector — a live claude keeps expiry ~8h out, so we almost always act only
// in idle gaps; a rare race with an active session self-heals because CC
// re-reads the credential store on a 401.
const CC_TOKEN_MAINT_INTERVAL_MS = 10 * 60 * 1000;
const CC_TOKEN_REFRESH_THRESHOLD_MS = 30 * 60 * 1000;
let ccTokenMaintInFlight = false;

async function maintainActiveCcToken(reason: string): Promise<void> {
  if (isRemoteDevice() || ccTokenMaintInFlight) return;
  ccTokenMaintInFlight = true;
  try {
    const expiresAt = await activeCredentialExpiresAt();
    if (expiresAt != null && expiresAt - Date.now() < CC_TOKEN_REFRESH_THRESHOLD_MS) {
      const res = await refreshActiveCredential();
      if (res.refreshed) {
        const mins = Math.round(((res.expiresAt ?? Date.now()) - Date.now()) / 60000);
        log(`[CC-AUTH] Refreshed active login (${mins}m to next expiry; ${reason})`);
        // The remotes run a pushed copy — hand them the fresh token now rather
        // than on the next tick.
        pushCredentialToRemoteHosts("token_refresh").catch(() => {});
      } else {
        log(`[CC-AUTH] Proactive refresh skipped: ${res.reason} (${reason})`);
      }
    }
    // Propagate a fresher active credential (a manual /login OR the refresh
    // above) into its saved profile. Cheap no-op when already in step.
    const updated = await resnapshotIfActiveFresher();
    if (updated) log(`[CC-AUTH] Re-snapshotted profile "${updated}" from fresher active login`);
  } catch (err) {
    log(`[CC-AUTH] Token maintenance failed (${reason}): ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    ccTokenMaintInFlight = false;
  }
}

// Per-account usage snapshots: probe the OAuth usage API for the active login
// and every saved profile with a live token, cache to ~/.codecast/cc-usage.json.
// The next heartbeat picks the file change up via the payload's mtime-keyed
// cache, so the web's meters follow within a beat. Primary devices only —
// remotes have no profile inventory of their own.
const CC_USAGE_REFRESH_INTERVAL_MS = 5 * 60 * 1000;
let ccUsageRefreshInFlight = false;

// Codex per-account usage: enroll/refresh the active login's profile, probe
// the active account via the real ~/.codex (RPC + rollout-log model mix), then
// probe each dormant profile via its CODEX_HOME snapshot dir. Shares the
// cc-usage cadence; the heartbeat reads the cache file via its mtime-keyed
// payload. Codex logins are per-machine (never pushed to remotes), so every
// device reports its own inventory.
let codexUsageRefreshInFlight = false;

async function maintainCodexUsageSnapshot(reason: string): Promise<void> {
  if (codexUsageRefreshInFlight) return;
  codexUsageRefreshInFlight = true;
  try {
    const res = await refreshCodexUsageSnapshots();
    if (res.probed.length > 0 || res.failed.length > 0) {
      const failNote = res.failed.length
        ? ` failed=${res.failed.map((f) => `${f.name}(${f.reason})`).join(",")}`
        : "";
      log(`[ACCOUNTS] Codex usage refreshed for ${res.probed.length} account(s) (${reason})${failNote}`);
    }
  } catch (err) {
    log(`[ACCOUNTS] Codex usage refresh failed (${reason}): ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    codexUsageRefreshInFlight = false;
  }
}

async function maintainCcUsageSnapshots(reason: string): Promise<void> {
  if (isRemoteDevice() || ccUsageRefreshInFlight) return;
  ccUsageRefreshInFlight = true;
  try {
    const res = await refreshUsageSnapshots();
    if (res.probed.length > 0 || res.failed.length > 0) {
      const failNote = res.failed.length
        ? ` failed=${res.failed.map((f) => `${f.name}(${f.reason})`).join(",")}`
        : "";
      log(`[ACCOUNTS] Usage refreshed for ${res.probed.length} account(s) (${reason})${failNote}`);
    }
  } catch (err) {
    log(`[ACCOUNTS] Usage refresh failed (${reason}): ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    ccUsageRefreshInFlight = false;
  }
}

// Snapshot this machine's installed agent-feature snippets + stable mode from
// local config, keyed by canonical slug (the web never sees the slug→config-key
// mapping). Reported on every heartbeat so the Settings page mirrors what each
// device actually has — and reflects a `cast install`/`--disable` within ~30s.
function buildDeviceSettingsPayload(config: Config | null): DeviceSnippetSettings | undefined {
  if (!config) return undefined;
  const snippets: Record<string, boolean> = {};
  for (const s of SNIPPET_CATALOG) {
    const v = (config as any)[s.enabledKey];
    if (typeof v === "boolean") {
      snippets[s.slug] = v;
      // Mirror under the pre-rename key so stale clients still see the flag.
      if (s.wireSlug) snippets[s.wireSlug] = v;
    }
  }
  return {
    snippets,
    stable_mode: (config as any).stable_mode ?? "off",
    stable_global: (config as any).stable_global === true,
  };
}

// Auto-enroll the machine's active CC login as a saved profile: after a fresh
// /login the account just appears in the web switcher, no save step. One
// attempt per account per daemon lifetime — a failure (e.g. API-key login,
// keychain hiccup) falls back to the Settings page's manual save CTA instead
// of retrying every beat. Remote devices run a pushed COPY of the primary's
// credential, so profiles are only ever saved on the primary.
const autoSaveDecidedAccounts = new Set<string>();
let profileNamesMigrated = false;
function maybeAutoSaveAccount(): void {
  if (isRemoteDevice()) return;
  if (!profileNamesMigrated) {
    // One-shot: profile names used to be auto-derived from the email DOMAIN
    // (claude2@almostcandid.com → almostcandid); they now come from the local
    // part (claude2). Rename still-auto-named profiles to the new form.
    profileNamesMigrated = true;
    try {
      for (const r of migrateLegacyProfileNames()) {
        log(`[ACCOUNTS] Renamed profile "${r.from}" → "${r.to}" (names now use the email's local part)`);
      }
    } catch (err) {
      log(`[ACCOUNTS] Profile name migration failed: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  try {
    // Ride the mtime-cached payload for the per-beat check — ~/.claude.json
    // can be multi-MB, so an unconditional parse every 30s is real work.
    const payload = getAccountsHeartbeatPayload();
    const key = payload?.active_uuid || payload?.active_email;
    if (!key || autoSaveDecidedAccounts.has(key)) return;
    if (payload.active_email && payload.profiles.some((p) => p.email === payload.active_email)) return;
    autoSaveDecidedAccounts.add(key);
    const saved = autoSaveActiveProfile();
    if (saved) {
      log(`[ACCOUNTS] Auto-saved active login as profile "${saved.name}"${saved.email ? ` (${saved.email})` : ""}`);
    }
  } catch (err) {
    log(`[ACCOUNTS] Auto-save of active login failed: ${err instanceof Error ? err.message : String(err)}`);
  }
  maybeEnableLimitsGuidance();
}

// The "Usage limits" agent snippet turns itself on the first time this machine
// has more than one saved Claude account (see limitsGuidance.ts). The daemon
// only decides; the CLI owns config + instruction-file writes, so the install
// goes through the same `cast install <slug>` the web Settings toggle uses.
// One attempt per daemon lifetime; an explicit off is never overridden.
let limitsGuidanceDecided = false;
function maybeEnableLimitsGuidance(): void {
  if (limitsGuidanceDecided) return;
  try {
    const config = readConfig();
    if (config?.limits_enabled !== undefined) {
      limitsGuidanceDecided = true;
      return;
    }
    if (!shouldAutoEnableLimitsGuidance(config, listProfiles().length)) return;
    limitsGuidanceDecided = true;
    log(`[ACCOUNTS] Second Claude account saved — enabling the usage-limits agent snippet`);
    runCastCommand(["install", "limits"], { timeoutMs: 60 * 1000 }).catch((e) =>
      logError("cast install limits failed", e instanceof Error ? e : new Error(String(e)))
    );
  } catch {}
}

// Same per-beat enrollment for the Codex login: a fresh `codex login` appears
// in the inventory on the next heartbeat instead of waiting for the usage
// cycle. One attempt per account per daemon lifetime, mirroring the CC path.
const codexAutoSaveDecided = new Set<string>();
let codexProfileNamesMigrated = false;
function maybeAutoSaveCodexAccount(): void {
  if (!codexProfileNamesMigrated) {
    codexProfileNamesMigrated = true;
    try {
      for (const r of migrateLegacyCodexProfileNames()) {
        log(`[ACCOUNTS] Renamed Codex profile "${r.from}" → "${r.to}" (names now use the email's local part)`);
      }
    } catch (err) {
      log(`[ACCOUNTS] Codex profile name migration failed: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  try {
    const payload = getCodexAccountsHeartbeatPayload();
    const key = payload?.active_uuid || payload?.active_email;
    if (!key || codexAutoSaveDecided.has(key)) return;
    codexAutoSaveDecided.add(key);
    const saved = autoSaveActiveCodexProfile();
    if (saved) {
      log(`[ACCOUNTS] Auto-saved active Codex login as profile "${saved.name}"${saved.email ? ` (${saved.email})` : ""}`);
    }
  } catch (err) {
    log(`[ACCOUNTS] Auto-save of active Codex login failed: ${err instanceof Error ? err.message : String(err)}`);
  }
}

async function sendHeartbeat(): Promise<void> {
  const config = readConfig();
  if (!config?.auth_token || !config?.convex_url) {
    return;
  }

  // Before publishing the account inventories, make sure the active logins are
  // in them — this is what makes a new `/login` (or `codex login`) show up in
  // Settings by itself.
  maybeAutoSaveAccount();
  maybeAutoSaveCodexAccount();

  // Dynamic-client model inventory: recollect in the background when stale; a
  // fresh set rides a beat only until the server acks it (hash-gated).
  ensureModelInventoryFresh();
  const modelInventory = pendingModelInventoryPayload();
  // Capability inventory (skills/plugins/MCP): same ride — background scan,
  // hash-gated, with an hourly liveness floor. See capabilities/heartbeat.ts.
  ensureCapabilityInventoryFresh();
  const capabilityPayload = pendingCapabilityPayload();

  try {
    const siteUrl = config.convex_url.replace(".cloud", ".site");
    // Bound the request: an untimed fetch here can hang indefinitely (observed
    // on a long-running daemon), starving device presence. Fail fast + retry.
    const response = await fetch(`${siteUrl}/cli/heartbeat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      signal: AbortSignal.timeout(15000),
      body: JSON.stringify({
        api_token: config.auth_token,
        version: daemonVersion || "unknown",
        platform,
        pid: process.pid,
        autostart_enabled: isAutostartEnabled(),
        has_tmux: hasTmux(),
        local_project_roots: computeLocalProjectRoots(),
        // Per-repo git health (origin real? fetch ok? ahead/behind) — see gitPlane.ts.
        git_plane: gitPlaneHeartbeatPayload(),
        // The device's PUBLIC git key (gitIdentity.ts) — not a secret; the web
        // shows it so the user can grant this machine repo access.
        git_pubkey: deviceGitPubkey(),
        device_id: deviceId(),
        device_label: deviceLabel(),
        // The machine's own name, kept separate from device_label (which a human
        // can override to anything). Purely a suggested default for the SSH host
        // in Settings → Devices — the daemon can't know whether it's reachable,
        // so nothing builds an attach command out of it unaided.
        device_hostname: stableHostname(),
        is_remote_device: isRemoteDevice(),
        // Time since the last keyboard/mouse event anywhere on this machine
        // (macOS only; omitted elsewhere). Sent as a DURATION so the server can
        // anchor it to its own clock — daemon clock skew can't fake presence.
        // Powers the on-by-default machine_wide_presence push routing.
        input_idle_ms: (await readInputIdleMs()) ?? undefined,
        // Saved CC account profiles (names/emails/tiers only, never tokens) so
        // the web can render the account switcher. Recomputed when the
        // backing files change (mtime-keyed cache), so CLI-side saves and
        // fresh /logins surface on the next beat.
        cc_accounts: getAccountsHeartbeatPayload() ?? undefined,
        // Codex (ChatGPT) account inventory — same shape as cc_accounts
        // (names/emails/plans + per-account usage, never tokens). Recomputed
        // when its backing files change (mtime-keyed cache).
        codex_accounts: getCodexAccountsHeartbeatPayload() ?? undefined,
        // Managed-provider-key metadata (pl-207): the device's ECDH public key
        // (not a secret — the web encrypts a key to it) + which providers have a
        // key here (ids only, never the keys). Lets the web show managed status
        // and seal a new key so Convex never sees plaintext.
        provider_key_pubkey: getProviderKeyPublicKey(CONFIG_DIR),
        managed_provider_ids: Object.keys(readProviderKeyStore(CONFIG_DIR)).sort(),
        // Installed agent-feature snippets + stable mode, so the web Settings
        // page mirrors (and can toggle) this device's setup.
        settings: buildDeviceSettingsPayload(config) ?? undefined,
        // Live model inventory for dynamic clients (opencode/pi), hash-gated so
        // the ~10KB list rides a beat only when it actually changed.
        model_inventory: modelInventory,
        capability_state: capabilityPayload,
        ...syncHealthFields(),
      }),
    });

    if (!response.ok) {
      const text = await response.text().catch(() => "");
      log(`Heartbeat failed: ${response.status} ${text}`);
      return;
    }
    if (modelInventory) markModelInventorySent(modelInventory.hash);
    if (capabilityPayload) markCapabilityPayloadSent(capabilityPayload.hash);

    const data = await response.json();
    if (data.commands && data.commands.length > 0) {
      log(`Received ${data.commands.length} remote command(s)`);
      for (const cmd of data.commands) {
        if (processedPollCommandIds.has(cmd.id)) continue;
        processedPollCommandIds.add(cmd.id);
        await executeRemoteCommand(cmd.id, cmd.command, config, cmd.args);
      }
    }

    // Capability convergence: one field read + one integer store per beat,
    // then the reconciler decides whether it has anything to do (mode off =
    // one field read; revisions equal = one compare). Fire-and-forget off the
    // beat: a slow disk must never delay presence, and a failure logs and
    // waits for the next beat. The kill switch works the moment the server
    // flips capabilities_mode, no CLI ship needed.
    recordConvergenceSignals(data);
    // Per-session accounts flag (web-set on the device row) — drives the
    // daemon's auto-mint of setup-tokens for the active login.
    if (typeof data.cc_session_tokens === "boolean") {
      sessionTokensEnabled = data.cc_session_tokens;
      maybeAutoMintToken();
    }
    // Team-gated agent snippets follow the team feature flags: install when a
    // team turns chat/calls on, disable when the last team turns it off.
    if (data.snippet_availability && typeof data.snippet_availability === "object") {
      void reconcileGatedSnippets(data.snippet_availability as Record<string, boolean>)
        .catch((err) => log(`[SNIPPET] gated reconcile failed: ${String(err).slice(0, 160)}`));
    }
    if (config.user_id) {
      void reconcileFromHeartbeat({
        siteUrl,
        apiToken: config.auth_token,
        userId: config.user_id,
        home: process.env.HOME || require("os").homedir(),
        log,
      }).catch((err) => log(`[capabilities] reconcile failed: ${String(err).slice(0, 160)}`));
    }

    if (data.sync_mode !== undefined) {
      const currentConfig = readConfig();
      const serverMode = data.sync_mode as "all" | "selected";
      const serverProjects: string[] = data.sync_projects ?? [];
      const localMode = currentConfig?.sync_mode ?? "all";
      const localProjects = currentConfig?.sync_projects ?? [];

      if (serverMode !== localMode || JSON.stringify(serverProjects) !== JSON.stringify(localProjects)) {
        log(`Sync settings updated from server: mode=${serverMode}, projects=${serverProjects.length}`);
        patchConfig({ sync_mode: serverMode, sync_projects: serverProjects });
        if (activeConfig) {
          activeConfig.sync_mode = serverMode;
          activeConfig.sync_projects = serverProjects;
        }
      }
    }

    if (data.team_id !== undefined) {
      const currentConfig = readConfig();
      if (currentConfig && currentConfig.team_id !== data.team_id) {
        log(`Team ID updated from server: ${data.team_id}`);
        patchConfig({ team_id: data.team_id });
        if (activeConfig) {
          activeConfig.team_id = data.team_id;
        }
      }
    }

    if (data.agent_permission_modes !== undefined) {
      const currentConfig = readConfig();
      const serverModes = data.agent_permission_modes;
      const localModes = currentConfig?.agent_permission_modes;
      if (JSON.stringify(serverModes) !== JSON.stringify(localModes)) {
        log(`Agent permission modes updated from server: ${JSON.stringify(serverModes)}`);
        patchConfig({ agent_permission_modes: serverModes });
        if (activeConfig) {
          activeConfig.agent_permission_modes = serverModes;
        }
      }
    }

    if (data.agent_default_params !== undefined) {
      const currentConfig = readConfig();
      const serverParams = data.agent_default_params;
      const localParams = currentConfig?.agent_default_params;
      if (JSON.stringify(serverParams) !== JSON.stringify(localParams)) {
        log(`Agent default params updated from server: ${JSON.stringify(serverParams)}`);
        patchConfig({ agent_default_params: serverParams });
        if (activeConfig) {
          activeConfig.agent_default_params = serverParams;
        }
      }
    }

    // ~/.claude/settings.json `model` mirrors the codecast default. A session's
    // `/model <x>` one-shot rewrites that file as a side effect; re-asserting
    // the pinned default here keeps the switch session-scoped in practice and
    // bare `claude` terminals on the model the user chose in codecast.
    if (data.default_models !== undefined) {
      try {
        if (reconcileClaudeSettingsModel(data.default_models)) {
          log(`[DEFAULT-MODEL] settings.json model -> ${data.default_models?.claude} (codecast default)`);
        }
      } catch (err) {
        log(`[DEFAULT-MODEL] settings.json reconcile failed: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  } catch (err) {
    log(`Heartbeat error: ${err instanceof Error ? err.message : String(err)}`);
  }
}

/**
 * Resolve how to invoke this CLI's own `cast` entrypoint as a child process,
 * coping with the three ways the daemon itself can be running:
 *   - from source   (`bun .../daemon.ts`)  -> bun + .../index.ts
 *   - compiled bin   (`cast _daemon`)       -> the cast binary itself
 *   - on PATH        (fallback)             -> `cast`
 * Returns argv parts so callers can spawn without shell-quoting hazards.
 */
/** Shell prefix routing an agent launch through `cast _disclaimed --` so the
 *  agent becomes TCC self-responsible (see disclaim.ts). "" off-macOS or when
 *  CODECAST_NO_DISCLAIM=1. */
function disclaimPrefix(): string {
  const { cmd, prefixArgs } = resolveCastInvocation();
  return buildDisclaimShellPrefix([cmd, ...prefixArgs].join(" "));
}

function resolveCastInvocation(): { cmd: string; prefixArgs: string[] } {
  const argv1 = process.argv[1] || "";
  if (argv1.endsWith("daemon.ts") || argv1.endsWith("daemon.js")) {
    const ext = argv1.endsWith(".ts") ? ".ts" : ".js";
    const indexPath = path.join(path.dirname(argv1), `index${ext}`);
    return { cmd: process.argv[0], prefixArgs: [indexPath] };
  }
  if (argv1 === "_daemon" || !argv1.includes("/")) {
    return { cmd: process.execPath, prefixArgs: [] };
  }
  return { cmd: "cast", prefixArgs: [] };
}

/**
 * Run a `cast <args...>` subcommand in a child process WITHOUT blocking the
 * daemon's event loop. Critical for long, I/O-heavy subcommands (e.g. a remote
 * move that scp's a multi-GB git bundle): a synchronous execFileSync would
 * freeze the single-threaded event loop, the `startEventLoopMonitor` tick would
 * stop, lastHeartbeatTick would go stale, and the watchdog would SIGKILL the
 * daemon mid-operation. Awaiting the child's 'exit' event yields to the loop so
 * heartbeats keep flowing. A hard timeout guards against a truly hung child.
 */
// Team-gated snippets (chat, calls) follow their team feature flag. The
// heartbeat carries, per gated slug, whether ANY of the user's teams has the
// feature on; planGatedSnippets (gatedSnippets.ts) decides what changed and
// this runs each change through the same `cast install` the web toggle and a
// human use — install on the way up, disable on the way down.
let gatedReconcileInFlight = false;
async function reconcileGatedSnippets(avail: Record<string, boolean>): Promise<void> {
  if (gatedReconcileInFlight) return;
  const cfg = readConfig();
  if (!cfg) return;
  const prev = cfg.snippet_availability ?? {};
  const plan = planGatedSnippets(prev, avail, cfg as any);
  const nothingNew = Object.keys(plan.next).every((k) => prev[k] === plan.next[k]);
  if (nothingNew && plan.actions.length === 0) return;
  gatedReconcileInFlight = true;
  try {
    let touched = false;
    const next = { ...plan.next };
    for (const { slug, enable } of plan.actions) {
      const cliArgs = enable ? ["install", slug] : ["install", slug, "--disable"];
      log(`[SNIPPET] ${enable ? "installing" : "disabling"} ${slug} (team feature ${enable ? "on" : "off"})`);
      const res = await runCastCommand(cliArgs, { timeoutMs: 60 * 1000 });
      if (res.code !== 0) {
        // Left unrecorded on purpose: the next beat retries it.
        log(`[SNIPPET] cast ${cliArgs.join(" ")} failed (exit ${res.code}): ${(res.stderr || res.stdout || "").trim().slice(-200)}`);
        if (prev[slug] === undefined) delete next[slug]; else next[slug] = prev[slug];
        continue;
      }
      touched = true;
    }
    patchConfig({ snippet_availability: next });
    // Report the new snippet state now rather than on the next beat.
    if (touched) await sendHeartbeat().catch(() => {});
  } finally {
    gatedReconcileInFlight = false;
  }
}

function runCastCommand(
  args: string[],
  opts: { timeoutMs?: number } = {},
): Promise<{ code: number | null; stdout: string; stderr: string }> {
  const timeoutMs = opts.timeoutMs ?? 30 * 60 * 1000;
  const { cmd, prefixArgs } = resolveCastInvocation();
  return new Promise((resolve) => {
    let stdout = "";
    let stderr = "";
    let child: ReturnType<typeof spawn>;
    try {
      child = spawn(cmd, [...prefixArgs, ...args], {
        // The daemon's launchd PATH has no node/bun/homebrew; the cast shim and
        // anything it execs (a browser driver, claude) need the agent PATH.
        env: { ...process.env, PATH: agentSpawnPath() },
        stdio: ["ignore", "pipe", "pipe"],
      });
    } catch (err) {
      resolve({ code: -1, stdout, stderr: String(err) });
      return;
    }
    const timer = setTimeout(() => {
      try { child.kill("SIGKILL"); } catch { /* already gone */ }
    }, timeoutMs);
    child.stdout?.on("data", (d) => { stdout += d.toString(); });
    child.stderr?.on("data", (d) => { stderr += d.toString(); });
    child.on("error", (err) => {
      clearTimeout(timer);
      resolve({ code: -1, stdout, stderr: `${stderr}${String(err)}` });
    });
    child.on("exit", (code) => {
      clearTimeout(timer);
      resolve({ code, stdout, stderr });
    });
  });
}

/**
 * True when a conversation is owned by a DIFFERENT device that is currently
 * online — so THIS daemon must NOT run/deliver/resume the session and should
 * leave it to the owner. Covers both a live local peer AND a remote Mac a
 * session was explicitly moved to: auto-routing never assigns a remote owner
 * (pickOwnerDevice excludes remotes), so an ONLINE remote owner is always a
 * deliberate server that genuinely runs the session — letting the local daemon
 * also resume/answer is the move's split-brain. An OFFLINE owner returns false
 * so this daemon can reclaim and serve as a fallback.
 */
function ownedByAnotherLiveDevice(
  info: { ownerDeviceId?: string | null; ownerOnline?: boolean } | null | undefined,
): boolean {
  return !!info?.ownerDeviceId && info.ownerDeviceId !== deviceId() && !!info.ownerOnline;
}

// Every resume driven by a resume_session / fork_session command — i.e. a human
// pressing Restart/Resume/Fork. See ResumeOptions.userInitiated.
const USER_RESUME = { userInitiated: true } as const;

export type OwnerInfo = { ownerDeviceId?: string | null; ownerIsRemote?: boolean; ownerOnline?: boolean } | null | undefined;

export type ResumeOwnerVerdict = "proceed" | "owned_by_live_device" | "remote_unowned" | "remote_no_conversation";

/**
 * Whether THIS daemon may resume a conversation, given who owns it. Two rules,
 * one owner lookup:
 *   - EVERY device: never resume a conversation owned by a DIFFERENT device that
 *     is currently live — that daemon is the one running it. The command queue
 *     has always enforced this (see the ownedByAnotherLiveDevice skip in
 *     executeRemoteCommand), but resume itself only gated remotes, so a
 *     conversation owned by a live peer got resumed on both machines at once.
 *   - REMOTE devices only: a remote daemon (the cloud Mac) manages ONLY sessions
 *     explicitly OWNED by it. Unlike the primary local daemon it must not adopt
 *     unowned sessions — doing so reconstitutes the user's real sessions from
 *     Convex and double-manages them (cross-device stomp).
 * A DEAD/unresponsive owner, or an unowned conversation, proceeds on a local
 * daemon: that failover (adopt and keep serving) is deliberate.
 */
export function resumeOwnerVerdict(input: {
  conversationId: string | undefined;
  localDeviceId: string;
  isRemote: boolean;
  owner: OwnerInfo;
}): ResumeOwnerVerdict {
  if (!!input.owner?.ownerDeviceId && input.owner.ownerDeviceId !== input.localDeviceId && !!input.owner.ownerOnline) {
    return "owned_by_live_device";
  }
  if (!input.isRemote) return "proceed";
  if (!input.conversationId) return "remote_no_conversation";
  if (input.owner?.ownerDeviceId !== input.localDeviceId) return "remote_unowned";
  return "proceed";
}

// Every tmux name start_session could have minted for a conversation
// (cc-<agent>-<convId.slice(-12)>), for EVERY launchable agent — sourced from the
// shared registry, because the old hardcoded ["claude","codex","cursor","gemini"]
// silently leaked opencode and pi panes, and this sweep is the ONLY teardown on
// the owner-defer path: a missing id there means a permanently unkillable pane.
export function derivedPaneNamesForConversation(conversationId: string): string[] {
  const convSuffix = conversationId.slice(-12);
  return Object.keys(AGENT_CLIENTS).map((agent) => `cc-${agent}-${convSuffix}`);
}

// Everything killConversationBackends clears per session, in one place so the
// owner-defer sweep can't drift from it. resumeInFlight matters most: a resume
// that passed the lifecycle/owner gates BEFORE the kill is still holding a
// promise, and leaving its entry behind lets the next delivery join that stale
// promise and adopt the pane it recreates. (This narrows the window; it cannot
// cancel a resume already in flight — one that lands after the sweep is caught by
// the next health check or reaper pass.)
export function clearSessionTrackingForKill(sessionId: string | null | undefined): void {
  if (!sessionId) return;
  // NOTE on restartingSessionIds: killConversationBackends never cleared it, and
  // this does. Harmless today because Restart enqueues kill and resume as two
  // separate daemon commands, so the guard is not yet set when the kill runs. It
  // stops being harmless if those ever land together or in-process: the guard is
  // what tells the watchdog "a restart is in progress, don't mark this
  // completed", so clearing it mid-restart would make Restart complete the
  // session instead of restarting it. If you couple them, drop this line.
  stopManagedSessionHeartbeat(sessionId);
  stopCodexPermissionPoller(sessionId);
  resumeSessionCache.delete(sessionId);
  sessionProcessCache.delete(sessionId);
  resumeInFlight.delete(sessionId);
  resumeInFlightStarted.delete(sessionId);
  restartingSessionIds.delete(sessionId);
}

// Test/inspection seam: which per-session kill-teardown maps still hold an entry.
export function sessionKillTrackingSnapshot(sessionId: string): Record<string, boolean> {
  return {
    pane: resumeSessionCache.has(sessionId),
    resumeInFlight: resumeInFlight.has(sessionId),
    resumeInFlightStarted: resumeInFlightStarted.has(sessionId),
    restarting: restartingSessionIds.has(sessionId),
    process: sessionProcessCache.has(sessionId),
  };
}

/**
 * Kill every tmux pane for a conversation that is PHYSICALLY on this machine,
 * regardless of who the conversation records as its owner. A pane in this
 * daemon's own tmux server is always safe to tear down, and an owner-mismatched
 * one is otherwise unkillable from anywhere: the owner device has no pane to
 * kill and this device refuses the command (2026-08-03 — pane on the laptop,
 * owner_device_id=nose, both daemons declined, the agent ran on untouched).
 *
 * Two ownership-independent sweeps, both keyed off ids alone (no lookup tables,
 * so they reach a pane that outlived every in-memory map — e.g. across a daemon
 * restart):
 *   1. any pane stamped with this session id (@codecast_session_id)
 *   2. the deterministic cc-<agent>-<convId.slice(-12)> name start_session mints
 * Each stops tracking BEFORE the kill, or heartbeatHealthCheck sees the vanished
 * tmux and RECONSTITUTES the agent. Returns how many panes were killed.
 */
export async function killLocalPanesForConversation(
  conversationId: string,
  sessionIdHint: string | undefined,
  context: string,
): Promise<number> {
  let killed = 0;
  const stopTracking = (id: string | null | undefined) => clearSessionTrackingForKill(id);

  const sessionId = sessionIdHint ?? buildReverseConversationCache(readConversationCache())[conversationId];
  // UNCONDITIONALLY, before any pane lookup — finding no pane is not the same as
  // having nothing to clear, and is in fact THE race this exists for: a resume
  // that passed the gates is mid-flight and its pane does not exist YET, so a
  // sweep that only cleared state next to a kill would leave resumeInFlight set
  // and let that resume complete into a killed conversation. (The loops below
  // still call it for the id stamped on a pane, which can differ from this one.)
  clearSessionTrackingForKill(sessionId);
  if (sessionId) {
    try {
      const { stdout: tmuxList } = await tmuxExec(["list-sessions", "-F", "#{session_name}"]);
      for (const tmuxName of tmuxList.trim().split("\n")) {
        if (!tmuxName || !(await tmuxSessionMatchesFullSessionId(tmuxName, sessionId))) continue;
        if (!validateTmuxTarget(tmuxName)) continue;
        stopTracking(sessionId);
        await killTmuxSessionAndTree(tmuxName);
        log(`[${context}] Killed local tmux ${tmuxName} (+process tree) for session ${sessionId.slice(0, 8)}`);
        killed++;
      }
    } catch {}
  }

  // agentType isn't in the kill args, so try every prefix; has-session guards
  // each (cheap, idempotent). The session id lives on the tmux itself, so we can
  // stop the right heartbeat even when no lookup table maps this conversation.
  for (const derivedName of derivedPaneNamesForConversation(conversationId)) {
    if (!validateTmuxTarget(derivedName)) continue;
    try {
      await tmuxExec(["has-session", "-t", derivedName], { timeout: 3000 });
    } catch {
      continue; // no such session
    }
    const derivedSessionId = (await getTmuxSessionOption(derivedName, "@codecast_session_id"))?.trim() || null;
    stopTracking(derivedSessionId);
    await killTmuxSessionAndTree(derivedName);
    log(`[${context}] Killed tmux ${derivedName} by derived name (session ${derivedSessionId?.slice(0, 8) ?? "?"}) for conversation ${conversationId.slice(0, 12)}`);
    killed++;
  }
  return killed;
}

// Tear down every backend bound to a conversation (app-server thread and/or
// tmux pane + process tree), stopping heartbeats BEFORE each kill (or
// heartbeatHealthCheck sees the vanished tmux and RECONSTITUTES the agent),
// then wipe delivery/resume caches so the next pending message cleanly
// auto-resumes. Shared by kill_session and switch_account — the latter recycles
// limit-blocked sessions so a fresh `claude --resume` re-reads the just-swapped
// account credential. Extracted verbatim from the kill_session command body.
async function killConversationBackends(
  conversationId: string,
  sessionIdHint?: string
): Promise<{ result?: string; error?: string }> {
  let result: string | undefined;
  let error: string | undefined;

  // Tear down every backend bound to this conversation (app-server thread
  // and/or tmux), then stamp the kill-specific server status. Shared with
  // start_session so "one backend per conversation" is enforced identically
  // -- and so a split-brained conversation gets BOTH backends killed, not
  // just the first one matched.
  const teardown = await teardownConversationBackendsLive(conversationId, { interruptActiveTurn: true });
  if (teardown.killedAppServer && teardown.appServerThreadId) {
    if (syncServiceRef) {
      syncServiceRef.markSessionCompleted(conversationId).catch(logConvexFailure);
      sendAgentStatus(syncServiceRef, conversationId, teardown.appServerThreadId, "stopped");
    }
    log(`[REMOTE] Killed app-server thread ${teardown.appServerThreadId.slice(0, 8)} for conversation ${conversationId.slice(0, 12)}`);
    return { result: "killed_app_server" };
  }
  if (teardown.killedTmux) {
    result = "killed_tmux";
  }

  const cache = readConversationCache();
  const reverse = buildReverseConversationCache(cache);
  // The caller can carry the session_id (from the conversation row, or the
  // client's cached copy of a deleted row) — fall back to it when the local
  // conversation cache has no mapping (remapped or ghost conversations).
  const sessionId = reverse[conversationId] ?? sessionIdHint;
  // A Codex subagent thread has NO process of its own — it runs inside its parent
  // TUI's process, so findSessionProcess resolves it to the PARENT's pid and tty
  // (see sessionProcessOwnership). Destroying that on one nested card's behalf
  // SIGKILLs the parent agent and every sibling thread. Reachable from three user
  // gestures today, including a plain `cast dismiss`.
  //
  // The plan covers BOTH process-destroying actions here, not just the reap.
  // resumeSessionCache is keyed by session id but its VALUE can be the PARENT's
  // tmux name: resolveLiveTmuxTarget resolves a subagent through the borrowed pid
  // to the parent's pane and caches that. So "resume a subagent card, then kill or
  // dismiss it" would kill the parent's tmux even with the reap guarded. Guarding
  // only the reap is not enough — see killCachedResumeTmux below.
  //
  // Only PROCESS teardown is skipped. Everything else still runs, so the card
  // retires exactly like any other kill: heartbeats stop, caches clear,
  // delivery/resume state is wiped, and the caller acks with no error. The honest
  // residual is that the thread keeps running inside the parent until it finishes
  // — a subagent genuinely cannot be killed independently of its parent.
  //
  // This deliberately no-ops the per-child kill_session that
  // cascadeHideToNestedChildren enqueues when a PARENT is killed: the parent's own
  // kill_session reaps the shared process once, so the children have nothing left
  // to do. Do not "restore" their reaps — they would each re-kill the same
  // already-dead tree, and the guard is what makes killing a child alone safe. The
  // parent's own kill is unaffected: it owns its process, so it takes the branch
  // below and tears its tree down normally.
  const teardownPlan = planSessionTeardown(sessionId ? sessionProcessOwnership(sessionId) : "owned");
  if (sessionId && !result && !teardownPlan.reapPidTree) {
    log(`[REMOTE] Skipping process teardown for ${shortId(sessionId)}: does not own its process (conversation ${conversationId.slice(0, 12)})`);
  } else if (sessionId && !result) {
    const proc = await findSessionProcess(sessionId, detectSessionAgentType(sessionId));
    if (proc) {
      const tmuxTarget = await findTmuxPaneForTty(proc.tty);
      if (tmuxTarget && validateTmuxTarget(tmuxTarget)) {
        const tmuxSessionName = tmuxTarget.split(":")[0];
        await killTmuxSessionAndTree(tmuxSessionName);
        await reapPidTree(proc.pid); // belt-and-suspenders for anything outside the pane
        result = "killed_tmux";
        log(`[REMOTE] Killed tmux ${tmuxSessionName} + process tree for conversation ${conversationId.slice(0, 12)}`);
      } else {
        const n = await reapPidTree(proc.pid);
        if (n > 0) {
          result = "killed_sigkill";
          log(`[REMOTE] SIGKILLed pid ${proc.pid} + descendants (${n} procs) for conversation ${conversationId.slice(0, 12)}`);
        } else {
          error = `Failed to kill pid ${proc.pid}`;
        }
      }
    }
  }

  if (sessionId) {
    const cachedTmux = resumeSessionCache.get(sessionId);
    if (cachedTmux && validateTmuxTarget(cachedTmux) && !teardownPlan.killCachedResumeTmux) {
      // The cached name is the PARENT's tmux, reached through the borrowed pid.
      // Forget the mapping without killing anything — the parent owns that pane.
      resumeSessionCache.delete(sessionId);
      log(`[REMOTE] Dropped cached resume tmux ${cachedTmux} for ${shortId(sessionId)} without killing it (session does not own that pane)`);
    } else if (cachedTmux && validateTmuxTarget(cachedTmux)) {
      await killTmuxSessionAndTree(cachedTmux);
      log(`[REMOTE] Killed cached resume tmux ${cachedTmux} (+process tree) for session ${shortId(sessionId)}`);
      resumeSessionCache.delete(sessionId);
      if (!result) result = "killed_tmux";
    }
    stopManagedSessionHeartbeat(sessionId);
    stopCodexPermissionPoller(sessionId);
    sessionProcessCache.delete(sessionId);
    resumeInFlight.delete(sessionId);
    resumeInFlightStarted.delete(sessionId);
  }

  // Last-resort sweep of anything still standing locally: a second pane for this
  // session, or an idle pre-warmed agent that outlived the in-memory
  // startedSessionTmux map (e.g. across a daemon restart) and has no live process
  // for findSessionProcess to match — the lookups above all miss it, yet its tmux
  // is right there under the derived name. Ownership-independent, so it is also
  // what the owner-skip path in executeRemoteCommand runs on its own.
  if (await killLocalPanesForConversation(conversationId, sessionId, "REMOTE") > 0 && !result) {
    result = "killed_tmux";
  }

  // A kill is a clean slate. Wipe per-session/per-conversation caches that
  // would otherwise block a subsequent resume or silently suppress the next
  // injected message.
  await clearConversationDeliveryAndResumeState(conversationId, sessionId, "REMOTE");

  if (!result) result = sessionId ? "no_process" : "no_session";
  return { result, error };
}

async function executeRemoteCommand(
  commandId: string,
  command: string,
  config: Config,
  commandArgs?: string
): Promise<void> {
  const siteUrl = config.convex_url?.replace(".cloud", ".site");
  if (!siteUrl || !config.auth_token) return;

  let result: string | undefined;
  let error: string | undefined;

  // Single-owner guard: skip session-targeted commands for conversations owned
  // by ANOTHER LIVE device (local peer OR a remote Mac the session was moved to).
  // Both daemons poll the same user-scoped command queue and moveSessionToDevice
  // enqueues an UNtargeted resume_session, so without this the non-owner daemon
  // races the owner — e.g. after a move-to-remote the local daemon would resume a
  // local copy and answer in parallel with the remote (split-brain). An OFFLINE
  // owner does NOT skip, so this daemon can reclaim a session whose owner died.
  const SESSION_COMMANDS = new Set(["resume_session", "fork_session", "kill_session", "send_keys", "escape", "rewind"]);
  if (SESSION_COMMANDS.has(command) && commandArgs && syncServiceRef) {
    try {
      const parsedArgs = JSON.parse(commandArgs);
      const convId = parsedArgs?.conversation_id;
      if (convId) {
        const info = await syncServiceRef.getConversationOwnerInfo(convId);
        if (ownedByAnotherLiveDevice(info)) {
          log(`[OWNER] skipping ${command} for ${String(convId).slice(0, 12)} — owned by live device ${info?.ownerDeviceId.slice(0, 8)}${info?.ownerIsRemote ? " (remote)" : ""} (not ${deviceId().slice(0, 8)})`);
          // …except a kill, which ALWAYS sweeps this machine's own panes first.
          // Routing the command to the owner is still right (it holds the rest of
          // the backends), but a pane physically here is only reachable from here:
          // deferring to the owner left owner-mismatched panes unkillable from
          // every device. The sweep is safe to run twice — it is has-session
          // guarded and idempotent — and the owner==local case never reaches it.
          if (command === "kill_session") {
            const sessionIdHint = typeof parsedArgs?.session_id === "string" && parsedArgs.session_id ? parsedArgs.session_id : undefined;
            const swept = await killLocalPanesForConversation(convId, sessionIdHint, "OWNER");
            // The owner runs the real teardown, but the local delivery/resume
            // caches are OURS and would otherwise survive the kill and suppress
            // (or resurrect) the next message. Always clear them — and always say
            // so: a silent swept-0 is indistinguishable from the command never
            // arriving, which is how this path stayed invisible.
            await clearConversationDeliveryAndResumeState(convId, sessionIdHint, "OWNER");
            log(swept > 0
              ? `[OWNER] kill_session for ${String(convId).slice(0, 12)} swept ${swept} local pane(s) and cleared in-flight resume state before deferring to the owner`
              : `[OWNER] kill_session for ${String(convId).slice(0, 12)} — no local panes; cleared in-flight resume state`);
          }
          return; // leave the rest of the command for the owner device
        }
      }
    } catch { /* on any error, fall through and execute (fail-open) */ }
  }

  try {
    switch (command) {
      case "status": {
        const state = readDaemonState();
        result = JSON.stringify({
          version: daemonVersion,
          platform,
          pid: process.pid,
          uptime: process.uptime(),
          autostart: isAutostartEnabled(),
          lastSync: state?.lastSyncTime,
          queueSize: state?.pendingQueueSize,
          stats: {
            messagesSynced: syncStats.messagesSynced,
            conversationsCreated: syncStats.conversationsCreated,
            activeSessions: syncStats.sessionsActive.size,
          },
        });
        log(`[REMOTE] Status requested, responding`);
        break;
      }
      case "version": {
        result = daemonVersion || "unknown";
        log(`[REMOTE] Version requested: ${result}`);
        break;
      }
      case "get_terminal_endpoint": {
        // The web's integrated terminal asks every live daemon for its
        // loopback endpoint, then connects to whichever answers on 127.0.0.1
        // — only the machine the browser is physically on is reachable, so
        // multi-device resolution falls out for free.
        result = JSON.stringify({
          port: hookServerPort,
          token: terminalToken,
          device_id: deviceId(),
          tmux: hasTmux(),
        });
        log(`[REMOTE] Terminal endpoint requested (port ${hookServerPort})`);
        break;
      }
      case "stream_pane": {
        // A browser on another machine wants to watch a pane here. It can't
        // reach the loopback PTY, so publish the pane's screen to the relay
        // instead, and take keystrokes back on the same request. It stops on
        // its own when the viewer's lease lapses; the lease is also what
        // authorizes input (packages/cli/src/terminal/paneStream.ts).
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const target = typeof parsed.target === "string" ? parsed.target : "";
        if (!isValidPaneTarget(target)) {
          error = `stream_pane: invalid target ${JSON.stringify(parsed.target)}`;
          break;
        }
        if (!hasTmux()) {
          error = "stream_pane: tmux is not installed on this machine";
          break;
        }
        const alreadyRunning = isPaneStreaming(target);
        startPaneStream(target, {
          log,
          push: async (msg) => {
            try {
              const res = await fetch(`${siteUrl}/cli/terminal/frame`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  api_token: config.auth_token,
                  device_id: deviceId(),
                  ...msg,
                }),
              });
              if (!res.ok) return null;
              return (await res.json()) as { stop: boolean; input?: string; fast?: boolean };
            } catch {
              return null;
            }
          },
        });
        result = JSON.stringify({ target, streaming: true, already: alreadyRunning });
        log(`[PANE] Streaming ${target} for a remote viewer${alreadyRunning ? " (already running)" : ""}`);
        break;
      }
      case "restart": {
        log(`[REMOTE] Restart requested`);
        result = "restarting";
        // Report result first, then restart
        await fetch(`${siteUrl}/cli/command-result`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            api_token: config.auth_token,
            command_id: commandId,
            result,
          }),
        });
        setTimeout(() => {
          restartDaemonProcess("remote restart command");
        }, 1000);
        return;
      }
      case "force_update": {
        const currentVersion = daemonVersion || "unknown";
        logLifecycle("update_start", `Remote update requested from v${currentVersion}`);
        result = "updating";
        // Report result first, then update
        await fetch(`${siteUrl}/cli/command-result`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            api_token: config.auth_token,
            command_id: commandId,
            result,
          }),
        });
        // Flush logs before update
        await flushRemoteLogs();
        setTimeout(async () => {
          const result = await performUpdate();
          if (result.success) {
            logLifecycle("update_complete", `Binary replaced from v${currentVersion}, restarting`);
            await flushRemoteLogs();
            restartDaemonProcess("remote update command");
          } else {
            logLifecycle("update_failed", `Update failed from v${currentVersion} error=${result.error}`);
            await flushRemoteLogs();
          }
        }, 1000);
        return;
      }
      case "reinstall": {
        const currentVersion = daemonVersion || "unknown";
        log(`[REMOTE] Reinstall requested from v${currentVersion}`);
        result = "reinstalling";
        await fetch(`${siteUrl}/cli/command-result`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ api_token: config.auth_token, command_id: commandId, result }),
        }).catch(() => {});
        await flushRemoteLogs();
        setTimeout(() => {
          try {
            execSync("curl -fsSL codecast.sh/install | sh", { timeout: 120000, stdio: "ignore" });
            logLifecycle("reinstall_complete", `Reinstalled from v${currentVersion}`);
          } catch (e) {
            logLifecycle("reinstall_failed", `Failed from v${currentVersion}: ${e instanceof Error ? e.message : String(e)}`);
          }
          flushRemoteLogs().finally(() => {
            setTimeout(() => process.exit(0), 500);
          });
        }, 1000);
        return;
      }
      case "run_workflow": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const workflowRunId = parsed.workflow_run_id;
        if (!workflowRunId) {
          error = "Missing workflow_run_id";
          break;
        }

        let projectPath = process.env.HOME || "/tmp";
        try {
          const resp = await fetch(`${siteUrl}/cli/workflow-runs/get`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ api_token: config.auth_token, run_id: workflowRunId }),
          });
          const data = await resp.json() as any;
          if (data.run?.project_path) {
            const vp = validatePath(data.run.project_path);
            if (vp) projectPath = vp;
          }
        } catch {}

        const shortId = workflowRunId.slice(-6);
        const tmuxSession = `wf-${shortId}`;

        if (!hasTmux()) {
          error = "tmux is not installed";
          break;
        }

        const { cmd: castCmd, prefixArgs: castPrefix } = resolveCastInvocation();
        const castBin = [castCmd, ...castPrefix].join(" ");
        const cmdText = `${castBin} workflow run-daemon ${workflowRunId}`;

        try {
          tmuxExecSync(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", tmuxSession, "-c", projectPath], { timeout: 5000 });
          tmuxExecSync(["send-keys", "-t", tmuxSession, "-l", cmdText], { timeout: 5000 });
          tmuxExecSync(["send-keys", "-t", tmuxSession, "Enter"], { timeout: 5000 });
          result = JSON.stringify({ tmux_session: tmuxSession, workflow_run_id: workflowRunId });
          log(`[REMOTE] Started workflow run ${workflowRunId} in tmux: ${tmuxSession}`);
        } catch (spawnErr) {
          error = `Failed to start workflow: ${spawnErr instanceof Error ? spawnErr.message : String(spawnErr)}`;
        }
        break;
      }
      case "start_session": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const rawAgentType = parsed.agent_type;
        // Registry-driven normalization (accepts either the convex spelling or the
        // client id; unknown/claude → "claude"). Replaces a hand-rolled ternary that
        // silently downgraded any client it didn't enumerate (e.g. opencode) to claude.
        const agentType: AgentClientId = fromConvexAgentType(rawAgentType);
        const rawPath: string = parsed.project_path || process.env.HOME || "/tmp";
        const conversationId: string | undefined = parsed.conversation_id;
        const expectedSessionId: string | undefined = parsed.session_id;
        const isolated: boolean = parsed.isolated === true;
        const worktreeName: string | undefined = parsed.worktree_name;
        // Per-session launch overrides from the web picker (shared-contract
        // option key + effort level). Unknown values are dropped here, never
        // passed through to the CLI.
        const requestedModelKey: string | undefined = typeof parsed.model === "string" ? parsed.model : undefined;
        const requestedEffort: string | undefined = typeof parsed.effort === "string" ? parsed.effort : undefined;
        // Per-session Claude account: a saved profile whose setup-token file is
        // sourced into this launch's env, so the session runs on that account
        // while the keychain login (and every other session) stays put.
        // Validated by name shape here; a missing token file is logged and the
        // launch falls back to the keychain (see accountSourcePrefix).
        const requestedAccount: string | undefined =
          agentType === "claude" && typeof parsed.cc_account === "string" && /^[a-z0-9][a-z0-9._-]{0,40}$/i.test(parsed.cc_account)
            ? parsed.cc_account
            : undefined;
        // Per-session stable-context prefs from the new-session page. Same
        // ride-along contract as model/effort: unknown values dropped here.
        const stablePrefs: StableLaunchPrefs = {
          ...(parsed.stable_mode === "team" || parsed.stable_mode === "solo" || parsed.stable_mode === "off"
            ? { stable_mode: parsed.stable_mode }
            : {}),
          ...(Array.isArray(parsed.stable_exclude)
            ? { stable_exclude: parsed.stable_exclude.filter((x: unknown): x is string => typeof x === "string" && /^[a-z0-9-]+$/i.test(x)) }
            : {}),
        };

        // A blank-project start (quick-create) defaults to $HOME — fine on the
        // user's own Mac, wrong on a remote box (the session would mislabel as
        // /Users/<remote-user> and run outside any checkout). The local fleet
        // serves these; a remote only runs starts that name a real project.
        if (!parsed.project_path && isRemoteDevice()) {
          log(`[REMOTE] start_session: blank project on a remote device — staying silent`);
          break;
        }

        // A conversation on the fenced execution rail (or quiescing onto it)
        // gets its runtime exclusively from the execution coordinator. This
        // legacy channel spawning one anyway would be a second, unmanaged
        // runtime beside the coordinator's binding — the split-brain the fence
        // exists to prevent. The gate re-checks at delivery time because a
        // start_session enqueued BEFORE the fence transition can arrive after.
        if (conversationId && syncServiceRef) {
          const protocolState = (await syncServiceRef.getProjectInfo(conversationId).catch(() => null))
            ?.execution_protocol_state;
          if (protocolState) {
            log(`start_session refused: conversation ${conversationId} is ${protocolState} — runtime is coordinator-owned`);
            break;
          }
        }

        const shortId = Math.random().toString(36).slice(2, 8);
        // Deterministic name keyed by conversation_id so kill/restart is a single
        // `tmux kill-session -t cc-<agent>-<convId>` with no lookup tables involved.
        const convSuffix = conversationId ? conversationId.slice(-12) : shortId;
        const tmuxSession = `cc-${agentType}-${convSuffix}`;

        // Assign claude's session id up front. `claude --session-id <uuid>` writes
        // its transcript to <uuid>.jsonl, so the daemon knows the JSONL path before
        // the process starts — no filesystem/process discovery, no cwd-based
        // matching, no hijack races. Reuse a caller-supplied id only if it's a real
        // UUID (the conversation_id is not), otherwise mint one.
        const assignedClaudeSessionId =
          agentType === "claude"
            ? (expectedSessionId && CLAUDE_UUID_RE.test(expectedSessionId) ? expectedSessionId : randomUUID())
            : undefined;

        // Resolve a usable local cwd. If `rawPath` doesn't exist on this
        // machine (conversation came from another host or was forked from
        // someone else's session), look up a local checkout for the same
        // git_remote_url. Refuse to start the session if no local checkout
        // exists — silently falling back to $HOME hides the problem and
        // makes the user's messages land in a totally wrong agent context.
        let cwd: string;
        const validatedRaw = validatePath(rawPath);
        if (validatedRaw) {
          cwd = validatedRaw;
        } else if (conversationId && syncServiceRef) {
          const projectInfo = await syncServiceRef.getProjectInfo(conversationId).catch(() => null);
          const recordedRoot = projectInfo?.git_root ?? null;
          let resolved = await resolveLocalProjectPath({
            projectPath: projectInfo?.project_path ?? rawPath,
            gitRoot: recordedRoot,
            gitRemoteUrl: projectInfo?.git_remote_url ?? null,
            findCandidates: (url) => syncServiceRef!.findLocalCheckouts(url).catch(() => []),
          });
          // Fallback mirroring the resume path (resolveResumeCwd): when the
          // git-remote lookup can't place the session — no remote recorded, or
          // the remote string differs across machines (SSH vs HTTPS) so the
          // exact-match candidate query misses — fall back to the
          // user/learned/convention resolver. Key it on the REPO ROOT so its
          // basename is the repo name (not a leaf subdir like "outreach"), then
          // re-append the in-repo subpath. start_session lacked this step, so a
          // foreign recorded path that resume could repair still refused here.
          if (!resolved) {
            // Seed with the recorded git_root only when rawPath lives under it
            // (conventionSeed): a root stamped off an unrelated conversation
            // that exists locally would otherwise win verbatim and launch the
            // session in the wrong repo.
            const rootSeed = conventionSeed(rawPath, recordedRoot);
            const localRepoRoot = resolveLocalRepo(rootSeed);
            if (localRepoRoot) {
              const subpath = rootSeed !== rawPath ? rawPath.slice(rootSeed.length) : "";
              const full = subpath ? path.join(localRepoRoot, subpath) : localRepoRoot;
              const placed = validatePath(full) ?? localRepoRoot;
              resolved = { path: placed, remapped: true, reason: `convention-resolved ${rawPath} → ${placed}` };
            }
          }
          if (!resolved) {
            // Don't clobber a session another device already owns. With device
            // routing this daemon shouldn't even receive a start_session it can't
            // run, but if it does (untargeted broadcast fallback), the machine
            // that actually has the checkout wins — we stay silent rather than
            // stamping a bogus "clone it first" banner over a live session.
            const owner = await syncServiceRef.getConversationOwner(conversationId).catch(() => null);
            if (owner && owner !== deviceId()) {
              log(`[REMOTE] start_session: no local checkout, but ${String(conversationId).slice(0, 12)} is owned by ${owner.slice(0, 8)} — staying silent`);
              break;
            }
            const remote = projectInfo?.git_remote_url ?? null;
            // Nothing to clone, nothing to point at → clear any stale banner and
            // stay silent. (Same rule as refuseResumeNoLocalCheckout.)
            if (!noLocalCheckoutBannerActionable({ remote, recordedPath: rawPath })) {
              syncServiceRef.setSessionError(conversationId).catch(() => {});
              log(`[REMOTE] start_session: no local checkout and no remote/path to act on — staying silent (cleared any stale banner)`);
              break;
            }
            error = `No local checkout for ${remote ?? "<unknown remote>"} (recorded path ${rawPath} doesn't exist here). Clone it first.`;
            log(`[REMOTE] start_session refused: ${error}`);
            syncServiceRef.setSessionError(conversationId, error).catch(() => {});
            break;
          }
          cwd = resolved.path;
          if (resolved.remapped) {
            log(`[REMOTE] start_session remapped path: ${resolved.reason}`);
          }
        } else {
          error = `Project path ${rawPath} doesn't exist`;
          log(`[REMOTE] start_session refused: ${error}`);
          break;
        }

        // Atomic pre-spawn claim: this daemon has resolved a runnable cwd, so now
        // race for ownership BEFORE spawning. Targeted commands already own the
        // conversation (no-op win). For a broadcast start_session (target couldn't
        // be resolved → every daemon with the checkout reaches here), Convex
        // serializes the claim so exactly one daemon wins; the losers skip,
        // preventing a double-spawn across machines.
        if (conversationId && syncServiceRef) {
          const claim = await syncServiceRef.claimConversationForStart(conversationId);
          if (!claim.won) {
            log(`[REMOTE] start_session: ${String(conversationId).slice(0, 12)} owned by ${claim.owner?.slice(0, 8) ?? "another live device"} — skipping spawn`);
            break;
          }
        }

        // One backend per conversation. A cross-agent reconfigure (Codex<->Claude)
        // or a same-agent restart enqueues a fresh start_session; tear down whatever
        // backend is currently bound BEFORE spawning so the prior agent's app-server
        // thread or tmux can't keep answering in parallel (the split-brain that
        // strands the first user turn and orphans a welcome-screen pane). This is
        // agent-agnostic, so it also clears stale delivery/resume state for the
        // Codex path, which previously only the tmux path did.
        if (conversationId) {
          const torn = await teardownConversationBackendsLive(conversationId, { interruptActiveTurn: true });
          // Reset delivery/resume state only when a live backend was actually
          // torn down (a real reconfigure/restart). A brand-new conversation
          // (cast spawn) has nothing to tear down, and its FIRST message is
          // typically already in flight waiting for this very start_session to
          // register the tmux — wiping the in-flight/dedup state here let the
          // subscription re-process that message and inject the briefing twice
          // (ct-40212 incident, msg ns74720h).
          if (torn.killedAppServer || torn.killedTmux) {
            await clearConversationDeliveryAndResumeState(conversationId, undefined, "RECONFIG");
          }
        }

        let worktreeResult: WorktreeResult | null = null;

        if (isolated && cwd) {
          const gitRoot = (() => {
            try {
              return execSync("git rev-parse --show-toplevel", {
                cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "ignore"],
              }).trim();
            } catch { return null; }
          })();
          if (gitRoot) {
            const wtName = worktreeName || `session-${shortId}`;
            worktreeResult = await createWorktree(gitRoot, wtName);
            if (worktreeResult) {
              cwd = worktreeResult.worktreePath;
              log(`[WORKTREE] Created isolated worktree: ${worktreeResult.worktreeName} at ${cwd}`);
            } else {
              log(`[WORKTREE] Failed to create worktree, falling back to repo root`);
            }
          }
        }

        if (agentType === "codex" && codexAppServerInstance?.binaryMissing) {
          error = "Codex is not installed. Install it from https://codex.openai.com then restart your daemon.";
          if (conversationId) {
            syncServiceRef?.setSessionError(conversationId, error).catch(() => {});
          }
          break;
        }

        // `cast stable off` removes the Claude SessionStart hook, but the
        // new-session picker can opt one session back into Team/Solo. Install
        // the gated hook before spawning so its exported override is actually
        // consumed. Idempotent for machines already configured for stable mode.
        ensureStableHookForLaunch(agentType, config.stable_mode, stablePrefs);

        // Binary is a registry lookup; the per-client arg construction lives in
        // launchCommand.ts (buildLaunchArgs, unit-tested per client). The daemon
        // keeps the impure pieces: reading the config accessor + flag helpers, the
        // one-time codex-bypass notification, and the arg sanitizer.
        const binary = launchBinary(agentType, { warn: log });
        const requestedModelOpt = requestedModelKey ? findModelOption(agentType, requestedModelKey) : undefined;
        const { binaryArgs: rawLaunchArgs, notifyCodexBypass } = buildLaunchArgs({
          agentType,
          configuredArgs: getConfiguredAgentArgs(agentType, config),
          permFlags: getPermissionFlags(agentType, config),
          defaultFlags: getDefaultParamFlags(agentType as AgentClientId, config),
          modelAlias: requestedModelOpt?.cliAlias,
          requestedEffort,
          assignedClaudeSessionId,
          hasCodexPermissionMode: !!config.agent_permission_modes?.codex,
        });
        if (notifyCodexBypass) {
          const flagFile = path.join(CONFIG_DIR, ".codex-bypass-notified");
          if (!fs.existsSync(flagFile)) {
            fs.writeFileSync(flagFile, new Date().toISOString());
            if (conversationId) {
              syncServiceRef?.createSessionNotification({
                conversation_id: conversationId,
                type: "info" as any,
                title: "Codex running in full-access mode",
                message: "Codex is running without permission prompts by default. Configure with: cast config codex_args",
              }).catch(() => {});
            }
          }
        }
        let binaryArgs = sanitizeBinaryArgs(rawLaunchArgs);
        // Export the per-session stable-context choice (and the conversation id,
        // so the SessionStart hook records against it directly with no lookup
        // race). Values are validated above / Convex ids — shell-safe tokens.
        const stableEnvParts: string[] = [];
        if (stablePrefs.stable_mode) stableEnvParts.push(`${STABLE_ENV_MODE}=${stablePrefs.stable_mode}`);
        if (stablePrefs.stable_exclude?.length) stableEnvParts.push(`${STABLE_ENV_EXCLUDE}=${stablePrefs.stable_exclude.join(",")}`);
        if (conversationId && /^[a-z0-9]+$/i.test(conversationId)) stableEnvParts.push(`${STABLE_ENV_CONVERSATION_ID}=${conversationId}`);
        const stableEnv = stableEnvParts.length ? ` ${stableEnvParts.join(" ")}` : "";
        const envPrefix = worktreeResult
          ? `${AGENT_ENV_SCRUB} AGENT_RESOURCE_INDEX=${worktreeResult.portIndex}${stableEnv}`
          : `${AGENT_ENV_SCRUB}${stableEnv}`;
        // Managed provider keys (opencode/pi) are sourced from a 0600 file so the
        // key never lands in `ps`/the pane; "" when nothing is managed (pl-207).
        const keyPrefix = providerKeySourcePrefix(agentType, CONFIG_DIR);
        // Same file-not-argv rule for the per-session Claude account token.
        const accountPrefix = accountSourcePrefix(requestedAccount, log);
        // Launch through the disclaim wrapper so the agent is TCC
        // self-responsible: privacy prompts name the agent (its own signed
        // identity), not codecast/bun (see disclaim.ts). The wrapper execs
        // plain argv, which works here because envPrefix starts with `env`.
        let cmdText = `${accountPrefix}${keyPrefix}${disclaimPrefix()}${envPrefix} ${[binary, ...binaryArgs].join(" ")}`;

        let codexThreadId: string | null = null;
        const codexSkipApprovals = binaryArgs.includes("--full-auto") || binaryArgs.includes("--dangerously-bypass-approvals-and-sandbox");
        const codexApprovalPolicy: ApprovalPolicy = codexSkipApprovals ? "never" : "on-request";
        const activeCodexAppServer = codexAppServerInstance?.running
          ? codexAppServerInstance
          : null;
        if (agentType === "codex" && activeCodexAppServer) {
          try {
            const sandbox = codexSkipApprovals ? "danger-full-access" as const : "workspace-write" as const;
            const builtContext = await buildCodexStableContext(config, cwd, stablePrefs);
            const resp = await startCodexThreadThenRecordStableContext(
              () => activeCodexAppServer.threadStart({
                cwd,
                sandbox,
                approvalPolicy: codexApprovalPolicy,
                ...(builtContext ? { developerInstructions: builtContext.text } : {}),
                ...(requestedModelOpt?.cliAlias ? { model: requestedModelOpt.cliAlias } : {}),
                ...(requestedEffort && (CODEX_EFFORT_LEVELS as readonly string[]).includes(requestedEffort)
                  ? { config: { model_reasoning_effort: requestedEffort } }
                  : {}),
              }),
              builtContext && conversationId
                ? () => {
                    void recordStableContext(config, {
                      conversation_id: conversationId,
                      data: builtContext.data,
                    });
                  }
                : undefined,
            );
            codexThreadId = resp.thread.id;
            log(`[codex-app-server] pre-created thread ${codexThreadId.slice(0, 8)} (approvalPolicy=${codexApprovalPolicy})`);
          } catch (err) {
            log(`[codex-app-server] thread pre-create failed, falling back: ${err instanceof Error ? err.message : String(err)}`);
          }
        }

        if (agentType === "codex" && codexThreadId) {
          const resultObj: Record<string, any> = { agent_type: agentType, project_path: cwd, app_server_thread_id: codexThreadId };
          if (worktreeResult) {
            resultObj.worktree_name = worktreeResult.worktreeName;
            resultObj.worktree_branch = worktreeResult.worktreeBranch;
            resultObj.worktree_path = worktreeResult.worktreePath;
            resultObj.port_index = worktreeResult.portIndex;
          }
          result = JSON.stringify(resultObj);
          log(`[REMOTE] Started ${agentType} session via app-server: ${codexThreadId.slice(0, 8)} (cwd: ${cwd})`);
          if (conversationId) {
            const initialManagedSessionId = getInitialManagedSessionId(agentType, expectedSessionId, codexThreadId);
            registerAppServerConversation(conversationId, codexThreadId, { cwd, approvalPolicy: codexApprovalPolicy });
            // This device now owns and runs the session — claim it and clear any
            // stale "clone it first" error a different device may have left.
            syncServiceRef?.claimSession(conversationId).catch(logConvexFailure);
            if (initialManagedSessionId && syncServiceRef) {
              syncServiceRef.markSessionActive(conversationId).catch(logConvexFailure);
              syncServiceRef.registerManagedSession(initialManagedSessionId, process.pid, undefined, conversationId).catch(logConvexFailure);
              syncServiceRef.updateSessionAgentStatus(conversationId, "connected").catch(logConvexFailure);
              ensureManagedSessionHeartbeat(initialManagedSessionId);
            }
            log(`[codex-app-server] registered conv=${conversationId.slice(0, 12)} -> thread=${codexThreadId.slice(0, 8)}`);
          }
          break;
        }

        if (!hasTmux()) {
          error = "tmux is not installed";
          break;
        }

        try {
          // Kill-before-create makes start_session idempotent: clicking the folder
          // switcher repeatedly just keeps respawning into the latest cwd.
          if (conversationId) {
            // Belt-and-suspenders: also kill an untracked tmux that happens to use
            // this agent's deterministic name. The teardown above already handled
            // the tracked backend, started-session registry, and delivery state.
            try { await tmuxExec(["kill-session", "-t", tmuxSession]); } catch {}
          }
          tmuxExecSync(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", tmuxSession, "-c", cwd], { timeout: 5000 });
          // Tag the tmux so warm-restart can rebuild startedSessionTmux from `tmux ls`.
          if (conversationId) {
            await setTmuxSessionOption(tmuxSession, "@codecast_conversation_id", conversationId).catch(() => {});
          }
          await setTmuxSessionOption(tmuxSession, "@codecast_agent_type", agentType).catch(() => {});
          await setTmuxSessionOption(tmuxSession, "@codecast_project_path", cwd).catch(() => {});
          tmuxExecSync(["send-keys", "-t", tmuxSession, "-l", cmdText], { timeout: 5000 });
          tmuxExecSync(["send-keys", "-t", tmuxSession, "Enter"], { timeout: 5000 });
          const resultObj: Record<string, any> = { tmux_session: tmuxSession, agent_type: agentType, project_path: cwd };
          if (worktreeResult) {
            resultObj.worktree_name = worktreeResult.worktreeName;
            resultObj.worktree_branch = worktreeResult.worktreeBranch;
            resultObj.worktree_path = worktreeResult.worktreePath;
            resultObj.port_index = worktreeResult.portIndex;
          }
          result = JSON.stringify(resultObj);
          log(`[REMOTE] Started ${agentType} session in tmux: ${tmuxSession} (cwd: ${cwd})`);
          if (conversationId) {
            const initialManagedSessionId = assignedClaudeSessionId ?? getInitialManagedSessionId(agentType, expectedSessionId);
            startedSessionTmux.set(conversationId, {
              tmuxSession,
              projectPath: cwd,
              startedAt: Date.now(),
              agentType,
              sessionId: initialManagedSessionId,
              worktreeName: worktreeResult?.worktreeName,
              worktreeBranch: worktreeResult?.worktreeBranch,
              worktreePath: worktreeResult?.worktreePath,
            });
            log(`[REMOTE] Registered started session tmux for conversation ${conversationId.slice(0, 12)}`);
            // This device now owns and runs the session — claim it and clear any
            // stale "clone it first" error a different device may have left.
            syncServiceRef?.claimSession(conversationId).catch(logConvexFailure);
            if (initialManagedSessionId) {
              registerManagedStartedSession(conversationId, initialManagedSessionId, tmuxSession);
            }
            if (agentType === "claude") {
              // `--session-id <uuid>` makes the JSONL deterministically named and
              // ensures it lands in THIS conversation's tmux, so discovery
              // tmux-exact-matches it (no cwd-fallback hijack) and the server's
              // session_id already equals the uuid (no mismatch/overwrite). We do
              // NOT pre-register conversationCache here: that would let
              // deliverMessage resolve sessionId immediately and skip the
              // readiness-gated started-tmux path, injecting the first message
              // into a still-booting prompt. Let discovery/the watcher link it.
              discoverAndLinkSession(conversationId, tmuxSession, cwd).catch(err => {
                log(`Session discovery failed for ${conversationId.slice(0, 12)}: ${err}`);
              });
            }
          }
        } catch (spawnErr) {
          error = `Failed to start session: ${spawnErr instanceof Error ? spawnErr.message : String(spawnErr)}`;
          log(`[REMOTE] start_session error: ${error}`);
        }
        break;
      }
      case "escape": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const conversationId = parsed.conversation_id;
        if (!conversationId) {
          error = "Missing conversation_id";
          break;
        }

        const escapeThreadId = appServerConversations.get(conversationId);
        if (escapeThreadId && codexAppServerInstance?.running) {
          const activeTurnId = findActiveTurnForThread(escapeThreadId);
          if (activeTurnId) {
            await codexAppServerInstance.turnInterrupt(escapeThreadId, activeTurnId);
            result = "escape_interrupted";
            log(`[REMOTE] Interrupted app-server turn ${activeTurnId.slice(0, 8)} on thread ${escapeThreadId.slice(0, 8)}`);
          } else {
            result = "escape_no_active_turn";
            log(`[REMOTE] No active turn to interrupt on app-server thread ${escapeThreadId.slice(0, 8)}`);
          }
          break;
        }

        const cache = readConversationCache();
        const reverse = buildReverseConversationCache(cache);
        const sessionId = reverse[conversationId];
        if (!sessionId) {
          error = `No session found for conversation ${conversationId}`;
          break;
        }
        const { tmuxTarget, proc } = await resolveSessionCommandPane(conversationId, sessionId, detectSessionAgentType(sessionId));
        if (tmuxTarget) {
          await tmuxExec(["send-keys", "-t", tmuxTarget, "Escape", "Escape"]);
          result = "escape_sent";
          log(`[REMOTE] Sent double Escape to session ${sessionId.slice(0, 8)} via tmux ${tmuxTarget}`);
        } else if (!proc) {
          error = `No running process for session ${sessionId.slice(0, 8)}`;
        } else if (!MID_TURN_AGENT_STATUSES.has(lastHookStatus.get(sessionId)?.status ?? "")) {
          // A SIGINT reaching claude at its prompt EXITS the process (observed
          // 2026-08-28: pid 41092 died on an escape sent to an idle session). The
          // signal is only an interrupt while a turn is running; otherwise there is
          // nothing to interrupt and the honest answer is a no-op.
          result = "escape_no_active_turn";
          log(`[REMOTE] No active turn to interrupt for session ${sessionId.slice(0, 8)} (no tmux pane, skipping SIGINT)`);
        } else {
          try {
            process.kill(proc.pid, "SIGINT");
            result = "escape_sent_sigint";
            log(`[REMOTE] Sent SIGINT to session ${sessionId.slice(0, 8)} pid=${proc.pid}`);
          } catch (killErr) {
            error = `Failed to send SIGINT to pid ${proc.pid}: ${killErr}`;
          }
        }
        break;
      }
      case "rewind": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const conversationId = parsed.conversation_id;
        const stepsBack = parsed.steps_back;
        if (!conversationId || stepsBack === undefined || stepsBack < 1) {
          error = "Missing conversation_id or invalid steps_back";
          break;
        }
        const cache = readConversationCache();
        const reverse = buildReverseConversationCache(cache);
        const sessionId = reverse[conversationId];
        if (!sessionId) {
          error = `No session found for conversation ${conversationId}`;
          break;
        }
        const agentType = detectSessionAgentType(sessionId);
        if (agentType !== "claude") {
          error = `Rewind not yet supported for ${agentType} sessions`;
          break;
        }
        const { tmuxTarget, proc } = await resolveSessionCommandPane(conversationId, sessionId, agentType);
        if (!proc && !tmuxTarget) {
          error = `No running process for session ${sessionId.slice(0, 8)}`;
          break;
        }
        if (!tmuxTarget) {
          error = `No tmux pane found for session ${sessionId.slice(0, 8)}`;
          break;
        }

        const safeSteps = Math.min(Math.max(1, Math.floor(Number(stepsBack))), 50);

        const PROMPT_RE = /[❯›]/;
        const BUSY_RE = /⠋|⠙|⠹|⠸|⠼|⠴|⠦|⠧|⠇|⠏|Wandering|Vibing|Coasting|Working|thinking/;
        const NAVIGATOR_RE = /Enter to continue/;
        const RESTORE_RE = /Restore conversation/;

        const captureLast = async (): Promise<string> => {
          const { stdout } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmuxTarget, "-S", "-8"]);
          return stdout.split("\n").slice(-15).join("\n");
        };

        const isAtPrompt = async (): Promise<boolean> => {
          const last = await captureLast();
          return PROMPT_RE.test(last) && !BUSY_RE.test(last);
        };

        const waitFor = async (test: (text: string) => boolean, label: string, maxWait = 10000): Promise<boolean> => {
          const start = Date.now();
          while (Date.now() - start < maxWait) {
            const last = await captureLast();
            if (test(last)) return true;
            await new Promise(r => setTimeout(r, 300));
          }
          log(`[REWIND] Timed out waiting for: ${label}`);
          return false;
        };

        // Step 1: Get to idle prompt (double Escape to interrupt if busy)
        if (!(await isAtPrompt())) {
          log(`[REWIND] Session not at prompt, sending double Escape to interrupt`);
          await tmuxExec(["send-keys", "-t", tmuxTarget, "Escape", "Escape"]);
          const gotPrompt = await waitFor(
            (text) => PROMPT_RE.test(text) && !BUSY_RE.test(text),
            "prompt after interrupt",
            30000,
          );
          if (!gotPrompt) {
            error = "Timed out waiting for prompt after interrupt";
            break;
          }
          log(`[REWIND] Got prompt after interrupt`);
        }

        // Step 2: Clear any existing text (double Escape clears in CC)
        log(`[REWIND] Clearing prompt with double Escape`);
        await tmuxExec(["send-keys", "-t", tmuxTarget, "Escape", "Escape"]);
        await new Promise(r => setTimeout(r, 300));

        // Step 3: Navigate history with Up arrows
        // First Up opens the visual navigator, subsequent Ups move back
        log(`[REWIND] Sending ${safeSteps} Up arrows to open navigator`);
        const upKeys = Array.from({ length: safeSteps }, () => "Up");
        await tmuxExec(["send-keys", "-t", tmuxTarget, ...upKeys]);

        // Step 4: Verify navigator opened
        const navigatorOpened = await waitFor(
          (text) => NAVIGATOR_RE.test(text),
          "navigator to open",
        );
        if (!navigatorOpened) {
          log(`[REWIND] Navigator did not open after ${safeSteps} Up arrows`);
          error = `No message found at history position ${safeSteps}`;
          break;
        }

        // Step 5: Select message in navigator (first Enter)
        log(`[REWIND] Selecting message in navigator`);
        await tmuxExec(["send-keys", "-t", tmuxTarget, "Enter"]);

        // Step 6: Confirm "Restore conversation" (second Enter)
        const atRestore = await waitFor(
          (text) => RESTORE_RE.test(text),
          "restore confirmation",
        );
        if (atRestore) {
          log(`[REWIND] Confirming restore`);
          await tmuxExec(["send-keys", "-t", tmuxTarget, "Enter"]);
        } else {
          log(`[REWIND] No restore confirmation shown, sending Enter anyway`);
          await tmuxExec(["send-keys", "-t", tmuxTarget, "Enter"]);
        }

        // Wait for forked session prompt with the rewound message pre-filled
        // Don't submit — let the user review/edit the message in the web UI
        await waitFor(
          (text) => PROMPT_RE.test(text) && !BUSY_RE.test(text),
          "prompt with rewound message",
          15000,
        );

        result = "rewind_sent";
        log(`[REWIND] Rewind ${stepsBack} steps sent to session ${sessionId.slice(0, 8)}`);
        break;
      }
      case "send_keys": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const conversationId = parsed.conversation_id;
        const keys = parsed.keys;
        if (!conversationId || !keys) {
          error = "Missing conversation_id or keys";
          break;
        }
        const ALLOWED_KEYS = new Set(["BTab", "Escape", "Enter", "Tab", "Up", "Down", "Left", "Right", "Space", "BSpace"]);
        const keyList = keys.split(" ");
        const invalidKey = keyList.find((k: string) => !ALLOWED_KEYS.has(k));
        if (invalidKey) {
          error = `Key '${invalidKey}' not in allowlist`;
          break;
        }
        let sessionId: string | undefined;
        {
          const cache = readConversationCache();
          const reverse = buildReverseConversationCache(cache);
          sessionId = reverse[conversationId];
        }
        if (!sessionId) {
          for (let i = 0; i < 10; i++) {
            await new Promise(r => setTimeout(r, 500));
            const freshCache = readConversationCache();
            const freshReverse = buildReverseConversationCache(freshCache);
            sessionId = freshReverse[conversationId];
            if (sessionId) break;
          }
        }
        if (!sessionId) {
          error = `No session found for conversation ${conversationId}`;
          break;
        }
        const { tmuxTarget, proc } = await resolveSessionCommandPane(conversationId, sessionId, detectSessionAgentType(sessionId));
        if (!proc && !tmuxTarget) {
          error = `No running process for session ${sessionId.slice(0, 8)}`;
          break;
        }
        if (tmuxTarget) {
          const groups: string[][] = [];
          for (const k of keyList) {
            if (k === "Escape" || k === "Enter" || (groups.length > 0 && k !== groups[groups.length - 1][0])) {
              groups.push([k]);
            } else if (groups.length === 0) {
              groups.push([k]);
            } else {
              groups[groups.length - 1].push(k);
            }
          }
          for (let i = 0; i < groups.length; i++) {
            if (i > 0) {
              const prevKey = groups[i - 1][0];
              const needsDelay = prevKey === "Escape" || prevKey === "Enter";
              await new Promise((r) => setTimeout(r, needsDelay ? 600 : 150));
            }
            await tmuxExec(["send-keys", "-t", tmuxTarget, ...groups[i]]);
          }
          result = "keys_sent";
          log(`[REMOTE] Sent ${keys} (${groups.length} groups) to session ${sessionId.slice(0, 8)} via tmux ${tmuxTarget}`);
        } else {
          error = `No tmux pane found for session ${sessionId.slice(0, 8)}`;
        }
        break;
      }
      case "kill_session": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const conversationId = parsed.conversation_id;
        if (!conversationId) {
          error = "Missing conversation_id";
          break;
        }
        const killed = await killConversationBackends(
          conversationId,
          typeof parsed.session_id === "string" && parsed.session_id ? parsed.session_id : undefined
        );
        result = killed.result;
        error = killed.error;
        break;
      }
      // "Update now" from the in-app banner: apply the published desktop release
      // immediately (force quit + swap + relaunch) instead of waiting for the
      // next app quit. Forced, so it stops a running app via SIGTERM/SIGKILL.
      case "desktop_update": {
        const applied = await checkForDesktopUpdate((msg) => log(msg), { force: true });
        if (applied) {
          result = "desktop_updated";
        } else {
          error = "no desktop update applied (already current, app not installed, or unavailable)";
        }
        break;
      }
      // Swap the machine's active Claude Code account to a saved profile, then
      // recycle the listed blocked sessions so they resume on the new account.
      // Order matters: kill BEFORE enqueueing the continues — a still-alive
      // claude process holds the old account's token in memory, so injecting
      // first would just re-hit the old account's limit. The pending "continue"
      // is what triggers the auto-resume that reads the fresh credential.
      case "switch_account": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const profile: string | undefined = typeof parsed.profile === "string" && parsed.profile ? parsed.profile : undefined;
        const conversationIds: string[] = Array.isArray(parsed.conversation_ids) ? parsed.conversation_ids : [];
        const sessionIds: Record<string, string> =
          parsed.session_ids && typeof parsed.session_ids === "object" ? parsed.session_ids : {};
        const sendContinue: boolean = parsed.continue_blocked !== false;
        // The web paints its "continue" bubble the moment the user clicks and
        // sends the client_id it painted with along the command. Enqueueing
        // under that id makes the server echo REPLACE that bubble instead of
        // adding a second one. Absent for server-initiated revives.
        const continueClientIds: Record<string, string> =
          parsed.client_ids && typeof parsed.client_ids === "object" ? parsed.client_ids : {};

        // save_as mode: snapshot the CURRENT login as a named profile (the web
        // Settings "save as profile" button). Pure save — no swap, no kills.
        if (typeof parsed.save_as === "string" && parsed.save_as) {
          try {
            const meta = saveProfile(parsed.save_as);
            result = JSON.stringify({ saved: meta.name, email: meta.email ?? null });
            log(`[ACCOUNTS] Saved active account as profile "${meta.name}"${meta.email ? ` (${meta.email})` : ""}`);
            // Push the refreshed profile inventory upstream now — the Settings
            // page is watching for it; don't make it wait a heartbeat cycle.
            sendHeartbeat().catch(() => {});
          } catch (err) {
            error = `Profile save failed: ${err instanceof Error ? err.message : String(err)}`;
          }
          break;
        }

        // remove mode: forget a saved profile (the web Settings remove
        // button). Pure deletion — no swap, no kills. deleteProfile guards the
        // active login (auto-enroll would resurrect it a heartbeat later).
        if (typeof parsed.remove === "string" && parsed.remove) {
          try {
            const meta = deleteProfile(parsed.remove);
            result = JSON.stringify({ removed: parsed.remove, email: meta.email ?? null });
            log(`[ACCOUNTS] Removed profile "${parsed.remove}"${meta.email ? ` (${meta.email})` : ""}`);
            // Confirm the shrunken inventory upstream now — the web already
            // hid the row optimistically and is waiting on this echo.
            sendHeartbeat().catch(() => {});
          } catch (err) {
            error = `Profile remove failed: ${err instanceof Error ? err.message : String(err)}`;
          }
          break;
        }

        // mint mode: mint a setup-token for the machine's current login (the
        // web toggle / "mint now"). Returns at once — the browser approval
        // outlives any command TTL — and the detached watcher reports the
        // outcome through reportMintFlow (see the MINT-FLOW block).
        if (typeof parsed.mint === "string" && parsed.mint) {
          try {
            result = await startMintFlow(parsed.mint, parsed.force === true);
          } catch (err) {
            error = `Mint launch failed: ${err instanceof Error ? err.message : String(err)}`;
            syncServiceRef?.reportMintFlow("rejected", parsed.mint, undefined, error).catch(() => {});
          }
          break;
        }

        let switched: string | null = null;
        if (profile) {
          try {
            const switchResult = useProfile(profile);
            switched = switchResult.to;
            log(`[ACCOUNTS] Switched CC account to "${profile}"${switchResult.toEmail ? ` (${switchResult.toEmail})` : ""}${switchResult.from ? `, re-saved outgoing as "${switchResult.from}"` : ""}`);
            // Remotes run on a pushed COPY of this credential — refresh them now
            // instead of waiting for the 30-min loop.
            pushCredentialToRemoteHosts("account_switch").catch(() => {});
            // Surface the new active account in Settings without waiting a beat.
            sendHeartbeat().catch(() => {});
          } catch (err) {
            // Don't tear anything down if the swap itself failed.
            error = `Account switch failed: ${err instanceof Error ? err.message : String(err)}`;
            break;
          }
        }

        let killed = 0;
        let continued = 0;
        for (const convId of conversationIds) {
          try {
            const out = await killConversationBackends(convId, sessionIds[convId]);
            if (out.result && out.result !== "no_process" && out.result !== "no_session") killed++;
          } catch (err) {
            log(`[ACCOUNTS] Teardown failed for ${String(convId).slice(0, 12)}: ${err instanceof Error ? err.message : String(err)}`);
          }
        }
        if (sendContinue && syncServiceRef) {
          for (const convId of conversationIds) {
            try {
              // client_id keyed by command id: re-running the command can't
              // double-queue, but a deliberate second switch still can.
              await syncServiceRef.enqueueUserMessage(
                convId,
                "continue",
                continueClientIds[convId] || `acct-switch-${commandId}-${convId}`,
              );
              continued++;
            } catch (err) {
              log(`[ACCOUNTS] Continue enqueue failed for ${String(convId).slice(0, 12)}: ${err instanceof Error ? err.message : String(err)}`);
            }
          }
        }
        result = JSON.stringify({ switched, killed, continued });
        log(`[ACCOUNTS] switch_account done: switched=${switched ?? "none"} killed=${killed}/${conversationIds.length} continued=${continued}`);
        break;
      }
      // Web sign-in CTA: run the browser OAuth flow via `claude auth login` and
      // report the outcome through completeLoginFlow (see the LOGIN-FLOW block).
      // Returns immediately — the flow takes as long as the user's browser
      // dance, far past any command TTL, so a detached watcher owns the rest.
      case "start_login": {
        if (isRemoteDevice()) {
          error = "Remote devices run a pushed copy of the primary's credential — sign in on the primary machine";
          break;
        }
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const email: string | undefined =
          typeof parsed.email === "string" && parsed.email ? parsed.email : undefined;
        try {
          result = await startLoginFlow(email, parsed.force === true);
        } catch (err) {
          error = `Sign-in launch failed: ${err instanceof Error ? err.message : String(err)}`;
          // The web is watching cc_login_flow, not command errors — report the
          // failure there too so the CTA comes back instead of spinning.
          syncServiceRef?.completeLoginFlow("rejected", email, error).catch(() => {});
        }
        break;
      }
      // fork_session = resume_session whose JSONL is materialized by the fork
      // fast path (parsed.fork_fast_path) before the normal resume pipeline
      // runs. A separate command name only for backward compat: daemons that
      // predate the fast path must no-op it, not resume-and-reconstitute.
      case "fork_session":
      case "resume_session": {
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const sessionId = parsed.session_id;
        const conversationId = parsed.conversation_id;
        if (!sessionId) {
          error = "Missing session_id";
          break;
        }
        // Fresh-session guard. If the conversation just had a session spawned
        // (startedSessionTmux still tracks it) and there's no linked Claude
        // session_id yet, an auto-resume from the UI's stuck-banner heuristic
        // will try `claude --resume <nanoid>` which can't succeed — the nanoid
        // is the optimistic id from the inline new-session flow, not a real
        // Claude UUID. We were churning through kill → repair → reconstitute
        // → start-fresh for every such call, racing the tryStartedTmux path
        // that was already about to deliver the user's first message.
        if (conversationId) {
          const startedEntry = startedSessionTmux.get(conversationId);
          if (startedEntry) {
            const cache = readConversationCache();
            const reverseCache = buildReverseConversationCache(cache);
            const linkedSessionId = reverseCache[conversationId];
            if (!linkedSessionId) {
              log(`[REMOTE] Skipping resume for ${sessionId.slice(0, 8)} — conversation ${conversationId.slice(0, 12)} has a freshly started tmux (${startedEntry.tmuxSession}) that hasn't been linked yet; tryStartedTmux will handle delivery.`);
              result = JSON.stringify({ skipped: true, reason: "fresh_session_unlinked" });
              break;
            }
          }
        }
        let projectPath = parsed.project_path;
        const forceReconstitute = parsed.force_reconstitute === true;
        // Set by reparentSessionToDevice (cast pull): this session may be running
        // on this machine for the first time, so its repo isn't checked out here.
        const reparented = parsed.reparented === true;
        // Registry-driven normalization; `undefined` means "claude / unspecified"
        // (the downstream `|| "claude"` fallbacks and the findSessionFile detection
        // path own that case). fromConvexAgentType handles both spellings and every
        // client (opencode, pi, ...); claude then collapses back to undefined to
        // preserve the original semantics.
        const normalizedResumeAgent = fromConvexAgentType(parsed.agent_type);
        const resumeAgentType: AgentClientId | undefined =
          normalizedResumeAgent === "claude" ? undefined : normalizedResumeAgent;
        // Skip if a resume is already in flight for this session
        if (resumeInFlight.has(sessionId)) {
          log(`[REMOTE] Resume already in flight for ${sessionId.slice(0, 8)}, skipping`);
          result = JSON.stringify({ skipped: true, reason: "resume_in_flight" });
          break;
        }
        if (conversationId) {
          const convFailures = conversationResumeFailures.get(conversationId);
          if (convFailures && convFailures.count >= CONVERSATION_RESUME_MAX_FAILURES) {
            if (Date.now() - convFailures.lastFailure < CONVERSATION_RESUME_COOLDOWN_MS) {
              log(`[REMOTE] Resume circuit breaker for conv=${conversationId.slice(0, 12)}: ${convFailures.count} failures, cooling down`);
              result = JSON.stringify({ skipped: true, reason: "circuit_breaker" });
              break;
            }
            conversationResumeFailures.delete(conversationId);
          }
        }
        // In-place agent switch: ignore the old transcript, rebuild as the
        // TARGET agent under a new native session id, rebind this conversation.
        // A live-pane reuse of the OLD agent would silently no-op the switch.
        if (parsed.switch_agent === true && conversationId) {
          const targetAgent: AgentClientId = resumeAgentType || "claude";
          log(`[REMOTE] Agent switch conv=${conversationId.slice(0, 12)} ${sessionId.slice(0, 8)} → ${targetAgent}`);
          restartingSessionIds.set(sessionId, Date.now());
          try {
            const cwd = projectPath
              ? await resolveResumeCwdOrRefuse({ recordedCwd: projectPath, cwdOverride: projectPath, conversationId })
              : null;
            if (!cwd) {
              await refuseResumeNoLocalCheckout(sessionId, conversationId, projectPath);
              error = "No local checkout for agent switch";
              break;
            }
            let switched = false;
            if (config?.convex_url && config?.auth_token && mayReconstituteResumeTranscript(targetAgent)) {
              try {
                const siteUrl = config.convex_url.replace(".cloud", ".site");
                const exportData = await fetchExport(siteUrl, config.auth_token, conversationId);
                if (exportData.messages.length > 0) {
                  let reconJsonl: string;
                  let newSessionId: string;
                  let reconFilePath: string;
                  if (targetAgent === "codex") {
                    ({ jsonl: reconJsonl, sessionId: newSessionId } = generateCodexJsonl(exportData));
                    ({ filePath: reconFilePath } = writeCodexSession(reconJsonl, newSessionId));
                  } else {
                    const tailMessages = chooseClaudeAutoTrim(exportData);
                    ({ jsonl: reconJsonl, sessionId: newSessionId } = generateClaudeCodeJsonl(exportData, { tailMessages }));
                    ({ filePath: reconFilePath } = writeClaudeCodeSession(reconJsonl, newSessionId, cwd));
                  }
                  setPosition(reconFilePath, fs.statSync(reconFilePath).size);
                  remapConversationSession(sessionId, newSessionId, conversationId);
                  void pushSessionIdBinding(conversationId, newSessionId, cwd);
                  const resumed = await autoResumeSession(
                    newSessionId, "", readTitleCache(), cwd, conversationId, targetAgent, USER_RESUME,
                  );
                  if (resumed) {
                    const cache = readConversationCache();
                    cache[newSessionId] = conversationId;
                    saveConversationCache(cache);
                    syncServiceRef?.markSessionActive(conversationId).catch(logConvexFailure);
                    conversationResumeFailures.delete(conversationId);
                    await clearConversationDeliveryAndResumeState(conversationId, newSessionId, "agent_switch");
                    result = JSON.stringify({ switched: true, session_id: newSessionId, agent_type: targetAgent });
                    log(`[REMOTE] Agent switch reconstituted ${sessionId.slice(0, 8)} → ${newSessionId.slice(0, 8)} (${targetAgent})`);
                    switched = true;
                  }
                }
              } catch (switchErr) {
                log(`[REMOTE] Agent switch reconstitution failed: ${switchErr instanceof Error ? switchErr.message : String(switchErr)}`);
              }
            }
            if (!switched) {
              error = `Failed to switch session ${sessionId.slice(0, 8)} to ${targetAgent}`;
            }
          } finally {
            restartingSessionIds.delete(sessionId);
          }
          break;
        }
        // opencode API fork. The parent's real ses_ id rode down in
        // parsed.parent_session_id (forkFromMessage). The session_id here is the
        // synthetic forked-<id> placeholder — it can't resolve in opencode.db, so
        // we mint a REAL forked ses_ via the serve sidecar, rebind this conversation
        // onto it, and resume THAT. The convex copy (advanceForkCopy) already gave
        // the fork its history; the sidecar fork just makes it a live, resumable
        // opencode session. On any failure we log the reason and fall through to the
        // generic path (blank spawn) — never a silent claim that a fork happened.
        if (
          resumeAgentType === "opencode" &&
          parsed.fork_api === true &&
          conversationId &&
          typeof parsed.parent_session_id === "string" &&
          parsed.parent_session_id !== sessionId &&
          AGENT_CLIENTS.opencode.capabilities.forkApi === true
        ) {
          // Idempotency: the dispatch outbox is at-least-once, so a redelivered fork
          // command must not mint a SECOND fork. If this conversation is already
          // bound to a real ses_ id, the fork already happened — re-resume that id
          // (autoResumeSession no-ops on a live pane) instead of forking again.
          const reverseCache = buildReverseConversationCache(readConversationCache());
          const boundReal = reverseCache[conversationId];
          let realForkId: string | null =
            typeof boundReal === "string" && boundReal.startsWith("ses_") ? boundReal : null;

          if (!realForkId) {
            const sidecar = await ensureOpencodeServer(config);
            if (!sidecar) {
              log(`[REMOTE] opencode fork for conv ${conversationId.slice(0, 12)}: serve sidecar unavailable — falling back to blank spawn`);
            } else {
              try {
                // fork_message_id (partial forks) truncates to match the convex copy;
                // omitted at tip = a full fork. See forkFromMessage.
                const forkMessageId = typeof parsed.fork_message_id === "string" ? parsed.fork_message_id : undefined;
                const forked = await sidecar.fork(parsed.parent_session_id, forkMessageId ? { messageID: forkMessageId } : {});
                realForkId = forked.id;
                // Map real id → conversation BEFORE the watcher sees it (else it
                // mints a doppelgänger), point convex at the real id, and baseline
                // the watcher past the copied history (opencode re-mints message
                // ids on fork, so re-syncing would duplicate).
                const cache = readConversationCache();
                cache[realForkId] = conversationId;
                saveConversationCache(cache);
                if (conversationCacheRef) conversationCacheRef[realForkId] = conversationId;
                seedOpencodeForkSyncBaseline(realForkId);
                const forkGitInfo = projectPath ? await getGitInfo(projectPath) : undefined;
                void pushSessionIdBinding(conversationId, realForkId, projectPath || undefined, forkGitInfo?.repoRoot || forkGitInfo?.root);
                log(`[REMOTE] opencode fork: ${parsed.parent_session_id.slice(0, 12)} → ${realForkId.slice(0, 12)} for conv ${conversationId.slice(0, 12)}`);
              } catch (forkErr) {
                log(`[REMOTE] opencode fork failed for conv ${conversationId.slice(0, 12)}: ${forkErr instanceof Error ? forkErr.message : String(forkErr)} — falling back to blank spawn`);
              }
            }
          }

          if (realForkId) {
            restartingSessionIds.set(realForkId, Date.now());
            const resumed = await autoResumeSession(realForkId, "", readTitleCache(), projectPath, conversationId, "opencode", USER_RESUME);
            restartingSessionIds.delete(realForkId);
            if (resumed) {
              syncServiceRef?.markSessionActive(conversationId).catch(logConvexFailure);
              conversationResumeFailures.delete(conversationId);
              await clearConversationDeliveryAndResumeState(conversationId, realForkId, "opencode_fork");
              result = JSON.stringify({ forked: true, session_id: realForkId });
              log(`[REMOTE] opencode fork ${realForkId.slice(0, 12)} resumed for conv ${conversationId.slice(0, 12)}`);
            } else {
              error = `opencode fork ${realForkId.slice(0, 12)} resume failed`;
            }
            break; // fork committed — do NOT also blank-spawn a second session
          }
          // No real fork id (sidecar unavailable or fork threw): fall through to the
          // generic path below, which blank-spawns opencode with the copied history.
        }
        // Fork fast path: materialize the new session's JSONL by copying the
        // parent's local transcript (byte-stable message content → Claude's
        // prompt cache stays warm), then let the normal resume pipeline take
        // it from there. Emitted by forkFromMessage the moment the fork is
        // created — the server-side message copy runs in parallel.
        if (parsed.fork_fast_path && parsed.parent_session_id && parsed.parent_session_id !== sessionId
            && !findSessionFile(sessionId)) {
          let copied = false;
          const parentFile = findSessionFile(parsed.parent_session_id);
          if (parentFile && parentFile.agentType === "claude") {
            try {
              const newPath = copyJsonlAsSession(parentFile.path, parsed.parent_session_id, sessionId);
              if (newPath) {
                // The server copy populates the fork conversation; start the
                // watcher at EOF so the copied history isn't re-ingested.
                setPosition(newPath, fs.statSync(newPath).size);
                // Map session → conversation BEFORE the watcher can see the
                // file, or it mints a doppelgänger conversation for it.
                if (conversationId) {
                  const cache = readConversationCache();
                  cache[sessionId] = conversationId;
                  saveConversationCache(cache);
                  if (conversationCacheRef) conversationCacheRef[sessionId] = conversationId;
                }
                copied = true;
                log(`[REMOTE] Fork fast path: copied parent JSONL ${parsed.parent_session_id.slice(0, 8)} → ${sessionId.slice(0, 8)}`);
              }
            } catch (copyErr) {
              log(`[REMOTE] Fork fast path copy failed for ${sessionId.slice(0, 8)}: ${copyErr instanceof Error ? copyErr.message : String(copyErr)}`);
            }
          }
          if (!copied && parsed.fork_fast_path_strict) {
            // Parent transcript isn't on this machine. Do NOT fall through to
            // reconstitution — the server-side message copy may still be in
            // flight and would rebuild a truncated history. The deferred
            // command emitted at copy completion handles this fork instead.
            log(`[REMOTE] Fork fast path unavailable for ${sessionId.slice(0, 8)} (no local parent transcript), deferring to post-copy resume`);
            result = JSON.stringify({ skipped: true, reason: "fork_fast_path_unavailable" });
            break;
          }
        }
        restartingSessionIds.set(sessionId, Date.now());
        // Reparented onto this machine: ensure the repo is checked out locally
        // (clone if missing) BEFORE resolving the resume cwd, so the resume and
        // its reconstruct-from-Convex JSONL write have a real directory. If no
        // checkout can be prepared, fall through — the normal resolution then
        // surfaces the "clone it first" banner as usual.
        // Where the session ran before this machine — captured before the
        // reparent checkout repoints projectPath, so the notice can name it.
        const priorCwd = projectPath;
        let reparentCheckout: ReparentedCheckout | undefined;
        if (reparented) {
          reparentCheckout = await ensureReparentedCheckout(conversationId, projectPath, parsed.git_remote_url);
          if (reparentCheckout) {
            projectPath = reparentCheckout.path;
            log(`[REPARENT] ${sessionId.slice(0, 8)} resuming in ${reparentCheckout.cloned ? "fresh clone" : "existing checkout"} ${reparentCheckout.path}${reparentCheckout.branch ? ` on branch ${reparentCheckout.branch}` : ""}`);
          }
        }
        if (resumeAgentType === "codex" && (parsed.fork === true || forceReconstitute) && conversationId) {
          try {
            const activeCodexAppServer = codexAppServerInstance?.running ? codexAppServerInstance : null;
            if (!activeCodexAppServer) {
              throw new Error("Codex app-server is unavailable; cannot import fork history");
            }
            const exportData = await fetchExport(siteUrl, config.auth_token!, conversationId);
            const recordedCwd = projectPath || exportData.conversation.project_path || exportData.conversation.git_root || undefined;
            const cwd = await resolveResumeCwdOrRefuse({ recordedCwd, cwdOverride: recordedCwd, conversationId });
            if (!cwd) {
              await refuseResumeNoLocalCheckout(sessionId, conversationId, recordedCwd || "unknown project");
              result = JSON.stringify({ forked: false, reason: "no_local_checkout" });
              break;
            }
            const { jsonl, sessionId: importSessionId } = generateCodexJsonl(exportData, { sessionId });
            const { filePath: importPath } = writeCodexSession(jsonl, importSessionId, "codecast-fork");
            setPosition(importPath, fs.statSync(importPath).size);
            const approvalPolicy = resolveCodexApprovalPolicy(config);
            const forked = await activeCodexAppServer.threadFork({
              threadId: "",
              path: importPath,
              cwd,
              approvalPolicy,
              sandbox: approvalPolicy === "never" ? "danger-full-access" : "workspace-write",
            });
            const realThreadId = forked.thread.id;
            remapConversationSession(sessionId, realThreadId, conversationId);
            registerAppServerConversation(conversationId, realThreadId, {
              cwd,
              persist: true,
              approvalPolicy,
            });
            if (forked.thread.path && fs.existsSync(forked.thread.path)) {
              setPosition(forked.thread.path, fs.statSync(forked.thread.path).size);
            }
            const forkGitInfo = await getGitInfo(cwd);
            await pushSessionIdBinding(conversationId, realThreadId, cwd, forkGitInfo?.repoRoot || forkGitInfo?.root);
            syncServiceRef?.claimSession(conversationId).catch(logConvexFailure);
            syncServiceRef?.markSessionActive(conversationId).catch(logConvexFailure);
            syncServiceRef?.registerManagedSession(realThreadId, process.pid, undefined, conversationId).catch(logConvexFailure);
            syncServiceRef?.updateSessionAgentStatus(conversationId, "connected").catch(logConvexFailure);
            ensureManagedSessionHeartbeat(realThreadId);
            conversationResumeFailures.delete(conversationId);
            await clearConversationDeliveryAndResumeState(conversationId, sessionId, "codex_app_server_fork");
            result = JSON.stringify({ forked: true, session_id: realThreadId, transport: "app-server" });
            log(`[REMOTE] Codex fork ${sessionId.slice(0, 8)} imported as app-server thread ${realThreadId.slice(0, 8)} for conv ${conversationId.slice(0, 12)}`);
          } catch (forkErr) {
            const message = forkErr instanceof Error ? forkErr.message : String(forkErr);
            logError(`[REMOTE] Codex app-server fork import failed for ${sessionId.slice(0, 8)}`, forkErr instanceof Error ? forkErr : new Error(message));
            error = `Codex history import failed: ${message}`;
            syncServiceRef?.setSessionError(conversationId, error).catch(logConvexFailure);
          } finally {
            restartingSessionIds.delete(sessionId);
          }
          break;
        }
        let resumed = false;
        if (forceReconstitute) {
          log(`[REMOTE] Force-reconstituting session ${sessionId.slice(0, 8)} from DB${projectPath ? ` in ${projectPath}` : ""}`);
          resumed = await repairAndResumeSession(sessionId, "", readTitleCache(), projectPath, conversationId, resumeAgentType, USER_RESUME);
        } else {
          log(`[REMOTE] Force-resuming session ${sessionId.slice(0, 8)}${projectPath ? ` in ${projectPath}` : ""}`);
          resumed = await autoResumeSession(sessionId, "", readTitleCache(), projectPath, conversationId, resumeAgentType, USER_RESUME);
          if (!resumed) {
            log(`[REMOTE] Auto-resume failed for ${sessionId.slice(0, 8)}, attempting repair...`);
            resumed = await repairAndResumeSession(sessionId, "", readTitleCache(), projectPath, conversationId, resumeAgentType, USER_RESUME);
          }
        }
        if (resumed) {
          if (conversationId) {
            const cache = readConversationCache();
            cache[sessionId] = conversationId;
            saveConversationCache(cache);
            if (syncServiceRef) {
              syncServiceRef.markSessionActive(conversationId).catch(logConvexFailure);
              // Don't force "connected" here — autoResumeSession already publishes the
              // accurate status (connected once the input prompt is visible, else resuming).
              // Overriding it would re-report the false-live signal fix #1 removes.
            }
          }
          restartingSessionIds.delete(sessionId);
          if (conversationId) conversationResumeFailures.delete(conversationId);
          // A resume revives the tmux pane just like a kill+restart does, so it shares the
          // same redelivery contract: clear the local injection dedup and re-pend injected
          // messages, else the re-queued pending message hits the "injected Ns ago" dedup
          // branch and never reaches the freshly-resumed pane. (Server resumeSession already
          // re-pends in Convex; this clears the *local* state that would otherwise suppress it.)
          await clearConversationDeliveryAndResumeState(conversationId, sessionId, "resume_session");
          result = JSON.stringify({ resumed: true, session_id: sessionId });
          log(`[REMOTE] Force-resume succeeded for ${sessionId.slice(0, 8)}`);
          if (reparented && conversationId) {
            await sendReparentNotice({
              conversationId, sessionId, priorCwd, checkout: reparentCheckout, command: parsed,
            });
          }
        } else if (conversationId && projectPath) {
          // Reconstitution AND the blank-session fallback below both run in `cwd`.
          // Resolve it to a real local checkout or refuse — never $HOME, which
          // would reconstitute/spawn in the home dir and mislabel the project.
          const cwd = await resolveResumeCwdOrRefuse({ recordedCwd: projectPath, cwdOverride: projectPath, conversationId });
          if (!cwd) {
            await refuseResumeNoLocalCheckout(sessionId, conversationId, projectPath);
            restartingSessionIds.delete(sessionId);
            break;
          }
          log(`[REMOTE] Resume failed for ${sessionId.slice(0, 8)}, reconstituting session from DB in ${cwd}...`);
          let reconstituted = false;

          // cursor-agent and opencode own their session stores (SQLite), and
          // pi/grok own their JSONL trees under ~/.pi and ~/.grok — none of them
          // may have a Claude JSONL fabricated for them. Skip DB reconstitution
          // for every store-owning client (mayReconstituteResumeTranscript is
          // the single predicate both resume sites share) and fall through to
          // the fresh spawn below.
          if (config?.convex_url && config?.auth_token && mayReconstituteResumeTranscript(resumeAgentType)) {
            try {
              const siteUrl = config.convex_url.replace(".cloud", ".site");
              const exportData = await fetchExport(siteUrl, config.auth_token!, conversationId);
              if (exportData.messages.length > 0) {
                const reconAgent = resumeAgentType || "claude";
                let reconJsonl: string;
                let newSessionId: string;
                let reconFilePath: string;
                if (reconAgent === "codex") {
                  ({ jsonl: reconJsonl, sessionId: newSessionId } = generateCodexJsonl(exportData, { sessionId }));
                  ({ filePath: reconFilePath } = writeCodexSession(reconJsonl, newSessionId));
                } else {
                  const TOKEN_BUDGET = CLAUDE_AUTO_TRIM_TARGET_TOKENS;
                  const tailMessages = chooseClaudeTailMessagesForTokenBudget(exportData, TOKEN_BUDGET);
                  ({ jsonl: reconJsonl, sessionId: newSessionId } = generateClaudeCodeJsonl(exportData, { tailMessages, sessionId }));
                  ({ filePath: reconFilePath } = writeClaudeCodeSession(reconJsonl, newSessionId, cwd));
                }
                setPosition(reconFilePath, fs.statSync(reconFilePath).size);
                log(`[REMOTE] Reconstituted ${reconAgent} JSONL for ${sessionId.slice(0, 8)} (${exportData.messages.length} msgs)`);

                const reconResumed = await autoResumeSession(newSessionId, "", readTitleCache(), cwd, conversationId, resumeAgentType, USER_RESUME);
                if (reconResumed) {
                  const cache = readConversationCache();
                  cache[newSessionId] = conversationId;
                  saveConversationCache(cache);
                  if (syncServiceRef) {
                    syncServiceRef.markSessionActive(conversationId).catch(logConvexFailure);
                    syncServiceRef.updateSessionAgentStatus(conversationId, "connected").catch(logConvexFailure);
                  }
                  restartingSessionIds.delete(sessionId);
                  if (conversationId) conversationResumeFailures.delete(conversationId);
                  // Same redelivery contract as the plain-resume branch above — clear local
                  // dedup so re-pended messages reach the reconstituted pane.
                  await clearConversationDeliveryAndResumeState(conversationId, newSessionId, "resume_session_reconstitute");
                  result = JSON.stringify({ reconstituted: true, session_id: newSessionId });
                  log(`[REMOTE] Reconstituted + resumed session ${sessionId.slice(0, 8)}`);
                  reconstituted = true;
                  if (reparented) {
                    // cwd (not projectPath): the refuse-or-resolve step above is
                    // what actually decided where this session lives now.
                    await sendReparentNotice({
                      conversationId, sessionId: newSessionId, priorCwd,
                      checkout: reparentCheckout?.path === cwd
                        ? reparentCheckout
                        : { path: cwd, cloned: false, branch: readBranch(cwd) },
                      command: parsed,
                    });
                  }
                }
              }
            } catch (reconErr) {
              log(`[REMOTE] Reconstitution failed for ${sessionId.slice(0, 8)}: ${reconErr instanceof Error ? reconErr.message : String(reconErr)}`);
            }
          }

          // resume_session is only triggered by explicit user actions (kill & restart,
          // repair). Always fall through to blank session — the user is asking us to restart,
          // not silently give up. Clear any stale fatal reason so it doesn't block future
          // auto-resume attempts either.
          if (!reconstituted) {
            resumeFatalReasons.delete(sessionId);
          }

          if (!reconstituted) {
            const existingStarted = startedSessionTmux.get(conversationId);
            if (existingStarted && (Date.now() - existingStarted.startedAt) < 60_000) {
              log(`[REMOTE] Fresh session ${existingStarted.tmuxSession} already started for ${conversationId.slice(0, 12)}, skipping duplicate`);
              result = JSON.stringify({ started_fresh: true, tmux_session: existingStarted.tmuxSession, deduplicated: true });
              break;
            }
            const blankAgentType = resumeAgentType || "claude";
            log(`[REMOTE] Starting blank ${blankAgentType} session in ${cwd}`);
            const shortId = Math.random().toString(36).slice(2, 8);
            const tmuxSession = `cc-${blankAgentType}-${shortId}`;
            // Registry-sourced binary (adds pi; cursor -> cursor-agent) — the same
            // launchBinary the fresh-start path uses, so no client is silently dropped
            // to claude here.
            const blankBinary = launchBinary(blankAgentType, { warn: log });
            // Inject the default permission flags exactly like start_session and
            // auto-resume. Building from config args alone here launched a bare
            // `claude` that fell into the project's dontAsk default — the agent
            // came back stranded with every tool denied.
            const safeBlankArgs = sanitizeBinaryArgs(buildBlankLaunchArgs(blankAgentType, config));
            const blankCmdText = `${AGENT_ENV_SCRUB} ${[blankBinary, ...safeBlankArgs].join(" ")}`;
            try {
              tmuxExecSync(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", tmuxSession, "-c", cwd], { timeout: 5000 });
              // Tag like the other creation paths so this session is discoverable
              // by conversation (findLiveTmuxForConversation / warm-restart). Without
              // the tag it is orphaned: a later fresh-start can't see it and spawns
              // a duplicate.
              await setTmuxSessionOption(tmuxSession, "@codecast_conversation_id", conversationId).catch(() => {});
              await setTmuxSessionOption(tmuxSession, "@codecast_agent_type", blankAgentType).catch(() => {});
              await setTmuxSessionOption(tmuxSession, "@codecast_project_path", cwd).catch(() => {});
              tmuxExecSync(["send-keys", "-t", tmuxSession, "-l", blankCmdText], { timeout: 5000 });
              tmuxExecSync(["send-keys", "-t", tmuxSession, "Enter"], { timeout: 5000 });
              startedSessionTmux.set(conversationId, {
                tmuxSession,
                projectPath: cwd,
                startedAt: Date.now(),
                agentType: blankAgentType,
              });
              discoverAndLinkSession(conversationId, tmuxSession, cwd).catch(err => {
                log(`Session discovery failed for ${conversationId.slice(0, 12)}: ${err}`);
              });
              result = JSON.stringify({ started_fresh: true, tmux_session: tmuxSession });
              log(`[REMOTE] Started fresh session ${tmuxSession} for conversation ${conversationId.slice(0, 12)}`);
            } catch (spawnErr) {
              error = `Failed to start fresh session: ${spawnErr instanceof Error ? spawnErr.message : String(spawnErr)}`;
            }
          }
        } else {
          error = `Failed to resume session ${sessionId.slice(0, 8)} — session file may not exist locally`;
        }
        if (!resumed && conversationId) {
          const prev = conversationResumeFailures.get(conversationId) || { count: 0, lastFailure: 0 };
          conversationResumeFailures.set(conversationId, { count: prev.count + 1, lastFailure: Date.now() });
        }
        break;
      }
      case "config_list": {
        const home = process.env.HOME || "";
        const claudeDir = path.join(home, ".claude");
        const codexDir = path.join(home, ".codex");

        type ConfigFile = { path: string; type: string; label: string; tool: string };
        const files: ConfigFile[] = [];

        const addFile = (filePath: string, type: string, label: string, tool: string) => {
          if (fs.existsSync(filePath)) files.push({ path: filePath, type, label, tool });
        };

        const addDir = (dir: string, type: string, tool: string) => {
          if (!fs.existsSync(dir)) return;
          try {
            for (const f of fs.readdirSync(dir)) {
              const fullPath = path.join(dir, f);
              const stat = fs.statSync(fullPath);
              if (stat.isDirectory()) {
                // Skills are directories containing SKILL.md
                const skillFile = path.join(fullPath, "SKILL.md");
                if (fs.existsSync(skillFile)) {
                  files.push({ path: skillFile, type, label: f, tool });
                }
              } else if (f.endsWith(".md") || f.endsWith(".json") || f.endsWith(".toml")) {
                files.push({ path: fullPath, type, label: f.replace(/\.(md|json|toml)$/, ""), tool });
              }
            }
          } catch {}
        };

        // Claude global files
        addFile(path.join(claudeDir, "CLAUDE.md"), "instructions", "Global CLAUDE.md", "claude");
        addFile(path.join(claudeDir, "settings.json"), "settings", "settings.json", "claude");
        addFile(path.join(claudeDir, "settings.local.json"), "settings", "settings.local.json", "claude");
        addFile(path.join(claudeDir, "keybindings.json"), "keybindings", "keybindings.json", "claude");
        addDir(path.join(claudeDir, "agents"), "agent", "claude");
        addDir(path.join(claudeDir, "commands"), "command", "claude");
        addDir(path.join(claudeDir, "skills"), "skill", "claude");
        addDir(path.join(claudeDir, "prompts"), "prompt", "claude");

        // Codex global files
        addFile(path.join(codexDir, "AGENTS.md"), "instructions", "Global AGENTS.md", "codex");
        addFile(path.join(codexDir, "AGENTS.override.md"), "instructions", "AGENTS.override.md", "codex");
        addFile(path.join(codexDir, "config.toml"), "settings", "config.toml", "codex");
        addDir(path.join(codexDir, "prompts"), "command", "codex");
        addDir(path.join(codexDir, "skills"), "skill", "codex");
        if (fs.existsSync(path.join(codexDir, "rules"))) {
          for (const f of fs.readdirSync(path.join(codexDir, "rules"))) {
            files.push({ path: path.join(codexDir, "rules", f), type: "rules", label: f, tool: "codex" });
          }
        }

        // Per-project files from known project paths
        const args_parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const projectPaths: string[] = args_parsed.project_paths || [];
        for (const pp of projectPaths) {
          const p = validatePath(pp);
          if (!p) continue;
          const name = path.basename(p);
          addFile(path.join(p, "CLAUDE.md"), "project_instructions", `${name}/CLAUDE.md`, "claude");
          addFile(path.join(p, "AGENTS.md"), "project_instructions", `${name}/AGENTS.md`, "codex");
          addFile(path.join(p, ".claude", "settings.json"), "project_settings", `${name}/.claude/settings.json`, "claude");
          addFile(path.join(p, ".claude", "settings.local.json"), "project_settings", `${name}/.claude/settings.local.json`, "claude");
          addFile(path.join(p, ".mcp.json"), "mcp", `${name}/.mcp.json`, "claude");
          addFile(path.join(p, ".codex", "config.toml"), "project_settings", `${name}/.codex/config.toml`, "codex");
          addDir(path.join(p, ".claude", "agents"), "project_agent", "claude");
          addDir(path.join(p, ".claude", "skills"), "project_skill", "claude");
          addDir(path.join(p, ".claude", "commands"), "project_command", "claude");
        }

        result = JSON.stringify(files);
        break;
      }
      case "config_read": {
        const { file_path: readPath } = commandArgs ? JSON.parse(commandArgs) : {};
        if (!readPath || typeof readPath !== "string") {
          error = "Missing file_path";
          break;
        }
        const home = process.env.HOME || "";
        const allowed = [path.join(home, ".claude"), path.join(home, ".codex")];
        const resolved = path.resolve(readPath);
        // Suffix arms stay (config_list advertises project files for viewing);
        // the includes() arms are gone — '/anything/.claude/x' matched another
        // user's home on a shared box, same hole the write fence closed.
        const isAllowed = allowed.some((a) => resolved.startsWith(a + path.sep) || resolved === a) ||
          readPath.endsWith("/CLAUDE.md") || readPath.endsWith("/AGENTS.md") ||
          readPath.endsWith("/.mcp.json") || readPath.endsWith("/settings.json") ||
          readPath.endsWith("/settings.local.json") || readPath.endsWith("/config.toml");
        if (!isAllowed) {
          error = "Path not allowed";
          break;
        }
        if (!fs.existsSync(resolved)) {
          result = JSON.stringify({ content: null, exists: false });
        } else {
          const content = fs.readFileSync(resolved, "utf-8");
          result = JSON.stringify({ content, exists: true });
        }
        break;
      }
      case "config_write": {
        const { file_path: writePath, content: writeContent } = commandArgs ? JSON.parse(commandArgs) : {};
        if (!writePath || typeof writePath !== "string" || typeof writeContent !== "string") {
          error = "Missing file_path or content";
          break;
        }
        // The old predicate accepted any path merely CONTAINING '/.claude/' or
        // ENDING in settings.json — which matches another user's home on a
        // shared box and any settings.json anywhere on disk. The fence now:
        //   1. this user's ~/.claude and ~/.codex subtrees, canonically resolved
        //      (realpath, so a symlink cannot walk the write out of the tree);
        //   2. the small set of agent config basenames inside a project root
        //      this daemon actually tracks — kept because config_list advertises
        //      project CLAUDE.md/.mcp.json for editing, and a fence that breaks
        //      the feature it guards just gets widened again later;
        //   3. nothing else.
        const home = process.env.HOME || "";
        const resolved = path.resolve(writePath);
        const dirReal = (() => {
          try {
            return fs.realpathSync(path.dirname(resolved));
          } catch {
            // Parent does not exist yet. Resolve the nearest existing ancestor
            // so a symlinked segment cannot smuggle the write elsewhere.
            let probe = path.dirname(resolved);
            const tail: string[] = [];
            while (!fs.existsSync(probe)) {
              tail.unshift(path.basename(probe));
              const up = path.dirname(probe);
              if (up === probe) return null;
              probe = up;
            }
            try {
              return path.join(fs.realpathSync(probe), ...tail);
            } catch {
              return null;
            }
          }
        })();
        if (!dirReal) {
          error = "Path not allowed";
          break;
        }
        const realTarget = path.join(dirReal, path.basename(resolved));
        const underOwnConfig = [path.join(home, ".claude"), path.join(home, ".codex")]
          .some((a) => realTarget === a || realTarget.startsWith(a + path.sep));
        const AGENT_CONFIG_BASENAMES = new Set([
          "CLAUDE.md", "AGENTS.md", ".mcp.json", "settings.json", "settings.local.json", "config.toml",
        ]);
        const underTrackedProject = (): boolean =>
          AGENT_CONFIG_BASENAMES.has(path.basename(realTarget)) &&
          computeLocalProjectRoots().some((root) => realTarget.startsWith(root + path.sep));
        // The roots are cached for the heartbeat. A project only a session
        // started in the last few minutes names is not in that cache yet, so
        // a miss recomputes once before it is refused.
        let allowed = underOwnConfig || underTrackedProject();
        if (!allowed) {
          invalidateLocalProjectRoots();
          allowed = underTrackedProject();
        }
        if (!allowed) {
          error = "Path not allowed";
          break;
        }
        // A file the capability materializer owns keys for is written through
        // its ledger, never over it: a raw whole-file write here would clobber
        // owned keys and orphan the ledger, voiding the ownership argument the
        // materializer rests on. The caller can pass override_owned after
        // showing the user the conflict.
        const { readLedger } = await import("./capabilities/ownedJson.js");
        const parsedArgs = commandArgs ? JSON.parse(commandArgs) : {};
        if (Object.keys(readLedger(realTarget)).length > 0 && !parsedArgs.override_owned) {
          error = "File carries capability-managed keys; pass override_owned to replace it wholesale";
          break;
        }
        fs.mkdirSync(path.dirname(realTarget), { recursive: true });
        const { atomicWriteFile } = await import("./atomicWrite.js");
        atomicWriteFile(realTarget, writeContent);
        result = JSON.stringify({ success: true });
        log(`[CONFIG] Wrote ${realTarget}`);
        break;
      }
      case "config_create": {
        const { dir_path, filename, content: createContent = "" } = commandArgs ? JSON.parse(commandArgs) : {};
        if (!dir_path || !filename) {
          error = "Missing dir_path or filename";
          break;
        }
        const home = process.env.HOME || "";
        const allowedDirs = [
          path.join(home, ".claude", "agents"),
          path.join(home, ".claude", "commands"),
          path.join(home, ".claude", "skills"),
          path.join(home, ".claude", "prompts"),
          path.join(home, ".codex", "prompts"),
          path.join(home, ".codex", "skills"),
        ];
        const expandedDir = dir_path.startsWith("~/") ? path.join(home, dir_path.slice(2)) : dir_path;
        const resolvedDir = path.resolve(expandedDir);
        if (!allowedDirs.some((a) => resolvedDir === a || resolvedDir.startsWith(a + path.sep))) {
          error = "Dir not allowed";
          break;
        }
        if (!/^[a-zA-Z0-9_-]+\.(md|json|toml)$/.test(filename)) {
          error = "Invalid filename";
          break;
        }
        const newPath = path.join(resolvedDir, filename);
        if (fs.existsSync(newPath)) {
          error = "File already exists";
          break;
        }
        fs.mkdirSync(resolvedDir, { recursive: true });
        fs.writeFileSync(newPath, createContent, "utf-8");
        result = JSON.stringify({ success: true, path: newPath });
        log(`[CONFIG] Created ${newPath}`);
        break;
      }
      case "config_delete": {
        const { file_path: deletePath } = commandArgs ? JSON.parse(commandArgs) : {};
        if (!deletePath || typeof deletePath !== "string") {
          error = "Missing file_path";
          break;
        }
        const home = process.env.HOME || "";
        const allowedDirs = [
          path.join(home, ".claude", "agents"),
          path.join(home, ".claude", "commands"),
          path.join(home, ".claude", "skills"),
          path.join(home, ".claude", "prompts"),
          path.join(home, ".codex", "prompts"),
          path.join(home, ".codex", "skills"),
        ];
        const expandedDelete = deletePath.startsWith("~/") ? path.join(home, deletePath.slice(2)) : deletePath;
        const resolved = path.resolve(expandedDelete);
        if (!allowedDirs.some((a) => resolved.startsWith(a + path.sep))) {
          error = "Only files in agents/commands/skills/prompts dirs can be deleted";
          break;
        }
        if (!fs.existsSync(resolved)) {
          error = "File not found";
          break;
        }
        fs.unlinkSync(resolved);
        result = JSON.stringify({ success: true });
        log(`[CONFIG] Deleted ${resolved}`);
        break;
      }
      case "move_to_device": {
        // Web-triggered move: THIS (source) daemon transfers the worktree to the
        // destination device, flips ownership, and resumes there. Only reaches us
        // because the command was target_device_id'd to us.
        //
        // The transfer (git push / scp of the worktree) can be multi-GB and take
        // minutes. Running it inline (synchronous execFileSync) froze the event
        // loop past the watchdog's 180s stale-heartbeat threshold, so the daemon
        // was force-restarted mid-move and the handoff silently never completed.
        // Delegate to `cast remote move` in a child process (which does transfer
        // + ownership flip + resume) and await it WITHOUT blocking the loop, so
        // heartbeats keep flowing and the watchdog leaves us alone.
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const sessionId: string | undefined = parsed.session_id;
        const conversationId: string | undefined = parsed.conversation_id;
        const toDeviceId: string | undefined = parsed.to_device_id;
        if (!sessionId || !conversationId || !toDeviceId) {
          error = "move_to_device: missing session_id/conversation_id/to_device_id";
          break;
        }
        log(`[MOVE] moving ${sessionId.slice(0, 8)} -> device ${toDeviceId.slice(0, 8)} (async child)`);
        const moveRes = await runCastCommand(["remote", "move", sessionId, "--to-device", toDeviceId]);
        if (moveRes.code === 0) {
          // Stop the local copy so ONLY the destination runs it. Ownership now
          // points at the remote, but a still-live local tmux/process (started OR
          // auto-resumed) would keep answering delivered messages in parallel
          // (split-brain) — reap every local backend, then clear the in-memory
          // delivery/resume bookkeeping.
          await stopLocalSessionBackends(conversationId, sessionId).catch(() => {});
          await clearConversationDeliveryAndResumeState(conversationId, sessionId, "move_to_device").catch(() => {});
          result = JSON.stringify({ moved: true, to: toDeviceId });
          log(`[MOVE] done — ${sessionId.slice(0, 8)} now owned by ${toDeviceId.slice(0, 8)}`);
        } else {
          const detail = childErrorDetail(moveRes.stderr, moveRes.stdout);
          error = `move failed (exit ${moveRes.code})${detail ? `: ${detail}` : ""}`;
          log(`[MOVE] FAILED ${sessionId.slice(0, 8)} -> ${toDeviceId.slice(0, 8)}: ${error}`);
        }
        break;
      }
      case "release_session": {
        // Ownership was reassigned AWAY from this device ("Run here" on another
        // machine). Targeted at us — the previous owner — so we must NOT sit
        // behind the SESSION_COMMANDS single-owner guard (which would skip this
        // precisely because we no longer own the conversation). Reap every
        // local backend so no stale tmux/agent copy keeps running here — the
        // same teardown move_to_device runs on the source after a transfer.
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const conversationId: string | undefined = parsed.conversation_id;
        const sessionId: string | undefined = parsed.session_id;
        if (!conversationId) {
          error = "release_session: missing conversation_id";
          break;
        }
        // Race guard: if ownership bounced back to us (A→B→A before we polled
        // move 1's release), this command is stale — tearing down would kill a
        // session we rightfully run. Fail-open on lookup error: the command
        // only exists because ownership moved away, so cleanup is the norm.
        try {
          const info = await syncServiceRef?.getConversationOwnerInfo(conversationId);
          if (info?.ownerDeviceId === deviceId()) {
            log(`[RELEASE] skipping ${conversationId.slice(0, 12)} — ownership is back on this device`);
            result = JSON.stringify({ released: false, reason: "owner_again" });
            break;
          }
        } catch { /* fall through and release */ }
        log(`[RELEASE] releasing ${conversationId.slice(0, 12)} — ownership moved to another device`);
        await stopLocalSessionBackends(conversationId, sessionId).catch(() => {});
        await clearConversationDeliveryAndResumeState(conversationId, sessionId, "release_session").catch(() => {});
        result = JSON.stringify({ released: true });
        break;
      }
      case "apply_snippet": {
        // Web "Agent Features" changed a setting for THIS device. Run the very CLI
        // command a human would, then heartbeat so the new state round-trips back
        // within seconds. Two shapes: a boolean snippet (`cast install <slug>` /
        // `--disable`) or the tri-state stable hook (`cast stable <mode>`).
        const parsed = commandArgs ? JSON.parse(commandArgs) : {};
        const snippet = parsed.snippet;
        // Match aliases too: the web sends pre-rename slugs (e.g. "scheduling"
        // for triggers) so its toggles also work on daemons that predate a rename.
        const known = snippet === "stable" || !!snippetBySlug(snippet);
        if (typeof snippet !== "string" || !known) {
          error = `apply_snippet: unknown snippet ${JSON.stringify(snippet)}`;
          break;
        }

        let cliArgs: string[];
        let logVerb: string;
        if (snippet === "stable") {
          const mode = parsed.mode === "team" || parsed.mode === "off" ? parsed.mode : "solo";
          cliArgs = ["stable", mode, ...(parsed.global ? ["-g"] : [])];
          logVerb = `stable=${mode}${parsed.global ? " (all projects)" : ""}`;
        } else {
          cliArgs = parsed.enabled ? ["install", snippet] : ["install", snippet, "--disable"];
          logVerb = `${parsed.enabled ? "installing" : "disabling"} ${snippet}`;
        }

        log(`[SNIPPET] ${logVerb} (web toggle)`);
        const res = await runCastCommand(cliArgs, { timeoutMs: 60 * 1000 });
        if (res.code === 0) {
          result = JSON.stringify({ snippet, ...(snippet === "stable" ? { mode: parsed.mode } : { enabled: parsed.enabled }) });
          // Push the freshly-written config state up now, don't wait for the
          // next ~30s beat — keeps the Settings control feeling instant.
          await sendHeartbeat().catch(() => {});
        } else {
          error = `cast ${cliArgs[0]} failed (exit ${res.code}): ${(res.stderr || res.stdout || "").trim().slice(-300)}`;
        }
        break;
      }
      case "set_provider_key": {
        // Web set/removed a managed provider key for THIS device (pl-207). A "set"
        // arrives SEALED to this device's ECDH public key — Convex never saw
        // plaintext. applyProviderKeyCommand decrypts + updates the 0600 store; we
        // then fan out to remotes and heartbeat so managed_provider_ids round-trips.
        const applied = applyProviderKeyCommand(CONFIG_DIR, commandArgs);
        if (!applied.ok) { error = `set_provider_key: ${applied.error}`; break; }
        log(`[KEYS] ${applied.op} ${applied.provider} (web)`);
        result = JSON.stringify({ op: applied.op, provider: applied.provider });
        pushProviderKeysToRemoteHosts("web set").catch(() => {});
        await sendHeartbeat().catch(() => {});
        break;
      }
      default:
        error = `Unknown command: ${command}`;
    }
  } catch (err) {
    error = err instanceof Error ? err.message : String(err);
  }

  // Report result
  try {
    await fetch(`${siteUrl}/cli/command-result`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        api_token: config.auth_token,
        command_id: commandId,
        result,
        error,
      }),
    });
  } catch {
    // Ignore
  }
}

async function flushRemoteLogs(): Promise<void> {
  await flushRemoteLogsViaHttp();
}

function ensureConfigDir(): void {
  if (!fs.existsSync(CONFIG_DIR)) {
    fs.mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 });
  }
}

type ConfigDiagnosis =
  | { ok: true; config: Config; convexUrl: string }
  | { ok: false; reason: string };

function diagnoseConfig(): ConfigDiagnosis {
  if (!fs.existsSync(CONFIG_FILE)) {
    return { ok: false, reason: "Waiting for configuration... (run 'cast auth' to set up)" };
  }
  let raw: string;
  try {
    raw = fs.readFileSync(CONFIG_FILE, "utf-8");
  } catch (err) {
    return {
      ok: false,
      reason: `[ERROR] Cannot read ${CONFIG_FILE}: ${err instanceof Error ? err.message : String(err)}`,
    };
  }
  let config: Config;
  try {
    config = JSON.parse(raw) as Config;
  } catch (err) {
    return {
      ok: false,
      reason: `[ERROR] ${CONFIG_FILE} is not valid JSON: ${err instanceof Error ? err.message : String(err)} — run 'cast auth' to recreate`,
    };
  }
  if (config.auth_token && isEncryptedToken(config.auth_token)) {
    try {
      config.auth_token = decryptToken(config.auth_token);
    } catch (err) {
      if (err instanceof TokenDecryptError) {
        return {
          ok: false,
          reason: `[ERROR] Auth token cannot be decrypted on this machine (${err.message}) — run 'cast auth' to re-encrypt`,
        };
      }
      throw err;
    }
  }
  if (!config.user_id) {
    return { ok: false, reason: `[ERROR] ${CONFIG_FILE} is missing user_id — run 'cast auth' to fix` };
  }
  const convexUrl = config.convex_url || process.env.CONVEX_URL;
  if (!convexUrl) {
    return {
      ok: false,
      reason: `[ERROR] ${CONFIG_FILE} is missing convex_url and CONVEX_URL is not set — run 'cast auth' to fix`,
    };
  }
  return { ok: true, config, convexUrl };
}

function readConfig(): Config | null {
  const diag = diagnoseConfig();
  return diag.ok ? diag.config : null;
}

const ANSI_ESCAPE_RE = /\x1b\[[0-9;]*m/g;

function stripAnsi(text: string): string {
  return text.replace(ANSI_ESCAPE_RE, "");
}

// Codex counterpart of the Claude SessionStart hook: same shared builder, with
// per-session launch prefs (from start_session args) overriding the machine's
// config defaults. Returns the block text plus the structured item list the
// caller records on the conversation.
export async function buildCodexStableContext(
  config: Config | null,
  cwd?: string,
  prefs?: StableLaunchPrefs,
): Promise<BuiltStableContext | undefined> {
  let mode: "team" | "solo" | null;
  if (prefs?.stable_mode === "off") mode = null;
  else if (prefs?.stable_mode === "team" || prefs?.stable_mode === "solo") mode = prefs.stable_mode;
  else mode = config?.stable_mode ?? null;
  if (!mode) return undefined;
  return buildStableContext(config, {
    mode,
    global: !!config?.stable_global,
    exclude: prefs?.stable_exclude ?? [],
    cwd,
  });
}

/** A stable-context card represents context that reached a real Codex thread.
 * Never publish it before threadStart resolves: app-server startup can fail and
 * fall back to tmux, where no developerInstructions were injected. */
export async function startCodexThreadThenRecordStableContext<T>(
  startThread: () => Promise<T>,
  record?: () => void,
): Promise<T> {
  const response = await startThread();
  try {
    record?.();
  } catch {
    // Recording is optional and must not turn a successful thread start into
    // a fallback launch.
  }
  return response;
}

function patchConfig(updates: Partial<Config>): void {
  const config = readConfig();
  if (!config) return;
  Object.assign(config, updates);
  const toWrite = { ...config };
  if (toWrite.auth_token && !isEncryptedToken(toWrite.auth_token)) {
    toWrite.auth_token = encryptToken(toWrite.auth_token);
  }
  fs.writeFileSync(CONFIG_FILE, JSON.stringify(toWrite, null, 2), { mode: 0o600 });
}

// conversations.json is >1MB on a busy machine, and hot paths (heartbeat
// maintenance, delivery, sweeps) read it per session — parsing it fresh each
// call cost ~85ms a call and was a top contributor to the loop freezes behind
// the "daemon under load" badge. Memoize the parse, validated by stat so a
// write from anywhere (including another process) invalidates it. Callers
// mutate the returned object then saveConversationCache it, so the memo shares
// the object and save refreshes the stamp.
let conversationCacheMemo: { data: ConversationCache; mtimeMs: number; size: number } | null = null;

function readConversationCache(): ConversationCache {
  const cacheFile = path.join(CONFIG_DIR, "conversations.json");
  let stat: fs.Stats;
  try {
    stat = fs.statSync(cacheFile);
  } catch {
    return {};
  }
  if (conversationCacheMemo && conversationCacheMemo.mtimeMs === stat.mtimeMs && conversationCacheMemo.size === stat.size) {
    return conversationCacheMemo.data;
  }
  try {
    const data = JSON.parse(fs.readFileSync(cacheFile, "utf-8")) as ConversationCache;
    conversationCacheMemo = { data, mtimeMs: stat.mtimeMs, size: stat.size };
    return data;
  } catch {
    return {};
  }
}

function saveConversationCache(cache: ConversationCache): void {
  const cacheFile = path.join(CONFIG_DIR, "conversations.json");
  fs.writeFileSync(cacheFile, JSON.stringify(cache, null, 2));
  try {
    const stat = fs.statSync(cacheFile);
    conversationCacheMemo = { data: cache, mtimeMs: stat.mtimeMs, size: stat.size };
  } catch {
    conversationCacheMemo = null;
  }
}

let projectMapCache: Record<string, string> | null = null;
function readProjectMap(): Record<string, string> {
  if (projectMapCache) return projectMapCache;
  try {
    projectMapCache = JSON.parse(fs.readFileSync(PROJECT_MAP_FILE, "utf-8")) as Record<string, string>;
  } catch {
    projectMapCache = {};
  }
  return projectMapCache;
}

// Remember that a repo identified by `key` (its basename, or a recorded remote path)
// lives at `localDir` on this machine. Gated to actual git-repo roots so the map stays a
// small, accurate index — this excludes $HOME, /tmp, and parent dirs like ~/src that a
// project-dir scan would otherwise decode and record as misleading entries. Only persists
// real, changed entries.
function recordProjectMapping(key: string, localDir: string): void {
  if (!key || !localDir) return;
  if (!fs.existsSync(path.join(localDir, ".git"))) return;
  const map = readProjectMap();
  if (map[key] === localDir) return;
  map[key] = localDir;
  try {
    fs.writeFileSync(PROJECT_MAP_FILE, JSON.stringify(map, null, 2));
    projectMapCache = map;
  } catch {}
}

function readTitleCache(): TitleCache {
  const cacheFile = path.join(CONFIG_DIR, "titles.json");
  if (!fs.existsSync(cacheFile)) {
    return {};
  }
  try {
    return JSON.parse(fs.readFileSync(cacheFile, "utf-8")) as TitleCache;
  } catch {
    return {};
  }
}

function saveTitleCache(cache: TitleCache): void {
  const cacheFile = path.join(CONFIG_DIR, "titles.json");
  fs.writeFileSync(cacheFile, JSON.stringify(cache, null, 2));
}

function generateTitleFromMessage(content: string): string {
  const trimmed = content.trim();
  if (!trimmed) {
    return "";
  }

  const cmdNameMatch = trimmed.match(/<command-name>([^<]*)<\/command-name>/);
  if (cmdNameMatch) return `/${cmdNameMatch[1].replace(/^\//, "")}`;

  const cmdMsgMatch = trimmed.match(/<command-message>([^<]*)<\/command-message>/);
  if (cmdMsgMatch) return `/${cmdMsgMatch[1].replace(/^\//, "")}`;

  const cleaned = trimmed
    .replace(/<[^>]+>[\s\S]*?<\/[^>]+>/g, "")
    .replace(/<[^>]+>/g, "")
    .trim();

  const result = cleaned || trimmed;
  if (result.length <= 50) {
    return result;
  }

  return result.slice(0, 50) + "...";
}

function readDaemonState(): DaemonState {
  if (!fs.existsSync(STATE_FILE)) {
    return {};
  }
  try {
    return JSON.parse(fs.readFileSync(STATE_FILE, "utf-8")) as DaemonState;
  } catch {
    return {};
  }
}

function saveDaemonState(updates: Partial<DaemonState>): void {
  try {
    const current = readDaemonState();
    const newState = { ...current, ...updates, timestamp: Date.now() };
    fs.writeFileSync(STATE_FILE, JSON.stringify(newState, null, 2), { mode: 0o600 });
  } catch (err) {
    log(`Failed to write daemon state: ${err instanceof Error ? err.message : String(err)}`);
  }
}

function handleAuthFailure(): boolean {
  const state = readDaemonState();
  const currentCount = (state.authFailureCount || 0) + 1;

  if (currentCount >= AUTH_FAILURE_THRESHOLD) {
    logError(`Auth failed ${currentCount} times consecutively - marking auth as expired`);
    saveDaemonState({ authExpired: true, authFailureCount: currentCount });
    return true;
  }

  log(`Auth failure ${currentCount}/${AUTH_FAILURE_THRESHOLD} - will retry`);
  saveDaemonState({ authFailureCount: currentCount });
  return false;
}

function resetAuthFailureCount(): void {
  const state = readDaemonState();
  if (state.authFailureCount && state.authFailureCount > 0) {
    saveDaemonState({ authFailureCount: 0 });
  }
}

interface GitInfo {
  commitHash?: string;
  branch?: string;
  remoteUrl?: string;
  status?: string;
  diff?: string;
  diffStaged?: string;
  root?: string;
  repoRoot?: string;
  worktreeName?: string;
  worktreeBranch?: string;
  worktreePath?: string;
}

// Sync-scope rules (test-scratch exclusion, excluded-paths, selected-projects
// allowlist) live in their own leaf module (./syncScope.js) so the
// reconciliation loop and `cast doctor` can share the EXACT same rules without
// importing this giant daemon module. Imported at the top and re-exported here
// for backward compatibility with tests that import them from "./daemon.js".
export { TEST_SCRATCH_DIRNAME, isTestScratchPath, isProjectAllowedToSync };

// Eight git child processes per call, and `git diff` / `git status` on a busy
// repo take seconds when the disk is contended (8s and 14s on 2026-09-02, a
// 23s loop freeze inside session discovery). Async, sequential: commands on
// one repo contend on index.lock, so parallel would not be faster anyway.
async function getGitInfo(projectPath: string): Promise<GitInfo | undefined> {
  const execGit = (args: string): Promise<string | undefined> =>
    new Promise((resolve) => {
      execFile("git", args.split(" "), {
        cwd: projectPath,
        encoding: "utf-8",
        maxBuffer: 10 * 1024 * 1024,
        timeout: 60_000,
      }, (err, stdout) => resolve(err ? undefined : String(stdout).trim()));
    });

  const commitHash = await execGit("rev-parse HEAD");
  if (!commitHash) {
    return undefined;
  }

  const branch = await execGit("rev-parse --abbrev-ref HEAD");
  const remoteUrl = await execGit("remote get-url origin");
  const status = await execGit("status --porcelain");
  const diff = await execGit("diff");
  const diffStaged = await execGit("diff --cached");
  const root = await execGit("rev-parse --show-toplevel");

  const commonDir = await execGit("rev-parse --path-format=absolute --git-common-dir");
  const repoRoot = commonDir?.endsWith("/.git") ? commonDir.slice(0, -5) : root;

  const worktreeMatch = projectPath.match(/(?:\.codecast\/worktrees|\.conductor|\.claude-worktrees\/[^/]+)\/([^/]+)/);
  const worktreeName = worktreeMatch ? worktreeMatch[1] : undefined;

  return {
    commitHash,
    branch,
    remoteUrl,
    status,
    diff: diff ? diff.slice(0, 100000) : undefined,
    diffStaged: diffStaged ? diffStaged.slice(0, 100000) : undefined,
    root,
    repoRoot,
    worktreeName,
    worktreeBranch: worktreeName ? branch : undefined,
    worktreePath: worktreeName ? projectPath : undefined,
  };
}

const CODECAST_WORKTREE_DIR = ".codecast/worktrees";

interface WorktreeResult {
  worktreePath: string;
  worktreeName: string;
  worktreeBranch: string;
  portIndex: number;
}

/**
 * Create or attach to a worktree.
 *
 * Two paths:
 *   1. NEW: if .codecast/workspace.toml exists, delegate to the workspace
 *      module (full manifest-driven setup: copy, install, hooks, contract).
 *      Project the resulting Workspace to the legacy WorktreeResult shape.
 *   2. LEGACY: minimal git worktree + .wt-setup-files copy. Preserved
 *      verbatim for repos that haven't opted in.
 *
 * On any failure of the new path, we fall through to the legacy path so the
 * daemon never regresses below pre-integration capability.
 */
async function createWorktree(
  repoRoot: string,
  name: string,
): Promise<WorktreeResult | null> {
  const manifestPath = path.join(repoRoot, ".codecast/workspace.toml");
  if (fs.existsSync(manifestPath)) {
    try {
      const ws = await import("./workspace/index.js");
      const result = await ws.acquireWorkspace(repoRoot, name);
      log(
        `[WORKTREE] new-path: ${name} state=${result.workspace.state} detected=${result.workspace.manifest.detected ?? "none"}`,
      );
      if (result.workspace.state === "ready") {
        return ws.toWorktreeResult(result.workspace);
      }
      // Broken contract — log details and fall through to legacy as safety net.
      const failures = result.workspace.contract?.checks
        .filter((c) => !c.ok)
        .map((c) => `${c.name}${c.reason ? `: ${c.reason}` : ""}`)
        .join("; ");
      log(`[WORKTREE] new-path ${name} broken, falling back. failures: ${failures}`);
    } catch (err) {
      log(`[WORKTREE] new-path ${name} threw, falling back: ${(err as Error).message}`);
    }
  }
  return createWorktreeLegacy(repoRoot, name);
}

function createWorktreeLegacy(repoRoot: string, name: string): WorktreeResult | null {
  const worktreeDir = path.join(repoRoot, CODECAST_WORKTREE_DIR);
  const worktreePath = path.join(worktreeDir, name);
  const branchName = `codecast/${name}`;

  if (fs.existsSync(worktreePath)) {
    const existingBranch = (() => {
      try {
        return execSync(`git rev-parse --abbrev-ref HEAD`, {
          cwd: worktreePath, encoding: "utf-8", stdio: ["pipe", "pipe", "ignore"],
        }).trim();
      } catch { return branchName; }
    })();
    return {
      worktreePath,
      worktreeName: name,
      worktreeBranch: existingBranch,
      portIndex: assignPortIndex(repoRoot),
    };
  }

  fs.mkdirSync(worktreeDir, { recursive: true });

  // Retry loop to handle concurrent git lock contention
  let created = false;
  let lastErr: unknown;
  for (let attempt = 0; attempt < 5; attempt++) {
    if (attempt > 0) {
      try { execSync(`sleep ${(200 + attempt * 300) / 1000}`, { stdio: "ignore" }); } catch {}
    }
    try {
      execSync(`git worktree add -b ${branchName} ${worktreePath}`, {
        cwd: repoRoot, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"],
      });
      created = true;
      break;
    } catch (err) {
      // Branch already exists — try without -b
      try {
        execSync(`git worktree add ${worktreePath} ${branchName}`, {
          cwd: repoRoot, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"],
        });
        created = true;
        break;
      } catch (err2) {
        lastErr = err2;
      }
    }
  }

  if (!created) {
    log(`[WORKTREE] Failed to create worktree: ${lastErr}`);
    return null;
  }

  // Remove large build artifact directories that bloat the worktree
  const LARGE_ARTIFACT_DIRS = ["packages/desktop/src-tauri/target"];
  for (const dir of LARGE_ARTIFACT_DIRS) {
    const fullPath = path.join(worktreePath, dir);
    if (fs.existsSync(fullPath)) {
      try { execSync(`/bin/rm -rf ${JSON.stringify(fullPath)}`, { stdio: "ignore" }); } catch {}
    }
  }

  copySetupFiles(repoRoot, worktreePath);

  return {
    worktreePath,
    worktreeName: name,
    worktreeBranch: branchName,
    portIndex: assignPortIndex(repoRoot),
  };
}

function assignPortIndex(repoRoot: string): number {
  const worktreeDir = path.join(repoRoot, CODECAST_WORKTREE_DIR);
  if (!fs.existsSync(worktreeDir)) return 0;
  const existing = fs.readdirSync(worktreeDir).filter(f => {
    try { return fs.statSync(path.join(worktreeDir, f)).isDirectory(); } catch { return false; }
  });
  return Math.min(existing.length - 1, 9);
}

function copySetupFiles(mainRoot: string, worktreePath: string): void {
  const configFile = path.join(mainRoot, ".wt-setup-files");
  const patterns = fs.existsSync(configFile)
    ? fs.readFileSync(configFile, "utf-8").split("\n").map(l => l.trim()).filter(l => l && !l.startsWith("#"))
    : [".env", ".env.local"];

  for (const pattern of patterns) {
    const src = path.join(mainRoot, pattern);
    const dest = path.join(worktreePath, pattern);
    if (!fs.existsSync(src) || fs.existsSync(dest)) continue;
    try {
      const destDir = path.dirname(dest);
      fs.mkdirSync(destDir, { recursive: true });
      if (fs.statSync(src).isDirectory()) {
        execSync(`cp -r ${JSON.stringify(src)} ${JSON.stringify(dest)}`, { stdio: "ignore" });
      } else {
        fs.copyFileSync(src, dest);
      }
    } catch {}
  }
}

function decodeProjectDirName(dirName: string): string {
  const stripped = dirName.startsWith("-") ? dirName.slice(1) : dirName;
  const tokens = stripped.split("-");

  let resolved = "/";
  let i = 0;

  while (i < tokens.length) {
    if (tokens[i] === "") { i++; continue; }
    let matched = false;
    for (let len = tokens.length - i; len >= 1; len--) {
      const candidate = tokens.slice(i, i + len).join("-");
      if (fs.existsSync(path.join(resolved, candidate))) {
        resolved = path.join(resolved, candidate);
        i += len;
        matched = true;
        break;
      }
      if (fs.existsSync(path.join(resolved, "." + candidate))) {
        resolved = path.join(resolved, "." + candidate);
        i += len;
        matched = true;
        break;
      }
    }
    if (!matched) {
      resolved = path.join(resolved, tokens[i]);
      i++;
    }
  }

  return resolved;
}

// A transcript's cwd never changes, so memoize the (small) head read by file.
const transcriptProjectPathCache = new Map<string, string>();

/**
 * Project path for a discovered transcript file. Trusts the cwd recorded INSIDE
 * the transcript over the (lossy, copyable) ~/.claude/projects folder slug — a
 * transcript resumed/copied into a foreign or $HOME dir would otherwise mislabel
 * the conversation (e.g. "/Users/m1"). See pickProjectPath for the rule.
 * `dirName` is the project-dir slug (the folder name).
 */
function resolveTranscriptProjectPath(filePath: string, dirName: string): string {
  const cached = transcriptProjectPathCache.get(filePath);
  if (cached !== undefined) return cached;
  const decodedSlugPath = decodeProjectDirName(dirName);
  let recordedCwd: string | undefined;
  try { recordedCwd = extractCwd(readFileHead(filePath, 65536)); } catch {}
  const result = pickProjectPath({ decodedSlugPath, recordedCwd, home: process.env.HOME });
  // Only memoize a trustworthy answer: a found cwd, or a slug that resolved to a
  // real non-$HOME project. A not-yet-populated transcript (no cwd line yet)
  // stays re-checkable so a transient guess isn't cached for the session's life.
  if (recordedCwd || (decodedSlugPath && decodedSlugPath !== process.env.HOME)) {
    transcriptProjectPathCache.set(filePath, result);
  }
  return result;
}

async function flushPendingMessagesBatch(
  pendingMsgs: Array<{ uuid?: string; role: "human" | "assistant" | "system"; content: string; timestamp: number; thinking?: string; toolCalls?: any; toolResults?: any; images?: any; subtype?: string; model?: string }>,
  conversationId: string,
  syncService: SyncService,
  retryQueue: RetryQueue,
): Promise<void> {
  try {
    await syncService.addMessages({
      conversationId,
      messages: pendingMsgs.map(msg => ({
        messageUuid: msg.uuid,
        role: msg.role,
        content: msg.content,
        timestamp: msg.timestamp,
        thinking: msg.thinking,
        toolCalls: msg.toolCalls,
        toolResults: msg.toolResults,
        images: msg.images,
        subtype: msg.subtype,
        model: msg.model,
      })),
    });
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err);
    if (isStaleConversationError(errMsg)) {
      log(`Batch pending flush hit stale conversation ${conversationId}; dropping batch so the caller can re-resolve: ${errMsg}`);
      return;
    }
    log(`Batch pending flush failed, queueing individually: ${errMsg}`);
    for (const msg of pendingMsgs) {
      retryQueue.add("addMessage", {
        conversationId,
        messageUuid: msg.uuid,
        role: msg.role,
        content: msg.content,
        timestamp: msg.timestamp,
        thinking: msg.thinking,
        toolCalls: msg.toolCalls,
        toolResults: msg.toolResults,
        images: msg.images,
        subtype: msg.subtype,
        model: msg.model,
      }, errMsg);
    }
  }
}

export type RawMessage = { uuid?: string; role: string; content: string; timestamp: number; thinking?: string; toolCalls?: any; toolResults?: any; images?: any; subtype?: string; model?: string };

// A cached conversation_id can become invalid against the current api_token in two ways:
// the conversation was deleted (Convex returns "Conversation not found") or the auth token
// now belongs to a different user (Convex returns "Unauthorized: can only add messages to
// your own conversations"). Both mean: drop the cache, let createConversation re-resolve
// by (session_id, current user_id). Retrying without re-resolving spins forever.
function isStaleConversationError(errMsg: string): boolean {
  return errMsg.includes("Conversation not found") ||
    errMsg.includes("Unauthorized: can only add messages to your own conversations");
}

function mapRole(role: string): "human" | "assistant" | "system" {
  return role === "user" ? "human" : role === "system" ? "system" : "assistant";
}

function prepMessageForSync(msg: RawMessage): { messageUuid?: string; role: "human" | "assistant" | "system"; content: string; timestamp: number; thinking?: string; toolCalls?: any; toolResults?: any; images?: any; subtype?: string; model?: string } {
  return {
    messageUuid: msg.uuid,
    role: mapRole(msg.role),
    content: redactSecrets(msg.content),
    timestamp: msg.timestamp,
    thinking: msg.thinking,
    toolCalls: msg.toolCalls,
    toolResults: msg.toolResults,
    images: msg.images,
    subtype: msg.subtype,
    model: msg.model,
  };
}

// Codex's app-server streams only the AGENT's output items back to us; the prompt we send
// via turn/start is never replayed (unlike Claude, whose JSONL echoes the user turn, so
// parseSessionFile captures it). Left to the live stream alone a Codex conversation persists
// as agent-only output — every user turn lost (ct-36429). So the daemon records the user turn
// itself at delivery time. Routed through the same addMessages path as Claude, the server
// content-matches it to the pending_messages row — adopting that row's client_id so the web's
// optimistic bubble reconciles, and marking the row delivered. The stable `codex-user-<id>`
// message_uuid keeps re-delivery idempotent.
export function buildCodexUserTurnMessage(
  content: string,
  pendingMessageId: string,
  timestamp: number,
): RawMessage {
  return { uuid: `codex-user-${pendingMessageId}`, role: "user", content, timestamp };
}

// A user-role turn the HARNESS emits on its own — the boot <task-notification>
// bundle about background tasks from the previous session — is never the echo
// of a pasted pending message. The positional delivery-ack pairing in
// syncMessagesBatch must skip these: pairing one with a pasted row stamps the
// row's client_id onto the notification turn, and the real echo later re-adopts
// the same client_id by content match — two transcript messages sharing one
// client id, which the web timeline renders as overlapping duplicate rows.
export function isHarnessEmittedUserTurn(content: string | undefined): boolean {
  return !!content && content.trimStart().startsWith("<task-notification>");
}

async function syncMessagesBatch(
  messages: RawMessage[],
  conversationId: string,
  syncService: SyncService,
  retryQueue: RetryQueue,
): Promise<{ authExpired: boolean; conversationNotFound: boolean }> {
  // Prepare + offload images ONCE. offloadImages mutates the prepared messages in
  // place (raw base64 → storageId, or drops oversized images), so the same small
  // array is reused for the send, the inline retry, and the retry-queue enqueue.
  // Previously each of those re-ran messages.map(prepMessageForSync), so the queue
  // persisted the full raw base64 and every retry re-uploaded the same image.
  const prepared = messages.map(prepMessageForSync);
  await syncService.offloadImages(prepared);
  if (retryQueue.hasPendingConversation(conversationId)) {
    log(`Conversation ${conversationId.slice(0, 12)} already has retry backlog; buffering ${messages.length} new msgs into retry queue`);
    retryQueue.add("addMessages", {
      conversationId,
      messages: prepared,
    }, "conversation backlog already queued");
    return { authExpired: false, conversationNotFound: false };
  }
  try {
    const synced = await syncService.addMessages({
      conversationId,
      messages: prepared,
    });
    resetAuthFailureCount();
    // If we just synced a user message from the JSONL, ack the injected pending
    // messages THIS process pasted (scoped — see collectPastedInjectedIds). The
    // content-matched ack in addMessages remains the reliable per-row path; this
    // covers pastes whose echo can't content-match (poll conversions, truncated
    // oversized content). Passing the explicit id list (even empty) stops a
    // historical user turn — e.g. an auto-resume resyncing a fresh JSONL from
    // position 0 — from terminalizing rows that never landed (DEC-01).
    if (messages.some(m => m.role === "user")) {
      const pastedIds = collectPastedInjectedIds(conversationId);
      const transcriptIds = synced.ids.filter((_, index) =>
        messages[index]?.role === "user" && !isHarnessEmittedUserTurn(messages[index]?.content));
      // The rows this process pasted and the user turns just committed are both
      // ordered. Pair the newest common suffix: older un-echoed pastes remain
      // injected for healing, while each daemon-vouched echo can stamp the
      // exact client_id needed by messages.send/v2 coverage (DWB-03).
      const pairCount = Math.min(pastedIds.length, transcriptIds.length);
      const deliveryAcks = pairCount === 0
        ? []
        : pastedIds.slice(-pairCount).map((pendingMessageId, index) => ({
            pendingMessageId,
            transcriptMessageId: transcriptIds[transcriptIds.length - pairCount + index]!,
          }));
      syncService.ackInjectedMessages(
        conversationId,
        pastedIds,
        deliveryAcks,
      ).catch(logConvexFailure);
    }
    return { authExpired: false, conversationNotFound: false };
  } catch (err) {
    if (err instanceof AuthExpiredError) {
      if (handleAuthFailure()) {
        return { authExpired: true, conversationNotFound: false };
      }
    }

    const errMsg = err instanceof Error ? err.message : String(err);
    if (isStaleConversationError(errMsg)) {
      return { authExpired: false, conversationNotFound: true };
    }

    // Hand the failed batch straight to the retry queue instead of burning a
    // second full inline attempt here. The old inline retry slept 2s then ran
    // another addMessages that could itself hit the 28s timeout — ~58s total
    // holding this file's per-file InvalidateSync slot before the op even
    // reached the queue, during which `cast status` and the live path saw
    // nothing. The retry queue now drains fast (collapse-on-recovery), so it's
    // the right owner of retries; a transient single blip just lands on the
    // queue's short initial backoff (~seconds) instead of a sub-minute freeze.
    log(`Batch sync failed (${messages.length} msgs), queueing for retry: ${errMsg}`);
    retryQueue.add("addMessages", {
      conversationId,
      messages: prepared,
    }, errMsg);
    return { authExpired: false, conversationNotFound: false };
  }
}

function readFileHead(filePath: string, maxBytes: number = 8192): string {
  const fd = fs.openSync(filePath, "r");
  try {
    const buf = Buffer.alloc(maxBytes);
    const bytesRead = fs.readSync(fd, buf, 0, maxBytes, 0);
    return buf.slice(0, bytesRead).toString("utf-8");
  } finally {
    fs.closeSync(fd);
  }
}

function readFileTail(filePath: string, maxBytes: number = 8192): string {
  const stat = fs.statSync(filePath);
  const fd = fs.openSync(filePath, "r");
  try {
    const offset = Math.max(0, stat.size - maxBytes);
    const buf = Buffer.alloc(Math.min(maxBytes, stat.size));
    const bytesRead = fs.readSync(fd, buf, 0, buf.length, offset);
    return buf.slice(0, bytesRead).toString("utf-8");
  } finally {
    fs.closeSync(fd);
  }
}

function readFileHeadAndTail(filePath: string, headBytes: number = 8192, tailBytes: number = 8192): string {
  const stat = fs.statSync(filePath);
  if (stat.size <= headBytes + tailBytes) {
    return fs.readFileSync(filePath, "utf-8");
  }
  const head = readFileHead(filePath, headBytes);
  const tail = readFileTail(filePath, tailBytes);
  return head + "\n" + tail;
}

// Codex stacks a rollout's full fork lineage as the leading run of session_meta records
// (each ~37KB, because base_instructions embeds the whole system prompt), so a fixed-size
// head read can't reach the chain root. Read complete lines from offset 0 until the first
// non-session_meta line, returning just that leading block for extractCodexForkRoot. This
// is position-independent (works on incremental syncs) and bounded by a deep-chain cap.
function readCodexSessionMetaHead(filePath: string): string {
  return timeSyncFs("readCodexSessionMetaHead", filePath, () => readCodexSessionMetaHeadSync(filePath));
}
const CODEX_META_HEAD_CHUNK = 256 * 1024;
const CODEX_META_HEAD_MAX = 16 * 1024 * 1024;
/** Where the leading session_meta block ends: the index just past its last
 *  line, or -1 while no complete non meta line exists yet. */
export function sessionMetaHeadCut(acc: string): number {
  let cut = 0;
  let nl = acc.indexOf("\n");
  while (nl >= 0) {
    const line = acc.slice(cut, nl);
    if (line.trim() && !line.includes('"type":"session_meta"')) return cut;
    cut = nl + 1;
    nl = acc.indexOf("\n", cut);
  }
  return -1;
}
function readCodexSessionMetaHeadSync(filePath: string): string {
  const fd = fs.openSync(filePath, "r");
  try {
    let acc = "";
    let offset = 0;
    while (offset < CODEX_META_HEAD_MAX) {
      const buf = Buffer.alloc(CODEX_META_HEAD_CHUNK);
      const bytesRead = fs.readSync(fd, buf, 0, CODEX_META_HEAD_CHUNK, offset);
      if (bytesRead === 0) break;
      acc += buf.subarray(0, bytesRead).toString("utf-8");
      offset += bytesRead;
      const cut = sessionMetaHeadCut(acc);
      if (cut >= 0) return acc.slice(0, cut);
      if (bytesRead < CODEX_META_HEAD_CHUNK) break; // EOF: whole file is session_meta (or empty)
    }
    return acc;
  } finally {
    fs.closeSync(fd);
  }
}
/** The same head for the metrics tick, read one window at a time off the
 *  loop. Same cap on bytes read; a torn trailing line is left out, which the
 *  metadata parse would have rejected anyway. */
export async function readCodexSessionMetaHeadAsync(filePath: string): Promise<string> {
  const size = (await fs.promises.stat(filePath)).size;
  const limit = Math.min(size, CODEX_META_HEAD_MAX);
  let acc = "";
  let offset = 0;
  while (offset < limit) {
    const { content, bytesConsumed } = await readIngestWindow(filePath, offset, limit - offset, { step: CODEX_META_HEAD_CHUNK });
    if (bytesConsumed === 0) break;
    acc += content;
    offset += bytesConsumed;
    const cut = sessionMetaHeadCut(acc);
    if (cut >= 0) return acc.slice(0, cut);
  }
  return acc;
}

// The leading session_meta block is immutable once written, so a rollout file's fork root
// never changes — cache it per path to avoid re-reading ~200KB on every incremental sync.
const codexForkRootCache = new Map<string, string | undefined>();
// The session metadata comes from the same immutable block, so it is cached
// once it decodes. An undecided read (the record still being written) is not
// cached, or a partial file would answer "no metadata" forever. Throws when
// the file is unreadable, like the head read it wraps.
const codexSessionMetaCache = new Map<string, NonNullable<ReturnType<typeof extractCodexSessionMetadata>>>();
function rememberCodexMeta(filePath: string, head: string): ReturnType<typeof extractCodexSessionMetadata> {
  const meta = extractCodexSessionMetadata(head);
  if (meta) codexSessionMetaCache.set(filePath, meta);
  return meta;
}
function codexSessionMetadataFor(filePath: string): ReturnType<typeof extractCodexSessionMetadata> {
  return codexSessionMetaCache.get(filePath) ?? rememberCodexMeta(filePath, readCodexSessionMetaHead(filePath));
}
/** Fill the metadata cache for a rollout off the loop, so the sync lookup
 *  the metrics tick makes next answers from the cache. */
async function primeCodexSessionMetadata(filePath: string): Promise<void> {
  if (codexSessionMetaCache.has(filePath)) return;
  try {
    rememberCodexMeta(filePath, await readCodexSessionMetaHeadAsync(filePath));
  } catch {
    // unreadable this pass; the sync lookup reports unknown
  }
}
function resolveCodexForkRoot(filePath: string): string | undefined {
  if (codexForkRootCache.has(filePath)) return codexForkRootCache.get(filePath);
  let root: string | undefined;
  try {
    root = extractCodexForkRoot(readCodexSessionMetaHead(filePath));
  } catch {
    root = undefined;
  }
  codexForkRootCache.set(filePath, root);
  return root;
}

// Does this session OWN the process that findSessionProcess resolves for it?
//
// "borrowed" for a Codex subagent THREAD, which has no process of its own: it runs
// inside the parent TUI's process, and the parent is what holds the subagent's
// rollout open — precisely what Strategy A2 matches on, so the lookup returns the
// PARENT's pid and tty.
//
// That answer is CORRECT for reaching the agent (they share a terminal, and the
// subagent's permission prompt renders in the parent's pane), so the injection
// paths deliberately do not consult this. It is wrong for the two things that
// treat a pid as property: attributing the subtree to the subagent double-counts
// it in fleet metrics, and reaping the tree on its behalf SIGKILLs the parent TUI
// and every sibling thread.
//
// Three-valued on purpose. "unknown" is not "owned": a rollout can exist on disk
// with its leading session_meta only PARTIALLY written — that record is ~37KB
// because base_instructions embeds the whole system prompt, while Strategy A2
// matches on the path, which exists the instant the file is created. Reading it
// mid-write yields no metadata, and collapsing that to "owned" would authorize a
// SIGKILL during the exact race the guard exists for. Callers choose the safe
// direction for their side: destructive paths fail closed, metrics fail open.
//
// Memoized only once DECIDED. The leading session_meta is immutable after it is
// fully written (same reasoning as codexForkRootCache), so a decided answer never
// changes; an undecided one must not be cached or the race becomes permanent.
// Note the cost asymmetry this leaves: an undecidable id re-walks findSessionFile
// on every call (~3.5ms), which is deliberate — correctness over a cached guess.
const sessionOwnershipCache = new Map<string, ProcessOwnership>();
// staleOk answers from the session-file index without the recent-changes probe
// (for the metrics tick, which fails open and re-asks). A "no rollout → owned"
// verdict from a possibly stale index is returned but NOT memoized: a rollout
// younger than the index could flip it, and memoizing the guess would hand the
// kill guard a wrong "owned" forever. Destructive callers use the default.
export function sessionProcessOwnership(sessionId: string, opts?: { staleOk?: boolean }): ProcessOwnership {
  const memo = sessionOwnershipCache.get(sessionId);
  if (memo !== undefined) return memo;

  // Ask the Codex rollout store DIRECTLY. Routing this through findSessionFile
  // was a live hole: that helper searches ~/.claude/projects first, and
  // materializeSession writes a CLAUDE-shaped JSONL under a Codex session id
  // (clientOwnsSessionStore excludes codex, so its regeneration skip never fires).
  // A materialized Codex subagent therefore resolved as agentType "claude" →
  // "owned" → memoized, silently restoring the full SIGKILL-the-parent defect and
  // keeping it until daemon restart. The rollout is the authority on what a Codex
  // session is; a materialized mirror is a copy, and must never answer this.
  const rolloutPath = findCodexRolloutPath(sessionId, opts);
  if (!rolloutPath) {
    // No rollout: either a genuinely non-Codex session (only Codex threads can
    // borrow, so it owns its process) or an id we know nothing about yet.
    if (!findSessionFile(sessionId, opts)) return "unknown";
    if (!opts?.staleOk) sessionOwnershipCache.set(sessionId, "owned");
    return "owned";
  }

  let meta: ReturnType<typeof extractCodexSessionMetadata>;
  try {
    meta = codexSessionMetadataFor(rolloutPath);
  } catch {
    return "unknown"; // unreadable this pass
  }
  if (!meta) return "unknown"; // file exists but session_meta isn't complete yet
  const ownership = classifyProcessOwnership(meta);
  if (ownership === "unknown") return "unknown"; // an unrecognized shape may change meaning; don't cache
  sessionOwnershipCache.set(sessionId, ownership);
  return ownership;
}

/** Metrics fail OPEN: only a session we positively know to be a borrower is
 *  denied credit for its subtree. An undecided session keeps reporting — the
 *  worst case is a transiently double-counted tree, not a lost signal. */
// Metrics-side negative memo: an "unknown" verdict re-walks two directory
// scans per call, and collectResourceSnapshot asks for every cached session
// every tick — under load that loop alone froze the event loop 6s (readdirSync,
// 2026-08-21). The kill guard keeps re-asking (it must); metrics, which fail
// open anyway, can reuse an undecided answer for a few minutes.
const borrowsUnknownUntil = new Map<string, number>();
const BORROWS_UNKNOWN_MEMO_MS = 5 * 60_000;
function sessionBorrowsProcess(sessionId: string): boolean {
  const until = borrowsUnknownUntil.get(sessionId);
  if (until !== undefined && until > Date.now()) return false;
  // staleOk: metrics fail open and re-ask; index staleness is within the same
  // few minutes this memo already tolerates. The kill guard asks fresh.
  const ownership = sessionProcessOwnership(sessionId, { staleOk: true });
  if (ownership === "unknown") borrowsUnknownUntil.set(sessionId, Date.now() + BORROWS_UNKNOWN_MEMO_MS);
  else borrowsUnknownUntil.delete(sessionId);
  return ownership === "borrowed";
}

/**
 * The borrowers among `sessionIds`, for the metrics tick. Everything the sync
 * verdict would read from disk is loaded first, off the loop: the session
 * file index (a cold index rebuilt synchronously, 6s at boot under load) and
 * the codex metadata head of every undecided rollout. The verdict itself
 * then answers from memory. A rollout whose head did not decode is memoized
 * as undecided here, so the sync path never re-reads it on the tick.
 */
export async function classifySharedPidSessions(sessionIds: string[]): Promise<Set<string>> {
  await ensureSessionFileIndex();
  const now = Date.now();
  const undecided = sessionIds.filter(
    (id) => !sessionOwnershipCache.has(id) && !((borrowsUnknownUntil.get(id) ?? 0) > now),
  );
  await runBounded(undecided, 4, async (id) => {
    const rollout = findCodexRolloutPath(id, { staleOk: true });
    if (!rollout) return;
    await primeCodexSessionMetadata(rollout);
    if (!codexSessionMetaCache.has(rollout)) borrowsUnknownUntil.set(id, Date.now() + BORROWS_UNKNOWN_MEMO_MS);
  }, "Ownership prime");
  return new Set(sessionIds.filter(sessionBorrowsProcess));
}

// ── Agent-team "spawned by" linking ──────────────────────────────────────────
// A teammate session's JSONL lines carry teamName/agentName stamps. Resolve the
// team's LEAD to a conversation and link the teammate to it as a VISIBLE child
// (conversations.linkSpawnedBy: powers the parent click-through only — no
// subagent nesting/hiding, the teammate stays a first-class inbox card).
//
// Resolving the lead is the hard part: ~/.claude/teams/<team>/config.json
// records leadSessionId, but team creation re-mints the lead's session id, so
// that id almost never matches a synced session. Fast path: the config id
// resolves in the conversation cache. Fallback (works while the team is live):
// the worker's tmux pane and the lead's pane share one tmux session — walk the
// non-member panes' process trees to a pid with a ~/.claude/sessions/<pid>.json
// entry, which names that agent's CURRENT session id.
const teamLinkDone = new Set<string>();
const teamLinkAttempts = new Map<string, number>();
const TEAM_LINK_MAX_ATTEMPTS = 3;

async function resolveTeamLeadConversation(
  teamName: string,
  agentName: string,
  conversationCache: ConversationCache,
): Promise<string | null> {
  let cfg: any;
  try {
    cfg = JSON.parse(
      fs.readFileSync(path.join(process.env.HOME || "", ".claude", "teams", teamName, "config.json"), "utf-8"),
    );
  } catch {
    return null;
  }

  const leadSessionId: string | undefined = cfg?.leadSessionId;
  if (leadSessionId && conversationCache[leadSessionId]) {
    return conversationCache[leadSessionId];
  }

  const members: any[] = Array.isArray(cfg?.members) ? cfg.members : [];
  const me = members.find((m) => m?.name === agentName);
  const memberPanes = new Set<string>(
    members.map((m) => m?.tmuxPaneId).filter((p: any) => typeof p === "string" && p.startsWith("%")),
  );
  const myPane: string | undefined = me?.tmuxPaneId;
  if (!myPane || !myPane.startsWith("%") || !hasTmux()) return null;

  try {
    const { stdout: sessOut } = await tmuxExec(["display-message", "-p", "-t", myPane, "#{session_name}"]);
    const tmuxSession = sessOut.trim();
    if (!tmuxSession) return null;
    const { stdout: panesOut } = await tmuxExec(["list-panes", "-s", "-t", tmuxSession, "-F", "#{pane_id} #{pane_pid}"]);
    const rootPids: number[] = [];
    for (const line of panesOut.trim().split("\n")) {
      const [paneId, pidStr] = line.trim().split(/\s+/);
      if (!paneId || memberPanes.has(paneId)) continue; // teammates' own panes can't be the lead
      const pid = parseInt(pidStr, 10);
      if (!isNaN(pid)) rootPids.push(pid);
    }
    if (rootPids.length === 0) return null;

    // One process snapshot → children map → BFS from the candidate panes' root
    // pids. Any descendant with a ~/.claude/sessions/<pid>.json entry is a live
    // agent whose registry names its current session id.
    const psOut = (await psSnapshotLines(["-axo", "pid=,ppid="])).join("\n");
    const children = new Map<number, number[]>();
    for (const line of psOut.trim().split("\n")) {
      const [pidStr, ppidStr] = line.trim().split(/\s+/);
      const pid = parseInt(pidStr, 10);
      const ppid = parseInt(ppidStr, 10);
      if (isNaN(pid) || isNaN(ppid)) continue;
      if (!children.has(ppid)) children.set(ppid, []);
      children.get(ppid)!.push(pid);
    }
    const queue = [...rootPids];
    const seen = new Set<number>(queue);
    const leadConvIds = new Set<string>();
    while (queue.length > 0) {
      const pid = queue.shift()!;
      for (const child of children.get(pid) ?? []) {
        if (!seen.has(child)) {
          seen.add(child);
          queue.push(child);
        }
      }
      try {
        const regPath = path.join(process.env.HOME || "", ".claude", "sessions", `${pid}.json`);
        if (fs.existsSync(regPath)) {
          const reg = JSON.parse(fs.readFileSync(regPath, "utf-8"));
          const sid = reg?.sessionId;
          if (typeof sid === "string" && conversationCache[sid]) {
            leadConvIds.add(conversationCache[sid]);
          }
        }
      } catch {}
    }
    // Exactly one live non-member agent in this tmux session — that's the lead.
    // Zero or several means we can't tell; stay unlinked rather than guess.
    if (leadConvIds.size === 1) return leadConvIds.values().next().value ?? null;
    return null;
  } catch {
    return null;
  }
}

async function maybeLinkTeamSpawn(
  sessionId: string,
  conversationId: string,
  content: string,
  syncService: SyncService,
  conversationCache: ConversationCache,
): Promise<void> {
  const info = extractTeamInfo(content);
  if (!info) return;
  const attempts = (teamLinkAttempts.get(sessionId) ?? 0) + 1;
  teamLinkAttempts.set(sessionId, attempts);
  if (attempts > TEAM_LINK_MAX_ATTEMPTS) {
    teamLinkDone.add(sessionId);
    return;
  }
  const parentConvId = await resolveTeamLeadConversation(info.teamName, info.agentName, conversationCache);
  if (!parentConvId || parentConvId === conversationId) {
    if (attempts >= TEAM_LINK_MAX_ATTEMPTS) {
      teamLinkDone.add(sessionId);
      log(`Could not resolve lead for teammate ${info.agentName} (${sessionId.slice(0, 8)}, team ${info.teamName}) — leaving unlinked`);
    }
    return;
  }
  await syncService.linkSpawnedBy(parentConvId, conversationId, info.teamName, info.agentName);
  teamLinkDone.add(sessionId);
  log(`Linked teammate ${info.agentName} (${sessionId.slice(0, 8)}) -> lead conversation ${parentConvId.slice(0, 12)} (team ${info.teamName})`);
}

// ── Spawned-agent parent linking (process ancestry) ─────────────────────────
// A headless agent launched by another session's Bash tool (`codex exec ...`,
// `claude -p ...`) writes a brand-new top-level transcript that neither the
// subagents/ path check nor tmux-spawn tracking can attribute — so it used to
// surface as a loose first-class inbox card. While the child runs, though, its
// ppid chain leads to the spawning agent's pid, which Claude Code registers in
// ~/.claude/sessions/<pid>.json with its CURRENT session id. Resolve that to a
// conversation and stamp the child as its subagent. Sessions that fail to
// resolve at creation get a few bounded retries on later sync passes (the
// child process may not have been visible yet), then stay first-class.
const spawnLinkAttempts = new Map<string, number>();
const SPAWN_LINK_MAX_ATTEMPTS = 3;
// Children whose client-native parent pointer (codex review wrapper session,
// opencode task-tool parent_id) named a session with no conversation yet —
// linked retroactively when the parent's conversation syncs.
const pendingNativeParents = new Map<string, { parentSessionId: string; description?: string }>();
const retiringCodexReviews = new Set<string>();

function readPidRegistrySessionId(pid: number): string | null {
  try {
    const regPath = path.join(process.env.HOME || "", ".claude", "sessions", `${pid}.json`);
    if (!fs.existsSync(regPath)) return null;
    const reg = JSON.parse(fs.readFileSync(regPath, "utf-8"));
    return typeof reg?.sessionId === "string" ? reg.sessionId : null;
  } catch {
    return null;
  }
}

// lsof-by-file finds the transcript's writer even when it has no tty, which is
// exactly the headless case findSessionProcess skips by design.
async function pidsWithFileOpen(filePath: string): Promise<number[]> {
  try {
    const { stdout } = await execAsync(`lsof -t -- ${JSON.stringify(filePath)} 2>/dev/null`);
    return stdout
      .trim()
      .split("\n")
      .map((s) => parseInt(s.trim(), 10))
      .filter((n) => !isNaN(n) && n !== process.pid);
  } catch {
    return []; // lsof exits non-zero when nothing has the file open
  }
}

// Identify ancestors that write no pid registry (every client except claude) by
// the transcript each one holds open — one lsof covers the whole chain, and the
// first agent-owned path a process has open names its session.
async function ancestorTranscriptSessionIds(pids: number[]): Promise<Map<number, string>> {
  const byPid = new Map<number, string>();
  if (pids.length === 0) return byPid;
  try {
    const { stdout } = await execAsync(`lsof -p ${pids.join(",")} -F pn 2>/dev/null`);
    for (const [pid, paths] of parseLsofPidPaths(stdout)) {
      for (const openPath of paths) {
        const ref = agentSessionFromTranscriptPath(openPath);
        if (ref) {
          byPid.set(pid, ref.sessionId);
          break;
        }
      }
    }
  } catch {
    // lsof exits non-zero when a pid died mid-walk; the chain just goes unresolved
  }
  return byPid;
}

async function resolveSpawnerConversation(
  filePath: string,
  sessionId: string,
  agentType: AgentClientId,
  conversationCache: ConversationCache,
): Promise<string | null> {
  let pids = await pidsWithFileOpen(filePath);
  if (pids.length === 0) {
    const proc = await findSessionProcess(sessionId, agentType).catch(() => null);
    if (proc) pids = [proc.pid];
  }
  if (pids.length === 0) return null;
  const psOut = (await psSnapshotLines(["-axo", "pid=,ppid="])).join("\n");
  const pidToPpid = parsePidPpidMap(psOut);
  for (const pid of pids) {
    const ancestors = collectAncestorPids(pidToPpid, pid);
    // Claude Code's pid registry first: a plain file read, no subprocess.
    const registrySessionId = resolveSpawnerSessionId(ancestors, readPidRegistrySessionId, sessionId);
    if (registrySessionId && conversationCache[registrySessionId]) {
      return conversationCache[registrySessionId];
    }
    // Then the open-transcript route, which is the only one that can name a
    // codex/gemini/pi spawner (`claude -p` run from a codex exec tool).
    const openTranscripts = await ancestorTranscriptSessionIds(ancestors);
    const openSessionId = resolveSpawnerSessionId(ancestors, (p) => openTranscripts.get(p) ?? null, sessionId);
    if (openSessionId && conversationCache[openSessionId]) {
      return conversationCache[openSessionId];
    }
  }
  return null;
}

// Retry a failed create-time resolution on a later sync pass; links
// retroactively via linkSessions (which no-ops if a parent appeared meanwhile).
async function maybeRetrySpawnLink(
  filePath: string,
  sessionId: string,
  agentType: AgentClientId,
  conversationId: string,
  syncService: SyncService,
  conversationCache: ConversationCache,
): Promise<void> {
  const attempts = spawnLinkAttempts.get(sessionId);
  if (attempts === undefined || attempts >= SPAWN_LINK_MAX_ATTEMPTS) return;
  spawnLinkAttempts.set(sessionId, attempts + 1);
  const parentConvId = await resolveSpawnerConversation(filePath, sessionId, agentType, conversationCache).catch(() => null);
  if (!parentConvId || parentConvId === conversationId) return;
  spawnLinkAttempts.delete(sessionId);
  try {
    await syncService.linkSessions(parentConvId, conversationId);
    log(`Linked spawned ${agentType} session ${sessionId.slice(0, 8)} -> parent ${parentConvId.slice(0, 12)} via process ancestry (retry)`);
  } catch (err) {
    log(`Failed retroactive spawn link for ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
  }
}

async function linkPendingNativeChildren(
  parentSessionId: string,
  parentConversationId: string,
  syncService: SyncService,
  conversationCache: ConversationCache,
): Promise<void> {
  for (const [childSessionId, pending] of pendingNativeParents) {
    if (pending.parentSessionId !== parentSessionId) continue;
    const childConversationId = conversationCache[childSessionId];
    if (!childConversationId) continue;
    await syncService.linkSessions(parentConversationId, childConversationId, pending.description);
    pendingNativeParents.delete(childSessionId);
    log(`Linked native child ${childSessionId.slice(0, 8)} -> parent ${parentSessionId.slice(0, 8)}${pending.description ? ` (${pending.description})` : ""}`);
  }
}

function scheduleCodexReviewRetirement(
  filePath: string,
  sessionId: string,
  conversationId: string,
  syncService: SyncService,
  attempt = 0,
): void {
  if (attempt === 0) {
    if (retiringCodexReviews.has(sessionId)) return;
    retiringCodexReviews.add(sessionId);
  }

  setTimeout(async () => {
    const writers = await pidsWithFileOpen(filePath);
    if (writers.length > 0 && attempt < 12) {
      scheduleCodexReviewRetirement(filePath, sessionId, conversationId, syncService, attempt + 1);
      return;
    }
    if (writers.length > 0) {
      retiringCodexReviews.delete(sessionId);
      log(`Skipped retiring completed Codex review ${sessionId.slice(0, 8)}: transcript still has a live writer`);
      return;
    }
    try {
      await syncService.killFinishedConversation(conversationId);
      log(`Retired completed Codex review ${sessionId.slice(0, 8)} (${conversationId.slice(0, 12)})`);
    } catch (err) {
      log(`Failed to retire completed Codex review ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      retiringCodexReviews.delete(sessionId);
    }
  }, attempt === 0 ? 10_000 : 5_000);
}

const bakImageRecoveryDone = new Set<string>();

function recoverImagesFromBackup(
  messages: ParsedMessage[],
  bakPath: string,
  logFn: (msg: string) => void,
): ParsedMessage[] {
  const unavailableToolIds = new Set<string>();
  for (const msg of messages) {
    if (!msg.toolResults) continue;
    for (const tr of msg.toolResults) {
      if (tr.content === "[result unavailable]") {
        unavailableToolIds.add(tr.toolUseId);
      }
    }
  }
  if (unavailableToolIds.size === 0) return messages;

  let bakContent: string;
  try {
    bakContent = fs.readFileSync(bakPath, "utf-8");
  } catch {
    return messages;
  }

  const bakMessages = parseSessionFile(bakContent);
  const imageMap = new Map<string, { mediaType: string; data: string; toolUseId?: string }>();
  for (const bm of bakMessages) {
    if (!bm.images) continue;
    for (const img of bm.images) {
      if (img.data && img.toolUseId && unavailableToolIds.has(img.toolUseId)) {
        imageMap.set(img.toolUseId, {
          mediaType: img.mediaType,
          data: img.data,
          toolUseId: img.toolUseId,
        });
      }
    }
  }

  if (imageMap.size === 0) return messages;
  logFn(`Recovered ${imageMap.size} images from backup file`);

  for (const msg of messages) {
    if (!msg.toolResults) continue;
    const recovered: typeof msg.images = [];
    for (const tr of msg.toolResults) {
      const img = imageMap.get(tr.toolUseId);
      if (img) {
        recovered.push(img);
      }
    }
    if (recovered.length > 0) {
      msg.images = [...(msg.images || []), ...recovered];
    }
  }

  return messages;
}

/**
 * Resolve which queued subagent→parent links can be established now that
 * `justCreatedSessionId` has been created and cached.
 *
 * Two orderings can leave a subagent orphaned, so both are handled here:
 *  - this session is the PARENT of children still in the pending map, or
 *  - this session is itself a pending CHILD whose parent was created while
 *    our own createConversation await was still in flight (the parent-side
 *    drain ran before we were cached and could not see us).
 *
 * Pure so it can be unit-tested without the daemon's async machinery.
 */
export function resolvePendingSubagentLinks(
  justCreatedSessionId: string,
  justCreatedConvId: string,
  pending: Map<string, string>,
  cache: Record<string, string>,
): Array<{ parentConvId: string; childConvId: string; childSessionId: string; parentSessionId: string }> {
  const links: Array<{ parentConvId: string; childConvId: string; childSessionId: string; parentSessionId: string }> = [];
  for (const [childSessionId, parentSessionId] of pending) {
    if (parentSessionId === justCreatedSessionId) {
      // We are the parent: link any child already cached.
      const childConvId = cache[childSessionId];
      if (childConvId) {
        links.push({ parentConvId: justCreatedConvId, childConvId, childSessionId, parentSessionId });
      }
    } else if (childSessionId === justCreatedSessionId) {
      // We are the child: link to our parent if it is now cached.
      const parentConvId = cache[parentSessionId];
      if (parentConvId) {
        links.push({ parentConvId, childConvId: justCreatedConvId, childSessionId, parentSessionId });
      }
    }
  }
  return links;
}

// Parent session id encoded in a subagent transcript path. Covers both layouts:
// <parent>/subagents/agent-x.jsonl and <parent>/subagents/workflows/<run>/agent-x.jsonl.
export function subagentParentSessionFromPath(filePath: string): string | undefined {
  const parts = filePath.split(path.sep);
  const idx = parts.lastIndexOf("subagents");
  return idx >= 1 ? parts[idx - 1] : undefined;
}

// Cap how many bytes a single sync pass reads from a file. A large unsynced
// backlog (e.g. an old, image-heavy session that gets resumed) used to be re-read
// in full every pass and synced as one all-or-nothing batch — which never completed
// within the sync window on an actively-growing file, so the position never advanced
// and the backlog grew without bound. Reading a bounded window and advancing the
// position after each successfully-synced chunk makes progress monotonic and
// guarantees convergence.
// Per-pass read cap. The read+JSON-parse of a pass is synchronous main-thread work,
// so this bounds the longest single event-loop hold a transcript sync can cause:
// 1MB parses in low hundreds of ms, where the old 4MB slices held the loop for
// seconds each and a backlogged sweep compounded them into minute-long freezes.
const SYNC_BYTES_PER_PASS = 1 * 1024 * 1024;
// How many bounded passes one invocation will chain (with an event-loop yield
// between each) before deferring to the next file-watch event / watchdog. Drains up
// to SYNC_BYTES_PER_PASS * this per trigger — kept at 24MB, matching the old
// 4MB x 6 — so a large idle backlog catches up just as fast, in smaller bites.
export const MAX_SYNC_CONTINUATIONS = 24;

/**
 * Where a read window may be cut: the index of the LAST byte to consume, or
 * -1 to ask for a bigger window. `len` is how many bytes of `buf` are valid;
 * `atEof` says no more bytes exist past them; `from` is the first byte an
 * earlier step of the same window did not already search (bytes before it
 * hold no boundary, so a step costs only the tail it read).
 */
export type PassBoundary = (buf: Buffer, len: number, atEof: boolean, from?: number) => number;

// A newline is one byte and never part of a multibyte sequence, so a byte cut
// at it is charset safe and the byte count needs no re-encode.
const newlineBoundary: PassBoundary = (buf, len, _atEof, from = 0) => {
  const i = buf.subarray(from, len).lastIndexOf(0x0a);
  return i < 0 ? -1 : from + i;
};

type ReadRequest = { buf: Buffer; offset: number; length: number; position: number };

export type ReadWindowOpts = { step?: number; boundary?: PassBoundary; buffer?: Buffer };

// The window algorithm both readers share: fill one window, look for a
// boundary, and when there is none and bytes remain, grow the window and
// read only the new tail. Growth doubles (capped at what exists) so an
// oversized line costs under twice its size in copying and a logarithmic
// number of steps; the boundary search covers only the new tail. Each
// `yield` is one read the driver performs (awaited or synchronous), so the
// async driver frees the loop between steps.
function* completeLinesPlan(
  position: number,
  available: number,
  opts: ReadWindowOpts,
): Generator<ReadRequest, { content: string; bytesConsumed: number; steps: number }, number> {
  const step = opts.step ?? SYNC_BYTES_PER_PASS;
  const boundary = opts.boundary ?? newlineBoundary;
  // allocUnsafe: every byte read below `len` is written by a read first.
  let buf = opts.buffer ?? Buffer.allocUnsafe(Math.min(available, step));
  let len = 0;
  let steps = 0;
  for (;;) {
    const from = len;
    const want = Math.min(buf.length, available) - len;
    const n = want > 0 ? yield { buf, offset: len, length: want, position: position + len } : 0;
    steps++;
    if (n <= 0) available = len; // the file shrank under us: what we hold is all there is
    len += n;
    const atEof = len >= available;
    const cut = len > 0 ? boundary(buf, len, atEof, from) : -1;
    if (cut >= 0) return { content: buf.toString("utf8", 0, cut + 1), bytesConsumed: cut + 1, steps };
    // No boundary at EOF: a line still being written. Consume nothing and let
    // the next pass re-read it (same rule as before the window existed).
    if (atEof) return { content: "", bytesConsumed: 0, steps };
    const grown = Buffer.allocUnsafe(Math.min(Math.max(buf.length * 2, step), available));
    buf.copy(grown, 0, 0, len);
    buf = grown;
  }
}

/**
 * The complete lines available at `position`, read one window at a time.
 * Replaces the old escape that, on a line longer than the window, re-read the
 * whole remaining file in one allocation; now an oversized line costs one
 * more window per step, with the loop free during every read.
 */
export async function readCompleteLines(
  fd: fs.promises.FileHandle,
  position: number,
  available: number,
  opts: ReadWindowOpts = {},
): Promise<{ content: string; bytesConsumed: number; steps: number }> {
  const plan = completeLinesPlan(position, available, opts);
  let r = plan.next(0);
  while (!r.done) {
    const { bytesRead } = await fd.read(r.value.buf, r.value.offset, r.value.length, r.value.position);
    r = plan.next(bytesRead);
  }
  return r.value;
}

/** The synchronous twin, for the hook paths that cannot await. */
export function readCompleteLinesSync(
  fd: number,
  position: number,
  available: number,
  opts: ReadWindowOpts = {},
): { content: string; bytesConsumed: number; steps: number } {
  const plan = completeLinesPlan(position, available, opts);
  let r = plan.next(0);
  while (!r.done) {
    r = plan.next(fs.readSync(fd, r.value.buf, r.value.offset, r.value.length, r.value.position));
  }
  return r.value;
}

/**
 * Drain any remaining known backlog in bounded passes instead of waiting for
 * the next file watch event or the 5 minute watchdog. The caller has already
 * advanced its position, so each continuation is durable forward progress.
 * The setImmediate lets queued work (heartbeats, deliveries, timers) run
 * between passes: each pass parses one window synchronously, and chaining
 * them back to back is what turned big backlogs into event loop freezes.
 */
export async function continueSyncPass(
  lastPosition: number,
  bytesConsumed: number,
  size: number,
  depth: number,
  next: () => Promise<void>,
): Promise<void> {
  if (!(bytesConsumed > 0 && lastPosition + bytesConsumed < size && depth < MAX_SYNC_CONTINUATIONS)) return;
  await new Promise((resolve) => setImmediate(resolve));
  await next();
}

/**
 * The stat every ingest pass starts with. Null means this pass has nothing
 * to do: the file is unreadable for now (logged; the next watch event
 * retries) or gone (logged, so the InvalidateSync backoff completes instead
 * of throwing ENOENT forever, which turned a deleted transcript into a
 * permanent retry loop). A shrink is a rotation and resets to the start.
 */
async function ingestStat(filePath: string, lastPosition: number): Promise<{ size: number; lastPosition: number } | null> {
  let size: number;
  try {
    size = (await fs.promises.stat(filePath)).size;
  } catch (err: any) {
    if (err.code === "EACCES" || err.code === "EPERM") {
      log(`Warning: Permission denied reading ${filePath}. Will retry when permissions are restored.`);
      return null;
    }
    if (err.code === "ENOENT") {
      log(`Transcript ${filePath} no longer exists; nothing to sync.`);
      return null;
    }
    throw err;
  }
  if (size < lastPosition) {
    log(`File rotation detected for ${filePath}: size=${size} < position=${lastPosition}. Resetting to start.`);
    setPosition(filePath, 0);
    lastPosition = 0;
  }
  return { size, lastPosition };
}

/**
 * One window of complete lines from `position`, on a handle held only for
 * the read. The read is async: a 1MB window still blocked the loop 8s when
 * the disk was contended (2026-09-02). The parse the caller does next stays
 * on the loop, which is what SYNC_BYTES_PER_PASS bounds.
 */
async function readIngestWindow(
  filePath: string,
  position: number,
  available: number,
  opts?: { step?: number; boundary?: PassBoundary },
): Promise<{ content: string; bytesConsumed: number; steps: number }> {
  const fd = await fs.promises.open(filePath, "r");
  try {
    return await readCompleteLines(fd, position, available, opts);
  } finally {
    await fd.close().catch(() => {});
  }
}

/**
 * Cut a cursor transcript window just before its last role header, so a
 * message whose lines straddle the window is never synced truncated:
 * parseCursorTranscriptFile buffers lines until the next header, so a newline
 * cut inside a message would sync the first half and drop the rest. At EOF
 * the cut is the last newline, which is what a whole tail read did before.
 */
export const cursorPassBoundary: PassBoundary = (buf, len, atEof, from = 0) => {
  // At EOF the whole window is consumed, so this is the one full search.
  if (atEof) return newlineBoundary(buf, len, atEof, 0);
  const end = newlineBoundary(buf, len, atEof, from);
  if (end < 0) return -1; // the tail added no complete line, so no new header
  // Only a line the window holds whole can be a header: past the last
  // newline, "user:" may be the start of a content line still to come. The
  // header rule is the parser's own, so the cut and the parse agree. Lines
  // whole before `from` were judged by an earlier step, so decode from the
  // line that straddles it.
  const lineStart = from > 0 ? buf.lastIndexOf(0x0a, from - 1) + 1 : 0;
  const lines = buf.toString("utf8", lineStart, end).split("\n");
  let headerAt = -1;
  let bytes = lineStart;
  for (const l of lines) {
    if (bytes > 0 && isCursorRoleHeaderLine(l)) headerAt = bytes;
    bytes += Buffer.byteLength(l, "utf8") + 1;
  }
  // The byte before the header line is the newline that ends the previous one.
  return headerAt < 0 ? -1 : headerAt - 1;
};

export async function processSessionFile(
  filePath: string,
  sessionId: string,
  projectPath: string,
  syncService: SyncService,
  userId: string,
  teamId: string | undefined,
  conversationCache: ConversationCache,
  retryQueue: RetryQueue,
  pendingMessages: PendingMessages,
  titleCache: TitleCache,
  updateStateCallback: () => void,
  parentConversationId?: string,
  overrideAgentType?: "claude_code",
  continuationDepth: number = 0,
): Promise<void> {
  const isSubagent = filePath.split(path.sep).includes("subagents");
  const stats = await ingestStat(filePath, getPosition(filePath));
  if (!stats) return;
  const lastPosition = stats.lastPosition;

  if (stats.size <= lastPosition) {
    // Nothing new to read, but the watchdog uses sync-ledger.json (NOT
    // positions.json) to decide which files are "stale". shouldTreatClaudeFileAsStale
    // flags a file when mtime > lastSyncedAt, so a file whose mtime was TOUCHED
    // without any bytes appended (compact-in-place, a `touch`, clock skew) used to
    // re-detect as stale every 5-min watchdog pass forever — burning event-loop time
    // and head-of-line-blocking incoming Convex commands (start_session etc.). The
    // old heal only ran when the position MOVED, so an mtime-only touch never
    // advanced the baseline. Advance lastSyncedAt (and lastSyncedPosition to the read
    // position) on EVERY no-op pass so the touch isn't re-flagged. We confirmed
    // size <= position here, so there is genuinely no unsynced tail — this can't mask
    // real content. Merge (not markSynced) so messageCount/conversationId aren't
    // clobbered to zero.
    const existing = getSyncRecord(filePath);
    const knownConvId = conversationCache[sessionId];
    updateSyncRecord(filePath, {
      lastSyncedAt: Date.now(),
      lastSyncedPosition: Math.max(existing?.lastSyncedPosition ?? 0, lastPosition),
      ...(knownConvId ? { conversationId: knownConvId } : {}),
    });
    return;
  }

  try {
    // One SYNC_BYTES_PER_PASS window of complete lines, so a large backlog
    // drains in bounded, convergent steps (see constant above) rather than
    // one giant batch. A trailing partial line (a large entry still being
    // written) is left for the next pass.
    const { content: newContent, bytesConsumed } = await readIngestWindow(filePath, lastPosition, stats.size - lastPosition);

    if (!newContent) {
      // No complete lines yet — don't advance position
      return;
    }
    const LARGE_BATCH_BYTES = 64 * 1024;
    if (bytesConsumed >= LARGE_BATCH_BYTES) {
      log(`Processing ${bytesConsumed} bytes for session ${sessionId.slice(0, 8)} (from position ${lastPosition})`);
    }
    let messages = parseTranscriptFor("claude", newContent);

    const bakPath = filePath + ".bak";
    if (!bakImageRecoveryDone.has(filePath) && fs.existsSync(bakPath)) {
      bakImageRecoveryDone.add(filePath);
      messages = recoverImagesFromBackup(messages, bakPath, log);
    }

    if (permissionJustResolved.has(sessionId)) {
      const before = messages.length;
      messages = messages.filter(m => !(m.role === "user" && /^[yn]$/i.test(m.content?.trim())));
      if (messages.length < before) {
        log(`Filtered ${before - messages.length} permission response message(s) for session ${sessionId.slice(0, 8)}`);
      }
      permissionJustResolved.delete(sessionId);
    }

    let conversationId = conversationCache[sessionId];

    // Check for summary title using the already-read new chunk + small tail read
    if (conversationId) {
      let titleContent: string;
      try {
        titleContent = newContent + "\n" + readFileTail(filePath, 4096);
      } catch (err: any) {
        if (err.code === 'EACCES' || err.code === 'EPERM') {
          log(`Warning: Permission denied reading ${filePath} for title update. Skipping.`);
          setPosition(filePath, lastPosition + bytesConsumed);
          return;
        }
        throw err;
      }
      const summaryTitle = extractSummaryTitle(titleContent);
      if (summaryTitle && titleCache[sessionId] !== summaryTitle) {
        try {
          await syncService.updateTitle(conversationId, summaryTitle);
          titleCache[sessionId] = summaryTitle;
          saveTitleCache(titleCache);
          log(`Updated title for session ${sessionId}: ${summaryTitle}`);
        } catch (err) {
          const errMsg = err instanceof Error ? err.message : String(err);
          log(`Failed to update title: ${errMsg}`);
        }
      }

      if (!planHandoffChecked.has(sessionId)) {
        planHandoffChecked.add(sessionId);
        let headContent: string;
        try {
          headContent = readFileHead(filePath, 16384);
        } catch { headContent = ""; }
        const headMessages = parseSessionFile(headContent);
        const userMsgs = headMessages.filter(m => m.role === "user").slice(0, 3);
        for (const msg of userMsgs) {
          if (!msg.content) continue;
          const handoffMatch = msg.content.match(/read the full transcript at:\s*([^\s]+\.jsonl)/i);
          if (handoffMatch) {
            const jsonlPath = handoffMatch[1];
            const parentSessionMatch = jsonlPath.match(/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.jsonl$/);
            if (parentSessionMatch) {
              const parentSessionId = parentSessionMatch[1];
              const parentConvId = conversationCache[parentSessionId];
              if (parentConvId) {
                try {
                  await syncService.linkPlanHandoff(parentConvId, conversationId);
                  planHandoffChildren.set(parentConvId, conversationId);
                  log(`Retroactive plan handoff: linked ${sessionId.slice(0, 8)} -> parent ${parentSessionId.slice(0, 8)}`);
                } catch (err) {
                  log(`Failed retroactive plan handoff link: ${err instanceof Error ? err.message : String(err)}`);
                }
              }
            }
            break;
          }
        }
      }
    }

  if (messages.length === 0) {
    setPosition(filePath, lastPosition + bytesConsumed);
    return;
  }

  if (!conversationId) {
    let headContent: string;
    try {
      headContent = readFileHead(filePath, 16384);
    } catch (err: any) {
      if (err.code === 'EACCES' || err.code === 'EPERM') {
        log(`Warning: Permission denied reading ${filePath} for conversation creation. Skipping.`);
        return;
      }
      throw err;
    }

    // The exact params the direct create attempts, kept for the catch block: a
    // failed create must retry with THIS object, not a rebuilt reduced one.
    let createParams: CreateConversationParams | null = null;
    try {
      const slug = extractSlug(headContent);
      const parentMessageUuid = extractParentUuid(headContent);
      const firstMessageTimestamp = messages[0]?.timestamp;
      const dirName = path.basename(path.dirname(filePath));
      const decodedPath = dirName ? decodeProjectDirName(dirName) : undefined;
      const actualProjectPath = pickProjectPath({
        decodedSlugPath: decodedPath || projectPath,
        recordedCwd: extractCwd(headContent),
        home: process.env.HOME,
      });
      const gitInfo = actualProjectPath ? await getGitInfo(actualProjectPath) : undefined;

      const firstUserMessage = messages.find(msg => msg.role === "user");
      const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

      // Detect parent conversation from file path (subagents/) or content (plan handoff)
      let isPlanHandoff = false;
      if (!parentConversationId) {
        const parentSessionId = subagentParentSessionFromPath(filePath);
        if (parentSessionId && conversationCache[parentSessionId]) {
          parentConversationId = conversationCache[parentSessionId];
          log(`Detected subagent parent for ${sessionId}: ${parentConversationId}`);
        } else if (parentSessionId) {
          pendingSubagentParents.set(sessionId, parentSessionId);
          log(`Subagent ${sessionId} parent ${parentSessionId} not cached yet, queued for linking`);
        }
      }
      if (!parentConversationId) {
        const userMessages = messages.filter(msg => msg.role === "user").slice(0, 3);
        for (const msg of userMessages) {
          if (!msg.content) continue;
          const handoffMatch = msg.content.match(/read the full transcript at:\s*([^\s]+\.jsonl)/i);
          if (handoffMatch) {
            const jsonlPath = handoffMatch[1];
            const parentSessionMatch = jsonlPath.match(/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.jsonl$/);
            if (parentSessionMatch) {
              const parentSessionId = parentSessionMatch[1];
              if (conversationCache[parentSessionId]) {
                parentConversationId = conversationCache[parentSessionId];
                isPlanHandoff = true;
                log(`Detected plan handoff parent for ${sessionId}: ${parentConversationId} (from ${parentSessionId})`);
              }
            }
            break;
          }
        }
      }

      // Detect parent from tmux spawn tracking (agent-spawn.sh / tmux new-session called by another session)
      if (!parentConversationId && tmuxSpawnedBySession.size > 0) {
        const spawnProc = await findSessionProcess(sessionId, "claude").catch(() => null);
        if (spawnProc) {
          let childTmuxName = sessionProcessCache.get(sessionId)?.tmuxTarget?.split(":")[0] ?? null;
          if (!childTmuxName) {
            const pane = await findTmuxPaneForTty(spawnProc.tty);
            if (pane) {
              childTmuxName = pane.split(":")[0];
              cacheSessionProcess(sessionId, spawnProc, pane);
            }
          }
          if (childTmuxName && tmuxSpawnedBySession.has(childTmuxName)) {
            parentConversationId = tmuxSpawnedBySession.get(childTmuxName)!;
            log(`Detected tmux-spawned parent for ${sessionId.slice(0, 8)}: ${parentConversationId.slice(0, 12)} via tmux session ${childTmuxName}`);
          }
        }
      }

      if (!conversationId) {
        const freshCache = readConversationCache();
        if (freshCache[sessionId]) {
          conversationId = freshCache[sessionId];
          conversationCache[sessionId] = conversationId;
          log(`Session ${sessionId.slice(0, 8)} already linked to ${conversationId.slice(0, 12)} by background discovery, skipping match`);
        }
      }

      let matchedStartedConversation: string | null = null;
      if (!conversationId && startedSessionTmux.size > 0 && !isSubagent && !parentConversationId) {
        const startedClaudeEntries = Array.from(startedSessionTmux.entries())
          .filter(([, entry]) => entry.agentType === "claude");
        const proc = await findSessionProcess(sessionId, "claude").catch(() => null);
        let tmuxSessionName: string | null = null;
        if (proc) {
          tmuxSessionName = sessionProcessCache.get(sessionId)?.tmuxTarget?.split(":")[0] ?? null;
          if (!tmuxSessionName) {
            const tmuxPane = await findTmuxPaneForTty(proc.tty);
            if (tmuxPane) {
              tmuxSessionName = tmuxPane.split(":")[0];
              cacheSessionProcess(sessionId, proc, tmuxPane);
            }
          }
        }
        matchedStartedConversation = matchStartedConversation(startedClaudeEntries, {
          tmuxSessionName,
          // Only allow the cwd fallback when the process wasn't found at all
          // (still spawning). A located process that isn't in our tmux belongs
          // to someone else — see matchStartedConversation.
          projectPath: proc ? null : actualProjectPath,
        });
        if (matchedStartedConversation && tmuxSessionName) {
          log(`Matched session ${sessionId.slice(0, 8)} to conversation ${matchedStartedConversation.slice(0, 12)} via tmux ${tmuxSessionName}`);
        } else if (matchedStartedConversation && actualProjectPath) {
          log(`Matched session ${sessionId.slice(0, 8)} to conversation ${matchedStartedConversation.slice(0, 12)} via projectPath fallback`);
        }
      }

      // Re-check after async gap: discoverAndLinkSession may have linked during findSessionProcess/findTmuxPaneForTty
      if (!conversationId && conversationCache[sessionId]) {
        conversationId = conversationCache[sessionId];
        matchedStartedConversation = null;
        log(`Session ${sessionId.slice(0, 8)} already linked to ${conversationId.slice(0, 12)} by discovery (post-async), skipping match/create`);
      }

        if (conversationId) {
          // Already linked by background discovery — skip matching and creation
        } else if (matchedStartedConversation) {
          conversationId = matchedStartedConversation;
          const tmuxEntry = startedSessionTmux.get(matchedStartedConversation);
          conversationCache[sessionId] = conversationId;
          saveConversationCache(conversationCache);
          // Reconcile project_path/git_root to the real session cwd: the stub
          // was created (e.g. from the web) before this session existed, so its
          // stored path is a guess that may not match where the session runs.
          void pushSessionIdBinding(conversationId, sessionId, actualProjectPath || undefined, gitInfo?.repoRoot || gitInfo?.root);
          if (tmuxEntry) {
          registerManagedStartedSession(conversationId, sessionId, tmuxEntry.tmuxSession);
          if (tmuxEntry.sessionId && tmuxEntry.sessionId !== sessionId) {
            stopManagedSessionHeartbeat(tmuxEntry.sessionId);
          }
          }
          deleteStartedSession(matchedStartedConversation);
          log(`Linked session ${sessionId} to existing started conversation ${conversationId}`);
        if (parentConversationId) {
          syncService.linkSessions(parentConversationId, conversationId, subagentDescriptions.get(sessionId)).then(() => {
            log(`Linked started conversation ${conversationId.slice(0, 12)} to parent ${parentConversationId!.slice(0, 12)}`);
          }).catch((err) => {
            log(`Failed to link started conversation to parent: ${err}`);
          });
        }
      } else if (isForkArtifactSessionId(sessionId)) {
        // A forked-* JSONL with no conversation mapping is a reconstitution
        // artifact whose binding moved to its UUID copy (see
        // removeForkArtifactJsonl). Minting a conversation here creates a
        // frozen doppelgänger that receives input but never output. Skip it,
        // and advance position + ledger so the stale-file scan doesn't
        // re-detect the file forever.
        setPosition(filePath, stats.size);
        markSynced(filePath, stats.size, 0);
        log(`Skipped conversation creation for fork artifact ${sessionId.slice(0, 28)} (${filePath})`);
        return;
      } else {
        const cliFlags = detectCliFlags(headContent + "\n" + newContent);
        let subagentDescription: string | undefined;
        let subagentAgentType: string | undefined;
        if (isSubagent) {
          try {
            const metaPath = filePath.replace(/\.jsonl$/, ".meta.json");
            if (fs.existsSync(metaPath)) {
              const meta = JSON.parse(fs.readFileSync(metaPath, "utf-8"));
              if (meta.description) {
                subagentDescription = meta.description;
                subagentDescriptions.set(sessionId, meta.description);
              }
              if (meta.agentType) subagentAgentType = meta.agentType;
            }
          } catch {}
        }
        // Teammate transcripts self-identify on every line — stamp the team
        // identity at create so the row never exists without it. The parent
        // LINK still happens via maybeLinkTeamSpawn below (lead resolution).
        const teamInfo = !isSubagent && newContent.includes('"teamName"') ? extractTeamInfo(newContent) : undefined;
        // A headless claude child (`claude -p` run from another session's Bash)
        // nests under its spawner as a subagent. Fork lineage (parentMessageUuid)
        // and agent-team teammates keep their first-class semantics — teammates
        // link via linkSpawnedBy, never via parent_conversation_id.
        if (!parentConversationId && !isSubagent && !parentMessageUuid && !teamInfo) {
          try {
            const spawnerConvId = await resolveSpawnerConversation(filePath, sessionId, "claude", conversationCache);
            if (spawnerConvId) {
              parentConversationId = spawnerConvId;
              log(`Detected spawned claude session ${sessionId.slice(0, 8)} -> parent ${spawnerConvId.slice(0, 12)} via process ancestry`);
            }
          } catch {}
          if (!parentConversationId) spawnLinkAttempts.set(sessionId, 1);
        }
        createParams = {
          userId,
          teamId,
          sessionId,
          agentType: overrideAgentType || "claude_code",
          projectPath: actualProjectPath,
          slug,
          title,
          startedAt: firstMessageTimestamp,
          parentMessageUuid: isPlanHandoff ? "plan-handoff" : (parentConversationId ? undefined : parentMessageUuid),
          parentConversationId,
          gitInfo,
          cliFlags: cliFlags || undefined,
          subagentDescription,
          // Path-derived: true even when the parent conversation isn't cached
          // yet, so the server never briefly sees this as a top-level session.
          isSubagent: isSubagent || undefined,
          agentTeamName: teamInfo?.teamName,
          agentName: teamInfo?.agentName,
        };
        conversationId = await syncService.createConversation(createParams);
        conversationCache[sessionId] = conversationId;
        saveConversationCache(conversationCache);
        if (isPlanHandoff && parentConversationId) {
          planHandoffChildren.set(parentConversationId, conversationId);
          log(`Registered plan handoff: parent ${parentConversationId.slice(0, 12)} -> child ${conversationId.slice(0, 12)}`);
        }
        log(`Created conversation ${conversationId} for session ${sessionId}`);
        syncStats.conversationsCreated++;
        syncSkillsForConversation(conversationId, actualProjectPath, syncService);

        // Create plan entity for Plan-type subagents and bind to parent conversation
        if (subagentAgentType === "Plan" && parentConversationId && !planModeSynced.has(sessionId)) {
          planModeSynced.add(sessionId);
          const parentSessionUuid = subagentParentSessionFromPath(filePath);
          if (parentSessionUuid) {
            syncService.syncPlanFromPlanMode({
              sessionId: parentSessionUuid,
              planContent: `# ${subagentDescription || "Plan"}`,
              projectPath: actualProjectPath,
            }).then((planShortId) => {
              if (planShortId) {
                planModePlanMap.set(sessionId, planShortId);
                savePlanModeCache();
                log(`Created plan ${planShortId} for Plan subagent ${sessionId.slice(0, 8)}, bound to parent ${parentSessionUuid.slice(0, 8)}`);
              }
            }).catch((err) => {
              log(`Failed to create plan for Plan subagent: ${err instanceof Error ? err.message : String(err)}`);
            });
          }
        }

        // Detect tmux and register managed session
        findSessionProcess(sessionId, "claude").then((proc) => {
          if (!proc) return;
          findTmuxPaneForTty(proc.tty).then((tmuxPane) => {
            const tmuxSessionName = tmuxPane?.split(":")[0];
            syncService.registerManagedSession(sessionId, proc.pid, tmuxSessionName, conversationId).catch(logConvexFailure);
            if (tmuxSessionName) log(`Registered managed session for ${sessionId.slice(0, 8)} (tmux: ${tmuxSessionName})`);
          }).catch(() => {
            syncService.registerManagedSession(sessionId, process.pid, undefined, conversationId).catch(logConvexFailure);
          });
        }).catch(() => {
          syncService.registerManagedSession(sessionId, process.pid, undefined, conversationId).catch(logConvexFailure);
        });

        // Resolve pending subagent links now that this session is cached —
        // both when it is the parent of queued children AND when it is itself a
        // queued child whose parent appeared during our in-flight create.
        for (const link of resolvePendingSubagentLinks(sessionId, conversationId, pendingSubagentParents, conversationCache)) {
          syncService.linkSessions(link.parentConvId, link.childConvId, subagentDescriptions.get(link.childSessionId)).then(() => {
            log(`Linked pending subagent ${link.childSessionId.slice(0, 8)} -> parent ${link.parentSessionId.slice(0, 8)}`);
          }).catch((err) => {
            log(`Failed to link subagent ${link.childSessionId.slice(0, 8)}: ${err}`);
          });
          pendingSubagentParents.delete(link.childSessionId);
        }
      }

      if ((global as any).activeSessions) {
        (global as any).activeSessions.set(conversationId, {
          sessionId,
          conversationId,
          projectPath: actualProjectPath || "",
        });
      }

      if (pendingMessages[sessionId]) {
        await flushPendingMessagesBatch(pendingMessages[sessionId], conversationId, syncService, retryQueue);
        delete pendingMessages[sessionId];
      }

      // Agent-team teammate? Link it to its lead as a visible child (once).
      // Cheap string gate first — only teammate transcripts carry the stamp.
      if (!isSubagent && !teamLinkDone.has(sessionId) && newContent.includes('"teamName"')) {
        maybeLinkTeamSpawn(sessionId, conversationId, newContent, syncService, conversationCache).catch((err) => {
          log(`Teammate link attempt failed for ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
        });
      }
    } catch (err) {
      if (err instanceof AuthExpiredError) {
        if (handleAuthFailure()) {
          log("⚠️  Authentication expired - sync paused");
          setPosition(filePath, lastPosition + bytesConsumed);
          return;
        }
        // Let it fall through to retry queue
      }

      const errMsg = err instanceof Error ? err.message : String(err);
      log(`Failed to create conversation, queueing for retry: ${errMsg}`);

      if (!pendingMessages[sessionId]) {
        pendingMessages[sessionId] = [];
      }
      for (const msg of messages) {
        pendingMessages[sessionId].push({
          uuid: msg.uuid,
          role: msg.role === "user" ? "human" : msg.role === "system" ? "system" : "assistant",
          content: redactSecrets(msg.content),
          timestamp: msg.timestamp,
          filePath,
          fileSize: stats.size,
          thinking: msg.thinking,
          toolCalls: msg.toolCalls,
          toolResults: msg.toolResults,
          images: msg.images,
          subtype: msg.subtype,
          model: msg.model,
        });
      }

      // A subagent whose create failed must stay re-parentable no matter what
      // the retry ends up sending (e.g. a stale persisted op from an older
      // daemon): the pending-link sweep re-links it once both sides are cached.
      // jx70pyh (2026-07-29): a network blip here minted a workflow agent as a
      // flat, unparented conversation because the retry op dropped the parent.
      const subagentParentSession = subagentParentSessionFromPath(filePath);
      if (subagentParentSession) {
        pendingSubagentParents.set(sessionId, subagentParentSession);
      }

      if (createParams) {
        // Retry exactly what the direct call attempted — rebuilding a reduced
        // param set here silently dropped parentConversationId/isSubagent.
        retryQueue.add("createConversation", createParams as unknown as Record<string, unknown>, errMsg);
        setPosition(filePath, lastPosition + bytesConsumed);
        return;
      }

      // Create failed before the params were assembled — rebuild what we can.
      let retryHeadContent: string;
      try {
        retryHeadContent = readFileHead(filePath, 16384);
      } catch (readErr: any) {
        if (readErr.code === 'EACCES' || readErr.code === 'EPERM') {
          log(`Warning: Permission denied reading ${filePath} for retry queue. Skipping.`);
          setPosition(filePath, lastPosition + bytesConsumed);
          return;
        }
        throw readErr;
      }

      const slug = extractSlug(retryHeadContent);
      const firstMsgTimestamp = messages[0]?.timestamp;
      const retryDirName = path.basename(path.dirname(filePath));
      const retryDecoded = retryDirName ? decodeProjectDirName(retryDirName) : undefined;
      const retryProjectPath = pickProjectPath({
        decodedSlugPath: retryDecoded || projectPath,
        recordedCwd: extractCwd(retryHeadContent),
        home: process.env.HOME,
      });
      const gitInfo = retryProjectPath ? await getGitInfo(retryProjectPath) : undefined;

      retryQueue.add("createConversation", {
        userId,
        teamId,
        sessionId,
        agentType: overrideAgentType || "claude_code",
        projectPath: retryProjectPath,
        slug,
        startedAt: firstMsgTimestamp,
        gitInfo,
        isSubagent: isSubagent || undefined,
      }, errMsg);

      setPosition(filePath, lastPosition + bytesConsumed);
      return;
    }
  }

  // Spawned-child link that failed at creation (child process not visible
  // yet) — bounded retries on later passes, no-op once resolved or exhausted.
  if (conversationId && spawnLinkAttempts.has(sessionId)) {
    maybeRetrySpawnLink(filePath, sessionId, "claude", conversationId, syncService, conversationCache).catch(() => {});
  }

  // Intercept plan mode tool calls (ExitPlanMode, TaskCreate, TaskUpdate) and sync to Convex
  if (conversationId && (newContent.includes("ExitPlanMode") || newContent.includes("TaskCreate") || newContent.includes("TaskUpdate"))) {
    const lines = newContent.split("\n");
    for (const line of lines) {
      if (!line.includes("ExitPlanMode") && !line.includes("TaskCreate") && !line.includes("TaskUpdate")) continue;
      try {
        const entry = JSON.parse(line);
        const msg = entry.message || entry;
        const blocks = Array.isArray(msg.content) ? msg.content : [];
        for (const block of blocks) {
          if (block.type !== "tool_use") continue;

          if (block.name === "ExitPlanMode" && block.input?.plan && !planModeSynced.has(sessionId)) {
            planModeSynced.add(sessionId);
            const dirName = path.basename(path.dirname(filePath));
            const projPath = dirName ? resolveTranscriptProjectPath(filePath, dirName) : undefined;
            try {
              const planShortId = await syncService.syncPlanFromPlanMode({
                sessionId,
                planContent: block.input.plan,
                projectPath: projPath,
              });
              if (planShortId) {
                planModePlanMap.set(sessionId, planShortId);
                savePlanModeCache();
              }
              log(`Synced plan_mode plan ${planShortId} for session ${sessionId.slice(0, 8)} (${block.input.plan.length} chars)`);
            } catch (err) {
              log(`Failed to sync plan_mode: ${err instanceof Error ? err.message : String(err)}`);
            }
          }

          if (block.name === "TaskCreate" && block.input?.subject) {
            const taskMap = planModeTaskMap.get(sessionId) || new Map();
            const localId = String(taskMap.size + 1);
            try {
              const shortId = await syncService.syncTaskFromPlanMode({
                sessionId,
                title: block.input.subject,
                description: block.input.description,
                planShortId: planModePlanMap.get(sessionId),
              });
              if (shortId) {
                taskMap.set(localId, shortId);
                planModeTaskMap.set(sessionId, taskMap);
                savePlanModeCache();
                log(`Synced task ${shortId} from TaskCreate in session ${sessionId.slice(0, 8)}: ${block.input.subject}`);
              }
            } catch (err) {
              log(`Failed to sync TaskCreate: ${err instanceof Error ? err.message : String(err)}`);
            }
          }

          if (block.name === "TaskUpdate" && block.input?.taskId && block.input?.status) {
            const taskMap = planModeTaskMap.get(sessionId);
            const shortId = taskMap?.get(String(block.input.taskId));
            if (shortId) {
              const rawStatus = String(block.input.status);
              const statusMap: Record<string, string> = {
                pending: "open",
                open: "open",
                backlog: "backlog",
                in_progress: "in_progress",
                in_review: "in_review",
                completed: "done",
                done: "done",
                deleted: "dropped",
                cancelled: "dropped",
                dropped: "dropped",
              };
              const status = statusMap[rawStatus];
              if (!status) {
                log(`Skipping TaskUpdate sync for ${shortId}: unknown status "${rawStatus}"`);
              } else {
                try {
                  await syncService.updateTaskStatus(shortId, status, sessionId);
                  log(`Updated task ${shortId} -> ${status} in session ${sessionId.slice(0, 8)}`);
                } catch (err) {
                  log(`Failed to sync TaskUpdate: ${err instanceof Error ? err.message : String(err)}`);
                }
              }
            }
          }
        }
      } catch {}
    }
  }

  // Detect tmux session spawns in bash tool calls (agent-spawn.sh, tmux new-session)
  if (conversationId && (newContent.includes("agent-spawn") || newContent.includes("tmux new-session") || newContent.includes("new-session"))) {
    const spawnLines = newContent.split("\n");
    for (const spawnLine of spawnLines) {
      if (!spawnLine.includes("agent-spawn") && !spawnLine.includes("new-session")) continue;
      try {
        const entry = JSON.parse(spawnLine);
        const msg = entry.message || entry;
        const blocks = Array.isArray(msg.content) ? msg.content : [];
        for (const block of blocks) {
          if (block.type !== "tool_use") continue;
          const cmd = block.input?.command;
          if (typeof cmd !== "string") continue;
          let spawnMatch = cmd.match(/agent-spawn(?:\.sh)?\s+\S+\s+["']?([^\s"']+)["']?/);
          if (!spawnMatch) {
            spawnMatch = cmd.match(/tmux\s+new-session\s+(?:.*?\s)?-s\s+["']?([^\s"']+)["']?/);
          }
          if (spawnMatch) {
            const tmuxName = spawnMatch[1];
            tmuxSpawnedBySession.set(tmuxName, conversationId);
            log(`Tracked tmux spawn: ${tmuxName} -> parent ${conversationId.slice(0, 12)}`);
            // Retroactively link if child session was already created
            for (const [childSid, info] of sessionProcessCache) {
              if (info.tmuxTarget?.split(":")[0] === tmuxName && conversationCache[childSid]) {
                const childConvId = conversationCache[childSid];
                syncService.linkSessions(conversationId, childConvId).then(() => {
                  log(`Retroactively linked tmux-spawned child ${childSid.slice(0, 8)} -> parent ${conversationId.slice(0, 12)}`);
                }).catch(err => {
                  log(`Failed retroactive tmux spawn link: ${err instanceof Error ? err.message : String(err)}`);
                });
              }
            }
          }
        }
      } catch {}
    }
  }

  syncSkillsForConversation(conversationId, projectPath, syncService);

  // A delivered user turn (typed, injected, or a harness wake) starts a turn
  // and spends any declared settle verdict from before it — the transcript is
  // the authority, not sync success, so this precedes the batch send. Subagent
  // transcripts sync under their own session id, so a workflow's internal
  // turns never move the parent session's mark.
  if (!isSubagent) {
    const turnTs = latestTurnStartTs(messages);
    if (turnTs !== null) markTurnStarted(sessionId, turnTs);
  }

  const batchResult = await syncMessagesBatch(messages, conversationId, syncService, retryQueue);
  if (batchResult.authExpired) {
    log("⚠️  Authentication expired - sync paused");
    return;
  }
  if (batchResult.conversationNotFound) {
    log(`Conversation ${conversationId} not found, invalidating cache and recreating...`);
    delete conversationCache[sessionId];
    saveConversationCache(conversationCache);

    let recreateHeadContent: string;
    try {
      recreateHeadContent = readFileHead(filePath, 16384);
    } catch (readErr: any) {
      if (readErr.code === 'EACCES' || readErr.code === 'EPERM') {
        log(`Warning: Permission denied reading ${filePath} for conversation recreation. Skipping.`);
        setPosition(filePath, lastPosition + bytesConsumed);
        return;
      }
      throw readErr;
    }

    const slug = extractSlug(recreateHeadContent);
    const firstMessageTimestamp = messages[0]?.timestamp;
    const recreateDirName = path.basename(path.dirname(filePath));
    const recreateDecoded = recreateDirName ? decodeProjectDirName(recreateDirName) : undefined;
    const recreateProjectPath = pickProjectPath({
      decodedSlugPath: recreateDecoded || projectPath,
      recordedCwd: extractCwd(recreateHeadContent),
      home: process.env.HOME,
    });
    const gitInfo = recreateProjectPath ? await getGitInfo(recreateProjectPath) : undefined;

    try {
      const firstUserMessage = messages.find(msg => msg.role === "user");
      const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

      conversationId = await syncService.createConversation({
        userId,
        teamId,
        sessionId,
        agentType: overrideAgentType || "claude_code",
        projectPath: recreateProjectPath,
        slug,
        title,
        startedAt: firstMessageTimestamp,
        gitInfo,
      });
      conversationCache[sessionId] = conversationId;
      saveConversationCache(conversationCache);
      log(`Recreated conversation ${conversationId} for session ${sessionId}`);

      await syncService.addMessages({
        conversationId,
        messages: messages.map(prepMessageForSync),
      });
    } catch (retryErr) {
      const retryErrMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
      log(`Failed to recreate conversation and add messages: ${retryErrMsg}`);
    }
  }

    setPosition(filePath, lastPosition + bytesConsumed);
    markSynced(filePath, lastPosition + bytesConsumed, messages.length, conversationId);
    log(`Synced ${messages.length} messages for session ${sessionId}`);
    syncStats.messagesSynced += messages.length;
    syncStats.sessionsActive.add(sessionId);
    tryRegisterSessionProcess(sessionId, "claude");

    const askTc = messages.flatMap(m => m.toolCalls || []).find((tc: any) => tc.name === "AskUserQuestion");
    if (askTc && !pendingInteractivePrompts.has(sessionId)) {
      const inp = askTc.input as any;
      const options = inp?.questions?.[0]?.options || [];
      pendingInteractivePrompts.set(sessionId, { timestamp: Date.now(), options });
      log(`AskUserQuestion in JSONL for ${sessionId.slice(0, 8)}, set pending prompt guard`);
      if (conversationId) {
        sendAgentStatus(syncService, conversationId, sessionId, "permission_blocked");
      }
    }

    const lastMessage = messages[messages.length - 1];
    const wasInterrupted = lastMessage?.role === "user" &&
      isInterruptControlMessage(lastMessage.content);

    const lastAssistantMessage = messages.filter(m => m.role === "assistant").pop();
    if (lastAssistantMessage && conversationId) {
      const permissionPrompt = detectPermissionPrompt(lastAssistantMessage.content);
      if (permissionPrompt && !permissionRecordPending.has(sessionId)) {
        log(`Permission prompt detected for tool: ${permissionPrompt.tool_name}`);
        permissionRecordPending.add(sessionId);
        permissionJustResolved.add(sessionId);
        sendAgentStatus(syncService, conversationId, sessionId, "permission_blocked");

        const permArgPreview = truncateForNotification(
          `${permissionPrompt.tool_name}: ${permissionPrompt.arguments_preview || ""}`, 150
        );
        syncService.createSessionNotification({
          conversation_id: conversationId,
          type: "permission_request",
          title: `codecast - Permission needed`,
          message: permArgPreview,
        }).catch(() => {});

        handlePermissionRequest(
          syncService,
          conversationId,
          sessionId,
          permissionPrompt,
          log
        ).then((decision) => {
          if (decision) {
            const key = decision.approved ? "Enter" : "Escape";
            log(`Attempting to inject '${key}' to session ${sessionId.slice(0, 8)}`);

            findSessionProcess(sessionId, detectSessionAgentType(sessionId)).then((proc) => {
              if (!proc) {
                log("No process found for session");
                return;
              }
              findTmuxPaneForTty(proc.tty).then(async (tmuxTarget) => {
                try {
                  if (tmuxTarget) {
                    await tmuxExec(["send-keys", "-t", tmuxTarget, key]);
                    log(`Injected '${key}' via tmux for session ${sessionId.slice(0, 8)}`);
                  } else {
                    await injectViaTerminal(proc.tty, decision.approved ? "\r" : "\x1b", proc.termProgram, { keystrokes: true });
                    log(`Injected '${key}' via terminal for session ${sessionId.slice(0, 8)}`);
                  }
                } catch (err) {
                  log(`Failed to inject permission: ${err instanceof Error ? err.message : String(err)}`);
                }
              });
            }).catch((err) => {
              log(`Failed to find Claude session: ${err instanceof Error ? err.message : String(err)}`);
            });
          } else {
            log("Permission request timed out or failed");
          }
          permissionRecordPending.delete(sessionId);
        }).catch((err) => {
          log(`Permission handling error: ${err instanceof Error ? err.message : String(err)}`);
          permissionRecordPending.delete(sessionId);
        });
      }

      if (!permissionPrompt) {
        const existingTimer = idleTimers.get(sessionId);
        if (existingTimer) clearTimeout(existingTimer);

        if (wasInterrupted) {
          idleTimers.delete(sessionId);
          lastIdleNotifiedSize.set(sessionId, stats.size);
          sendAgentStatus(syncService, conversationId, sessionId, "idle");
        } else if (lastHookStatus.has(sessionId)) {
          // Single-writer rule: when the status hook is active for a session,
          // its handler is the only emitter of agent_status. The transcript
          // watcher used to second-guess it via a 30s recency cliff plus a
          // size-debounced fallback, which produced working/idle flap whenever
          // the model paused mid-turn between tool calls.
          idleTimers.delete(sessionId);
        } else {
          // No hook history — fall back to transcript heuristics. This path is
          // for sessions where the codecast status hook isn't installed.
          const hasPendingToolCalls = (lastAssistantMessage.toolCalls?.length ?? 0) > 0 &&
            !messages.some(m => m.role === "assistant" && (m.toolResults?.length ?? 0) > 0 &&
              m.timestamp >= lastAssistantMessage.timestamp);

          if (hasPendingToolCalls) {
            sendAgentStatus(syncService, conversationId, sessionId, "working");
            idleTimers.delete(sessionId);
          } else if (lastAssistantMessage.stopReason === "end_turn") {
            idleTimers.delete(sessionId);
            const capturedSize = stats.size;
            if (capturedSize !== lastIdleNotifiedSize.get(sessionId)) {
              lastIdleNotifiedSize.set(sessionId, capturedSize);
              sendAgentStatus(syncService, conversationId, sessionId, resolveTurnEndStatus(sessionId, filePath));
            }
          } else {
            sendAgentStatus(syncService, conversationId, sessionId, "working");
            const capturedSize = stats.size;
            const capturedConvId = conversationId;

            if (capturedSize !== lastIdleNotifiedSize.get(sessionId)) {
              lastIdleNotifiedSize.set(sessionId, capturedSize);
              idleTimers.set(sessionId, setTimeout(() => {
                idleTimers.delete(sessionId);
                sendAgentStatus(syncService, capturedConvId, sessionId, resolveTurnEndStatus(sessionId, filePath));
              }, IDLE_DEBOUNCE_MS));
            }
          }
        }
      }
    } else if (conversationId) {
      const existingTimer = idleTimers.get(sessionId);
      if (existingTimer) {
        clearTimeout(existingTimer);
        idleTimers.delete(sessionId);
      }
      if (wasInterrupted) {
        // Interruption message arrived without an assistant message in this batch
        // (assistant messages were already synced earlier). Transition to idle immediately.
        log(`Interrupted session detected (no assistant msg in batch): ${sessionId.slice(0, 8)}, setting idle`);
        lastIdleNotifiedSize.set(sessionId, stats.size);
        sendAgentStatus(syncService, conversationId, sessionId, "idle");
      } else {
        lastIdleNotifiedSize.delete(sessionId);
      }
    }

    updateStateCallback();

    await continueSyncPass(lastPosition, bytesConsumed, stats.size, continuationDepth, () => processSessionFile(
      filePath,
      sessionId,
      projectPath,
      syncService,
      userId,
      teamId,
      conversationCache,
      retryQueue,
      pendingMessages,
      titleCache,
      updateStateCallback,
      parentConversationId,
      overrideAgentType,
      continuationDepth + 1,
    ));
  } catch (err: any) {
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      log(`Warning: Permission denied reading ${filePath}. Will retry when permissions are restored.`);
      return;
    }
    const errMsg = err instanceof Error ? err.message : String(err);
    const stack = err instanceof Error && err.stack ? `\n${err.stack}` : "";
    log(`processSessionFile failed for ${sessionId.slice(0, 8)} at position=${lastPosition}: ${errMsg}${stack}`);
    throw err;
  }
}

async function processCursorSession(
  dbPath: string,
  sessionId: string,
  workspacePath: string,
  syncService: SyncService,
  userId: string,
  teamId: string | undefined,
  conversationCache: ConversationCache,
  retryQueue: RetryQueue,
  pendingMessages: PendingMessages,
  updateStateCallback: () => void
): Promise<void> {
  const syncedCount = getPosition(dbPath);

  let result: { messages: ParsedMessage[]; maxRowId: number; totalCount: number };
  try {
    result = extractMessagesFromCursorDb(dbPath, syncedCount);
  } catch (err: any) {
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      log(`Warning: Permission denied reading ${dbPath}. Will retry when permissions are restored.`);
      return;
    }
    const errMsg = err instanceof Error ? err.message : String(err);
    log(`Failed to extract messages from Cursor DB: ${errMsg}`);
    return;
  }

  const { messages, totalCount } = result;

  if (messages.length === 0) {
    return;
  }

  let conversationId = conversationCache[sessionId];

  if (!conversationId) {
    try {
      const firstMessageTimestamp = messages[0]?.timestamp;
      const firstUserMessage = messages.find(msg => msg.role === "user");
      const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

      conversationId = await syncService.createConversation({
        userId,
        teamId,
        sessionId,
        agentType: "cursor",
        projectPath: workspacePath,
        title,
        startedAt: firstMessageTimestamp,
      });
      conversationCache[sessionId] = conversationId;
      saveConversationCache(conversationCache);
      log(`Created conversation ${conversationId} for Cursor session ${sessionId}`);

      if (pendingMessages[sessionId]) {
        await flushPendingMessagesBatch(pendingMessages[sessionId], conversationId, syncService, retryQueue);
        delete pendingMessages[sessionId];
      }
    } catch (err) {
      if (err instanceof AuthExpiredError) {
        if (handleAuthFailure()) {
          log("⚠️  Authentication expired - sync paused");
          setPosition(dbPath, totalCount);
          return;
        }
        // Let it fall through to retry queue
      }

      const errMsg = err instanceof Error ? err.message : String(err);
      log(`Failed to create Cursor conversation, queueing for retry: ${errMsg}`);

      if (!pendingMessages[sessionId]) {
        pendingMessages[sessionId] = [];
      }
      for (const msg of messages) {
        pendingMessages[sessionId].push({
          uuid: msg.uuid,
          role: msg.role === "user" ? "human" : msg.role === "system" ? "system" : "assistant",
          content: redactSecrets(msg.content),
          timestamp: msg.timestamp,
          filePath: dbPath,
          fileSize: totalCount,
          thinking: msg.thinking,
          toolCalls: msg.toolCalls,
          toolResults: msg.toolResults,
          images: msg.images,
          subtype: msg.subtype,
          model: msg.model,
        });
      }

      const firstMsgTimestamp = messages[0]?.timestamp;

      retryQueue.add("createConversation", {
        userId,
        teamId,
        sessionId,
        agentType: "cursor",
        projectPath: workspacePath,
        startedAt: firstMsgTimestamp,
      }, errMsg);

      setPosition(dbPath, totalCount);
      return;
    }
  }

  const batchResult = await syncMessagesBatch(messages, conversationId, syncService, retryQueue);
  if (batchResult.authExpired) {
    log("⚠️  Authentication expired - sync paused");
    return;
  }
  if (batchResult.conversationNotFound) {
    log(`Conversation ${conversationId} not found, invalidating cache and recreating...`);
    delete conversationCache[sessionId];
    saveConversationCache(conversationCache);

    const firstMessageTimestamp = messages[0]?.timestamp;
    const firstUserMessage = messages.find(msg => msg.role === "user");
    const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

    try {
      conversationId = await syncService.createConversation({
        userId,
        teamId,
        sessionId,
        agentType: "cursor",
        projectPath: workspacePath,
        title,
        startedAt: firstMessageTimestamp,
      });
      conversationCache[sessionId] = conversationId;
      saveConversationCache(conversationCache);
      log(`Recreated conversation ${conversationId} for Cursor session ${sessionId}`);

      await syncService.addMessages({
        conversationId,
        messages: messages.map(prepMessageForSync),
      });
    } catch (retryErr) {
      const retryErrMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
      log(`Failed to recreate conversation and add messages: ${retryErrMsg}`);
    }
  }

  setPosition(dbPath, totalCount);
  log(`Synced ${messages.length} Cursor messages for session ${sessionId}`);
  syncStats.messagesSynced += messages.length;
  syncStats.sessionsActive.add(sessionId);

  updateStateCallback();
}

async function processCursorTranscriptFile(
  filePath: string,
  sessionId: string,
  syncService: SyncService,
  userId: string,
  teamId: string | undefined,
  conversationCache: ConversationCache,
  retryQueue: RetryQueue,
  pendingMessages: PendingMessages,
  updateStateCallback: () => void,
  continuationDepth: number = 0,
): Promise<void> {
  const stats = await ingestStat(filePath, getPosition(filePath));
  if (!stats || stats.size <= stats.lastPosition) return;
  const lastPosition = stats.lastPosition;

  try {
    // Windowed like claude ingest; the boundary keeps a multi line message
    // whole across passes (see cursorPassBoundary).
    const { content: newContent, bytesConsumed } = await readIngestWindow(filePath, lastPosition, stats.size - lastPosition, { boundary: cursorPassBoundary });
    if (!newContent) return;
    const messages = parseTranscriptFor("cursor", newContent);

    let conversationId = conversationCache[sessionId];

    if (messages.length === 0) {
      setPosition(filePath, lastPosition + bytesConsumed);
      return;
    }

    if (!conversationId) {
      let projectPath: string | undefined;
      try {
        projectPath = findWorkspacePathForCursorConversation(sessionId) || undefined;
      } catch {
        projectPath = undefined;
      }

      const firstMessageTimestamp = messages[0]?.timestamp;
      const firstUserMessage = messages.find(msg => msg.role === "user");
      const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;
      const gitInfo = projectPath ? await getGitInfo(projectPath) : undefined;

      try {
        conversationId = await syncService.createConversation({
          userId,
          teamId,
          sessionId,
          agentType: "cursor",
          projectPath,
          slug: undefined,
          title,
          startedAt: firstMessageTimestamp,
          parentMessageUuid: undefined,
          gitInfo,
        });
        conversationCache[sessionId] = conversationId;
        saveConversationCache(conversationCache);
        log(`Created conversation ${conversationId} for Cursor transcript ${sessionId}`);
        syncStats.conversationsCreated++;

        if (pendingMessages[sessionId]) {
          await flushPendingMessagesBatch(pendingMessages[sessionId], conversationId, syncService, retryQueue);
          delete pendingMessages[sessionId];
        }
      } catch (err) {
        if (err instanceof AuthExpiredError) {
          if (handleAuthFailure()) {
            log("⚠️  Authentication expired - sync paused");
            setPosition(filePath, lastPosition + bytesConsumed);
            return;
          }
        }

        const errMsg = err instanceof Error ? err.message : String(err);
        log(`Failed to create Cursor conversation, queueing for retry: ${errMsg}`);

        if (!pendingMessages[sessionId]) {
          pendingMessages[sessionId] = [];
        }
        for (const msg of messages) {
          pendingMessages[sessionId].push({
            uuid: msg.uuid,
            role: msg.role === "user" ? "human" : msg.role === "system" ? "system" : "assistant",
            content: redactSecrets(msg.content),
            timestamp: msg.timestamp,
            filePath,
            fileSize: stats.size,
            thinking: msg.thinking,
            toolCalls: msg.toolCalls,
            toolResults: msg.toolResults,
            images: msg.images,
            subtype: msg.subtype,
            model: msg.model,
          });
        }

        retryQueue.add("createConversation", {
          userId,
          teamId,
          sessionId,
          agentType: "cursor",
          projectPath,
          title,
          startedAt: firstMessageTimestamp,
          gitInfo,
        }, errMsg);

        setPosition(filePath, lastPosition + bytesConsumed);
        return;
      }
    }

    const batchResult = await syncMessagesBatch(messages, conversationId, syncService, retryQueue);
    if (batchResult.authExpired) {
      log("⚠️  Authentication expired - sync paused");
      return;
    }
    if (batchResult.conversationNotFound) {
      log(`Conversation ${conversationId} not found, invalidating cache and recreating...`);
      delete conversationCache[sessionId];
      saveConversationCache(conversationCache);

      try {
        const projectPath = findWorkspacePathForCursorConversation(sessionId) || undefined;
        const firstMessageTimestamp = messages[0]?.timestamp;
        const firstUserMessage = messages.find(m => m.role === "user");
        const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;
        const gitInfo = projectPath ? await getGitInfo(projectPath) : undefined;

        conversationId = await syncService.createConversation({
          userId,
          teamId,
          sessionId,
          agentType: "cursor",
          projectPath,
          slug: undefined,
          title,
          startedAt: firstMessageTimestamp,
          parentMessageUuid: undefined,
          gitInfo,
        });
        conversationCache[sessionId] = conversationId;
        saveConversationCache(conversationCache);
        log(`Recreated conversation ${conversationId} for Cursor transcript ${sessionId}`);

        await syncService.addMessages({
          conversationId,
          messages: messages.map(prepMessageForSync),
        });
      } catch (retryErr) {
        const retryErrMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
        log(`Failed to recreate Cursor conversation and add messages: ${retryErrMsg}`);
      }
    }

    setPosition(filePath, lastPosition + bytesConsumed);
    markSynced(filePath, lastPosition + bytesConsumed, messages.length, conversationId);
    log(`Synced ${messages.length} Cursor transcript messages for session ${sessionId}`);
    syncStats.messagesSynced += messages.length;
    syncStats.sessionsActive.add(sessionId);

    updateStateCallback();

    await continueSyncPass(lastPosition, bytesConsumed, stats.size, continuationDepth, () => processCursorTranscriptFile(
      filePath,
      sessionId,
      syncService,
      userId,
      teamId,
      conversationCache,
      retryQueue,
      pendingMessages,
      updateStateCallback,
      continuationDepth + 1,
    ));
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err);
    log(`Error processing Cursor transcript file ${filePath}: ${errMsg}`);
  }
}

async function processCodexSession(
  filePath: string,
  sessionId: string,
  syncService: SyncService,
  userId: string,
  teamId: string | undefined,
  conversationCache: ConversationCache,
  retryQueue: RetryQueue,
  pendingMessages: PendingMessages,
  titleCache: TitleCache,
  updateStateCallback: () => void,
  continuationDepth: number = 0,
): Promise<void> {
  const stats = await ingestStat(filePath, getPosition(filePath));
  if (!stats || stats.size <= stats.lastPosition) return;
  const lastPosition = stats.lastPosition;

  try {
    // Windowed like claude ingest: one pass per window, continuation below.
    const { content: newContent, bytesConsumed } = await readIngestWindow(filePath, lastPosition, stats.size - lastPosition);
    if (!newContent) return;
    let sessionMetaHead: string;
    try {
      sessionMetaHead = readFileHead(filePath, 4096);
    } catch (err: any) {
      if (err.code === "EACCES" || err.code === "EPERM") {
        log(`Warning: Permission denied reading ${filePath} for Codex session metadata. Skipping.`);
        return;
      }
      throw err;
    }
    if (isAppServerManagedCodexSessionHead(sessionMetaHead)) {
      setPosition(filePath, lastPosition + bytesConsumed);
      markSynced(filePath, lastPosition + bytesConsumed, 0);
      log(`Skipping app-server-managed Codex transcript ${sessionId}`);
      return;
    }
    const codexMetadata = codexSessionMetadataFor(filePath);
    const nativeParentSessionId = codexMetadata?.parentThreadId;
    const messages = parseTranscriptFor("codex", newContent);

    // Collapse Codex's per-resume fork chain into one conversation: every fork of a logical
    // session embeds its lineage back to a common root, so we key the conversation off that
    // root. We register BOTH the live fork id and the root so future forks collapse here and
    // lookups by the live session id (inject/status/kill) keep resolving.
    const forkRoot = resolveCodexForkRoot(filePath);
    const lineageKeys =
      forkRoot && forkRoot !== sessionId ? [sessionId, forkRoot] : [sessionId];
    const setConversationCache = (cid: string): void => {
      let changed = false;
      for (const k of lineageKeys) {
        if (conversationCache[k] !== cid) {
          conversationCache[k] = cid;
          changed = true;
        }
      }
      if (changed) saveConversationCache(conversationCache);
    };
    const clearConversationCache = (): void => {
      let changed = false;
      for (const k of lineageKeys) {
        if (k in conversationCache) {
          delete conversationCache[k];
          changed = true;
        }
      }
      if (changed) saveConversationCache(conversationCache);
    };

    // Prefer the lineage root's conversation over a per-fork entry: the root is the
    // canonical conversation with the full history, so a fork that was previously (under
    // the old bug) synced into its own conversation heals back onto the root here, and its
    // stale per-fork id is re-pointed below. The orphaned duplicate row no longer receives
    // updates (clean it up separately).
    let conversationId =
      (forkRoot ? conversationCache[forkRoot] : undefined) ?? conversationCache[sessionId];
    // Mirror the resolved conversation onto both the live fork id and the lineage root.
    if (conversationId) setConversationCache(conversationId);

    if (conversationId) {
      let titleContent: string;
      try {
        titleContent = newContent + "\n" + readFileTail(filePath, 4096);
      } catch (err: any) {
        if (err.code === 'EACCES' || err.code === 'EPERM') {
          log(`Warning: Permission denied reading ${filePath} for title update. Skipping.`);
          setPosition(filePath, lastPosition + bytesConsumed);
          return;
        }
        throw err;
      }
      const summaryTitle = extractSummaryTitle(titleContent);
      if (summaryTitle && titleCache[sessionId] !== summaryTitle) {
        try {
          await syncService.updateTitle(conversationId, summaryTitle);
          titleCache[sessionId] = summaryTitle;
          saveTitleCache(titleCache);
          log(`Updated title for Codex session ${sessionId}: ${summaryTitle}`);
        } catch (err) {
          const errMsg = err instanceof Error ? err.message : String(err);
          log(`Failed to update title: ${errMsg}`);
        }
      }
    }

    if (messages.length === 0) {
      setPosition(filePath, lastPosition + bytesConsumed);
      return;
    }

    if (!conversationId) {
      try {
        const headContent = sessionMetaHead.length >= 16384 ? sessionMetaHead : readFileHead(filePath, 16384);
        const projectPath = extractCodexCwd(headContent);
        const firstMessageTimestamp = messages[0]?.timestamp;
        let matchedStartedConversation: string | null = null;

        if (startedSessionTmux.size > 0) {
          const startedCodexEntries = Array.from(startedSessionTmux.entries())
            .filter(([, entry]) => entry.agentType === "codex");
          const proc = await findSessionProcess(sessionId, "codex").catch(() => null);
          let tmuxSessionName: string | null = null;

          if (proc) {
            tmuxSessionName = sessionProcessCache.get(sessionId)?.tmuxTarget?.split(":")[0] ?? null;
            if (!tmuxSessionName) {
              const tmuxPane = await findTmuxPaneForTty(proc.tty);
              if (tmuxPane) {
                tmuxSessionName = tmuxPane.split(":")[0];
                cacheSessionProcess(sessionId, proc, tmuxPane);
              }
            }
          }

          matchedStartedConversation = matchStartedConversation(startedCodexEntries, {
            tmuxSessionName,
            // Only allow the cwd fallback when the process wasn't found at all
            // (see claude branch / matchStartedConversation).
            projectPath: proc ? null : projectPath,
          });

          if (matchedStartedConversation && tmuxSessionName) {
            log(`Matched codex session ${sessionId.slice(0, 8)} to conversation ${matchedStartedConversation.slice(0, 12)} via tmux ${tmuxSessionName}`);
          } else if (matchedStartedConversation && projectPath) {
            log(`Matched codex session ${sessionId.slice(0, 8)} to conversation ${matchedStartedConversation.slice(0, 12)} via projectPath fallback`);
          }
        }

        if (matchedStartedConversation) {
          conversationId = matchedStartedConversation;
          const tmuxEntry = startedSessionTmux.get(matchedStartedConversation);
          setConversationCache(conversationId);
          // Reconcile project_path/git_root to the real session cwd (see Claude
          // match branch): the stub's stored path was a guess made before the
          // session existed and may not match where it actually runs.
          const codexGitInfo = projectPath ? await getGitInfo(projectPath) : undefined;
          void pushSessionIdBinding(conversationId, sessionId, projectPath || undefined, codexGitInfo?.repoRoot || codexGitInfo?.root);
          if (tmuxEntry) {
            registerManagedStartedSession(conversationId, sessionId, tmuxEntry.tmuxSession);
            if (tmuxEntry.sessionId && tmuxEntry.sessionId !== sessionId) {
              stopManagedSessionHeartbeat(tmuxEntry.sessionId);
            }
            startCodexPermissionPoller(sessionId, tmuxEntry.tmuxSession, conversationId, syncService);
          }
          deleteStartedSession(matchedStartedConversation);
          log(`Linked Codex session ${sessionId} to existing started conversation ${conversationId}`);
        } else {

          const firstUserMessage = messages.find(msg => msg.role === "user");
          const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

          // A codex session spawned by another session's Bash tool (`codex
          // exec`) nests under its spawner as a subagent instead of surfacing
          // as a loose first-class card. Only fresh, unmatched sessions get
          // here — started stubs and forks resolved above stay first-class.
          let parentConversationId = nativeParentSessionId
            ? conversationCache[nativeParentSessionId]
            : undefined;
          if (nativeParentSessionId) {
            if (parentConversationId) {
              log(`Detected native Codex review ${sessionId.slice(0, 8)} -> wrapper ${nativeParentSessionId.slice(0, 8)}`);
            } else {
              pendingNativeParents.set(sessionId, { parentSessionId: nativeParentSessionId, description: "review" });
            }
          } else {
            try {
              const spawnerConvId = await resolveSpawnerConversation(filePath, sessionId, "codex", conversationCache);
              if (spawnerConvId) {
                parentConversationId = spawnerConvId;
                log(`Detected spawned codex session ${sessionId.slice(0, 8)} -> parent ${spawnerConvId.slice(0, 12)} via process ancestry`);
              }
            } catch {}
            if (!parentConversationId) spawnLinkAttempts.set(sessionId, 1);
          }

          conversationId = await syncService.createConversation({
            userId,
            teamId,
            sessionId,
            agentType: "codex",
            projectPath,
            slug: undefined,
            title,
            startedAt: firstMessageTimestamp,
            parentMessageUuid: undefined,
            parentConversationId,
            isSubagent: !!nativeParentSessionId || undefined,
            gitInfo: undefined,
          });
          setConversationCache(conversationId);
          await linkPendingNativeChildren(sessionId, conversationId, syncService, conversationCache);
          log(`Created conversation ${conversationId} for Codex session ${sessionId}${forkRoot && forkRoot !== sessionId ? ` (lineage root ${forkRoot.slice(0, 8)})` : ""}`);

          if ((global as any).activeSessions) {
            (global as any).activeSessions.set(conversationId, {
              sessionId,
              conversationId,
              projectPath: "",
            });
          }

          if (pendingMessages[sessionId]) {
            await flushPendingMessagesBatch(pendingMessages[sessionId], conversationId, syncService, retryQueue);
            delete pendingMessages[sessionId];
          }
        }
      } catch (err) {
        if (err instanceof AuthExpiredError) {
          if (handleAuthFailure()) {
            log("⚠️  Authentication expired - sync paused");
            setPosition(filePath, lastPosition + bytesConsumed);
            return;
          }
          // Let it fall through to retry queue
        }

        const errMsg = err instanceof Error ? err.message : String(err);
        log(`Failed to create Codex conversation, queueing for retry: ${errMsg}`);

        if (!pendingMessages[sessionId]) {
          pendingMessages[sessionId] = [];
        }
        for (const msg of messages) {
          pendingMessages[sessionId].push({
            uuid: msg.uuid,
            role: msg.role === "user" ? "human" : msg.role === "system" ? "system" : "assistant",
            content: redactSecrets(msg.content),
            timestamp: msg.timestamp,
            filePath,
            fileSize: stats.size,
            thinking: msg.thinking,
            toolCalls: msg.toolCalls,
            toolResults: msg.toolResults,
            images: msg.images,
            subtype: msg.subtype,
            model: msg.model,
          });
        }

        const firstMsgTimestamp = messages[0]?.timestamp;
        const firstUserMessage = messages.find(msg => msg.role === "user");
        const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

        retryQueue.add("createConversation", {
          userId,
          teamId,
          sessionId,
          agentType: "codex",
          title,
          startedAt: firstMsgTimestamp,
        }, errMsg);

        setPosition(filePath, lastPosition + bytesConsumed);
        return;
      }
    }

    const batchResult = await syncMessagesBatch(messages, conversationId, syncService, retryQueue);
    if (batchResult.authExpired) {
      log("⚠️  Authentication expired - sync paused");
      return;
    }
    if (batchResult.conversationNotFound) {
      log(`Conversation ${conversationId} not found, invalidating cache and recreating...`);
      clearConversationCache();

      const firstMsgTimestamp = messages[0]?.timestamp;
      const firstUserMessage = messages.find(msg => msg.role === "user");
      const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

      try {
        conversationId = await syncService.createConversation({
          userId,
          teamId,
          sessionId,
          agentType: "codex",
          title,
          startedAt: firstMsgTimestamp,
        });
        setConversationCache(conversationId);
        log(`Recreated conversation ${conversationId} for Codex session ${sessionId}`);

        await syncService.addMessages({
          conversationId,
          messages: messages.map(prepMessageForSync),
        });
      } catch (retryErr) {
        const retryErrMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
        log(`Failed to recreate Codex conversation and add messages: ${retryErrMsg}`);
      }
    }

    setPosition(filePath, lastPosition + bytesConsumed);
    markSynced(filePath, lastPosition + bytesConsumed, messages.length, conversationId);
    log(`Synced ${messages.length} Codex messages for session ${sessionId}`);
    syncStats.messagesSynced += messages.length;
    syncStats.sessionsActive.add(sessionId);
    tryRegisterSessionProcess(sessionId, "codex");

    if (conversationId) {
      await linkPendingNativeChildren(sessionId, conversationId, syncService, conversationCache);
      // The completed-review predicates need the review's full event history, but
      // newContent is only the bytes since the last sync position — a live-watched
      // review delivers exited_review_mode and task_complete in different chunks.
      // Once the terminal task_complete shows up, judge against the whole transcript.
      if (codexMetadata?.originator === "codex_exec" && newContent.includes('"task_complete"')) {
        let fullContent = newContent;
        try {
          fullContent = await fs.promises.readFile(filePath, "utf-8");
        } catch {}
        if (
          isCompletedStandaloneCodexReview(codexMetadata, fullContent) ||
          isCompletedNativeCodexReviewChild(codexMetadata, fullContent)
        ) {
          scheduleCodexReviewRetirement(filePath, sessionId, conversationId, syncService);
        }
      }
    }

    // Spawned-child link that failed at creation (child process not visible
    // yet) — bounded retries on later passes, no-op once resolved or exhausted.
    if (conversationId && spawnLinkAttempts.has(sessionId)) {
      maybeRetrySpawnLink(filePath, sessionId, "codex", conversationId, syncService, conversationCache).catch(() => {});
    }

    // Agent status tracking for Codex sessions (skip if managed by app-server)
    if (conversationId && !appServerConversations.has(conversationId)) {
      sendAgentStatus(syncService, conversationId, sessionId, "working");
    }

    updateStateCallback();

    await continueSyncPass(lastPosition, bytesConsumed, stats.size, continuationDepth, () => processCodexSession(
      filePath,
      sessionId,
      syncService,
      userId,
      teamId,
      conversationCache,
      retryQueue,
      pendingMessages,
      titleCache,
      updateStateCallback,
      continuationDepth + 1,
    ));
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err);
    log(`Error processing Codex session file ${filePath}: ${errMsg}`);
  }
}

const geminiSyncedCounts = new Map<string, number>();

async function processGeminiSession(
  filePath: string,
  sessionId: string,
  projectHash: string,
  syncService: SyncService,
  userId: string,
  teamId: string | undefined,
  conversationCache: ConversationCache,
  retryQueue: RetryQueue,
  pendingMessages: PendingMessages,
  titleCache: TitleCache,
  updateStateCallback: () => void
): Promise<void> {
  try {
    let content: string;
    try {
      content = await fs.promises.readFile(filePath, "utf-8");
    } catch (err: any) {
      if (err.code === 'EACCES' || err.code === 'EPERM') {
        log(`Warning: Permission denied reading ${filePath}. Will retry later.`);
        return;
      }
      throw err;
    }

    const allMessages = parseTranscriptFor("gemini", content);
    const previousCount = geminiSyncedCounts.get(filePath) || 0;

    if (allMessages.length <= previousCount) {
      return;
    }

    const newMessages = allMessages.slice(previousCount);
    let conversationId = conversationCache[sessionId];

    if (!conversationId) {
      try {
        const firstUserMessage = allMessages.find(msg => msg.role === "user");
        const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;
        const startTime = allMessages[0]?.timestamp;

        conversationId = await syncService.createConversation({
          userId,
          teamId,
          sessionId,
          agentType: "gemini",
          projectPath: undefined,
          slug: undefined,
          title,
          startedAt: startTime,
          parentMessageUuid: undefined,
          gitInfo: undefined,
        });
        conversationCache[sessionId] = conversationId;
        saveConversationCache(conversationCache);
        log(`Created conversation ${conversationId} for Gemini session ${sessionId}`);

        if ((global as any).activeSessions) {
          (global as any).activeSessions.set(conversationId, {
            sessionId,
            conversationId,
            projectPath: "",
          });
        }

        if (pendingMessages[sessionId]) {
          await flushPendingMessagesBatch(pendingMessages[sessionId], conversationId, syncService, retryQueue);
          delete pendingMessages[sessionId];
        }
      } catch (err) {
        if (err instanceof AuthExpiredError) {
          if (handleAuthFailure()) {
            log("⚠️  Authentication expired - sync paused");
            geminiSyncedCounts.set(filePath, allMessages.length);
            return;
          }
        }

        const errMsg = err instanceof Error ? err.message : String(err);
        log(`Failed to create Gemini conversation, queueing for retry: ${errMsg}`);

        if (!pendingMessages[sessionId]) {
          pendingMessages[sessionId] = [];
        }
        for (const msg of newMessages) {
          pendingMessages[sessionId].push({
            uuid: msg.uuid,
            role: msg.role === "user" ? "human" : msg.role === "system" ? "system" : "assistant",
            content: redactSecrets(msg.content),
            timestamp: msg.timestamp,
            filePath,
            fileSize: content.length,
            thinking: msg.thinking,
            toolCalls: msg.toolCalls,
            toolResults: msg.toolResults,
            images: msg.images,
            subtype: msg.subtype,
            model: msg.model,
          });
        }

        const firstUserMessage = allMessages.find(msg => msg.role === "user");
        const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

        retryQueue.add("createConversation", {
          userId,
          teamId,
          sessionId,
          agentType: "gemini",
          title,
          startedAt: allMessages[0]?.timestamp,
        }, errMsg);

        geminiSyncedCounts.set(filePath, allMessages.length);
        return;
      }
    }

    const batchResult = await syncMessagesBatch(newMessages, conversationId, syncService, retryQueue);
    if (batchResult.authExpired) {
      log("⚠️  Authentication expired - sync paused");
      return;
    }
    if (batchResult.conversationNotFound) {
      log(`Conversation ${conversationId} not found, invalidating cache and recreating...`);
      delete conversationCache[sessionId];
      saveConversationCache(conversationCache);

      const firstUserMessage = allMessages.find(msg => msg.role === "user");
      const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;

      try {
        conversationId = await syncService.createConversation({
          userId,
          teamId,
          sessionId,
          agentType: "gemini",
          title,
          startedAt: allMessages[0]?.timestamp,
        });
        conversationCache[sessionId] = conversationId;
        saveConversationCache(conversationCache);
        log(`Recreated conversation ${conversationId} for Gemini session ${sessionId}`);

        await syncService.addMessages({
          conversationId,
          messages: newMessages.map(prepMessageForSync),
        });
      } catch (retryErr) {
        const retryErrMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
        log(`Failed to recreate Gemini conversation and add messages: ${retryErrMsg}`);
      }
    }

    geminiSyncedCounts.set(filePath, allMessages.length);
    log(`Synced ${newMessages.length} Gemini messages for session ${sessionId}`);
    syncStats.messagesSynced += newMessages.length;
    syncStats.sessionsActive.add(sessionId);
    tryRegisterSessionProcess(sessionId, "gemini");

    updateStateCallback();
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err);
    log(`Error processing Gemini session file ${filePath}: ${errMsg}`);
  }
}

// Count of ParsedMessages last synced per opencode session. Unlike the gemini
// counter this is keyed by session id (opencode has no single file) and is used to
// bound the batch, not to skip: opencode messages stream their content into parts,
// so we re-send the last already-synced message too (addMessages upserts by uuid,
// patching it in place) to pick up a message whose body grew after its first sync.
const opencodeSyncedCounts = new Map<string, number>();

// The opencode `serve` sidecar (opencodeServer.ts) is a daemon-wide, LAZY singleton:
// its only job today is the fork-by-id API, which is rare, so — unlike the codex
// app-server (a per-turn transport spun up at boot) — we don't keep a serve process
// running on every machine. It starts on the first fork that needs it, tears itself
// down after an idle timeout (the serve HTTP surface is unauthenticated, so we don't
// leave it up forever after a single fork), and is also stopped on daemon shutdown
// AND on the crash/exit paths (see the uncaughtException + process "exit" handlers)
// so a daemon that dies hard can't orphan a live unauthenticated serve. Fork works
// cross-project-scope (verified: a sidecar in any cwd forks any session by id, and
// the fork inherits the PARENT's directory), so one instance suffices regardless of
// which project the fork lives in.
let opencodeServerInstance: OpencodeServer | null = null;

/** Start (once) and await readiness of the fork sidecar. Returns the running server,
 *  or null when it can't be used (disabled by config, binary missing, or never became
 *  healthy) — callers then fall back honestly rather than claiming a fork happened. */
export async function ensureOpencodeServer(config: Config | null | undefined): Promise<OpencodeServer | null> {
  if (!isOpencodeServerEnabled(config)) return null;
  if (opencodeServerInstance?.running) return opencodeServerInstance;
  if (opencodeServerInstance?.binaryMissing) return null;
  if (!opencodeServerInstance) {
    opencodeServerInstance = new OpencodeServer({
      log,
      port: opencodeServerPort(config),
    });
    opencodeServerInstance.on("error", (err: Error) =>
      log(`[opencode-server] ${err.message}`));
    opencodeServerInstance.on("binaryNotFound", (bin: string) =>
      log(`[opencode-server] "${bin}" not installed — opencode fork unavailable`));
    // Idle self-teardown: drop the singleton so the NEXT fork lazily builds a fresh
    // one. ensureOpencodeServer already re-`start()`s a stopped-but-present instance,
    // but nulling keeps the lifecycle unambiguous (no stale state to reason about).
    opencodeServerInstance.on("idleStopped", () => {
      log(`[opencode-server] stopped after idle timeout — will respawn on next fork`);
      opencodeServerInstance = null;
    });
  }
  if (opencodeServerInstance.running) return opencodeServerInstance;
  const srv = opencodeServerInstance;
  const ready = await new Promise<boolean>((resolve) => {
    const timer = setTimeout(() => resolve(false), 25_000);
    const done = (ok: boolean) => { clearTimeout(timer); resolve(ok); };
    srv.once("ready", () => done(true));
    srv.once("binaryNotFound", () => done(false));
    srv.once("closed", () => done(false));
    srv.start();
  });
  return ready && srv.running ? srv : null;
}

/** After forking an opencode session, its copied history is ALREADY in convex
 *  (advanceForkCopy copied it from the parent, keeping the parent's uuids). opencode's
 *  fork re-mints NEW message ids for that same content, so if the DB watcher re-synced
 *  them they'd land as DUPLICATE rows. Seed the synced-count past the copied history
 *  (+1 so even the boundary re-send of the last, already-finalized message is skipped);
 *  only genuinely new branch turns sync from here. */
export function seedOpencodeForkSyncBaseline(forkSessionId: string): number {
  try {
    const assembled = assembleOpencodeSession(forkSessionId);
    const count = assembled ? parseTranscriptFor("opencode", assembled).length : 0;
    const baseline = count + 1;
    opencodeSyncedCounts.set(forkSessionId, baseline);
    return baseline;
  } catch {
    /* leave unseeded — worst case the watcher re-forwards copies, never data loss */
    return 0;
  }
}

async function processOpencodeSession(
  sessionId: string,
  syncService: SyncService,
  userId: string,
  teamId: string | undefined,
  conversationCache: ConversationCache,
  retryQueue: RetryQueue,
  pendingMessages: PendingMessages,
  titleCache: TitleCache,
  updateStateCallback: () => void
): Promise<void> {
  try {
    const assembled = assembleOpencodeSession(sessionId);
    if (!assembled) return;
    const allMessages = parseTranscriptFor("opencode", assembled);
    if (allMessages.length === 0) return;

    const cwd = resolveOpencodeSessionCwd(sessionId);
    let conversationId = conversationCache[sessionId];

    if (!conversationId) {
      // A session spawned by another opencode session's task tool carries its
      // spawner in session.parent_id — nest it under the spawner as a subagent
      // (same contract as the codex native-review path). A task-tool child is
      // never the session a user launched, so it must not claim a started stub
      // (its cwd matches its parent's, which would collide with the cwd match).
      const lineage = readOpencodeSessionLineage(sessionId);

      // Bind a freshly launched opencode session to its pending started-tmux
      // conversation. opencode's session id never appears in the launched process
      // args (it starts as a bare `opencode` TUI and mints its own id), so — unlike
      // codex — the tmux-name match can't resolve; we bind by cwd via the project
      // map (resolveOpencodeSessionCwd), which is matchStartedConversation's cwd
      // fallback. If nothing matches, this is a fresh first-class session.
      let matchedStartedConversation: string | null = null;
      if (!lineage.parentSessionId && startedSessionTmux.size > 0 && cwd) {
        const startedOpencodeEntries = Array.from(startedSessionTmux.entries())
          .filter(([, entry]) => entry.agentType === "opencode");
        matchedStartedConversation = matchStartedConversation(startedOpencodeEntries, {
          tmuxSessionName: null,
          projectPath: cwd,
        });
      }

      if (matchedStartedConversation) {
        conversationId = matchedStartedConversation;
        const tmuxEntry = startedSessionTmux.get(matchedStartedConversation);
        conversationCache[sessionId] = conversationId;
        saveConversationCache(conversationCache);
        const gitInfo = cwd ? await getGitInfo(cwd) : undefined;
        void pushSessionIdBinding(conversationId, sessionId, cwd || undefined, gitInfo?.repoRoot || gitInfo?.root);
        if (tmuxEntry) {
          registerManagedStartedSession(conversationId, sessionId, tmuxEntry.tmuxSession);
          if (tmuxEntry.sessionId && tmuxEntry.sessionId !== sessionId) {
            stopManagedSessionHeartbeat(tmuxEntry.sessionId);
          }
        }
        deleteStartedSession(matchedStartedConversation);
        log(`Linked opencode session ${sessionId} to started conversation ${conversationId.slice(0, 12)} via cwd ${cwd}`);
      } else {
        const firstUserMessage = allMessages.find((m) => m.role === "user");
        const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;
        const parentConversationId = lineage.parentSessionId ? conversationCache[lineage.parentSessionId] : undefined;
        if (lineage.parentSessionId && !parentConversationId) {
          // Parent hasn't synced yet (backfill order is arbitrary) — link when it does.
          pendingNativeParents.set(sessionId, { parentSessionId: lineage.parentSessionId, description: lineage.agentName });
        }
        try {
          conversationId = await syncService.createConversation({
            userId,
            teamId,
            sessionId,
            agentType: "opencode",
            projectPath: cwd,
            slug: undefined,
            title,
            startedAt: allMessages[0]?.timestamp,
            parentMessageUuid: undefined,
            parentConversationId,
            isSubagent: lineage.parentSessionId ? true : undefined,
            subagentDescription: parentConversationId ? lineage.agentName : undefined,
            gitInfo: cwd ? await getGitInfo(cwd) : undefined,
          });
        } catch (err) {
          if (err instanceof AuthExpiredError && handleAuthFailure()) {
            log("⚠️  Authentication expired - sync paused");
            return;
          }
          throw err;
        }
        conversationCache[sessionId] = conversationId;
        saveConversationCache(conversationCache);
        log(`Created conversation ${conversationId} for opencode session ${sessionId}${parentConversationId ? ` (subagent of ${parentConversationId.slice(0, 12)})` : ""}`);
        if (pendingMessages[sessionId]) {
          await flushPendingMessagesBatch(pendingMessages[sessionId], conversationId, syncService, retryQueue);
          delete pendingMessages[sessionId];
        }
      }
    }

    // Upsert-based delta: re-send the last already-synced message (its body may have
    // grown as parts streamed in) plus everything new. addMessages patches by uuid.
    const prevCount = opencodeSyncedCounts.get(sessionId) ?? 0;
    const toSync = allMessages.slice(Math.max(0, prevCount - 1));
    if (toSync.length > 0) {
      const batchResult = await syncMessagesBatch(toSync, conversationId, syncService, retryQueue);
      if (batchResult.authExpired) {
        log("⚠️  Authentication expired - sync paused");
        return;
      }
      if (batchResult.conversationNotFound) {
        log(`Conversation ${conversationId} not found, invalidating opencode cache`);
        delete conversationCache[sessionId];
        saveConversationCache(conversationCache);
        opencodeSyncedCounts.delete(sessionId);
        return;
      }
    }
    opencodeSyncedCounts.set(sessionId, allMessages.length);

    // This session may be the parent a task-tool child synced ahead of.
    await linkPendingNativeChildren(sessionId, conversationId, syncService, conversationCache);

    // Title: opencode names the session in its meta (info.title); mirror it.
    try {
      const metaTitle = (JSON.parse(assembled).info as { title?: string } | undefined)?.title;
      if (metaTitle && titleCache[sessionId] !== metaTitle) {
        await syncService.updateTitle(conversationId, metaTitle);
        titleCache[sessionId] = metaTitle;
        saveTitleCache(titleCache);
      }
    } catch {}

    // Status is transcript-driven (opencode panes aren't classifiable and reconcile
    // defers on them): the newest message tells us working vs turn-complete, so this
    // fires the idle flip that routes the session into needs-input when its turn ends.
    if (conversationId && !appServerConversations.has(conversationId)) {
      const turn = classifyOpencodeTranscriptTail(assembled);
      sendAgentStatus(syncService, conversationId, sessionId, turn === "idle" ? resolveTurnEndStatus(sessionId) : "working");
    }

    syncStats.messagesSynced += toSync.length;
    syncStats.sessionsActive.add(sessionId);
    tryRegisterSessionProcess(sessionId, "opencode");
    updateStateCallback();
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err);
    log(`Error processing opencode session ${sessionId}: ${errMsg}`);
  }
}

// pi sessions re-parse the whole JSONL each pass, but unlike gemini the parser
// resolves the ACTIVE BRANCH of an id/parentId tree — a /tree branch switch makes
// the active branch shrink or diverge while the file grows. A count-based delta
// guard (allMessages.length <= previousCount) therefore either silently drops the
// new branch's turns or splices branch A's prefix onto branch B's tail. Instead we
// track the exact set of synced message uuids per file: new turns are the active
// messages not yet synced (a divergent branch's turns always fall here, never
// skipped), and orphans are synced uuids that dropped off the active branch (the
// abandoned branch). Keyed by file path; in-memory only (a daemon restart resets to
// empty, which re-syncs the full active branch idempotently via uuid upsert).
// Shared by pi AND grok (processTranscriptDeltaSession): grok's rewind_marker
// drops accumulated turns exactly the way a pi branch switch does, and the two
// clients' transcript roots are disjoint so one path-keyed map serves both.
// The value maps each synced uuid to its messageSyncSig — grok STREAMS chunks
// into a message whose uuid stays stable (the parser coalesces them, keyed by
// the opening line), so uuid membership alone would freeze every message at
// whatever prefix the first watcher pass caught.
const piSyncedSigs = new Map<string, Map<string, string>>();

// One message's sync signature: the whole serialized message. A grok assistant
// message GROWS under an unchanged uuid across parses — content/thinking chunks
// stream in, toolCalls attach, turn_completed stamps stopReason — so equality
// must compare the payload, not just the uuid. pi messages land as complete
// JSONL lines and never change, so for them this degrades to the old uuid-only
// behavior (the signature compares equal on every later pass).
export function messageSyncSig(m: unknown): string {
  return JSON.stringify(m);
}

// Pure delta between the parser's current active branch and what was already
// synced. `newMessages` are active messages not yet synced OR whose signature
// changed since their last sync (sent via addMessages, which upserts by uuid and
// patches a changed payload in place). `orphanUuids` are synced uuids no longer
// on the active branch — the abandoned branch's turns, deleted so the synced
// conversation equals the active branch exactly (never a splice). `nextSynced`
// is the active branch's uuid -> signature map, stored after a clean sync.
// Because pi's active branch is the unique parentId chain to the leaf, two branches
// that share a uuid at any index share the whole prefix below it — so a set diff
// catches every divergence (same-length, shrink, or mid-prefix), not just growth.
export function computePiSyncDelta<T extends { uuid?: string }>(
  activeMessages: T[],
  syncedSigs: ReadonlyMap<string, string>,
): { newMessages: T[]; orphanUuids: string[]; nextSynced: Map<string, string> } {
  const nextSynced = new Map<string, string>();
  const newMessages: T[] = [];
  for (const m of activeMessages) {
    // A message with no uuid can't be deduped or tracked; the pi/grok parsers
    // always set one, so this branch only satisfies the optional type — treat it
    // as new.
    if (!m.uuid) {
      newMessages.push(m);
      continue;
    }
    const sig = messageSyncSig(m);
    nextSynced.set(m.uuid, sig);
    if (syncedSigs.get(m.uuid) !== sig) newMessages.push(m);
  }
  const orphanUuids: string[] = [];
  for (const uuid of syncedSigs.keys()) {
    if (!nextSynced.has(uuid)) orphanUuids.push(uuid);
  }
  return { newMessages, orphanUuids, nextSynced };
}

// ── grok transcript-path helpers ─────────────────────────────────────────────
// updates.jsonl carries no cwd. The authoritative source is the sibling
// summary.json (`info.cwd`, unencoded — and correct across session-dir
// relocation); the %-encoded grandparent dir name is the fallback (lossless
// except for grok's long-path hash dirs, where decode returns null).
export function grokSessionCwdFromTranscriptPath(updatesPath: string): string | undefined {
  try {
    const summaryPath = path.join(path.dirname(updatesPath), "summary.json");
    if (fs.existsSync(summaryPath)) {
      const cwd = extractGrokCwd(fs.readFileSync(summaryPath, "utf-8"));
      if (cwd) return cwd;
    }
  } catch {}
  return decodeGrokCwdSlug(path.basename(path.dirname(path.dirname(updatesPath)))) ?? undefined;
}

// True when the session dir's summary.json marks it grok-internal (a subagent /
// subagent_fork child, or hidden). Such sessions must never surface as top-level
// codecast conversations — grok runs its own subagents and each writes a full
// sibling session dir. A missing or unreadable summary means "not internal":
// summary.json can land moments after the first updates, and skipping on absence
// would drop the opening messages of every real session.
export function isGrokInternalSessionDir(updatesPath: string): boolean {
  try {
    const summaryPath = path.join(path.dirname(updatesPath), "summary.json");
    if (!fs.existsSync(summaryPath)) return false;
    return isGrokInternalSession(fs.readFileSync(summaryPath, "utf-8"));
  } catch {
    return false;
  }
}

// pi and grok share this whole-file delta sync pipeline: both are file-per-session
// JSONL clients whose parser rebuilds the ACTIVE branch each pass (pi's parentId
// chain, grok's rewind filter), so sync is the same computePiSyncDelta diff —
// upsert the new turns, delete the orphaned ones. Everything client-specific is
// parameterized here; the wrappers below (processPiSession / processGrokSession)
// are what the watcher registrations bind.
async function processTranscriptDeltaSession(
  client: Extract<AgentClientId, "pi" | "grok">,
  filePath: string,
  sessionId: string,
  syncService: SyncService,
  userId: string,
  teamId: string | undefined,
  conversationCache: ConversationCache,
  retryQueue: RetryQueue,
  pendingMessages: PendingMessages,
  titleCache: TitleCache,
  updateStateCallback: () => void
): Promise<void> {
  try {
    // grok-internal children (subagents, hidden sessions) sync through their
    // parent's transcript; ingesting them here would mint a top-level codecast
    // conversation per subagent.
    if (client === "grok" && isGrokInternalSessionDir(filePath)) return;
    let content: string;
    try {
      content = await fs.promises.readFile(filePath, "utf-8");
    } catch (err: any) {
      if (err.code === "EACCES" || err.code === "EPERM") {
        log(`Warning: Permission denied reading ${filePath}. Will retry later.`);
        return;
      }
      if (err.code === "ENOENT") {
        log(`${client} transcript ${filePath} no longer exists; nothing to sync.`);
        return;
      }
      throw err;
    }

    const allMessages = parseTranscriptFor(client, content);
    // A transient empty/corrupt parse must be a no-op, never a signal to delete the
    // synced conversation (orphan detection below would treat every synced uuid as
    // abandoned).
    if (allMessages.length === 0) return;
    const syncedSigs = piSyncedSigs.get(filePath) ?? new Map<string, string>();
    const { newMessages, orphanUuids, nextSynced } = computePiSyncDelta(allMessages, syncedSigs);
    if (newMessages.length === 0 && orphanUuids.length === 0) return;

    let conversationId = conversationCache[sessionId];

    if (!conversationId) {
      try {
        // Authoritative project path is the transcript's own record of its cwd
        // (pi: the session header; grok: the sibling summary.json); the containing
        // slug dir decodes back to it only lossily (see decodePiCwdSlug — and
        // grok's long-path hash dirs don't decode at all).
        const projectPath = client === "pi"
          ? extractPiCwd(content) ?? decodePiCwdSlug(path.basename(path.dirname(filePath)))
          : grokSessionCwdFromTranscriptPath(filePath);

        // Bind a daemon-launched agent to its start_session stub (codex pattern):
        // find the live process's tmux pane and match it against the pending started
        // conversations; fall back to a unique cwd match when the process isn't found.
        let matchedStartedConversation: string | null = null;
        if (startedSessionTmux.size > 0) {
          const startedPiEntries = Array.from(startedSessionTmux.entries())
            .filter(([, entry]) => entry.agentType === client);
          const proc = await findSessionProcess(sessionId, client).catch(() => null);
          let tmuxSessionName: string | null = null;
          if (proc) {
            tmuxSessionName = sessionProcessCache.get(sessionId)?.tmuxTarget?.split(":")[0] ?? null;
            if (!tmuxSessionName) {
              const tmuxPane = await findTmuxPaneForTty(proc.tty);
              if (tmuxPane) {
                tmuxSessionName = tmuxPane.split(":")[0];
                cacheSessionProcess(sessionId, proc, tmuxPane);
              }
            }
          }
          matchedStartedConversation = matchStartedConversation(startedPiEntries, {
            tmuxSessionName,
            projectPath: proc ? null : projectPath,
          });
        }

        if (matchedStartedConversation) {
          conversationId = matchedStartedConversation;
          const tmuxEntry = startedSessionTmux.get(matchedStartedConversation);
          conversationCache[sessionId] = conversationId;
          saveConversationCache(conversationCache);
          const piGitInfo = projectPath ? await getGitInfo(projectPath) : undefined;
          void pushSessionIdBinding(conversationId, sessionId, projectPath || undefined, piGitInfo?.repoRoot || piGitInfo?.root);
          if (tmuxEntry) {
            registerManagedStartedSession(conversationId, sessionId, tmuxEntry.tmuxSession);
            if (tmuxEntry.sessionId && tmuxEntry.sessionId !== sessionId) {
              stopManagedSessionHeartbeat(tmuxEntry.sessionId);
            }
          }
          deleteStartedSession(matchedStartedConversation);
          log(`Linked ${client} session ${sessionId.slice(0, 8)} to started conversation ${conversationId.slice(0, 12)}`);
        } else {
          const firstUserMessage = allMessages.find((msg) => msg.role === "user");
          const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;
          conversationId = await syncService.createConversation({
            userId,
            teamId,
            sessionId,
            agentType: client,
            projectPath,
            slug: undefined,
            title,
            startedAt: allMessages[0]?.timestamp,
            parentMessageUuid: undefined,
            gitInfo: undefined,
          });
          conversationCache[sessionId] = conversationId;
          saveConversationCache(conversationCache);
          log(`Created conversation ${conversationId} for ${client} session ${sessionId}`);

          if ((global as any).activeSessions) {
            (global as any).activeSessions.set(conversationId, { sessionId, conversationId, projectPath: "" });
          }

          if (pendingMessages[sessionId]) {
            await flushPendingMessagesBatch(pendingMessages[sessionId], conversationId, syncService, retryQueue);
            delete pendingMessages[sessionId];
          }
        }
      } catch (err) {
        if (err instanceof AuthExpiredError) {
          if (handleAuthFailure()) {
            log("⚠️  Authentication expired - sync paused");
            piSyncedSigs.set(filePath, nextSynced);
            return;
          }
        }
        const errMsg = err instanceof Error ? err.message : String(err);
        log(`Failed to create ${client} conversation, queueing for retry: ${errMsg}`);

        if (!pendingMessages[sessionId]) pendingMessages[sessionId] = [];
        for (const msg of newMessages) {
          pendingMessages[sessionId].push({
            uuid: msg.uuid,
            role: msg.role === "user" ? "human" : msg.role === "system" ? "system" : "assistant",
            content: redactSecrets(msg.content),
            timestamp: msg.timestamp,
            filePath,
            fileSize: content.length,
            thinking: msg.thinking,
            toolCalls: msg.toolCalls,
            toolResults: msg.toolResults,
            images: msg.images,
            subtype: msg.subtype,
            model: msg.model,
          });
        }
        const firstUserMessage = allMessages.find((msg) => msg.role === "user");
        const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;
        retryQueue.add("createConversation", {
          userId, teamId, sessionId, agentType: client, title, startedAt: allMessages[0]?.timestamp,
        }, errMsg);
        piSyncedSigs.set(filePath, nextSynced);
        return;
      }
    }

    // A pure branch switch back onto a shorter branch produces no new turns, only
    // orphans — skip the empty batch and go straight to cleanup.
    let conversationRecreated = false;
    if (newMessages.length > 0) {
      const batchResult = await syncMessagesBatch(newMessages, conversationId, syncService, retryQueue);
      if (batchResult.authExpired) {
        log("⚠️  Authentication expired - sync paused");
        return; // leave the synced set unadvanced so the next pass retries
      }
      if (batchResult.conversationNotFound) {
        conversationRecreated = true;
        log(`Conversation ${conversationId} not found, invalidating cache and recreating...`);
        delete conversationCache[sessionId];
        saveConversationCache(conversationCache);

        const firstUserMessage = allMessages.find((msg) => msg.role === "user");
        const title = firstUserMessage ? generateTitleFromMessage(firstUserMessage.content) : undefined;
        try {
          conversationId = await syncService.createConversation({
            userId, teamId, sessionId, agentType: client, title, startedAt: allMessages[0]?.timestamp,
          });
          conversationCache[sessionId] = conversationId;
          saveConversationCache(conversationCache);
          log(`Recreated conversation ${conversationId} for ${client} session ${sessionId}`);
          // Fresh conversation: rebuild it from the FULL active branch, not just the
          // delta (the shared prefix isn't there anymore). No orphans to clean.
          await syncService.addMessages({ conversationId, messages: allMessages.map(prepMessageForSync) });
        } catch (retryErr) {
          const retryErrMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
          log(`Failed to recreate ${client} conversation and add messages: ${retryErrMsg}`);
        }
      }
    }

    // Branch-switch cleanup: delete the abandoned branch's already-synced turns so
    // the conversation equals the active branch exactly (never a splice). On a delete
    // failure keep the orphans in the synced set so the next pass retries rather than
    // stranding them permanently.
    let finalSynced = nextSynced;
    if (orphanUuids.length > 0 && !conversationRecreated) {
      try {
        await syncService.deleteMessagesByUuid(conversationId, orphanUuids);
        log(`Deleted ${orphanUuids.length} orphaned ${client} message(s) after branch switch for session ${sessionId}`);
      } catch (err) {
        logConvexFailure(err);
        finalSynced = new Map(nextSynced);
        for (const uuid of orphanUuids) finalSynced.set(uuid, syncedSigs.get(uuid) ?? "");
      }
    }

    piSyncedSigs.set(filePath, finalSynced);
    log(`Synced ${newMessages.length} ${client} messages for session ${sessionId}`);
    syncStats.messagesSynced += newMessages.length;
    syncStats.sessionsActive.add(sessionId);
    tryRegisterSessionProcess(sessionId, client);

    if (conversationId) {
      // Status is transcript-driven, like opencode's (8347): these clients'
      // panes are excluded from reconcileStatusFromPane (grok's ❯ composer
      // stays visible mid-turn and lies "idle"; pi/opencode have no glyph), so
      // the transcript tail is the settle signal — turn_completed (grok) / a
      // terminal stop (pi) flips the session out of "working" into its
      // turn-end verdict. The final tail always reaches here: turn_completed
      // stamps stopReason on the last assistant message, which changes its
      // messageSyncSig and re-opens the delta.
      const turn = classifyTranscriptTailFor(client)?.(content) ?? "unknown";
      sendAgentStatus(syncService, conversationId, sessionId, turn === "idle" ? resolveTurnEndStatus(sessionId) : "working");
    }

    updateStateCallback();
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err);
    log(`Error processing ${client} session file ${filePath}: ${errMsg}`);
  }
}

const processPiSession = processTranscriptDeltaSession.bind(null, "pi");
const processGrokSession = processTranscriptDeltaSession.bind(null, "grok");

interface ActiveSession {
  sessionId: string;
  conversationId: string;
  projectPath: string;
}

let reconnectAttempt = 0;
const BASE_DELAY_MS = 1000;
const MAX_DELAY_MS = 30000;

function getReconnectDelay(): number {
  const delay = Math.min(BASE_DELAY_MS * Math.pow(2, reconnectAttempt), MAX_DELAY_MS);
  reconnectAttempt++;
  return delay;
}

function resetReconnectDelay(): void {
  reconnectAttempt = 0;
}

interface ClaudeSessionInfo {
  pid: number;
  tty: string;
  sessionId: string;
  termProgram?: string;
}

function normalizeTty(tty: string): string {
  if (tty.startsWith("/dev/")) return tty;
  if (tty.startsWith("ttys")) return `/dev/${tty}`;
  if (tty.match(/^s\d+$/)) return `/dev/tty${tty}`;
  return `/dev/${tty}`;
}

// A remapped conversation keeps its old session id as an alias
// (remapConversationSession), so one conversation can have several cached ids.
// Reverse resolution must return the live resumable binding: a UUID beats a
// dead agent-*/forked-* alias; among same-shape ids the later (newer) wins.
export function preferLiveSessionId(prev: string | undefined, next: string): string {
  if (prev !== undefined && CLAUDE_UUID_RE.test(prev) && !CLAUDE_UUID_RE.test(next)) return prev;
  return next;
}

function buildReverseConversationCache(cache: ConversationCache): Record<string, string> {
  const reverse: Record<string, string> = {};
  for (const [sessionId, convId] of Object.entries(cache)) {
    reverse[convId] = preferLiveSessionId(reverse[convId], sessionId);
  }
  return reverse;
}

export function findCachedSessionIdForConversation(
  cache: Record<string, string>,
  conversationId: string,
): string | undefined {
  let found: string | undefined;
  for (const [sessionId, convId] of Object.entries(cache)) {
    if (convId === conversationId) found = preferLiveSessionId(found, sessionId);
  }
  return found;
}

function detectSessionAgentType(sessionId: string): AgentClientId {
  if (sessionId.startsWith("session-")) return "gemini";
  // staleOk: called from per-tick loops; a type hint from a slightly stale
  // index is fine (the type of an id never changes once its file exists).
  const sessionFile = findSessionFile(sessionId, { staleOk: true });
  return sessionFile?.agentType ?? "claude";
}

function tryRegisterSessionProcess(sessionId: string, agentType: AgentClientId): void {
  try {
    // Heartbeat membership is in-memory and lost on daemon restart, while registry
    // files persist on disk. Always ensure heartbeat is running for known sessions,
    // even when skipping the expensive process discovery below.
    if (syncServiceRef && !managedHeartbeatSessions.has(sessionId)) {
      const cache = readConversationCache();
      const conversationId = cache[sessionId];
      if (conversationId) {
        ensureManagedSessionHeartbeat(sessionId);
      }
    }

    const registryDir = path.join(CONFIG_DIR, "session-registry");
    const registryFile = path.join(registryDir, `${sessionId}.json`);

    if (fs.existsSync(registryFile)) {
      const stat = fs.statSync(registryFile);
      if (Date.now() - stat.mtimeMs < 300_000) return;
      // A hook-written claim is the process's own word about which session it
      // runs (see judgeProcessIdentity). While that pid lives, an opportunistic
      // rewrite would replace the truth with a lookup heuristic — the very
      // heuristic the identity check exists to second-guess — so leave it alone.
      try {
        const reg = JSON.parse(fs.readFileSync(registryFile, "utf-8"));
        if (isHookRegistration(reg) && typeof reg.pid === "number" && isProcessRunning(reg.pid)) return;
      } catch {}
    }

    findSessionProcess(sessionId, agentType).then((result) => {
      if (!result) return;
      try {
        fs.mkdirSync(registryDir, { recursive: true });
        fs.writeFileSync(registryFile, JSON.stringify({ pid: result.pid, tty: result.tty, ts: Math.floor(Date.now() / 1000), src: "daemon" }));
        log(`Opportunistically registered session ${sessionId.slice(0, 8)}: pid=${result.pid}, tty=${result.tty}`);
      } catch {}
      if (syncServiceRef) {
        const cache = readConversationCache();
        const conversationId = cache[sessionId];
        if (conversationId) {
          findTmuxPaneForTty(result.tty).then((tmuxPane) => {
            const tmuxSessionName = tmuxPane?.split(":")[0];
            syncServiceRef!.registerManagedSession(sessionId, result.pid, tmuxSessionName, conversationId).catch(() => {});
          }).catch(() => {
            syncServiceRef!.registerManagedSession(sessionId, result.pid, undefined, conversationId).catch(() => {});
          });
          ensureManagedSessionHeartbeat(sessionId);
        }
      }
    }).catch(() => {});
  } catch {}
}

// One `ps aux` for the whole daemon, refreshed at most every few seconds.
// findSessionProcessImpl used to grep the process table per session; a fleet
// sweep on a cache-cold daemon fired dozens of concurrent `ps aux | grep`
// pipelines, each 8s and ~20% CPU on a loaded box (load avg 389 on
// 2026-08-21) — a feedback loop where the probe itself was the load. Snapshot
// once, share across callers, filter in JS. `codecast` lines are dropped as the
// old `grep -v codecast` did (the daemon's own processes).
const PS_SNAPSHOT_TTL_MS = 3_000;
// One shared snapshot per `ps` argument list ("aux", "-axo pid=,ppid="), with
// in-flight dedup. execFile, not exec: through `/bin/sh -c` a timeout kills the
// shell and orphans `ps` to launchd still burning CPU (9 such orphans seen
// 2026-08-21); execFile's timeout kills ps itself. The duration is logged when
// slow so saturation is visible — on a 2000-process box one ps took 20s+.
const psSnapshots = new Map<string, { ts: number; lines: string[] }>();
const psSnapshotInflight = new Map<string, Promise<string[]>>();
async function psSnapshotLines(args: string[]): Promise<string[]> {
  const key = args.join(" ");
  const cached = psSnapshots.get(key);
  if (cached && Date.now() - cached.ts < PS_SNAPSHOT_TTL_MS) return cached.lines;
  const inflight = psSnapshotInflight.get(key);
  if (inflight) return inflight;
  const startedAt = Date.now();
  const run = (async () => {
    try {
      const { stdout } = await _execFileAsync("ps", args, { timeout: 30_000, killSignal: "SIGKILL", maxBuffer: 64 * 1024 * 1024, env: SAFE_ENV });
      const lines = String(stdout).split("\n").filter((l) => l.trim() && !l.includes("codecast"));
      psSnapshots.set(key, { ts: Date.now(), lines });
      const took = Date.now() - startedAt;
      if (took > 2_000) log(`[PS-SNAPSHOT] ps ${key} took ${took}ms (${lines.length} lines)`);
      return lines;
    } finally {
      psSnapshotInflight.delete(key);
    }
  })();
  psSnapshotInflight.set(key, run);
  return run;
}
async function psAuxLines(): Promise<string[]> {
  return psSnapshotLines(["aux"]);
}
/** Lines of the shared `ps aux` snapshot matching an ERE-style pattern. */
async function psAuxGrep(pattern: string): Promise<string[]> {
  const re = new RegExp(pattern);
  return (await psAuxLines()).filter((l) => re.test(l));
}

const findSessionProcessInflight = new Map<string, Promise<ClaudeSessionInfo | null>>();

/**
 * The token to grep the process table with (`ps aux | grep -E '<token>'`) when
 * locating a live session's process, per client. codex and gemini match by their
 * registry binary name (so a new jsonl-dir client plugs in via its descriptor).
 * claude and cursor share the caller-supplied claude-process pattern: cursor owns
 * a SQLite store and has no local process to resume, so a cursor lookup falls
 * through to claude's pattern exactly as before the registry. The two call sites
 * pass different claude patterns (a bare "claude" vs a hardened regex), so the
 * claude pattern stays a parameter rather than a descriptor field.
 */
export function sessionProcessGrepToken(agentType: AgentClientId, claudePattern: string): string {
  // grok is a compiled Rust binary whose ps comm/argv is its registry binary name
  // (verified live on v1.0.5) — same rule as codex/gemini. Falling through to the
  // claude pattern would grep for claude processes and never find a grok session.
  if (agentType === "codex" || agentType === "gemini" || agentType === "grok") return AGENT_CLIENTS[agentType].binary;
  // pi runs as `node …/@mariozechner/pi-coding-agent/dist/cli.js`, so its registry
  // binary "pi" is far too generic for `ps … | grep` (would match python/pip/…). Match
  // the distinctive package path that always appears in the process command line.
  if (agentType === "pi") return "pi-coding-agent";
  return claudePattern;
}

async function findSessionProcess(sessionId: string, agentType: AgentClientId = "claude"): Promise<ClaudeSessionInfo | null> {
  const key = `${sessionId}:${agentType}`;
  const inflight = findSessionProcessInflight.get(key);
  if (inflight) return inflight;

  // Every strategy below answers "where did this session run"; the identity
  // check answers "what does that pid run now". Strategies 0 and B check inline
  // so the search can continue past a foreign pid; this is the backstop for the
  // rest (the process cache, the cwd heuristics).
  const promise = findSessionProcessImpl(sessionId, agentType).then(async (result) => {
    if (result && await rejectsForeignProcess(sessionId, result.pid, "lookup")) {
      sessionProcessCache.delete(sessionId);
      return null;
    }
    return result;
  });
  findSessionProcessInflight.set(key, promise);
  return promise.finally(() => findSessionProcessInflight.delete(key));
}

// ── Process identity: which session does a pid actually run? ────────────────
// The verdict logic is pure (sessionProcessMatcher.judgeProcessIdentity); this
// is the plumbing: the pid's argv and start time from `ps`, and the hook claims
// for that pid from the session registry.
const HOOK_CLAIM_INDEX_TTL_MS = 60_000;
const HOOK_CLAIM_MAX_AGE_MS = 2 * 24 * 60 * 60 * 1000;
let hookClaimsByPid = new Map<number, ProcessSessionClaim[]>();
let hookClaimsIndexedAt = 0;

/** The SessionStart hook always records `term`; the daemon's opportunistic
 *  writes never did (and now carry `src: "daemon"`). Only the hook speaks for
 *  the process itself. */
function isHookRegistration(reg: unknown): boolean {
  return !!reg && typeof reg === "object" && typeof (reg as { term?: unknown }).term === "string"
    && (reg as { src?: unknown }).src !== "daemon";
}

let hookClaimsIndexing: Promise<void> | null = null;

// The registry dir holds thousands of files; only the recent ones (by mtime) are
// parsed, and the scan is async and shared so concurrent lookups don't each pay
// for it or block the loop.
async function hookClaimsForPid(pid: number): Promise<ProcessSessionClaim[]> {
  if (Date.now() - hookClaimsIndexedAt >= HOOK_CLAIM_INDEX_TTL_MS) {
    hookClaimsIndexing ??= (async () => {
      const dir = path.join(CONFIG_DIR, "session-registry");
      const next = new Map<number, ProcessSessionClaim[]>();
      const cutoffMs = Date.now() - HOOK_CLAIM_MAX_AGE_MS;
      try {
        for (const file of await fs.promises.readdir(dir)) {
          if (!file.endsWith(".json")) continue;
          const full = path.join(dir, file);
          try {
            if ((await fs.promises.stat(full)).mtimeMs < cutoffMs) continue;
            const reg = JSON.parse(await fs.promises.readFile(full, "utf-8"));
            if (!isHookRegistration(reg) || typeof reg.pid !== "number" || typeof reg.ts !== "number") continue;
            const list = next.get(reg.pid) ?? [];
            list.push({ sessionId: file.slice(0, -5), ts: reg.ts });
            next.set(reg.pid, list);
          } catch {}
        }
      } catch {}
      hookClaimsByPid = next;
      hookClaimsIndexedAt = Date.now();
    })().finally(() => { hookClaimsIndexing = null; });
    await hookClaimsIndexing;
  }
  return hookClaimsByPid.get(pid) ?? [];
}

/** argv, start time and hook claims of a live pid — the inputs to the identity verdict. */
async function describeProcessIdentity(pid: number): Promise<{ argvId: string | null; claims: ProcessSessionClaim[]; processStartSec: number | null }> {
  let etime = "";
  let argv = "";
  try {
    const { stdout } = await execAsync(`ps -o etime=,command= -p ${pid} 2>/dev/null`, { timeout: 3000, killSignal: "SIGKILL" });
    const line = stdout.trim();
    const sp = line.indexOf(" ");
    etime = sp === -1 ? line : line.slice(0, sp);
    argv = sp === -1 ? "" : line.slice(sp + 1).trim();
  } catch {}
  const elapsed = parsePsEtimeSeconds(etime);
  return {
    argvId: argvSessionId(argv),
    claims: await hookClaimsForPid(pid),
    processStartSec: elapsed === null ? null : Math.floor(Date.now() / 1000) - elapsed,
  };
}

/** The session a live pid runs by its own account (hook claim, else argv), or null. */
async function processDeclaredSession(pid: number): Promise<string | null> {
  return processDeclaredSessionId(await describeProcessIdentity(pid));
}

/** True (and logged) when `pid` demonstrably runs a session other than `sessionId`. */
async function rejectsForeignProcess(sessionId: string, pid: number, via: string): Promise<boolean> {
  const { verdict, declared } = judgeProcessIdentity({ sessionId, ...(await describeProcessIdentity(pid)) });
  if (verdict !== "foreign") return false;
  log(`[IDENTITY] pid=${pid} (${via}) runs session ${shortId(declared!)}, not ${shortId(sessionId)} — not using it`);
  return true;
}

async function findSessionProcessImpl(sessionId: string, agentType: AgentClientId = "claude"): Promise<ClaudeSessionInfo | null> {
  // Check process cache first
  const cached = await getCachedSessionProcess(sessionId);
  if (cached) {
    log(`Process cache hit for session ${shortId(sessionId)}: pid=${cached.pid}`);
    return cached;
  }

  const binaryPattern = sessionProcessGrepToken(agentType, "claude");

  try {
    const codexResumeCandidates: Array<{ pid: number; tty: string }> = [];
    // Strategy 0: Check session registry (written by SessionStart hook)
    try {
      const registryFile = path.join(CONFIG_DIR, "session-registry", `${sessionId}.json`);
      if (fs.existsSync(registryFile)) {
        const reg = JSON.parse(fs.readFileSync(registryFile, "utf-8"));
        const pid = reg.pid;
        const tty = normalizeTty(reg.tty);
        const termProgram = reg.term || undefined;
        // Verify process is still alive and is a claude-like process
        const { stdout: checkPs } = await execAsync(`ps -o comm= -p ${pid} 2>/dev/null`);
        if (checkPs.trim()) {
          if (agentType === "codex") {
            log(`Ignoring registry candidate for codex session ${shortId(sessionId)} (pid=${pid})`);
          } else if (await rejectsForeignProcess(sessionId, pid, "registry")) {
            // The pid lives on but runs another session now (a reused pid, or an
            // in-process switch): this registration is stale, not this session's.
            try { fs.unlinkSync(registryFile); } catch {}
          } else {
          const result = { pid, tty, sessionId, termProgram };
          cacheSessionProcess(sessionId, result);
          log(`Found session ${shortId(sessionId)} via registry: pid=${pid}, tty=${tty}, term=${termProgram ?? "unknown"}`);
          return result;
          }
        } else {
          // Process is dead, clean up stale registry
          try { fs.unlinkSync(registryFile); } catch {}
        }
      }
    } catch {}

    // Strategy A: find resumed sessions by command line
    try {
      const lines = await psAuxGrep(binaryPattern);
      const geminiCandidates: Array<{ pid: number; tty: string }> = [];
      for (const line of lines) {
        if (!line.trim()) continue;
        const isResume = isResumeInvocation(agentType, line);
        if (!isResume && agentType !== "gemini") continue;
        const parts = line.trim().split(/\s+/);
        if (parts.length < 7) continue;
        const pid = parseInt(parts[1], 10);
        const tty = parts[6];
        if (isNaN(pid) || tty === "?" || tty === "??") continue;
        const normalizedTty = normalizeTty(tty);
        if (line.includes(sessionId)) {
          if (agentType === "codex") {
            codexResumeCandidates.push({ pid, tty: normalizedTty });
            continue;
          }
          const result = { pid, tty: normalizedTty, sessionId };
          cacheSessionProcess(sessionId, result);
          log(`Found session ${shortId(sessionId)} via resume process match: pid=${pid}`);
          return result;
        }
        if (agentType === "gemini") {
          geminiCandidates.push({ pid, tty: normalizedTty });
        }
      }

      if (agentType === "gemini" && geminiCandidates.length > 0) {
        if (geminiCandidates.length === 1) {
          const only = geminiCandidates[0];
          const result = { pid: only.pid, tty: only.tty, sessionId };
          cacheSessionProcess(sessionId, result);
          log(`Found Gemini session ${shortId(sessionId)} via single process candidate: pid=${only.pid}`);
          return result;
        }

        // Gemini CLI may not expose session ids in argv; pick most recently started candidate.
        let newest: { pid: number; tty: string; startedAt: number } | null = null;
        for (const c of geminiCandidates) {
          try {
            const { stdout: startOut } = await execAsync(`ps -o lstart= -p ${c.pid}`);
            const startedAt = new Date(startOut.trim()).getTime();
            if (!isNaN(startedAt) && (!newest || startedAt > newest.startedAt)) {
              newest = { pid: c.pid, tty: c.tty, startedAt };
            }
          } catch {}
        }

        if (newest) {
          const result = { pid: newest.pid, tty: newest.tty, sessionId };
          cacheSessionProcess(sessionId, result);
          log(`Found Gemini session ${shortId(sessionId)} via newest process heuristic: pid=${newest.pid}`);
          return result;
        }

        const fallback = geminiCandidates[0];
        const result = { pid: fallback.pid, tty: fallback.tty, sessionId };
        cacheSessionProcess(sessionId, result);
        log(`Found Gemini session ${shortId(sessionId)} via fallback process candidate: pid=${fallback.pid}`);
        return result;
      }
    } catch {}

    // Strategy A2: Codex live-session matching by open JSONL file (works for non-resume iTerm sessions)
    if (agentType === "codex") {
      try {
        const stdout = (await psAuxGrep("codex")).join("\n");
        const lines = stdout.trim().split("\n");
        const candidates: Array<{ pid: number; tty: string; tmuxTarget: string | null }> = [];
        for (const line of lines) {
          if (!line.trim()) continue;
          const parts = line.trim().split(/\s+/);
          if (parts.length < 7) continue;
          const pid = parseInt(parts[1], 10);
          const tty = parts[6];
          if (isNaN(pid) || tty === "?" || tty === "??") continue;

          try {
            const { stdout: lsofOut } = await execAsync(`lsof -p ${pid} 2>/dev/null`);
            if (!hasCodexSessionFileOpen(lsofOut, sessionId)) continue;
            const normalizedTty = normalizeTty(tty);
            let tmuxTarget: string | null = null;
            try {
              tmuxTarget = await findTmuxPaneForTty(normalizedTty);
            } catch {}
            candidates.push({ pid, tty: normalizedTty, tmuxTarget });
          } catch {}
        }

        if (candidates.length > 0) {
          const preferred = choosePreferredCodexCandidate(candidates);
          if (!preferred) return null;
          const result = { pid: preferred.pid, tty: preferred.tty, sessionId };
          cacheSessionProcess(sessionId, result, preferred.tmuxTarget || undefined);
          if (preferred.tmuxTarget) {
            log(`Found codex session ${shortId(sessionId)} via lsof session file match (tmux): pid=${preferred.pid}`);
          } else {
            log(`Found codex session ${shortId(sessionId)} via lsof session file match (non-tmux preferred): pid=${preferred.pid}`);
          }
          return result;
        }

        if (codexResumeCandidates.length > 0) {
          const candidate = codexResumeCandidates[0];
          const result = { pid: candidate.pid, tty: candidate.tty, sessionId };
          cacheSessionProcess(sessionId, result);
          log(`Found codex session ${shortId(sessionId)} via resume process fallback: pid=${candidate.pid}`);
          return result;
        }
      } catch {}
    }

    // Strategy B: Scan tmux sessions named cc-resume-* or codecast-*
    try {
      const { stdout: tmuxList } = await tmuxExec(["list-sessions", "-F", "#{session_name}"]);
      for (const tmuxName of tmuxList.trim().split("\n")) {
        if (!(await tmuxSessionMatchesFullSessionId(tmuxName, sessionId))) continue;
        // Get the pane TTY for this tmux session
        try {
          const { stdout: paneInfo } = await tmuxExec(["list-panes", "-t", tmuxName, "-F", "#{pane_tty} #{pane_pid}"]);
          const paneLine = paneInfo.trim().split("\n")[0];
          if (paneLine) {
            const [paneTty, panePidStr] = paneLine.split(" ");
            const panePid = parseInt(panePidStr, 10);
            if (!isNaN(panePid) && paneTty) {
              try {
                const { stdout: childPs } = await execAsync(`pgrep -P ${panePid} -f ${binaryPattern} 2>/dev/null`);
                const childPid = parseInt(childPs.trim().split("\n")[0]?.trim(), 10);
                // A tmux named for this session can host another session's agent
                // (observed: cc-resume-c291b8e9 running `claude --resume 3d2a9117`).
                // The name is where the session was PUT; the process says what
                // runs there now.
                if (!isNaN(childPid) && await rejectsForeignProcess(sessionId, childPid, `tmux ${tmuxName}`)) continue;
                if (!isNaN(childPid)) {
                  const result = { pid: childPid, tty: normalizeTty(paneTty), sessionId };
                  cacheSessionProcess(sessionId, result, `${tmuxName}:0.0`);
                  log(`Found session ${shortId(sessionId)} via tmux session ${tmuxName}: pid=${childPid}`);
                  return result;
                }
                // No agent child process found - check if pane shell itself is an agent
                if ((await isAgentProcess(panePid)) && !(await rejectsForeignProcess(sessionId, panePid, `tmux ${tmuxName}`))) {
                  const result = { pid: panePid, tty: normalizeTty(paneTty), sessionId };
                  cacheSessionProcess(sessionId, result, `${tmuxName}:0.0`);
                  log(`Found session ${shortId(sessionId)} via tmux session ${tmuxName}: pid=${panePid} (direct)`);
                  return result;
                }
                log(`Tmux session ${tmuxName} has no active agent (shell pid=${panePid}), skipping`);
              } catch {}
            }
          }
        } catch {}
      }
    } catch {}

    // Strategy C: CWD-based matching for non-resumed sessions
    const jsonlPath = findSessionJsonlPath(sessionId);
    if (jsonlPath) {
      const jsonlStat = fs.statSync(jsonlPath);
      const recentlyModified = Date.now() - jsonlStat.mtimeMs < 60_000;

      if (recentlyModified) {
        // Determine the project directory from the JSONL content
        const jsonlContent = readFileHead(jsonlPath, 5000);
        const projectCwd = extractCwd(jsonlContent) || (agentType === "codex" ? extractCodexCwd(jsonlContent) : null);

        if (projectCwd) {
          try {
            const psPattern = sessionProcessGrepToken(agentType, "/claude\\b|claude-code");
            const psOut = (await psAuxGrep(psPattern)).join("\n");
            const candidates: Array<{ pid: number; tty: string }> = [];

            for (const line of psOut.trim().split("\n")) {
              if (!line.trim()) continue;
              const parts = line.trim().split(/\s+/);
              if (parts.length < 7) continue;
              const pid = parseInt(parts[1], 10);
              const tty = parts[6];
              if (isNaN(pid) || tty === "?" || tty === "??") continue;

              // Check CWD of this process
              try {
                const { stdout: lsofOut } = await execAsync(`lsof -d cwd -a -p ${pid} -F n 2>/dev/null`);
                const cwdLine = lsofOut.split("\n").find(l => l.startsWith("n"));
                if (cwdLine) {
                  const processCwd = cwdLine.slice(1);
                  // Match if CWD is the project dir or a subdirectory of it
                  if (processCwd === projectCwd || processCwd.startsWith(projectCwd + "/")) {
                    candidates.push({ pid, tty: normalizeTty(tty) });
                  }
                }
              } catch {}
            }

            // Filter out candidates already cached for a different session
            const unclaimed = candidates.filter(c => {
              for (const [cachedSid, cachedInfo] of sessionProcessCache) {
                if (cachedSid !== sessionId && cachedInfo.pid === c.pid) return false;
              }
              return true;
            });

            if (unclaimed.length === 1) {
              const result = { pid: unclaimed[0].pid, tty: unclaimed[0].tty, sessionId };
              cacheSessionProcess(sessionId, result);
              log(`Found session ${shortId(sessionId)} via CWD match: pid=${unclaimed[0].pid}, cwd=${projectCwd}`);
              return result;
            } else if (unclaimed.length > 1) {
              // Disambiguate using JSONL birth time vs process start time
              const jsonlBirthMs = jsonlStat.birthtimeMs;
              let bestCandidate: { pid: number; tty: string } | null = null;
              let bestDelta = Infinity;

              for (const c of unclaimed) {
                try {
                  const { stdout: etimeOut } = await execAsync(`ps -o lstart= -p ${c.pid}`);
                  const processStart = new Date(etimeOut.trim()).getTime();
                  const delta = Math.abs(processStart - jsonlBirthMs);
                  if (delta < bestDelta) {
                    bestDelta = delta;
                    bestCandidate = c;
                  }
                } catch {}
              }

              if (bestCandidate && bestDelta < 300_000) {
                const result = { pid: bestCandidate.pid, tty: bestCandidate.tty, sessionId };
                cacheSessionProcess(sessionId, result);
                log(`Found session ${shortId(sessionId)} via CWD+timing match: pid=${bestCandidate.pid}, delta=${Math.round(bestDelta / 1000)}s`);
                return result;
              }
              log(`CWD match found ${unclaimed.length} unclaimed candidates for ${shortId(sessionId)}, could not disambiguate`);
            } else {
              log(`CWD match found ${candidates.length} candidates for ${shortId(sessionId)} but all claimed by other sessions`);
            }
          } catch {}
        }
      }
    }

    return null;
  } catch (err) {
    log(`Error finding Claude session process: ${err instanceof Error ? err.message : String(err)}`);
    return null;
  }
}

// Session-control commands (escape / rewind / send_keys) must act on the SAME
// pane a message injection lands in, so they resolve through the delivery
// resolver first and only then fall back to the pid -> tty -> pane scan. On
// 2026-08-28 an escape resolved by the tty scan alone missed the cached pane,
// fell back to SIGINT on the claude pid, and cancelled the turn a message had
// started 400ms earlier (the web then showed "hasn't reached the agent").
async function resolveSessionCommandPane(
  conversationId: string,
  sessionId: string,
  agentType: AgentClientId,
): Promise<{ tmuxTarget: string | null; proc: ClaudeSessionInfo | null }> {
  const live = await resolveLiveTmuxTarget(conversationId, sessionId, agentType);
  if (live.tmuxTarget) {
    const target = live.tmuxTarget.includes(":") ? live.tmuxTarget : `${live.tmuxTarget}:0.0`;
    if (validateTmuxTarget(target)) return { tmuxTarget: target, proc: live.proc };
  }
  const proc = live.proc ?? (await findSessionProcess(sessionId, agentType));
  if (!proc) return { tmuxTarget: null, proc: null };
  const tmuxTarget = await findTmuxPaneForTty(proc.tty);
  return { tmuxTarget: tmuxTarget && validateTmuxTarget(tmuxTarget) ? tmuxTarget : null, proc };
}

async function findTmuxPaneForTty(tty: string): Promise<string | null> {
  if (!hasTmux()) return null;
  try {
    const { stdout } = await tmuxExec(["list-panes", "-a", "-F", "#{pane_tty} #{session_name}:#{window_index}.#{pane_index}"]);
    const normalizedTty = normalizeTty(tty);

    for (const line of stdout.trim().split("\n")) {
      const [paneTty, target] = line.split(" ");
      if (paneTty === normalizedTty && target) {
        return target;
      }
    }
    return null;
  } catch {
    return null;
  }
}

type InteractivePrompt = { question: string; options: Array<{ label: string; description?: string }>; isConfirmation?: boolean; header?: string; firstOptionIdx?: number; multiSelect?: boolean };

// Unicode "Box Drawing" block (┌┐└┘─│ …). An AskUserQuestion option's `preview`
// renders as a box to the RIGHT of the options; tmux capture-pane flattens those
// columns onto the option rows, so naive parsing captures "│ … │" as a description.
// Such content is never an option's own description — we drop it so a scraped card
// never carries box-drawing glyphs (the full-fidelity card comes from the JSONL).
const BOX_DRAWING_CHARS = /[─-╿]/;

// Newer AskUserQuestion menus print a short label "chip" on its own line above the
// question — e.g. "□ Stale pending policy". The glyph is a box/ballot character
// (NOT in the Box Drawing block, so BOX_DRAWING_CHARS won't catch it). The web card
// renders this as `header`; the scrape used to drop it so scraped cards had no chip.
const HEADER_CHIP = /^[□☐☑☒▢▣◻◼◽◾■]\s*(.+)$/;
// ▔/▁ are the top/bottom edges of newer dialog frames (Block Elements, outside the
// Box Drawing range). capture-pane -J can also glue a full-width rule onto the text
// row that follows it, so RULE_RUN strips leading/trailing runs off heading lines.
const SEPARATOR_LINE = /^[─━═▔▁\-_]{5,}$/;
const RULE_RUN_EDGE = /^[─━═▔▁\-_]{3,}\s*|\s*[─━═▔▁\-_]{3,}$/g;

// A multiSelect AskUserQuestion renders a checkbox between the number and the
// label — "1. [ ] Restart" / "2. [x] Redeploy" (or a unicode ballot box). It's a
// selection-state glyph, not part of the label, so strip it off the front. Only a
// 0-or-1-char bracket pair counts, so real bracketed labels like "[Recommended]"
// survive.
const CHECKBOX_PREFIX = /^\s*(?:\[[ xX*✓✔·]?\]|[□☐☑☒▢▣◻◼◽◾])\s*/;
// Claude Code appends two synthetic affordance rows to every AskUserQuestion menu:
// a free-text "Type something" row and a "Chat about this" escape hatch. They carry
// no real description — and the free-text row renders a "Submit" button beneath it
// that must not be scraped as its description.
const SYNTHETIC_OPTION = /^(?:type something\.?|chat about this)$/i;

// Key-hint rows of a real interactive dialog footer ("Enter to select · ↑/↓ to
// navigate · Esc to cancel"). A row qualifies only on a STRONG hint or two weaker
// ones together: these sessions talk ABOUT terminal UIs, so prose like "←/→ to
// move between chips" or a lone "Esc to cancel" spec line is routine conversation
// content, and a loose any-hint scan is how numbered prose answers became poll
// cards (conv jx795ez, then again conv jx730d3).
const FOOTER_HINT_STRONG = /enter to (confirm|select)|(?:press\s+)?n\s+to\s+add\s+notes|[↑↓]\s*\/\s*[↑↓]\s*to\s+(navigate|select|choose)|arrow keys to (navigate|select|choose)/i;
const FOOTER_HINT_WEAK = [/↑\s*\/?\s*↓/, /←\s*\/?\s*→/, /esc(ape)?\s+to\s+(exit|cancel)/i, /tab to switch/i, /arrow keys/i];
function isMenuFooterRow(line: string): boolean {
  if (FOOTER_HINT_STRONG.test(line)) return true;
  let weak = 0;
  for (const atom of FOOTER_HINT_WEAK) if (atom.test(line)) weak++;
  return weak >= 2;
}
// Markers of the composer's hint bar — by the time one of these is on screen
// below the "options", we're looking at the prompt area, not a blocking dialog.
const COMPOSER_BAR = /\?\s+for shortcuts|shift\+tab to cycle|bypass permissions|accept edits on|plan mode on|esc to interrupt/i;
// Rows that exist only while the agent UI is LIVE and unblocked: the working
// spinner ("✢ Actualizing… (3m 6s · …)" — flush-left glyph) and the composer
// caret ("❯" bare or with a typed draft). A blocking dialog REPLACES the composer
// and spinner, so any of these BELOW a candidate menu is structural proof the
// "menu" is scrolled conversation content, not a live dialog. The caret regex
// exempts "❯ 1." cursor-on-option rows and the cursor parked on a synthetic row.
const SPINNER_ROW = /^[✻✶✢✳✽·]\s+\S/;
const COMPOSER_CARET_ROW = /^\s?❯(?!\s*\d+[.)]\s)(?!\s*(?:Chat about this|Type something))/;

// True when any live-composer row sits below `fromIdx` — the pane is not blocked
// on a dialog there. Box-art rows are skipped (a dialog's right-hand preview box
// can contain arbitrary text, including hint-like glyphs).
function liveComposerBelow(lines: string[], fromIdx: number): boolean {
  for (let i = fromIdx + 1; i < lines.length; i++) {
    if (BOX_DRAWING_CHARS.test(lines[i])) continue;
    if (COMPOSER_BAR.test(lines[i]) || SPINNER_ROW.test(lines[i]) || COMPOSER_CARET_ROW.test(lines[i])) return true;
  }
  return false;
}

// A real menu's footer renders inside the dialog, below the options, separated only
// by dialog chrome: blank rows, rules, the right-hand preview's box art, indented
// continuation/description rows, or the synthetic free-text rows. Hunting for hints
// in the whole tail below the options is how a prose answer with numbered section
// headings became a poll: its "options" sat mid-pane and the scan picked up
// hint-like text from the composer/status region dozens of rows further down. Walk
// down only while rows stay dialog-shaped; anything else (an assistant ⏺ bullet,
// the ❯ composer, a shell prompt) means we left the dialog without meeting a footer.
export function menuFooterBelowOptions(lines: string[], lastOptionIdx: number): boolean {
  for (let i = lastOptionIdx + 1, cap = Math.min(lines.length, lastOptionIdx + 41); i < cap; i++) {
    if (COMPOSER_BAR.test(lines[i])) return false;
    if (isMenuFooterRow(lines[i])) return true;
    const trimmed = lines[i].trim();
    if (!trimmed) continue;
    const dialogish = SEPARATOR_LINE.test(trimmed) || BOX_DRAWING_CHARS.test(lines[i])
      || /^\s{2,}/.test(lines[i]) || SYNTHETIC_OPTION.test(trimmed);
    if (!dialogish) return false;
  }
  return false;
}

// Pull the header chip and the (possibly multi-line) question out of the lines above
// the first option. The question can wrap across several rows; the menu renderer
// breaks it mid-sentence, so taking only the last line truncated it. Walk upward from
// the first option, stitching contiguous text until a blank line, separator, cursor
// row, or the chip bounds it — anything past those belongs to a prior turn. The chip
// itself can sit a blank line above the question, so scan for it independently.
function extractPromptHeading(lines: string[], firstOptionIdx: number): { header?: string; question: string } {
  const start = Math.max(0, firstOptionIdx - 8);
  let header: string | undefined;
  for (let i = firstOptionIdx - 1; i >= start; i--) {
    const chip = lines[i].trim().match(HEADER_CHIP);
    if (chip) { header = chip[1].trim(); break; }
  }
  const qLines: string[] = [];
  for (let i = firstOptionIdx - 1; i >= start; i--) {
    const trimmed = lines[i].trim();
    if (HEADER_CHIP.test(trimmed)) break;
    if (!trimmed) { if (qLines.length) break; else continue; }
    if (/^[❯>]/.test(trimmed) || SEPARATOR_LINE.test(trimmed)) break;
    // -J join can fuse a full-width dialog rule onto the question's own row
    // ("▔▔▔… What do you want to do?") — strip edge runs; a row that was ONLY
    // a short rule is chrome and bounds the question like a separator.
    const deRuled = trimmed.replace(RULE_RUN_EDGE, "").trim();
    if (!deRuled) { if (qLines.length) break; else continue; }
    qLines.unshift(deRuled);
  }
  const question = qLines.join(" ") || header || "Select an option";
  return { header, question };
}

export function parseInteractivePrompt(text: string): InteractivePrompt | null {
  const lines = text.split("\n");
  const optionPattern = /^\s*[❯>)]*\s*(\d+)[.)]\s+(.+?)(?:\s{2,}(.+?))?$/;
  const options: Array<{ label: string; description?: string }> = [];
  let firstOptionIdx = -1;
  let lastOptionIdx = -1;
  let gapCount = 0;
  let hasCursorIndicator = false;
  // Any option row carrying a checkbox glyph marks the menu as multiSelect. This
  // matters because a pending AskUserQuestion never reaches the session JSONL on
  // Claude Code ≥2.1.201 (the tool_use is only written once answered), so the live
  // card is always scrape/sidecar-sourced — and the hook sidecar goes stale after
  // 5 minutes, leaving this glyph as the only multiSelect signal.
  let hasCheckbox = false;
  // The AskUserQuestion menu renders each option's description on indented
  // continuation lines BELOW the numbered label. We scan bottom-up, so those
  // lines arrive before their option; buffer them and attach on the next match.
  let pendingDesc: string[] = [];

  for (let i = lines.length - 1; i >= 0; i--) {
    const m = lines[i].match(optionPattern);
    if (m) {
      if (lastOptionIdx < 0) lastOptionIdx = i;
      firstOptionIdx = i;
      if (/^\s*[❯>]\s*\d/.test(lines[i])) hasCursorIndicator = true;
      if (CHECKBOX_PREFIX.test(m[2])) hasCheckbox = true;
      const label = m[2]
        .replace(CHECKBOX_PREFIX, "")        // multiSelect checkbox: "[ ]" / "[x]" / "☐"
        .replace(/\s*[✓✗✔☑]\s*/g, "")        // stray selection glyphs anywhere
        .trim();
      if (label.length > 200) { pendingDesc = []; continue; }
      // A same-line trailing segment is a real description only if it isn't the
      // right-hand preview box flattened onto this row (see BOX_DRAWING_CHARS).
      const inlineDesc = m[3]?.trim();
      const descParts = [
        inlineDesc && !BOX_DRAWING_CHARS.test(inlineDesc) ? inlineDesc : undefined,
        ...pendingDesc,
      ].filter((s): s is string => !!s);
      // The synthetic "Type something" / "Chat about this" rows never have a real
      // description; the "Submit" button under the free-text row would otherwise be
      // mis-scraped as one.
      const description = SYNTHETIC_OPTION.test(label)
        ? undefined
        : descParts.length ? descParts.join(" ") : undefined;
      if (label) options.unshift({ label, description });
      pendingDesc = [];
      gapCount = 0;
    } else if (options.length > 0) {
      const trimmed = lines[i].trim();
      // A continuation/description line is indented past the flush-left question.
      // multiSelect menus indent descriptions only 2 spaces — the same column as
      // non-cursor option rows ("  2.") — so the old 4-space floor treated every
      // such description as prose and broke the bottom-up scan, dropping options.
      const isIndented = /^\s{2,}/.test(lines[i]);
      const isSeparator = /^[─━═\-_]{3,}$/.test(trimmed);
      // A row carrying any box-drawing glyph is the side-panel preview, not a
      // continuation of the option's description — treat it as a gap, not text.
      const isBoxArt = BOX_DRAWING_CHARS.test(trimmed);
      if (trimmed && isIndented && !isSeparator && !isBoxArt && trimmed.length <= 300) {
        // Indented continuation line = description for the option just above it.
        pendingDesc.unshift(trimmed);
      } else if (!trimmed || isIndented || isSeparator || isBoxArt) {
        gapCount++;
        if (gapCount > 8) break;
      } else {
        break;
      }
    }
  }

  // Structural gate for both paths: a live composer/spinner below the candidate
  // proves the pane is NOT blocked on a dialog — the "menu"/"hint" is scrolled
  // conversation content. Content checks alone can't make this call (prose here
  // routinely contains literal key-hint text).
  if (options.length >= 2 && firstOptionIdx >= 0 && !liveComposerBelow(lines, lastOptionIdx)) {
    const hasFooter = menuFooterBelowOptions(lines, lastOptionIdx);
    if (hasCursorIndicator || hasFooter) {
      const { header, question } = extractPromptHeading(lines, firstOptionIdx);
      return { question, options, firstOptionIdx, ...(header ? { header } : {}), ...(hasCheckbox ? { multiSelect: true } : {}) };
    }
  }

  // Detect confirmation prompts: "Press Enter to continue..." / "Esc to cancel"
  const tailLines = lines.slice(-15);
  const joined = tailLines.join("\n");
  const enterMatch = joined.match(/(?:press\s+)?enter\s+to\s+(continue|confirm|proceed|accept)[\s.…]*/i);
  const escMatch = joined.match(/esc(?:ape)?\s+to\s+(cancel|exit|quit|go back)[\s.…]*/i);
  if (enterMatch && !tailLines.some(l => COMPOSER_BAR.test(l) || SPINNER_ROW.test(l) || COMPOSER_CARET_ROW.test(l))) {
    // Question extraction: real interstitials (the usage-limit dialog, trust
    // prompts) draw a rule as their top edge with the question right below it.
    // Search only BELOW the last rule in the tail — the old "topmost non-hint
    // line of the tail" reached above the dialog and shipped unrelated prose
    // fragments ("singleton merge implementation:") as the card's question.
    // Two-column dialog rows are flattened by capture-pane, so keep only the
    // left column (3+ spaces = column gap), and strip bullet/box glyphs.
    const ruleIdx = tailLines.reduce((acc, l, i) => (/[─━═▔▁]{5,}/.test(l) ? i : acc), -1);
    let question = "Continue?";
    for (const raw of tailLines.slice(ruleIdx + 1)) {
      if (/press|enter|esc/i.test(raw)) continue;     // key-hint rows
      if (/^\s*[❯>]\s/.test(raw)) continue;           // selection-cursor option rows
      const cleaned = raw.replace(/[─-╿▔▁]/g, " ").replace(/^\s*[⏺●]\s*/, "")
        .trim().split(/\s{3,}/)[0]?.trim() ?? "";
      if (cleaned.length > 5) { question = cleaned; break; }
    }
    const confirmOptions: Array<{ label: string; description?: string }> = [
      { label: `Continue (${enterMatch[1]})` },
    ];
    if (escMatch) {
      confirmOptions.push({ label: `Cancel (${escMatch[1]})` });
    }
    return { question, options: confirmOptions, isConfirmation: true };
  }

  return null;
}

// Claude Code's spend-limit interstitial — "What do you want to do?" over the
// unnumbered "Adjust monthly spend limit" / "Wait for limit to reset" rows — is
// TUI-only: unlike the one-line limit banners, it writes NO isApiErrorMessage
// entry to the JSONL (verified 2026-08-14: a 1:40pm park left the transcript
// untouched), so the pane scrape is the only place the park is visible. Shipping
// the generic Continue/Cancel confirmation card for it is worse than nothing:
// the card's "Continue" sends Enter, and Enter here CONFIRMS the highlighted
// billing option (the near-miss documented on the 2026-07-13 paywall incident).
// Instead the daemon emits the canonical limit banner text this function
// returns — classifyApiErrorBanner reads it as kind "limit", which is the same
// path a CLI-written banner takes: pending_api_error_kind="limit", the blocked
// badge, the auto-switch check, and continue-on-reset all follow from it.
export function spendLimitDialogBanner(paneContent: string): string | null {
  const tail = paneContent.split("\n").slice(-20).join("\n");
  if (!/Adjust monthly spend limit/i.test(tail) || !/Wait for limit to reset/i.test(tail)) return null;
  // A live dialog carries its key-hint footer in the same tail; a scrollback
  // echo of the dialog text (e.g. quoted in prose) doesn't.
  if (!/enter to confirm/i.test(tail)) return null;
  const resets = tail.match(/\b(Resets [^\n]+?)(?:\s{3,}|\s*$)/im)?.[1]?.trim();
  return `You've hit your monthly spend limit · ${resets ?? "parked at the spend limit dialog"}`;
}

// The same park, wearing the other costume. The spend dialog above has
// UNNUMBERED rows so parseInteractivePrompt reads it as a confirmation; the
// usage-limit variant — "What do you want to do?" over "Stop and wait for
// limit to reset" / "Switch to usage credits" / "Switch to Team plan" — is a
// NUMBERED menu, so it slipped past the confirmation-only check above and got
// minted as an ordinary poll card (uuid `interactive-prompt-…`). That card is
// the same hazard the spend dialog was fixed for: its options are billing
// actions, so "answering" it changes the plan.
//
// Recognized by the option rows via the shared isUsageLimitDialog, which the
// web's decision queue uses too, so the daemon and the queue can never
// disagree about what counts as a billing interstitial.
export function usageLimitMenuBanner(
  paneContent: string,
  optionLabels: readonly string[]
): string | null {
  if (!isUsageLimitDialog(optionLabels)) return null;
  const tail = paneContent.split("\n").slice(-20).join("\n");
  const resets = tail.match(/\b(Resets [^\n]+?)(?:\s{3,}|\s*$)/im)?.[1]?.trim();
  return `You've hit your usage limit · ${resets ?? "parked at the usage limit dialog"}`;
}

// Claude Code renders each assistant message with a leading bullet ("⏺" on current
// builds, "●" on older ones) and indents its continuation lines two spaces. A turn
// that ends in AskUserQuestion is buffered out of the JSONL until answered, so while
// the question is pending the reasoning that motivates it lives ONLY in the rendered
// pane. Pull that prose block back out so the web question card can show *why* it's
// being asked — best-effort while pending, replaced byte-exact when the turn flushes.
const ASSISTANT_BULLET = /^(?:⏺|●)\s+/;
// Markers that bound this turn from above: a user prompt ("❯ …" / "> …"), the working
// spinner ("✻ …" / "✶ …"), or a tool bullet ("⏺ Bash(…)") / its result gutter ("⎿ …")
// / a collapsed-output summary. Crossing one means we've walked into a prior turn or a
// tool call, not the prose that precedes the question.
const PROSE_STOP_ABOVE = /^\s*(?:❯|>|✻|✶|✳)\s/;
const TOOLISH_LINE = /^(?:⏺\s+\w+\(|⎿|\s*(?:Called|Running)\b.*\(ctrl\+o)/;

// Extract the assistant prose immediately above an interactive prompt's menu. Returns
// "" when there's no preceding prose (e.g. a bare slash menu or a tool call sits right
// above the dialog). Anchored on parseInteractivePrompt's option index so numbered
// lists *inside* the prose ("1. Task-tool subagents …") can't be mistaken for the menu.
export function extractAssistantProseAbovePrompt(paneText: string): string {
  const parsed = parseInteractivePrompt(paneText);
  if (!parsed || parsed.isConfirmation || parsed.firstOptionIdx == null) return "";
  const firstOptionIdx = parsed.firstOptionIdx;
  const lines = paneText.split("\n");

  // dialogTop: the topmost chrome row that caps the menu. Walk up from the options past
  // the question/tab/blank rows to the first full-width rule or header chip (bounded to a
  // short window so a far-away rule from a PRIOR turn — e.g. an "★ Insight ───" block —
  // can't be mistaken for it)...
  let chromeBottom = -1;
  for (let i = firstOptionIdx - 1, floor = Math.max(0, firstOptionIdx - 20); i >= floor; i--) {
    const t = lines[i].trim();
    if (SEPARATOR_LINE.test(t) || HEADER_CHIP.test(t)) { chromeBottom = i; break; }
  }
  if (chromeBottom < 0) return "";
  // ...then absorb any contiguous chrome/blank rows above it, so a separator sitting
  // over a header chip (older menu format) becomes the true top instead of dangling as
  // a stray "───" line at the end of the recovered prose.
  let dialogTop = chromeBottom;
  for (let i = chromeBottom - 1; i >= 0; i--) {
    const t = lines[i].trim();
    if (!(SEPARATOR_LINE.test(t) || HEADER_CHIP.test(t))) break; // blank or prose ends the run
    dialogTop = i;
  }

  // proseStart: the nearest assistant bullet above dialogTop. Bail if we cross a turn
  // boundary or a tool bullet first — then no buffered prose precedes this question.
  let proseStart = -1;
  for (let i = dialogTop - 1, floor = Math.max(0, dialogTop - 100); i >= floor; i--) {
    const raw = lines[i];
    if (!raw.trim()) continue;
    if (ASSISTANT_BULLET.test(raw)) { proseStart = TOOLISH_LINE.test(raw) ? -1 : i; break; }
    if (PROSE_STOP_ABOVE.test(raw) || TOOLISH_LINE.test(raw)) break;
  }
  if (proseStart < 0) return "";

  // Collect [proseStart, dialogTop): strip the bullet off the first line and the 2-space
  // gutter off the rest. Keep blank lines and inner "───"/list rows — they're part of the
  // reasoning, and markdown reflow on the client smooths the TUI's hard wraps.
  const out: string[] = [];
  for (let i = proseStart; i < dialogTop; i++) {
    const s = (i === proseStart ? lines[i].replace(ASSISTANT_BULLET, "") : lines[i].replace(/^ {1,2}/, ""));
    out.push(s.replace(/\s+$/, ""));
  }
  while (out.length && !out[out.length - 1].trim()) out.pop();
  return out.join("\n").trim().slice(0, 6000);
}

// A real AskUserQuestion's full tool_input (every question, header, option label AND
// description, multiSelect) is handed to us by the PreToolUse/PermissionRequest hook —
// the one place it exists while the turn is buffered. The hook drops it in a per-session
// sidecar (codecast-status.sh) because it's too large to ride the status URL. Read it so
// the card is full-fidelity instead of a box-art-stripped scrape. Stale files (>5min, or
// from a prior question) are ignored; the live menu's question is the cross-check.
function readAskUserQuestionInput(sessionId: string): { questions: any[] } | null {
  try {
    const p = path.join(ASK_INPUT_DIR, `${sessionId}.json`);
    const stat = fs.statSync(p);
    if (Date.now() - stat.mtimeMs > 5 * 60_000) return null;
    const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
    if (Array.isArray(parsed?.questions) && parsed.questions.length) return { questions: parsed.questions };
  } catch {}
  return null;
}

// Guard against a stale sidecar (a prior question's tool_input) being stamped onto the
// menu now on screen: only trust it when its first question matches the scraped one.
// Both are normalized to alphanumerics so the scrape's wrapping/glyph noise doesn't
// defeat the match; a 24-char overlap either way is a confident same-question signal.
export function sidecarMatchesScrape(questions: any[], scrapedQuestion: string): boolean {
  const norm = (s: string) => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  const sq = norm(questions?.[0]?.question);
  const pq = norm(scrapedQuestion);
  if (sq.length < 8 || pq.length < 8) return false;
  return sq.includes(pq.slice(0, 24)) || pq.includes(sq.slice(0, 24));
}

// Build the AskUserQuestion card's `questions`: the hook's real tool_input when it's for
// THIS on-screen question (full option descriptions, header, multiSelect — all of which
// the box-art scrape loses), otherwise the scraped prompt as a graceful fallback.
export function resolveInteractiveQuestions(prompt: InteractivePrompt, sidecar: { questions: any[] } | null): any[] {
  if (sidecar && sidecarMatchesScrape(sidecar.questions, prompt.question)) return sidecar.questions;
  return [{
    question: prompt.question,
    ...(prompt.header ? { header: prompt.header } : {}),
    options: prompt.options,
    ...(prompt.isConfirmation ? { isConfirmation: true } : {}),
    ...(prompt.multiSelect ? { multiSelect: true } : {}),
  }];
}

// `multi` marks a poll whose digit keys are multiSelect checkbox TOGGLES: the menu is
// expected to stay on the same question after each one, so the tmux closed-loop must
// not "confirm" them with Enter (Enter on a multiSelect list toggles the highlighted
// row, corrupting the selection). The sender navigates tabs itself via Right/Enter.
type PollMessage = { keys?: string[]; steps?: Array<{ key: string; text?: string }>; text?: string; display?: string; multi?: boolean };

export function parsePollMessage(content: string): PollMessage | null {
  try {
    const parsed = JSON.parse(content);
    if (parsed.__cc_poll && (Array.isArray(parsed.keys) || Array.isArray(parsed.steps) || typeof parsed.text === "string")) return parsed;
  } catch {}
  return null;
}

// A free-text answer to an AskUserQuestion menu. Claude Code's question menu has no
// inline text slot, so the only way to enter free text is to decline the whole menu
// (Escape) and type the answer at the prompt — which discards every menu selection. The
// web sends such an answer as a top-level `text` with no menu keys; pre-2026-06-27 builds
// embedded it inside `steps` (one step per `text`). BOTH are a decline: do it ONCE up
// front, then type. Doing it per-step (the old behavior) declined the menu mid-loop and
// spilled the remaining option digits into the freshly-reopened prompt box (the "211"
// bug). The OTHER text shape — menu keys PLUS `poll.text` (e.g. plan feedback, where
// option 4 opens a feedback field) — is NOT a decline: those keys drive a menu whose
// final option opens the text input, so the text lands in the field, not at the prompt.
//
// Returns the text to type after the decline (newlines flattened — a literal LF reads as
// Enter in the TUI and submits early, which is why the normal paste path flattens too; the
// middot keeps multi-answer prose readable on one line), or null when this isn't a decline.
export function pollDeclineText(poll: PollMessage): string | null {
  const steps: Array<{ key: string; text?: string }> = poll.steps || (poll.keys || []).map(k => ({ key: k }));
  const menuSteps = steps.filter(s => !s.text);
  const embeddedText = steps.filter(s => s.text).map(s => s.text!).join("\n\n");
  const isDecline = (poll.text != null && menuSteps.length === 0) || (embeddedText !== "" && poll.text == null);
  if (!isDecline) return null;
  return (poll.text ?? embeddedText).replace(/\r?\n+/g, "  ·  ").trim();
}

// The menu-navigation steps of a poll (the option keystrokes), excluding any step that
// carries embedded free text (those decline the menu — see pollDeclineText).
export function pollMenuSteps(poll: PollMessage): Array<{ key: string; text?: string }> {
  const steps: Array<{ key: string; text?: string }> = poll.steps || (poll.keys || []).map(k => ({ key: k }));
  return steps.filter(s => !s.text);
}

// The synthetic poll the daemon emits for a live interactive prompt must carry a
// STABLE message id. checkForInteractivePrompt fires from several call sites
// (post-inject, post-resume, heartbeat) that can race inside the capture-delay
// window — all pass the pending guard before any of them sets it — and a
// timestamped uuid made each emit a distinct server row, so the same prompt
// rendered 4-5x in the UI. Keying the uuid on the prompt's *content* makes
// addMessages idempotent: addMessages upserts by (conversation_id, message_uuid),
// so identical prompts collapse to a single row no matter how many callers detect
// them. Distinct prompts still get distinct ids and render separately.
export function interactivePromptMessageUuid(sessionId: string, prompt: InteractivePrompt): string {
  const canonical = JSON.stringify({
    q: prompt.question,
    o: prompt.options.map(o => [o.label, o.description ?? ""]),
    c: !!prompt.isConfirmation,
  });
  const digest = createHash("sha256").update(canonical).digest("hex").slice(0, 16);
  return `interactive-prompt-${sessionId}-${digest}`;
}

// Retire a previously-emitted synthetic prompt card: sync a tool_result for its
// tool_use so every client stops rendering an open, answerable question. A real
// AskUserQuestion is closed by the CLI's own JSONL flush, but a scraped TUI menu
// (a /model confirmation, a trust dialog) resolves invisibly — answered by
// injected keys, dismissed in the terminal, or blown away by a queued delivery's
// Enter — and nothing else ever writes its tool_result. Without this, the card
// stays open in the conversation forever and a late click fires keys into
// whatever the pane shows by then. The daemon emitted the card, so the daemon
// owns its whole lifecycle. No-op when nothing synthetic is on record (real-AUQ
// deferrals and limit banners never set an interactive-prompt uuid).
// The uuid to emit for a freshly detected menu: content-deterministic, but a
// menu already closed once (tool_result synced) mints a suffixed id — the
// upsert would otherwise revive the old row, whose tool_result makes the new
// card render pre-answered. Racing callers agree on the suffix because the
// count only moves on a close. Exported for tests.
export function nextSyntheticPromptUuid(baseUuid: string): string {
  const closedCount = closedSyntheticPrompts.get(baseUuid) ?? 0;
  return closedCount > 0 ? `${baseUuid}-r${closedCount}` : baseUuid;
}

// Exported for tests.
export async function closeSyntheticPrompt(
  sessionId: string,
  conversationId: string,
  syncService: SyncService,
  resolution: string,
): Promise<void> {
  const promptUuid = lastEmittedSyntheticPrompt.get(sessionId);
  if (!promptUuid || !promptUuid.startsWith("interactive-prompt-")) return;
  lastEmittedSyntheticPrompt.delete(sessionId);
  const base = promptUuid.replace(/-r\d+$/, "");
  closedSyntheticPrompts.set(base, (closedSyntheticPrompts.get(base) ?? 0) + 1);
  try {
    await syncService.addMessages({
      conversationId,
      messages: [{
        messageUuid: `${promptUuid}-closed`,
        role: "human" as const,
        content: "",
        timestamp: Date.now(),
        toolResults: [{ toolUseId: promptUuid, content: resolution }],
      }],
    });
    log(`Closed synthetic prompt for ${sessionId.slice(0, 8)}: ${resolution}`);
  } catch (err) {
    log(`Failed to close synthetic prompt for ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
  }
}

// A real AskUserQuestion writes its tool_use to the session JSONL the instant it's
// emitted and blocks there until answered (verified: a ~17-min gap between the
// tool_use line and its tool_result). The file watcher syncs that tool_use as a
// full-fidelity AskUserQuestion card — header, multiSelect, and option descriptions
// intact. So when the live tmux menu IS that AskUserQuestion, a scraped card would be
// a degraded duplicate (bare labels, synthetic "Type something"/"Chat about this"
// rows, no header). Detect the pending tool_use so the scrape can defer to the
// authoritative JSONL path. Returns true only when the latest AskUserQuestion in the
// tail has no matching tool_result yet (i.e. still blocking).
export function jsonlHasPendingAskUserQuestion(jsonlText: string): boolean {
  let lastAskId: string | null = null;
  const resultIds = new Set<string>();
  for (const line of jsonlText.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    let entry: any;
    try { entry = JSON.parse(trimmed); } catch { continue; }
    const content = entry?.message?.content;
    if (!Array.isArray(content)) continue;
    for (const block of content) {
      if (block?.type === "tool_use" && block?.name === "AskUserQuestion" && block?.id) {
        lastAskId = block.id;
      } else if (block?.type === "tool_result" && block?.tool_use_id) {
        resultIds.add(block.tool_use_id);
      }
    }
  }
  return lastAskId !== null && !resultIds.has(lastAskId);
}

export function sessionHasPendingAskUserQuestion(sessionId: string): boolean {
  const jsonlPath = findSessionJsonlPath(sessionId);
  if (!jsonlPath) return false;
  try { return jsonlHasPendingAskUserQuestion(readFileTail(jsonlPath, 65536)); } catch { return false; }
}

// When the spend limit interrupts a turn mid-flight, the CLI writes its own
// one-line limit banner (isApiErrorMessage) to the JSONL before parking on the
// interstitial — that entry syncs through the watcher and already stamps the
// park server-side. The daemon must then ONLY suppress the scraped card, not
// stack a synthetic banner under the real one. True when the newest
// content-bearing JSONL entry is a limit-kind banner: an older banner followed
// by real turns means the park it recorded is over and a fresh park deserves a
// fresh banner.
export function jsonlTailEndsWithLimitBanner(jsonlText: string): boolean {
  let lastIsLimitBanner = false;
  for (const line of jsonlText.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    let entry: any;
    try { entry = JSON.parse(trimmed); } catch { continue; }
    const content = entry?.message?.content;
    const text = typeof content === "string"
      ? content
      : Array.isArray(content) ? content.find((b: any) => b?.type === "text")?.text : null;
    const hasContent = (typeof text === "string" && text.trim().length > 0)
      || (Array.isArray(content) && content.some((b: any) => b?.type === "tool_use" || b?.type === "tool_result"));
    if (!hasContent) continue;
    lastIsLimitBanner = !!entry?.isApiErrorMessage && classifyApiErrorBanner(text) === "limit";
  }
  return lastIsLimitBanner;
}

async function checkForInteractivePrompt(
  tmuxTarget: string,
  sessionId: string,
  conversationId: string,
  syncService: SyncService,
  delayMs = 2000,
): Promise<void> {
  if (pendingInteractivePrompts.has(sessionId)) { log(`Skipping prompt check: pending prompt exists for ${sessionId.slice(0, 8)}`); return; }

  await new Promise(resolve => setTimeout(resolve, delayMs));

  // The pane verdict below may run the synchronous open task scan (a settle
  // goes through resolveTurnEndStatus). Prime it off the loop first, and
  // before the capture so the pane snapshot is fresh after the yield. After a
  // restart this is the read that would otherwise cover the whole transcript
  // on the loop, once per recovered session, inside the boot scan.
  const file = findSessionFile(sessionId, { staleOk: true });
  if (file?.agentType === "claude") await primeOpenTaskScan(file.path, sessionId);

  try {
    // -200 (vs the old -50): a long reasoning block above the menu must stay in the
    // capture so extractAssistantProseAbovePrompt can recover the full prose. The menu
    // sits at the bottom either way, so parseInteractivePrompt is unaffected.
    const { stdout: paneContent } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmuxTarget, "-S", "-200"]);
    const prompt = parseInteractivePrompt(paneContent);
    if (!prompt) {
      log(`No interactive prompt found in ${tmuxTarget} for session ${sessionId.slice(0, 8)}`, "debug");
      // Backstop: with no blocking prompt on screen, the live pane is the ground
      // truth for whether this agent is idle or working. Correct a latched status
      // (a lost lifecycle hook, or one wiped by a daemon restart) before returning.
      // This runs both periodically (heartbeatHealthCheck) and right after a warm
      // restart (the recovered-session scan), so a stale "working" can't persist.
      reconcileStatusFromPane(paneContent, sessionId, conversationId, syncService);
      return;
    }

    log(`Interactive prompt detected in session ${sessionId.slice(0, 8)}: "${prompt.question}" with ${prompt.options.length} options (confirmation=${!!prompt.isConfirmation})`);

    // The spend-limit interstitial is a limit park, not a question: emit the
    // canonical limit banner (see spendLimitDialogBanner) instead of a scraped
    // card whose "Continue" would confirm a billing action. The banner message
    // is what stamps pending_api_error_kind="limit" server-side, so the blocked
    // badge and the auto-switch check fire exactly as for a CLI-written banner.
    // Both costumes of the park: the unnumbered spend dialog (a confirmation)
    // and the numbered usage-limit menu. Neither is a question, so neither may
    // become a card — the menu variant reaches here as an ordinary prompt and
    // would otherwise be minted with billing actions as its options.
    {
      const limitBanner = prompt.isConfirmation
        ? spendLimitDialogBanner(paneContent)
        : usageLimitMenuBanner(paneContent, prompt.options.map((o) => o.label));
      if (limitBanner) {
        const now = Date.now();
        const digest = createHash("sha256").update(limitBanner).digest("hex").slice(0, 12);
        // Hour-bucketed uuid: the same park re-detected upserts one row, while a
        // fresh park later (after resumed turns superseded the first banner)
        // still re-emits instead of being swallowed by the re-emit guard.
        const bannerUuid = `limit-dialog-${sessionId}-${digest}-${Math.floor(now / 3_600_000)}`;
        if (lastEmittedSyntheticPrompt.get(sessionId) === bannerUuid) return;
        pendingInteractivePrompts.set(sessionId, { timestamp: now, options: prompt.options, isConfirmation: !!prompt.isConfirmation });
        // If the CLI already wrote its own limit banner for this park (it does
        // when the limit cuts a turn mid-flight), that banner syncs via the
        // watcher and is the park signal — suppressing the card is the whole
        // job. Emitting here too would stack a duplicate banner card.
        const jsonlPath = findSessionJsonlPath(sessionId);
        let cliBannerSynced = false;
        try { cliBannerSynced = !!jsonlPath && jsonlTailEndsWithLimitBanner(readFileTail(jsonlPath, 65536)); } catch {}
        if (cliBannerSynced) {
          lastEmittedSyntheticPrompt.set(sessionId, bannerUuid);
          log(`Limit dialog parked ${sessionId.slice(0, 8)} (${prompt.isConfirmation ? "spend" : "usage"}) — CLI banner already in JSONL, suppressed scraped card`);
          return;
        }
        await syncService.addMessages({
          conversationId,
          messages: [{ messageUuid: bannerUuid, role: "assistant" as const, content: limitBanner, timestamp: now }],
        });
        lastEmittedSyntheticPrompt.set(sessionId, bannerUuid);
        log(`Limit dialog parked ${sessionId.slice(0, 8)} (${prompt.isConfirmation ? "spend" : "usage"}) — emitted limit banner instead of a scraped card`);
        return;
      }
    }

    // If this live menu is a real AskUserQuestion tool call, its tool_use is already
    // in the JSONL and the file watcher syncs it as a full-fidelity card. Emitting a
    // scraped card here would be a degraded duplicate, so defer to that path — it also
    // sets the pending-prompt guard and the permission_blocked status.
    //
    // The tool_use write can lag the on-screen render by a beat, and the heartbeat
    // path calls us with delayMs=0, so a single point-in-time check can read the
    // JSONL *before* the flush lands and wrongly fall through to a scraped card
    // (this is how the "Disk headroom" poll shipped a garbled card). Poll briefly so
    // the deferral wins the flush race. A genuine non-JSONL menu (e.g. the `--model`
    // picker) never gains a pending tool_use, so it just costs this short settle.
    if (!prompt.isConfirmation) {
      for (let attempt = 0; attempt < 4; attempt++) {
        if (sessionHasPendingAskUserQuestion(sessionId)) {
          log(`Deferring to JSONL AskUserQuestion card for ${sessionId.slice(0, 8)} (skipping scraped duplicate)`);
          return;
        }
        if (attempt < 3) await new Promise(r => setTimeout(r, 500));
      }
    }

    const now = Date.now();
    pendingInteractivePrompts.set(sessionId, { timestamp: now, options: prompt.options, isConfirmation: prompt.isConfirmation });

    // Content-deterministic id: the same prompt detected by racing callers
    // upserts to one server row instead of N duplicate poll cards. A menu we
    // already CLOSED once (answered or dismissed, tool_result synced) must mint
    // a fresh uuid though — the upsert would revive the old row, whose existing
    // tool_result makes the new card render pre-answered. The close count keeps
    // racing callers agreeing on the same suffixed id.
    const promptUuid = nextSyntheticPromptUuid(interactivePromptMessageUuid(sessionId, prompt));

    // Don't re-emit (and re-surface) a synthetic prompt we already emitted for this
    // session — a re-rendered blocking menu after a heartbeat guard-clear is the same
    // prompt, not a new one. Distinct prompts have distinct uuids and still emit.
    if (lastEmittedSyntheticPrompt.get(sessionId) === promptUuid) {
      log(`Skipping re-emit of identical synthetic prompt for ${sessionId.slice(0, 8)}`);
      return;
    }

    // The assistant's reasoning that motivates this question is buffered out of the
    // JSONL until answered, so scrape it off the pane — without it the web user can't
    // judge the question. Empty for confirmations / bare slash menus (no preceding prose).
    const prose = prompt.isConfirmation ? "" : extractAssistantProseAbovePrompt(paneContent);

    // Prefer the hook's full tool_input (option descriptions + headers + multiSelect,
    // which the box-art-stripped scrape loses) when it's for THIS question; else fall
    // back to the scrape. Both self-correct to the real JSONL card once answered.
    const sidecar = prompt.isConfirmation ? null : readAskUserQuestionInput(sessionId);
    const questions = resolveInteractiveQuestions(prompt, sidecar);
    if (prose) log(`Recovered ${prose.length} chars of buffered prose for ${sessionId.slice(0, 8)}'s question`);

    await syncService.addMessages({
      conversationId,
      messages: [
        // Prose as its OWN message just before the card, so it renders ABOVE the question
        // (the order the terminal shows, and the order the real JSONL messages take once
        // flushed) instead of below it. The "…-prose" uuid still begins with
        // "interactive-prompt-", so the same client dedup that drops the scraped card on
        // answer sweeps this too — and if the session dies unanswered, the reasoning is
        // preserved rather than lost with the buffer.
        ...(prose ? [{
          messageUuid: `${promptUuid}-prose`,
          role: "assistant" as const,
          content: prose,
          timestamp: now - 1,
        }] : []),
        {
          messageUuid: promptUuid,
          role: "assistant" as const,
          content: "",
          timestamp: now,
          toolCalls: [{
            id: promptUuid,
            name: "AskUserQuestion",
            input: { questions },
          }],
        },
      ],
    });

    lastEmittedSyntheticPrompt.set(sessionId, promptUuid);
    log(`Synced interactive prompt as AskUserQuestion for session ${sessionId.slice(0, 8)}`);
  } catch (err) {
    log(`Interactive prompt check failed: ${err instanceof Error ? err.message : String(err)}`);
  }
}

function normalizePromptText(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

export function tmuxPromptStillHasInput(paneContent: string, input: string): boolean {
  const normalizedInput = normalizePromptText(input);
  if (!normalizedInput) return false;
  const lines = paneContent.split("\n");
  const recent = lines.slice(-80).join("\n");
  const lastPromptIndex = Math.max(recent.lastIndexOf("❯"), recent.lastIndexOf("›"));
  if (lastPromptIndex === -1) return false;
  const fromPrompt = recent.slice(lastPromptIndex);
  return normalizePromptText(fromPrompt).includes(normalizedInput);
}

// A multi-line bracketed paste can render in the composer as a collapsed chip
// with none of the pasted text visible — Claude Code shows
// "[Pasted text #1 +13 lines]", other agent TUIs use similar "[Pasted …]"
// tokens. When the content we just injected was multi-line, that chip at the
// prompt IS our message sitting in the input box: the submit-verify loop must
// treat it exactly like visible stuck input (press Enter), not as a
// stranger's draft to avoid stomping.
export function tmuxPromptShowsPastePlaceholder(paneContent: string): boolean {
  const recent = paneContent.split("\n").slice(-80).join("\n");
  const lastPromptIndex = Math.max(recent.lastIndexOf("❯"), recent.lastIndexOf("›"));
  if (lastPromptIndex === -1) return false;
  return /\[[^\]\n]*pasted[^\]\n]*\]/i.test(recent.slice(lastPromptIndex));
}

// The Claude Code TUI renders its live UI (input box, or modal that replaces it) at the
// very bottom of the pane, bracketed by box-drawing separator runs. Everything above
// those separators is transcript — immutable history rendered as text — and must not
// influence inject decisions. Extracting the live region first means scrollback can
// never produce a false positive (the original bug: stale "Interrupted · What should
// Claude do instead?" transcript matched forever).
export function extractTmuxLiveRegion(paneContent: string): string {
  const lines = paneContent.replace(/\s+$/, "").split("\n");
  const TAIL = 25;
  const tail = lines.slice(-TAIL);
  const isSep = (line: string) => /[─━]{20,}/.test(line);
  const sepIdx: number[] = [];
  for (let i = 0; i < tail.length; i++) {
    if (isSep(tail[i])) sepIdx.push(i);
  }
  if (sepIdx.length >= 2) {
    // Input box: take the box body AND everything below the box (the footer).
    // The footer is where Claude Code renders "esc to interrupt" while it is
    // generating — and the input box (❯) stays visible the whole time for
    // type-ahead. Slicing to `bot` (box body only) hid that marker, so a busy
    // agent showing its input box was misclassified "idle" and we pasted into
    // it; the queued text never submitted, never acked, and retried forever.
    // Nothing but the live footer renders below the box, so this can't pull in
    // scrollback (the reason the region is narrowed in the first place).
    const top = sepIdx[sepIdx.length - 2];
    return tail.slice(top + 1).join("\n");
  }
  if (sepIdx.length === 1) {
    // Modal or busy indicator: one separator, content lives below it.
    return tail.slice(sepIdx[0] + 1).join("\n");
  }
  // No separators visible — could be spinner-only or unusual UI. Use a tight tail
  // (5 lines) so transcript text from older turns can't reach the classifier.
  return tail.slice(-5).join("\n");
}

// Every tmux launch types `env -u CLAUDECODE … <agent> …` into a fresh shell,
// so pane content ABOVE that echoed command is shell-startup noise, not agent
// output. On a machine whose rc files print errors at startup (e.g. a bash
// completions file sourced by zsh emitting "command not found"), scanning the
// whole pane tripped the fatal-error check on the first readiness poll and
// killed every auto-resume in a loop — the tmux existed for <1s at a time, so
// the web "attach" command never found it. Returns only content BELOW the echo
// line (the echo itself is excluded: it contains the agent binary name and, on
// fancy shell themes, a ❯ prompt glyph — both false-positive readiness
// signals). When no echo is visible the agent TUI has scrolled it away — along
// with the noise above it — so the full capture is safe to scan.
export function paneContentAfterLaunchEcho(paneContent: string): string {
  const idx = paneContent.indexOf("env -u CLAUDECODE");
  if (idx < 0) return paneContent;
  const nl = paneContent.indexOf("\n", idx);
  return nl >= 0 ? paneContent.slice(nl + 1) : "";
}

export type TmuxLiveState =
  | "idle"          // empty input prompt — safe to paste
  | "busy"          // spinner / "esc to interrupt" — wait
  | "interrupted"   // "What should Claude do instead?" dialog — Escape to clear
  | "rewind"        // Rewind/Restore modal — Escape to cancel (NEVER Enter, that rewinds)
  | "trust"         // workspace "Quick safety check" prompt — Enter accepts ("Yes, I trust" is preselected)
  | "warning"       // dismissable banner — Enter to ack
  | "exited"        // bare shell, agent has exited — abort
  | "unknown";      // anything we don't recognize — defer, do not guess

// Classifies the live region only. Ordering matters: more-specific dialogs are
// matched before more-general ones (e.g. Rewind contains "Interrupted" in its option
// list, so check Rewind first). Idle is a positive whitelist — never inferred from
// absence of other patterns.
export function classifyTmuxLiveState(region: string): TmuxLiveState {
  if (/Resume this session with:/i.test(region)) return "exited";
  if (/-(?:ba)?sh:.*(?:No such file|command not found)/.test(region)) return "exited";
  if (/⠋|⠙|⠹|⠸|⠼|⠴|⠦|⠧|⠇|⠏|esc to interrupt/i.test(region)) return "busy";
  // Rewind / cancel-able modal: distinguished from warnings by an Esc option.
  // Warnings have only "Press enter to continue" (no Esc). The "❯ (current)" marker
  // is also unique to the Rewind option list.
  // Workspace trust prompt (first launch in a directory). Its footer is
  // "Enter to confirm · Esc to cancel", so it must be recognized BEFORE the
  // Rewind rule below — misread as Rewind, the Escape we send is this dialog's
  // "No, exit": the agent quits, the resume loops, and the message never lands
  // (17 panes found dead on this on 2026-08-21).
  if (/Quick safety check|trust this folder|Is this a project you created/i.test(region)) return "trust";
  if (/Esc to cancel|❯\s*\(current\)/i.test(region)) return "rewind";
  if (/What should Claude do instead\?/i.test(region)) return "interrupted";
  // Teammate panel: a lead session with in-process agents renders a chip list
  // (⏺ main, ◯ name · state, "↓ N more") below its footer. Teammate panes split
  // the window, and a squeezed lead pane truncates the footer's "esc to
  // interrupt" marker — or, squeezed further, leaves the chip list as the ONLY
  // content the scraper sees (the jx77h6jcsa0s freeze). Either way the pane is a
  // live Claude Code TUI whose input box takes type-ahead, so classify busy:
  // the paste path skips the leading Escape (never interrupts a mid-turn lead)
  // and paste+Enter still submits when the lead is actually idle. Checked
  // before the prompt-visible idle rule because chips + visible ❯ says nothing
  // about whether the lead is generating. Requires a panel signature (⏺ main
  // header, a second chip, or the overflow marker) so one stray ◯ line in a
  // no-separator fallback region can't hijack the classification.
  const chipLines = region.split("\n").filter((l) => /^\s*◯\s+\S+/.test(l)).length;
  if (chipLines >= 2 || (chipLines >= 1 && /(?:^\s*⏺\s+main\s*$|↓\s*\d+\s*more)/m.test(region))) {
    return "busy";
  }
  // Input prompt visible = no blocking modal. Real warnings ("Press enter to
  // continue", weekly-limit popup) replace the input box, so the prompt glyph
  // disappears while they're up. Persistent footer banners — "Update available!
  // Run: brew upgrade claude-code" sits below the input box on every turn —
  // match the warning regex but DON'T block input; checking idle first prevents
  // an Enter-press-loop that mis-classifies as AGENT_STUCK_WARNING for any
  // Claude Code session with an update pending. Mirrors injectViaTmuxInner's
  // own guard, which only acks warnings when no prompt is visible.
  const promptVisible = region.includes("❯") || region.includes("›");
  if (promptVisible) return "idle";
  if (/Press enter to continue|Update available|weekly limit|recorded with model|⚠/i.test(region)) return "warning";
  return "unknown";
}

// Clients whose tmux readiness is classified WHOLE-PANE from their registry
// promptReadyPattern, with busy-detection checked first — not the claude-chrome
// ❯/›-glyph whitelist in classifyTmuxLiveState. Two ways in:
//  - No glyph at all: opencode (footer `ctrl+p commands`, placeholder `Ask
//    anything…`) and pi (status-bar context-budget segment, e.g. `0.0%/200k`).
//    Without this the injection pre-flight read their idle prompt as "unknown"
//    and refused to paste — a fresh opencode/pi launch's FIRST message never
//    delivered (ct-39174): tryStartedTmux reached the pane and logged "ready
//    (prompt visible)", then ensureTmuxReady threw AGENT_UNKNOWN_STATE and
//    delivery fell through to materialize/fresh-start, which both fail for a
//    store-owned client that has no session row until it has processed a turn.
//  - Glyph that LIES while busy: grok keeps its ❯ composer visible for the whole
//    turn (live pane capture, v1.0.5), so the glyph-whitelist path would read a
//    mid-turn pane "idle" and the paste's leading Escape would cancel the running
//    turn. grok needs the busy-first order this classifier guarantees.
const GLYPHLESS_PROMPT_CLIENTS: ReadonlySet<AgentClientId> = new Set(["opencode", "pi", "grok"]);

// The registry promptReadyPattern for a client classified whole-pane (see
// GLYPHLESS_PROMPT_CLIENTS above), null for the ❯/›-glyph clients. Every pane
// classification site that knows its client routes through this instead of
// re-testing set membership, so no site can fall back to the claude-chrome
// whitelist for a client it cannot read.
export function glyphlessPromptPattern(agentType: AgentClientId | undefined): RegExp | null {
  return agentType && GLYPHLESS_PROMPT_CLIENTS.has(agentType)
    ? AGENT_CLIENTS[agentType].promptReadyPattern
    : null;
}

// Injection-readiness for a glyph-less client, tested against the WHOLE pane (not
// extractTmuxLiveRegion's tight live-region tail — opencode has no ─/━ separator,
// so that tail drops to the status bar and misses the footer marker). These
// clients have no pane-driven modals (panePromptMonitoring:false; the store
// watcher is the authoritative turn-state source), so readiness is the narrow
// question "is the TUI up and accepting input": a visible readyPattern with no
// active spinner means ready-to-paste. `busy` is best-effort — the store, not the
// pane, owns turn state — but a visible spinner still says to skip the
// interrupting Escape and paste into the type-ahead box instead.
export function classifyGlyphlessClientPaneState(
  paneContent: string,
  readyPattern: RegExp,
): TmuxLiveState {
  if (/-(?:ba)?sh:.*(?:No such file|command not found)/.test(paneContent)) return "exited";
  // Busy before ready, always. Braille spinner frames + "esc to interrupt" cover
  // opencode/pi; `Esc:cancel` / `Waiting for response` / `[stop]` are grok's busy
  // chrome (live pane capture, v1.0.5 — the spinner sits in grok's HEADER, which a
  // short capture window can crop, so the footer/status text must count too).
  // CAUTION: keep these markers literal — grok's IDLE states contain the words
  // "send a message to interrupt", so a generic /interrupt/ heuristic would read
  // an idle grok pane as busy forever.
  if (/⠋|⠙|⠹|⠸|⠼|⠴|⠦|⠧|⠇|⠏|esc to interrupt|Esc:cancel|Waiting for response|\[stop\]/i.test(paneContent)) return "busy";
  if (readyPattern.test(paneContent)) return "idle";
  return "unknown";
}

// Whole-pane live-state for a KNOWN client — the reaper's idle gates go through
// this. GLYPHLESS_PROMPT_CLIENTS classify with busy-first ordering against
// their registry pattern: classifyTmuxLiveState would read grok's persistent ❯
// composer as "idle" mid-turn (a busy grok must never look reapable), and read
// pi/opencode as a permanent "unknown" (their idle terminals were never
// reaped). Other clients keep the claude-chrome whitelist unchanged.
export function classifyLivePaneFor(agentType: AgentClientId, paneContent: string): TmuxLiveState {
  const glyphless = glyphlessPromptPattern(agentType);
  return glyphless
    ? classifyGlyphlessClientPaneState(paneContent, glyphless)
    : classifyTmuxLiveState(paneContent);
}

// Pane-state status reconcile — the tmux-session counterpart to
// reconcileStatusFromTranscript. For a tmux-managed session the live pane is the
// authoritative "is the agent busy right now" signal: the transcript can't tell
// that a finished agent is idle when its last turn was cut off mid-tool (the JSONL
// ends without an `end_turn` and reads "active" forever), and a daemon restart
// wipes lastSentAgentStatus so the heartbeat re-asserts the server's stale active
// status indefinitely. The pure decision below corrects only on a positive pane
// signal, mirroring reconciledStatus:
//   - idle pane + stale-active (or post-restart unknown) status -> idle
//   - busy pane + quiet (or post-restart unknown) status        -> working
// Modal/exited/unknown panes defer. classifyTmuxLiveState checks busy/modal
// patterns before "idle" (a busy agent's type-ahead input box reads "busy", not
// "idle"), so a false idle can't slip through.
//
// permission_blocked is treated as recoverable here too — but ONLY because the
// sole caller (reconcileStatusFromPane via checkForInteractivePrompt) runs this
// AFTER parseInteractivePrompt confirmed there is NO interactive menu on the pane.
// So an idle/busy pane with a permission_blocked latch means the AskUserQuestion
// was dismissed/answered and the resume hook was lost. This is the tmux fix for
// "session parked on a buffered AskUserQuestion shows working/needs-input forever":
// Claude Code buffers the question's tool_use out of the JSONL until answered, so
// the transcript can't see it and reconcileStatusFromTranscript must defer to this
// pane signal for tmux sessions. While the menu IS up, classifyTmuxLiveState reads
// it as rewind/unknown (and the caller defers anyway), so the block can't be
// cleared out from under a still-waiting agent.
export function paneReconcileTarget(
  state: TmuxLiveState,
  stored: AgentStatus | undefined,
): AgentStatus | null {
  if (state === "idle") {
    const staleActive = stored === "working" || stored === "thinking" || stored === "connected" || stored === "permission_blocked";
    // A parked "waiting" is re-derived too: the caller runs the settle verdict
    // again, which re-checks the open tasks against live processes — a task
    // that died without a notice drains the session back to idle here instead
    // of sitting parked until the quiet-time decay. A stored "idle" re-derives
    // for the same reason in the OTHER direction: a false task-death verdict
    // (e.g. a stale cached agent pid condemning live watchers) collapses
    // waiting → idle, and without this leg nothing ever climbs back — the
    // session sits in needs-input while a live watcher stands. The re-derive
    // is O(transcript delta) and publishes only when the verdict changes.
    return stored === undefined || staleActive || stored === "waiting" || stored === "idle" ? "idle" : null;
  }
  if (state === "busy") {
    // The settle verdicts count as quiet too: a busy pane over a parked
    // ("waiting" / "dormant" / "done") session is the wake whose activity hook
    // was lost — promote it, or the row stays filed as parked while it works.
    const quiet = stored === undefined || stored === "idle" || stored === "connected" || stored === "permission_blocked"
      || stored === "waiting" || stored === "dormant" || stored === "done";
    return quiet ? "working" : null;
  }
  return null;
}

function reconcileStatusFromPane(
  paneContent: string,
  sessionId: string,
  conversationId: string,
  syncService: SyncService,
): void {
  // The claude-chrome classifier below cannot read GLYPHLESS_PROMPT_CLIENTS
  // panes — worse than "unknown" for grok, whose ❯ composer stays visible for
  // the whole turn while its busy chrome (header spinner, "Esc:cancel",
  // "[stop]") sits OUTSIDE the live region: a mid-turn grok pane classifies
  // "idle" here and this backstop would settle a working session every health
  // check, flapping against the sync path's "working". These clients' turn
  // state is transcript-driven instead (processTranscriptDeltaSession /
  // processOpencodeSession classify the tail on every sync), so skipping the
  // pane is a no-op, not a gap. pi/opencode already no-op'd here ("unknown");
  // this makes the exclusion explicit and safe for glyphed liars.
  if (GLYPHLESS_PROMPT_CLIENTS.has(detectSessionAgentType(sessionId))) return;
  const state = classifyTmuxLiveState(extractTmuxLiveRegion(paneContent));
  const stored = lastSentAgentStatus.get(sessionId);
  let target = paneReconcileTarget(state, stored);
  if (!target) return;
  // A pane-confirmed settle goes through the same verdict as a Stop hook, so a
  // turn whose hook was lost still lands on its declared / inferred status.
  if (target === "idle") target = resolveTurnEndStatus(sessionId);
  if (target === stored) {
    // Unchanged status: send only to publish a report that moved, or the
    // periodic re-publish that keeps a "waiting" vouched for; otherwise
    // nothing.
    if (pendingOpenTasksChanged(sessionId) || (stored === "waiting" && openTasksRefreshDue(sessionId, Date.now()))) {
      sendAgentStatus(syncService, conversationId, sessionId, target);
    } else {
      pendingOpenTaskReports.delete(sessionId);
    }
    return;
  }
  log(`[STATUS-PANE-RECONCILE] ${sessionId.slice(0, 8)} stored=${stored ?? "none"} pane=${state} -> ${target}`);
  sendAgentStatus(syncService, conversationId, sessionId, target);
}

// Recognizes the synthetic control message Claude Code appends when the user
// interrupts a turn (ESC / Ctrl-C): "[Request interrupted ...]" or
// "[Request cancelled ...]". It is NOT a fresh prompt — the agent was stopped
// and is now parked at the prompt waiting on the user. Mirrors the web's
// isInterruptControlMessage and the server's isInterruptMsg so all three layers
// agree that an interrupt is not "the agent's move."
export function isInterruptControlMessage(text: string | null | undefined): boolean {
  const t = text?.trim();
  if (!t) return false;
  return t.startsWith("[Request interrupted") || t.startsWith("[Request cancelled");
}

// Leading surface text of a JSONL message's `content`, which is either a raw
// string or an array of content blocks (text / tool_use / tool_result …).
// Returns the first text block's text (or the string itself); "" when there is
// no surface text. Enough to recognize the interrupt control message above.
function jsonlMessageText(content: unknown): string {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    for (const block of content) {
      if (block && typeof block === "object" && (block as { type?: string }).type === "text") {
        return String((block as { text?: unknown }).text ?? "");
      }
    }
  }
  return "";
}

// Turn-completion state derived from a Claude JSONL transcript tail. This is the
// universal ground truth for "is the agent mid-turn or done" -- every session
// writes a transcript, unlike a tmux pane (a bare-terminal session has none).
export type TranscriptTurnState =
  | "idle"     // last real message is an assistant turn that ended (end_turn etc.)
  | "active"   // mid-turn: a pending tool_use, or a user/tool_result awaiting reply
  | "unknown"; // streaming/partial/no parseable real message -> defer, never guess

// Classifies the most recent *real* message in a JSONL tail. `system`/meta lines
// (and any partially-written final line that won't parse) are skipped so we land
// on the last genuine user/assistant turn. The signal is structural:
//   - assistant + stop_reason end_turn/stop_sequence/max_tokens -> turn ended (idle)
//   - assistant + stop_reason tool_use                          -> mid-turn (active)
//   - user (fresh prompt or tool_result)                        -> agent's move (active)
//   - assistant with no/streaming stop_reason, or nothing real  -> unknown (defer)
// AskUserQuestion-blocked sessions read as `active` (their last assistant turn is a
// pending tool_use), so they are never mistaken for idle; the open-poll/needs-input
// path owns that case.
export function classifyTranscriptTail(tailContent: string): TranscriptTurnState {
  const lines = tailContent.split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line) continue;
    let d: { type?: string; message?: { role?: string; stop_reason?: string | null; content?: unknown } };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // partial/corrupt line (e.g. mid-write tail) -> skip
    }
    const role = d.message?.role ?? (d.type === "user" || d.type === "assistant" ? d.type : undefined);
    if (role === "assistant") {
      const sr = d.message?.stop_reason;
      if (sr === "tool_use") return "active";
      if (sr === "end_turn" || sr === "stop_sequence" || sr === "max_tokens") return "idle";
      return "unknown"; // streaming / unrecognized stop_reason -> defer
    }
    if (role === "user") {
      // A [Request interrupted]/[Request cancelled] control message is not a fresh
      // prompt: the user stopped the agent mid-turn and it is now parked at the
      // prompt. Reading it as "active" (the agent's move) is exactly what kept
      // bare-terminal interrupted sessions latched in "working" — the reconcile
      // heartbeat re-derived "active" every cycle, so reconciledStatus flipped a
      // freshly-idle session back to working forever, and the server never saw an
      // idle status to route into needs-input. An interrupt is turn-ended (idle),
      // mirroring Codex's task_aborted. (tmux sessions self-heal via the pane
      // reconcile; bare-terminal ones have only this transcript signal.)
      if (isInterruptControlMessage(jsonlMessageText(d.message?.content))) return "idle";
      return "active";
    }
    // system/meta entry -> keep scanning for the last real message
  }
  return "unknown";
}

// Open background work in a Claude JSONL transcript: tasks the harness started
// (run_in_background Bash, a command moved to the background on timeout, a
// Monitor, a Workflow run) that have not yet reached a terminal state. While any is open, the
// harness re-invokes the agent when it finishes — so a turn that ended with an
// open task is "waiting" (an active substate), not idle/needs-input.
//
// Opens come from tool_result text (the id is only ever surfaced there);
// closes come from:
//   - a <task-notification> carrying a <status> tag. Terminal notifications
//     (completed/failed/stopped) always carry one; Monitor interim event
//     notifications carry none and must NOT close the task. Delivery shapes
//     vary: a plain user message, a queue-operation "remove" (top-level
//     content), or an attachment (prompt) — an enqueue alone is not delivery.
//   - a TaskStop tool_use (the agent tore the task down; no notification comes).
// Lines are scoped to `currentSessionId` when given: a resumed session's file
// replays prior-run history verbatim (original sessionId preserved per line),
// and those runs' tasks died with their process — counting them would latch a
// phantom "waiting".
export function scanOpenBackgroundTasks(content: string, currentSessionId?: string): Set<string> {
  return scanOpenBackgroundTasksInto(new Set<string>(), content, currentSessionId);
}

// When each open task was armed (ms), keyed by task id — the restart fence's
// input. A background task is a child of the agent process that started it;
// when that process is replaced (crash, kill, account switch, `claude
// --resume`) the task dies with it and no terminal notification is ever
// written, so its start line would keep the session "waiting" forever (the
// 1h decay merely rate-limits the lie). Same rule the web's monitor rows apply
// (monitorRows.effectiveMonitorStatus over agent_started_at).
export type OpenTaskTimes = Map<string, number>;

// The scanner core, threading an existing `open` set so a caller that already
// scanned the first N bytes can feed it only the bytes after N. Open/close are
// order-dependent but purely sequential (a task opens on its start line and
// closes on a later notification/TaskStop line), so scanning the file in two
// halves against the same set gives the same answer as scanning it whole.
// The harness's own "this is now a background task" results, anchored to the
// START of the tool_result: the harness always leads with them, and an
// unanchored scan also fired on a foreground command whose OUTPUT quoted one (an
// agent grepping a transcript for these phrases parked its own session in
// "waiting" on a task id nothing would ever close). Same rule as the web's
// monitorRows scanner.
const OPEN_TASK_START_RE = /^\s*(?:Command running in background with ID: ([A-Za-z0-9_-]+)|Command did not complete within its \d+s timeout and was moved to the background \(ID: ([A-Za-z0-9_-]+)\)|Monitor started \(task ([A-Za-z0-9_-]+)|Workflow launched in background\. Task ID: ([A-Za-z0-9_-]+))/;
export function openTaskStart(text: string): { id: string; kind: OpenTaskKind } | undefined {
  const m = text.match(OPEN_TASK_START_RE);
  if (!m) return undefined;
  if (m[1]) return { id: m[1], kind: "background" };
  if (m[2]) return { id: m[2], kind: "promoted" };
  if (m[3]) return { id: m[3], kind: "monitor" };
  return { id: m[4], kind: "workflow" };
}
export function openTaskStartId(text: string): string | undefined {
  return openTaskStart(text)?.id;
}

// What the scanner knows about one open task: the shared report shape (what
// gets published) plus the tool call that armed it. `command` is the FULL
// script here — the process check needs it — and is cut to its first line
// only when reported.
export type OpenTaskInfo = OpenTaskReport & { openedAt?: number };

// The tool_use blocks that can arm a task, remembered until their result lands
// (a result always follows its call closely) so the start result can be joined
// to the description/command the agent gave. Bounded: a call whose result was
// lost (an interrupted turn) must not leak forever.
type PendingTaskCall = { name: string; description?: string; command?: string };
const PENDING_TASK_CALLS_MAX = 200;
const TASK_ARMING_TOOLS = new Set(["Bash", "Monitor", "Workflow"]);

function scanOpenBackgroundTasksInto(
  open: Set<string>,
  content: string,
  currentSessionId?: string,
  openedAt?: OpenTaskTimes,
  info?: Map<string, OpenTaskInfo>,
  pendingCalls?: Map<string, PendingTaskCall>,
): Set<string> {
  for (const rawLine of content.split("\n")) {
    const line = rawLine.trim();
    if (!line) continue;
    let d: {
      type?: string;
      sessionId?: string;
      timestamp?: string;
      operation?: string;
      content?: unknown;
      attachment?: { prompt?: unknown };
      message?: { role?: string; content?: unknown };
    };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // partial/corrupt line (mid-write tail) -> skip
    }
    if (currentSessionId && d.sessionId && d.sessionId !== currentSessionId) continue;
    const lineAt = d.timestamp ? Date.parse(d.timestamp) : NaN;
    // A notification that arrives while the agent is mid-turn is recorded as a
    // queue-operation (top-level content) and an attachment (prompt), never as
    // a plain user message — close on the delivered forms. "remove" = dequeued
    // for delivery; an enqueue alone is left open (the wake hasn't happened
    // yet, so the session is still the harness's move).
    if (d.type === "queue-operation") {
      if (d.operation === "remove" && typeof d.content === "string") closeNotifiedTasks(d.content, open);
      continue;
    }
    if (d.type === "attachment") {
      const prompt = d.attachment?.prompt;
      if (typeof prompt === "string") closeNotifiedTasks(prompt, open);
      continue;
    }
    if (d.type !== "user" && d.type !== "assistant") continue;
    const blocks = d.message?.content;
    const surface = typeof blocks === "string" ? blocks : "";
    if (!Array.isArray(blocks)) {
      closeNotifiedTasks(surface, open);
      continue;
    }
    for (const b of blocks) {
      if (!b || typeof b !== "object") continue;
      const block = b as { type?: string; id?: string; name?: string; input?: unknown; content?: unknown; text?: string; tool_use_id?: string };
      if (block.type === "text" && block.text) {
        closeNotifiedTasks(block.text, open);
      } else if (block.type === "tool_result") {
        const text = typeof block.content === "string"
          ? block.content
          : Array.isArray(block.content)
            ? block.content.map((c) => (c && typeof c === "object" ? String((c as { text?: unknown }).text ?? "") : "")).join(" ")
            : "";
        const started = openTaskStart(text);
        const call = block.tool_use_id && pendingCalls ? pendingCalls.get(block.tool_use_id) : undefined;
        if (block.tool_use_id) pendingCalls?.delete(block.tool_use_id);
        if (started) {
          open.add(started.id);
          if (openedAt && Number.isFinite(lineAt)) openedAt.set(started.id, lineAt);
          info?.set(started.id, {
            id: started.id,
            kind: started.kind,
            ...(call?.description ? { description: call.description } : {}),
            ...(call?.command ? { command: call.command } : {}),
            ...(Number.isFinite(lineAt) ? { started_at: lineAt, openedAt: lineAt } : {}),
            ...(block.tool_use_id ? { tool_use_id: block.tool_use_id } : {}),
          });
        }
      } else if (block.type === "tool_use" && block.name === "TaskStop") {
        const taskId = (block.input as { task_id?: unknown } | undefined)?.task_id;
        if (typeof taskId === "string") open.delete(taskId);
      } else if (block.type === "tool_use" && block.id && block.name && TASK_ARMING_TOOLS.has(block.name) && pendingCalls) {
        const input = (block.input ?? {}) as { description?: unknown; command?: unknown };
        pendingCalls.set(block.id, {
          name: block.name,
          ...(typeof input.description === "string" ? { description: input.description } : {}),
          ...(typeof input.command === "string" ? { command: input.command } : {}),
        });
        if (pendingCalls.size > PENDING_TASK_CALLS_MAX) {
          const oldest = pendingCalls.keys().next().value;
          if (oldest !== undefined) pendingCalls.delete(oldest);
        }
      }
    }
  }
  return open;
}

// One notification can carry SEVERAL <task-id> tags (the harness batches an
// orphan sweep into a single <status>stopped</status> notification) — close
// every id it names, but only when a <status> tag marks it terminal (Monitor
// interim events carry no status and must not close their task).
function closeNotifiedTasks(text: string, open: Set<string>): void {
  if (!text.includes("<task-notification>")) return;
  if (!/<status>[^<]+<\/status>/.test(text)) return;
  for (const m of text.matchAll(/<task-id>([^<]+)<\/task-id>/g)) open.delete(m[1]);
}

// Incremental wrapper for scanOpenBackgroundTasks. Turn-end and reconcile both
// consult it, and reconcile runs on every heartbeat. The old version cached by
// file size and re-read the WHOLE transcript on any size change — but the very
// sessions this is called for ("waiting" on background work) are the ones whose
// transcript grows on every tick, so the cache never hit and each heartbeat
// re-materialized a multi-MB file as a JS string (+ its split() array). Measured
// 2026-08-15: one 31MB transcript = +140MB RSS per scan; several live sessions
// pushed daemon phys_footprint to a 934MB peak. JSONL is append-only, so keep the
// scanner's `open` set plus the byte offset consumed and scan only the new
// bytes — same verdict, O(delta) memory. The offset only advances past complete
// lines, so a half-written tail is re-read (not skipped) on the next call. A
// shrink (rotation/rewrite) resets to a full scan.
export const SCAN_CHUNK_BYTES = 4 * 1024 * 1024;
type OpenTaskScanState = {
  offset: number;
  open: Set<string>;
  openedAt: OpenTaskTimes;
  info: Map<string, OpenTaskInfo>;
  pendingCalls: Map<string, PendingTaskCall>;
  sessionId?: string;
};
const openTaskScanCache = new Map<string, OpenTaskScanState>();
/** How far the open task scan has read a transcript (tests and diagnostics). */
export function openTaskScanOffset(transcriptPath: string): number | undefined {
  return openTaskScanCache.get(transcriptPath)?.offset;
}
/** Would a synchronous open task scan of this transcript read more than one
 *  window right now? True for a never scanned transcript. A missing file is
 *  not cold: the sync scan makes its empty claim at once. */
export function openTaskScanIsCold(transcriptPath: string): boolean {
  let size: number;
  try {
    size = fs.statSync(transcriptPath).size;
  } catch {
    return false;
  }
  const offset = openTaskScanOffset(transcriptPath);
  return offset === undefined || size - offset > SCAN_CHUNK_BYTES;
}
// `notBefore` is the restart fence: a task armed before it belongs to a
// replaced agent process and is dead however open the transcript says it is
// (see OpenTaskTimes). Callers pass the agent's process start when known.
export function openBackgroundTaskIds(transcriptPath: string, sessionId?: string, notBefore?: number): string[] {
  return openBackgroundTasks(transcriptPath, sessionId, notBefore).map((t) => t.id);
}

// The open tasks with what the scanner knows about each (see OpenTaskInfo) —
// the transcript's claim, fenced by process generation but NOT yet checked
// against live processes (verifiedOpenTasks does that).
// The scan state for a transcript, reset when the file shrank or the session
// changed. Shared by the sync scan and the async prime so both advance the
// same offset.
function openTaskScanState(transcriptPath: string, size: number, sessionId?: string): OpenTaskScanState {
  let state = openTaskScanCache.get(transcriptPath);
  if (state && (state.offset > size || state.sessionId !== sessionId)) state = undefined;
  if (!state) state = { offset: 0, open: new Set<string>(), openedAt: new Map<string, number>(), info: new Map(), pendingCalls: new Map(), sessionId };
  return state;
}

function consumeOpenTaskChunk(state: OpenTaskScanState, content: string, bytesConsumed: number): void {
  scanOpenBackgroundTasksInto(state.open, content, state.sessionId, state.openedAt, state.info, state.pendingCalls);
  state.offset += bytesConsumed;
}

/**
 * Scan a transcript's unscanned bytes for open tasks off the loop, one
 * SCAN_CHUNK_BYTES window per step with a yield between. The heartbeat
 * maintenance path awaits this before the synchronous scan, so the sync scan
 * (which hook paths must keep, they cannot await) only ever covers the delta
 * since the last prime instead of a whole transcript after a restart.
 */
// At most this many transcripts prime at once: each chunk in flight is one
// SCAN_CHUNK_BYTES buffer plus its decoded string, and the warm restart scan
// asks for every recovered session in one tick.
const openTaskPrimeSlots = countingSemaphore(4);
export async function primeOpenTaskScan(transcriptPath: string, sessionId?: string, opts?: { front?: boolean }): Promise<void> {
  try {
    const size = (await fs.promises.stat(transcriptPath)).size;
    const state = openTaskScanState(transcriptPath, size, sessionId);
    // Cached before the first read, so a synchronous scan that lands while a
    // read is in flight shares this state instead of building its own.
    openTaskScanCache.set(transcriptPath, state);
    // The slot is only for the read. A primed transcript (one stat of work)
    // must not queue behind the fleet's whole transcript reads: after a
    // restart every recovered session is queued at once, and the prompt
    // checks and question card path await a prime before they capture.
    if (state.offset >= size) return;
    await openTaskPrimeSlots.run(() => primeOpenTaskScanNow(transcriptPath, state, size), opts);
  } catch {
    // unreadable transcript: the sync scan makes the same (empty) claim
  }
}
async function primeOpenTaskScanNow(transcriptPath: string, state: OpenTaskScanState, size: number): Promise<void> {
  try {
    while (state.offset < size) {
      const at = state.offset;
      const { content, bytesConsumed } = await readIngestWindow(transcriptPath, at, size - at, { step: SCAN_CHUNK_BYTES });
      // A hook path scanned synchronously during the read: it replaced the
      // state or moved the offset past this chunk, so the chunk is already
      // covered. Applying it again replayed its lines after later ones (a
      // task closed later came back open) and left the offset past EOF,
      // which the next sync scan read as a shrink and rescanned in full.
      if (openTaskScanCache.get(transcriptPath) !== state) return;
      if (state.offset !== at) continue;
      if (!bytesConsumed) break; // torn trailing line at EOF
      consumeOpenTaskChunk(state, content, bytesConsumed);
      await new Promise((resolve) => setImmediate(resolve));
    }
  } catch {
    // unreadable transcript: the sync scan makes the same (empty) claim
  }
}

export function openBackgroundTasks(transcriptPath: string, sessionId?: string, notBefore?: number): OpenTaskInfo[] {
  try {
    const size = fs.statSync(transcriptPath).size;
    const state = openTaskScanState(transcriptPath, size, sessionId);
    if (size > state.offset) {
      // Chunked, not one read of (size - offset): the FIRST scan of a session
      // covers the whole transcript, and at boot the daemon first-scans every
      // waiting session back to back — one-shot reads made that a ~500MB burst.
      // A window caps per-scan memory at SCAN_CHUNK_BYTES regardless of file
      // size, and a line longer than the window grows it one window at a time
      // (readCompleteLinesSync), never to the whole remaining file. Each pass
      // consumes only complete lines; the partial tail is re-read next call.
      timeSyncFs("openBackgroundTasks", transcriptPath, () => {
        const fd = fs.openSync(transcriptPath, "r");
        // One buffer for every window of this scan, not one per window.
        const buffer = Buffer.allocUnsafe(Math.min(SCAN_CHUNK_BYTES, size - state.offset));
        try {
          while (state.offset < size) {
            const { content, bytesConsumed } = readCompleteLinesSync(fd, state.offset, size - state.offset, { step: SCAN_CHUNK_BYTES, buffer });
            if (!bytesConsumed) break; // torn trailing line at EOF -> defer to next call
            consumeOpenTaskChunk(state, content, bytesConsumed);
          }
        } finally {
          fs.closeSync(fd);
        }
      });
      openTaskScanCache.set(transcriptPath, state);
    }
    const infoFor = (id: string): OpenTaskInfo => state!.info.get(id) ?? { id, kind: "background" };
    if (notBefore === undefined) return [...state.open].map(infoFor);
    // 60s of slack: the process start comes from ps etime (1s resolution) and
    // the transcript stamps come from the agent's own clock.
    const fence = notBefore - 60_000;
    return [...state.open].filter((id) => {
      const at = state!.openedAt.get(id);
      return at === undefined || at >= fence;
    }).map(infoFor);
  } catch {
    return []; // unreadable transcript -> no claim of open work
  }
}

// ---- Process check for open tasks ----------------------------------------
// The harness runs every shell-backed task (a background Bash, a command it
// moved to the background on timeout, a Monitor's script) as a direct child of
// the agent process, wrapped as
//   /bin/bash -c source <snapshot> … && eval '<command>' < /dev/null && pwd -P >| …
// so a task is alive exactly while such a child exists. The transcript alone
// cannot tell: the harness loses a completion notice now and then (a promoted
// command whose notice never got written parked its session "waiting" on
// every settle for hours, 2026-08-17), and a task that dies with its process
// gets no notice either. Checking the process table turns "waiting" from a
// scrape into a claim we verified.
//
// The snapshot is refreshed in the background (one `ps` for the whole machine,
// at most every PROCESS_SNAPSHOT_TTL_MS) and read synchronously by the settle
// paths, which are sync; a consumer that finds no snapshot yet trusts the
// transcript. Failure modes are biased toward "alive": no snapshot, no known
// agent pid, a workflow task (no shell), a command we cannot turn into a
// needle, a task younger than the snapshot — all count as open. Only a task
// that is older than a successful snapshot and has no matching child of a
// known agent pid is called dead.
export type ProcessSnapshot = { at: number; procs: Array<{ pid: number; ppid: number; command: string }> };
const PROCESS_SNAPSHOT_TTL_MS = 15_000;
let processSnapshot: ProcessSnapshot | undefined;
let processSnapshotInFlight = false;
function ensureProcessSnapshotFresh(): void {
  if (processSnapshotInFlight) return;
  if (processSnapshot && Date.now() - processSnapshot.at < PROCESS_SNAPSHOT_TTL_MS) return;
  processSnapshotInFlight = true;
  const startedAt = Date.now();
  execFile("ps", ["-axww", "-o", "pid=,ppid=,command="], { maxBuffer: 64 * 1024 * 1024, timeout: 10_000 }, (err, stdout) => {
    processSnapshotInFlight = false;
    if (err || typeof stdout !== "string") return; // keep the previous snapshot; consumers stay lenient
    processSnapshot = { at: startedAt, procs: parseProcessTable(stdout) };
  });
}
export { parseProcessTable };
// The fragment of the harness wrapper that names this task's command: the
// literal `eval '` followed by the command up to its first single quote or
// newline (the harness escapes quotes in more than one style across versions,
// so the needle stops before them). Undefined when nothing usable remains.
export function taskProcessNeedle(command: string | undefined): string | undefined {
  if (!command) return undefined;
  const cut = command.search(/['\n]/);
  const prefix = (cut >= 0 ? command.slice(0, cut) : command).slice(0, 80);
  return prefix.trim() ? `eval '${prefix}` : undefined;
}
// A task just armed may not be in a snapshot taken moments before it — and the
// transcript's clock and the daemon's are close but not identical.
const TASK_PROCESS_GRACE_MS = 30_000;
export function verifyOpenTasks(
  tasks: OpenTaskInfo[],
  snapshot: ProcessSnapshot | undefined,
  agentPid: number | undefined,
): { alive: OpenTaskInfo[]; dead: OpenTaskInfo[] } {
  if (!snapshot || agentPid === undefined) return { alive: tasks, dead: [] };
  // Children of the agent (and their children — one indirection of slack in
  // case a wrapper ever sits between).
  const byPid = new Map(snapshot.procs.map((p) => [p.pid, p]));
  const isUnderAgent = (pid: number): boolean => {
    let cur = byPid.get(pid);
    for (let depth = 0; cur && depth < 2; depth++) {
      if (cur.ppid === agentPid) return true;
      cur = byPid.get(cur.ppid);
    }
    return false;
  };
  const alive: OpenTaskInfo[] = [];
  const dead: OpenTaskInfo[] = [];
  for (const t of tasks) {
    if (t.kind === "workflow") { alive.push(t); continue; }
    const needle = taskProcessNeedle(t.command);
    if (!needle) { alive.push(t); continue; }
    if (t.openedAt !== undefined && t.openedAt > snapshot.at - TASK_PROCESS_GRACE_MS) { alive.push(t); continue; }
    const found = snapshot.procs.some((p) => p.command.includes(needle) && isUnderAgent(p.pid));
    (found ? alive : dead).push(t);
  }
  return { alive, dead };
}
// The published shape: first line of the command only, no scan-private fields.
export function toOpenTaskReports(tasks: OpenTaskInfo[]): OpenTaskReport[] {
  return tasks.map(({ openedAt: _openedAt, command, ...rest }) => ({
    ...rest,
    ...(command ? { command: (command.split("\n").find((l) => l.trim()) ?? "").trim().slice(0, 200) } : {}),
  }));
}
// The pid behind a session, from the discovery cache; undefined until found.
// Checks registry supersession first: the open-task process check runs off
// this pid, and a stale one condemns every LIVE watcher the session's real
// process armed — collapsing a genuine "waiting" park into needs_input.
// Undefined (superseded, not yet rediscovered) fails toward "alive": exactly
// the lenient bias verifyOpenTasks wants.
function agentProcessPid(sessionId: string): number | undefined {
  if (dropSupersededProcessCacheEntry(sessionId)) return undefined;
  return sessionProcessCache.get(sessionId)?.pid;
}
// The open tasks the daemon will vouch for: transcript-open, generation-fenced,
// process-checked. Kicks a snapshot refresh so the NEXT call sees fresh
// processes; this call reads whatever snapshot exists.
export function verifiedOpenTasks(transcriptPath: string, sessionId: string): OpenTaskInfo[] {
  ensureProcessSnapshotFresh();
  const scanned = openBackgroundTasks(transcriptPath, sessionId, agentProcessStartedAt(sessionId));
  if (scanned.length === 0) return scanned;
  const { alive, dead } = verifyOpenTasks(scanned, processSnapshot, agentProcessPid(sessionId));
  if (dead.length) {
    log(`[OPEN-TASKS] ${sessionId.slice(0, 8)} ${dead.length} task(s) open in the transcript but no shell under pid ${agentProcessPid(sessionId)}: ${dead.map((t) => `${t.id}${t.description ? ` (${t.description})` : ""}`).join(", ")}`);
  }
  return alive;
}

// The agent process's start for a session, from the resource sampler's last
// report (ps etime → startedAt); undefined until the first sample or off
// darwin, in which case the restart fence simply doesn't apply.
function agentProcessStartedAt(sessionId: string): number | undefined {
  return lastReportedMetrics.get(sessionId)?.agentStartedAt;
}

export type SettleVerdict = "idle" | "waiting" | "dormant" | "done";

// The agent's own answer to "who acts next", if it gave one THIS turn: the
// `cast state --status dormant|done` stamp, trusted only when written after
// the turn began (turnStartedAt; the daemon's boot when the turn predates it —
// an older stamp has an unknown turn and is not trusted). Any client — the
// stamp is a plain file `cast state` writes on this machine, so Codex and the
// rest declare exactly like Claude.
export function declaredSettleVerdict(
  sessionId: string,
  now: number = Date.now(),
  turnStart: number | undefined = turnStartedAt.get(sessionId),
  stamp = readThreadStateStamp(sessionId),
): "dormant" | "done" | null {
  if (!stamp?.status || !DECLARED_VERDICT_STATUSES.has(stamp.status)) return null;
  const since = turnStart ?? DAEMON_BOOTED_AT;
  if (stamp.at < since || stamp.at > now + 60_000) return null;
  return stamp.status as "dormant" | "done";
}

// The status a finished turn should settle into. In trust order: the agent's
// declaration ("dormant" / "done", see declaredSettleVerdict); "waiting" when
// the transcript shows open background work (the harness will re-invoke the
// agent — Claude transcripts only, other clients don't surface background
// tasks in a scannable form); plain "idle" otherwise. An interrupted turn
// always settles idle: the user took control (ESC), so the ball is theirs even
// if an open task (e.g. a dev server) is still running or a stamp was written.
function resolveTurnEndStatus(sessionId: string, transcriptPath?: string): SettleVerdict {
  const file = transcriptPath
    ? { path: transcriptPath, agentType: "claude" as const }
    : findSessionFile(sessionId);
  const claude = !!file && file.agentType === "claude";
  let tail: string | null = null;
  if (claude) {
    try { tail = readFileTailSync(file!.path); } catch {}
  }
  // Turn start for the stamp fence: the in-memory mark while the daemon has
  // one, else the transcript's own last delivered input (restart-proof — see
  // transcriptTailTurnStartTs). declaredSettleVerdict still falls back to the
  // boot time when neither exists: needs-input stays the safe side.
  const turnStart = turnStartedAt.get(sessionId)
    ?? (tail !== null ? transcriptTailTurnStartTs(tail, sessionId) ?? undefined : undefined);
  const declared = declaredSettleVerdict(sessionId, Date.now(), turnStart);
  const openTasks = claude ? verifiedOpenTasks(file!.path, sessionId) : [];
  // Every settle publishes what it checked — an empty list included, so the
  // server's open_tasks never outlives the tasks. Picked up by the very next
  // sendAgentStatus for this session (callers send the verdict inline).
  if (claude) pendingOpenTaskReports.set(sessionId, toOpenTaskReports(openTasks));
  const openWork = openTasks.length > 0;
  if (!declared && !openWork) return "idle";
  if (tail !== null && transcriptTailEndsInterrupted(tail)) return "idle";
  return declared ?? "waiting";
}

// The newest turn-STARTING user message in a Claude JSONL tail: a user turn
// that is not a tool_result reply (those ride inside a turn), scoped to
// `currentSessionId` when given (a resumed file replays prior runs' history
// verbatim). The raw-line twin of latestTurnStartTs, for callers that hold a
// file tail rather than a parsed batch. Null when the window holds none.
//
// This is what lets declaredSettleVerdict survive a daemon restart: the
// in-memory turn mark dies with the process, and the old DAEMON_BOOTED_AT
// stand-in read every pre-boot `cast state dormant|done` stamp as untrusted —
// so a restart's boot reconcile republished "idle" over every parked session's
// declared verdict (17 live sessions demoted in one restart, 2026-08-31). The
// transcript is the durable record of delivered input; a stamp newer than the
// last user turn is the CURRENT turn's declaration, whatever the daemon's age.
export function transcriptTailTurnStartTs(tailContent: string, currentSessionId?: string): number | null {
  let latest: number | null = null;
  for (const rawLine of tailContent.split("\n")) {
    const line = rawLine.trim();
    if (!line) continue;
    let d: { type?: string; sessionId?: string; timestamp?: string; message?: { role?: string; content?: unknown } };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // partial/corrupt line (mid-write tail, or the cut first line) -> skip
    }
    if (d.type !== "user" || d.message?.role !== "user") continue;
    if (currentSessionId && d.sessionId && d.sessionId !== currentSessionId) continue;
    const content = d.message?.content;
    if (Array.isArray(content) && content.some((b) => (b as { type?: string })?.type === "tool_result")) continue;
    const ts = d.timestamp ? Date.parse(d.timestamp) : NaN;
    if (!isNaN(ts) && (latest === null || ts > latest)) latest = ts;
  }
  return latest;
}

// True when the newest real message in a Claude JSONL tail is the synthetic
// "[Request interrupted ...]" control message — the user stopped the turn.
// Mirrors classifyTranscriptTail's line-scanning (which deliberately maps an
// interrupt to the same "idle" as a normal turn end, so it can't be used to
// tell the two apart).
export function transcriptTailEndsInterrupted(tailContent: string): boolean {
  const lines = tailContent.split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line) continue;
    let d: { type?: string; message?: { role?: string; content?: unknown } };
    try {
      d = JSON.parse(line);
    } catch {
      continue;
    }
    const role = d.message?.role ?? (d.type === "user" || d.type === "assistant" ? d.type : undefined);
    if (role === "user") return isInterruptControlMessage(jsonlMessageText(d.message?.content));
    if (role === "assistant") return false;
  }
  return false;
}

// Codex's rollout JSONL marks turn boundaries with `event_msg` records instead of
// a per-message stop_reason. A turn ends with `task_complete` (and `turn_aborted`/
// `task_aborted` for interrupted ones); a turn is in flight after `task_started`
// or a fresh `user_message`. Everything else (`agent_message`, `token_count`,
// `response_item` deltas) is intra-turn noise we scan past. We read the tail back
// to front and decide on the first boundary event, mirroring classifyTranscriptTail
// so reconciledStatus can treat both agent types identically.
export function classifyCodexTranscriptTail(tailContent: string): TranscriptTurnState {
  const lines = tailContent.split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line) continue;
    let d: { type?: string; payload?: { type?: string } };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // partial/corrupt line (mid-write tail) -> skip
    }
    if (d.type !== "event_msg") continue;
    const t = d.payload?.type;
    if (t === "task_complete" || t === "turn_complete" || t === "task_aborted" || t === "turn_aborted") return "idle";
    if (t === "task_started" || t === "user_message") return "active";
    // token_count / agent_message / reasoning etc. -> intra-turn, keep scanning
  }
  return "unknown";
}

// OpenCode's json-store has no per-line stop_reason; a turn's state lives in the
// message file itself. findSessionFile points at a session's NEWEST message file
// (its tail), so the classifier reads that single message's JSON: an assistant
// message with `time.completed` set has finished its turn (idle); one without is
// still streaming (active); a user message is the agent's move (active). Also
// accepts the assembled export shape ({ messages: [...] }) so the same function
// works whether fed a lone message file or a whole-session snapshot — it decides
// off the newest message either way. Mirrors classifyTranscriptTail's
// active/idle/unknown contract so reconciledStatus treats opencode like the rest.
export function classifyOpencodeTranscriptTail(tailContent: string): TranscriptTurnState {
  let parsed: any;
  try {
    parsed = JSON.parse(tailContent);
  } catch {
    return "unknown"; // partial/mid-write file -> defer
  }
  // Assembled snapshot: reduce to the newest message's info.
  const info = Array.isArray(parsed?.messages)
    ? parsed.messages[parsed.messages.length - 1]?.info
    : parsed;
  const role = info?.role;
  if (role === "assistant") {
    return info?.time?.completed ? "idle" : "active";
  }
  if (role === "user") return "active";
  return "unknown";
}

// The single client -> transcript-tail classifier mapping. Claude, codex and
// opencode have a tail classifier; cursor/gemini return undefined, which every
// caller treats as "this client's transcript format isn't classified — defer" (the
// old `agentType !== "claude" && agentType !== "codex"` gate). A new client wires
// pi writes a JSONL tree; each line is a {type,id,parentId,...} entry. Turn state is
// carried on the assistant message's `stopReason`, mirroring claude's stop_reason:
//   - toolUse                       -> mid-turn (a tool call is pending) -> active
//   - stop/length/error/aborted     -> the turn ended                    -> idle
//   - a user or toolResult entry    -> the agent's move is next          -> active
//   - a streaming/unrecognized state -> defer                            -> unknown
// We read the tail back-to-front and decide on the first `message` entry, scanning
// past non-message entries (model_change / thinking_level_change / branch_summary /
// session header). NOTE: pi only flushes a turn's entries to disk once its assistant
// message completes (session-manager `_persist` buffers until the first assistant
// arrives), so an in-flight no-tool turn shows the PRIOR turn's end here — the pane
// readiness / status hooks cover that gap, exactly as for the other clients.
export function classifyPiTranscriptTail(tailContent: string): TranscriptTurnState {
  const lines = tailContent.split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line) continue;
    let d: { type?: string; message?: { role?: string; stopReason?: string } };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // partial/corrupt line (mid-write tail) -> skip
    }
    if (d.type !== "message") continue; // model_change / header / etc. -> keep scanning
    const role = d.message?.role;
    if (role === "assistant") {
      const sr = d.message?.stopReason;
      if (sr === "toolUse") return "active";
      if (sr === "stop" || sr === "length" || sr === "error" || sr === "aborted") return "idle";
      return "unknown"; // streaming / unrecognized stopReason -> defer
    }
    if (role === "user" || role === "toolResult") return "active";
    // any other role (extended message types) -> keep scanning for a real turn
  }
  return "unknown";
}

// Grok's updates.jsonl marks turn boundaries with the xAI `turn_completed` update
// — upstream calls it "the durable, replayable signal that a turn reached its
// terminal outcome" — instead of a per-message stop_reason. We read the tail back
// to front (mirroring classifyCodexTranscriptTail) and decide on the first
// meaningful update:
//   - turn_completed (ANY stop_reason: end_turn/cancelled/error/…)  -> idle
//   - pending_interaction with no later interaction_resolved        -> active
//     (the agent is parked on a question/permission — same convention as claude's
//     pending AskUserQuestion: never idle; the needs-input path owns surfacing it)
//   - user_message_chunk / tool_call / tool_call_update             -> active
//   - a streaming agent_message/thought chunk with no terminal mark -> unknown
//     (a crashed stream must defer, never read as active — claude convention)
// Housekeeping kinds appended AFTER turn_completed (last_turn_summary,
// session_summary_generated, session_recap, rewind_marker) and UI/meta kinds are
// scanned past. An unparsable line is the expected torn tail (buffered appends +
// healing) — skip it, never fail.
export function classifyGrokTranscriptTail(tailContent: string): TranscriptTurnState {
  const lines = tailContent.split("\n");
  // interaction_resolved lines sit AFTER the pending_interaction they answer, so
  // scanning backward we collect resolutions first and match them off by id
  // (falling back to a counter when the id fields are absent).
  const resolvedIds = new Set<string>();
  let resolvedAnon = 0;
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line) continue;
    let d: { params?: { update?: Record<string, unknown> }; update?: Record<string, unknown> };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // torn/partial line (mid-write tail) -> skip
    }
    const update = d.params?.update ?? d.update;
    const kind = update?.sessionUpdate;
    if (typeof kind !== "string") continue;
    switch (kind) {
      case "turn_completed":
        return "idle";
      case "interaction_resolved": {
        const key = update?.interaction_id ?? update?.id;
        if (typeof key === "string") resolvedIds.add(key);
        else resolvedAnon++;
        break; // keep scanning
      }
      case "pending_interaction": {
        const key = update?.interaction_id ?? update?.id;
        if (typeof key === "string" && resolvedIds.has(key)) break;
        if (typeof key !== "string" && resolvedAnon > 0) {
          resolvedAnon--;
          break;
        }
        return "active";
      }
      case "user_message_chunk":
      case "tool_call":
      case "tool_call_update":
        return "active";
      case "agent_message_chunk":
      case "agent_thought_chunk":
        return "unknown"; // streaming with no terminal marker -> defer
      default:
        break; // plan / meta / post-turn housekeeping -> keep scanning
    }
  }
  return "unknown";
}

// The single client -> transcript-tail classifier mapping. claude, codex and pi have
// a tail classifier; cursor/gemini return undefined, which every caller treats as
// "this client's transcript format isn't classified — defer" (the old
// `agentType !== "claude" && agentType !== "codex"` gate). A new jsonl client wires
// its classifier in here rather than adding another branch at each reconcile site.
// Kept daemon-side (not on the shared descriptor) so shared stays free of daemon
// types. Mirrors the parser.ts parseTranscriptFor dispatch.
const CLASSIFY_TRANSCRIPT_TAIL_BY_CLIENT: Partial<
  Record<AgentClientId, (tailContent: string) => TranscriptTurnState>
> = {
  claude: classifyTranscriptTail,
  codex: classifyCodexTranscriptTail,
  opencode: classifyOpencodeTranscriptTail,
  pi: classifyPiTranscriptTail,
  grok: classifyGrokTranscriptTail,
};

export function classifyTranscriptTailFor(
  agentType: AgentClientId,
): ((tailContent: string) => TranscriptTurnState) | undefined {
  return CLASSIFY_TRANSCRIPT_TAIL_BY_CLIENT[agentType];
}

// Decides whether the hook-driven status (lastSentAgentStatus) should be corrected
// against the transcript turn-state. The status hook is a last-write-wins latch: if
// a lifecycle transition is lost end-to-end (e.g. the Stop hook never reaches the
// daemon), the latch freezes at the wrong value and the heartbeat re-broadcasts it
// forever. The 2026-04-14 heartbeat-carries-status fix only repairs server<-daemon
// drift; it cannot repair a wrong *local* value -- this does.
//
// Corrects only on a positive structural signal in either direction, deferring on
// anything ambiguous, so it can never be wrong:
//   - active (working/thinking) but transcript ended its turn  -> idle (lost Stop)
//   - quiet (idle/connected) but transcript is mid-turn         -> working (lost activity hook)
// Everything else is untouched: a genuine long tool run is `active` (never flipped to
// idle), `unknown` defers, and permission_blocked/resuming/stopped/compacting are
// owned by other code paths.
export function reconciledStatus(
  stored: AgentStatus | undefined,
  turn: TranscriptTurnState,
): AgentStatus | null {
  const isActive = stored === "working" || stored === "thinking";
  const isQuiet = stored === "idle" || stored === "connected";
  if (isActive && turn === "idle") return "idle";
  if (isQuiet && turn === "active") return "working";
  return null;
}

// reconciledStatus with background-task awareness layered on:
//   - a turn-ended correction lands on "waiting" instead of "idle" while the
//     transcript still holds open background work (the harness will re-invoke);
//   - a stored "waiting" self-heals in both directions: forward to "working"
//     when the transcript went active (task notification arrived but the
//     activity hook was lost), and down to "idle" once the turn is ended with
//     no open work left (lost final Stop hook). Ambiguity defers, as ever.
//   - a stored DECLARED verdict ("dormant" / "done") wakes forward to "working"
//     when the transcript went active and otherwise holds: the agent said so,
//     and the declaration is spent only by the next turn start (which is that
//     very wake). A declaration made this turn also outranks the open-task
//     "waiting" on any correction that would otherwise land on idle.
export function reconciledStatusWithTasks(
  stored: AgentStatus | undefined,
  turn: TranscriptTurnState,
  hasOpenTasks: boolean,
  declared: "dormant" | "done" | null = null,
): AgentStatus | null {
  if (stored === "dormant" || stored === "done") {
    return turn === "active" ? "working" : null;
  }
  if (stored === "waiting") {
    if (turn === "active") return "working";
    if (turn === "idle" && !hasOpenTasks) return declared ?? "idle";
    return null;
  }
  const base = reconciledStatus(stored, turn);
  if (base !== "idle") return base;
  return declared ?? (hasOpenTasks ? "waiting" : "idle");
}

// The role of the most recent *real* (non-system/meta) message in a Claude JSONL
// tail, or null if none parses. Mirrors classifyTranscriptTail's role logic so the
// two stay consistent. Used to recover a stuck permission_blocked: an answered
// prompt's tail ends in a USER turn (the AskUserQuestion answer / a permissioned
// tool's tool_result is a type:"user" entry appended after the blocking assistant
// tool_use), while a still-pending prompt ends in the assistant tool_use.
export function transcriptTailLastRealRole(tailContent: string): "user" | "assistant" | null {
  const lines = tailContent.split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line) continue;
    let d: { type?: string; message?: { role?: string } };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // partial/corrupt line (mid-write tail) -> skip
    }
    const role = d.message?.role ?? (d.type === "user" || d.type === "assistant" ? d.type : undefined);
    if (role === "user" || role === "assistant") return role;
    // system/meta entry -> keep scanning for the last real message
  }
  return null;
}

// The wall-clock timestamp of the most recent *real* message in a Claude JSONL
// tail (epoch ms), or null when none parses or carries one. Same scan as
// transcriptTailLastRealRole, reading the `timestamp` field real turns carry and
// meta lines don't.
//
// This is the honest "when did anything actually happen" clock, and file mtime is
// NOT: metadata touches rewrite mtime with no new content (2026-08-03 — two
// transcripts whose last real message was 13 days old carried an mtime from that
// morning). Any gate measured in days must use this, not fs.statSync.
export function transcriptTailLastRealTimestamp(tailContent: string): number | null {
  const lines = tailContent.split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line) continue;
    let d: { type?: string; timestamp?: unknown; message?: { role?: string } };
    try {
      d = JSON.parse(line);
    } catch {
      continue; // partial/corrupt line (mid-write tail) -> skip
    }
    const role = d.message?.role ?? (d.type === "user" || d.type === "assistant" ? d.type : undefined);
    if (role !== "user" && role !== "assistant") continue; // system/meta -> keep scanning
    if (typeof d.timestamp !== "string") return null;
    const ms = Date.parse(d.timestamp);
    return Number.isFinite(ms) ? ms : null;
  }
  return null;
}

// permission_blocked is a latch with no other recovery path: the daemon doesn't
// drive AskUserQuestion resolution, reconciledStatus deliberately skips it, and the
// pane reconcile can't tell an answered poll from a pending one. So a lost resume
// "working" hook freezes the session in "Needs Input". Recover only on the positive
// signal that the prompt was answered -- the transcript tail's last real message is
// a user turn. A still-pending prompt ends in the assistant tool_use (lastRole
// "assistant") and is left untouched, so this can never clear a live prompt.
export function permissionBlockedRecoveryTarget(
  stored: AgentStatus | undefined,
  lastRealRole: "user" | "assistant" | null,
): AgentStatus | null {
  if (stored !== "permission_blocked") return null;
  return lastRealRole === "user" ? "working" : null;
}

// In bypassPermissions mode Claude Code still emits permission_prompt
// Notifications for tools it auto-approves; those are phantom blocks (the agent
// never pauses) and must be rewritten to "working" to avoid a dangling web
// Approve/Deny dialog. AskUserQuestion is the exception: it genuinely blocks the
// agent on a user prompt regardless of permission mode, so the status hook tags
// it via `message` and we let that one through to the "needs input" bucket.
export function isPhantomBypassPermissionBlock(
  status: string | undefined,
  permissionMode: string | undefined,
  message: string | undefined,
): boolean {
  if (status !== "permission_blocked") return false;
  if (permissionMode !== "bypassPermissions") return false;
  return !(message || "").startsWith("AskUserQuestion");
}

// Decide whether one hook event's permission_blocked should be suppressed as a phantom
// bypass auto-approve, accounting for an in-progress AskUserQuestion block. `blocked` is
// mutated in place across the event stream for a session:
//   - a PreToolUse AskUserQuestion hook (message="AskUserQuestion") opens the block
//   - any non-blocked status closes it (the answer landed and the agent moved on)
// While the block is open, a context-free permission_blocked Notification is the agent
// genuinely waiting — not a phantom — so it must not be suppressed. This is what keeps
// the web honest ("waiting for input", not "working/stuck") for raw-iTerm sessions whose
// question can't be scraped from a pane or read from the buffered JSONL until answered.
export function classifyBypassBlock(
  blocked: Set<string>,
  sessionId: string,
  status: string | undefined,
  permissionMode: string | undefined,
  message: string | undefined,
): { suppress: boolean } {
  if (status === "permission_blocked" && (message || "").startsWith("AskUserQuestion")) {
    blocked.add(sessionId);
  } else if (status && status !== "permission_blocked") {
    blocked.delete(sessionId);
  }
  const suppress =
    isPhantomBypassPermissionBlock(status, permissionMode, message) && !blocked.has(sessionId);
  return { suppress };
}

const tmuxTargetLocks = new Map<string, Promise<void>>();
// Cap how long a new caller will wait on an existing lock holder. Combined with the
// Promise.race timeout in deliverMessage, this keeps a single hung inject from wedging
// every subsequent inject for the same tmux session. Set well above typical inject
// (~5s) but below the deliverMessage ceiling (180s).
const TMUX_LOCK_WAIT_MS = 60_000;

async function withTmuxLock<T>(target: string, fn: () => Promise<T>): Promise<T> {
  const baseTarget = target.split(":")[0];
  const start = Date.now();
  while (tmuxTargetLocks.has(baseTarget)) {
    const elapsed = Date.now() - start;
    if (elapsed >= TMUX_LOCK_WAIT_MS) {
      log(`tmux lock for ${baseTarget} held >${Math.round(elapsed / 1000)}s, forcing release and proceeding`);
      tmuxTargetLocks.delete(baseTarget);
      break;
    }
    const existing = tmuxTargetLocks.get(baseTarget);
    if (!existing) break;
    // Race the held lock against a short slice so the elapsed check runs even if
    // the holder never resolves.
    await Promise.race([
      existing,
      new Promise<void>(r => setTimeout(r, Math.min(1000, TMUX_LOCK_WAIT_MS - elapsed))),
    ]);
  }
  let resolve: () => void;
  const lock = new Promise<void>(r => { resolve = r; });
  tmuxTargetLocks.set(baseTarget, lock);
  try {
    return await fn();
  } finally {
    // Only delete if we still own the slot — a forced release may have replaced us
    // with a successor whose entry must not be removed by our finally.
    if (tmuxTargetLocks.get(baseTarget) === lock) {
      tmuxTargetLocks.delete(baseTarget);
    }
    resolve!();
  }
}

// Drives the live UI to a paste-safe condition through repeated
// classify→act→re-classify steps, and reports whether the agent is mid-turn so
// the caller can adapt its paste. Throws a structured error (SESSION_EXITED,
// AGENT_UNKNOWN_STATE, …) so retryStuckMessages can decide whether to redrive.
// Per-state actions are hardcoded to safe choices (Escape for both interrupted
// and rewind — Enter would rewind the conversation), and the stall guard fails
// fast if our action doesn't change the live state instead of hammering forever.
//
// `busy: true` means the agent is generating but its input box (❯) is live for
// type-ahead — a paste lands in Claude Code's native queue and submits when the
// turn ends. We do NOT wait for idle: that only ever served to keep the paste
// path's mandatory leading Escape from interrupting the turn, and the caller now
// simply skips that Escape when busy (see injectViaTmuxInner).
// Detached tmux sessions default to 80x24, and Claude Code's teammate panes
// split that window until the lead pane is too narrow for its TUI to render
// recognizably (truncated footer markers, separators under the detection
// threshold, chip-list-only regions). Nobody is attached to daemon-owned
// sessions, so claim a real screen. An attached client re-imposes its own size.
const TMUX_WINDOW_WIDTH = "220";
const TMUX_WINDOW_HEIGHT = "50";
const TMUX_SIZE_ARGS = ["-x", TMUX_WINDOW_WIDTH, "-y", TMUX_WINDOW_HEIGHT];
// When teammate panes split the 220-column window, give the lead pane 130 and
// leave 89 for the side stack — both sides stay above the 80-column TUI floor.
const TMUX_LEAD_PANE_WIDTH = "130";

// Self-heal for a lead pane under 80 columns — too narrow to render the markers
// the classifier needs (and mirrored at that width by the web terminal). Two
// distinct squeezes: a window that was never sized (created before the daemon
// sized its windows, or re-squeezed by a small attached client that detached),
// fixed by resize-window; and a window SPLIT by Claude Code's teammate panes,
// where resize-window is a no-op — the total is already right, only the pane
// tiling is wrong — so the lead pane must be widened directly. Returns the tmux
// commands to run (without target); empty when the pane is healthy.
//
// A window that is short rather than narrow is the web terminal split's
// signature: it sizes the pane to a few rows while open and hands the size
// back on detach — unless the daemon died under it. Nobody attached and the
// window at a fraction of its height means that hand-back was lost, so the
// window is put back. Only when nobody is attached: a live client (the split
// itself, a human's terminal) owns the size while it is there.
const TMUX_MIN_UNATTENDED_HEIGHT = 20;
export function planLeadPaneHeal(paneWidth: number, windowPanes: number, windowHeight = Infinity, sessionAttached = 0): string[][] {
  const narrow = !(paneWidth >= 80); // NaN (unparseable) counts as narrow, as before
  const short = windowHeight < TMUX_MIN_UNATTENDED_HEIGHT && sessionAttached === 0;
  if (!narrow && !short) return [];
  const cmds: string[][] = [["resize-window", "-x", TMUX_WINDOW_WIDTH, "-y", TMUX_WINDOW_HEIGHT]];
  if (narrow && windowPanes > 1) cmds.push(["resize-pane", "-x", TMUX_LEAD_PANE_WIDTH]);
  return cmds;
}

// Best-effort — classification proceeds either way.
async function ensureTmuxPaneWide(target: string): Promise<void> {
  try {
    const { stdout } = await tmuxExec(["display-message", "-p", "-t", target, "#{pane_width}|#{window_panes}|#{window_height}|#{session_attached}"]);
    const [paneWidth, windowPanes, windowHeight, sessionAttached] = stdout.trim().split("|").map((part) => parseInt(part, 10));
    const heals = planLeadPaneHeal(paneWidth, windowPanes, windowHeight, sessionAttached);
    if (!heals.length) return;
    for (const [cmd, ...rest] of heals) await tmuxExec([cmd, "-t", target, ...rest]);
    // Give the TUI a beat to reflow before the first capture.
    await new Promise(resolve => setTimeout(resolve, 500));
  } catch {}
}

// Boot + periodic sweep over every managed agent window nobody is attached
// to. The per-target heal above only runs when a message is injected, so a
// pane left squeezed by a viewer that never handed the size back — the daemon
// died or restarted under it, and no in-band restore survives that — stays
// squeezed for as long as the agent goes without a message, painting a
// screen too small to render into (165x6 across a restart, 2026-08-21).
// Unattended only: a live client, web or human, owns the size while it is
// there and restores it when it leaves.
async function healSqueezedAgentWindows(): Promise<number> {
  if (!hasTmux()) return 0;
  let healed = 0;
  try {
    const { stdout } = await tmuxExec([
      "list-windows", "-a", "-F", "#{session_name}|#{session_attached}|#{pane_width}|#{window_panes}|#{window_height}",
    ]);
    for (const line of stdout.split("\n")) {
      const [name, attached, paneWidth, windowPanes, windowHeight] = line.split("|");
      if (!name || !isManagedTmuxName(name)) continue;
      if ((parseInt(attached ?? "", 10) || 0) > 0) continue;
      const heals = planLeadPaneHeal(
        parseInt(paneWidth ?? "", 10),
        parseInt(windowPanes ?? "", 10) || 1,
        parseInt(windowHeight ?? "", 10),
        0,
      );
      if (!heals.length) continue;
      for (const [cmd, ...rest] of heals) await tmuxExec([cmd, "-t", name, ...rest]);
      healed++;
      log(`[TERM] healed squeezed agent window ${name} (was ${paneWidth}x${windowHeight}, nobody attached)`);
    }
  } catch {}
  return healed;
}

export async function ensureTmuxReady(target: string, agentType?: AgentClientId): Promise<{ busy: boolean }> {
  const STUCK_BUDGET_MS = 8_000;
  await ensureTmuxPaneWide(target);
  const startedAt = Date.now();
  let lastCorrectiveState: TmuxLiveState | null = null;
  let sameStateAttempts = 0;

  // Glyph-less clients (opencode/pi/grok) are classified from the WHOLE pane via
  // their registry readiness pattern, not the ❯/›-glyph whitelist (see
  // classifyGlyphlessClientPaneState / ct-39174).
  const glyphlessPattern = glyphlessPromptPattern(agentType);

  while (true) {
    let stdout: string;
    try {
      ({ stdout } = await tmuxExec(["capture-pane", "-p", "-J", "-t", target, "-S", "-25"]));
    } catch (err) {
      throw new Error(`AGENT_CAPTURE_FAILED: ${err instanceof Error ? err.message : String(err)}`);
    }
    const region = glyphlessPattern ? stdout : extractTmuxLiveRegion(stdout);
    const state = glyphlessPattern
      ? classifyGlyphlessClientPaneState(stdout, glyphlessPattern)
      : classifyTmuxLiveState(region);

    if (state === "idle") return { busy: false };
    if (state === "exited") {
      throw new Error("SESSION_EXITED: agent has exited, refusing to inject into bare shell");
    }

    // Mid-turn: inject into the live type-ahead box instead of waiting for idle.
    // The caller skips the leading Escape on this signal so the turn isn't
    // interrupted; Claude Code queues the pasted message and submits it when the
    // turn ends. verifyTmuxSubmitAfterPaste confirms it reached the queue.
    if (state === "busy") return { busy: true };

    // Corrective states: cap total time and bail if our key didn't move the state.
    if (Date.now() - startedAt >= STUCK_BUDGET_MS) {
      throw new Error(`AGENT_NOT_READY: live state '${state}' did not settle within ${STUCK_BUDGET_MS}ms`);
    }

    // Glyph-less clients have no pane-driven corrective modals — an "unknown"
    // here just means the readiness marker hasn't rendered yet (TUI still
    // booting/redrawing), so poll again until it does or the budget above trips.
    // There are no keys to send.
    if (glyphlessPattern) {
      await new Promise(resolve => setTimeout(resolve, 300));
      continue;
    }

    if (state === lastCorrectiveState) {
      if (++sameStateAttempts >= 3) {
        throw new Error(`AGENT_STUCK_${state.toUpperCase()}: corrective input did not change live state`);
      }
    } else {
      sameStateAttempts = 0;
      lastCorrectiveState = state;
    }

    if (state === "unknown") {
      log(`Unrecognized live UI in ${target}, deferring: ${region.replace(/\s+/g, " ").slice(0, 240)}`);
      throw new Error("AGENT_UNKNOWN_STATE: deferring");
    }

    if (state === "interrupted") {
      log(`Clearing Interrupted dialog in ${target}`);
      await tmuxExec(["send-keys", "-t", target, "Escape"]);
      await new Promise(resolve => setTimeout(resolve, 500));
    } else if (state === "rewind") {
      log(`Cancelling Rewind dialog in ${target} (Escape, never Enter)`);
      await tmuxExec(["send-keys", "-t", target, "Escape"]);
      await new Promise(resolve => setTimeout(resolve, 500));
    } else if (state === "trust") {
      log(`Accepting workspace trust prompt in ${target} (Enter)`);
      await tmuxExec(["send-keys", "-t", target, "Enter"]);
      await new Promise(resolve => setTimeout(resolve, 2000));
    } else if (state === "warning") {
      log(`Dismissing warning banner in ${target}`);
      await tmuxExec(["send-keys", "-t", target, "Enter"]);
      await new Promise(resolve => setTimeout(resolve, 800));
    }
  }
}

// Read the question of any interactive menu currently on the pane (null if none).
// Lets a numbered poll keystroke tell whether it submitted (menu gone, or advanced to
// the next question) or merely moved the highlight (same question still up). See the
// closed-loop in injectViaTmuxInner.
async function paneInteractiveQuestion(target: string): Promise<string | null> {
  try {
    const { stdout } = await tmuxExec(["capture-pane", "-p", "-J", "-t", target, "-S", "-80"]);
    return parseInteractivePrompt(stdout)?.question ?? null;
  } catch {
    return null;
  }
}

async function pasteTextIntoPane(target: string, text: string, bracketed = true): Promise<void> {
  await pasteTextIntoPaneWith(tmuxExec, target, text, bracketed);
}

// Post-submit verification: closed loop until the pasted message provably
// submitted. Extracted from injectViaTmuxInner with injected IO so the
// boot-race state machine is unit-testable (daemon.inject-submit-verify.test.ts).
//
// The key case is a freshly spawned agent: Claude Code renders its shell
// (banner + input box) within ~1s of spawn but doesn't consume stdin until
// several seconds later, so the paste sits pty-buffered with the pane FROZEN
// — and when the buffer finally drains, any Enter queued alongside the text
// is coalesced into the paste burst (rendered as a newline, never a submit).
// Only a discrete Enter sent AFTER the drain submits. The old fixed 5×400ms
// loop misread the frozen pane ("no prompt, no stuck text → processing") and
// exited on its first iteration; the text then surfaced after boot with no
// Enter left to submit it, and the message sat in the composer forever
// (jx7ev2w: three kill+restarts in a row died this way).
export type TmuxSubmitVerifyIO = {
  capture: () => Promise<string>;
  sendEnter: () => Promise<void>;
  rePaste: () => Promise<void>;
  sleep: (ms: number) => Promise<void>;
  log: (msg: string) => void;
};

export async function verifyTmuxSubmitAfterPaste(
  io: TmuxSubmitVerifyIO,
  opts: { prePaste: string; pasteConfirmed: boolean; contentPrefix: string; multiline?: boolean; deadlineMs?: number },
): Promise<{ outcome: "submitted" | "timeout" | "exited"; rePasted: boolean; payloadSeen: boolean; payloadCheckable: boolean }> {
  const TICK = 400;
  const deadlineMs = opts.deadlineMs ?? 15_000;
  const normalizedPrefix = opts.contentPrefix.replace(/\s+/g, " ").trim();
  const prefixWasVisibleBefore =
    !!normalizedPrefix && opts.prePaste.replace(/\s+/g, " ").includes(normalizedPrefix);
  // Whether "our payload is on screen" is a checkable question at all: with an
  // empty prefix, or one that was already visible pre-paste (a redelivery of
  // text still in the transcript), absence of the prefix proves nothing. In
  // those ambiguous cases the loop keeps its legacy activity-based exits.
  const payloadCheckable = !!normalizedPrefix && !prefixWasVisibleBefore;
  let rePasted = false;
  let pasteSeen = false; // we watched our text sit in the input box
  let payloadSeen = false; // any trace of our text: in the box, or as transcript
  let idleEnters = 0;
  let liveNoTextTicks = 0;
  for (let elapsed = 0; elapsed < deadlineMs; elapsed += TICK) {
    await io.sleep(TICK);
    let pane: string;
    try {
      pane = await io.capture();
    } catch {
      return { outcome: "timeout", rePasted, payloadSeen, payloadCheckable };
    }
    const lastLines = pane.split("\n").slice(-15).join("\n");
    const hasPrompt = /[❯›]/.test(lastLines);
    const hasActivity = /⠋|⠙|⠹|⠸|⠼|⠴|⠦|⠧|⠇|⠏|●|thinking|Bash|Read|Edit|Write|Glob|Grep/.test(lastLines);
    if (payloadCheckable && pane.replace(/\s+/g, " ").includes(normalizedPrefix)) {
      payloadSeen = true;
    }
    // Activity (or a promptless pane) only proves that A turn is running — not
    // that it is OUR turn. On a cold-boot pane whose paste was dropped, the
    // buffered clearing bytes submit as a garbage message and start a turn that
    // looks exactly like success (ct-40212). So when the paste was unconfirmed
    // AND our payload is checkable but has never been seen, activity is not
    // accepted as evidence — fall through to the content-based checks instead.
    const foreignTurnPossible = !opts.pasteConfirmed && payloadCheckable && !pasteSeen && !payloadSeen;

    if (/-(?:ba)?sh:.*(?:No such file|command not found)/.test(lastLines) ||
        /Resume this session with:/i.test(pane)) {
      return { outcome: "exited", rePasted, payloadSeen, payloadCheckable };
    }

    if (hasActivity && !foreignTurnPossible) return { outcome: "submitted", rePasted, payloadSeen, payloadCheckable };

    // Frozen pane = the agent hasn't consumed the pty buffer yet (cold boot).
    // No evidence either way — keep waiting. Critically, do NOT re-paste or
    // conclude "processing": both misread a TUI that simply hasn't woken up.
    if (pane === opts.prePaste) continue;

    const inputStuck = tmuxPromptStillHasInput(pane, opts.contentPrefix) ||
      (!!opts.multiline && tmuxPromptShowsPastePlaceholder(pane));
    if (inputStuck) {
      // The TUI rendered our text but it's still in the box — earlier Enters
      // were coalesced into the paste burst or dropped during boot. The TUI
      // is provably consuming input now, so a discrete Enter registers.
      pasteSeen = true;
      io.log("message still in input box, pressing Enter");
      await io.sendEnter();
      continue;
    }

    if (!hasPrompt) {
      // No prompt + text not in input = processing — unless a foreign turn
      // (garbage submit) could explain it; then keep watching for content.
      if (!foreignTurnPossible) return { outcome: "submitted", rePasted, payloadSeen, payloadCheckable };
      continue;
    }

    if (pasteSeen || payloadSeen) {
      // Our text left the input box (we watched it go after an Enter, or it
      // now shows above the box as transcript) — submitted.
      return { outcome: "submitted", rePasted, payloadSeen: true, payloadCheckable };
    }

    if (opts.pasteConfirmed) {
      // Pane changed right after the paste but the prefix never matched
      // (unrecognized prompt glyph, or TUI wrapping broke the 40-char match).
      // Enter is safe — the box holds nothing but our message — but bounded
      // so an idle false-positive can't spin until the deadline.
      if (++idleEnters > 5) return { outcome: "timeout", rePasted, payloadSeen, payloadCheckable };
      io.log("paste confirmed but not visible at prompt, pressing Enter");
      await io.sendEnter();
      continue;
    }

    // Live pane, empty prompt, our text nowhere: the paste was likely dropped.
    // Require a few consecutive live observations first — the box can render a
    // beat before the pty buffer drains, and a premature re-paste doubles the
    // message once it does.
    liveNoTextTicks++;
    if (!rePasted && liveNoTextTicks >= 3) {
      const promptLine = lastLines.split("\n").find((l) => /[❯›]/.test(l));
      const m = promptLine?.match(/[❯›]/);
      const afterPrompt = promptLine && m ? promptLine.slice(m.index! + 1).trim() : "";
      if (afterPrompt) return { outcome: "timeout", rePasted, payloadSeen, payloadCheckable }; // someone else's text at the prompt — don't stomp it
      io.log("paste likely dropped (live empty prompt), re-pasting once");
      await io.rePaste();
      rePasted = true;
      liveNoTextTicks = 0;
    }
  }
  return { outcome: "timeout", rePasted, payloadSeen, payloadCheckable };
}

// Drains the composer with blind C-a/C-k cycles before a paste.
//
// Why C-a/C-k cycles and not a single C-u: in Claude Code 2.1.x's input box a
// single C-u does not reliably empty the buffer when stale text is present
// (e.g. a prompt recalled via Up arrow). The leftover then concatenates with
// the paste and the trailing Enter submits both as one message — the
// "old prompt + new follow-up" duplication seen on 2026-05-19. Cycling C-a
// (start of line) + C-k (kill to end) drains reliably; three cycles handles
// multi-line drafts. See daemon.inject-clear.test.ts.
//
// This drain is best-effort: whatever it misses shows up at the prompt as
// foreign text and fails the Enter gate (awaitTmuxComposerPayload), which
// re-drains and re-pastes. The gate, not this drain, is the closed loop.
export async function drainTmuxComposer(
  target: string,
  exec: typeof tmuxExec = tmuxExec,
): Promise<void> {
  for (let i = 0; i < 3; i++) {
    await exec(["send-keys", "-t", target, "C-a"]);
    await new Promise(resolve => setTimeout(resolve, 20));
    await exec(["send-keys", "-t", target, "C-k"]);
    await new Promise(resolve => setTimeout(resolve, 20));
  }
  await new Promise(resolve => setTimeout(resolve, 50));
}

// A TUI paints its composer seconds before it starts reading stdin: on a cold
// boot under load, Claude Code's ❯ box is visible while every key sent to the
// pty still lands in a buffer the input handler later mishandles (ct-40212;
// measured gap up to ~7s on a loaded host). A painted prompt is therefore NOT
// proof of readiness. Earlier revisions proved consumption by typing a foreign
// probe character ("q") before the paste — but any injected character can
// outrace a screen-based check: a probe still sitting in the pty buffer is
// invisible to capture-pane, renders AFTER the drain verifies clean, and
// submits glued to the message ("q<message>", ct-47277). The pty guarantees
// byte ORDER, not visibility, so the one check that cannot be outraced is
// waiting for the LAST bytes written — the payload itself — to render: once
// the payload is visible, everything written before it has been consumed too.
//
// awaitTmuxComposerPayload is that check. After the paste, poll the composer
// until the text at the prompt IS the payload (prefix match, whitespace
// ignored, since the TUI soft-wraps the box at arbitrary points) with nothing
// before it. Foreign text at the prompt — a stale draft the blind drain
// missed, a mishandled control byte — fails the match and triggers a drain +
// re-paste; Enter is only ever sent by the caller over a composer that
// visibly holds the message and nothing else. Every re-paste is preceded by
// C-a/C-k clearing bytes in the same pty stream, so in-order processing wipes
// any late flush of the earlier paste before the fresh one lands — a doubled
// message is impossible by construction.
//
// Scope: only panes showing a ❯/› composer glyph (Claude/cursor style) and a
// payload the composer can be watched for (non-blank, free of prompt glyphs
// that would break the last-glyph anchor); "unwatchable" keeps the legacy
// timed-Enter behavior for glyphless clients. Throws AGENT_STDIN_NOT_READY
// when the composer never converges within the budget — the delivery layer's
// retry/backoff redelivers later instead of submitting into a deaf or dirty
// pane.
const stripComposerWs = (s: string) => s.replace(/\s+/g, "");

// The first 40 non-whitespace chars the composer must show at the prompt, or
// null when the payload cannot be watched for.
export function tmuxWatchablePrefix(payload: string): string | null {
  if (/[❯›]/.test(payload)) return null;
  return stripComposerWs(payload).slice(0, 40) || null;
}

export async function awaitTmuxComposerPayload(
  target: string,
  payload: string,
  opts: {
    multiline?: boolean;
    prePaste?: string;
    rePaste: () => Promise<void>;
    budgetMs?: number;
    exec?: typeof tmuxExec;
  },
): Promise<"matched" | "unwatchable"> {
  const exec = opts.exec ?? tmuxExec;
  const prefix = tmuxWatchablePrefix(payload);
  if (prefix === null) return "unwatchable";
  const deadline = Date.now() + (opts.budgetMs ?? 20_000);
  const tick = () => new Promise(resolve => setTimeout(resolve, 150));

  let glyphlessTicks = 0;
  let liveEmptyTicks = 0;
  let foreignTicks = 0;
  let rePastes = 0;
  const drainAndRePaste = async (why: string) => {
    log(`${why} in ${target}, draining and re-pasting`);
    rePastes++;
    liveEmptyTicks = 0;
    foreignTicks = 0;
    await drainTmuxComposer(target, exec);
    await opts.rePaste();
  };

  while (Date.now() < deadline) {
    let pane: string;
    try {
      ({ stdout: pane } = await exec(["capture-pane", "-p", "-J", "-t", target, "-S", "-40"]));
    } catch {
      return "unwatchable"; // capture problems are diagnosed by the post-submit verifier
    }
    const glyphAt = Math.max(pane.lastIndexOf("❯"), pane.lastIndexOf("›"));
    if (glyphAt === -1) {
      // Glyphless client, or a transient redraw hid the box: after a few
      // consecutive misses, hand back to the legacy timed-Enter path.
      if (++glyphlessTicks >= 3) return "unwatchable";
      await tick();
      continue;
    }
    glyphlessTicks = 0;
    const afterGlyph = pane.slice(glyphAt + 1);
    const glyphLine = afterGlyph.split("\n", 1)[0];
    // A multi-line bracketed paste can render as a collapsed chip
    // ("[Pasted text #1 +13 lines]") with none of the text visible: the chip
    // at the prompt with nothing before it IS the payload.
    const chip = opts.multiline ? glyphLine.match(/\[[^\]\n]*pasted[^\]\n]*\]/i) : null;
    const matched = chip
      ? !glyphLine.slice(0, chip.index).trim()
      : stripComposerWs(afterGlyph).startsWith(prefix);
    if (matched) return "matched";

    if (!glyphLine.trim()) {
      // Empty prompt. A frozen pane (identical to the pre-paste capture)
      // means the paste is still pty-buffered — wait, never re-paste: a
      // second copy would flush right behind the first. A LIVE empty prompt
      // held for a few ticks means the paste was dropped.
      foreignTicks = 0;
      if (opts.prePaste !== undefined && pane === opts.prePaste) {
        liveEmptyTicks = 0;
      } else if (++liveEmptyTicks >= 3 && rePastes < 2) {
        await drainAndRePaste("composer still empty after paste");
      }
      await tick();
      continue;
    }

    // Foreign text at the prompt: a stale draft, probe-era residue, or a
    // render still mid-flush. Give it a few ticks to converge into a match,
    // then clear and re-paste.
    liveEmptyTicks = 0;
    if (++foreignTicks >= 3 && rePastes < 2) {
      await drainAndRePaste("composer holds foreign text");
    }
    await tick();
  }
  throw new Error("AGENT_STDIN_NOT_READY: composer never showed the pasted payload, leaving message pending for retry");
}

export async function injectViaTmux(target: string, content: string, agentType?: AgentClientId): Promise<void> {
  return withTmuxLock(target, () => injectViaTmuxInner(target, content, agentType));
}

async function injectViaTmuxInner(target: string, content: string, agentType?: AgentClientId): Promise<void> {
  // Does this client's TUI bracket a paste? Decides whether newlines in the
  // payload survive as composer newlines or get flattened to spaces — see
  // prepareInjectedContent. Applies to poll free-text answers too: those are
  // usually one line, but nothing stops a user from writing several.
  const bracketed = clientAcceptsBracketedPaste(agentType);
  const poll = parsePollMessage(content);
  if (poll) {
    // Poll keys only mean anything against a live menu. A stale card click (the
    // menu resolved minutes ago) otherwise fires arrows/Enter/Escape into
    // whatever the TUI shows NOW — a blind Enter is how a dead /model card
    // opened a Shell-details overlay and wedged every later delivery
    // (2026-08-21). Menu gone: a free-text answer still delivers as a plain
    // message; a key-only answer is dropped as stale.
    const liveMenu = await paneInteractiveQuestion(target);
    if (!liveMenu) {
      const fallbackText = (poll.text || pollDeclineText(poll) || "").trim();
      if (!fallbackText) {
        log(`Interactive menu no longer on screen in ${target}; dropped stale poll keys`);
        return;
      }
      log(`Interactive menu no longer on screen in ${target}; delivering poll answer as plain text`);
      return injectViaTmuxInner(target, fallbackText, agentType);
    }
    // A free-text answer can't be entered into Claude Code's AUQ menu — decline the whole
    // menu once (Escape) and type the answer at the prompt. See pollDeclineText for why.
    const declineText = pollDeclineText(poll);
    if (declineText !== null) {
      await tmuxExec(["send-keys", "-t", target, "Escape"]);
      await new Promise(resolve => setTimeout(resolve, 500));
      if (declineText) {
        await pasteTextIntoPane(target, declineText, bracketed);
        await new Promise(resolve => setTimeout(resolve, 150));
        await tmuxExec(["send-keys", "-t", target, "Enter"]);
      }
      log(`Injected poll free-text answer (declined menu) via tmux to ${target}`);
      return;
    }

    const menuSteps = pollMenuSteps(poll);
    for (const step of menuSteps) {
      // A bare digit submits a plain AskUserQuestion menu, but an AUQ whose options
      // carry `preview`s renders side-by-side and the digit ONLY navigates — its
      // footer reads "Enter to select", so the answer never lands without a follow-up
      // Enter (verified in tmux on Claude Code 2.1.166). Decide per keypress instead
      // of guessing: note the on-screen question, send the digit, then look again. If
      // the SAME question is still up the digit only highlighted, so confirm with
      // Enter; if the menu is gone (auto-submitted) or advanced to the next question,
      // a follow-up Enter would be spurious, so skip it. On a `multi` poll the digits
      // are checkbox toggles and the menu is SUPPOSED to stay up — the confirm Enter
      // would re-toggle the highlighted row, so skip the probe entirely.
      const qBefore = !poll.multi && /^\d+$/.test(step.key) ? await paneInteractiveQuestion(target) : null;
      await tmuxExec(["send-keys", "-t", target, step.key]);
      await new Promise(resolve => setTimeout(resolve, 500));
      if (qBefore && (await paneInteractiveQuestion(target)) === qBefore) {
        await tmuxExec(["send-keys", "-t", target, "Enter"]);
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
    if (poll.text) {
      await new Promise(resolve => setTimeout(resolve, 300));
      await pasteTextIntoPane(target, poll.text, bracketed);
      await new Promise(resolve => setTimeout(resolve, 150));
      await tmuxExec(["send-keys", "-t", target, "Enter"]);
    } else if (menuSteps.length > 0) {
      // Claude Code ≥2.1.x no longer auto-continues AskUserQuestion forms: every
      // multi-question (and multiSelect) form parks on a final "Review your answers"
      // pane with the cursor on "1. Submit answers" (verified in tmux on 2.1.201).
      // Payloads that predate the pane — one digit per question — stall there, so
      // after the steps run, confirm the pane if (and only if) it's what's on screen.
      const { stdout } = await tmuxExec(["capture-pane", "-p", "-J", "-t", target, "-S", "-30"]);
      if (/Ready to submit your answers\?/.test(stdout) && /❯\s*1[.)]\s*Submit answers/.test(stdout)) {
        await tmuxExec(["send-keys", "-t", target, "Enter"]);
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
    log(`Injected poll response via tmux to ${target}`);
    return;
  }
  // Newlines survive when this client's TUI brackets the paste (`paste-buffer
  // -p` only emits the markers for a program that asked for the mode) — see
  // prepareInjectedContent and the bracketedPaste capability.
  const sanitized = prepareInjectedContent(content, { bracketed });

  // Closed-loop pre-flight: classify the live UI region only (transcript ignored),
  // dispatch the correct clearing key per modal, re-classify until paste-safe.
  // Never sends a key without first proving which modal it'll act against — that's
  // the invariant that prevents Escape-at-idle from spuriously opening the Rewind
  // dialog. `busy` = agent mid-turn with a live type-ahead box; we paste into its
  // native queue rather than waiting for the turn to finish.
  const { busy } = await ensureTmuxReady(target, agentType);

  const contentLines = content.split(/\r?\n/).length;
  const captureLines = Math.max(30, contentLines + Math.ceil(sanitized.length / 60) + 10);
  const contentPrefix = sanitized.slice(0, 40);

  const doPaste = () => pasteTextIntoPane(target, sanitized, bracketed);

  // Clear any stale input before pasting to prevent draft text from being
  // prepended to the injected message or submitted by the trailing Enter —
  // see drainTmuxComposer for why C-a/C-k cycles. The drain is best-effort:
  // the Enter gate below refuses to submit over anything it missed.
  //
  // Escape is the one key here that doubles as "interrupt the current turn", so
  // it is gated on the agent being idle. Mid-turn the type-ahead box holds at most
  // a fresh draft, which the C-a/C-k drain clears without interrupting — and the
  // pasted message then rides Claude Code's native queue until the turn ends.
  if (!busy) {
    await tmuxExec(["send-keys", "-t", target, "Escape"]);
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  await drainTmuxComposer(target);

  // Capture pane before paste for before/after comparison
  let prePaste = "";
  try {
    const { stdout } = await tmuxExec(["capture-pane", "-p", "-J", "-t", target, "-S", `-${captureLines}`]);
    prePaste = stdout;
  } catch {}

  // Paste once
  await doPaste();

  // The payload is its own readiness probe: Enter is only sent once the
  // composer visibly holds it and nothing else — see awaitTmuxComposerPayload
  // for the deaf-boot, dropped-paste and foreign-residue handling. A gate
  // match doubles as paste confirmation for the post-submit verifier.
  const enterDelay = Math.max(100, Math.min(1000, Math.ceil(sanitized.length / 100) * 50));
  const gate = await awaitTmuxComposerPayload(target, sanitized, {
    multiline: bracketed && sanitized.includes("\n"),
    prePaste,
    rePaste: doPaste,
  });
  let pasteConfirmed = gate === "matched";
  if (gate === "matched") {
    await tmuxExec(["send-keys", "-t", target, "Enter"]);
  } else {
    // Unwatchable pane (glyphless client, blank payload): legacy timing.
    // Brief confirmation — did the pane change? (4 checks, 100ms apart.)
    // The post-submit verify loop below is the real safety net there.
    for (let attempt = 0; attempt < 4; attempt++) {
      await new Promise(resolve => setTimeout(resolve, 100));
      try {
        const { stdout: postPaste } = await tmuxExec(["capture-pane", "-p", "-J", "-t", target, "-S", `-${captureLines}`]);
        if (postPaste !== prePaste) {
          pasteConfirmed = true;
          break;
        }
      } catch {}
    }
    if (!pasteConfirmed) {
      log(`Paste may not have landed in ${target} (pane unchanged after 400ms), proceeding anyway`);
    }
    // Adaptive delay so tmux paste-buffer flushes before Enter; the same
    // pty-stream ordering that makes the gate sound keeps this safe too.
    await new Promise(resolve => setTimeout(resolve, enterDelay));
    await tmuxExec(["send-keys", "-t", target, "Enter"]);
  }

  // Post-submit: verify the agent started processing — see
  // verifyTmuxSubmitAfterPaste for the full state machine. The ultimate
  // backstop for a lost message is the Convex healer (it revives any
  // never-acked row once the session is idle), but that takes minutes — this
  // loop recovers the common cases (dropped Enter, cold-boot pty buffering)
  // in seconds.
  const verify = await verifyTmuxSubmitAfterPaste(
    {
      capture: async () =>
        (await tmuxExec(["capture-pane", "-p", "-J", "-t", target, "-S", `-${captureLines}`])).stdout,
      sendEnter: async () => {
        await tmuxExec(["send-keys", "-t", target, "Enter"]);
      },
      rePaste: async () => {
        await tmuxExec(["send-keys", "-t", target, "C-u"]);
        await new Promise(resolve => setTimeout(resolve, 200));
        await doPaste();
        await new Promise(resolve => setTimeout(resolve, enterDelay));
        await tmuxExec(["send-keys", "-t", target, "Enter"]);
      },
      sleep: (ms) => new Promise(resolve => setTimeout(resolve, ms)),
      log: (msg) => log(`${msg} (${target})`),
    },
    { prePaste, pasteConfirmed, contentPrefix, multiline: sanitized.includes("\n") },
  );
  if (verify.outcome === "exited") {
    // Propagates to deliverMessage's transient-failure backoff (the old
    // in-loop throw was swallowed by its own catch and never reached anyone).
    throw new Error("SESSION_EXITED: message was pasted into a bare shell");
  }
  if (verify.outcome === "timeout" && !pasteConfirmed && verify.payloadCheckable && !verify.payloadSeen) {
    // The full verify window produced zero trace of the payload: the paste
    // never rendered, never sat in the box, never appeared as transcript.
    // Returning normally here would ack a message the agent never saw — the
    // ct-40212 silent briefing drop. Throw instead so the delivery layer's
    // retry/backoff redelivers; the pre-paste C-a/C-k drain on the retry
    // clears any residue if the pty buffer drains late.
    throw new Error("INJECT_UNVERIFIED: paste unconfirmed and payload never appeared, leaving message pending for retry");
  }

  log(`Injected via tmux to ${target}${pasteConfirmed ? "" : " (unconfirmed)"}${verify.rePasted ? " (re-pasted)" : ""}${verify.outcome === "timeout" ? " (submit unverified)" : ""}`)
}

export function buildAppleScript(
  app: "iTerm2" | "Terminal",
  normalizedTty: string,
  content: string,
  poll: ReturnType<typeof parsePollMessage>,
  keystrokes = false,
  bracketed = true,
): { script: string; args: string } {
  const isIterm = app === "iTerm2";
  const prepareMessageText = (text: string): string => {
    const prepared = prepareInjectedContent(text, { bracketed });
    return bracketed ? `${PASTE_START}${prepared}${PASTE_END}` : prepared;
  };
  const appleScriptMessageExpression = (text: string): string => {
    const prepared = prepareInjectedContent(text, { bracketed })
      .replace(/\\/g, "\\\\")
      .replace(/"/g, '\\"');
    const literal = `"${prepared}"`;
    return bracketed
      ? `(ASCII character 27) & "[200~" & ${literal} & (ASCII character 27) & "[201~"`
      : literal;
  };

  if (poll) {
    // A free-text answer can't be entered into the AUQ menu: decline it once (Escape),
    // then type the answer at the prompt (textAction below). Otherwise drive the option
    // keystrokes. See pollDeclineText — declining per-step spilled the leftover option
    // digits into the reopened prompt box (the "211" bug).
    const declineText = pollDeclineText(poll);
    const menuSteps = pollMenuSteps(poll);

    let stepActions: string;
    if (declineText !== null) {
      stepActions = isIterm
        ? `            tell s to write text (ASCII character 27)`
        : `          do script (ASCII character 27) in t`;
    } else if (isIterm) {
      stepActions = menuSteps.map((step, i) => {
        const lines = [`            tell s to write text "${step.key}" without newline`];
        if (i < menuSteps.length - 1) lines.push("            delay 0.5");
        return lines.join("\n");
      }).join("\n");
    } else {
      stepActions = menuSteps.map((step, i) => {
        const lines = [`          do script "${step.key}" in t`];
        if (i < menuSteps.length - 1) lines.push("          delay 0.5");
        return lines.join("\n");
      }).join("\n");
    }

    // The text to type at the prompt: the declined free-text answer, or `poll.text` typed
    // into a field a menu option opened (plan feedback).
    const promptText = declineText !== null ? declineText : poll.text;
    const promptExpression = promptText ? appleScriptMessageExpression(promptText) : "";
    const textAction = promptText
      ? isIterm
        ? `\n            delay 0.3\n            tell s to write text ${promptExpression} without newline\n            delay 0.15\n            tell s to write text ""`
        : `\n          delay 0.3\n          do script ${promptExpression} in t`
      : "";

    const script = isIterm
      ? `on run argv
  set targetTty to item 1 of argv
  tell application "iTerm2"
    repeat with w in windows
      repeat with t in tabs of w
        repeat with s in sessions of t
          set sTty to tty of s
          if sTty is targetTty then
${stepActions}${textAction}
            return "ok"
          end if
        end repeat
      end repeat
    end repeat
  end tell
  return "not_found"
end run`
      : `on run argv
  set targetTty to item 1 of argv
  tell application "Terminal"
    repeat with w in windows
      repeat with t in tabs of w
        if tty of t is targetTty then
${stepActions}${textAction}
          return "ok"
        end if
      end repeat
    end repeat
  end tell
  return "not_found"
end run`;
    return { script, args: `'${normalizedTty}'` };
  }

  // Bracket message text so a multi-line prompt reaches the composer as one
  // message (see prepareInjectedContent). Both apps write the string as raw
  // bytes, so the markers do the same job here as `tmux paste-buffer -p`. The
  // submitting return lands after the closing marker: iTerm2 sends it as the
  // explicit empty `write text` below, Terminal.app as `do script`'s implicit
  // one. Keystroke payloads (an approve/deny "\r" or Escape) skip all of this —
  // they must stay raw keys.
  const payload = keystrokes ? content : prepareMessageText(content);
  const escapedContent = payload.replace(/'/g, "'\\''");
  const script = isIterm
    ? `on run argv
  set msgText to item 1 of argv
  set targetTty to item 2 of argv
  tell application "iTerm2"
    repeat with w in windows
      repeat with t in tabs of w
        repeat with s in sessions of t
          set sTty to tty of s
          if sTty is targetTty then
            tell s to write text msgText without newline
            delay 0.15
            tell s to write text ""
            return "ok"
          end if
        end repeat
      end repeat
    end repeat
  end tell
  return "not_found"
end run`
    : `on run argv
  set msgText to item 1 of argv
  set targetTty to item 2 of argv
  tell application "Terminal"
    repeat with w in windows
      repeat with t in tabs of w
        if tty of t is targetTty then
          do script msgText in t
          return "ok"
        end if
      end repeat
    end repeat
  end tell
  return "not_found"
end run`;
  return { script, args: `'${escapedContent}' '${normalizedTty}'` };
}

// ── Terminal label helper ───────────────────────────────────────────────────
function getTerminalLabel(termProgram?: string): string {
  switch (termProgram) {
    case "Apple_Terminal": return "Terminal.app";
    case "iTerm.app": return "iTerm2";
    case "ghostty": return "Ghostty";
    case "kitty": return "Kitty";
    case "WezTerm": return "WezTerm";
    case "Alacritty": return "Alacritty";
    default: return termProgram || "iTerm2";
  }
}

// Terminals where we know there's no direct injection API — tmux required
const TMUX_ONLY_TERMINALS = new Set(["ghostty", "Alacritty"]);

// ── AppleScript injection (iTerm2 + Terminal.app) ──────────────────────────
// Extracted from original injectViaTerminal — logic is identical
async function injectViaAppleScript(
  tty: string,
  content: string,
  termProgram?: string,
  keystrokes = false,
  bracketed = true,
): Promise<void> {
  const normalizedTty = normalizeTty(tty);
  const poll = keystrokes ? null : parsePollMessage(content);

  const app: "iTerm2" | "Terminal" = termProgram === "Apple_Terminal" ? "Terminal" : "iTerm2";
  const { script, args } = buildAppleScript(
    app,
    normalizedTty,
    content,
    poll,
    keystrokes,
    bracketed,
  );

  const tmpFile = writeTerminalInjectionScript(script);
  try {
    const { stdout } = await execAsync(`osascript "${tmpFile}" ${args}`);
    if (stdout.trim() === "not_found") {
      throw new Error(`${app} session not found for TTY ${normalizedTty}`);
    }
    log(`Injected ${poll ? "poll response" : "message"} via ${app} for TTY ${normalizedTty}`);
  } finally {
    try { fs.unlinkSync(tmpFile); } catch {}
  }
}

export function writeTerminalInjectionScript(
  script: string,
  directory = CONFIG_DIR,
): string {
  const tmpFile = path.join(
    directory,
    `terminal-inject-${process.pid}-${randomUUID()}.scpt`,
  );
  fs.writeFileSync(tmpFile, script, { flag: "wx", mode: 0o600 });
  return tmpFile;
}

// ── Kitty injection via remote control (`kitty @`) ─────────────────────────
// Requires allow_remote_control in kitty.conf

function mapKeyForKitty(key: string): string {
  const map: Record<string, string> = {
    Return: "enter", Enter: "enter", Escape: "escape",
    Up: "up", Down: "down", Left: "left", Right: "right",
    Tab: "tab", Space: "space", Backspace: "backspace", Delete: "delete",
  };
  return map[key] || key.toLowerCase();
}

async function findKittyWindowId(normalizedTty: string): Promise<number | null> {
  const { stdout } = await execAsync("kitty @ ls");
  const osWindows = JSON.parse(stdout);
  for (const osWindow of osWindows) {
    for (const tab of osWindow.tabs) {
      for (const window of tab.windows) {
        try {
          const { stdout: ttyOut } = await execAsync(`ps -o tty= -p ${window.pid}`);
          const windowTty = normalizeTty(ttyOut.trim());
          if (windowTty === normalizedTty) return window.id;
        } catch {}
      }
    }
  }
  return null;
}

// Send message text to a kitty window as a bracketed paste for verified clients
// so newlines land as composer newlines rather than Enter keys. Two flags matter:
//   --from-file        content is sent verbatim; passed as an argument instead,
//                      kitty interprets escapes, so a message containing the
//                      two characters \n would arrive as a real newline.
//   --bracketed-paste  `auto` wraps the payload only when the program in the
//                      window has bracketed paste mode on. Unverified clients
//                      skip it and receive text flattened before this call.
// The flag is newer than the oldest kitty we might meet, so an invocation that
// fails retries flattened on the plain send-text that has always worked.
async function kittySendText(match: string, text: string, bracketed: boolean): Promise<void> {
  const tmpFile = writeKittyInjectionPayload(
    prepareInjectedContent(text, { bracketed }),
  );
  try {
    const pasteFlag = bracketed ? " --bracketed-paste=auto" : "";
    try {
      await execAsync(`kitty @ send-text ${match}${pasteFlag} --from-file '${tmpFile}'`);
    } catch (err) {
      log(`kitty bracketed paste failed (${err instanceof Error ? err.message : String(err)}), sending flattened`);
      // Keep the fallback file-based too: putting arbitrary prompt text in the
      // shell command leaks it through process listings and reintroduces escape
      // interpretation. Flatten, overwrite our private file, and retry plainly.
      fs.writeFileSync(
        tmpFile,
        prepareInjectedContent(text, { bracketed: false }),
        { mode: 0o600 },
      );
      await execAsync(`kitty @ send-text ${match} --from-file '${tmpFile}'`);
    }
  } finally {
    try { fs.unlinkSync(tmpFile); } catch {}
  }
}

export function writeKittyInjectionPayload(
  payload: string,
  directory = CONFIG_DIR,
): string {
  const tmpFile = path.join(
    directory,
    `kitty-inject-${process.pid}-${randomUUID()}`,
  );
  fs.writeFileSync(tmpFile, payload, { flag: "wx", mode: 0o600 });
  return tmpFile;
}

async function injectViaKitty(
  tty: string,
  content: string,
  keystrokes = false,
  bracketed = true,
): Promise<void> {
  const normalizedTty = normalizeTty(tty);
  const windowId = await findKittyWindowId(normalizedTty);
  if (windowId === null) {
    throw new Error(`Kitty window not found for TTY ${normalizedTty}`);
  }
  const match = `--match id:${windowId}`;

  if (keystrokes) {
    const escaped = content.replace(/'/g, "'\\''");
    await execAsync(`kitty @ send-text ${match} '${escaped}'`);
    return;
  }

  const poll = parsePollMessage(content);
  if (poll) {
    // Free-text answer: decline the AUQ menu once (Escape) and type at the prompt. See
    // pollDeclineText — doing it per-step spilled leftover option digits into the prompt.
    const declineText = pollDeclineText(poll);
    if (declineText !== null) {
      await execAsync(`kitty @ send-key ${match} escape`);
      await new Promise(r => setTimeout(r, 500));
      if (declineText) {
        await kittySendText(match, declineText, bracketed);
        await new Promise(r => setTimeout(r, 150));
        await execAsync(`kitty @ send-key ${match} enter`);
      }
      log(`Injected poll free-text answer (declined menu) via Kitty for TTY ${normalizedTty}`);
      return;
    }
    for (const step of pollMenuSteps(poll)) {
      await execAsync(`kitty @ send-key ${match} ${mapKeyForKitty(step.key)}`);
      await new Promise(r => setTimeout(r, 500));
    }
    if (poll.text) {
      await new Promise(r => setTimeout(r, 300));
      await kittySendText(match, poll.text, bracketed);
      await new Promise(r => setTimeout(r, 150));
      await execAsync(`kitty @ send-key ${match} enter`);
    }
    log(`Injected poll response via Kitty for TTY ${normalizedTty}`);
    return;
  }

  await pasteAndSubmitText({
    paste: () => kittySendText(match, content, bracketed),
    submit: () => execAsync(`kitty @ send-key ${match} enter`),
  });
  log(`Injected message via Kitty for TTY ${normalizedTty}`);
}

// ── WezTerm injection via CLI (`wezterm cli`) ──────────────────────────────

const WEZTERM_KEY_SEQUENCES: Record<string, string> = {
  Return: "\r", Enter: "\r", Escape: "\x1b",
  Up: "\x1b[A", Down: "\x1b[B", Left: "\x1b[D", Right: "\x1b[C",
  Tab: "\t", Backspace: "\x7f", Delete: "\x1b[3~", Space: " ",
};

async function findWezTermPaneId(normalizedTty: string): Promise<number | null> {
  const { stdout } = await execAsync("wezterm cli list --format json");
  const panes = JSON.parse(stdout);
  for (const pane of panes) {
    if (pane.tty_name && normalizeTty(pane.tty_name) === normalizedTty) {
      return pane.pane_id;
    }
  }
  return null;
}

// --no-paste means "send these bytes as raw keystrokes", which is right for the
// key sequences below and wrong for message text: raw newlines read as Enter.
// Omitting it lets WezTerm deliver the payload as a bracketed paste when the
// pane's program has the mode on, so verified clients keep newlines. Unverified
// clients receive flattened text with --no-paste.
async function weztermSendText(
  paneId: number,
  text: string,
  opts: { asKeystrokes?: boolean; bracketed?: boolean } = {},
): Promise<void> {
  const asKeystrokes = opts.asKeystrokes ?? false;
  const bracketed = opts.bracketed ?? true;
  const payload = asKeystrokes ? text : prepareInjectedContent(text, { bracketed });
  const escaped = payload.replace(/'/g, "'\\''");
  const pasteFlag = asKeystrokes || !bracketed ? " --no-paste" : "";
  await execAsync(`printf '%s' '${escaped}' | wezterm cli send-text --pane-id ${paneId}${pasteFlag}`);
}

// Keystrokes (Escape, Enter, arrows, menu digits) must never be bracketed.
async function weztermSendKeys(paneId: number, keys: string): Promise<void> {
  await weztermSendText(paneId, keys, { asKeystrokes: true });
}

async function injectViaWezTerm(
  tty: string,
  content: string,
  keystrokes = false,
  bracketed = true,
): Promise<void> {
  const normalizedTty = normalizeTty(tty);
  const paneId = await findWezTermPaneId(normalizedTty);
  if (paneId === null) {
    throw new Error(`WezTerm pane not found for TTY ${normalizedTty}`);
  }

  if (keystrokes) {
    await weztermSendKeys(paneId, content);
    return;
  }

  const poll = parsePollMessage(content);
  if (poll) {
    // Free-text answer: decline the AUQ menu once (Escape) and type at the prompt. See
    // pollDeclineText — doing it per-step spilled leftover option digits into the prompt.
    const declineText = pollDeclineText(poll);
    if (declineText !== null) {
      await weztermSendKeys(paneId, "\x1b"); // Escape
      await new Promise(r => setTimeout(r, 500));
      if (declineText) {
        await weztermSendText(paneId, declineText, { bracketed });
        await new Promise(r => setTimeout(r, 150));
        await weztermSendKeys(paneId, "\r"); // Enter
      }
      log(`Injected poll free-text answer (declined menu) via WezTerm for TTY ${normalizedTty}`);
      return;
    }
    for (const step of pollMenuSteps(poll)) {
      const seq = WEZTERM_KEY_SEQUENCES[step.key];
      await weztermSendKeys(paneId, seq || step.key);
      await new Promise(r => setTimeout(r, 500));
    }
    if (poll.text) {
      await new Promise(r => setTimeout(r, 300));
      await weztermSendText(paneId, poll.text, { bracketed });
      await new Promise(r => setTimeout(r, 150));
      await weztermSendKeys(paneId, "\r");
    }
    log(`Injected poll response via WezTerm for TTY ${normalizedTty}`);
    return;
  }

  await pasteAndSubmitText({
    paste: () => weztermSendText(paneId, content, { bracketed }),
    submit: () => weztermSendKeys(paneId, "\r"),
  });
  log(`Injected message via WezTerm for TTY ${normalizedTty}`);
}

// ── Terminal injection router ──────────────────────────────────────────────
// Routes to the appropriate strategy based on TERM_PROGRAM.
// AppleScript path (iTerm2/Terminal.app) is the default fallback for
// unknown terminals — preserves existing behavior exactly.
// `keystrokes: true` marks a payload that IS keys rather than text — the
// permission approve/deny "\r"/"\x1b" senders. Verified clients receive message
// text as a bracketed paste; unverified clients receive one flattened prompt. A
// keystroke payload must never be bracketed, because wrapping a lone carriage
// return would turn "approve" into a literal newline the TUI ignores.
async function injectViaTerminal(
  tty: string,
  content: string,
  termProgram?: string,
  opts: { keystrokes?: boolean; agentType?: AgentClientId } = {},
): Promise<void> {
  const keystrokes = opts.keystrokes ?? false;
  const bracketed = clientAcceptsBracketedPaste(opts.agentType);
  if (termProgram === "kitty") {
    return injectViaKitty(tty, content, keystrokes, bracketed);
  }
  if (termProgram === "WezTerm") {
    return injectViaWezTerm(tty, content, keystrokes, bracketed);
  }
  if (termProgram && TMUX_ONLY_TERMINALS.has(termProgram)) {
    throw new Error(`${getTerminalLabel(termProgram)} does not support direct injection — use tmux for this terminal`);
  }
  // Apple_Terminal, iTerm.app, unknown → existing AppleScript path
  return injectViaAppleScript(tty, content, termProgram, keystrokes, bracketed);
}


type SessionFileInfo = { path: string; agentType: AgentClientId };

// A message that can never reach its target, whatever we retry: the delivery
// loop cancels the row instead of walking the retry ladder (and instead of
// "undeliverable", which the server re-pends).
class UndeliverableMessageError extends Error {}

/** The Codex rollout for a session id, if one exists:
 *  ~/.codex/sessions/YYYY/MM/DD/<name>-<timestamp>-<sessionId>.jsonl
 *
 *  Separate from findSessionFile because the rollout is the AUTHORITY on whether
 *  a session is a Codex thread, while findSessionFile answers a different
 *  question — "which transcript should I read?" — and searches ~/.claude/projects
 *  first. Those diverge whenever materializeSession has written a Claude-shaped
 *  mirror under a Codex session id (it does: clientOwnsSessionStore excludes
 *  codex, so the regeneration skip never fires for it). See
 *  sessionProcessOwnership, which must never be answered by the mirror.
 *
 *  Answered from the codex-only half of the session-file index (built solely
 *  from ~/.codex/sessions, so the mirror cannot shadow it) instead of a
 *  recursive walk per call: undecided ownership deliberately re-asks every
 *  resource tick, and the per-call walk froze the loop for tens of seconds
 *  when the expiring negative memos re-asked in a batch on a saturated disk
 *  (2026-08-29, and the same shape on 2026-08-21).
 *
 *  A MISS still answers with per-call ground truth: sessionProcessOwnership
 *  memoizes "owned" for an id with no rollout, so a stale "no rollout" here
 *  would freeze the wrong verdict and re-open the SIGKILL-the-parent hole for
 *  any rollout younger than the index. Creating (or moving) a rollout bumps
 *  its containing day dir's mtime, so scanning only the leaf dirs touched
 *  since the walk closes that window at a few stats' cost. */
function findCodexRolloutPath(sessionId: string, opts?: { staleOk?: boolean }): string | null {
  const hit = indexedSessionLookup(() => codexRolloutIndex, (p) => p, codexRolloutKnownMisses, sessionId);
  if (hit || opts?.staleOk) return hit;
  const recent = probeRecentCodexRollouts(sessionId);
  if (recent) {
    codexRolloutIndex?.set(sessionId, recent);
    codexRolloutKnownMisses.delete(sessionId);
  }
  return recent;
}

// The rollout store is YYYY/MM/DD leaf dirs. Enumerate the (few dozen)
// directories, but readdir only leaves whose mtime is at/after the last index
// walk — steady state that is one or two active day dirs. Files sitting at a
// non-leaf level are checked whenever their parent dir is fresh, matching the
// old fully-recursive walk for anything recently added.
function probeRecentCodexRollouts(sessionId: string): string | null {
  return timeSyncFs("probeRecentCodexRollouts", sessionId, () => probeRecentCodexRolloutsSync(sessionId));
}
function probeRecentCodexRolloutsSync(sessionId: string): string | null {
  const since = sessionFileIndexBuiltAt - 60_000; // clock/mtime slack
  const scan = (dir: string, depth: number): string | null => {
    let mtimeMs: number;
    try { mtimeMs = fs.statSync(dir).mtimeMs; } catch { return null; }
    let entries: fs.Dirent[] | null = null;
    if (mtimeMs >= since) {
      try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return null; }
      for (const e of entries) {
        if (e.isFile() && e.name.endsWith(".jsonl") && e.name.includes(sessionId)) {
          return path.join(dir, e.name);
        }
      }
    }
    if (depth >= 3) return null; // sessions/<year>/<month>/<day> is the leaf
    if (!entries) {
      try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return null; }
    }
    for (const e of entries) {
      if (!e.isDirectory()) continue;
      const found = scan(path.join(dir, e.name), depth + 1);
      if (found) return found;
    }
    return null;
  };
  return scan(path.join(process.env.HOME || "", ".codex", "sessions"), 0);
}

function findSessionJsonlPath(sessionId: string): string | null {
  return findSessionFile(sessionId)?.path ?? null;
}

// Every path a Claude transcript for `sessionId` can live at, in lookup
// order: the project dir's own <sessionId>.jsonl, then under each session dir
// the subagent layouts —
//   <parent-session-id>/<sessionId>.jsonl
//   <parent-session-id>/subagents/<sessionId>.jsonl            (Agent tool)
//   <parent-session-id>/subagents/workflows/<run>/<id>.jsonl   (Workflow tool)
// Paths are yielded whether or not they exist; callers check.
function* claudeTranscriptCandidates(sessionId: string): Generator<string> {
  const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
  if (!fs.existsSync(claudeProjectsDir)) return;
  const projectDirs = fs.readdirSync(claudeProjectsDir, { withFileTypes: true })
    .filter(d => d.isDirectory()).map(d => d.name);
  for (const dir of projectDirs) {
    const dirPath = path.join(claudeProjectsDir, dir);
    yield path.join(dirPath, `${sessionId}.jsonl`);
    try {
      const subEntries = fs.readdirSync(dirPath, { withFileTypes: true })
        .filter(d => d.isDirectory());
      for (const subDir of subEntries) {
        const parentDir = path.join(dirPath, subDir.name);
        yield path.join(parentDir, `${sessionId}.jsonl`);
        const subagentsDir = path.join(parentDir, "subagents");
        yield path.join(subagentsDir, `${sessionId}.jsonl`);
        const workflowsDir = path.join(subagentsDir, "workflows");
        if (fs.existsSync(workflowsDir)) {
          for (const wfRun of fs.readdirSync(workflowsDir, { withFileTypes: true })) {
            if (!wfRun.isDirectory()) continue;
            yield path.join(workflowsDir, wfRun.name, `${sessionId}.jsonl`);
          }
        }
      }
    } catch {}
  }
}

// The Workflow-tool agent transcript for `sessionId`, if one exists anywhere,
// else null. Deliberately NOT findSessionFile(...).path: the resume repair
// ladder copies such a transcript to the project dir's top level (so
// `claude --resume` can see it), and that copy is what findSessionFile returns
// first — a path check on it would wave the agent through. The agent has no
// process of its own to reach and no standalone resume that means anything, so
// both the delivery rail and autoResumeSession refuse it.
export function workflowAgentTranscriptPathFor(sessionId: string): string | null {
  for (const candidate of claudeTranscriptCandidates(sessionId)) {
    if (isWorkflowAgentTranscriptPath(candidate) && fs.existsSync(candidate)) return candidate;
  }
  return null;
}

// ─── Session-file index ────────────────────────────────────────────────────
// findSessionFile used to walk every transcript store per CALL — ~75 project
// dirs plus their subdirs (~1500 readdirs) for a claude lookup, a full
// recursive ~/.codex/sessions walk for codex, and so on. A single miss cost
// ~350ms of sync FS on the event loop, and the heartbeat maintenance pass
// calls it once per due session — with a 700+ session fleet that alone pinned
// the loop 5-20s per tick and lit the "daemon under load" badge. So the walk
// runs ONCE, enumerating every store into sessionId -> file, and lookups are
// map hits validated by a single existsSync.
//
// Freshness: a hit is stat-validated before it is returned, so deletions never
// go stale. An UNSEEN id missing from the index triggers one rebuild (throttled
// to the miss-rebuild window), so a transcript written moments ago — a new
// session, a repair — is found within ~2s. An id already confirmed absent from
// the CURRENT build is remembered and answers null without another walk, so
// chronic misses (sessions with no local file, re-queried by every maintenance
// tick) cost one map hit, not one walk per tick. The TTL only bounds how long a
// lower-priority path can keep answering after a higher-priority twin appears
// (the repair-ladder copy case) — rare and non-urgent, so it is generous.
//
// Insertion order per store mirrors the old probe order exactly (claude's
// project-dir readdir order with top-level files before subagent layouts), and
// stores are merged claude-first, so a session id present in two places keeps
// resolving to the same file the walk would have returned.
const SESSION_FILE_INDEX_TTL_MS = 5 * 60_000;
const SESSION_FILE_INDEX_MISS_REBUILD_MS = 2_000;
let sessionFileIndex: Map<string, SessionFileInfo> | null = null;
// The codex store's OWN view, from the same walk. sessionProcessOwnership must
// never let a claude-shaped mirror of a codex session answer for the rollout
// (the SIGKILL-the-parent hole), so it needs a lookup the claude stores can't
// shadow — this map is built exclusively from ~/.codex/sessions.
let codexRolloutIndex: Map<string, string> | null = null;
let sessionFileIndexBuiltAt = 0;
// Ids confirmed absent from the CURRENT index build (cleared on rebuild),
// tracked per map since an id can be present in one store and not the other.
const sessionFileKnownMisses = new Set<string>();
const codexRolloutKnownMisses = new Set<string>();
// The HOME the index was walked under. Tests swap HOME to a temp dir per case;
// an index carried across that swap would answer from the wrong tree.
let sessionFileIndexHome = "";

// Ids that missed and are waiting for a fresh build to confirm or refute
// them: id -> the build time they first missed against. Survives installs on
// purpose (it is what turns a pending miss into a confirmed one).
const sessionFilePendingMisses = new Map<string, number>();

/** Test hook: forget the index so the next lookup re-walks. */
export function resetSessionFileIndexForTests(): void {
  sessionFileIndex = null;
  codexRolloutIndex = null;
  sessionFileIndexBuiltAt = 0;
  sessionFileKnownMisses.clear();
  codexRolloutKnownMisses.clear();
  sessionFilePendingMisses.clear();
}

/** Test hook: make the index look `ms` old so the miss path treats it as stale. */
export function ageSessionFileIndexForTests(ms: number): void {
  sessionFileIndexBuiltAt -= ms;
}

function indexSessionFile(
  index: Map<string, SessionFileInfo>,
  sessionId: string,
  filePath: string,
  agentType: AgentClientId,
): void {
  // First wins: enumeration follows the old probe order, so an earlier entry is
  // the one the per-call walk would have returned.
  if (!index.has(sessionId)) index.set(sessionId, { path: filePath, agentType });
}

// The trailing uuid in a codex rollout (`<name>-<ts>-<uuid>.jsonl`) or pi
// (`<ISO-ts>_<uuid>.jsonl`) filename — the session id both stores key by.
const TRAILING_UUID_JSONL_RE = /([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.jsonl$/i;

// One transcript store per client: where it lives, how deep to look, and how
// a file's path names its session. Both index builders below walk exactly
// these, so the sync cold build and the async refresh cannot drift apart.
// Enumeration order per store mirrors the old per-call probe order (a
// directory's own files before its subdirectories, so a top-level
// <sessionId>.jsonl wins over a nested twin), and stores are merged
// claude-first.
type IndexStore = {
  root: string;
  agentType: AgentClientId;
  walk: WalkOptions;
  idOf: (f: WalkEntry) => string | null;
};
const segs = (rel: string) => rel.split(path.sep);
function sessionFileIndexStores(home: string): IndexStore[] {
  return [
    // Claude: <project>/<id>.jsonl, <project>/<session>/<id>.jsonl, its
    // subagents/, and subagents/workflows/<run>/ — never tool-results etc.
    {
      root: path.join(home, ".claude", "projects"),
      agentType: "claude",
      walk: {
        maxDepth: 6,
        dirFilter: (rel) => {
          const d = segs(rel);
          return d.length <= 2 || (d.length === 3 && d[2] === "subagents") || (d.length === 4 && d[3] === "workflows") || d.length === 5;
        },
        fileFilter: (rel) => rel.endsWith(".jsonl") && segs(rel).length !== 5,
      },
      idOf: (f) => f.name.slice(0, -6),
    },
    // Codex: ~/.codex/sessions/YYYY/MM/DD/<name>-<ts>-<sessionId>.jsonl, recursive.
    {
      root: path.join(home, ".codex", "sessions"),
      agentType: "codex",
      walk: {},
      idOf: (f) => TRAILING_UUID_JSONL_RE.exec(f.name)?.[1] ?? null,
    },
    // Gemini: ~/.gemini/tmp/<hash>/chats/<sessionId>.json
    {
      root: path.join(home, ".gemini", "tmp"),
      agentType: "gemini",
      walk: { maxDepth: 3, dirFilter: (rel) => { const d = segs(rel); return d.length === 1 || d[1] === "chats"; }, fileFilter: (rel) => rel.endsWith(".json") && segs(rel).length === 3 },
      idOf: (f) => f.name.slice(0, -5),
    },
    // pi: ~/.pi/agent/sessions/<cwd-slug>/<ISO-ts>_<sessionId>.jsonl
    {
      root: path.join(home, ".pi", "agent", "sessions"),
      agentType: "pi",
      walk: { maxDepth: 2, fileFilter: (rel) => segs(rel).length === 2 },
      idOf: (f) => TRAILING_UUID_JSONL_RE.exec(f.name)?.[1] ?? null,
    },
    // grok: ~/.grok/sessions/<url-encoded-cwd>/<sessionId>/updates.jsonl — the
    // session DIRECTORY is named by the id.
    {
      root: path.join(home, ".grok", "sessions"),
      agentType: "grok",
      walk: { maxDepth: 3, fileFilter: (rel) => segs(rel).length === 3 && path.basename(rel) === "updates.jsonl" },
      idOf: (f) => segs(f.rel)[1],
    },
  ];
}

type SessionFileIndexBuild = { index: Map<string, SessionFileInfo>; codexRollouts: Map<string, string> };
function recordIndexFiles(build: SessionFileIndexBuild, store: IndexStore, files: WalkEntry[]): void {
  for (const f of files) {
    const id = store.idOf(f);
    if (!id) continue;
    indexSessionFile(build.index, id, f.path, store.agentType);
    // The codex store's own view: first found wins, as the old recursive walk did.
    if (store.agentType === "codex" && !build.codexRollouts.has(id)) build.codexRollouts.set(id, f.path);
  }
}

// Synchronous: for a lookup that cannot wait (no index yet, or HOME changed
// under a test). readdir only, ~4ms warm; never the periodic path.
function buildSessionFileIndex(home: string): SessionFileIndexBuild {
  const build: SessionFileIndexBuild = { index: new Map(), codexRollouts: new Map() };
  for (const store of sessionFileIndexStores(home)) {
    walkDirsSync(store.root, store.walk, (files) => recordIndexFiles(build, store, files));
  }
  return build;
}

async function buildSessionFileIndexAsync(home: string): Promise<SessionFileIndexBuild> {
  const build: SessionFileIndexBuild = { index: new Map(), codexRollouts: new Map() };
  for (const store of sessionFileIndexStores(home)) {
    await walkDirs(store.root, store.walk, (files) => recordIndexFiles(build, store, files));
  }
  return build;
}

function installSessionFileIndex(home: string, built: SessionFileIndexBuild): void {
  sessionFileIndexHome = home;
  sessionFileIndex = built.index;
  codexRolloutIndex = built.codexRollouts;
  sessionFileIndexBuiltAt = Date.now();
  sessionFileKnownMisses.clear();
  codexRolloutKnownMisses.clear();
}

function rebuildSessionFileIndex(): void {
  const home = process.env.HOME || "";
  installSessionFileIndex(home, buildSessionFileIndex(home));
}

// The periodic path. The cold sync build blocked the loop 6s at boot under
// load (LOOP-FREEZE 2026-09-02, collectResourceSnapshot → sessionBorrowsProcess
// → this walk) and again every TTL; the same walk on the libuv pool costs the
// loop nothing, and lookups keep answering from the previous map meanwhile
// (hits are stat-validated, so a stale map is never wrong, only incomplete).
// One refresh in flight at a time; the boot path kicks the first one so the
// first lookup rarely has to build cold.
let sessionFileIndexRefresh: Promise<void> | null = null;
export function refreshSessionFileIndex(): Promise<void> {
  if (sessionFileIndexRefresh) return sessionFileIndexRefresh;
  const home = process.env.HOME || "";
  sessionFileIndexRefresh = buildSessionFileIndexAsync(home)
    .then((built) => {
      // A sync build that ran meanwhile (HOME swap, cold lookup) is at least as
      // fresh as this one only if it is newer than our start; simpler and safe:
      // install unless HOME moved under us.
      if ((process.env.HOME || "") === home) installSessionFileIndex(home, built);
    })
    .catch(() => {})
    .finally(() => { sessionFileIndexRefresh = null; });
  return sessionFileIndexRefresh;
}

/** Resolves once an index for the current HOME exists. Awaiting this before a
 *  lookup is what keeps the lookup's cold rebuild off the loop. */
export function ensureSessionFileIndex(): Promise<void> {
  if (sessionFileIndex && sessionFileIndexHome === (process.env.HOME || "")) return Promise.resolve();
  return refreshSessionFileIndex();
}

/** Test seam: when the index was last built (0 while none exists). */
export function sessionFileIndexBuiltAtForTests(): number {
  return sessionFileIndexBuiltAt;
}

// The shared freshness policy for both index maps: stat-validated hits, one
// throttled rebuild for an unseen miss, misses confirmed by a fresh walk
// remembered until the next rebuild. See the block comment above.
function indexedSessionLookup<T>(
  getMap: () => Map<string, T> | null,
  pathOf: (entry: T) => string,
  knownMisses: Set<string>,
  sessionId: string,
): T | null {
  let rebuiltThisCall = false;
  if (!getMap() || sessionFileIndexHome !== (process.env.HOME || "")) {
    rebuildSessionFileIndex();
    rebuiltThisCall = true;
  } else if (Date.now() - sessionFileIndexBuiltAt > SESSION_FILE_INDEX_TTL_MS) {
    void refreshSessionFileIndex(); // serve the current map; the fresh one lands async
  }
  let hit = getMap()!.get(sessionId);
  if (hit !== undefined && !fs.existsSync(pathOf(hit))) {
    getMap()!.delete(sessionId);
    hit = undefined;
  }
  if (hit === undefined && !knownMisses.has(sessionId)) {
    const missKey = `${getMap() === codexRolloutIndex ? "codex:" : "all:"}${sessionId}`;
    const firstMissedAgainst = sessionFilePendingMisses.get(missKey);
    if (rebuiltThisCall || (firstMissedAgainst !== undefined && firstMissedAgainst < sessionFileIndexBuiltAt)) {
      // Confirmed absent: by the walk this call just did, or by a build that
      // landed after the id first missed. Remembered until the next build.
      knownMisses.add(sessionId);
      sessionFilePendingMisses.delete(missKey);
    } else {
      // An UNSEEN id missing from the index: the file may have been created
      // since the last walk (a fresh session, a repair write). Ask for a fresh
      // build OFF the loop — one per window — and answer null meanwhile; the
      // caller retries and the next call answers from the fresh map. The old
      // sync rebuild here, cleared of its known misses by every install, walked
      // the whole tree every 2s for as long as any session had no transcript:
      // 9 freezes of up to 47s in 8 minutes on a busy disk (2026-09-02).
      if (firstMissedAgainst === undefined) sessionFilePendingMisses.set(missKey, sessionFileIndexBuiltAt);
      if (Date.now() - sessionFileIndexBuiltAt > SESSION_FILE_INDEX_MISS_REBUILD_MS) void refreshSessionFileIndex();
    }
  }
  return hit ?? null;
}

// Per-call ground truth for the window the index can't see. Delivery and
// resume paths routinely query a session id BEFORE its transcript exists (the
// cold-boot injection window), and a confirmed miss is remembered until the
// next rebuild — so without this, a transcript that lands moments after the
// first query would stay invisible for minutes. Creating a top-level session
// file bumps its parent dir's mtime, so statting the store's dirs and probing
// only fresh ones (direct existsSync where the filename is the id) closes the
// window at ~1ms. Nested claude layouts (subagents, workflow runs) are not
// probed: those agents are reached through their parent and tolerate index
// latency.
function probeRecentSessionFiles(sessionId: string): SessionFileInfo | null {
  return timeSyncFs("probeRecentSessionFiles", sessionId, () => probeRecentSessionFilesSync(sessionId));
}
function probeRecentSessionFilesSync(sessionId: string): SessionFileInfo | null {
  const home = process.env.HOME || "";
  const since = sessionFileIndexBuiltAt - 60_000; // clock/mtime slack
  const freshDirs = (parent: string): string[] => {
    const out: string[] = [];
    try {
      for (const e of fs.readdirSync(parent, { withFileTypes: true })) {
        if (!e.isDirectory()) continue;
        const p = path.join(parent, e.name);
        try { if (fs.statSync(p).mtimeMs >= since) out.push(p); } catch {}
      }
    } catch {}
    return out;
  };

  // Store order mirrors the old walk's priority: claude, codex, gemini, pi, grok.
  for (const dir of freshDirs(path.join(home, ".claude", "projects"))) {
    const candidate = path.join(dir, `${sessionId}.jsonl`);
    if (fs.existsSync(candidate)) return { path: candidate, agentType: "claude" };
  }
  const codex = probeRecentCodexRollouts(sessionId);
  if (codex) return { path: codex, agentType: "codex" };
  for (const dir of freshDirs(path.join(home, ".gemini", "tmp"))) {
    const candidate = path.join(dir, "chats", `${sessionId}.json`);
    if (fs.existsSync(candidate)) return { path: candidate, agentType: "gemini" };
  }
  for (const dir of freshDirs(path.join(home, ".pi", "agent", "sessions"))) {
    try {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        if (e.isFile() && e.name.endsWith(".jsonl") && e.name.includes(sessionId)) {
          return { path: path.join(dir, e.name), agentType: "pi" };
        }
      }
    } catch {}
  }
  for (const dir of freshDirs(path.join(home, ".grok", "sessions"))) {
    const candidate = path.join(dir, sessionId, "updates.jsonl");
    if (fs.existsSync(candidate)) return { path: candidate, agentType: "grok" };
  }
  return null;
}

// Two freshness tiers, chosen by the CALLER's tolerance:
// - default: per-call ground truth. A miss runs the recent-changes probe, so a
//   transcript created since the last walk is still found. For delivery,
//   resume/repair, the fork fast path — anywhere acting on "missing" is wrong
//   or destructive.
// - staleOk: index-only. A miss answers null with no further IO. For bulk
//   periodic sweeps (status reconcile, git sweep, agent-type hints) that query
//   hundreds of chronically fileless sessions per tick — per-miss probing there
//   would rebuild the very syscall storm the index removed, and those sweeps
//   re-run anyway, so index-freshness (≤2s for unseen ids via the miss rebuild,
//   ≤TTL otherwise) is enough.
export function findSessionFile(sessionId: string, opts?: { staleOk?: boolean }): SessionFileInfo | null {
  let hit = indexedSessionLookup(() => sessionFileIndex, (e) => e.path, sessionFileKnownMisses, sessionId);
  if (!hit && !opts?.staleOk) {
    hit = probeRecentSessionFiles(sessionId);
    if (hit) {
      sessionFileIndex?.set(sessionId, hit);
      sessionFileKnownMisses.delete(sessionId);
    }
  }
  if (hit) return hit;

  // OpenCode sessions live in the SQLite store (~/.local/share/opencode/opencode.db),
  // not a per-session file, so the "path" is the DB itself and it cannot be
  // enumerated into the index. This lets callers that only need the agent type /
  // a stat resolve opencode; the transcript-tail path reads binary DB bytes and
  // safely defers (classifyOpencodeTranscriptTail returns "unknown" on
  // unparseable input) — opencode status is authoritatively driven from
  // processOpencodeSession, which reads the DB directly.
  if (sessionId.startsWith("ses_") && sessionExistsInOpencodeDb(sessionId)) {
    return { path: opencodeDbPath(), agentType: "opencode" };
  }

  return null;
}

const resumeSessionCache = new Map<string, string>();
// Sessions whose liveness we heartbeat. A single global flush loop batches all
// of these into ONE mutation per tick (flushManagedHeartbeats) instead of one
// mutation per session — so the inbox/plans/tasks subscriptions, which collect
// every managed_sessions row, are invalidated once per flush rather than once
// per session per 30s. See managedSessions:heartbeatBatch.
const managedHeartbeatSessions = new Set<string>();
let heartbeatFlushTimer: NodeJS.Timeout | null = null;
let heartbeatFlushInProgress = false;
let heartbeatMaintenanceInProgress = false;
let heartbeatMaintenanceCount = 0;
let lastHeartbeatSendAt = 0;
const HEARTBEAT_FLUSH_INTERVAL_MS = 30_000;
// Cap the per-transaction slice so a write conflict retries a bounded number of
// rows, not the whole fleet.
const HEARTBEAT_BATCH_SIZE = 25;
const HEALTH_CHECK_EVERY_N_HEARTBEATS = 3;

// Tmux-kill policy: the daemon only tears down a managed tmux session in
// response to an *unambiguous* death signal — the session is no longer listed
// by tmux at all (a `tmux has-session` failure). Passive indicators ("no agent
// process visible in the pane's process tree", "JSONL hasn't been written for
// N minutes", "CPU is near zero") are never enough to justify auto-killing
// a worker. Operators drive repair via the UI's Kill & restart action when
// they see a session looks wedged.

// Heartbeat responses are intentionally ignored. The old "dismissed + idle for
// 1h → kill" auto-reap was removed: dismissal is a UI state, not a worker
// lifecycle signal — a user can dismiss a card and still expect the agent
// running when they return. Workers live until the user explicitly kills them.
// (The batched heartbeat therefore returns only a count, not per-session state.)

// Codex tmux pane monitoring for permission prompts
const codexPermissionPollers = new Map<string, NodeJS.Timeout>();
const codexPermissionPending = new Set<string>(); // sessionIds currently waiting for permission decision
const codexPermissionRunning = new Set<string>(); // sessionIds with an in-flight tmux capture

let codexAppServerInstance: CodexAppServer | null = null;
type AppServerThreadEntry = { threadId: string; conversationId: string; cwd?: string; approvalPolicy?: ApprovalPolicy };
type PersistedAppServerThreadRecord = { threadId: string; updatedAt: number; cwd?: string };
type AppServerStreamingPartial = { itemId: string; content: string };
type AppServerPartialMessage = AppServerStreamingPartial;
type AppServerTurnProgress = {
  threadId: string;
  items: ThreadItem[];
  lastSyncedSignature?: string;
  partials: Map<string, AppServerPartialMessage>;
  partialOrder: string[];
  partialFlushTimer?: ReturnType<typeof setTimeout>;
  syncChain?: Promise<void>;
};
const appServerThreads = new Map<string, AppServerThreadEntry>();
const appServerConversations = new Map<string, string>();
const persistedAppServerThreads = new Map<string, PersistedAppServerThreadRecord>();
const appServerTurnProgress = new Map<string, AppServerTurnProgress>();
const APP_SERVER_THREAD_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const APP_SERVER_DELTA_FLUSH_MS = 500;
let rehydratePersistedAppServerThreadsPromise: Promise<void> | null = null;

export function upsertAppServerThreadRegistration(
  threads: Map<string, AppServerThreadEntry>,
  conversations: Map<string, string>,
  conversationId: string,
  threadId: string,
  extra?: Partial<AppServerThreadEntry>,
): void {
  const existingThreadId = conversations.get(conversationId);
  if (existingThreadId && existingThreadId !== threadId) {
    const existingThreadEntry = threads.get(existingThreadId);
    if (existingThreadEntry?.conversationId === conversationId) {
      threads.delete(existingThreadId);
    }
  }

  const existingConversation = threads.get(threadId)?.conversationId;
  if (existingConversation && existingConversation !== conversationId) {
    conversations.delete(existingConversation);
  }

  threads.set(threadId, { threadId, conversationId, ...extra });
  conversations.set(conversationId, threadId);
}

export function removeAppServerThreadRegistration(
  threads: Map<string, AppServerThreadEntry>,
  conversations: Map<string, string>,
  conversationId: string,
  threadId?: string,
): void {
  const resolvedThreadId = threadId ?? conversations.get(conversationId);
  conversations.delete(conversationId);
  if (!resolvedThreadId) return;
  const existing = threads.get(resolvedThreadId);
  if (existing?.conversationId === conversationId) {
    threads.delete(resolvedThreadId);
  }
}

function findActiveTurnForThread(threadId: string): string | undefined {
  for (const [turnId, progress] of appServerTurnProgress) {
    if (progress.threadId === threadId) return turnId;
  }
  return undefined;
}

/**
 * Tear down EVERY live backend bound to a conversation, regardless of agent type.
 *
 * A conversation must own exactly one backend. A cross-agent reconfigure
 * (Codex <-> Claude, allowed pre-first-message) or a same-agent restart enqueues
 * a fresh start_session. The Codex start registers an app-server thread and
 * returns BEFORE the tmux kill-before-create block, so without this a later
 * Claude start would leave the Codex thread alive alongside the new tmux (and
 * vice-versa) -- a split-brain where two agents answer one conversation, the
 * first user turn is stranded on the loser, and an orphan welcome-screen pane is
 * left behind (ct-33497).
 *
 * Dependencies are injected so this is unit-testable without a real tmux /
 * app-server. Server-side status is intentionally left to callers: kill_session
 * marks the session completed; start_session is about to re-register and claim.
 */
export async function teardownConversationBackends(
  conversationId: string,
  deps: {
    appServerConversations: Map<string, string>;
    appServerThreads: Map<string, AppServerThreadEntry>;
    startedTmux: { get(conversationId: string): { tmuxSession: string } | undefined };
    killTmuxTree: (tmuxSession: string) => Promise<void>;
    deleteStarted: (conversationId: string) => void;
    stopHeartbeat: (sessionId: string) => void;
    forgetPersisted: (conversationId: string) => void;
    isValidTmuxTarget?: (target: string) => boolean;
    interruptActiveTurn?: (threadId: string) => Promise<void>;
    onLog?: (message: string) => void;
  },
): Promise<{ killedAppServer: boolean; killedTmux: boolean; appServerThreadId?: string }> {
  let killedAppServer = false;
  let killedTmux = false;

  // 1. App-server agent (Codex) thread.
  const appServerThreadId = deps.appServerConversations.get(conversationId);
  if (appServerThreadId) {
    if (deps.interruptActiveTurn) {
      try { await deps.interruptActiveTurn(appServerThreadId); } catch {}
    }
    removeAppServerThreadRegistration(deps.appServerThreads, deps.appServerConversations, conversationId, appServerThreadId);
    deps.forgetPersisted(conversationId);
    deps.stopHeartbeat(appServerThreadId);
    killedAppServer = true;
    deps.onLog?.(`[REMOTE] Tore down app-server thread ${appServerThreadId.slice(0, 8)} for conversation ${conversationId.slice(0, 12)}`);
  }

  // 2. tmux-backed agent (Claude/Cursor/Gemini). The registry holds whatever
  //    agent was last started, so this kills a different-typed tmux too.
  const started = deps.startedTmux.get(conversationId);
  if (started && (deps.isValidTmuxTarget ? deps.isValidTmuxTarget(started.tmuxSession) : true)) {
    await deps.killTmuxTree(started.tmuxSession);
    deps.deleteStarted(conversationId);
    killedTmux = true;
    deps.onLog?.(`[REMOTE] Tore down started tmux ${started.tmuxSession} (+process tree) for conversation ${conversationId.slice(0, 12)}`);
  }

  return { killedAppServer, killedTmux, appServerThreadId };
}

/** Bind {@link teardownConversationBackends} to the daemon's live globals. */
function teardownConversationBackendsLive(
  conversationId: string,
  opts: { interruptActiveTurn?: boolean } = {},
): Promise<{ killedAppServer: boolean; killedTmux: boolean; appServerThreadId?: string }> {
  return teardownConversationBackends(conversationId, {
    appServerConversations,
    appServerThreads,
    startedTmux: startedSessionTmux,
    killTmuxTree: killTmuxSessionAndTree,
    deleteStarted: deleteStartedSession,
    stopHeartbeat: stopManagedSessionHeartbeat,
    forgetPersisted: forgetPersistedAppServerConversation,
    isValidTmuxTarget: validateTmuxTarget,
    interruptActiveTurn: opts.interruptActiveTurn
      ? async (threadId: string) => {
          if (!codexAppServerInstance?.running) return;
          const activeTurnId = findActiveTurnForThread(threadId);
          if (activeTurnId) await codexAppServerInstance.turnInterrupt(threadId, activeTurnId);
        }
      : undefined,
    onLog: log,
  });
}

/**
 * Stop EVERY local backend for a session so nothing keeps running on this
 * machine: the started tmux + app-server thread (teardownConversationBackendsLive),
 * the live process tree, the auto-resume tmux (resumeSessionCache), any zombie
 * cc-resume tmux still matching the session id, and the per-session heartbeat +
 * caches. Best-effort and idempotent. Shared by kill_session and move_to_device:
 * an auto-resumed copy lives in resumeSessionCache (a `cc-resume-*` tmux), which
 * teardownConversationBackendsLive alone does NOT reap — leaving it alive after a
 * move is exactly the split-brain where the local machine keeps answering.
 */
async function stopLocalSessionBackends(conversationId: string, sessionId: string | undefined): Promise<void> {
  await teardownConversationBackendsLive(conversationId, { interruptActiveTurn: true }).catch(() => {});
  if (!sessionId) return;
  // Same borrowed-pid hazard as killConversationBackends, and the same TWO unsafe
  // actions: reaping the resolved pid tree, and killing the tmux in
  // resumeSessionCache. Both can belong to the PARENT — the cache is keyed by
  // session id, but resolveLiveTmuxTarget fills it by resolving a subagent through
  // the borrowed pid to the parent's PANE, so the value is the parent's tmux name.
  // The session id being ours says nothing about who owns what it points at.
  // This is what keeps move_to_device / release_session from stranding a user's
  // running parent TUI. The tmux-name sweep further down is genuinely safe
  // unguarded: it matches names derived from THIS session's id, which a parent's
  // tmux never carries.
  const teardownPlan = planSessionTeardown(sessionProcessOwnership(sessionId));
  try {
    if (teardownPlan.reapPidTree) {
      const proc = await findSessionProcess(sessionId, detectSessionAgentType(sessionId));
      if (proc) {
        const tmuxTarget = await findTmuxPaneForTty(proc.tty);
        if (tmuxTarget && validateTmuxTarget(tmuxTarget)) {
          await killTmuxSessionAndTree(tmuxTarget.split(":")[0]).catch(() => {});
        }
        await reapPidTree(proc.pid).catch(() => 0);
      }
    }
  } catch { /* best-effort */ }
  const cachedTmux = resumeSessionCache.get(sessionId);
  if (cachedTmux && validateTmuxTarget(cachedTmux)) {
    if (teardownPlan.killCachedResumeTmux) {
      await killTmuxSessionAndTree(cachedTmux).catch(() => {});
    } else {
      log(`Dropped cached resume tmux ${cachedTmux} for ${shortId(sessionId)} without killing it (session does not own that pane)`);
    }
    resumeSessionCache.delete(sessionId);
  }
  stopManagedSessionHeartbeat(sessionId);
  stopCodexPermissionPoller(sessionId);
  sessionProcessCache.delete(sessionId);
  resumeInFlight.delete(sessionId);
  resumeInFlightStarted.delete(sessionId);
  try {
    const { stdout: tmuxList } = await tmuxExec(["list-sessions", "-F", "#{session_name}"]);
    for (const tmuxName of tmuxList.trim().split("\n")) {
      if (!tmuxName || !(await tmuxSessionMatchesFullSessionId(tmuxName, sessionId))) continue;
      if (!validateTmuxTarget(tmuxName)) continue;
      await killTmuxSessionAndTree(tmuxName).catch(() => {});
    }
  } catch { /* best-effort */ }
}

function makeAppServerTurnProgress(threadId: string): AppServerTurnProgress {
  return {
    threadId,
    items: [],
    partials: new Map(),
    partialOrder: [],
  };
}

function clearAppServerTurnProgress(turnId: string): void {
  const progress = appServerTurnProgress.get(turnId);
  if (progress?.partialFlushTimer) {
    clearTimeout(progress.partialFlushTimer);
  }
  appServerTurnProgress.delete(turnId);
}

function clearLiveAppServerThreadRegistrations(): void {
  appServerThreads.clear();
  appServerConversations.clear();
  for (const turnId of appServerTurnProgress.keys()) {
    clearAppServerTurnProgress(turnId);
  }
}

function buildAppServerProgressSignature(messages: RawMessage[]): string {
  return JSON.stringify(messages.map((message) => ({
    uuid: message.uuid,
    role: message.role,
    content: message.content,
    thinking: message.thinking,
    toolCalls: message.toolCalls,
    toolResults: message.toolResults,
    images: message.images,
    subtype: message.subtype,
  })));
}

export function buildAppServerStreamingTailMessages(
  completedItems: ThreadItem[],
  partials: AppServerStreamingPartial[],
): RawMessage[] {
  const items: ThreadItem[] = [...completedItems];
  for (const partial of partials) {
    items.push({
      type: "agentMessage",
      id: partial.itemId,
      text: partial.content,
      phase: null,
    });
  }
  const messages = threadItemsToMessages(items) as RawMessage[];
  const tail = messages[messages.length - 1];
  if (!tail) return [];
  if (
    tail.role === "assistant" &&
    !tail.content.trim() &&
    !tail.thinking?.trim() &&
    !tail.images?.length &&
    !tail.toolCalls &&
    !tail.toolResults
  ) {
    return [];
  }
  return [tail];
}

function rememberAppServerPartialStart(progress: AppServerTurnProgress, item: ThreadItem): void {
  if (item.type !== "agentMessage") return;
  const existing = progress.partials.get(item.id);
  if (!existing) {
    progress.partialOrder.push(item.id);
  }
  progress.partials.set(item.id, {
    itemId: item.id,
    content: existing?.content ?? item.text ?? "",
  });
}

function appendAppServerPartialDelta(progress: AppServerTurnProgress, itemId: string, delta: string): void {
  if (!delta) return;
  const existing = progress.partials.get(itemId);
  if (!existing) {
    progress.partialOrder.push(itemId);
  }
  progress.partials.set(itemId, {
    itemId,
    content: (existing?.content ?? "") + delta,
  });
}

function removeAppServerPartial(progress: AppServerTurnProgress, itemId: string): void {
  if (!progress.partials.delete(itemId)) return;
  progress.partialOrder = progress.partialOrder.filter((id) => id !== itemId);
  if (progress.partials.size === 0 && progress.partialFlushTimer) {
    clearTimeout(progress.partialFlushTimer);
    progress.partialFlushTimer = undefined;
  }
}

function buildAppServerPartialMessages(progress: AppServerTurnProgress): RawMessage[] {
  const partials: AppServerStreamingPartial[] = [];
  for (const itemId of progress.partialOrder) {
    const partial = progress.partials.get(itemId);
    if (!partial) continue;
    partials.push(partial);
  }
  return buildAppServerStreamingTailMessages(progress.items, partials);
}

function scheduleAppServerPartialSync(
  turnId: string,
  conversationId: string,
  syncService: SyncService,
  retryQueue: RetryQueue,
  threadIdForLog: string,
): void {
  const progress = appServerTurnProgress.get(turnId);
  if (!progress || progress.partialFlushTimer) return;
  progress.partialFlushTimer = setTimeout(() => {
    const current = appServerTurnProgress.get(turnId);
    if (current) current.partialFlushTimer = undefined;
    flushAppServerPartialSync(turnId, conversationId, syncService, retryQueue, threadIdForLog).catch((err) => {
      log(`[codex-app-server] delta sync failed for thread ${threadIdForLog}: ${err instanceof Error ? err.message : String(err)}`);
    });
  }, APP_SERVER_DELTA_FLUSH_MS);
}

async function flushAppServerPartialSync(
  turnId: string,
  conversationId: string,
  syncService: SyncService,
  retryQueue: RetryQueue,
  threadIdForLog: string,
): Promise<void> {
  const progress = appServerTurnProgress.get(turnId);
  if (!progress) return;
  if (progress.partialFlushTimer) {
    clearTimeout(progress.partialFlushTimer);
    progress.partialFlushTimer = undefined;
  }
  const messages = buildAppServerPartialMessages(progress);
  if (messages.length === 0) return;
  await syncAppServerTurnMessagesIfChanged(turnId, conversationId, messages, syncService, retryQueue, threadIdForLog);
}

async function syncAppServerTurnMessagesIfChanged(
  turnId: string,
  conversationId: string,
  messages: RawMessage[],
  syncService: SyncService,
  retryQueue: RetryQueue,
  threadIdForLog: string,
): Promise<void> {
  if (messages.length === 0) return;
  const progress = appServerTurnProgress.get(turnId);
  if (!progress) return;
  const previous = progress.syncChain ?? Promise.resolve();
  const run = previous.catch(() => {}).then(async () => {
    const current = appServerTurnProgress.get(turnId);
    if (!current) return;
    const signature = buildAppServerProgressSignature(messages);
    if (current.lastSyncedSignature === signature) return;
    const batchResult = await syncMessagesBatch(messages, conversationId, syncService, retryQueue);
    if (!batchResult.authExpired && !batchResult.conversationNotFound) {
      current.lastSyncedSignature = signature;
      syncStats.messagesSynced += messages.length;
      syncStats.sessionsActive.add(threadIdForLog);
      log(`[codex-app-server] live synced ${messages.length} messages for thread ${threadIdForLog}`);
    }
  });
  const marker = run.then(() => undefined, () => undefined);
  progress.syncChain = marker;
  try {
    await run;
  } finally {
    if (progress.syncChain === marker) {
      progress.syncChain = undefined;
    }
  }
}

function persistAppServerThreadRegistrations(): void {
  try {
    const data: Record<string, PersistedAppServerThreadRecord> = {};
    const now = Date.now();
    for (const [conversationId, record] of persistedAppServerThreads) {
      if (now - record.updatedAt < APP_SERVER_THREAD_TTL_MS) {
        data[conversationId] = record;
      }
    }
    fs.writeFileSync(APP_SERVER_THREADS_FILE, JSON.stringify(data), "utf-8");
  } catch {}
}

function registerAppServerConversation(
  conversationId: string,
  threadId: string,
  opts: {
    cwd?: string;
    updatedAt?: number;
    persist?: boolean;
    approvalPolicy?: ApprovalPolicy;
  } = {},
): void {
  const updatedAt = opts.updatedAt ?? Date.now();
  const existingThreadId = appServerConversations.get(conversationId);
  const existingConversation = appServerThreads.get(threadId)?.conversationId;
  upsertAppServerThreadRegistration(appServerThreads, appServerConversations, conversationId, threadId, { cwd: opts.cwd, approvalPolicy: opts.approvalPolicy });
  if (!opts.persist) return;
  if (existingConversation && existingConversation !== conversationId) {
    persistedAppServerThreads.delete(existingConversation);
  }
  persistedAppServerThreads.set(conversationId, { threadId, updatedAt, cwd: opts.cwd });
  if (existingThreadId && existingThreadId !== threadId) {
    persistedAppServerThreads.delete(conversationId);
  }
  persistAppServerThreadRegistrations();
}

function forgetPersistedAppServerConversation(conversationId: string): void {
  if (!persistedAppServerThreads.delete(conversationId)) return;
  persistAppServerThreadRegistrations();
}

function markAppServerConversationResumable(
  conversationId: string,
  threadId?: string,
  updatedAt: number = Date.now(),
): void {
  const resolvedThreadId = threadId ?? appServerConversations.get(conversationId);
  if (!resolvedThreadId) return;
  const liveEntry = appServerThreads.get(resolvedThreadId);
  persistedAppServerThreads.set(conversationId, {
    threadId: resolvedThreadId,
    updatedAt,
    cwd: liveEntry?.cwd,
  });
  persistAppServerThreadRegistrations();
}

async function rehydratePersistedAppServerThreads(): Promise<void> {
  if (!codexAppServerInstance?.running || persistedAppServerThreads.size === 0) return;

  const entries = [...persistedAppServerThreads.entries()];
  let resumed = 0;
  let dropped = 0;

  for (const [conversationId, record] of entries) {
    if (appServerConversations.has(conversationId)) continue;
    try {
      await codexAppServerInstance.threadResume({
        threadId: record.threadId,
        ...(record.cwd ? { cwd: record.cwd } : {}),
      });
      const rehydratedPolicy = resolveCodexApprovalPolicy(activeConfig);
      registerAppServerConversation(conversationId, record.threadId, {
        cwd: record.cwd,
        updatedAt: record.updatedAt,
        persist: false,
        approvalPolicy: rehydratedPolicy,
      });
      ensureManagedSessionHeartbeat(record.threadId);
      resumed++;
    } catch (err) {
      dropped++;
      persistedAppServerThreads.delete(conversationId);
      log(`[codex-app-server] dropping persisted thread ${record.threadId.slice(0, 8)} for conv=${conversationId.slice(0, 12)}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  if (dropped > 0) {
    persistAppServerThreadRegistrations();
  }
  if (resumed > 0 || dropped > 0) {
    log(`[codex-app-server] rehydrated ${resumed} persisted thread(s), dropped ${dropped}`);
  }
}

function loadPersistedAppServerThreadRegistrations(): void {
  try {
    if (!fs.existsSync(APP_SERVER_THREADS_FILE)) return;
    const raw = JSON.parse(fs.readFileSync(APP_SERVER_THREADS_FILE, "utf-8")) as Record<string, { threadId: string; updatedAt?: number; cwd?: string }>;
    const now = Date.now();
    let loaded = 0;
    for (const [conversationId, record] of Object.entries(raw)) {
      if (!record?.threadId) continue;
      const updatedAt = record.updatedAt ?? now;
      if (now - updatedAt >= APP_SERVER_THREAD_TTL_MS) continue;
      persistedAppServerThreads.set(conversationId, {
        threadId: record.threadId,
        updatedAt,
        cwd: record.cwd,
      });
      loaded++;
    }
    if (loaded > 0) {
      log(`Loaded ${loaded} app-server thread registration(s) from disk`);
    }
  } catch {}
}

const CODEX_PERMISSION_PATTERNS = [
  /Would you like to run the following command\?/,
  /Press enter to confirm or esc to cancel/,
  /Do you want to proceed\?/,
];

function detectCodexPermissionFromPane(paneContent: string): { reason: string; command: string } | null {
  if (!CODEX_PERMISSION_PATTERNS.some(p => p.test(paneContent))) return null;

  let reason = "";
  let command = "";
  const lines = paneContent.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.includes("Reason:")) {
      reason = line.replace(/.*Reason:\s*/, "").trim();
    }
    if (line.startsWith("$ ")) {
      command = line.slice(2).trim();
      // Collect continuation lines (long commands wrap)
      for (let j = i + 1; j < lines.length && j < i + 5; j++) {
        const next = lines[j].trim();
        if (next && !next.startsWith("1.") && !next.startsWith("2.") && !next.startsWith("3.") && !next.startsWith("Press ")) {
          command += " " + next;
        } else break;
      }
    }
  }

  return { reason: reason || "Command approval requested", command: command.slice(0, 300) };
}

function startCodexPermissionPoller(sessionId: string, tmuxSession: string, conversationId: string, syncService: SyncService): void {
  if (codexPermissionPollers.has(sessionId)) return;

  const interval = setInterval(async () => {
    if (codexPermissionPending.has(sessionId)) return;
    if (codexPermissionRunning.has(sessionId)) return;
    if (isInWakeGrace()) return;

    codexPermissionRunning.add(sessionId);
    try {
      const { stdout: paneContent } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmuxSession, "-S", "-30"], { timeout: 3000, killSignal: "SIGKILL" });
      const prompt = detectCodexPermissionFromPane(paneContent);
      if (!prompt) return;

      codexPermissionPending.add(sessionId);
      log(`Codex permission prompt detected in tmux for session ${sessionId.slice(0, 8)}: ${prompt.reason.slice(0, 100)}`);

      sendAgentStatus(syncService, conversationId, sessionId, "permission_blocked");

      const preview = truncateForNotification(
        `${prompt.command || prompt.reason}`, 200
      );
      syncService.createSessionNotification({
        conversation_id: conversationId,
        type: "permission_request",
        title: "codecast - Permission needed",
        message: preview,
      }).catch(() => {});

      const permissionPrompt = {
        tool_name: "exec_command",
        arguments_preview: prompt.command || prompt.reason,
      };

      handlePermissionRequest(syncService, conversationId, sessionId, permissionPrompt, log)
        .then(async (decision) => {
          if (decision) {
            const key = decision.approved ? "Enter" : "Escape";
            log(`Injecting Codex permission '${key}' for session ${sessionId.slice(0, 8)}`);
            try {
              await tmuxExec(["send-keys", "-t", tmuxSession, key]);
            } catch (err) {
              log(`Failed to inject Codex permission key: ${err instanceof Error ? err.message : String(err)}`);
            }
          }
          sendAgentStatus(syncService, conversationId, sessionId, "working");
          codexPermissionPending.delete(sessionId);
        })
        .catch((err) => {
          log(`Codex permission handling error: ${err instanceof Error ? err.message : String(err)}`);
          codexPermissionPending.delete(sessionId);
        });
    } catch {
      // tmux session may have ended
    } finally {
      codexPermissionRunning.delete(sessionId);
    }
  }, 3000);

  codexPermissionPollers.set(sessionId, interval);
  log(`Started Codex permission poller for session ${sessionId.slice(0, 8)} on tmux ${tmuxSession}`);
}

function stopCodexPermissionPoller(sessionId: string): void {
  const interval = codexPermissionPollers.get(sessionId);
  if (interval) {
    clearInterval(interval);
    codexPermissionPollers.delete(sessionId);
    codexPermissionPending.delete(sessionId);
  }
}

type StartedSessionInfo = {
  tmuxSession: string;
  projectPath: string;
  startedAt: number;
  agentType: AgentClientId;
  sessionId?: string;
  worktreeName?: string;
  worktreeBranch?: string;
  worktreePath?: string;
};

const STARTED_SESSION_TTL_MS = 24 * 60 * 60 * 1000;

class PersistedStartedSessions extends Map<string, StartedSessionInfo> {
  constructor() {
    super();
    this.load();
  }

  set(key: string, value: StartedSessionInfo): this {
    super.set(key, value);
    this.save();
    return this;
  }

  delete(key: string): boolean {
    const result = super.delete(key);
    if (result) this.save();
    return result;
  }

  private save(): void {
    try {
      const data: Record<string, StartedSessionInfo> = {};
      const now = Date.now();
      for (const [k, v] of this) {
        if (now - v.startedAt < STARTED_SESSION_TTL_MS) data[k] = v;
      }
      fs.writeFileSync(STARTED_SESSIONS_FILE, JSON.stringify(data), "utf-8");
    } catch {}
  }

  private load(): void {
    try {
      if (!fs.existsSync(STARTED_SESSIONS_FILE)) return;
      const raw = JSON.parse(fs.readFileSync(STARTED_SESSIONS_FILE, "utf-8"));
      const now = Date.now();
      for (const [k, v] of Object.entries(raw) as [string, StartedSessionInfo][]) {
        if (now - v.startedAt < STARTED_SESSION_TTL_MS) {
          super.set(k, v);
        }
      }
      if (this.size > 0) {
        log(`Loaded ${this.size} started session(s) from disk`);
      }
    } catch {}
  }
}

loadPersistedAppServerThreadRegistrations();
const startedSessionTmux = new PersistedStartedSessions();
const restartingSessionIds = new Map<string, number>();
const RESTART_GUARD_TTL_MS = 60_000;

/** The largest window resumeReadinessPollMs can return. */
export const MAX_RESUME_READINESS_POLL_MS = 120_000;

// Prevent concurrent resume attempts on the same session
const resumeInFlight = new Map<string, Promise<boolean>>();
const resumeInFlightStarted = new Map<string, number>();
// Must stay STRICTLY LARGER than the longest a single resume can legitimately
// take, or the guard expires under a healthy resume and admits a second one into
// the SAME tmux name — observed live on jx78ksdh85pw: the first resume ran 128s
// (see resumeReadinessPollMs), the 120s guard called it stale, and the second
// attempt died on `duplicate session: cc-resume-c731de13` after typing a second
// `claude --resume` line into the pane the first was still booting. Derived from
// the readiness ceiling plus setup (kill, new-session, JSONL relocate, model
// scan) so raising a tier can never silently re-open that window.
export const RESUME_IN_FLIGHT_TIMEOUT_MS = MAX_RESUME_READINESS_POLL_MS + 60_000;

// How long to wait for a cold-resumed agent to render its prompt before giving up.
// A `claude --resume` replays the whole transcript on boot, so the window scales
// with JSONL size. The floor was 15s, which was too tight for a from-scratch
// (reconstituted) session — the boot would still be initializing when the poll
// gave up, and the optimistic inject pasted into a half-booted/dead shell. 30s
// floor gives a normal cold boot room to finish.
//
// The 500KB step exists because the old 1MB boundary put an 880KB transcript in
// the 30s tier while Claude needed 38-71s to render its prompt for it — so every
// restart of that session reported a timeout even when the boot was fine.
export function resumeReadinessPollMs(jsonlSizeBytes: number): number {
  if (jsonlSizeBytes > 10_000_000) return 120_000;
  if (jsonlSizeBytes > 1_000_000) return 90_000;
  if (jsonlSizeBytes > 500_000) return 60_000;
  return 30_000;
}

// ---- Tier 3: warm pool selection (pure policy, unit-tested) ----
// Only an ACTIVE recent session whose agent has DIED is a warm candidate. The
// recency window is deliberately short and mirrors the watchdog's idle-stale cutoff:
// once a session has been idle long enough to be marked completed it is no longer
// "hot", and re-warming it would resurrect work the user (or the agent) finished.
// Circuit-broken and fatally-failed sessions are excluded so we never pile resume
// attempts onto something that's already failing.
export const WARM_POOL_ACTIVE_STATUSES = new Set(["idle", "working", "thinking", "connected"]);

export interface WarmCandidate {
  sessionId: string;
  status: string;      // last hook status for the session
  tsMs: number;        // when that status was observed (ms epoch)
  agentAlive: boolean; // is a live agent already attached?
  circuitOpen: boolean;
  fatal: boolean;
}

export function selectSessionsToWarm(
  candidates: WarmCandidate[],
  nowMs: number,
  opts: { recencyWindowMs: number; cap: number },
): string[] {
  if (opts.cap <= 0) return [];
  return candidates
    .filter(c => WARM_POOL_ACTIVE_STATUSES.has(c.status))
    .filter(c => nowMs - c.tsMs <= opts.recencyWindowMs)
    .filter(c => !c.agentAlive)   // already warm — nothing to do
    .filter(c => !c.circuitOpen)  // already failing — don't pile on
    .filter(c => !c.fatal)        // unrecoverable — don't try
    .sort((a, b) => b.tsMs - a.tsMs) // most-recently-active first
    .slice(0, opts.cap)
    .map(c => c.sessionId);
}

type ResumeFatalReason = "missing_conversation" | "session_not_found" | "invalid_session_id";
const resumeFatalReasons = new Map<string, ResumeFatalReason>();
const conversationResumeFailures = new Map<string, { count: number; lastFailure: number }>();
const CONVERSATION_RESUME_MAX_FAILURES = 3;
const CONVERSATION_RESUME_COOLDOWN_MS = 5 * 60 * 1000; // 5 min cooldown after max failures

// The circuit breaker is reason-aware. A FATAL failure (no conversation, retired
// model, session JSONL truly gone) means "stop trying for a while" — the long
// cooldown. A TRANSIENT failure (a resume we just launched died, a slow/raced
// boot, a one-off SESSION_EXITED during inject) means "back off briefly, then
// retry" — a short cooldown. Treating both the same is what turned a single
// recoverable cold-boot into a 5-minute dead session: 3 quick transient give-ups
// tripped the 300s breaker even though the identical resume succeeded moments
// later. The cooldown is set by the MOST RECENT failure's severity.
const sessionDeliveryFailures = new Map<string, { count: number; lastFailure: number; cooldownMs: number }>();
const SESSION_CIRCUIT_BREAKER_THRESHOLD = 3;
const SESSION_CIRCUIT_BREAKER_COOLDOWN_MS = 300_000; // 5 minutes — fatal failures
const SESSION_CIRCUIT_BREAKER_TRANSIENT_COOLDOWN_MS = 15_000; // 15s — transient (slow/raced boot)

export function isSessionCircuitOpen(sessionId: string): boolean {
  const entry = sessionDeliveryFailures.get(sessionId);
  if (!entry) return false;
  if (entry.count >= SESSION_CIRCUIT_BREAKER_THRESHOLD) {
    if (Date.now() - entry.lastFailure < entry.cooldownMs) return true;
    sessionDeliveryFailures.delete(sessionId);
  }
  return false;
}

export function recordSessionDeliveryFailure(sessionId: string, opts?: { transient?: boolean }): void {
  const prev = sessionDeliveryFailures.get(sessionId);
  const cooldownMs = opts?.transient
    ? SESSION_CIRCUIT_BREAKER_TRANSIENT_COOLDOWN_MS
    : SESSION_CIRCUIT_BREAKER_COOLDOWN_MS;
  sessionDeliveryFailures.set(sessionId, {
    count: (prev?.count ?? 0) + 1,
    lastFailure: Date.now(),
    cooldownMs,
  });
}

export function resetSessionDeliveryFailures(sessionId: string): void {
  sessionDeliveryFailures.delete(sessionId);
}

const UUID_JSONL_RE = /^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.jsonl$/;

export function classifyClaudeResumeFatalReason(paneContent: string): ResumeFatalReason | null {
  if (/No conversation found with session ID:/i.test(paneContent)) return "missing_conversation";
  if (/Session not found/i.test(paneContent)) return "session_not_found";
  return null;
}

export function shouldMaterializeFreshClaudeSession(reason: ResumeFatalReason | null | undefined): boolean {
  return reason === "missing_conversation" || reason === "session_not_found";
}

export function shouldStartBlankSessionAfterResumeFailure(reason: ResumeFatalReason | null | undefined): boolean {
  return !shouldMaterializeFreshClaudeSession(reason);
}

function stopManagedSessionHeartbeat(sessionId: string | undefined): void {
  if (!sessionId) return;
  managedHeartbeatSessions.delete(sessionId);
}

function ensureManagedSessionHeartbeat(sessionId: string): void {
  if (!syncServiceRef) return;
  managedHeartbeatSessions.add(sessionId);
  ensureHeartbeatFlushLoop();
}

function ensureHeartbeatFlushLoop(): void {
  if (heartbeatFlushTimer || !syncServiceRef) return;
  heartbeatFlushTimer = setInterval(() => { void flushManagedHeartbeats(); }, HEARTBEAT_FLUSH_INTERVAL_MS);
}

// Run an async op over items with bounded concurrency (a small worker pool), so
// a fleet-wide pass doesn't fire N tmux/network calls at once.
// One item's failure is logged and the pool moves on: a fleet pass must not
// stop at its first bad session.
async function runBounded<T>(items: T[], concurrency: number, fn: (item: T) => Promise<void>, label = "bounded worker"): Promise<void> {
  let idx = 0;
  const describe = (item: T): string => (typeof item === "string" ? item : JSON.stringify(item)?.slice(0, 200) ?? String(item));
  const worker = async () => {
    while (idx < items.length) {
      const item = items[idx++];
      try {
        await fn(item);
      } catch (err) {
        log(`${label} failed for ${describe(item)}: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(concurrency, items.length) }, worker));
}

// Deterministically place a session in one of `mod` buckets — used to spread the
// per-session health check across flush ticks instead of running the whole fleet
// on one tick.
export function heartbeatHealthCheckBucket(sessionId: string, mod: number): number {
  let h = 0;
  for (let i = 0; i < sessionId.length; i++) h = (h * 31 + sessionId.charCodeAt(i)) >>> 0;
  return h % mod;
}

// One flush per HEARTBEAT_FLUSH_INTERVAL_MS for the WHOLE fleet: collapses N
// per-session heartbeat transactions into ⌈N/25⌉ batched ones, so the inbox
// subscription recomputes ~once per flush instead of ~once per session.
async function flushManagedHeartbeats(): Promise<void> {
  if (!syncServiceRef || managedHeartbeatSessions.size === 0) return;
  // The liveness send and the maintenance pass are guarded SEPARATELY. The send
  // is a couple of batched mutations and must land every tick: the server
  // coerces a session's active status to "stopped" once last_heartbeat ages
  // past the 90s liveness window, so a starved send re-files the entire working
  // fleet under needs-input. Maintenance (tmux health checks, the orphan
  // reaper, the WIP snapshot sweep) legitimately runs for minutes under load —
  // one shared guard let a single long pass swallow every send in between
  // (observed: 11-minute heartbeat gaps while a 92-session WIP sweep ran,
  // 2026-07-20).
  if (!heartbeatFlushInProgress) {
    heartbeatFlushInProgress = true;
    try {
      await runHeartbeatFlush();
    } finally {
      heartbeatFlushInProgress = false;
    }
  }
  // Fire-and-forget: a maintenance pass must never delay the next send. Its own
  // guard skips ticks while the prior pass is still in flight so passes don't
  // pile up; the next tick resumes the cadence.
  if (!heartbeatMaintenanceInProgress) {
    heartbeatMaintenanceInProgress = true;
    void runHeartbeatMaintenance()
      .catch(() => {})
      .finally(() => { heartbeatMaintenanceInProgress = false; });
  }
}

async function runHeartbeatFlush(): Promise<void> {
  // Capture once so the non-null narrowing holds across the awaits below
  // (a module-level `let` would re-widen to `SyncService | null` after each).
  const sync = syncServiceRef;
  if (!sync) return;
  const ids = [...managedHeartbeatSessions];
  const now = Date.now();

  // Cadence sentinel: sends past 2x the interval mean something starved the
  // send path (an event-loop block, a guard regression) and the server is about
  // to distrust the fleet's active statuses — make it loud in the log.
  if (lastHeartbeatSendAt && now - lastHeartbeatSendAt > HEARTBEAT_FLUSH_INTERVAL_MS * 2) {
    log(`[HEARTBEAT-FLUSH] WARNING: ${Math.round((now - lastHeartbeatSendAt) / 1000)}s since last send (interval ${HEARTBEAT_FLUSH_INTERVAL_MS / 1000}s) — liveness sends are being starved`);
  }
  lastHeartbeatSendAt = now;

  // Batched liveness write. logHeartbeatStatus stays per-session (throttled,
  // local-only). Resource metrics are pushed separately by collectResourceSnapshot.
  const payload = ids.map((sessionId) => {
    const status = lastSentAgentStatus.get(sessionId);
    logHeartbeatStatus(sessionId, status);
    return status
      ? { session_id: sessionId, agent_status: status, client_ts: now }
      : { session_id: sessionId };
  });
  const batchCount = Math.ceil(payload.length / HEARTBEAT_BATCH_SIZE);
  for (let i = 0; i < payload.length; i += HEARTBEAT_BATCH_SIZE) {
    try {
      await sync.heartbeatManagedSessionsBatch(payload.slice(i, i + HEARTBEAT_BATCH_SIZE));
    } catch {}
  }
  // One line/tick to confirm the fleet flushes in a handful of transactions
  // (each = one inbox invalidation) rather than ~N. Pre-batch this was N/30s.
  log(`[HEARTBEAT-FLUSH] sessions=${ids.length} batches=${batchCount}`);
}

// The slow fleet-hygiene half of the heartbeat tick — everything that may block
// for minutes and therefore must never share a guard with the liveness send.
async function runHeartbeatMaintenance(): Promise<void> {
  const sync = syncServiceRef;
  if (!sync) return;
  const ids = [...managedHeartbeatSessions];
  const tick = heartbeatMaintenanceCount++;

  // Self-heal pass (local): reconcile a status latched on a lost hook transition
  // against the transcript/pane. Sharded by session so only ~1/N of the fleet
  // runs each tick (every session every N ticks ≈ 90s), and bounded so the tmux
  // captures stay gentle. heartbeatHealthCheck also reconstitutes a session whose
  // tmux has vanished.
  const phase = tick % HEALTH_CHECK_EVERY_N_HEARTBEATS;
  const due = ids.filter((id) => heartbeatHealthCheckBucket(id, HEALTH_CHECK_EVERY_N_HEARTBEATS) === phase);
  // Bounded, not serial: each reconcile may await a transcript prime after a
  // restart, and the health checks below wait for all of them.
  await runBounded(due, 4, (sessionId) => reconcileStatusFromTranscript(sessionId, sync).catch(() => {}));
  await runBounded(due, 5, (sessionId) => heartbeatHealthCheck(sessionId).catch(() => {}));

  // Conservative reap of long-idle orphan terminals — gentle (capped per pass)
  // and logged to a dedicated reaper.log. See reapIdleOrphanTerminals.
  if (tick % REAP_EVERY_N_FLUSHES === 0) {
    await reapIdleOrphanTerminals().catch((e) => log(`[REAPER] pass error: ${(e as Error)?.message ?? e}`));
  }

  // Keep each session's working tree recoverable from another machine. See
  // sweepWipSnapshots.
  if (tick % WIP_SNAPSHOT_EVERY_N_FLUSHES === 0) {
    await sweepWipSnapshots(ids).catch((e) => log(`[WIP] pass error: ${(e as Error)?.message ?? e}`));
  }

  // Keep every repo's origin real, fetched, and measured; un-retires wip pushes
  // when a repaired remote makes them possible again. See sweepGitPlaneFleet.
  // Runs right after the wip sweep on its own cadence so a repair this tick is
  // already usable by the next wip pass. Fetch frequency is gated inside the
  // engine (per-repo interval), so this cadence only bounds repair latency.
  if (tick % GIT_PLANE_EVERY_N_FLUSHES === 0) {
    await sweepGitPlaneFleet(ids).catch((e) => log(`[GITPLANE] pass error: ${(e as Error)?.message ?? e}`));
  }
}

// ─── Working-tree snapshots ────────────────────────────────────────────────
// A session reparented onto another machine gets a plain `git clone` of its
// remote, so it lands on the DEFAULT branch holding only PUSHED work — the
// agent's uncommitted edits, untracked files and unpushed commits stay behind
// (ct-38955, ct-38956). The destination cannot fetch what was never published,
// and it cannot ask this machine for it: a reparent is driven entirely from the
// destination, and the source may be a closed laptop by then.
//
// So the source publishes continuously instead. Each pass captures the tree as a
// dangling commit and force-pushes it to a hidden ref (see wipSnapshot.ts —
// non-destructive, secrets excluded by .gitignore, never touches a real branch).
// The work is then already on the remote when a pull happens, which is what lets
// the whole flow work with the source offline.
//
// Gentle by construction, because this runs for every managed session forever:
//   - the tree hash gates the push, so an unchanged tree costs one local
//     commit-tree and NO network. A session between turns is the common case.
//   - passes are ~5min apart and bounded to a few concurrent snapshots.
//   - every git call is async; a sync exec here would block the daemon's loop
//     past the watchdog's stale-heartbeat threshold on a large repo.
const WIP_SNAPSHOT_EVERY_N_FLUSHES = 10; // ~5 min (flush = 30s), same cadence as the reaper
const GIT_PLANE_EVERY_N_FLUSHES = 10; // ~5 min repair latency; fetches self-gate to ~10 min per repo
const WIP_SNAPSHOT_CONCURRENCY = 3;
// PUSHES per pass, not sessions per pass. Every eligible session is snapshotted
// every pass (local and cheap), and the tree hash gates the network — so steady
// state is ~0 pushes no matter how large the fleet. The herd only exists on the
// first pass after a restart, when the hash map is empty and everything looks
// new (observed: 44 pushes in one tick); this drains that backlog over a few
// passes. Capping SESSIONS instead was wrong and shipped-then-fixed here: with
// more sessions than the cap, each got a turn only every Nth pass, its cached
// hash was always stale, so every pass pushed a full batch and no snapshot was
// ever fresh.
// Approximate, not exact: the counter is checked inside a concurrent map, so up
// to CONCURRENCY-1 extra can slip through. That's fine — it bounds the herd, it
// isn't a quota. Measured drain on a 46-session machine: pushed=10/unchanged=0,
// then 9/10, 10/19, 10/29 as the hash cache fills — i.e. it converges to ~0
// pushes and stays silent until real work happens.
const WIP_SNAPSHOT_MAX_PUSHES_PER_PASS = 8;
/** checkout path -> last tree hash we pushed. Skips the network when nothing
 * changed. Keyed by CHECKOUT, not session: the tree belongs to the repo, and
 * keying it per session meant one agent's edit invalidated every sibling's entry
 * at once, so the throttle never engaged. */
const lastPushedWipTree = new Map<string, string>();
/** checkout path -> why we stopped trying. A repo the user can read but not push
 * (a cloned public repo, revoked access) never becomes pushable by waiting, so one
 * permanent failure retires it rather than failing every pass forever. */
const wipSnapshotGivenUp = new Map<string, string>();
/** Round-robin cursor so every session gets a turn under MAX_PER_PASS. */
let wipSweepCursor = 0;

/** transcript path -> the cwd recorded in its head. A session's cwd is written
 * at session start and never changes, so this is extracted once per file
 * instead of re-reading 64KB per session per sweep (which, across a large
 * fleet, was one of the loop pins behind the "under load" badge). Only
 * successful extractions are cached: a just-created transcript whose head
 * doesn't carry the cwd yet gets re-read next pass. */
const sessionCwdCache = new Map<string, string>();

/** Sessions with both a conversation id and a real local cwd — the common
 * ground of every git-side sweep (wip snapshots, git-plane health). */
function collectGitSweepTargets(
  sessionIds: string[],
): Array<{ sessionId: string; conversationId: string; cwd: string }> {
  const cache = readConversationCache();
  const targets: Array<{ sessionId: string; conversationId: string; cwd: string }> = [];
  for (const sessionId of sessionIds) {
    const conversationId = cache[sessionId];
    if (!conversationId) continue;
    const file = findSessionFile(sessionId, { staleOk: true }); // bulk 5-min sweep
    if (!file) continue;
    let cwd = sessionCwdCache.get(file.path);
    if (!cwd) {
      try {
        const head = readFileHead(file.path, 65536);
        cwd = file.agentType === "codex" ? extractCodexCwd(head) : extractCwd(head);
      } catch {}
      if (cwd) sessionCwdCache.set(file.path, cwd);
    }
    if (!cwd || !fs.existsSync(cwd)) continue;
    targets.push({ sessionId, conversationId, cwd });
  }
  return targets;
}

async function sweepWipSnapshots(sessionIds: string[]): Promise<void> {
  if (!sessionIds.length) return;
  // Off switch, read fresh each pass so it takes effect without a restart. This
  // loop writes to the user's real git remotes, and this daemon runs from source
  // on dev machines where the watchdog reloads whatever is on disk within ~1min —
  // a side-effecting path like this needs a way to be inert that doesn't require
  // stopping the daemon (which would take every session's sync down with it).
  if (readConfig()?.wip_snapshots_enabled === false) return;
  // Retired checkouts (unpushable remote) are skipped; the git-plane sweep
  // un-retires them when it repairs the repo's origin or sees a fetch recover.
  const eligible = collectGitSweepTargets(sessionIds).filter(
    (t) => !wipSnapshotGivenUp.has(t.cwd),
  );
  if (!eligible.length) return;

  // Group by CHECKOUT, because that is what a snapshot actually describes. Many
  // sessions share one repo — on a busy machine ~50 sessions live in ~6 checkouts
  // — and per-session work was quadratic waste: N identical trees snapshotted, N
  // near-identical commits pushed to N refs. Worse, it defeated the tree-hash
  // throttle entirely: any agent touching a shared checkout invalidated every
  // sibling session's cache at once, so `unchanged` sat at 0 and every pass
  // pushed a full batch forever (observed live: pushed=10 unchanged=0 for hours).
  // That also made the freshness promise hollow — with a per-pass cap and a
  // 50-deep backlog a given repo's snapshot went HOURS stale, which is the whole
  // point of the feature. One snapshot per checkout, one push carrying every
  // sibling's refspec.
  //
  // Keyed by repo TOPLEVEL, sharing sweepGitPlaneFleet's notion of "same repo"
  // rather than inventing a second one: sessions whose cwd is a subdirectory of
  // the same checkout collapse together (they have one working tree, so they'd
  // otherwise be snapshotted once per subdirectory), while linked worktrees stay
  // separate because --show-toplevel returns the worktree root. Falls back to the
  // cwd when the root can't be read, which only loses the deduplication.
  const byRoot = new Map<string, typeof eligible>();
  for (const e of eligible) {
    const key = (await repoRootFor(e.cwd)) ?? e.cwd;
    const group = byRoot.get(key);
    if (group) group.push(e);
    else byRoot.set(key, [e]);
  }
  const repos = [...byRoot.entries()].map(([cwd, sessions]) => ({ cwd, sessions }));

  // Rotate the ORDER (not the membership): every repo is snapshotted every pass,
  // but when the push cap bites, priority rotates so no repo is starved.
  const targets = repos
    .slice(wipSweepCursor % repos.length)
    .concat(repos.slice(0, wipSweepCursor % repos.length));
  wipSweepCursor = (wipSweepCursor + WIP_SNAPSHOT_MAX_PUSHES_PER_PASS) % repos.length;

  let pushed = 0;
  let skipped = 0;
  let deferred = 0;
  await runBounded(targets, WIP_SNAPSHOT_CONCURRENCY, async (t) => {
    const label = path.basename(t.cwd);
    try {
      const remote = await defaultRemote(t.cwd);
      if (!remote) return; // no remote = nowhere to publish; the notice covers it
      const snap = await createWipSnapshot(t.cwd);
      if (!snap) return;
      // Keyed by checkout: the tree belongs to the repo, not the session.
      if (lastPushedWipTree.get(t.cwd) === snap.tree) {
        skipped++;
        return; // tree unchanged since the last push — no network
      }
      if (pushed >= WIP_SNAPSHOT_MAX_PUSHES_PER_PASS) {
        // Cap reached: leave the hash unrecorded so the next pass retries this one
        // (the rotation above gives it priority).
        deferred++;
        return;
      }
      const res = await pushWipSnapshot(t.cwd, {
        remote,
        conversationIds: t.sessions.map((s) => s.conversationId),
        sha: snap.sha,
        // Ride whichever identity the git-plane sweep proved works for this
        // repo (the device fallback key on access-granted remote machines).
        env: gitEnvFor((await repoRootFor(t.cwd)) ?? t.cwd),
      });
      if (res.ok) {
        lastPushedWipTree.set(t.cwd, snap.tree);
        pushed++;
      } else if (res.permanent) {
        // Not pushable, and waiting won't change that — retire it (logged once)
        // rather than failing on every pass forever. Keyed by checkout, since
        // pushability is a property of the remote. The reorientation notice still
        // tells a moved agent only pushed work is present.
        wipSnapshotGivenUp.set(t.cwd, res.error ?? "push refused");
        log(`[WIP] giving up on ${label} (remote not pushable): ${res.error}`);
      } else {
        log(`[WIP] push failed for ${label}: ${res.error}`);
      }
    } catch (e) {
      log(`[WIP] snapshot error for ${label}: ${(e as Error)?.message ?? e}`);
    }
  });
  // Silent when nothing changed (the steady state), so the log stays meaningful.
  if (pushed || deferred) {
    log(
      `[WIP] snapshots pushed=${pushed} unchanged=${skipped}${deferred ? ` deferred=${deferred}` : ""} of ${targets.length} repos (${eligible.length} sessions)`,
    );
  }
}

// ─── Git-plane health ──────────────────────────────────────────────────────
// Keeps every repo with live sessions anchored to a REAL origin (repairing
// transport-leftover origins like dead bundle paths), fetched on a cadence,
// and measured (ahead/behind), with the result riding the device heartbeat.
// Engine in gitPlane.ts; this is the fleet glue. When a repo's remote becomes
// usable again (origin repaired, failing fetch recovered), the wip-snapshot
// retirement latch for its checkouts is dropped so work sync resurrects
// without a daemon restart — the m1 failure mode (2026-08-02) where a dead
// bundle origin silently retired every session's snapshot pushes.

/** Latest sweep result, capped, for the next heartbeat to report. */
let latestGitPlane: RepoPlaneState[] | undefined;

function gitPlaneHeartbeatPayload(): RepoPlaneState[] | undefined {
  return latestGitPlane?.slice(0, GIT_PLANE_REPORT_CAP);
}

async function sweepGitPlaneFleet(sessionIds: string[]): Promise<void> {
  if (!sessionIds.length || !syncServiceRef) return;
  const targets = collectGitSweepTargets(sessionIds);
  if (!targets.length) return;

  // Group by repo TOPLEVEL (not cwd): several checkout cwds — worktrees,
  // subdirectory sessions — can share one repo whose origin is the shared fact.
  const byRoot = new Map<string, { conversationIds: string[]; cwds: Set<string> }>();
  for (const t of targets) {
    const root = await repoRootFor(t.cwd);
    if (!root) continue;
    const group = byRoot.get(root) ?? { conversationIds: [], cwds: new Set() };
    if (!group.conversationIds.includes(t.conversationId)) group.conversationIds.push(t.conversationId);
    group.cwds.add(t.cwd);
    byRoot.set(root, group);
  }
  if (!byRoot.size) return;

  const states = await sweepGitPlane(
    [...byRoot.entries()].map(([root, g]) => ({ root, conversationIds: g.conversationIds })),
    {
      resolveCanonical: async (conversationId) => {
        const info = await syncServiceRef!.getProjectInfo(conversationId).catch(() => null);
        return info?.git_remote_url ?? undefined;
      },
      onRemoteUsable: (root) => {
        for (const cwd of byRoot.get(root)?.cwds ?? []) {
          if (wipSnapshotGivenUp.delete(cwd)) {
            log(`[GITPLANE] un-retired wip snapshots for ${cwd}`);
          }
          lastPushedWipTree.delete(cwd);
        }
      },
      mintDeviceKey: () => ensureDeviceGitKey(deviceLabel()),
      log,
    },
  );
  latestGitPlane = states;
  const bad = states.filter((s) => !s.origin_ok || s.fetch_ok === false);
  if (bad.length) {
    log(`[GITPLANE] ${states.length} repos, ${bad.length} unhealthy: ${bad.map((s) => `${path.basename(s.root)}(${!s.origin_ok ? "origin" : s.needs_access ? "needs-access" : "fetch"})`).join(", ")}`);
  }
}

// ─── Orphan terminal reaper ────────────────────────────────────────────────
// The daemon keeps a warm tmux terminal per managed session and (deliberately)
// never auto-kills idle ones, so every conversation ever resumed leaves a
// cc-resume-* / cx-resume-* terminal behind, and every started one a
// cc-<agent>-<conv> pane. They accumulate without bound and, once re-adopted on
// a restart, re-float a stale "working" into the inbox.
//
// Two candidate classes, differing ONLY in the extra hide-state gate:
//   - cc-resume-* / cx-resume-*: a warm re-resume shell. Reaped on the idle
//     signals alone — clicking the session cold-resumes it, so nothing is lost.
//   - any other codecast-stamped pane (@codecast_session_id /
//     @codecast_conversation_id): the session's PRIMARY terminal. Reaped only
//     when its conversation is already out of the inbox — stashed, dismissed or
//     killed. A conversation VISIBLE in the inbox is never auto-reaped, however
//     long it has been idle, because the user is still holding it.
//
// This reaps a terminal ONLY when multiple independent ground-truth signals agree
// it is finished, and writes every kill to a dedicated reaper.log so the action is
// auditable. The signals (all must pass):
//   - no transcript activity for REAP_IDLE_MS (file mtime) — long-quiet, which a
//     genuine long-running tool never is (real tools finish in minutes)
//   - the LIVE pane reads "idle" (classifyTmuxLiveState is a positive whitelist;
//     a spinner / "esc to interrupt" / any modal reads non-idle and is skipped)
//   - the transcript tail shows a COMPLETED turn (classifyTranscriptTail === idle;
//     a pending tool_use or an open AskUserQuestion reads "active" and is skipped)
//   - the pane is RE-checked in the instant before the kill (TOCTOU guard)
// A reaped session loses only its warm process — the full transcript is on disk,
// so it cold-resumes on click. The kill first removes the session from the
// heartbeat / pane-tracking sets so heartbeatHealthCheck can't reconstitute it.
const REAPER_LOG_FILE = path.join(CONFIG_DIR, "reaper.log");
const REAPER_LOG_MAX_BYTES = 1_000_000;
const REAP_IDLE_MS = 5 * 60 * 60 * 1000;    // 5h of no transcript activity
// The higher bar a DANGLING USER TURN must clear (measured from the last real
// message, never mtime). See danglingUserTurnIsReapable.
const REAP_DANGLING_TURN_IDLE_MS = 24 * 60 * 60 * 1000;
const REAP_MAX_PER_PASS = 3;                 // gentle drain; first kills stay observable
const REAP_EVERY_N_FLUSHES = 10;             // ~5 min between passes (flush = 30s)
const REAP_TMUX_PREFIXES = ["cc-resume-", "cx-resume-"];
// Both codecast stamps + name in ONE tmux call, so identifying every candidate
// costs one exec per pass instead of one show-options per pane.
//
// The separator must be PRINTABLE. tmux rewrites control characters in format
// output to `_`, and it does so exactly when the caller is NOT inside tmux —
// which is the daemon, always (launchd). The tab this used to use came back as
// `_`, welding all three fields into one string: every row parsed as a pane
// named `cc-resume-abc_<sessionid>_<convid>`, which matches no live pane, so
// every kill silently missed and no stamped pane was ever identified. The name
// goes LAST because it is the only human-named field, so a stray separator in
// it re-joins instead of shifting the stamps.
const REAP_FIELD_SEP = "|";
const REAP_LIST_FORMAT = `#{@codecast_session_id}${REAP_FIELD_SEP}#{@codecast_conversation_id}${REAP_FIELD_SEP}#{session_name}`;

function reaperLog(message: string, mirror = true): void {
  const line = `[${new Date().toISOString()}] ${message}\n`;
  try {
    // Nothing rotates this file, and the per-pass summary appends every ~5 min
    // forever — keep the tail, drop the oldest half once it gets large.
    if (fs.statSync(REAPER_LOG_FILE).size > REAPER_LOG_MAX_BYTES) {
      const kept = fs.readFileSync(REAPER_LOG_FILE, "utf8").slice(-REAPER_LOG_MAX_BYTES / 2);
      fs.writeFileSync(REAPER_LOG_FILE, kept.slice(kept.indexOf("\n") + 1));
    }
  } catch {}
  try { fs.appendFileSync(REAPER_LOG_FILE, line); } catch {}
  // Mirror to daemon.log (and the server log feed) at warn — a kill is notable.
  // The per-pass summary passes mirror=false: it fires every ~5 min and would
  // swamp the feed, but belongs in reaper.log where the kills are.
  if (mirror) log(`[REAPER] ${message}`, "warn");
}

export type ReapCandidate = {
  tmux: string;
  /** From @codecast_session_id, when the pane carries it. */
  sessionId: string | null;
  /** From @codecast_conversation_id, when the pane carries it. */
  convId: string | null;
  /** "resume" panes reap on idle alone; "stamped" panes also need a hide state. */
  kind: "resume" | "stamped";
};

// One `tmux list-sessions` row: the two codecast stamps + name (see
// REAP_LIST_FORMAT). Returns null for a pane this daemon has no business
// touching — neither a resume shell nor codecast-stamped. Unset user options
// expand to the empty string; a tmux too old to expand `#{@opt}` hands the
// placeholder back verbatim, or emits the bare name with no separators at all.
// Both read as "no stamps", so a pane goes uncollected rather than misidentified.
export function parseReapCandidateRow(row: string): ReapCandidate | null {
  const parts = row.split(REAP_FIELD_SEP);
  // Fewer fields than the format emits means the separators never survived:
  // take the whole row as the name and treat it as unstamped.
  const [name, sessionId, convId] =
    parts.length < 3
      ? [row, "", ""]
      : [parts.slice(2).join(REAP_FIELD_SEP), parts[0], parts[1]];
  const tmux = (name ?? "").trim();
  if (!tmux) return null;
  const unexpanded = (v: string) => v.includes("#{");
  const stampedSession = (sessionId ?? "").trim();
  const stampedConv = (convId ?? "").trim();
  const stampedSessionId = stampedSession && !unexpanded(stampedSession) ? stampedSession : null;
  const stampedConvId = stampedConv && !unexpanded(stampedConv) ? stampedConv : null;
  if (REAP_TMUX_PREFIXES.some((p) => tmux.startsWith(p))) {
    return { tmux, sessionId: stampedSessionId, convId: stampedConvId, kind: "resume" };
  }
  if (stampedSessionId || stampedConvId) {
    return { tmux, sessionId: stampedSessionId, convId: stampedConvId, kind: "stamped" };
  }
  return null;
}

// Whether a stamped (primary-terminal) pane's conversation is hidden enough to
// reap. Killed, stashed and dismissed all mean the user has taken the card out
// of their inbox; anything still visible there is off limits regardless of idle
// time, and a PINNED card is visible even when killed (see shouldShowInInbox).
// Unknown lifecycle fails CLOSED — the opposite of the resurrection gate,
// because here the cautious move is to leave the agent running.
export function stampedPaneReapEligibility(
  lifecycle: ConversationLifecycle | null | undefined,
): { eligible: boolean; reason: string | null } {
  // "Absent hide fields" is NOT "not hidden". The status-only fallback carries no
  // hide state at all, and reading its silence as "inbox-visible" would put a lie
  // in the audit log (killed conversations reported as visible-and-skipped) while
  // the stamped reaper silently no-ops against an undeployed backend. Demand that
  // the state was actually fetched.
  if (!lifecycle || !lifecycle.hideStateKnown) return { eligible: false, reason: "hide-state-unknown" };
  if (lifecycle.inboxPinnedAt) return { eligible: false, reason: "pinned" };
  const hidden = !!(lifecycle.inboxKilledAt || lifecycle.inboxStashedAt || lifecycle.inboxDismissedAt);
  if (!hidden) return { eligible: false, reason: "inbox-visible" };
  return { eligible: true, reason: null };
}

/**
 * Rescues the ONE case where `transcript=active` blocks a reap forever.
 *
 * classifyTranscriptTail reads a trailing user turn as "active" — it is the
 * agent's move — with no staleness dimension. When an agent dies or wedges
 * mid-turn, the transcript is frozen with the user's unanswered prompt last, so
 * the tail reads "active" for all eternity and the pane is permanently
 * un-reapable. That is the unbounded accumulator: 25 of this machine's 267 idle
 * Claude transcripts (~9%) are stuck exactly this way, some 682h old.
 *
 * A dead agent is not mid-turn. So a DANGLING user turn reaps once every
 * independent signal agrees it is abandoned: the live pane already reads idle
 * (guaranteed by reapBlockReason's ordering, passed explicitly so this decision
 * is complete on its own), and the last real message is older than the raised
 * REAP_DANGLING_TURN_IDLE_MS bar — measured from the MESSAGE timestamp, because
 * mtime lies (see transcriptTailLastRealTimestamp).
 *
 * A pending tool_use still blocks at any age: that is real in-flight work. No
 * timestamp → no honest clock → keep blocking. The fix lives here rather than in
 * classifyTranscriptTail because the status-reconcile path depends on the
 * classifier's current semantics.
 *
 * A PENDING AskUserQuestion looks EXACTLY like a dangling user turn and must be
 * excluded separately. Claude Code buffers the AUQ tool_use out of the JSONL
 * until it is answered (see extractPendingToolUseFromTail), so while a question
 * waits, the newest message physically in the transcript is the previous,
 * already-resolved tool_result — a `user` turn. lastRealRole cannot see the
 * question, and the pane classifier's modal detection is regex on footer copy,
 * one release away from letting a live question-blocked session be killed. So we
 * consult the ask-input sidecar directly — see askUserQuestionStillPending.
 */
export function danglingUserTurnIsReapable(input: {
  turn: TranscriptTurnState;
  lastRealRole: "user" | "assistant" | null;
  lastRealTimestampMs: number | null;
  /** mtime of ~/.codecast/ask-input/<session>.json, or null when absent. */
  askSidecarMtimeMs: number | null;
  paneIdle: boolean;
  now: number;
}): boolean {
  if (input.turn !== "active") return false;
  if (input.lastRealRole !== "user") return false;
  if (!input.paneIdle) return false;
  if (input.lastRealTimestampMs === null) return false;
  if (askUserQuestionStillPending(input.askSidecarMtimeMs, input.lastRealTimestampMs)) return false;
  return input.now - input.lastRealTimestampMs >= REAP_DANGLING_TURN_IDLE_MS;
}

/**
 * Whether an AskUserQuestion is still waiting on the user, judged by ORDERING
 * rather than existence.
 *
 * The sidecar is written when the question is asked and is NEVER deleted —
 * readAskUserQuestionInput copes via a 5-minute mtime window, and this machine
 * has 123 of them going back to June. So "a sidecar exists" is nearly meaningless
 * (it blocked 5 of 23 stuck panes here, 3 of whose questions were answered weeks
 * ago) and gets monotonically worse as sessions accumulate one each — it would
 * quietly retire this escape hatch altogether.
 *
 * Ordering is the honest signal: answering a question flushes the buffered turn
 * AND appends the user's answer, so the transcript gains a message NEWER than the
 * sidecar. A sidecar newer than the last real message therefore means the
 * question was asked and nothing has happened since — still pending. On the same
 * 23 panes this correctly protects exactly 2, both genuinely abandoned mid-question.
 *
 * KNOWN INERT SHAPES — strictly better than the pane regex alone, but not total:
 *   - a stale sidecar from an ANSWERED earlier question masks a LATER pending one
 *     whose own write never happened: codecast-status.sh skips the write when the
 *     tool_input carries an empty `questions` array (statusHook.ts), and the hook
 *     can also lose it to its own timeout. The mask reads as "pending" — the SAFE
 *     direction (we decline to reap), so it costs a leaked pane, not a killed
 *     question.
 *   - a session running WITHOUT the codecast status hook writes no sidecar at all,
 *     so it has no protection here beyond the pane classifier.
 * Closing either needs a signal the agent emits unconditionally while blocked;
 * the sidecar is the best one that exists today.
 */
export function askUserQuestionStillPending(
  sidecarMtimeMs: number | null,
  lastRealTimestampMs: number | null,
): boolean {
  if (sidecarMtimeMs === null) return false;
  if (lastRealTimestampMs === null) return true; // can't order them → assume pending
  return sidecarMtimeMs > lastRealTimestampMs;
}

// Collapse a skip reason into a stable bucket for the per-pass summary — the raw
// reasons embed the exact idle age ("active-37min"), which would give every pane
// its own tally line.
export function reapSkipBucket(reason: string): string {
  return reason.startsWith("active-") ? "active" : reason;
}

// "pane=busy×3, no-transcript×8" — commonest first, so the reason the reaper is
// doing nothing is the first thing on the line.
export function summarizeReapSkips(reasons: string[]): string {
  if (reasons.length === 0) return "none";
  const counts = new Map<string, number>();
  for (const r of reasons) {
    const bucket = reapSkipBucket(r);
    counts.set(bucket, (counts.get(bucket) ?? 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([bucket, n]) => `${bucket}×${n}`)
    .join(", ");
}

// Resolve the full session id for a cc-resume-* terminal. The tmux name carries
// only an 8-char prefix, so prefer the authoritative @codecast_session_id option,
// then fall back to globbing the transcript by that prefix. Returns null when the
// session can't be identified — in which case it is NEVER killed.
async function resolveReapSessionId(tmux: string): Promise<string | null> {
  const opt = await getTmuxSessionOption(tmux, "@codecast_session_id");
  if (opt && opt.trim()) return opt.trim();
  const prefix = REAP_TMUX_PREFIXES.reduce((s, p) => s.startsWith(p) ? s.slice(p.length) : s, tmux);
  if (!prefix || prefix.length < 8) return null;
  const claudeDir = path.join(process.env.HOME || "", ".claude", "projects");
  try {
    for (const dir of await fs.promises.readdir(claudeDir, { withFileTypes: true })) {
      if (!dir.isDirectory()) continue;
      const found = (await fs.promises.readdir(path.join(claudeDir, dir.name)))
        .find((f) => f.startsWith(prefix) && f.endsWith(".jsonl"));
      if (found) return found.replace(/\.jsonl$/, "");
    }
  } catch {}
  return null;
}

// findSessionFile walks every ~/.claude/projects dir with sync readdir (~4.5ms on
// a miss) and the reaper now calls it per candidate per pass. Cache the resolved
// transcript across passes, revalidated with a single statSync; a moved/deleted
// file falls back to the full walk. Reaper-local on purpose — findSessionFile has
// many other callers whose freshness assumptions we're not touching.
const reapTranscriptCache = new Map<string, SessionFileInfo>();
// Misses need caching more than hits do: "no-transcript" is the DOMINANT skip
// bucket, and each one paid the full walk every pass forever. TTL'd rather than
// permanent so a transcript that shows up later (a resume materializing one) is
// still found within half an hour.
const reapTranscriptMisses = new Map<string, number>();
const REAP_TRANSCRIPT_MISS_TTL_MS = 30 * 60 * 1000;

function findReapTranscript(sessionId: string, now: number = Date.now()): SessionFileInfo | null {
  const cached = reapTranscriptCache.get(sessionId);
  if (cached) {
    try {
      fs.statSync(cached.path);
      return cached;
    } catch {
      reapTranscriptCache.delete(sessionId);
    }
  }
  const missedAt = reapTranscriptMisses.get(sessionId);
  if (missedAt !== undefined && now - missedAt < REAP_TRANSCRIPT_MISS_TTL_MS) return null;
  // staleOk: a missed transcript just defers reap classification to a later
  // pass (and this path already TTLs its misses for half an hour).
  const found = findSessionFile(sessionId, { staleOk: true });
  if (found) {
    reapTranscriptCache.set(sessionId, found);
    reapTranscriptMisses.delete(sessionId);
  } else {
    reapTranscriptMisses.set(sessionId, now);
  }
  return found;
}

// mtime of the pending-AskUserQuestion sidecar, or null when the session never
// asked one. See askUserQuestionStillPending for why mtime and not existence.
function askInputSidecarMtimeMs(sessionId: string): number | null {
  try {
    return fs.statSync(path.join(ASK_INPUT_DIR, `${sessionId}.json`)).mtimeMs;
  } catch {
    return null;
  }
}

// `tmux list-panes -s -t <sess>` emits one line per pane across ALL windows.
// killTmuxSessionAndTree takes the whole tmux SESSION, while every reap gate only
// inspects :0.0 — so a second window or a split (the user's own shell, or another
// live agent) would die on the strength of one idle pane's evidence. Exactly one
// pane means what we inspected is all there is. Unparseable output → not single
// (fail closed).
export function tmuxSessionIsSinglePane(listPanesStdout: string): boolean {
  const panes = listPanesStdout.split("\n").map((l) => l.trim()).filter(Boolean);
  return panes.length === 1;
}

// The reason a terminal is NOT safe to reap, or null if it passed every gate.
// On success returns the resolved transcript path + idle age so the caller need
// not re-scan. Cheapest gates first (idle-age before the pane/tail reads).
async function reapBlockReason(
  sessionId: string, tmux: string, now: number,
): Promise<{ reason: string } | { reason: null; idleHours: number }> {
  const file = findReapTranscript(sessionId, now);
  if (!file) return { reason: "no-transcript" };
  const classifyTail = classifyTranscriptTailFor(file.agentType);
  if (!classifyTail) return { reason: `agent=${file.agentType}` };
  let idleMs: number;
  try { idleMs = now - fs.statSync(file.path).mtimeMs; } catch { return { reason: "stat-failed" }; }
  if (idleMs < REAP_IDLE_MS) return { reason: `active-${Math.round(idleMs / 60000)}min` };
  let pane: string;
  try { ({ stdout: pane } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmux + ":0.0", "-S", "-25"], { timeout: 4000 })); }
  catch { return { reason: "pane-capture-failed" }; }
  const live = classifyLivePaneFor(file.agentType, pane);
  if (live !== "idle") return { reason: `pane=${live}` };
  let tail: string;
  try { tail = readFileTailSync(file.path); } catch { return { reason: "tail-read-failed" }; }
  const turn = classifyTail(tail);
  let idleHours = Math.round(idleMs / 3600000);
  if (turn !== "idle") {
    const lastRealTimestampMs = transcriptTailLastRealTimestamp(tail);
    const askSidecarMtimeMs = askInputSidecarMtimeMs(sessionId);
    const reapable = danglingUserTurnIsReapable({
      turn,
      lastRealRole: transcriptTailLastRealRole(tail),
      lastRealTimestampMs,
      askSidecarMtimeMs,
      paneIdle: true, // established above — we only reach here when live === "idle"
      now,
    });
    if (!reapable) {
      // Name the AUQ case separately: "transcript=active" on a session that is
      // actually waiting on a question is the misleading log line that hid this.
      return askUserQuestionStillPending(askSidecarMtimeMs, lastRealTimestampMs)
        ? { reason: "pending-question" }
        : { reason: `transcript=${turn}` };
    }
    // Report the age the DECISION used. mtime can be far younger than the content
    // (metadata touches), and logging "idle=16h" for a 325h-dead turn would make
    // the reap look reckless in the audit log.
    idleHours = Math.max(idleHours, Math.round((now - lastRealTimestampMs!) / 3600000));
  }
  return { reason: null, idleHours };
}

async function reapOneTerminal(sessionId: string, tmux: string, convId: string | undefined, idleHours: number): Promise<void> {
  // TOCTOU guard: re-confirm the pane is still idle in the instant before the kill.
  try {
    const { stdout: pane } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmux + ":0.0", "-S", "-25"], { timeout: 4000 });
    const live = classifyLivePaneFor(detectSessionAgentType(sessionId), pane);
    if (live !== "idle") { reaperLog(`SKIP ${tmux} (${sessionId.slice(0, 8)}): pane became "${live}" at kill time`); return; }
  } catch { reaperLog(`SKIP ${tmux} (${sessionId.slice(0, 8)}): recheck capture failed`); return; }

  // Stop tracking BEFORE the kill so heartbeatHealthCheck can't see the vanished
  // tmux and reconstitute it.
  stopManagedSessionHeartbeat(sessionId);
  resumeSessionCache.delete(sessionId);
  stopCodexPermissionPoller(sessionId);
  // Leave a clean "finished" status rather than letting the heartbeat-staleness
  // path decay a frozen "working" into "stopped"/needs-attention. No session_error
  // (this is a tidy reap, not a crash).
  if (convId && syncServiceRef) {
    await syncServiceRef.updateSessionAgentStatus(convId, "idle").catch(() => {});
  }
  await killTmuxSessionAndTree(tmux);
  reaperLog(`REAPED ${tmux} session=${sessionId.slice(0, 8)} conv=${(convId || "?").slice(0, 12)} idle=${idleHours}h`);
}

async function reapIdleOrphanTerminals(): Promise<void> {
  const now = Date.now();
  let candidates: ReapCandidate[];
  try {
    const { stdout } = await tmuxExec(["list-sessions", "-F", REAP_LIST_FORMAT], { timeout: 5000 });
    candidates = stdout.split("\n")
      .map(parseReapCandidateRow)
      .filter((c): c is ReapCandidate => c !== null);
  } catch { return; }
  if (candidates.length === 0) return;

  const convCache = readConversationCache();
  const skips: string[] = [];
  let reaped = 0;
  for (const cand of candidates) {
    if (reaped >= REAP_MAX_PER_PASS) { skips.push("pass-cap"); continue; }
    const sessionId = cand.sessionId ?? await resolveReapSessionId(cand.tmux);
    if (!sessionId) { skips.push("unidentified"); continue; } // never kill what we can't name
    const verdict = await reapBlockReason(sessionId, cand.tmux, now);
    if (verdict.reason !== null) { skips.push(verdict.reason); continue; }
    const convId = cand.convId ?? convCache[sessionId];
    // A stamped pane is the session's PRIMARY terminal — the one a human may be
    // attached to. Two extra gates, cheapest first: the whole tmux session must
    // be the single pane we actually inspected, and its conversation must already
    // be out of the inbox. (cc-resume-* shells skip both: nobody attaches to them.)
    if (cand.kind === "stamped") {
      let panes: string;
      try { ({ stdout: panes } = await tmuxExec(["list-panes", "-s", "-t", cand.tmux, "-F", "#{window_index}.#{pane_index}"], { timeout: 4000 })); }
      catch { skips.push("pane-list-failed"); continue; }
      if (!tmuxSessionIsSinglePane(panes)) { skips.push("multi-pane"); continue; }
      const lifecycle = convId && syncServiceRef
        ? await syncServiceRef.getConversationLifecycle(convId, sessionId).catch(() => null)
        : null;
      const eligibility = stampedPaneReapEligibility(lifecycle);
      if (!eligibility.eligible) { skips.push(eligibility.reason!); continue; }
    }
    await reapOneTerminal(sessionId, cand.tmux, convId, verdict.idleHours);
    reaped++;
  }
  // Every pass leaves a line: without it the skip reasons were invisible and a
  // reaper that had quietly stopped reaping looked identical to one with nothing
  // to do. File-only (mirror=false) — this fires every ~5 min.
  reaperLog(`pass: ${candidates.length} candidates, reaped ${reaped}, skipped: ${summarizeReapSkips(skips)}`, false);
}

// Reads the last ~64KB of a file as UTF-8 without loading the whole thing --
// transcripts run to MBs and this is called per-session on every heartbeat.
function readFileTailSync(filePath: string, maxBytes = 64 * 1024): string {
  const fd = fs.openSync(filePath, "r");
  try {
    const size = fs.fstatSync(fd).size;
    const start = Math.max(0, size - maxBytes);
    const len = size - start;
    if (len <= 0) return "";
    const buf = Buffer.allocUnsafe(len);
    fs.readSync(fd, buf, 0, len, start);
    return buf.toString("utf8");
  } finally {
    fs.closeSync(fd);
  }
}

// Self-heals a status latch frozen on a lost lifecycle transition by reconciling
// lastSentAgentStatus against the session's JSONL transcript (the universal
// ground truth -- works for tmux-managed and bare-terminal sessions alike). The
// decision is the pure reconciledStatus, which defers on any ambiguity. Claude and
// Codex transcripts are both parsed (each via its own tail classifier); Codex in
// particular has no Stop-hook equivalent and its watcher-driven idle transition
// rides a setTimeout that dies across macOS sleep, so this heartbeat-driven path
// is its only durable latch recovery. Gemini/Cursor formats are not yet classified.
export async function reconcileStatusFromTranscript(sessionId: string, syncService: SyncService): Promise<void> {
  const stored = lastSentAgentStatus.get(sessionId);

  // permission_blocked recovery. tmux-managed sessions are handled by the PANE
  // (paneReconcileTarget now recovers permission_blocked once the menu is gone) —
  // the transcript MUST defer to it here, because Claude Code buffers an
  // AskUserQuestion's tool_use out of the JSONL until it is answered. So when the
  // agent runs an auto-approved tool (e.g. Bash in bypassPermissions) and THEN
  // asks a question, the transcript tail is the earlier tool's tool_result (a user
  // turn) while the real question is invisible — reading "tail ends in a user turn
  // => answered" would wrongly flip a still-waiting agent to "working" and latch it
  // there (this was the "stuck working" inbox bug). Bare-terminal sessions have no
  // pane, so they keep the transcript recovery as their only signal. Restricted to
  // Claude (Codex permission blocks are recovered by startCodexPermissionPoller's
  // own working transition).
  if (stored === "permission_blocked") {
    if (resumeSessionCache.has(sessionId)) return; // tmux: pane is authoritative
    // staleOk here and below: this reconcile runs for every session every
    // maintenance tick, and most of the fleet has no local transcript — probing
    // each miss would re-create the per-tick walk storm. The next tick retries.
    const file = findSessionFile(sessionId, { staleOk: true });
    if (!file || file.agentType !== "claude") return;
    let lastRole: "user" | "assistant" | null;
    try {
      lastRole = transcriptTailLastRealRole(readFileTailSync(file.path));
    } catch {
      return; // can't read the transcript -> defer, never guess
    }
    const corrected = permissionBlockedRecoveryTarget(stored, lastRole);
    if (!corrected) return;
    const conversationId = readConversationCache()[sessionId];
    if (!conversationId) return;
    log(`[STATUS-RECONCILE] ${sessionId.slice(0, 8)} stored=permission_blocked lastRole=${lastRole ?? "none"} -> ${corrected}`);
    sendAgentStatus(syncService, conversationId, sessionId, corrected);
    return;
  }

  // tmux-managed sessions are reconciled from the live pane (the authoritative
  // busy/idle signal) by reconcileStatusFromPane. Skip the transcript verdict
  // for them: a turn cut off mid-tool reads "active" forever, so the transcript
  // would flip a pane-confirmed idle back to "working" every cycle. The
  // transcript path remains the reconcile for bare-terminal sessions, which
  // have no pane. Both kinds get the open task prime below.
  const paneManaged = resumeSessionCache.has(sessionId);
  // Cheap in-memory gate first: skip the file lookup entirely unless the stored
  // status is one we'd ever correct.
  if (!paneManaged && !(stored === "working" || stored === "thinking" || stored === "idle" || stored === "connected" || stored === "waiting" || stored === "dormant" || stored === "done")) {
    return;
  }
  const file = findSessionFile(sessionId, { staleOk: true });
  if (!file) return;
  // Bring the open task scan up to date off the loop before any verdict. The
  // pane reconcile, the Stop hook and verifiedOpenTasks below all run the
  // synchronous scan, and after a restart that scan covers the whole
  // transcript on the loop unless a prime got there first. The scan is
  // caches its offset, so on an unchanged transcript this is one stat.
  if (file.agentType === "claude") await primeOpenTaskScan(file.path, sessionId);
  if (paneManaged) return;
  // The prime yielded. A hook that landed meanwhile already moved the status,
  // and a verdict built on the stored value above would publish over it; the
  // next tick reconciles from fresh inputs. The tail is read after the yield
  // for the same reason.
  if (lastSentAgentStatus.get(sessionId) !== stored) return;
  let turn: TranscriptTurnState;
  try {
    const tail = readFileTailSync(file.path);
    const classifyTail = classifyTranscriptTailFor(file.agentType);
    if (!classifyTail) return; // gemini/cursor formats not classified yet -> defer
    turn = classifyTail(tail);
  } catch {
    return; // can't read the transcript -> defer, never guess
  }
  // Only verify open tasks against live processes when the verdict depends
  // on it: a correction landing on idle (might really be waiting), or a stored
  // waiting (might have drained back to idle / woken to working). The scan
  // behind it is primed above, so it costs only the delta.
  const needsTaskScan = file.agentType === "claude" &&
    (stored === "waiting" || reconciledStatus(stored, turn) === "idle");
  const openTasks = needsTaskScan ? verifiedOpenTasks(file.path, sessionId) : [];
  const hasOpenTasks = openTasks.length > 0;
  // The stamp read is a single small file, paid only when a settle correction
  // is on the table (same gate as the task scan).
  const declared = needsTaskScan || reconciledStatus(stored, turn) === "idle" ? declaredSettleVerdict(sessionId) : null;
  const corrected = reconciledStatusWithTasks(stored, turn, hasOpenTasks, declared);
  // A parked "waiting" that still checks out re-publishes its tasks on a slow
  // cadence so the server's report keeps vouching for it (see
  // OPEN_TASKS_REFRESH_MS); nothing else about the status changes.
  if (needsTaskScan) pendingOpenTaskReports.set(sessionId, toOpenTaskReports(openTasks));
  const refresh = !corrected && needsTaskScan &&
    (pendingOpenTasksChanged(sessionId) || (stored === "waiting" && hasOpenTasks && openTasksRefreshDue(sessionId, Date.now())));
  if (!corrected && !refresh) { pendingOpenTaskReports.delete(sessionId); return; }
  // Only now (a correction is warranted) pay the conversation-cache read.
  const conversationId = readConversationCache()[sessionId];
  if (!conversationId) { pendingOpenTaskReports.delete(sessionId); return; }
  if (!corrected) {
    sendAgentStatus(syncService, conversationId, sessionId, stored as AgentStatus);
    return;
  }
  log(`[STATUS-RECONCILE] ${sessionId.slice(0, 8)} stored=${stored} turn=${turn} -> ${corrected}`);
  sendAgentStatus(syncService, conversationId, sessionId, corrected);
}

async function heartbeatHealthCheck(sessionId: string): Promise<void> {
  const tmux = resumeSessionCache.get(sessionId);
  if (!tmux) return;

  if (resumeInFlight.has(sessionId)) return;
  const restartTs = restartingSessionIds.get(sessionId);
  if (restartTs && Date.now() - restartTs < RESTART_GUARD_TTL_MS) return;

  // The only auto-action allowed: if the tmux server no longer lists this
  // session, reconstitute the worker. The kill inside handleDeadSession is a
  // no-op in that case (nothing to kill), and the reconstitution restores the
  // agent the user wants alive.
  try {
    await tmuxExec(["has-session", "-t", tmux], { timeout: 3000, killSignal: "SIGKILL" });
  } catch {
    log(`[HEARTBEAT-HEALTH] tmux session ${tmux} gone for ${sessionId.slice(0, 8)}, triggering reconstitution`);
    await handleDeadSession(sessionId, tmux);
    return;
  }

  if (syncServiceRef) {
    const cache = readConversationCache();
    const convId = cache[sessionId];
    if (convId) {
      const pending = pendingInteractivePrompts.get(sessionId);
      if (pending && Date.now() - pending.timestamp > 90_000) {
        try {
          const { stdout: pane } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmux + ":0.0", "-S", "-50"]);
          if (!parseInteractivePrompt(pane)) {
            pendingInteractivePrompts.delete(sessionId);
            log(`[HEARTBEAT-HEALTH] Cleared stale pending prompt for ${sessionId.slice(0, 8)}`);
            // The menu resolved in the terminal without an answer flowing through
            // us (Esc, a local keypress, a dialog superseded by the next render).
            // Retire the scraped card too, or it stays an open question forever.
            await closeSyntheticPrompt(sessionId, convId, syncServiceRef, "Dismissed in the terminal");
          } else {
            pending.timestamp = Date.now();
          }
        } catch {
          pendingInteractivePrompts.delete(sessionId);
        }
      } else if (!pending) {
        checkForInteractivePrompt(tmux + ":0.0", sessionId, convId, syncServiceRef, 0).catch(() => {});
      }
    }
  }
}

// ─── Kill-state gate for resurrection ──────────────────────────────────────
// The daemon keeps managed sessions warm and reconstitutes any whose tmux
// vanished, which is right for a crash and wrong for a KILL — a kill tears the
// pane down, the health sweep sees the vanished tmux, and the agent the user
// just retired comes straight back (2026-08-03: five conversations, all
// status=completed with inbox_killed_at stamped, resurrected on every pass).
// The verdict is this pure function; "killed" and "completed" are equivalent
// here, since killSession stamps both and a completed conversation is finished
// either way.
export function isConversationRetired(
  lifecycle: ConversationLifecycle | null | undefined,
  opts: { trustStatusFallback: boolean },
): boolean {
  // Unknown lifecycle fails OPEN: a Convex blip must not strand a genuinely
  // crashed live session that the user still wants running.
  if (!lifecycle) return false;
  // The status-only fallback resolves by session id via `.first()` — the OLDEST
  // twin (ct-36973). With twins it can report the wrong row's status in EITHER
  // direction, and a false "completed" here refuses to resume a LIVE session,
  // silently stranding it. So only the caller that can absorb a wrong refusal may
  // act on it: heartbeat reconstitution, where the worst case is a crashed
  // session staying down — the pre-fix status quo, recoverable with Restart.
  // Every other path (delivery, warm pool, resume repair) requires the real
  // conversation-id-resolved query and otherwise proceeds.
  if (!lifecycle.hideStateKnown && !opts.trustStatusFallback) return false;
  return !!lifecycle.inboxKilledAt || lifecycle.status === "completed";
}

export type ResumeOptions = {
  /**
   * This resume is an explicit human gesture (the resume_session / fork_session
   * command), not the daemon reviving something on its own — so it bypasses the
   * retired-conversation gate. It has to: restartSession leaves an existing row's
   * status/inbox_killed_at untouched when it enqueues the kill→resume pair, so a
   * "Restart" on a killed card reaches the daemon still looking killed, and
   * refusing it would break the one gesture that is meant to bring a session back.
   * Only the gate reads this; nothing downstream does.
   */
  userInitiated?: boolean;
};

// Convex side of the gate. Runs only on resurrection paths (rare), never per
// heartbeat, and swallows lookup failures into "not retired" (fail open).
export async function conversationForbidsResurrection(
  conversationId: string,
  sessionId: string,
  context: string,
  opts: { trustStatusFallback: boolean },
  // Injectable so the wired gate — including its fail-open on a throwing lookup —
  // is testable without a live Convex client. Production always uses the default.
  fetchLifecycle: (c: string, s: string) => Promise<ConversationLifecycle | null> = (c, sid) =>
    syncServiceRef ? syncServiceRef.getConversationLifecycle(c, sid) : Promise.resolve(null),
): Promise<boolean> {
  const lifecycle = await fetchLifecycle(conversationId, sessionId).catch(() => null);
  if (!isConversationRetired(lifecycle, opts)) return false;
  log(`[${context}] not reconstituting ${sessionId.slice(0, 8)} — conversation killed (conv=${conversationId.slice(0, 12)} status=${lifecycle?.status ?? "?"}${lifecycle?.inboxKilledAt ? " killed_at=set" : ""} via=${lifecycle?.source})`);
  return true;
}

async function handleDeadSession(sessionId: string, tmuxSession: string): Promise<void> {
  try { await tmuxExec(["kill-session", "-t", tmuxSession]); } catch {}
  resumeSessionCache.delete(sessionId);
  stopCodexPermissionPoller(sessionId);
  stopManagedSessionHeartbeat(sessionId);

  const cache = readConversationCache();
  const conversationId = cache[sessionId];

  // A retired conversation is not a crash. Tracking is already fully torn down
  // above (the same set reapOneTerminal clears), so stamp the tidy "idle" and
  // stop — before the transcript regeneration inside repairAndResumeSession and
  // before the "Session crashed" banner, neither of which belongs on a session
  // the user deliberately killed. autoResumeSession gates on this too (it is the
  // chokepoint for every other resume path); this earlier check is what keeps
  // the crash-recovery side effects from running at all.
  if (conversationId && await conversationForbidsResurrection(conversationId, sessionId, "HEARTBEAT-HEALTH", { trustStatusFallback: true })) {
    if (syncServiceRef) await syncServiceRef.updateSessionAgentStatus(conversationId, "idle").catch(() => {});
    return;
  }

  // A Workflow-tool agent's pane going away is not a crash either: the agent
  // lives inside its host session, and the only pane it could have had was a
  // standalone copy. Nothing to reconstitute — the regeneration below would
  // rewrite the host's transcript and the resume would be refused anyway.
  const workflowAgentTranscript = workflowAgentTranscriptPathFor(sessionId);
  if (workflowAgentTranscript) {
    log(`[HEARTBEAT-HEALTH] not reconstituting ${sessionId.slice(0, 8)} — workflow agent transcript (${workflowAgentTranscript}); the host session owns it`);
    if (conversationId && syncServiceRef) await syncServiceRef.updateSessionAgentStatus(conversationId, "idle").catch(() => {});
    return;
  }

  // Crash recovery shares the kill_session lifecycle contract: the tmux pane has
  // been torn down, any "injected" messages on Convex were lost with it, and the
  // daemon's local dedup state now references a dead pane. Reset both so the
  // reconstituted session can replay pending work.
  await clearConversationDeliveryAndResumeState(conversationId, sessionId, "HEARTBEAT-HEALTH");

  if (conversationId && syncServiceRef) {
    await syncServiceRef.setSessionError(conversationId, "Session crashed — reconstituting from database").catch(logConvexFailure);
  }

  const repaired = await repairAndResumeSession(sessionId, "", readTitleCache(), undefined, conversationId);
  if (repaired) {
    log(`[HEARTBEAT-HEALTH] Reconstituted session ${sessionId.slice(0, 8)}`);
    if (conversationId && syncServiceRef) {
      await syncServiceRef.setSessionError(conversationId).catch(logConvexFailure);
      await syncServiceRef.updateSessionAgentStatus(conversationId, "connected").catch(logConvexFailure);
    }
  } else {
    log(`[HEARTBEAT-HEALTH] Reconstitution failed for ${sessionId.slice(0, 8)}`);
    if (conversationId && syncServiceRef) {
      await syncServiceRef.setSessionError(conversationId, "Session crashed and could not be reconstituted").catch(logConvexFailure);
    }
  }
}

export function registerManagedStartedSession(conversationId: string, sessionId: string, tmuxSession: string): void {
  // Track the pane immediately, exactly as a resumed/warm-recovered session is. The periodic
  // health sweep (heartbeatHealthCheck) and the pane-authoritative status reconcile both gate
  // on resumeSessionCache membership. A freshly-started session that was never resumed wasn't
  // in it, so a buffered AskUserQuestion parked on such a session went un-scraped — invisible
  // on the web until it was answered (or until a daemon restart warm-recovered the session
  // into the cache, which was the only reason it ever recovered). Set before the syncServiceRef
  // guard: this is local bookkeeping that doesn't depend on the sync client.
  resumeSessionCache.set(sessionId, tmuxSession);
  if (!syncServiceRef) return;
  setTmuxSessionOption(tmuxSession, "@codecast_conversation_id", conversationId).catch(() => {});
  setTmuxSessionOption(tmuxSession, "@codecast_session_id", sessionId).catch(() => {});
  syncServiceRef.markSessionActive(conversationId).catch(logConvexFailure);
  syncServiceRef.registerManagedSession(sessionId, process.pid, tmuxSession, conversationId).catch(logConvexFailure);
  ensureManagedSessionHeartbeat(sessionId);
}

// Test/inspection seam: whether a session's pane is tracked (present in resumeSessionCache),
// which is what makes it eligible for the periodic interactive-prompt scrape and the
// pane-authoritative status reconcile.
export function isSessionPaneTracked(sessionId: string): boolean {
  return resumeSessionCache.has(sessionId);
}

function deleteStartedSession(conversationId: string): void {
  const entry = startedSessionTmux.get(conversationId);
  if (entry?.sessionId) {
    stopManagedSessionHeartbeat(entry.sessionId);
  }
  startedSessionTmux.delete(conversationId);
}

export function getInitialManagedSessionId(
  agentType: AgentClientId,
  expectedSessionId?: string,
  appServerThreadId?: string,
): string | undefined {
  if (agentType === "codex") return appServerThreadId || expectedSessionId;
  return expectedSessionId;
}

// ── Fresh-launch pane readiness ──────────────────────────────────────────────
// Shared by first-message delivery (tryStartedTmux) and discovery below: both
// need to know whether a pane the daemon just launched is at its input prompt.
// The prompt pattern is per client, from the registry: Claude/cursor ❯ or ⏵,
// Codex > at line end, Gemini > at line end or "gemini". It intentionally
// DISAGREES with the shared /[❯›]/ of the resume-readiness / picker paths; the
// registry's promptReadyPattern encodes THIS fresh-launch site. Do not collapse
// the two.
export type StartedPaneState = "ready" | "booting" | "trust" | "fatal" | "gone";

const STARTED_PANE_FATAL_ERRORS = [
  "cannot be launched inside another",
  "command not found",
  "No such file or directory",
  "ENOENT",
];
const TRUST_PROMPT_RE = /trust this folder|safety check|Is this a project/i;

// Pure classification of one pane capture. Only output below the echoed launch
// command is scanned for launch errors (see paneContentAfterLaunchEcho). The
// workspace trust prompt paints a ❯ of its own, so it wins over the prompt
// pattern: a pane showing it is "trust", never "ready".
export function classifyStartedPane(paneContent: string, promptPattern: RegExp): StartedPaneState {
  const agentPane = paneContentAfterLaunchEcho(paneContent);
  if (STARTED_PANE_FATAL_ERRORS.some(e => agentPane.includes(e))) return "fatal";
  if (TRUST_PROMPT_RE.test(paneContent)) return "trust";
  return promptPattern.test(agentPane) ? "ready" : "booting";
}

// Captures and classifies a started pane. Accepts the trust prompt when it is
// showing ("Yes, I trust" is preselected; Enter accepts) and reports "trust" so
// the caller keeps polling. A failed capture is "booting" while the tmux
// session exists and "gone" once it does not.
async function probeStartedPane(entry: StartedSessionInfo): Promise<{ state: StartedPaneState; pane: string }> {
  let paneContent: string;
  try {
    ({ stdout: paneContent } = await tmuxExec(["capture-pane", "-p", "-J", "-t", entry.tmuxSession, "-S", "-20"]));
  } catch {
    const alive = await tmuxExec(["has-session", "-t", entry.tmuxSession]).then(() => true, () => false);
    return { state: alive ? "booting" : "gone", pane: "" };
  }
  const state = classifyStartedPane(paneContent, AGENT_CLIENTS[entry.agentType].promptReadyPattern);
  if (state === "trust") {
    log(`Started session ${entry.tmuxSession} showing trust prompt, sending Enter to accept`);
    await tmuxExec(["send-keys", "-t", entry.tmuxSession, "Enter"]).catch(() => {});
    await new Promise(resolve => setTimeout(resolve, 2000));
  }
  return { state, pane: paneContentAfterLaunchEcho(paneContent) };
}

// Discovery polls every 2s; 60 polls = 120s, the same budget as
// MAX_RESUME_READINESS_POLL_MS, so a boot under load (seven launches in one
// second has been observed) still binds.
const DISCOVERY_POLL_ATTEMPTS = 60;

async function discoverAndLinkSession(
  conversationId: string,
  tmuxSession: string,
  cwd: string,
): Promise<void> {
  const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
  const projectDirName = claudeProjectDirName(cwd);
  const projectDir = path.join(claudeProjectsDir, projectDirName);

  const existingFiles = new Set<string>();
  for (const f of await fs.promises.readdir(projectDir).catch(() => [] as string[])) {
    if (UUID_JSONL_RE.test(f)) existingFiles.add(f);
  }

  const link = async (linkedSessionId: string, how: string): Promise<void> => {
    const startedEntry = startedSessionTmux.get(conversationId);
    const cache = readConversationCache();
    const reverseCache = buildReverseConversationCache(cache);
    if (reverseCache[conversationId]) {
      log(`[DISCOVER] Conversation ${conversationId.slice(0, 12)} already linked to ${reverseCache[conversationId].slice(0, 8)} by another writer`);
      deleteStartedSession(conversationId);
      return;
    }
    cache[linkedSessionId] = conversationId;
    if (conversationCacheRef) {
      conversationCacheRef[linkedSessionId] = conversationId;
    }
    saveConversationCache(cache);
    if (syncServiceRef) {
      // Reconcile project_path/git_root to the real session cwd (see Claude
      // match branch). `cwd` is authoritative here: the pane was launched in it.
      const discoveryGitInfo = await getGitInfo(cwd);
      void pushSessionIdBinding(conversationId, linkedSessionId, cwd, discoveryGitInfo?.repoRoot || discoveryGitInfo?.root);
      registerManagedStartedSession(conversationId, linkedSessionId, tmuxSession);
      if (startedEntry?.sessionId && startedEntry.sessionId !== linkedSessionId) {
        stopManagedSessionHeartbeat(startedEntry.sessionId);
      }
    }
    deleteStartedSession(conversationId);
    log(`[DISCOVER] Linked session ${linkedSessionId.slice(0, 8)} to conversation ${conversationId.slice(0, 12)} via ${how}`);
  };

  for (let attempt = 0; attempt < DISCOVERY_POLL_ATTEMPTS; attempt++) {
    await new Promise(resolve => setTimeout(resolve, 2000));
    const entry = startedSessionTmux.get(conversationId);
    if (!entry) {
      log(`[DISCOVER] Conversation ${conversationId.slice(0, 12)} already linked by watcher, stopping discovery`);
      return;
    }
    // An assigned `--session-id` needs no file to discover: the pane at its
    // input prompt IS the session. Claude writes <uuid>.jsonl only on the first
    // turn, so a new session nobody has typed into has no transcript to find;
    // waiting on the file left every such session unbound after the timeout
    // (its card never left the unstarted state) while the agent sat ready.
    // Binding still waits for the prompt on purpose: an early cache entry would
    // let deliverMessage skip the readiness-gated started-tmux path and paste
    // the first message into a still-booting prompt.
    if (entry.sessionId) {
      const probe = await probeStartedPane(entry);
      if (probe.state === "ready") {
        await link(entry.sessionId, "prompt readiness");
        return;
      }
      if (probe.state === "fatal" || probe.state === "gone") {
        log(`[DISCOVER] Started session ${entry.tmuxSession} is ${probe.state}, stopping discovery for ${conversationId.slice(0, 12)}${probe.pane ? `: ${probe.pane.slice(0, 200)}` : ""}`);
        return;
      }
    }
    const names = await fs.promises.readdir(projectDir).catch(() => null);
    if (!names) continue;
    const candidates: string[] = [];
    for (const f of names) {
      const m = f.match(UUID_JSONL_RE);
      if (!m || existingFiles.has(f)) continue;
      const sessionId = m[1];
      const cache = readConversationCache();
      if (cache[sessionId]) continue;
      candidates.push(sessionId);
    }
    if (candidates.length === 0) continue;
    // Verify which candidate belongs to this tmux session's process
    let linkedSessionId: string | null = null;
    let foundInOtherTmux = false;
    for (const sessionId of candidates) {
      try {
        const proc = await findSessionProcess(sessionId, "claude").catch(() => null);
        if (proc) {
          const tmuxPane = await findTmuxPaneForTty(proc.tty);
          if (tmuxPane && tmuxPane.split(":")[0] === tmuxSession) {
            linkedSessionId = sessionId;
            break;
          } else {
            // Process located but not in our tmux — either a different tmux or
            // no tmux at all (a bare terminal/iTerm session). A web-started
            // session always runs inside its own tmux, so this candidate is
            // not ours regardless. Block the single-candidate fallback below.
            foundInOtherTmux = true;
            log(`[DISCOVER] Candidate ${sessionId.slice(0, 8)} is in ${tmuxPane ? `tmux ${tmuxPane.split(":")[0]}` : "no tmux"}, not ${tmuxSession} — skipping`);
          }
        }
      } catch {}
    }
    // Fall back to single candidate only if process wasn't found at all —
    // if it was found in a different tmux session, it belongs to another conversation
    if (!linkedSessionId && candidates.length === 1 && !foundInOtherTmux) {
      linkedSessionId = candidates[0];
    }
    if (linkedSessionId) {
      await link(linkedSessionId, "JSONL discovery");
      return;
    }
  }
  log(`[DISCOVER] Timed out discovering session for conversation ${conversationId.slice(0, 12)}`);
}

// A daemon restart reloads startedSessionTmux from disk but not the discovery
// polls that were running against those panes. Every persisted pane whose
// conversation is still unlinked gets its discovery restarted, so a restart
// during a boot never leaves a ready agent with an unbound card.
function resumeStartedSessionDiscovery(): void {
  const reverse = buildReverseConversationCache(readConversationCache());
  for (const [conversationId, entry] of startedSessionTmux) {
    if (!entry.sessionId || reverse[conversationId]) continue;
    log(`[DISCOVER] Resuming discovery for ${conversationId.slice(0, 12)} in ${entry.tmuxSession} after restart`);
    discoverAndLinkSession(conversationId, entry.tmuxSession, entry.projectPath).catch(err => {
      log(`Session discovery failed for ${conversationId.slice(0, 12)}: ${err}`);
    });
  }
}

// The resume tmux name is built in resumeCommand.ts (resumeTmuxName /
// resumeShortId), where `cast restart --tmux` can match what this daemon
// builds. Re-exported here for the callers and tests that already import it
// from the daemon.
export { resumeShortId };

function remapConversationSession(
  oldSessionId: string,
  newSessionId: string,
  conversationId: string,
  conversationCache?: ConversationCache,
): void {
  const cache = conversationCache || readConversationCache();
  // Keep the old id as an alias to the same conversation. Transcript copies
  // under the old id survive the remap (a reconstituted agent-* JSONL, the
  // workflow's own subagents/workflows file) and the watcher rediscovers them;
  // an unmapped id gets minted as a fresh conversation with no parent link.
  // Aliased, they re-bind here and the server dedups messages by uuid. Reverse
  // lookups still route to newSessionId — see preferLiveSessionId.
  cache[oldSessionId] = conversationId;
  cache[newSessionId] = conversationId;
  saveConversationCache(cache);
  if (conversationCacheRef) {
    conversationCacheRef[oldSessionId] = conversationId;
    conversationCacheRef[newSessionId] = conversationId;
  }
  resumeSessionCache.delete(oldSessionId);
  stopManagedSessionHeartbeat(oldSessionId);
  stopCodexPermissionPoller(oldSessionId);
  resumeFatalReasons.delete(oldSessionId);
}

const planHandoffChildren = new Map<string, string>();
const planHandoffChecked = new Set<string>();
const planModeSynced = new Set<string>();
const planModePlanMap = new Map<string, string>(); // sessionId -> plan short_id
const planModeTaskMap = new Map<string, Map<string, string>>(); // sessionId -> (localTaskId -> shortId)

const PLAN_MODE_CACHE_FILE = path.join(CONFIG_DIR, "plan-mode-cache.json");

function loadPlanModeCache(): void {
  try {
    if (!fs.existsSync(PLAN_MODE_CACHE_FILE)) return;
    const data = JSON.parse(fs.readFileSync(PLAN_MODE_CACHE_FILE, "utf-8"));
    if (data.synced) for (const s of data.synced) planModeSynced.add(s);
    if (data.plans) for (const [k, v] of Object.entries(data.plans)) planModePlanMap.set(k, v as string);
    if (data.tasks) {
      for (const [sessionId, taskObj] of Object.entries(data.tasks)) {
        const map = new Map<string, string>();
        for (const [localId, shortId] of Object.entries(taskObj as Record<string, string>)) {
          map.set(localId, shortId);
        }
        planModeTaskMap.set(sessionId, map);
      }
    }
  } catch {}
}

function savePlanModeCache(): void {
  try {
    const tasks: Record<string, Record<string, string>> = {};
    for (const [sessionId, map] of planModeTaskMap) {
      tasks[sessionId] = Object.fromEntries(map);
    }
    fs.writeFileSync(PLAN_MODE_CACHE_FILE, JSON.stringify({
      synced: [...planModeSynced],
      plans: Object.fromEntries(planModePlanMap),
      tasks,
    }), { mode: 0o600 });
  } catch {}
}

loadPlanModeCache();

// Track subagent sessions whose parent hasn't been cached yet: childSessionId -> parentSessionId
const pendingSubagentParents = new Map<string, string>();
// Track subagent descriptions read from .meta.json: sessionId -> description
const subagentDescriptions = new Map<string, string>();
// Track tmux sessions spawned by known parent sessions: tmuxSessionName -> parentConversationId
const tmuxSpawnedBySession = new Map<string, string>();

interface CachedProcessInfo {
  pid: number;
  tty: string;
  tmuxTarget?: string;
  termProgram?: string;
  lastVerified: number;
  // When this mapping was FILLED (not last revalidated): the reference point a
  // newer hook-written registry registration supersedes (see
  // registrySupersedesCachedPid — the stale-pid self-heal).
  filledAt: number;
}

const sessionProcessCache = new Map<string, CachedProcessInfo>();
const PROCESS_CACHE_TTL_MS = 30_000;

// ── Registry supersession probe ─────────────────────────────────────────────
// The session's own registry file, read cheaply and memoized: the sync settle
// paths (agentProcessPid → verifiedOpenTasks) consult it on every settle, so
// the read must not hit disk each time. A short TTL keeps the heal window
// close to the cache's own revalidation cadence.
const REGISTRY_PROBE_TTL_MS = 30_000;
const registryProbeCache = new Map<string, { at: number; reg: unknown }>();
function registryRegistrationFor(sessionId: string): unknown {
  const hit = registryProbeCache.get(sessionId);
  if (hit && Date.now() - hit.at < REGISTRY_PROBE_TTL_MS) return hit.reg;
  let reg: unknown = null;
  try {
    reg = JSON.parse(fs.readFileSync(path.join(CONFIG_DIR, "session-registry", `${sessionId}.json`), "utf-8"));
  } catch {
    reg = null;
  }
  // Bounded: entries are per live-ish session; a runaway caller must not grow
  // this without limit.
  if (registryProbeCache.size > 1000) registryProbeCache.clear();
  registryProbeCache.set(sessionId, { at: Date.now(), reg });
  return reg;
}

// Drop a cached session→pid mapping the session's own registry has proven
// stale (a newer hook registration names a different pid). Returns true when
// the entry was dropped; the next discovery re-fills from the registry
// (Strategy 0). This is the self-heal for the "unknown verdict fails open"
// hole: the old pid often can't be CONVICTED as foreign (it has no current
// claims), but the session's own file can still outvote it.
function dropSupersededProcessCacheEntry(sessionId: string): boolean {
  const cached = sessionProcessCache.get(sessionId);
  if (!cached) return false;
  const reg = registryRegistrationFor(sessionId);
  if (!registrySupersedesCachedPid(reg as { pid?: unknown; ts?: unknown; term?: unknown; src?: unknown } | null, cached.pid, cached.filledAt)) return false;
  log(`[IDENTITY] session ${shortId(sessionId)}: registry hook claim names pid ${(reg as { pid: number }).pid}, newer than cached fill — dropping stale cached pid ${cached.pid}`);
  sessionProcessCache.delete(sessionId);
  return true;
}

// Server rows registered with their tmux name, so a later tmux discovery for
// the same session (e.g. a session that started OUTSIDE tmux and was resumed
// into one — registration happens once at first detection, so its row carries
// tmux_session=null forever and the web header never shows the copy-tmux-attach
// icon) re-registers exactly once per name change.
const registeredTmuxBySession = new Map<string, string>();

function cacheSessionProcess(sessionId: string, info: ClaudeSessionInfo, tmuxTarget?: string): void {
  sessionProcessCache.set(sessionId, {
    pid: info.pid,
    tty: info.tty,
    tmuxTarget,
    termProgram: info.termProgram,
    lastVerified: Date.now(),
    filledAt: Date.now(),
  });
  // A fresh fill is a fresh answer — don't let a pre-fill registry probe hide
  // a registration written moments before this mapping was discovered.
  registryProbeCache.delete(sessionId);
  // Backfill tmux_session on the server row when this cache fill is the first
  // place the tmux placement shows up. registerManagedSession patches the
  // existing row by session_id; conversation_id/device_id are omitted so the
  // ownership stamp is untouched.
  const tmuxName = tmuxTarget?.split(":")[0];
  if (tmuxName && syncServiceRef && registeredTmuxBySession.get(sessionId) !== tmuxName) {
    registeredTmuxBySession.set(sessionId, tmuxName);
    // A notOwner refusal is a lease conflict (e.g. the source machine of a
    // reparent still heartbeats its row). Forget the name so a later scan
    // retries — once the conflict clears, the backfill lands without waiting
    // for a daemon restart.
    syncServiceRef.registerManagedSession(sessionId, info.pid, tmuxName).then((res) => {
      if (res && (res as any).notOwner && registeredTmuxBySession.get(sessionId) === tmuxName) {
        registeredTmuxBySession.delete(sessionId);
      }
    }).catch(() => {});
  }
}

async function getCachedSessionProcess(sessionId: string): Promise<ClaudeSessionInfo | null> {
  // Supersession outranks the TTL: a registry hook claim newer than this
  // mapping proves it stale however recently the pid checked out as alive.
  if (dropSupersededProcessCacheEntry(sessionId)) return null;
  const cached = sessionProcessCache.get(sessionId);
  if (!cached) return null;
  if (Date.now() - cached.lastVerified > PROCESS_CACHE_TTL_MS) {
    // Alive, an agent, and still THIS session's agent — a cached pid outlives an
    // in-process /clear or /resume switch as easily as it outlives the process.
    if (!isProcessRunning(cached.pid) || !(await isAgentProcess(cached.pid)) || await rejectsForeignProcess(sessionId, cached.pid, "cache")) {
      sessionProcessCache.delete(sessionId);
      return null;
    }
    cached.lastVerified = Date.now();
  }
  return { pid: cached.pid, tty: cached.tty, sessionId, termProgram: cached.termProgram };
}

async function validateProcessCache(): Promise<void> {
  for (const [sessionId, cached] of sessionProcessCache) {
    if (dropSupersededProcessCacheEntry(sessionId)) continue;
    if (!isProcessRunning(cached.pid) || !(await isAgentProcess(cached.pid))) {
      sessionProcessCache.delete(sessionId);
    }
  }
}

const latestSessionResources = new Map<string, SessionResources>();
const RESOURCE_MONITOR_INTERVAL_MS = 30_000;

// Sleep-aware idle accounting. We accumulate idle time per session only across
// ticks where the machine was awake, so a closed-lid gap never makes a frozen
// session look "idle for hours" the moment it wakes. A session's counter resets
// to 0 whenever it shows activity (CPU above the floor or a working status).
const sessionAwakeIdleMs = new Map<string, number>();
// Last metrics actually pushed per session, so shouldReportMetrics can skip
// re-reporting idle, unchanged sessions every tick (see resourceMonitor.ts).
const lastReportedMetrics = new Map<string, ReportedMetrics>();
let lastResourceTickAt = 0;
// A gap larger than this between resource ticks means the daemon was suspended
// (sleep) or stalled — either way that interval is not real awake-idle time.
const RESOURCE_TICK_SLEEP_GAP_MS = RESOURCE_MONITOR_INTERVAL_MS * 2.5;

export function getLatestSessionResources(): ReadonlyMap<string, SessionResources> {
  return latestSessionResources;
}

export function getSessionAwakeIdleMs(sessionId: string): number {
  return sessionAwakeIdleMs.get(sessionId) ?? 0;
}

async function collectResourceSnapshot(): Promise<void> {
  if (process.platform !== "darwin") return;
  if (sessionProcessCache.size === 0) return;

  // Sessions whose cached pid is borrowed rather than owned (a Codex subagent
  // thread shares its parent's process): they must not be credited with a subtree
  // that isn't theirs, or the parent's usage lands in the fleet total once per
  // child. Fails OPEN — an undecided session keeps reporting, since the cost is a
  // transiently double-counted tree rather than a lost liveness signal.
  const sharedPidSessions = await classifySharedPidSessions([...sessionProcessCache.keys()]);
  // Read after the await: the cache moves while the classification runs.
  const sessionPids = new Map<string, number>();
  for (const [sessionId, info] of sessionProcessCache) sessionPids.set(sessionId, info.pid);

  try {
    const resources = await collectSessionResources(sessionPids, sharedPidSessions);
    latestSessionResources.clear();
    for (const [sessionId, r] of resources) {
      latestSessionResources.set(sessionId, r);
    }

    // Advance per-session awake-idle counters. Skip the very first tick, wake
    // grace, and any oversized gap (sleep/stall) so suspended time is excluded.
    const now = Date.now();
    const elapsed = lastResourceTickAt > 0 ? now - lastResourceTickAt : 0;
    const sleepSkip = lastResourceTickAt === 0 || isInWakeGrace() || elapsed > RESOURCE_TICK_SLEEP_GAP_MS;
    lastResourceTickAt = now;

    for (const [sessionId, r] of resources) {
      sessionAwakeIdleMs.set(sessionId, nextAwakeIdleMs({
        prevIdleMs: sessionAwakeIdleMs.get(sessionId) ?? 0,
        cpu: r.cpu,
        status: lastSentAgentStatus.get(sessionId),
        elapsedMs: elapsed,
        sleepSkip,
        // Never accrue idle time on a cpu=0 we zeroed ourselves — see
        // nextAwakeIdleMs. Before the dedupe a borrower inherited the parent's
        // real CPU, so a busy parent kept resetting this; now nothing would, and
        // the row would drift into the Sessions page's bulk-kill bucket.
        sharesRootPid: r.sharesRootPid,
      }));
    }
    // Drop counters for sessions whose process tree is gone (no longer collected).
    for (const sessionId of sessionAwakeIdleMs.keys()) {
      if (!resources.has(sessionId)) sessionAwakeIdleMs.delete(sessionId);
    }
    for (const sessionId of lastReportedMetrics.keys()) {
      if (!resources.has(sessionId)) lastReportedMetrics.delete(sessionId);
    }

    // Push metrics for every live session here (not only resume-managed ones),
    // so the Sessions page sees fresh metrics — and thus liveness — for anything
    // with a real process tree, including sessions reporting a "stopped" status.
    //
    // Bounded concurrency: firing one mutation per session at once (a burst of N
    // simultaneous POSTs for N live sessions, every tick) saturates the daemon's
    // outbound connection pool and file descriptors, starving the message-sync
    // mutations of sockets so they hang to their 60s timeout while the backend is
    // actually idle. A small worker pool caps in-flight metric requests so syncs
    // always have headroom. Metrics are best-effort and unawaited per-call, so the
    // pool just paces them across the tick.
    let metricsReported = 0;
    let metricsSkipped = 0;
    if (syncServiceRef) {
      const METRICS_CONCURRENCY = 4;
      await runBounded([...resources.entries()], METRICS_CONCURRENCY, async ([sessionId, r]) => {
        const agentPid = sessionProcessCache.get(sessionId)?.pid;
        const status = lastSentAgentStatus.get(sessionId);
        // Skip flat, idle, recently-reported sessions: this is what keeps the
        // per-tick write burst proportional to ACTIVE sessions rather than the
        // whole fleet, leaving socket headroom for message sync.
        // Hold the previously reported start across ps's one-second
        // resolution, so only a real restart changes the value we send.
        const agentStartedAt = stableAgentStartedAt(r.agentStartedAt, lastReportedMetrics.get(sessionId)?.agentStartedAt);
        if (!shouldReportMetrics({ cur: { cpu: r.cpu, memory: r.memory, pidCount: r.pidCount, agentPid, agentStartedAt }, prev: lastReportedMetrics.get(sessionId), status, now })) {
          metricsSkipped++;
          return;
        }
        metricsReported++;
        lastReportedMetrics.set(sessionId, { cpu: r.cpu, memory: r.memory, pidCount: r.pidCount, agentPid, agentStartedAt, at: now });
        await syncServiceRef!.reportSessionMetrics(
          sessionId, r.cpu, r.memory, r.pidCount, agentPid, sessionAwakeIdleMs.get(sessionId) ?? 0, agentStartedAt,
        ).catch(() => {});
      }, "Metrics worker");
    }

    if (resources.size > 0) {
      log(`[RESOURCES] metrics reported=${metricsReported} skipped=${metricsSkipped} (${resources.size} sessions)`);
      log(`[RESOURCES] ${formatResourcesLog(resources)}`, "debug");
    }
  } catch (err) {
    log(`[RESOURCES] Collection failed: ${err instanceof Error ? err.message : String(err)}`, "warn");
  }
}

const LIVENESS_RECONCILE_INTERVAL_MS = 120_000; // 2 min — conservative; daemon is load-sensitive

// Periodic liveness reconciliation for the Sessions page.
//
// sessionProcessCache is otherwise seeded only by event-driven discovery (a
// JSONL write), so a session that goes idle and stops writing is never
// re-tracked after a daemon restart and wrongly shows as "dead". This sweep
// re-establishes the session→pid mapping for every managed_sessions row whose
// agent is still alive, so collectResourceSnapshot reports fresh metrics and the
// page's liveness signal becomes accurate.
//
// Cheap by construction: one Convex query + one `tmux list-panes -a`, then a
// bounded process-tree walk only for rows whose tmux session is actually live.
async function reconcileSessionLiveness(): Promise<void> {
  if (process.platform !== "darwin") return;
  if (!syncServiceRef) return;
  if (isInWakeGrace()) return;

  const catalog = await syncServiceRef.listManagedSessions();
  if (!catalog || catalog.length === 0) return;

  // session_name -> pane_pid for every live pane, in one call.
  const paneByTmux = new Map<string, number>();
  if (hasTmux()) {
    try {
      const { stdout } = await tmuxExec(
        ["list-panes", "-a", "-F", "#{session_name} #{pane_pid}"],
        { timeout: 5000, killSignal: "SIGKILL" },
      );
      for (const line of stdout.trim().split("\n")) {
        const [name, pid] = line.trim().split(/\s+/);
        const n = parseInt(pid, 10);
        if (name && !isNaN(n) && !paneByTmux.has(name)) paneByTmux.set(name, n);
      }
    } catch {}
  }

  // Rows needing resolution (skip ones collectResourceSnapshot already tracks).
  const pending = catalog.filter((row) => !sessionProcessCache.has(row.session_id));

  // Resolve agent pids with bounded concurrency — each resolution is a
  // process-tree walk (pgrep), and doing ~160 sequentially stalls for tens of
  // seconds under load. A small pool keeps the boot sweep to a few seconds
  // without flooding the process table.
  let seeded = 0;
  const CONCURRENCY = 12;
  for (let i = 0; i < pending.length; i += CONCURRENCY) {
    const batch = pending.slice(i, i + CONCURRENCY);
    await Promise.all(batch.map(async (row) => {
      let agentPid: number | null = null;
      const panePid = row.tmux_session ? paneByTmux.get(row.tmux_session) : undefined;
      if (panePid !== undefined) {
        agentPid = await findAgentPidInTree(panePid);
      } else if (row.agent_pid && isProcessRunning(row.agent_pid) && (await isAgentProcess(row.agent_pid))) {
        agentPid = row.agent_pid;
      }
      if (agentPid !== null) {
        cacheSessionProcess(
          row.session_id,
          { pid: agentPid, tty: "", sessionId: row.session_id },
          row.tmux_session,
        );
        seeded++;
      }
    }));
  }

  if (seeded > 0) log(`[LIVENESS] Reconciled ${seeded} live session(s) into process cache`);
}

function resolveSessionId(filePath: string): string {
  const name = path.basename(filePath, ".jsonl");
  if (CLAUDE_UUID_RE.test(name)) return name;
  const parts = filePath.split(path.sep);
  if (parts.includes("subagents")) return name;
  try {
    const head = readFileHead(filePath, 4096);
    const m = head.match(/"sessionId"\s*:\s*"([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})"/i);
    if (m) return m[1];
  } catch {}
  return name;
}

function slugify(text: string, maxLen = 30): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, maxLen)
    .replace(/-+$/, "");
}

/**
 * Ordered, de-duplicated list of tmux sessions to probe for a live agent before
 * spawning a fresh resume session. Priority: the cached resume tmux, then the
 * original started session (cc-<agent>-<convId> from start_session), then the
 * resume-named session. Including the started session is what stops a force-resume
 * of an already-live started session from spawning a parallel cc-resume- tmux and
 * splitting message delivery across two panes.
 */
export function resumeReuseCandidates(
  cachedTmux: string | undefined,
  startedTmux: string | undefined,
  resumeTmux: string,
): string[] {
  const out: string[] = [];
  for (const t of [cachedTmux, startedTmux, resumeTmux]) {
    if (t && !out.includes(t)) out.push(t);
  }
  return out;
}

// Build the `env` prefix for an auto-resume command. Always strips CLAUDECODE so the
// resumed agent doesn't refuse to launch "inside another Claude Code session". For Claude,
// also pushes the "Resume from summary?" thresholds out of reach: that prompt fires for
// old/large sessions (default >70min AND >100k tokens) and blocks the TUI awaiting a choice,
// but a daemon auto-resume has no human at the pane to answer it — so it would wedge forever
// and trip the web stuck-banner into a kill+restart loop. There is no CLI flag for it, only
// these env gates (read by Claude Code as process.env.CLAUDE_CODE_RESUME_THRESHOLD_*).
export function buildResumeEnvPrefix(agentType: string): string {
  return agentType === "claude"
    ? `${AGENT_ENV_SCRUB} CLAUDE_CODE_RESUME_THRESHOLD_MINUTES=999999999 CLAUDE_CODE_RESUME_TOKEN_THRESHOLD=999999999999`
    : AGENT_ENV_SCRUB;
}

// The settings-level transcript pin (agentEnv.ts): idempotent, respects an
// authored value, logs only when it actually writes.
function assertClaudePersistencePin(): void {
  try {
    if (ensureClaudeSettingsPersistence() === "wrote") {
      log("[AGENT-ENV] pinned CLAUDE_CODE_FORCE_SESSION_PERSISTENCE=1 in ~/.claude/settings.json");
    }
  } catch (err) {
    log(`[AGENT-ENV] settings persistence pin failed: ${err instanceof Error ? err.message : String(err)}`);
  }
}

// The same markers persisted in the tmux server's global environment seed every
// new pane before our `env -u` prefix runs (see agentEnv.ts). Clearing them
// there is idempotent and protects panes people open by hand too.
function scrubTmuxGlobalEnv(): void {
  if (!hasTmux()) return;
  for (const v of AGENT_SCRUBBED_ENV_VARS) {
    try { tmuxExecSync(["set-environment", "-gu", v], { timeout: 3000 }); } catch {}
  }
}

interface ResolvedLiveSession {
  /** A live tmux target ready for injection (bare "cc-x" for cache/started/resume-name,
   *  "cc-x:win.pane" for a process-discovered pane), or null if no live tmux was found. */
  tmuxTarget: string | null;
  /** Where the live target came from (logging), or null when no live tmux was found. */
  source: "cache" | "started" | "resume-name" | "process" | null;
  /** The live agent process when discovered by process scan — lets callers fall back to
   *  direct-terminal (AppleScript/CLI) injection for agents not running inside tmux. */
  proc: ClaudeSessionInfo | null;
  /** True when a cached resume tmux existed and passed has-session. */
  cachedStillValid: boolean;
}

/**
 * Single source of truth for "is this session already running, and where do I inject?".
 * Probes, in order: the cached resume tmux, the original started session
 * (cc-<agent>-<convId>), an optional resume-named session, then a live OS process
 * (→ its tmux pane, or the bare process for non-tmux terminal injection). Read-only
 * apart from self-healing cache eviction (drops a cached entry whose tmux is gone or
 * whose agent has died). Both deliverMessage and autoResumeSession route through this
 * so the two delivery paths can never disagree about whether a session is already live.
 */
async function resolveLiveTmuxTarget(
  conversationId: string | undefined,
  sessionId: string,
  agentType: AgentClientId,
  resumeTmuxName?: string,
): Promise<ResolvedLiveSession> {
  const cachedTmux = resumeSessionCache.get(sessionId);
  let cachedStillValid = false;

  const dropCache = () => {
    resumeSessionCache.delete(sessionId);
    stopCodexPermissionPoller(sessionId);
    stopManagedSessionHeartbeat(sessionId);
  };

  // 1. Cached resume tmux — verified before use; self-heals on gone/dead.
  if (cachedTmux) {
    let hasSessionOk = false;
    try {
      await tmuxExec(["has-session", "-t", cachedTmux], { timeout: 3000, killSignal: "SIGKILL" });
      hasSessionOk = true;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      // Only a definitive "no such session" drops the cache — transient tmux errors
      // (timeout, EAGAIN) must not nuke a live mapping; just fall through to other probes.
      if (/can't find session|no such session|session not found/i.test(msg)) {
        logDelivery(`Cached tmux ${cachedTmux} gone (${msg.slice(0, 80)}), clearing cache`);
        dropCache();
      } else {
        logDelivery(`Cached tmux ${cachedTmux} has-session transient error (${msg.slice(0, 80)}), keeping cache and falling through`);
      }
    }
    if (hasSessionOk) {
      cachedStillValid = true;
      let agentAlive = true;
      try { agentAlive = await isTmuxAgentAlive(cachedTmux, sessionId); } catch {}
      if (agentAlive) {
        return { tmuxTarget: cachedTmux, source: "cache", proc: null, cachedStillValid: true };
      }
      // Dead agent: drop the cache (leave the tmux in place) and keep probing.
      logDelivery(`Cached tmux ${cachedTmux} has no live agent, clearing cache (leaving tmux in place)`);
      dropCache();
      cachedStillValid = false;
    }
  }

  // 2/3. Started session, then optional resume-named session — both verified alive.
  const startedTmux = conversationId ? startedSessionTmux.get(conversationId)?.tmuxSession : undefined;
  for (const candidate of resumeReuseCandidates(undefined, startedTmux, resumeTmuxName ?? "")) {
    try {
      await tmuxExec(["has-session", "-t", candidate], { timeout: 3000, killSignal: "SIGKILL" });
      if (await isTmuxAgentAlive(candidate, sessionId)) {
        return {
          tmuxTarget: candidate,
          source: candidate === startedTmux ? "started" : "resume-name",
          proc: null,
          cachedStillValid,
        };
      }
    } catch {}
  }

  // 4. Live OS process → its tmux pane (or the bare process for AppleScript/CLI fallback).
  // Materialized sessions have no running process and CWD+timing heuristics false-positive.
  const isMaterialized = materializedSessions.has(sessionId);
  const proc = isMaterialized ? null : await findSessionProcess(sessionId, agentType);
  if (proc) {
    if (!(await isAgentProcess(proc.pid))) {
      // Leftover shell, not an agent — drop the stale process cache and give up on it.
      sessionProcessCache.delete(sessionId);
      return { tmuxTarget: null, source: null, proc: null, cachedStillValid };
    }
    let pane = await findTmuxPaneForTty(proc.tty);
    // Claude often runs in a tmux pane whose pty mapping isn't visible (nested tmux, fresh
    // pane): fall back to a still-valid cached target rather than the AppleScript path,
    // which would type into the foreground terminal and silently drop the message.
    if (!pane && cachedStillValid && cachedTmux) pane = cachedTmux;
    return { tmuxTarget: pane, source: pane ? "process" : null, proc, cachedStillValid };
  }

  return { tmuxTarget: null, source: null, proc: null, cachedStillValid };
}

async function autoResumeSession(sessionId: string, content: string, titleCache: TitleCache, cwdOverride?: string, conversationId?: string, agentTypeHint?: AgentClientId, opts?: ResumeOptions): Promise<boolean> {
  // Lifecycle gate: a killed/completed conversation must never come back on its
  // own. This is the chokepoint every AUTOMATIC resurrection path funnels through
  // (the health check's reconstitution, message-delivery resume, the warm pool,
  // repairAndResumeSession), so the check lives here rather than at each caller.
  // Fails OPEN on a lookup error.
  if (!opts?.userInitiated && conversationId && await conversationForbidsResurrection(conversationId, sessionId, "RESUME", { trustStatusFallback: false })) {
    return false;
  }

  // Single-owner resume gate — see resumeOwnerVerdict for the two rules it folds
  // together. One owner lookup serves both.
  const ownerInfo = conversationId && syncServiceRef
    ? await syncServiceRef.getConversationOwnerInfo(conversationId)
    : null;
  const verdict = resumeOwnerVerdict({ conversationId, localDeviceId: deviceId(), isRemote: isRemoteDevice(), owner: ownerInfo });
  if (verdict === "owned_by_live_device") {
    log(`[OWNER] skipping resume of ${sessionId.slice(0, 8)} — owned by live device ${ownerInfo!.ownerDeviceId.slice(0, 8)}${ownerInfo!.ownerIsRemote ? " (remote)" : ""} (not ${deviceId().slice(0, 8)})`);
    return false;
  }
  if (verdict === "remote_no_conversation") {
    log(`[OWNER] remote daemon skipping resume of ${sessionId.slice(0, 8)} — no conversation id to verify ownership`);
    return false;
  }
  if (verdict === "remote_unowned") {
    const owner = ownerInfo?.ownerDeviceId;
    log(`[OWNER] remote daemon skipping resume of ${sessionId.slice(0, 8)} — owner=${owner ? owner.slice(0, 8) : "unowned"} (this device ${deviceId().slice(0, 8)})`);
    return false;
  }
  // Deduplicate concurrent resume attempts on the same session
  const existing = resumeInFlight.get(sessionId);
  if (existing) {
    const startedAt = resumeInFlightStarted.get(sessionId) ?? 0;
    const age = Date.now() - startedAt;
    if (age > RESUME_IN_FLIGHT_TIMEOUT_MS) {
      logDelivery(`Resume in-flight for ${sessionId.slice(0, 8)} is stale (${Math.round(age / 1000)}s), clearing and retrying`);
      resumeInFlight.delete(sessionId);
      resumeInFlightStarted.delete(sessionId);
    } else {
      logDelivery(`Resume already in flight for ${sessionId.slice(0, 8)}, waiting (age=${Math.round(age / 1000)}s)...`);
      try {
        const result = await Promise.race([
          existing,
          new Promise<boolean>((_, reject) => setTimeout(() => reject(new Error("resume_timeout")), RESUME_IN_FLIGHT_TIMEOUT_MS - age)),
        ]);
        if (result && content) {
          const tmuxSession = resumeSessionCache.get(sessionId);
          if (tmuxSession) {
            await injectViaTmux(tmuxSession + ":0.0", content, agentTypeHint);
            log(`Injected message to already-resumed session ${sessionId.slice(0, 8)}`);
          }
        }
        return result;
      } catch (err) {
        if (err instanceof Error && err.message === "resume_timeout") {
          logDelivery(`Resume in-flight timed out for ${sessionId.slice(0, 8)}, clearing and retrying`);
          resumeInFlight.delete(sessionId);
          resumeInFlightStarted.delete(sessionId);
        } else {
          throw err;
        }
      }
    }
  }
  const promise = autoResumeSessionInner(sessionId, content, titleCache, cwdOverride, conversationId, agentTypeHint);
  resumeInFlight.set(sessionId, promise);
  resumeInFlightStarted.set(sessionId, Date.now());
  try {
    return await promise;
  } finally {
    resumeInFlight.delete(sessionId);
    resumeInFlightStarted.delete(sessionId);
  }
}

/**
 * The resume tmux for `sessionId` is about to be killed and recreated. If it is
 * occupied by ANOTHER session's live agent (resolveLiveTmuxTarget refused it as
 * foreign), that agent is a squatter in a name that will now be reused: move it
 * to the tmux name its own session resolves to, so its own deliveries keep
 * reaching it and its terminal shows the right session. If that name is already
 * live, the squatter is a second instance of that session writing the same
 * transcript — the kill below is the right end for it, so just say so.
 */
async function relocateForeignOccupant(tmuxSession: string, sessionId: string, agentType: AgentClientId): Promise<void> {
  try {
    const { stdout } = await tmuxExec(["list-panes", "-t", tmuxSession, "-F", "#{pane_pid}"], { timeout: 3000, killSignal: "SIGKILL" });
    const panePid = parseInt(stdout.trim().split("\n")[0] ?? "", 10);
    if (isNaN(panePid)) return;
    const agentPid = await findAgentPidInTree(panePid);
    if (agentPid === null) return;
    const occupant = await processDeclaredSession(agentPid);
    if (!occupant || occupant === sessionId) return;
    const home = resumeTmuxName(agentType, occupant);
    let homeLive = false;
    try {
      await tmuxExec(["has-session", "-t", home], { timeout: 3000, killSignal: "SIGKILL" });
      homeLive = await isTmuxAgentAlive(home, occupant);
    } catch {}
    if (homeLive) {
      log(`[IDENTITY] tmux ${tmuxSession} hosts a second instance of ${shortId(occupant)} (pid=${agentPid}); ${home} is already live — letting the recreate kill it`);
      return;
    }
    try { await tmuxExec(["kill-session", "-t", home]); } catch {}
    await tmuxExec(["rename-session", "-t", tmuxSession, home]);
    await setTmuxSessionOption(home, "@codecast_session_id", occupant);
    resumeSessionCache.set(occupant, home);
    sessionProcessCache.delete(occupant);
    const occupantConv = readConversationCache()[occupant];
    if (syncServiceRef && occupantConv) {
      syncServiceRef.registerManagedSession(occupant, agentPid, home, occupantConv).catch(logConvexFailure);
    }
    log(`[IDENTITY] tmux ${tmuxSession} hosted ${shortId(occupant)} (pid=${agentPid}), not ${shortId(sessionId)} — renamed it to ${home}`);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    // No such tmux is the ordinary case (nothing to relocate); only a real failure is worth a line.
    if (!/can't find|no such session|session not found/i.test(msg)) {
      log(`[IDENTITY] relocate check for ${tmuxSession} failed: ${msg.slice(0, 160)}`);
    }
  }
}

async function autoResumeSessionInner(sessionId: string, content: string, titleCache: TitleCache, cwdOverride?: string, conversationId?: string, agentTypeHint?: AgentClientId): Promise<boolean> {
  if (!hasTmux()) {
    logDelivery(`Cannot auto-resume ${sessionId.slice(0, 8)}: tmux not installed`);
    return false;
  }
  const priorFatalReason = resumeFatalReasons.get(sessionId);
  if (priorFatalReason) {
    logDelivery(`Skipping auto-resume for ${sessionId.slice(0, 8)}: prior fatal reason=${priorFatalReason}`);
    return false;
  }

  // Reuse an already-live, identity-verified agent pane: cache it, inject the
  // pending content, and make sure heartbeat/registration exist. Shared by the
  // cheap probe below and the full pre-recreate probe further down.
  const reuseLiveSession = async (live: ResolvedLiveSession, liveAgentType: AgentClientId): Promise<boolean> => {
    if (!live.tmuxTarget) return false;
    const bareName = live.tmuxTarget.split(":")[0];
    logDelivery(`Session ${resumeShortId(sessionId)} already alive in tmux=${live.tmuxTarget} (${live.source}), reusing`);
    resumeSessionCache.set(sessionId, bareName);
    if (content) {
      await injectViaTmux(live.tmuxTarget.includes(":") ? live.tmuxTarget : live.tmuxTarget + ":0.0", content, liveAgentType);
    }
    // Ensure heartbeat + sync registration exist (may be missing after daemon restart)
    if (syncServiceRef && conversationId && !managedHeartbeatSessions.has(sessionId)) {
      syncServiceRef.registerManagedSession(sessionId, process.pid, bareName, conversationId).catch(logConvexFailure);
      syncServiceRef.updateSessionAgentStatus(conversationId, "connected").catch(logConvexFailure);
      ensureManagedSessionHeartbeat(sessionId);
    }
    return true;
  };

  // FAST PATH: probe for a live pane BEFORE any Convex lookups, JSONL scans or
  // reconstitution. A resume aimed at an already-alive session (the web's
  // stuck-message auto-resume routinely fires while a delivery is in flight)
  // must cost tmux-probe milliseconds, not the full resume preamble — under
  // daemon load that preamble ran ~60s and pushed delivery past the UI's alarm
  // budget, turning a delivered message into a false "hasn't reached the agent".
  // The probe is identity-verified (isTmuxAgentAlive checks the pane's agent
  // declares THIS session), so reuse is safe without the ownership preamble —
  // resume commands are runner-addressed, and a verified-local live agent is
  // this daemon's to feed either way. Only runs with an agent-type hint; the
  // hintless case falls through to the full probe after type detection.
  if (agentTypeHint) {
    try {
      const fastLive = await resolveLiveTmuxTarget(conversationId, sessionId, agentTypeHint, resumeTmuxName(agentTypeHint, sessionId));
      if (await reuseLiveSession(fastLive, agentTypeHint)) return true;
    } catch (err) {
      logDelivery(`Live-session fast probe failed for ${sessionId.slice(0, 8)}, continuing with full resume: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  let sessionFile = findSessionFile(sessionId);
  const config = readConfig();
  // cursor-agent and opencode each own their session store (SQLite: ~/.cursor,
  // ~/.local/share/opencode/opencode.db), and pi/grok own their JSONL trees under
  // ~/.pi and ~/.grok; resume needs no local Claude JSONL for any of them. Trust
  // the store-owned agent type HERE — via the hint, else what findSessionFile
  // detected — before the reconstitution below (mayReconstituteResumeTranscript)
  // can mislabel the session as claude and materialize a bogus Claude JSONL for
  // it, and before the transcript-cwd read (which would parse binary DB bytes).
  // A missing pi/grok file falls through to the refuse branch — an honest
  // failure, not a fabricated claude session.
  const storeOwnedResumeType = agentTypeHint ?? sessionFile?.agentType;
  const isStoreOwnedResume = storeOwnedResumeType === "cursor" || storeOwnedResumeType === "opencode";
  const isCursorResume = agentTypeHint === "cursor";
  if (mayReconstituteResumeTranscript(storeOwnedResumeType) && !sessionFile && conversationId && config?.auth_token && config?.convex_url) {
    logDelivery(`Session ${sessionId.slice(0, 8)} not found locally, reconstituting from codecast...`);
    try {
      const siteUrl = config.convex_url.replace(".cloud", ".site");
      const data = await fetchExport(siteUrl, config.auth_token, conversationId);
      if (data.messages.length === 0) {
        logDelivery(`Reconstitution skipped for ${sessionId.slice(0, 8)}: conversation has 0 messages`);
        return false;
      }
      const reconAgentType = agentTypeHint || (data.conversation.agent_type === "codex" ? "codex" : undefined) || "claude";
      let jsonl: string;
      let reconId: string;
      if (reconAgentType === "codex") {
        ({ jsonl, sessionId: reconId } = generateCodexJsonl(data, { sessionId }));
      } else {
        const tailMessages = chooseClaudeAutoTrim(data);
        ({ jsonl, sessionId: reconId } = generateClaudeCodeJsonl(data, { tailMessages, sessionId }));
      }
      // Write under the same cwd the resume will run in (see localSessionDir):
      // a valid override wins, otherwise the locally-resolved repo path.
      const reconDir = (cwdOverride && fs.existsSync(cwdOverride))
        ? cwdOverride
        : localSessionDir(data.conversation.project_path || undefined);
      const result = reconAgentType === "codex"
        ? writeCodexSession(jsonl, reconId)
        : writeClaudeCodeSession(jsonl, reconId, reconDir);
      logDelivery(`Reconstituted ${sessionId.slice(0, 8)} (${data.messages.length} msgs)`);
      if (conversationId && reconId !== sessionId) {
        remapConversationSession(sessionId, reconId, conversationId);
        if (syncServiceRef) {
          void pushSessionIdBinding(conversationId, reconId);
        }
      } else if (conversationId) {
        // Ensure cache has the mapping even when sessionId is preserved
        const cache = readConversationCache();
        cache[sessionId] = conversationId;
        saveConversationCache(cache);
        if (conversationCacheRef) conversationCacheRef[sessionId] = conversationId;
      }
      sessionId = reconId;
      sessionFile = findSessionFile(reconId);
      if (!sessionFile) {
        logDelivery(`Reconstituted file not found at expected path: ${result.filePath}`);
        return false;
      }
    } catch (err) {
      logDelivery(`Reconstitution failed for ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
      return false;
    }
  } else if (!sessionFile && !isStoreOwnedResume) {
    logDelivery(`Cannot auto-resume ${sessionId.slice(0, 8)}: session JSONL file not found${!conversationId ? " (no conversation ID for reconstitution)" : ""}`);
    return false;
  }

  // Every caller lands here (delivery, kill & restart, `cast restart <id>`):
  // a Workflow-tool agent transcript is never resumed as a session of its own.
  const workflowAgentTranscript = workflowAgentTranscriptPathFor(sessionId);
  if (workflowAgentTranscript) {
    logDelivery(`Cannot auto-resume ${sessionId.slice(0, 8)}: workflow agent transcript (${workflowAgentTranscript}) — the host session owns it`);
    return false;
  }

  const agentType: AgentClientId = resolveResumeAgentType(agentTypeHint, sessionFile?.agentType);
  // Backstop against a poisoned session id (RCE): the resume line below is built by
  // interpolating this id and then TYPED INTO A LIVE SHELL via `tmux send-keys -l`.
  // The watchers now refuse to ingest a malformed id, but a row poisoned before that
  // fix can still arrive from convex as the authoritative session_id — refuse it here
  // (both the claude and non-claude branches converge on this id) rather than build a
  // command around shell metacharacters. Honest failure, no execution; the fatal
  // reason stops the resume-retry loop from re-attempting it forever.
  if (!isValidResumeSessionId(agentType, sessionId)) {
    log(`[SECURITY] Refusing resume of ${agentType} session with malformed id: ${JSON.stringify(sessionId.slice(0, 80))}`);
    resumeFatalReasons.set(sessionId, "invalid_session_id");
    return false;
  }
  const jsonlPath = isStoreOwnedResume ? "" : sessionFile!.path;
  const jsonlContent = isStoreOwnedResume ? "" : readFileHead(jsonlPath, 5000);

  let cwd: string;
  let resumeCmd: string;
  const shortId = resumeShortId(sessionId);
  const title = titleCache[sessionId] || (jsonlContent ? extractSummaryTitle(jsonlContent) : "");
  const slug = title ? slugify(title) : "";

  if (isStoreOwnedResume) {
    // No local transcript to recover a cwd from (cursor/opencode keep it in their
    // own store); prefer an explicit override, else the conversation's recorded
    // project path, else $HOME.
    const projectPath = conversationId && syncServiceRef
      ? (await syncServiceRef.getProjectInfo(conversationId).catch(() => null))?.project_path ?? undefined
      : undefined;
    cwd = (cwdOverride && fs.existsSync(cwdOverride)) ? cwdOverride
      : (projectPath && fs.existsSync(projectPath)) ? projectPath
      : (process.env.HOME || "/tmp");
  } else {
    // Resolve where to resume. A recorded transcript cwd we can't map to a local
    // checkout means refusing (mirrors start_session) — NOT $HOME, which would run
    // the agent in the wrong dir and mislabel the project as the home dir. Gemini
    // transcripts carry no cwd, so they have nothing to refuse on and keep $HOME.
    const recordedCwd =
      agentType === "codex" ? (extractCodexCwd(jsonlContent) || undefined)
      : agentType === "gemini" ? undefined
      // grok's updates.jsonl carries no cwd — the sibling summary.json (info.cwd)
      // is authoritative, with the encoded dir name as fallback.
      : agentType === "grok" ? grokSessionCwdFromTranscriptPath(jsonlPath)
      : (extractCwd(jsonlContent) || undefined);
    const resolvedCwd = await resolveResumeCwdOrRefuse({ recordedCwd, cwdOverride, conversationId });
    if (resolvedCwd) {
      cwd = resolvedCwd;
    } else if (agentType === "gemini" && !recordedCwd) {
      cwd = process.env.HOME || "/tmp";
    } else {
      await refuseResumeNoLocalCheckout(sessionId, conversationId, recordedCwd);
      return false;
    }
  }

  // grok gets its configured args + permission flags on resume too: its
  // permission mode is a launch flag (never persisted in the session dir), so a
  // bare `grok --resume <id>` would re-enter Ask mode and park on TUI prompts
  // nobody can answer. getPermissionFlags already yields null when
  // agent_args.grok pins a mode, so the flags can't double up.
  // Per-session account twin of the effort fallback below: set from the
  // conversation row inside the claude branch, sourced on the resume line.
  let resumeAccountPrefix = "";
  const nonClaudeResumeCmd = buildNonClaudeResumeCommand(agentType, sessionId, {
    codexArgs: getAgentArgs(config, "codex"),
    codexPermFlags: agentType === "codex" ? getPermissionFlags("codex", config) : null,
    grokArgs: getAgentArgs(config, "grok"),
    grokPermFlags: agentType === "grok" ? getPermissionFlags("grok", config) : null,
  });
  if (nonClaudeResumeCmd !== null) {
    // codex / gemini / cursor: a single self-contained resume invocation. The
    // Claude-only repair machinery below (UUID rewrite, JSONL relocation,
    // model/effort recovery) does NOT run for these — their transcripts and
    // session ids are their own.
    resumeCmd = nonClaudeResumeCmd;
  } else {
    const jsonlBypass = extractJsonlPermissionMode(jsonlContent) === "bypassPermissions";
    const extraFlags = combineClaudeResumeFlags(
      getAgentArgs(config, "claude"),
      getPermissionFlags("claude", config),
      jsonlBypass,
    );
    let resumeId = sessionId;
    let resumeJsonlPath = jsonlPath;
    try {
      const rewrite = rewriteSubagentJsonlToUuid(sessionId, jsonlPath);
      if (rewrite.rewrote) {
        log(`Copied non-UUID session ${sessionId} to resumable UUID ${rewrite.resumeId}`);
        resumeId = rewrite.resumeId;
        if (rewrite.newJsonlPath) resumeJsonlPath = rewrite.newJsonlPath;
        // Remap all caches so subsequent lookups use the new UUID
        if (conversationId) {
          remapConversationSession(sessionId, rewrite.resumeId, conversationId);
          if (syncServiceRef) {
            void pushSessionIdBinding(conversationId, rewrite.resumeId);
          }
        }
        // A fork-artifact source must go immediately: the remap above just
        // unmapped it, and the sync watcher processes new files within
        // ~500ms — left behind, it gets rediscovered as an unknown session
        // and minted a frozen doppelgänger conversation.
        if (removeForkArtifactJsonl(sessionId, jsonlPath)) {
          log(`Removed fork artifact JSONL for ${sessionId.slice(0, 28)} after UUID copy`);
        }
      }
    } catch (err) {
      log(`Failed to copy session for UUID resume: ${err instanceof Error ? err.message : String(err)}`);
    }
    // Guarantee the session JSONL lives under the slug of the cwd we're about to
    // resume in. findSessionFile() searches *every* project dir, so it can return
    // a copy written under another machine's path (e.g. a fork whose origin was
    // /Users/<other>/...). `claude --resume` only scans its own cwd's project dir,
    // so relocate the file there or Claude reports "No conversation found with
    // session ID" and crashes. This also self-heals stale wrong-dir JSONLs left by
    // earlier runs.
    try {
      const resumeFile = findSessionFile(resumeId);
      if (resumeFile) {
        const cwdProjectDir = path.join(process.env.HOME || "", ".claude", "projects", claudeProjectDirName(cwd));
        const desiredPath = path.join(cwdProjectDir, `${resumeId}.jsonl`);
        if (path.resolve(resumeFile.path) !== path.resolve(desiredPath)) {
          fs.mkdirSync(cwdProjectDir, { recursive: true });
          fs.copyFileSync(resumeFile.path, desiredPath);
          log(`Relocated session ${resumeId.slice(0, 8)} JSONL into resume cwd dir (${cwd})`);
        }
      }
    } catch (err) {
      log(`Failed to relocate session JSONL for ${resumeId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
    }
    // Override the recorded model with its short alias so the resume never lands
    // on a retired pinned snapshot. Scans the file itself, not the small head
    // window read above — the first assistant line (where the model field first
    // appears) can sit well past it. Reads the UUID copy when one was made:
    // the fork-artifact source is deleted above.
    const modelFlag = resumeModelFlagFromFile(resumeJsonlPath, extraFlags);
    // Effort twin: transcript switch echoes win; else the conversation row
    // (a session launched with --effort that never switched in-session leaves
    // no transcript trace, so without this a restart silently drops it).
    let effortFlag = resumeEffortFlagFromFile(resumeJsonlPath, extraFlags);
    // One row read serves both fallbacks: effort (above) and the per-session
    // account. The account has no transcript echo at all — CLAUDE_CODE_OAUTH_TOKEN
    // is read at process start — so without this a restart lands the session on
    // the keychain login (verified 2026-09-01: `/status` flips from
    // "Auth token: CLAUDE_CODE_OAUTH_TOKEN" to "Login method: Claude Max account").
    const convInfo = conversationId && syncServiceRef
      ? await syncServiceRef.getProjectInfo(conversationId).catch(() => null)
      : null;
    if (!effortFlag && !/(^|\s)--effort(\s|=)/.test(extraFlags)) {
      const convEffort = convInfo?.effort;
      if (convEffort && /^[a-z]+$/.test(convEffort)) effortFlag = ` --effort ${convEffort}`;
    }
    resumeAccountPrefix = accountSourcePrefix(convInfo?.cc_account ?? undefined, log);
    resumeCmd = `${launchBinary("claude", { warn: log })} --resume ${resumeId}${modelFlag}${effortFlag}${extraFlags ? " " + extraFlags : ""}`;
  }

  const tmuxSession = resumeTmuxName(agentType, sessionId, slug);

  // Check if this session already has a healthy agent running (avoid killing + recreating).
  // resolveLiveTmuxTarget probes the cached resume tmux, the original started session
  // (cc-<agent>-<convId>), this resume-named session, and any live process — reusing the
  // first with a live agent. The started-session probe is what prevents a force-resume of
  // an already-live started session from spawning a parallel cc-resume- tmux and splitting
  // delivery across two panes.
  const live = await resolveLiveTmuxTarget(conversationId, sessionId, agentType, tmuxSession);
  if (await reuseLiveSession(live, agentType)) return true;

  try {
    await relocateForeignOccupant(tmuxSession, sessionId, agentType);
    try { await tmuxExec(["kill-session", "-t", tmuxSession]); } catch {}

    try {
      await tmuxExec(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", tmuxSession, "-c", cwd]);
    } catch (createErr) {
      // The kill above just removed this name, so "duplicate session" can only mean
      // a CONCURRENT resume recreated it between the two calls. Typing our command
      // line into that pane would stack a second `claude --resume` on top of the one
      // already booting there, and returning false sends the caller into
      // reconstitution — rewriting the JSONL under a live boot. Yield to the other
      // resume instead: it owns the pane and reports its own readiness.
      const msg = createErr instanceof Error ? createErr.message : String(createErr);
      if (!msg.includes("duplicate session")) throw createErr;
      logDelivery(`Resume of ${shortId} yielding: tmux ${tmuxSession} was recreated by a concurrent resume`);
      resumeSessionCache.set(sessionId, tmuxSession);
      return true;
    }
    await setTmuxSessionOption(tmuxSession, "@codecast_session_id", sessionId);
    await setTmuxSessionOption(tmuxSession, "@codecast_agent_type", agentType);

    // See buildResumeEnvPrefix: strips CLAUDECODE and (for Claude) suppresses the
    // "Resume from summary?" prompt that would otherwise wedge an unattended auto-resume.
    const resumeEnvPrefix = buildResumeEnvPrefix(agentType);
    // Same managed-key injection as a fresh launch, so a resumed opencode/pi
    // session gets its provider key too (pl-207).
    const resumeKeyPrefix = providerKeySourcePrefix(agentType, CONFIG_DIR);
    // disclaimPrefix: resumed agents carry their own TCC identity, same as a
    // fresh launch (resumeEnvPrefix always starts with `env`, so the wrapper's
    // plain-argv exec contract holds).
    await tmuxExec(["send-keys", "-t", tmuxSession, "-l", `${resumeAccountPrefix}${resumeKeyPrefix}${disclaimPrefix()}${resumeEnvPrefix} ${resumeCmd}`]);
    await tmuxExec(["send-keys", "-t", tmuxSession, "Enter"]);

    logDelivery(`Auto-resumed ${agentType} ${shortId} in tmux=${tmuxSession} cwd=${cwd} cmd=${resumeCmd}`);

    // Register managed session early with "resuming" status — will transition to "connected" once prompt is visible
    resumeSessionCache.set(sessionId, tmuxSession);
    if (syncServiceRef && conversationId) {
      syncServiceRef.registerManagedSession(sessionId, process.pid, tmuxSession, conversationId).catch(logConvexFailure);
      syncServiceRef.updateSessionAgentStatus(conversationId, "resuming").catch(logConvexFailure);
      stopManagedSessionHeartbeat(sessionId);
      ensureManagedSessionHeartbeat(sessionId);

      // Start tmux pane monitoring for Codex permission prompts
      if (agentType === "codex" && conversationId) {
        startCodexPermissionPoller(sessionId, tmuxSession, conversationId, syncServiceRef);
      }
    }

    // Poll for agent readiness - check every 250ms, bail on fatal errors
    // Must see the input prompt (❯ for Claude, › for Codex) to know the TUI is ready
    const fatalErrors = [
      "cannot be launched inside another",
      "command not found",
      "No such file or directory",
      "Session not found",
      "No conversation found",
      "is not an object",
      "ENOENT",
    ];
        // The glyph-prompt clients settle on ❯/›; the GLYPHLESS_PROMPT_CLIENTS
        // (opencode's footer, pi's box + status bar, grok's persistent-glyph
        // composer) watch their registry readiness patterns instead — one lookup,
        // not a per-client ternary, so a new registry client is never silently
        // classified with claude's glyphs.
        const promptPattern = glyphlessPromptPattern(agentType) ?? /[❯›]/;
    // Scale readiness poll based on JSONL file size — large sessions take much longer to resume
    let jsonlSize = 0;
    try { jsonlSize = fs.statSync(jsonlPath).size; } catch {}
    const maxPollMs = resumeReadinessPollMs(jsonlSize);
    const startTime = Date.now();
    let ready = false;

    // Deadline, not an iteration count. The old `maxPollMs / 250` loop assumed a
    // capture-pane was free; each one actually costs 150-800ms depending on how
    // many panes the tmux server holds, so a nominal 30s budget burned 128s of
    // wall clock on a busy box (70+ panes here). That overrun is what pushed a
    // single resume past the in-flight guard and let a second one collide with it.
    while (Date.now() - startTime < maxPollMs) {
        await new Promise(resolve => setTimeout(resolve, 250));
        try {
          const { stdout: paneContent } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmuxSession, "-S", "-20"]);
          // Scan only output below the echoed launch command — shell rc noise
          // above it must not read as an agent crash (see paneContentAfterLaunchEcho).
          const agentPane = paneContentAfterLaunchEcho(paneContent);
          if (fatalErrors.some(e => agentPane.includes(e))) {
            const fatalReason = agentType === "claude" ? classifyClaudeResumeFatalReason(agentPane) : null;
            if (fatalReason) {
              resumeFatalReasons.set(sessionId, fatalReason);
            }
            logDelivery(`Auto-resume FATAL for ${shortId}: agent crashed. Pane: ${agentPane.slice(0, 300)}`);
            try { await tmuxExec(["kill-session", "-t", tmuxSession]); } catch {}
            return false;
          }
          // The resume exited straight back to a bare shell (Claude prints "Resume this
          // session with: …" on exit; a failed launch leaves a shell command-not-found).
          // This is the failure that produced "SESSION_EXITED: agent has exited" — the
          // old poll didn't recognize it, waited the full window, then pasted into the
          // dead shell. Detect it and abort fast WITHOUT recording a fatal reason: a
          // bare-shell exit is transient (an identical resume succeeds moments later once
          // any prior holder is gone), so the delivery loop's short-cooldown retry path
          // takes over instead of locking the session for 5 minutes.
          if (classifyTmuxLiveState(extractTmuxLiveRegion(agentPane)) === "exited") {
            logDelivery(`Auto-resume EXITED for ${shortId}: resume dropped to a bare shell, aborting (transient). Pane: ${agentPane.slice(-200)}`);
            try { await tmuxExec(["kill-session", "-t", tmuxSession]); } catch {}
            return false;
          }
          if (promptPattern.test(agentPane) && await isTmuxAgentAlive(tmuxSession)) {
            // A bare ❯/› also renders as the cursor of a blocking selection menu (e.g. Claude's
            // "Resume from summary?" prompt). Matching that would publish a false "connected" while
            // the agent is frozen awaiting a choice. Keep polling until the menu clears. Only guard
            // against option menus (isConfirmation false) — "press enter to continue" warnings are
            // cleared by the Escape pass below, so they must not block readiness here.
            const blockingMenu = parseInteractivePrompt(paneContent);
            if (blockingMenu && !blockingMenu.isConfirmation) {
              continue;
            }
            resumeFatalReasons.delete(sessionId);
            logDelivery(`Agent ${shortId} ready (prompt visible) after ${Date.now() - startTime}ms`);
            ready = true;
            break;
          }
      } catch {}
    }
    if (!ready) {
      const alive = await isTmuxAgentAlive(tmuxSession).catch(() => false);
      if (!alive) {
        logDelivery(`Agent ${shortId} startup timed out after ${Date.now() - startTime}ms and agent is not alive, marking stopped`);
        try { await tmuxExec(["kill-session", "-t", tmuxSession]); } catch {}
        resumeSessionCache.delete(sessionId);
        stopManagedSessionHeartbeat(sessionId);
        if (syncServiceRef && conversationId) {
          sendAgentStatus(syncServiceRef, conversationId, sessionId, "stopped");
        }
        return false;
      }
      logDelivery(`Agent ${shortId} startup timed out after ${Date.now() - startTime}ms (max=${maxPollMs}ms, jsonl=${Math.round(jsonlSize / 1024)}KB) but agent process alive, proceeding`);
    }

    // Transition to "connected" only when we actually saw the input prompt. On a timeout-but-alive
    // resume we don't know the agent is interactive yet, so leave it "resuming" — the next hook event
    // (working/idle) will correct it. Reporting "connected" prematurely is exactly the false-live
    // signal that lets the web watchdog escalate to a destructive kill+restart.
    if (ready && syncServiceRef && conversationId) {
      syncServiceRef.updateSessionAgentStatus(conversationId, "connected").catch(logConvexFailure);
    }

    // Dismiss startup warnings (model mismatch, rate limit) before injection
    // These warnings block the prompt -- send Escape then Enter to clear them
    if (ready || !content) {
      try {
        const { stdout: preInjectPane } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmuxSession, "-S", "-15"]);
        const warningPatterns = /⚠|recorded with model|weekly limit|Update available|Press enter to continue/;
        if (warningPatterns.test(preInjectPane)) {
          logDelivery(`Clearing startup warnings for ${shortId} before injection`);
          await tmuxExec(["send-keys", "-t", tmuxSession, "Escape"]);
          await new Promise(resolve => setTimeout(resolve, 300));
          // Wait for the prompt to appear after clearing warnings
          for (let w = 0; w < 20; w++) {
            await new Promise(resolve => setTimeout(resolve, 250));
            try {
              const { stdout: cleared } = await tmuxExec(["capture-pane", "-p", "-J", "-t", tmuxSession, "-S", "-5"]);
              if (promptPattern.test(cleared.split("\n").slice(-3).join("\n"))) break;
            } catch {}
          }
        }
      } catch {}
    }

    // Inject the message (skip if empty — resume-only mode)
    if (content) {
      await injectViaTmux(tmuxSession + ":0.0", content, agentType);
      log(`Injected message to auto-resumed ${agentType} session ${shortId}`);
    } else {
      log(`Auto-resumed ${agentType} session ${shortId} (no message to inject)`);
    }

    return true;
  } catch (err) {
    logDelivery(`Auto-resume EXCEPTION ${agentType} ${shortId}: ${err instanceof Error ? err.message : String(err)}`);
    return false;
  }
}

const repairAttempts = new Map<string, number>();
const REPAIR_COOLDOWN_MS = 60 * 1000;
const repairInFlight = new Map<string, Promise<boolean>>();

// codecast owns a transcript GENERATOR for exactly two clients — claude and codex
// (generateClaudeCodeJsonl / generateCodexJsonl). Every other client keeps its
// session in a store we do NOT produce: cursor/opencode in SQLite, pi/gemini/grok
// in their own JSONL dialects (grok: ~/.grok/sessions/<enc-cwd>/<uuid>/). So
// repairing/materializing/reconstituting a Claude-or-Codex JSONL for them is
// invalid, and when the write targets the client's own file it is DESTRUCTIVE —
// the opencode repair path copied opencode.db → .bak then wrote a Claude JSONL
// over the shared ~/.local/share/opencode/opencode.db, clobbering every session
// in it (ct-39174 / ct-39178). These clients recover by a plain re-resume; never
// regenerate a transcript for them.
export function clientOwnsSessionStore(agentType: AgentClientId | undefined | null): boolean {
  return agentType != null && agentType !== "claude" && agentType !== "codex";
}

// The resume paths' twin of clientOwnsSessionStore: may a resume with NO local
// transcript fabricate one from the convex export? Only for the clients whose
// missing-transcript recovery has always been a local reconstitution — claude,
// codex, and an unhinted resume (which defaults to claude downstream). gemini is
// grandfathered: its reconstitution has always produced a claude-labeled JSONL
// and changing that is not this guard's job. Everything else (cursor, opencode,
// pi, grok) owns its session store: a missing transcript falls to the refuse /
// fresh-spawn branch — an honest failure, never a fabricated Claude JSONL. Both
// enumeration sites (autoResumeSessionInner and the resume_session handler) call
// THIS predicate, so a new client is excluded by default instead of silently
// joining the claude fallback.
export function mayReconstituteResumeTranscript(agentType: AgentClientId | undefined | null): boolean {
  return agentType == null || agentType === "claude" || agentType === "codex" || agentType === "gemini";
}

async function repairAndResumeSession(
  sessionId: string,
  content: string,
  titleCache: TitleCache,
  cwdOverride?: string,
  conversationId?: string,
  agentTypeHint?: AgentClientId,
  opts?: ResumeOptions
): Promise<boolean> {
  const existing = repairInFlight.get(sessionId);
  if (existing) return existing;

  const cooldownKey = conversationId || sessionId;
  const lastAttempt = repairAttempts.get(cooldownKey) || repairAttempts.get(sessionId);
  if (lastAttempt && Date.now() - lastAttempt < REPAIR_COOLDOWN_MS) {
    log(`Repair cooldown active for ${sessionId.slice(0, 8)} (conv=${conversationId?.slice(0, 8) ?? "?"}), skipping`);
    return false;
  }

  // A Workflow-tool agent has no standalone session to repair into: regenerating
  // its transcript from Convex overwrites the host run's agent file (the
  // `.bak` + truncated `agent-*.jsonl` pairs of 2026-08-20) and the resume is
  // refused downstream anyway. Stop before touching the disk.
  const workflowAgentTranscript = workflowAgentTranscriptPathFor(sessionId);
  if (workflowAgentTranscript) {
    log(`Cannot repair ${sessionId.slice(0, 8)}: workflow agent transcript (${workflowAgentTranscript}) — the host session owns it`);
    return false;
  }

  // A store-owned client (cursor/opencode/pi) has no local Claude/Codex JSONL to
  // repair — regenerating one and writing it over the client's own store corrupts
  // it (opencode's shared SQLite db, ct-39174/ct-39178). The prior guard checked
  // only agentTypeHint, so a caller that passed no hint (e.g. the retry/heal paths)
  // sent an opencode session straight into Claude regeneration and clobbered the db.
  // Resolve the type from the hint OR the on-disk session file (findSessionFile has
  // no cursor lookup, hence the hint) and re-resume instead of touching a transcript.
  const repairType = agentTypeHint ?? findSessionFile(sessionId)?.agentType ?? "claude";
  if (clientOwnsSessionStore(repairType)) {
    log(`Repairing ${repairType} session ${sessionId.slice(0, 8)} = re-resume (${repairType} owns its session store; no Claude/Codex JSONL to regenerate)`);
    return autoResumeSession(sessionId, content, titleCache, cwdOverride, conversationId, repairType, opts);
  }

  const promise = (async (): Promise<boolean> => {
    let success = false;

    try {
      const config = readConfig();
      if (!config?.convex_url || !config?.auth_token) {
        log(`Cannot repair session: missing config`);
        return false;
      }

      const convId = conversationId || (() => {
        const cache = readConversationCache();
        return cache[sessionId];
      })();

      if (!convId) {
        log(`Cannot repair ${sessionId.slice(0, 8)}: no conversation_id found`);
        return false;
      }

      const siteUrl = config.convex_url.replace(".cloud", ".site");

      try {
        log(`Repairing session ${sessionId.slice(0, 8)} via Convex regeneration...`);
        const exportData = await fetchExport(siteUrl, config.auth_token!, convId);
        if (exportData.messages.length === 0) {
          log(`Repair aborted for ${sessionId.slice(0, 8)}: conversation has 0 messages, nothing to resume`);
          return false;
        }
        const sessionFile = findSessionFile(sessionId);
        const agentType = agentTypeHint || sessionFile?.agentType || "claude";
        const isCodexSession = agentType === "codex";
        const failureReason = !isCodexSession ? resumeFatalReasons.get(sessionId) ?? null : null;
        const projectPath = cwdOverride || exportData.conversation.project_path || undefined;

        let jsonl: string;
        let tailMessages: number | undefined;
        let targetSessionId = sessionId;

        if (isCodexSession) {
          ({ jsonl } = generateCodexJsonl(exportData, { sessionId }));
        } else {
          const TOKEN_BUDGET = CLAUDE_AUTO_TRIM_TARGET_TOKENS;
          tailMessages = chooseClaudeTailMessagesForTokenBudget(exportData, TOKEN_BUDGET);
          if (shouldMaterializeFreshClaudeSession(failureReason)) {
            const generated = generateClaudeCodeJsonl(exportData, { tailMessages });
            jsonl = generated.jsonl;
            targetSessionId = generated.sessionId;
          } else {
            ({ jsonl } = generateClaudeCodeJsonl(exportData, { tailMessages, sessionId }));
          }
        }

        if (targetSessionId !== sessionId) {
          const { filePath: repairFilePath } = writeClaudeCodeSession(jsonl, targetSessionId, localSessionDir(projectPath));
          setPosition(repairFilePath, fs.statSync(repairFilePath).size);
          remapConversationSession(sessionId, targetSessionId, convId);
          if (titleCache[sessionId] && !titleCache[targetSessionId]) {
            titleCache[targetSessionId] = titleCache[sessionId];
            saveTitleCache(titleCache);
          }
          if (syncServiceRef) {
            void pushSessionIdBinding(convId, targetSessionId);
          }
          log(`Materialized fresh Claude session ${targetSessionId.slice(0, 8)} from stale ${sessionId.slice(0, 8)} (${exportData.messages.length} messages, tail=${tailMessages})`);

          const resumed = await autoResumeSession(targetSessionId, content, titleCache, cwdOverride || projectPath, convId, agentTypeHint, opts);
          if (resumed) {
            log(`Repair + resume succeeded for ${sessionId.slice(0, 8)} via fresh session ${targetSessionId.slice(0, 8)}`);
            success = true;
            return true;
          }
        } else if (sessionFile) {
          const bakPath = sessionFile.path + ".bak";
          if (!fs.existsSync(bakPath)) {
            fs.copyFileSync(sessionFile.path, bakPath);
          }
          fs.writeFileSync(sessionFile.path, jsonl);
          if (isCodexSession) {
            log(`Repaired Codex JSONL for ${sessionId.slice(0, 8)} (${exportData.messages.length} messages)`);
          } else {
            log(`Repaired JSONL for ${sessionId.slice(0, 8)} (${exportData.messages.length} messages, tail=${tailMessages})`);
          }
        } else if (isCodexSession) {
          writeCodexSession(jsonl, sessionId, "rollout");
          log(`Wrote new Codex session file for ${sessionId.slice(0, 8)}`);
        } else {
          const { filePath: repairFilePath } = writeClaudeCodeSession(jsonl, sessionId, localSessionDir(projectPath));
          setPosition(repairFilePath, fs.statSync(repairFilePath).size);
          log(`Wrote new session file for ${sessionId.slice(0, 8)}`);
        }

        const resumed = await autoResumeSession(sessionId, content, titleCache, cwdOverride || projectPath, convId, agentTypeHint, opts);
        if (resumed) {
          log(`Repair + resume succeeded for ${sessionId.slice(0, 8)}`);
          success = true;
          return true;
        }
      } catch (err) {
        log(`Convex regeneration failed for ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
      }

      try {
        const sessionFile = findSessionFile(sessionId);
        if (!sessionFile) return false;

        log(`Attempting surgical JSONL cleanup for ${sessionId.slice(0, 8)}...`);
        const lines = fs.readFileSync(sessionFile.path, "utf-8").split("\n").filter(l => l.trim());
        const cleanLines: string[] = [];
        let removed = 0;

        for (const line of lines) {
          try {
            const parsed = JSON.parse(line);
            const content = parsed.message?.content;
            if (Array.isArray(content)) {
              const hasCorruptToolResult = content.some((c: any) =>
                c.type === "tool_result" && c.content && typeof c.content === "string" &&
                (c.content.includes("is not an object") || c.content.includes("undefined"))
              );
              if (hasCorruptToolResult) {
                removed++;
                continue;
              }
            }
            cleanLines.push(line);
          } catch {
            cleanLines.push(line);
          }
        }

        if (removed > 0) {
          const bakPath = sessionFile.path + ".bak";
          if (!fs.existsSync(bakPath)) {
            fs.copyFileSync(sessionFile.path, bakPath);
          }
          fs.writeFileSync(sessionFile.path, cleanLines.join("\n") + "\n");
          log(`Surgical cleanup: removed ${removed} corrupt entries from ${sessionId.slice(0, 8)}`);

          const resumed = await autoResumeSession(sessionId, content, titleCache, cwdOverride, convId, agentTypeHint, opts);
          if (resumed) {
            log(`Surgical repair + resume succeeded for ${sessionId.slice(0, 8)}`);
            success = true;
            return true;
          }
        }
      } catch (err) {
        log(`Surgical cleanup failed for ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
      }

      return false;
    } finally {
      repairInFlight.delete(sessionId);
      const now = Date.now();
      if (success) {
        repairAttempts.delete(sessionId);
        if (conversationId) repairAttempts.delete(conversationId);
      } else {
        repairAttempts.set(sessionId, now);
        if (conversationId) repairAttempts.set(conversationId, now);
      }
    }
  })();

  repairInFlight.set(sessionId, promise);
  return promise;
}

async function postDeliveryHealthCheck(
  sessionId: string,
  conversationId: string,
  content: string,
  messageId: string,
  syncService: SyncService,
  titleCache: TitleCache,
  conversationCache: ConversationCache
): Promise<void> {
  await new Promise(resolve => setTimeout(resolve, 15000));

  // Skip health check if a resume is already in flight (remote or auto)
  if (resumeInFlight.has(sessionId)) {
    log(`Health check: skipping for ${sessionId.slice(0, 8)}, resume in flight`);
    return;
  }
  const restartTs = restartingSessionIds.get(sessionId);
  if (restartTs && Date.now() - restartTs < RESTART_GUARD_TTL_MS) {
    log(`Health check: skipping for ${sessionId.slice(0, 8)}, restart in progress`);
    return;
  }

  const tmuxSession = resumeSessionCache.get(sessionId);
  if (!tmuxSession) return;

  try {
    await tmuxExec(["has-session", "-t", tmuxSession]);
  } catch {
    log(`Health check: tmux session ${tmuxSession} is dead after delivery for ${sessionId.slice(0, 8)}`);

    const repaired = await repairAndResumeSession(sessionId, content, titleCache, undefined, conversationId);
    if (repaired) {
      log(`Health check: repaired and re-delivered message for ${sessionId.slice(0, 8)}`);
      try { await syncService.setSessionError(conversationId); } catch {}
    } else {
      log(`Health check: repair failed for ${sessionId.slice(0, 8)}, retrying message delivery`);
      try {
        await syncService.retryMessage(messageId);
        await syncService.setSessionError(conversationId, "Session crashed — retrying message delivery");
      } catch {}
    }
    return;
  }

  // Detection-only past this point. The tmux-session-missing branch above
  // already covers the unambiguous death case (and reconstitutes the worker
  // since there is nothing to kill). If the tmux is still listed we trust it
  // — a missing agent process or empty pane is not enough signal to tear
  // down a session out from under the user. They drive repair from the UI's
  // Kill & restart action when something looks wrong.
  const alive = await isTmuxAgentAlive(tmuxSession);
  if (alive) {
    log(`Health check: session ${sessionId.slice(0, 8)} is healthy`);
    try { await syncService.setSessionError(conversationId); } catch {}
  } else {
    log(`Health check: session ${sessionId.slice(0, 8)} agent looks idle/missing in ${tmuxSession}; not auto-killing (use Kill & restart in UI if wedged)`);
  }
}

const materializeFailures = new Map<string, number>();
const materializeInFlight = new Map<string, Promise<string | null>>();
const materializedSessions = new Set<string>();
const MATERIALIZE_COOLDOWN_MS = 5 * 60 * 1000;

// Pure selector: from a set of tmux sessions tagged with a conversation id,
// pick a live one belonging to this conversation. Used to reuse an existing
// managed session instead of spawning a duplicate when the in-memory
// startedSessionTmux cache is stale (e.g. resurrected from disk across a
// daemon restart, pointing at a session that was killed in a prior lifetime).
export function pickReusableConversationTmux(
  candidates: Array<{ tmuxSession: string; conversationId: string | null; alive: boolean }>,
  conversationId: string,
): string | null {
  for (const c of candidates) {
    if (c.alive && c.conversationId === conversationId) return c.tmuxSession;
  }
  return null;
}

// tmux is the durable source of truth for "is a session for this conversation
// already running?" — unlike startedSessionTmux, which persists to disk and
// reloads stale entries on each daemon construction.
async function findLiveTmuxForConversation(
  conversationId: string,
): Promise<StartedSessionInfo | null> {
  if (!hasTmux()) return null;
  try {
    const { stdout } = await tmuxExec(["list-sessions", "-F", "#{session_name}"]);
    const names = stdout
      .trim()
      .split("\n")
      .filter(isManagedTmuxName);
    const candidates: Array<{ tmuxSession: string; conversationId: string | null; alive: boolean }> = [];
    for (const name of names) {
      const convId = await getTmuxSessionOption(name, "@codecast_conversation_id");
      // Only pay for the liveness check on a conversation match.
      const alive = convId === conversationId ? await isTmuxAgentAlive(name) : false;
      candidates.push({ tmuxSession: name, conversationId: convId, alive });
    }
    const match = pickReusableConversationTmux(candidates, conversationId);
    if (!match) return null;
    const projectPath =
      (await getTmuxSessionOption(match, "@codecast_project_path")) || process.env.HOME || "/tmp";
    const agentType =
      ((await getTmuxSessionOption(match, "@codecast_agent_type")) as StartedSessionInfo["agentType"] | null) ||
      "claude";
    return { tmuxSession: match, projectPath, startedAt: Date.now(), agentType };
  } catch {
    return null;
  }
}

async function startFreshSessionForDelivery(
  conversationId: string,
): Promise<StartedSessionInfo | null> {
  const existing = startedSessionTmux.get(conversationId);
  if (existing) return existing;

  if (!hasTmux()) {
    logDelivery(`Cannot start fresh session: tmux not available`);
    return null;
  }

  // Before spawning ANOTHER blank session, consult tmux for a live one already
  // tagged with this conversation. Guards against the double-start where the
  // in-memory cache lost track of a running session (resume fallback, restart
  // reload) and a redundant session would otherwise be created and the live one
  // orphaned.
  const reusable = await findLiveTmuxForConversation(conversationId);
  if (reusable) {
    startedSessionTmux.set(conversationId, reusable);
    logDelivery(
      `Reusing live tmux ${reusable.tmuxSession} for conv=${conversationId.slice(0, 12)} instead of starting fresh`,
    );
    return reusable;
  }

  const config = readConfig();
  let projectPath: string | null = null;
  let declaredAgentType: AgentClientId | null = null;

  if (config?.convex_url && config?.auth_token) {
    try {
      const siteUrl = config.convex_url.replace(".cloud", ".site");
      const exportData = await fetchExport(siteUrl, config.auth_token!, conversationId);
      declaredAgentType = fromConvexAgentType(exportData.conversation?.agent_type);
      if (exportData.conversation?.project_path && fs.existsSync(exportData.conversation.project_path)) {
        projectPath = exportData.conversation.project_path;
      }
    } catch (err) {
      // Delivery must never invent a backend when it cannot resolve the durable
      // conversation identity. Leaving the message pending is recoverable;
      // silently attaching a Claude runtime to (for example) a Codex
      // conversation is not.
      logDelivery(`Refusing fresh delivery fallback for conv=${conversationId.slice(0, 12)} — could not resolve declared agent: ${err instanceof Error ? err.message : String(err)}`);
      return null;
    }
  }

  // This legacy escape hatch predates multiple agent clients and can only
  // construct Claude sessions. It must not cross the conversation's durable
  // agent boundary when another runtime is merely late to register.
  if (declaredAgentType !== "claude") {
    logDelivery(`Refusing cross-agent delivery fallback for conv=${conversationId.slice(0, 12)} — requested ${declaredAgentType ?? "unknown"}, fallback is claude`);
    return null;
  }

  if (!projectPath) {
    // $HOME is an acceptable last resort only on the LOCAL primary daemon (a
    // blank quick-create lands in the user's home). On a remote box it would
    // run the session under /Users/<remote-user> with the wrong identity and
    // context — refuse and leave the message pending for the local fleet.
    if (isRemoteDevice()) {
      logDelivery(`Refusing fresh session for conv=${conversationId.slice(0, 12)} — remote device with no real project path`);
      return null;
    }
    projectPath = process.env.HOME || "/tmp";
  }

  const shortId = Math.random().toString(36).slice(2, 8);
  const tmuxSession = `cc-claude-${shortId}`;
  // Same permission-flag injection as start_session / auto-resume — a delivery
  // that spawns a fresh agent must enter bypass, not the project's dontAsk
  // default (which silently denies every tool until the user manually opens
  // permissions). This is the path that strands "started without bypass" threads.
  const safeBlankArgs = sanitizeBinaryArgs(buildBlankLaunchArgs("claude", config));
  const blankCmdText = `${AGENT_ENV_SCRUB} ${["claude", ...safeBlankArgs].join(" ")}`;

  try {
    tmuxExecSync(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", tmuxSession, "-c", projectPath], { timeout: 5000 });
    await setTmuxSessionOption(tmuxSession, "@codecast_conversation_id", conversationId).catch(() => {});
    await setTmuxSessionOption(tmuxSession, "@codecast_agent_type", "claude").catch(() => {});
    await setTmuxSessionOption(tmuxSession, "@codecast_project_path", projectPath).catch(() => {});
    tmuxExecSync(["send-keys", "-t", tmuxSession, "-l", blankCmdText], { timeout: 5000 });
    tmuxExecSync(["send-keys", "-t", tmuxSession, "Enter"], { timeout: 5000 });
    const entry: StartedSessionInfo = {
      tmuxSession,
      projectPath,
      startedAt: Date.now(),
      agentType: "claude",
    };
    startedSessionTmux.set(conversationId, entry);
    if (syncServiceRef) {
      syncServiceRef.registerManagedSession(tmuxSession, process.pid, tmuxSession, conversationId as any).catch(logConvexFailure);
      ensureManagedSessionHeartbeat(tmuxSession);
    }
    discoverAndLinkSession(conversationId, tmuxSession, projectPath).catch(err => {
      log(`Session discovery failed for ${conversationId.slice(0, 12)}: ${err}`);
    });
    logDelivery(`Started fresh session ${tmuxSession} for conv=${conversationId.slice(0, 12)} in ${projectPath}`);
    return entry;
  } catch (err) {
    logDelivery(`Failed to start fresh session for conv=${conversationId.slice(0, 12)}: ${err instanceof Error ? err.message : String(err)}`);
    return null;
  }
}

async function materializeSession(
  conversationId: string,
  conversationCache: ConversationCache,
  titleCache: TitleCache,
  syncService?: SyncService
): Promise<string | null> {
  const existing = materializeInFlight.get(conversationId);
  if (existing) return existing;

  const lastFail = materializeFailures.get(conversationId);
  if (lastFail && Date.now() - lastFail < MATERIALIZE_COOLDOWN_MS) {
    return null;
  }

  const config = readConfig();
  if (!config?.convex_url || !config?.auth_token) {
    logDelivery(`Cannot materialize: missing convex_url or auth_token`);
    return null;
  }

  const siteUrl = config.convex_url.replace(".cloud", ".site");

  const promise = (async (): Promise<string | null> => {
    try {
      logDelivery(`Materializing session for conv=${conversationId.slice(0, 12)}...`);
      const exportData = await fetchExport(siteUrl, config.auth_token!, conversationId);
      if (exportData.messages.length === 0) {
        logDelivery(`Materialization skipped for ${conversationId.slice(0, 12)}: 0 messages (session_id=${exportData.conversation?.session_id?.slice(0, 8) || "none"})`);
        return null;
      }
      // A store-owned client (opencode/pi/cursor) has no Claude-JSONL transcript to
      // materialize — fabricating one is invalid and, for opencode, the write path
      // corrupts the shared opencode.db (ct-39174/ct-39178). Delivery falls back to
      // the started-pane injection / re-resume instead of a materialized session.
      const matAgentType = fromConvexAgentType(exportData.conversation.agent_type);
      if (clientOwnsSessionStore(matAgentType)) {
        logDelivery(`Materialization skipped for ${conversationId.slice(0, 12)}: ${matAgentType} owns its session store (no Claude JSONL to materialize)`);
        return null;
      }

      const TOKEN_BUDGET = CLAUDE_AUTO_TRIM_TARGET_TOKENS;
      const tailMessages = chooseClaudeTailMessagesForTokenBudget(exportData, TOKEN_BUDGET);
      // Use the conversation's actual session_id so the JSONL matches Convex
      const convSessionId = exportData.conversation.session_id || undefined;
      const { jsonl, sessionId } = generateClaudeCodeJsonl(exportData, { tailMessages, sessionId: convSessionId });
      const projectPath = exportData.conversation.project_path || undefined;
      const { filePath: matFilePath } = writeClaudeCodeSession(jsonl, sessionId, localSessionDir(projectPath));
      setPosition(matFilePath, fs.statSync(matFilePath).size);

      conversationCache[sessionId] = conversationId;
      saveConversationCache(conversationCache);
      materializedSessions.add(sessionId);
      if (exportData.conversation.title) {
        titleCache[sessionId] = exportData.conversation.title;
        saveTitleCache(titleCache);
      }

      if (syncService) {
        void pushSessionIdBinding(conversationId, sessionId);
      }

      logDelivery(`Materialized session=${sessionId.slice(0, 8)} conv=${conversationId.slice(0, 12)} (${exportData.messages.length} msgs, tail=${tailMessages})`);
      return sessionId;
    } catch (err) {
      logDelivery(`Materialization FAILED for ${conversationId.slice(0, 12)}: ${err instanceof Error ? err.message : String(err)}`);
      materializeFailures.set(conversationId, Date.now());
      return null;
    } finally {
      materializeInFlight.delete(conversationId);
    }
  })();

  materializeInFlight.set(conversationId, promise);
  return promise;
}

// Map a storage object's Content-Type to a file extension. The extension must
// match the actual bytes: clients now upload WebP (compressed) as well as the
// PNG/JPEG they always have, and the agent that reads this file should see a
// truthful extension rather than a blanket ".png" (which mislabeled every JPEG).
function imageExtForContentType(contentType: string | null): string {
  const ct = (contentType || "").toLowerCase();
  if (ct.includes("webp")) return "webp";
  if (ct.includes("jpeg") || ct.includes("jpg")) return "jpg";
  if (ct.includes("gif")) return "gif";
  return "png";
}

async function downloadImage(storageId: string, syncService: SyncService): Promise<string | null> {
  const dir = "/tmp/codecast/images";
  // A prior materialization may have used any extension — reuse it if present.
  for (const ext of ["png", "webp", "jpg", "jpeg", "gif"]) {
    const cached = `${dir}/${storageId}.${ext}`;
    if (fs.existsSync(cached)) return cached;
  }

  const imageUrl = await syncService.getImageUrl(storageId);
  if (!imageUrl) {
    log(`downloadImage: no URL for storage id ${storageId} (auth rejected or file missing)`);
    return null;
  }

  fs.mkdirSync(dir, { recursive: true });

  const resp = await fetch(imageUrl);
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
  const destPath = `${dir}/${storageId}.${imageExtForContentType(resp.headers.get("content-type"))}`;
  fs.writeFileSync(destPath, Buffer.from(await resp.arrayBuffer()));
  return destPath;
}

async function deliverMessage(
  conversationId: string,
  content: string,
  conversationCache: ConversationCache,
  syncService: SyncService,
  messageId: string,
  titleCache: TitleCache
): Promise<boolean> {
  logDelivery(`deliverMessage called: conv=${conversationId.slice(0, 12)} msgId=${messageId.slice(0, 12)} content="${content.slice(0, 80)}"`);

  const childConvId = planHandoffChildren.get(conversationId);
  if (childConvId) {
    logDelivery(`Redirecting message from plan parent ${conversationId.slice(0, 12)} to child ${childConvId.slice(0, 12)}`);
    return deliverMessage(childConvId, content, conversationCache, syncService, messageId, titleCache);
  }

  // Single-owner delivery guard (split-brain prevention). If a DIFFERENT live
  // device owns this conversation — a local peer, or a remote Mac it was moved
  // to — that owner delivers; THIS daemon must not resume a local copy and answer
  // in parallel. Checked unconditionally up front: sessionId is resolved from the
  // conversation record below, so a known-but-stale local session id would sail
  // past a `!sessionId`-only guard (the original split-brain after move-to-remote).
  // An OFFLINE owner does NOT skip, so a dead owner's session can be reclaimed.
  // Fail-open on any lookup error so a transient query failure never blocks sends.
  try {
    const ownerInfo = await syncService.getConversationOwnerInfo(conversationId);
    if (ownedByAnotherLiveDevice(ownerInfo)) {
      logDelivery(`[OWNER] skipping delivery for ${conversationId.slice(0, 12)} — owned by live device ${ownerInfo?.ownerDeviceId.slice(0, 8)}${ownerInfo?.ownerIsRemote ? " (remote)" : ""} (not ${deviceId().slice(0, 8)})`);
      return false;
    }
    // A remote daemon serves ONLY conversations explicitly moved to it. An
    // unowned conversation — or one owned by a currently-offline local Mac — is
    // the local fleet's to pick up when it wakes; adopting it here spawns a
    // $HOME session on the cloud box (how blank iOS sessions landed on m1).
    // ownerInfo is null on lookup failure too, so a remote fails CLOSED.
    if (isRemoteDevice() && ownerInfo?.ownerDeviceId !== deviceId()) {
      logDelivery(`[OWNER] remote daemon skipping delivery for ${conversationId.slice(0, 12)} — owner=${ownerInfo?.ownerDeviceId?.slice(0, 8) ?? "unowned"} (this device ${deviceId().slice(0, 8)})`);
      return false;
    }
  } catch {
    // Fail-open for a local primary daemon (a transient query failure must not
    // block sends); a remote must not act on a conversation it can't verify.
    if (isRemoteDevice()) {
      logDelivery(`[OWNER] remote daemon skipping delivery for ${conversationId.slice(0, 12)} — ownership lookup failed (fail-closed)`);
      return false;
    }
  }

  const tryAppServerDelivery = async (): Promise<boolean> => {
    if (!codexAppServerInstance?.running) return false;
    const appServerThreadId = appServerConversations.get(conversationId);
    if (appServerThreadId) {
      try {
        const input: Array<{ type: "text"; text: string }> = [{ type: "text", text: content }];
        await codexAppServerInstance.turnStart({ threadId: appServerThreadId, input });
        // Delivered input = a new turn: spend any declared settle verdict from
        // before it (codex settles key turnStartedAt by thread id — see
        // resolveTurnEndStatus at the app-server turn-completed handler).
        markTurnStarted(appServerThreadId, Date.now());
        // Persist the user turn ourselves: the app-server replays only the agent's output,
        // so without this the prompt is never stored and the conversation reads as agent-only
        // (ct-36429). syncMessagesBatch routes it through the same addMessages path as Claude,
        // which content-matches the pending row (client_id adoption + delivered ack + dedupe).
        if (retryQueueRef) {
          await syncMessagesBatch(
            [buildCodexUserTurnMessage(content, messageId, Date.now())],
            conversationId,
            syncService,
            retryQueueRef,
          );
        }
        await syncService.updateMessageStatus({ messageId, status: "delivered", deliveredAt: Date.now() });
        logDelivery(`[codex-app-server] delivered via app-server to thread ${appServerThreadId.slice(0, 8)}`);
        return true;
      } catch (err) {
        removeAppServerThreadRegistration(appServerThreads, appServerConversations, conversationId, appServerThreadId);
        if (err instanceof Error && /thread not found|no rollout found/i.test(err.message)) {
          forgetPersistedAppServerConversation(conversationId);
        }
        logDelivery(`[codex-app-server] delivery failed, falling back to tmux: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
    return false;
  };

  if (await tryAppServerDelivery()) return true;

  const reverseCache = buildReverseConversationCache(conversationCache);
  let sessionId = reverseCache[conversationId];

  const pendingPrompt = pendingInteractivePrompts.get(sessionId || conversationId);
  pendingInteractivePrompts.delete(sessionId || conversationId);

  // If there's an active poll and the message is plain text (not already a poll response),
  // check if it matches one of the poll options and convert to a poll response
  if (pendingPrompt && !parsePollMessage(content)) {
    const normalized = content.replace(/\s+/g, " ").trim().toLowerCase();
    if (normalized && pendingPrompt.options.length > 0) {
      if (pendingPrompt.isConfirmation) {
        const isConfirm = /^(continue|enter|yes|ok|confirm|proceed|accept|y)$/i.test(normalized) ||
          (pendingPrompt.options[0] && normalized.includes(pendingPrompt.options[0].label.toLowerCase().split(" (")[0]));
        const isCancel = /^(cancel|escape|esc|no|quit|n)$/i.test(normalized) ||
          (pendingPrompt.options[1] && normalized.includes(pendingPrompt.options[1].label.toLowerCase().split(" (")[0]));
        if (isConfirm) {
          content = JSON.stringify({ __cc_poll: true, keys: ["Enter"], display: "Continue" });
          logDelivery(`Converted plain text to confirmation Enter for session=${(sessionId || conversationId).slice(0, 8)}`);
        } else if (isCancel) {
          content = JSON.stringify({ __cc_poll: true, keys: ["Escape"], display: "Cancel" });
          logDelivery(`Converted plain text to confirmation Escape for session=${(sessionId || conversationId).slice(0, 8)}`);
        }
      } else {
        const matchIdx = pendingPrompt.options.findIndex(opt => {
          const optNorm = opt.label.replace(/\s+/g, " ").trim().toLowerCase();
          return optNorm === normalized || normalized.includes(optNorm) || optNorm.includes(normalized);
        });
        if (matchIdx >= 0) {
          const display = pendingPrompt.options[matchIdx].label;
          const steps: Array<{ key: string }> = [];
          for (let i = 0; i < matchIdx; i++) steps.push({ key: "Down" });
          steps.push({ key: "Enter" });
          content = JSON.stringify({ __cc_poll: true, steps, display });
          logDelivery(`Converted plain text "${display}" to poll arrows=${matchIdx}+Enter for session=${(sessionId || conversationId).slice(0, 8)}`);
        }
      }
    }
  }

  // The answer to a scraped TUI menu resolves it: retire the synthetic card so
  // no client keeps an open question for a dialog that is about to be gone
  // (closeSyntheticPrompt also drops the re-emit record, so a genuine re-ask of
  // the same menu later mints a fresh card). A plain-text delivery only clears
  // the re-emit record, matching the old behavior — its card, if any, is
  // retired by the heartbeat once the menu leaves the pane.
  {
    const outgoingPoll = parsePollMessage(content);
    if (outgoingPoll) {
      const display = outgoingPoll.display || outgoingPoll.text || "";
      await closeSyntheticPrompt(
        sessionId || conversationId,
        conversationId,
        syncService,
        display ? `Answered from the app: ${display}` : "Answered from the app",
      );
    } else {
      lastEmittedSyntheticPrompt.delete(sessionId || conversationId);
    }
  }

  if (!sessionId) {
    const cacheKeys = Object.keys(conversationCache);
    const reverseKeys = Object.keys(reverseCache);
    logDelivery(`No session in cache for conv=${conversationId.slice(0, 12)}, cache has ${cacheKeys.length} sessions/${reverseKeys.length} convs, startedTmux has ${startedSessionTmux.size} entries`);
    syncService.updateSessionAgentStatus(conversationId, "starting").catch(logConvexFailure);
    // Try delivering via a recently started tmux session (from start_session command)
    const tryStartedTmux = async (entry: StartedSessionInfo): Promise<boolean> => {
      try {
        await tmuxExec(["has-session", "-t", entry.tmuxSession]);
        let ready = false;
        const startTime = Date.now();
        for (let i = 0; i < 60; i++) {
          await new Promise(resolve => setTimeout(resolve, 250));
          const probe = await probeStartedPane(entry);
          if (probe.state === "gone") throw new Error(`tmux session ${entry.tmuxSession} is gone`);
          if (probe.state === "fatal") {
            log(`Started session ${entry.tmuxSession} hit fatal error, falling through. Pane: ${probe.pane.slice(0, 200)}`);
            deleteStartedSession(conversationId);
            return false;
          }
          if (probe.state === "ready") {
            log(`Started session ${entry.tmuxSession} ready (prompt visible) after ${Date.now() - startTime}ms`);
            ready = true;
            break;
          }
        }
        if (!ready) {
          log(`Started session ${entry.tmuxSession} startup timed out after ${Date.now() - startTime}ms, proceeding anyway`);
        }
        // Brief settle after the prompt paints. This is NOT the readiness
        // guarantee — injectViaTmux gates Enter on the pasted payload actually
        // rendering in the composer (awaitTmuxComposerPayload, ct-40212), so a
        // slow input handler stalls the gate, not the submit. The 500ms just
        // lets the freshly painted frame stop redrawing.
        await new Promise(resolve => setTimeout(resolve, 500));
        const startedTmuxTarget = entry.tmuxSession + ":0.0";
        // Mark "injected" best-effort (non-blocking) BEFORE the paste. The mark is fire-and-forget
        // with an 8s timeout (markInjectedBestEffort), so it can never wedge delivery the way the
        // old un-timed `await updateMessageStatus` did. Marking before the inject closes the
        // doubled-message race: the inject makes Claude echo the message to JSONL within ms, and
        // addMessages' content-matched ack only promotes an EXISTING "injected"/"pending" row to
        // "delivered". If we marked after and the ack won the race it would find no row and the
        // daemon's later mark would strand the row "injected", which the 120s retry cron re-pends
        // → duplicate reply. Marking first guarantees the ack always has a row to promote.
        markInjectedBestEffort(syncService, messageId, undefined, { conversationId });
        await injectViaTmux(startedTmuxTarget, content, entry.agentType);
        syncService.updateSessionAgentStatus(conversationId, "connected").catch(logConvexFailure);
        log(`Injected message to started session tmux ${entry.tmuxSession} for conversation ${conversationId.slice(0, 12)}`);
        const isPollResponse = !!parsePollMessage(content);
        if (content.trimStart().startsWith("/") || isPollResponse) {
          checkForInteractivePrompt(startedTmuxTarget, conversationId, conversationId, syncService, isPollResponse ? 4000 : 2000).catch(() => {});
        }
        return true;
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        // A deaf-but-painted composer (payload never rendered) or a paste that
        // provably never reached the agent are conditions of THIS healthy,
        // still-booting pane. Falling through would start a SECOND instance
        // beside it (the incident's duplicated-backend shape) — rethrow so the
        // delivery layer retries into the same pane after backoff instead.
        if (msg.startsWith("AGENT_STDIN_NOT_READY") || msg.startsWith("INJECT_UNVERIFIED")) {
          throw err;
        }
        log(`Started session tmux ${entry.tmuxSession} not reachable, falling through: ${msg}`);
        // Only clear if session is old (>60s). Fresh sessions may just need more startup time.
        if (Date.now() - entry.startedAt > 60_000) {
          deleteStartedSession(conversationId);
        }
        return false;
      }
    };

    const started = startedSessionTmux.get(conversationId);
    if (started && await tryStartedTmux(started)) return true;

    const freshCache = readConversationCache();
    const freshReverse = buildReverseConversationCache(freshCache);
    sessionId = freshReverse[conversationId];

    // (Cross-device ownership is enforced unconditionally at the top of
    // deliverMessage — by here we've already established this daemon may serve.)

    if (sessionId) {
      conversationCache[sessionId] = conversationId;
      log(`Found session ${sessionId.slice(0, 8)} for conversation ${conversationId.slice(0, 12)} via disk cache refresh`);
    } else if (!started) {
      logDelivery(`Waiting up to 12s for start_session to populate startedSessionTmux for conv=${conversationId.slice(0, 12)}`);
      for (let i = 0; i < 24; i++) {
        await new Promise(r => setTimeout(r, 500));
        // Codex app-server startup registers asynchronously and has no tmux or
        // transcript-cache entry. Recheck its binding during the same readiness
        // wait so a pending first message cannot race ahead and create Claude.
        if (await tryAppServerDelivery()) return true;
        const justStarted = startedSessionTmux.get(conversationId);
        if (justStarted) {
          log(`Found startedSessionTmux for ${conversationId.slice(0, 12)} after ${(i + 1) * 500}ms wait`);
          if (await tryStartedTmux(justStarted)) return true;
          break;
        }
        // Also check disk cache - session may have linked via watcher
        const recheckCache = readConversationCache();
        const recheckReverse = buildReverseConversationCache(recheckCache);
        if (recheckReverse[conversationId]) {
          sessionId = recheckReverse[conversationId];
          conversationCache[sessionId!] = conversationId;
          log(`Found session ${sessionId!.slice(0, 8)} for ${conversationId.slice(0, 12)} via disk cache on wait iteration ${i + 1}`);
          break;
        }
      }
      if (!sessionId) {
        log(`No session_id in local cache for conversation ${conversationId}, attempting to materialize from server...`);
        sessionId = (await materializeSession(conversationId, conversationCache, titleCache, syncService))!;
        if (!sessionId) {
          logDelivery(`Materialization failed for conv=${conversationId.slice(0, 12)}, starting fresh session`);
          const freshEntry = await startFreshSessionForDelivery(conversationId);
          if (freshEntry && await tryStartedTmux(freshEntry)) return true;
          log(`Cannot deliver: no local session, materialization failed, and fresh start failed for ${conversationId}`);
          return false;
        }
        syncService.updateSessionAgentStatus(conversationId, "resuming").catch(logConvexFailure);
      }
    } else {
      log(`No session_id in local cache for conversation ${conversationId}, attempting to materialize from server...`);
      sessionId = (await materializeSession(conversationId, conversationCache, titleCache, syncService))!;
      if (!sessionId) {
        logDelivery(`Materialization failed for conv=${conversationId.slice(0, 12)}, starting fresh session`);
        const freshEntry = await startFreshSessionForDelivery(conversationId);
        if (freshEntry && await tryStartedTmux(freshEntry)) return true;
        logDelivery(`Cannot deliver: no local session, materialization failed, and fresh start failed for conv=${conversationId.slice(0, 12)}`);
        return false;
      }
      syncService.updateSessionAgentStatus(conversationId, "resuming").catch(logConvexFailure);
    }
  }

  // Determine session type for process discovery and auto-resume
  const isCursorSession = sessionId.startsWith("cursor-");
  const isGeminiSession = sessionId.startsWith("session-");

  // Cursor is an IDE, not a terminal process - can't inject
  if (isCursorSession) {
    logDelivery(`Session ${sessionId.slice(0, 20)} is Cursor IDE, cannot inject - skipping`);
    return false;
  }

  // Detect codex sessions by checking if the JSONL exists in codex paths
  let detectedType: AgentClientId = isGeminiSession ? "gemini" : "claude";
  if (!isGeminiSession) {
    const sessionFile = findSessionFile(sessionId);
    if (sessionFile) detectedType = sessionFile.agentType;
  }

  logDelivery(`Delivering to session=${sessionId.slice(0, 12)} conv=${conversationId.slice(0, 12)} type=${detectedType}`);


  // Find an already-live session (cached tmux / started session / live process pane) via the
  // shared resolver, so this path and autoResumeSession agree on "is it live and where".
  const live = await resolveLiveTmuxTarget(conversationId, sessionId, detectedType);
  let agentDetectedDead = false;
  if (live.tmuxTarget) {
    // Bare names (cache/started) target the session's active pane via ":0.0"; a
    // process-discovered pane ("cc-x:win.pane") is already fully qualified.
    const injectTarget = live.tmuxTarget.includes(":") ? live.tmuxTarget : live.tmuxTarget + ":0.0";
    const tmuxSessionName = injectTarget.split(":")[0];
    try {
      // Mark "injected" best-effort (non-blocking) BEFORE the paste. markInjectedBestEffort is
      // fire-and-forget with an 8s timeout, so it can't wedge the paste the way the old un-timed
      // `await updateMessageStatus` did. Marking first closes the doubled-message race: the paste
      // makes Claude echo the message to JSONL within ms; addMessages' content-matched ack only
      // promotes an EXISTING row to "delivered". If we marked after and the ack ran first it would
      // find no row, the daemon's later mark would strand the row "injected", and the 120s retry
      // cron would re-pend it → duplicate reply. Marking first guarantees the ack has a row.
      markInjectedBestEffort(syncService, messageId, undefined, { conversationId });
      await injectViaTmux(injectTarget, content, detectedType);
      // A process-discovered pane can go stale between scan and inject — verify the agent
      // survived and fall through to auto-resume if it crashed (the original optimistic path).
      if (live.source === "process" && !(await isTmuxAgentAlive(tmuxSessionName))) {
        logDelivery(`Agent in ${injectTarget} is dead after injection, falling through to auto-resume`);
        sessionProcessCache.delete(sessionId);
        agentDetectedDead = true;
      } else {
        if (live.source === "cache") syncService.setSessionError(conversationId).catch(logConvexFailure);
        logDelivery(`Injected via tmux ${injectTarget} (source=${live.source})`);
        const isPollResponse = !!parsePollMessage(content);
        if (content.trimStart().startsWith("/") || isPollResponse) {
          checkForInteractivePrompt(injectTarget, sessionId, conversationId, syncService, isPollResponse ? 4000 : 2000).catch(() => {});
        }
        return true;
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      // Same reasoning as tryStartedTmux: these two mean a live pane exists
      // but hasn't consumed our payload yet. Fall-through would auto-resume a
      // parallel instance beside it — rethrow and let the retry re-enter this
      // same pane after backoff.
      if (msg.startsWith("AGENT_STDIN_NOT_READY") || msg.startsWith("INJECT_UNVERIFIED")) {
        throw err;
      }
      logDelivery(`tmux injection failed for ${injectTarget}: ${msg}`);
    }
  }

  // Live agent process not inside tmux (or the tmux inject failed without a confirmed-dead
  // agent): try direct terminal injection (AppleScript for iTerm2/Terminal.app, CLI for
  // Kitty/WezTerm). Skipped when the agent was just detected dead — that goes to auto-resume.
  if (live.proc && !agentDetectedDead) {
    const termLabel = getTerminalLabel(live.proc.termProgram);
    logDelivery(`Trying ${termLabel} injection for tty=${live.proc.tty}`);
    try {
      // Mark "injected" best-effort (non-blocking) BEFORE the terminal paste — same ack-race
      // reasoning and same wedge-safety (fire-and-forget 8s timeout) as the tmux paths above.
      markInjectedBestEffort(syncService, messageId, undefined, { conversationId });
      await injectViaTerminal(live.proc.tty, content, live.proc.termProgram, {
        agentType: detectedType,
      });
      logDelivery(`Injected via ${termLabel} tty=${live.proc.tty}`);
      return true;
    } catch (err) {
      logDelivery(`${termLabel} injection failed for ${live.proc.tty}: ${err instanceof Error ? err.message : String(err)}`);
    }
    logDelivery(`All injection methods failed for live process pid=${live.proc.pid}, falling back to auto-resume`);
  } else if (!live.tmuxTarget && !live.proc) {
    logDelivery(`No running process found for session=${sessionId.slice(0, 12)} type=${detectedType}`);
  }

  // A Workflow-tool agent has no process to reach once its host's turn is
  // over, and a standalone resume of it only spawns a copy that runs the brief
  // again for nobody. Cancel the message rather than retry: no injection path
  // can ever succeed for it.
  const workflowAgentPath = workflowAgentTranscriptPathFor(sessionId);
  if (workflowAgentPath) {
    logDelivery(`Refusing to resume workflow agent ${sessionId.slice(0, 8)} for msg=${messageId.slice(0, 8)}: ${workflowAgentPath}`);
    throw new UndeliverableMessageError(`workflow agent transcript ${workflowAgentPath}`);
  }

  // Circuit breaker: skip auto-resume if this session has failed too many times recently
  if (isSessionCircuitOpen(sessionId)) {
    logDelivery(`Circuit breaker OPEN for session=${sessionId.slice(0, 8)}, skipping auto-resume (cooldown ${SESSION_CIRCUIT_BREAKER_COOLDOWN_MS / 1000}s)`);
    return false;
  }

  // Last resort: auto-resume in a new tmux session
  const tmuxAvailable = hasTmux();
  logDelivery(`Attempting auto-resume: session=${sessionId.slice(0, 8)} tmux=${tmuxAvailable}`);
  if (!tmuxAvailable) {
    logDelivery(`CANNOT auto-resume: tmux is not installed. Install with: brew install tmux`);
  }
  // Mark "injected" best-effort (non-blocking) before the resume. autoResumeSession spins up
  // tmux + Claude and injects the content; the content-matched ack in addMessages flips the row
  // to "delivered" when Claude echoes the message to JSONL, so this status write is not
  // load-bearing. Keeping it non-blocking ensures a slow/stalled Convex mark can't wedge the
  // resume+inject — the same failure mode fixed on the live-tmux path above.
  markInjectedBestEffort(syncService, messageId, undefined, { conversationId });
  const resumed = await autoResumeSession(sessionId, content, titleCache, undefined, conversationId);
  if (resumed) {
    resetSessionDeliveryFailures(sessionId);
    materializedSessions.delete(sessionId);
    logDelivery(`Injected via auto-resume for session=${sessionId.slice(0, 8)}`);
    const isPollResponse = !!parsePollMessage(content);
    if (content.trimStart().startsWith("/") || isPollResponse) {
      const resumeTmux = resumeSessionCache.get(sessionId);
      if (resumeTmux) {
        checkForInteractivePrompt(resumeTmux + ":0.0", sessionId, conversationId, syncService, isPollResponse ? 4000 : 2000).catch(() => {});
      }
    }
    postDeliveryHealthCheck(sessionId, conversationId, content, messageId, syncService, titleCache, conversationCache).catch(err => {
      log(`Health check error: ${err instanceof Error ? err.message : String(err)}`);
    });
    return true;
  }

  // Auto-resume failed - try repair (regenerate JSONL from Convex)
  logDelivery(`Auto-resume failed for ${sessionId.slice(0, 8)}, attempting repair...`);
  // Row is already marked "injected" from the auto-resume attempt above; repair+resume is a
  // second delivery path for the same message, so no re-mark needed.
  const repaired = await repairAndResumeSession(sessionId, content, titleCache, undefined, conversationId);
  if (repaired) {
    resetSessionDeliveryFailures(sessionId);
    materializedSessions.delete(sessionId);
    logDelivery(`Injected via repair+resume for session=${sessionId.slice(0, 8)}`);
    const isPollResponse = !!parsePollMessage(content);
    if (content.trimStart().startsWith("/") || isPollResponse) {
      const resumeTmux = resumeSessionCache.get(sessionId);
      if (resumeTmux) {
        checkForInteractivePrompt(resumeTmux + ":0.0", sessionId, conversationId, syncService, isPollResponse ? 4000 : 2000).catch(() => {});
      }
    }
    postDeliveryHealthCheck(sessionId, conversationId, content, messageId, syncService, titleCache, conversationCache).catch(err => {
      log(`Health check error: ${err instanceof Error ? err.message : String(err)}`);
    });
    return true;
  }

  // Only a genuinely-unrecoverable resume (recorded in resumeFatalReasons: missing
  // conversation, retired model, session truly gone) earns the long 5-min cooldown.
  // Everything else — a resume we launched that died, a slow/raced cold boot, a
  // one-off SESSION_EXITED during inject — is transient and gets the short backoff,
  // so a recoverable hiccup can no longer masquerade as a dead session for minutes.
  const fatal = resumeFatalReasons.has(sessionId);
  recordSessionDeliveryFailure(sessionId, { transient: !fatal });
  logDelivery(`DELIVERY FAILED: all methods exhausted for session=${sessionId.slice(0, 8)} conv=${conversationId.slice(0, 12)} (${fatal ? "fatal" : "transient"})`);
  return false;
}

function isSyncPaused(): boolean {
  return process.env.CODE_CHAT_SYNC_PAUSED === "1" || process.env.CODECAST_PAUSED === "1";
}

async function repairProjectPaths(syncService: SyncService): Promise<void> {
  const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
  if (!fs.existsSync(claudeProjectsDir)) return;

  log("Checking for project paths that need repair...");

  const projectDirs = fs.readdirSync(claudeProjectsDir, { withFileTypes: true })
    .filter(d => d.isDirectory())
    .map(d => d.name);

  let repaired = 0;
  let checked = 0;

  // updateProjectPath only consumes the repo root, and the full getGitInfo
  // (status + both diffs, 8 subprocesses) per FILE starved the event loop for
  // minutes on a large ~/.claude/projects — the watchdog then killed the daemon
  // mid-boot as "wedged". One cheap subprocess per unique project path instead.
  const repoRootCache = new Map<string, string | undefined>();
  const resolveRepoRoot = (projectPath: string): string | undefined => {
    if (repoRootCache.has(projectPath)) return repoRootCache.get(projectPath);
    let root: string | undefined;
    try {
      const commonDir = execSync("git rev-parse --path-format=absolute --git-common-dir", {
        cwd: projectPath,
        encoding: "utf-8",
        stdio: ["pipe", "pipe", "ignore"],
      }).trim();
      root = commonDir.endsWith("/.git")
        ? commonDir.slice(0, -5)
        : execSync("git rev-parse --show-toplevel", {
            cwd: projectPath,
            encoding: "utf-8",
            stdio: ["pipe", "pipe", "ignore"],
          }).trim() || undefined;
    } catch {
      root = undefined;
    }
    repoRootCache.set(projectPath, root);
    return root;
  };

  for (const dir of projectDirs) {
    const dirPath = path.join(claudeProjectsDir, dir);
    const sessionFiles = fs.readdirSync(dirPath)
      .filter(f => f.endsWith(".jsonl") && f !== "sessions-index.json");

    const decodedPath = decodeProjectDirName(dir);
    const resolvedDir = decodedPath && decodedPath !== process.env.HOME && fs.existsSync(decodedPath) ? decodedPath : null;
    // Learn this repo's local home so a fork recorded on another machine (different
    // absolute path, same basename) resolves here even if it lives off-convention.
    // (Never the bare $HOME — that's the fingerprint of a stray $HOME-fallback dir.)
    if (resolvedDir) recordProjectMapping(path.basename(resolvedDir), resolvedDir);

    for (const file of sessionFiles) {
      // Let the event loop breathe between files: this sweep runs during boot,
      // and back-to-back synchronous transcript reads starve the heartbeat tick
      // the watchdog uses to tell alive from wedged.
      await new Promise(resolve => setImmediate(resolve));
      const filePath = path.join(dirPath, file);
      const sessionId = resolveSessionId(filePath);

      try {
        checked++;

        // Trust the transcript's recorded cwd over the (lossy, copyable) folder
        // slug; a transcript resumed/copied into a foreign or $HOME dir would
        // otherwise re-clobber project_path to e.g. "/Users/m1" on every startup.
        const projectPath = resolveTranscriptProjectPath(filePath, dir);
        if (!projectPath) continue;

        const result = await syncService.updateProjectPath(sessionId, projectPath, resolveRepoRoot(projectPath));
        if (result?.updated) {
          repaired++;
          log(`Repaired path for ${sessionId.slice(0, 8)}: ${projectPath}`);
        }
      } catch {
        // Skip files we can't read or sessions that don't exist in Convex
      }
    }
  }

  if (repaired > 0) {
    log(`Repaired ${repaired} project paths (checked ${checked})`);
  }
}

async function backfillPlanModeFromJSONL(syncService: SyncService): Promise<void> {
  const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
  if (!fs.existsSync(claudeProjectsDir)) return;

  let synced = 0;
  const projectDirs = fs.readdirSync(claudeProjectsDir, { withFileTypes: true })
    .filter(d => d.isDirectory())
    .map(d => d.name);

  for (const dir of projectDirs) {
    const dirPath = path.join(claudeProjectsDir, dir);
    let sessionFiles: string[];
    try {
      sessionFiles = fs.readdirSync(dirPath).filter(f => f.endsWith(".jsonl") && !f.includes("sessions-index"));
    } catch { continue; }

    const decodedPath = decodeProjectDirName(dir);

    for (const file of sessionFiles) {
      const filePath = path.join(dirPath, file);
      const sessionId = file.replace(".jsonl", "");
      if (planModeSynced.has(sessionId)) continue;

      try {
        // Async read + a yield per file: this walks every transcript (gigabytes
        // here) at boot, and readFileSync back-to-back starved the event loop —
        // the watchdog then killed the daemon mid-boot as "wedged".
        await new Promise(resolve => setImmediate(resolve));
        const content = await fs.promises.readFile(filePath, "utf-8");
        if (!content.includes("ExitPlanMode")) continue;

        let planContent: string | undefined;
        for (const line of content.split("\n")) {
          if (!line.includes("ExitPlanMode")) continue;
          try {
            const entry = JSON.parse(line);
            const msg = entry.message || entry;
            const blocks = Array.isArray(msg.content) ? msg.content : [];
            for (const block of blocks) {
              if (block.type === "tool_use" && block.name === "ExitPlanMode" && block.input?.plan) {
                planContent = block.input.plan;
                break;
              }
            }
          } catch { continue; }
          if (planContent) break;
        }

        if (!planContent) continue;

        // Trust the transcript cwd over a slug that only resolves to $HOME (a
        // stray $HOME-fallback dir); keep undefined when nothing resolves.
        const projPath =
          decodedPath && decodedPath !== process.env.HOME && fs.existsSync(decodedPath)
            ? decodedPath
            : (extractCwd(content) || undefined);
        const planShortId = await syncService.syncPlanFromPlanMode({
          sessionId,
          planContent,
          projectPath: projPath,
        });

        planModeSynced.add(sessionId);
        if (planShortId) planModePlanMap.set(sessionId, planShortId);
        savePlanModeCache();
        synced++;
        log(`Backfilled plan_mode plan ${planShortId || "doc-only"} for session ${sessionId.slice(0, 8)}`);
      } catch (err) {
        // Skip individual failures silently
      }
    }
  }

  if (synced > 0) log(`Backfilled ${synced} plan_mode plan(s) from JSONL history`);
}

async function waitForConfig(): Promise<{ config: Config; convexUrl: string }> {
  const checkInterval = 30000;
  let lastReason: string | null = null;
  let unchangedRepeats = 0;
  const HEARTBEAT_EVERY = 20; // re-log the same reason every ~10min so it can't slip past log rotation

  while (true) {
    const diag = diagnoseConfig();
    if (diag.ok) {
      return { config: diag.config, convexUrl: diag.convexUrl };
    }
    if (diag.reason !== lastReason) {
      log(diag.reason);
      lastReason = diag.reason;
      unchangedRepeats = 0;
    } else if (++unchangedRepeats >= HEARTBEAT_EVERY) {
      log(diag.reason);
      unchangedRepeats = 0;
    }
    await new Promise(resolve => setTimeout(resolve, checkInterval));
  }
}

function isProcessRunning(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

/**
 * Is a live agent running in this tmux session — and, when `sessionId` is given,
 * is it THIS session's agent? A tmux named for a session can host a different
 * session's process (see judgeProcessIdentity); for the caller that is not
 * "alive", it is "occupied by someone else", and reusing it would inject this
 * session's messages into that other agent.
 */
async function isTmuxAgentAlive(tmuxSession: string, sessionId?: string): Promise<boolean> {
  if (!hasTmux()) return false;
  try {
    const { stdout } = await tmuxExec(
      ["list-panes", "-t", tmuxSession, "-F", "#{pane_pid}"], { timeout: 3000, killSignal: "SIGKILL" }
    );
    const panePid = stdout.trim();
    if (!panePid) return false;

    const agentPid = await findAgentPidInTree(parseInt(panePid, 10));
    if (agentPid !== null && sessionId && await rejectsForeignProcess(sessionId, agentPid, `tmux ${tmuxSession}`)) return false;
    const hasProcess = agentPid !== null;

    try {
      const { stdout: paneContent } = await tmuxExec(
        ["capture-pane", "-p", "-J", "-t", tmuxSession, "-S", "-10"], { timeout: 3000, killSignal: "SIGKILL" }
      );
      const trimmed = paneContent.trim();
      if (!trimmed) return false;
      if (/Resume this session with:/i.test(trimmed)) return false;
      if (/Segmentation fault|panic:|SIGABRT|core dumped|exited with/.test(trimmed)) return false;
      if (/-(?:ba)?sh:.*(?:No such file|command not found)/.test(trimmed)) return false;
      if (hasProcess) return true;
      // No agent process in the process tree — the agent has exited or crashed.
      // Don't optimistically return true just because the pane has content; that
      // content is likely a crash stack trace or leftover output from the dead
      // process. Return false so the caller falls through to auto-resume.
      return false;
    } catch {}
    return hasProcess;
  } catch {
    return false;
  }
}

// Walk a process tree (BFS, bounded depth) and return the first agent process
// pid found, or null. The pid is what we seed into sessionProcessCache — it must
// be the agent itself (not the parent shell) so the cache's isAgentProcess
// revalidation keeps it alive.
async function findAgentPidInTree(rootPid: number, maxDepth = 4): Promise<number | null> {
  const visited = new Set<number>();
  async function scan(pids: number[], depth: number): Promise<number | null> {
    if (depth > maxDepth || pids.length === 0) return null;
    for (const pid of pids) {
      if (visited.has(pid)) continue;
      visited.add(pid);
      if (await isAgentProcess(pid)) return pid;
    }
    for (const pid of pids) {
      try {
        const { stdout } = await execAsync(`pgrep -P ${pid}`, { timeout: 3000, killSignal: "SIGKILL" });
        const children = stdout.trim().split(/\s+/).filter(Boolean).map(Number);
        const found = await scan(children, depth + 1);
        if (found !== null) return found;
      } catch {}
    }
    return null;
  }
  // Include the root itself, then descend — a bare `claude` pane_pid is the agent.
  if (await isAgentProcess(rootPid)) return rootPid;
  try {
    const { stdout } = await execAsync(`pgrep -P ${rootPid}`, { timeout: 3000, killSignal: "SIGKILL" });
    const childPids = stdout.trim().split(/\s+/).filter(Boolean).map(Number);
    return scan(childPids, 1);
  } catch {}
  return null;
}

// Async on purpose: this runs per session in fleet-wide sweeps (liveness
// reconcile, process-tree scans). As a sync `ps` it blocked the event loop
// ~1.8s per call under load (SLOW-SYNC-SPAWN, 2026-08-21) — dozens of calls per
// sweep froze delivery for the whole fleet.
async function isAgentProcess(pid: number): Promise<boolean> {
  try {
    const { stdout } = await execAsync(`ps -o comm= -p ${pid} 2>/dev/null`, { timeout: 3000, killSignal: "SIGKILL" });
    return isRecognizedAgentComm(stdout.trim());
  } catch {
    return false;
  }
}

let skipRespawn = false;

const DAEMON_LAUNCHD_LABEL = "sh.codecast.daemon";

// Parse the running instance pid out of `launchctl print gui/<uid>/<label>` output.
// Pure so ownership detection is testable without a live launchd.
export function parseLaunchdPrintPid(printOutput: string): number | null {
  const m = printOutput.match(/^\s*pid = (\d+)\b/m);
  if (!m) return null;
  const pid = parseInt(m[1], 10);
  return Number.isFinite(pid) && pid > 0 ? pid : null;
}

function readLaunchdDaemonJob(): { loaded: boolean; pid: number | null } {
  if (platform !== "darwin" || !process.getuid) return { loaded: false, pid: null };
  try {
    const res = spawnSync("launchctl", ["print", `gui/${process.getuid()}/${DAEMON_LAUNCHD_LABEL}`], {
      encoding: "utf-8",
      timeout: 5000,
    });
    if (res.status !== 0) return { loaded: false, pid: null };
    return { loaded: true, pid: parseLaunchdPrintPid(res.stdout || "") };
  } catch {
    return { loaded: false, pid: null };
  }
}

// The same question for the timers. The sync read above stays for the
// restart and lock paths, which cannot await.
async function readLaunchdDaemonJobAsync(): Promise<{ loaded: boolean; pid: number | null }> {
  if (platform !== "darwin" || !process.getuid) return { loaded: false, pid: null };
  try {
    const { stdout } = await _execFileAsync("launchctl", ["print", `gui/${process.getuid()}/${DAEMON_LAUNCHD_LABEL}`], {
      encoding: "utf-8",
      timeout: 5000,
    });
    return { loaded: true, pid: parseLaunchdPrintPid(stdout || "") };
  } catch {
    return { loaded: false, pid: null };
  }
}

// "Managed by launchd" must mean "launchd's supervised instance IS this process".
// The old env probe (XPC_SERVICE_NAME) survives into every {...process.env} child,
// so a self-spawned replacement believed launchd owned it: its restarts went
// through `kickstart -k`, which cannot kill a process that isn't the job instance
// and instead spawned duplicates that lost the pid-file race — while the shell
// watchdog kickstarted the "dead" job every cycle. Ask launchd, not the env.
function isManagedByLaunchd(): boolean {
  return readLaunchdDaemonJob().pid === process.pid;
}
async function isManagedByLaunchdAsync(): Promise<boolean> {
  return (await readLaunchdDaemonJobAsync()).pid === process.pid;
}

// Mutual supervision: the launchd watchdog revives the daemon, and the daemon
// (here) revives the watchdog. As long as either is alive it restores the other,
// so the pair survives sleep, crashes, `cast stop`, and the upgrade/login races
// that can boot one of them out of launchd. Without this the watchdog had no
// backstop — once it was booted out nothing brought it back, and a daemon that
// then died stayed dead (the 30-min outage we hit). Throttled so the periodic
// health tick doesn't shell out to launchctl when the watchdog is already healthy.
//
// "Loaded" is NOT "alive". A StartInterval watchdog was observed wedged at runs=1
// for 27h — launchd listed it as loaded while it had stopped firing entirely, so a
// loaded-only check (the old behavior here) saw "fine" and never revived it. The
// resident watchdog now stamps a heartbeat file every loop; we treat a stale stamp
// as a dead loop and kickstart it, mirroring how the watchdog judges the daemon.
// The detached bootout+bootstrap pair that makes an edited plist take effect:
// launchd caches the job definition at bootstrap time, so kickstart alone would
// keep running the old one. bootout kills us (we are the job instance); the same
// detached shell then bootstraps the rewritten plist. Pure so the wiring is
// testable without killing a live daemon.
export function buildLaunchdPlistReloadCommand(uid: number, plistPath: string): string {
  return `sleep 1; launchctl bootout gui/${uid}/${DAEMON_LAUNCHD_LABEL}; sleep 1; launchctl bootstrap gui/${uid} ${shellEscapeForSh(plistPath)}`;
}

// One-time fleet migration: rewrite a legacy daemon plist that points launchd
// directly at the codecast binary into the /bin/sh + launcher-script form, so the
// login item's BTM identity stops changing on every binary self-update — the
// source of the repeated macOS "codecast can run in the background" notifications
// (see supervision.ts). The existing ProgramArguments are preserved verbatim
// inside the launcher, so compiled and from-source installs both keep their exact
// command. Ends with a detached bootout+bootstrap that restarts us under the new
// definition; after that the plist contains /bin/sh and this never fires again.
function migrateDaemonPlistToStableLauncher(): void {
  const home = process.env.HOME;
  if (!home || !process.getuid) return;
  try {
    const plistPath = path.join(home, "Library", "LaunchAgents", "sh.codecast.daemon.plist");
    let content: string;
    try {
      content = fs.readFileSync(plistPath, "utf-8");
    } catch {
      return; // no autostart configured — nothing to migrate
    }
    if (!daemonPlistNeedsUpgrade(content)) return;

    const args = extractPlistProgramArguments(content);
    // Only migrate a command we can vouch for — an absolute-path executable that
    // exists. A launcher exec'ing a broken command would crash-loop under KeepAlive.
    if (args.length === 0 || !args[0].startsWith("/") || !fs.existsSync(args[0])) {
      log(`Daemon plist migration skipped: unrecognized ProgramArguments (${JSON.stringify(args)})`);
      return;
    }

    const launcherPath = path.join(CONFIG_DIR, DAEMON_LAUNCHER_FILENAME);
    const daemonCommand = args.map(shellEscapeForSh).join(" ");
    fs.writeFileSync(launcherPath, buildDaemonLauncherScript({ daemonCommand }), { mode: 0o755 });
    fs.writeFileSync(plistPath, buildDaemonPlistXml({ scriptPath: launcherPath, configDir: CONFIG_DIR }), { mode: 0o644 });

    logLifecycle("plist_stable_identity_migration", `rewrote ${plistPath} to /bin/sh launcher, reloading job`);
    persistLogQueue(); // the bootout below kills us before exit handlers run
    spawn("sh", ["-c", buildLaunchdPlistReloadCommand(process.getuid(), plistPath)], {
      detached: true,
      stdio: "ignore",
    }).unref();
  } catch (err) {
    log(`Daemon plist migration failed: ${err instanceof Error ? err.message : String(err)}`);
  }
}

/** What the supervision tick should do, from what it observed. Pure so the
 *  branches are testable without launchd. */
export function watchdogSupervisionAction(input: { loaded: boolean; plistExists: boolean; heartbeat: string | null; now: number }): "bootstrap" | "plist_missing" | "kickstart" | "none" {
  if (!input.loaded) return input.plistExists ? "bootstrap" : "plist_missing";
  // Loaded. A stale heartbeat means the loop is wedged or dead.
  return watchdogHeartbeatStale(input.heartbeat, input.now) ? "kickstart" : "none";
}

let lastWatchdogEnsureAt = 0;
let watchdogEnsureInFlight = false;
// Async: three launchctl calls on the health tick held the loop for their
// whole round trip. The throttle stamp is taken before the first await, and
// the in flight flag keeps the boot call and the tick from overlapping.
async function ensureWatchdogSupervised(force = false): Promise<void> {
  if (platform !== "darwin" || !process.getuid) return;
  const now = Date.now();
  if (!force && now - lastWatchdogEnsureAt < 4 * 60 * 1000) return;
  if (watchdogEnsureInFlight) return;
  lastWatchdogEnsureAt = now;
  watchdogEnsureInFlight = true;
  try {
    if (!(await isManagedByLaunchdAsync())) return;
    migrateDaemonPlistToStableLauncher();
    const uid = process.getuid();
    const domain = `gui/${uid}`;
    const label = "sh.codecast.watchdog";
    const launchctl = (args: string[]): Promise<boolean> =>
      _execFileAsync("launchctl", args, { timeout: 10_000 }).then(() => true, () => false);
    const plistPath = `${process.env.HOME}/Library/LaunchAgents/${label}.plist`;
    const loaded = await launchctl(["print", `${domain}/${label}`]);
    const heartbeat = loaded
      ? await fs.promises.readFile(path.join(CONFIG_DIR, WATCHDOG_HEARTBEAT_FILENAME), "utf-8").catch(() => null)
      : null;
    const action = watchdogSupervisionAction({ loaded, plistExists: fs.existsSync(plistPath), heartbeat, now });
    switch (action) {
      case "plist_missing":
        log(`Watchdog plist missing (${plistPath}): run 'cast setup' to restore supervision`);
        return;
      case "bootstrap":
        log("Watchdog launchd job not loaded: bootstrapping it");
        await launchctl(["bootstrap", domain, plistPath]);
        await launchctl(["kickstart", `${domain}/${label}`]);
        return;
      case "kickstart":
        log("Watchdog loaded but heartbeat stale: kickstarting the wedged loop");
        await launchctl(["kickstart", "-k", `${domain}/${label}`]);
        return;
      case "none":
        return;
    }
  } catch (err) {
    log(`ensureWatchdogSupervised failed: ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    watchdogEnsureInFlight = false;
  }
}

// Environment for a child daemon this process spawns itself. Strip launchd's job
// marker: the child is NOT the supervised instance, and inheriting the variable is
// how self-spawned daemons used to believe they were.
function replacementEnv(): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ...process.env, CODECAST_RESTART: "1" };
  delete env.XPC_SERVICE_NAME;
  return env;
}

function spawnReplacement(): boolean {
  try {
    const child = spawn(process.execPath, process.argv.slice(1), {
      detached: true,
      stdio: "ignore",
      env: replacementEnv(),
    });
    child.unref();
    return true;
  } catch {
    return false;
  }
}

// Force launchd to relaunch this job via `kickstart -k` (kill + start). We do NOT
// trust KeepAlive to notice our exit on its own: it has been observed to silently
// not respawn after a self-heal exit, leaving the daemon dead for hours until a
// manual kickstart. kickstart is an explicit imperative that works even when
// KeepAlive is wedged, and because it SIGKILLs us externally it also doesn't depend
// on our own exit timer firing — which matters when we're restarting precisely
// because the timer subsystem is dead (post-sleep). Detached so it outlives our exit.
// `-k` kills the current instance before starting; the brief sleep lets us flush
// and (if timers are alive) exit gracefully first, but the kill makes restart happen
// even if our own exit never does. Pure so the wiring (label, gui/$uid, -k) is testable
// without spawning a real kickstart against the live daemon.
export function buildLaunchdKickstartCommand(uid: number): string {
  return `sleep 1; launchctl kickstart -k gui/${uid}/${DAEMON_LAUNCHD_LABEL}`;
}

function requestLaunchdRestart(): boolean {
  if (platform !== "darwin" || !process.getuid) return false;
  try {
    const uid = process.getuid();
    persistLogQueue(); // SIGKILL skips exit handlers; flush queued logs first
    spawn("sh", ["-c", buildLaunchdKickstartCommand(uid)], {
      detached: true,
      stdio: "ignore",
    }).unref();
    return true;
  } catch {
    return false;
  }
}

// One restart contract for every "exit and come back" path (self-heal, remote
// restart/update, forced update, disk version mismatch). Ownership decides the
// mechanism, and ownership is read from launchd itself — never from the
// environment, which self-spawned children inherit.
function restartDaemonProcess(reason: string): void {
  const job = readLaunchdDaemonJob();
  const managed = job.pid !== null && job.pid === process.pid;
  log(`Restarting daemon (${reason}); launchd job: ${job.loaded ? (managed ? "managed" : "loaded, not ours") : "absent"}`);
  if (managed) {
    // kickstart -k kills us externally in ~1s, so the restart does not depend on
    // our own timers (dead in the post-sleep self-heal case). The delayed exit
    // below only matters if the kickstart never fires; when it works we are gone
    // before the timer runs.
    if (requestLaunchdRestart()) {
      setTimeout(() => process.exit(0), 2000);
      return;
    }
    persistLogQueue();
    process.exit(0); // KeepAlive respawns us
  }
  if (job.loaded) {
    // We are not the instance launchd supervises (a self-spawned lineage).
    // Spawning another unmanaged replacement would perpetuate that lineage and
    // keep the watchdog kickstarting a job it sees as dead. Hand ownership back:
    // free the pid file by exiting and kick the job so launchd's instance wins it.
    skipRespawn = true;
    if (!requestLaunchdRestart()) spawnReplacement();
    persistLogQueue();
    process.exit(0);
  }
  const spawned = spawnReplacement();
  if (spawned) skipRespawn = true;
  persistLogQueue();
  // Exit synchronously: the replacement is already racing for the pid file, and a
  // timer-deferred exit never happens when the timer subsystem is dead.
  process.exit(0);
}

// Cross-platform self-heal. setInterval/setTimeout do not reliably survive a long
// system sleep (kqueue-timer death on macOS, similar hazards elsewhere): they stop
// firing and never re-arm, so the daemon stays alive but every interval-based safety
// net is dead. We cannot detect that from a timer (the detector would be dead too),
// so we check from event-driven callbacks that DO resume on wake (file watcher, Convex
// socket) and restart through the existing supervisor contract (launchd KeepAlive /
// systemd Restart=always / self-respawn) to get a fresh timer subsystem. No OS-specific
// code. lastEventLoopTick is refreshed by the event-loop monitor every ~30s; if it
// drifts far past that, the monitor's timer is dead rather than merely slow.
let lastEventLoopTick = Date.now();
let selfHealing = false;
const SELF_HEAL_TICK_STALE_MS = 5 * 60 * 1000;

// Restart only when the event-loop monitor's timer is dead (tick far past its ~30s
// cadence), never when it is merely slow under load, and never twice.
export function shouldSelfHeal(
  staleMs: number,
  alreadyHealing: boolean,
  thresholdMs: number = SELF_HEAL_TICK_STALE_MS,
): boolean {
  if (alreadyHealing) return false;
  return staleMs > thresholdMs;
}

function selfHealIfTimersStalled(source: string): void {
  const stale = Date.now() - lastEventLoopTick;
  if (!shouldSelfHeal(stale, selfHealing)) return;
  selfHealing = true;
  log(`[SELF-HEAL] event-loop timer stalled ${Math.round(stale / 1000)}s (timers dead, likely post-sleep), restarting via ${source}`);
  logLifecycle("self_heal_restart", `tick stalled ${Math.round(stale / 1000)}s, via ${source}`);
  restartDaemonProcess(`event-loop timers stalled, via ${source}`);
}

// Post-sleep watcher recovery. Distinct from selfHeal (which handles a dead *timer*):
// here the timers are alive but the file watcher's FSEvents stream went silent across
// the sleep WITHOUT erroring. The daemon stays "running, connected" yet stops seeing
// file changes — the queue is empty while a transcript sits unsynced for hours. The
// 60-min idle watcher restart can't catch this because the wake handler keeps re-arming
// lastWatcherEventTime, so a laptop opened more than once an hour never accumulates a
// continuous idle hour. The cure is to stop trusting the watcher across a wake: restart
// it, then sweep for files it may have missed and push their bytes directly.
//
// Pure orchestrator (deps injected) so the order + failure handling is unit-testable,
// mirroring shouldSelfHeal/computeDaemonHealth. The restart is guarded by the same
// Promise.race timeout the watchdog uses — restart() can deadlock bun's File Watcher
// thread on a close→open, and the timeout lets recovery proceed to the sweep regardless.
// The sweep is the real safety net: even if the restart times out, the bytes still ship.
export async function runWakeRecovery(deps: {
  restartWatcher: () => Promise<void>;
  sweep: () => Promise<void>;
  onWatcherRestarted: () => void;
  log: (msg: string) => void;
  logError: (msg: string, err: Error) => void;
  restartTimeoutMs?: number;
}): Promise<void> {
  const timeoutMs = deps.restartTimeoutMs ?? 10_000;
  try {
    await Promise.race([
      deps.restartWatcher(),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error(`wake watcher restart timeout after ${Math.round(timeoutMs / 1000)}s`)), timeoutMs),
      ),
    ]);
    deps.onWatcherRestarted();
    deps.log("Wake recovery: file watcher restarted");
  } catch (err) {
    deps.logError("Wake recovery: watcher restart failed (continuing to sweep)", err instanceof Error ? err : new Error(String(err)));
  }

  try {
    await deps.sweep();
  } catch (err) {
    deps.logError("Wake recovery: unsynced sweep failed", err instanceof Error ? err : new Error(String(err)));
  }
}

const CRASH_FILE = path.join(CONFIG_DIR, "crash-count.json");

function recordCrash(): { count: number; backoffMinutes: number } {
  try {
    let crashes: { count: number; firstCrash: number } = { count: 0, firstCrash: Date.now() };
    if (fs.existsSync(CRASH_FILE)) {
      crashes = JSON.parse(fs.readFileSync(CRASH_FILE, "utf-8"));
    }
    const windowMs = 30 * 60 * 1000;
    if (Date.now() - crashes.firstCrash > windowMs) {
      crashes = { count: 0, firstCrash: Date.now() };
    }
    crashes.count++;
    fs.writeFileSync(CRASH_FILE, JSON.stringify(crashes));
    const backoffMinutes = crashes.count <= 3 ? 0 : Math.min(crashes.count * 2, 30);
    return { count: crashes.count, backoffMinutes };
  } catch {
    return { count: 1, backoffMinutes: 0 };
  }
}

function clearCrashCount(): void {
  try { if (fs.existsSync(CRASH_FILE)) fs.unlinkSync(CRASH_FILE); } catch {}
}

function readPidFile(pidFile: string): number | null {
  try {
    const pid = parseInt(fs.readFileSync(pidFile, "utf-8").trim(), 10);
    return Number.isFinite(pid) && pid > 0 ? pid : null;
  } catch {
    return null;
  }
}

export function tryAcquirePidFileLock(
  pidFile: string,
  pid: number,
  options: {
    nowMs?: number;
    staleGraceMs?: number;
    isProcessRunning?: (pid: number) => boolean;
  } = {},
): boolean {
  const nowMs = options.nowMs ?? Date.now();
  const staleGraceMs = options.staleGraceMs ?? PID_FILE_STALE_GRACE_MS;
  const isPidRunning = options.isProcessRunning ?? isProcessRunning;

  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const fd = fs.openSync(pidFile, "wx", 0o600);
      try {
        fs.writeFileSync(fd, `${pid}\n`);
        fs.fsyncSync(fd);
      } finally {
        fs.closeSync(fd);
      }
      return true;
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code !== "EEXIST") return false;
    }

    const existingPid = readPidFile(pidFile);
    if (existingPid === pid) return true;
    if (existingPid && isPidRunning(existingPid)) return false;

    let stat: fs.Stats;
    try {
      stat = fs.statSync(pidFile);
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code === "ENOENT") continue;
      return false;
    }

    if (nowMs - stat.mtimeMs < staleGraceMs) {
      return false;
    }

    try {
      fs.unlinkSync(pidFile);
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code === "ENOENT") continue;
      return false;
    }
  }

  return false;
}

export function releasePidFileIfOwned(pidFile: string, pid: number): boolean {
  if (readPidFile(pidFile) !== pid) return false;
  try {
    fs.unlinkSync(pidFile);
    return true;
  } catch {
    return false;
  }
}

function acquireLock(): boolean {
  const underLaunchd = isManagedByLaunchd();

  if (underLaunchd) {
    // We are the instance launchd supervises — the rightful pid-file owner. A live
    // holder that isn't us is a rogue from a self-spawned lineage; deferring to it
    // ("already running, exiting") sustains the watchdog's kickstart storm, spawning
    // a doomed duplicate every cycle. Take over instead.
    const holder = readPidFile(PID_FILE);
    if (holder && holder !== process.pid && isProcessRunning(holder)) {
      log(`Killing rogue daemon ${holder} (launchd instance taking over)`);
      try { process.kill(holder, "SIGKILL"); } catch {}
      releasePidFileIfOwned(PID_FILE, holder);
    }
  } else {
    // Even without a PID file, check for zombie daemon processes (e.g. from a
    // shutdown that deleted the PID file but failed to exit).
    try {
      const pgrepOut = execSync(`pgrep -f 'daemon\\.ts$' 2>/dev/null || true`, { encoding: "utf-8", timeout: 3000 });
      const pids = pgrepOut.trim().split("\n").map(Number).filter(p => p && p !== process.pid && isProcessRunning(p));
      for (const zombiePid of pids) {
        log(`Killing zombie daemon process ${zombiePid}`);
        try { process.kill(zombiePid, "SIGKILL"); } catch {}
      }
    } catch {}
  }

  return tryAcquirePidFileLock(PID_FILE, process.pid);
}

// The watchdog's three stale sweeps differ only in where they look and what
// makes one file stale; skipping a missing tree, ignoring anything older than
// maxAgeMs and returning newest first is common to all three. The walk is async
// so a sweep over tens of thousands of transcripts never pins the loop.
async function findStaleFiles(
  root: string,
  walk: WalkOptions,
  maxAgeMs: number,
  isStale: (file: WalkFile) => boolean,
): Promise<string[]> {
  if (!fs.existsSync(root)) return [];
  const now = Date.now();
  const stale: WalkFile[] = [];
  await walkFiles(root, walk, (f) => {
    if (now - f.stat.mtimeMs > maxAgeMs) return;
    try {
      if (isStale(f)) stale.push(f);
    } catch {
      // unreadable this pass
    }
  });
  stale.sort((a, b) => b.stat.mtimeMs - a.stat.mtimeMs);
  return stale.map((f) => f.path);
}

// Top-level <project>/<session>.jsonl only.
function findStaleSessionFiles(maxAgeMs: number = 7 * 24 * 60 * 60 * 1000): Promise<string[]> {
  return findStaleFiles(
    path.join(process.env.HOME || "", ".claude", "projects"),
    { maxDepth: 2, fileFilter: (rel) => rel.endsWith(".jsonl") },
    maxAgeMs,
    (f) => shouldTreatClaudeFileAsStale(f.stat, getSyncRecord(f.path)),
  );
}

export function shouldTreatClaudeFileAsStale(
  fileStat: { mtimeMs: number; size: number },
  syncRecord: SyncRecord | null
): boolean {
  if (!syncRecord) {
    return true;
  }
  if (!syncRecord.isLegacyFallback && fileStat.mtimeMs > syncRecord.lastSyncedAt) {
    return true;
  }
  return fileStat.size > syncRecord.lastSyncedPosition;
}

// Defined in codexWatcher.ts so the `cast status` stuck-sync report (index.ts) can
// share it without importing the whole daemon module. Re-exported here for existing
// importers of "./daemon.js" (e.g. daemon.stale.test.ts).
export { isAppServerManagedCodexSessionHead };

// A codex transcript the app server manages is written by that server, not by
// us, so a position behind its size is expected and not stale.
function findStaleCodexSessionFiles(maxAgeMs: number = 7 * 24 * 60 * 60 * 1000): Promise<string[]> {
  return findStaleFiles(
    path.join(process.env.HOME || "", ".codex", "sessions"),
    { fileFilter: (rel) => rel.endsWith(".jsonl") },
    maxAgeMs,
    (f) => f.stat.size !== getPosition(f.path) && !isAppServerManagedCodexSessionHead(readFileHead(f.path, 2048)),
  );
}

function detectCursorPath(): string {
  const platform = process.platform;
  const home = process.env.HOME || "";

  if (platform === "darwin") {
    return path.join(home, "Library", "Application Support", "Cursor");
  } else if (platform === "linux") {
    return path.join(home, ".config", "Cursor");
  } else if (platform === "win32") {
    return path.join(process.env.APPDATA || "", "Cursor");
  }

  return path.join(home, ".cursor");
}

function getCursorWorkspaceStoragePath(): string | null {
  const cursorPath = detectCursorPath();
  const workspaceStoragePath = path.join(cursorPath, "User", "workspaceStorage");
  if (!fs.existsSync(workspaceStoragePath)) {
    return null;
  }
  return workspaceStoragePath;
}

function getCursorWorkspaceFolderPath(workspaceStorageDir: string): string | null {
  const workspaceJsonPath = path.join(workspaceStorageDir, "workspace.json");
  try {
    if (!fs.existsSync(workspaceJsonPath)) {
      return null;
    }
    const content = fs.readFileSync(workspaceJsonPath, "utf-8");
    const data = JSON.parse(content);

    const folderUri = data.folder || data.workspace;
    if (!folderUri) {
      return null;
    }

    if (folderUri.startsWith("file://")) {
      const decoded = decodeURIComponent(folderUri.slice(7));
      if (process.platform === "win32" && decoded.match(/^\/[A-Z]:/i)) {
        return decoded.slice(1);
      }
      return decoded;
    }

    return folderUri;
  } catch {
    return null;
  }
}

function getCursorMaxRowId(dbPath: string): number {
  let db: Database | null = null;
  try {
    db = new Database(dbPath, { readonly: true });

    const tableExists = db
      .query<{ name: string }, []>(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='ItemTable'"
      )
      .get();

    if (!tableExists) {
      return 0;
    }

    const maxRowIdResult = db
      .query<{ maxRowId: number | null }, []>(
        "SELECT MAX(rowid) as maxRowId FROM ItemTable WHERE key = 'workbench.panel.aichat.view.aichat.chatdata'"
      )
      .get();

    return maxRowIdResult?.maxRowId ?? 0;
  } catch {
    return 0;
  } finally {
    if (db) {
      db.close();
    }
  }
}

interface CursorComposerData {
  allComposers?: Array<{
    composerId?: string;
  }>;
}

function getCursorComposerData(dbPath: string): CursorComposerData | null {
  let db: Database | null = null;
  try {
    db = new Database(dbPath, { readonly: true });
    const row = db
      .query<{ value: string }, []>(
        "SELECT value FROM ItemTable WHERE key = 'composer.composerData' LIMIT 1"
      )
      .get();
    if (!row?.value) {
      return null;
    }
    return JSON.parse(row.value) as CursorComposerData;
  } catch {
    return null;
  } finally {
    if (db) {
      db.close();
    }
  }
}

function findWorkspacePathForCursorConversation(sessionId: string): string | null {
  const workspaceStoragePath = getCursorWorkspaceStoragePath();
  if (!workspaceStoragePath) {
    return null;
  }

  let workspaceDirs: string[];
  try {
    workspaceDirs = fs.readdirSync(workspaceStoragePath);
  } catch {
    return null;
  }

  for (const workspaceHash of workspaceDirs) {
    const dbPath = path.join(workspaceStoragePath, workspaceHash, "state.vscdb");
    if (!fs.existsSync(dbPath)) {
      continue;
    }

    const composerData = getCursorComposerData(dbPath);
    const composers = composerData?.allComposers || [];
    if (!composers.some(c => c.composerId === sessionId)) {
      continue;
    }

    const workspaceStorageDir = path.dirname(dbPath);
    return getCursorWorkspaceFolderPath(workspaceStorageDir);
  }

  return null;
}

interface StaleCursorSession {
  sessionId: string;
  workspacePath: string;
  dbPath: string;
  mtimeMs: number;
}

// The last sweep's row count per db, keyed on the newest of the db and its
// wal mtime: a write lands in the wal first and the db's own mtime only moves
// on checkpoint (the same rule cursorWatcher uses). The sqlite open is the
// one sync step here, so it runs only for a db that changed since last time;
// the position compare still runs every sweep, so a failed sync is retried.
const cursorStaleSweepSeen = new Map<string, { mtimeMs: number; maxRowId: number }>();
export async function findStaleCursorSessions(maxAgeMs: number = 7 * 24 * 60 * 60 * 1000): Promise<StaleCursorSession[]> {
  const workspaceStoragePath = getCursorWorkspaceStoragePath();
  if (!workspaceStoragePath) return [];
  const now = Date.now();
  const newestByDb = new Map<string, number>();
  await walkFiles(
    workspaceStoragePath,
    { maxDepth: 2, fileFilter: (rel) => /state\.vscdb(-wal)?$/.test(rel) },
    (f) => {
      const dbPath = f.path.endsWith("-wal") ? f.path.slice(0, -"-wal".length) : f.path;
      newestByDb.set(dbPath, Math.max(newestByDb.get(dbPath) ?? 0, f.stat.mtimeMs));
    },
  );

  const staleSessions: StaleCursorSession[] = [];
  for (const [dbPath, mtimeMs] of newestByDb) {
    if (now - mtimeMs > maxAgeMs) continue;
    try {
      let seen = cursorStaleSweepSeen.get(dbPath);
      if (!seen || seen.mtimeMs !== mtimeMs) {
        seen = { mtimeMs, maxRowId: timeSyncFs("getCursorMaxRowId", dbPath, () => getCursorMaxRowId(dbPath)) };
        cursorStaleSweepSeen.set(dbPath, seen);
      }
      if (seen.maxRowId <= 0) continue;
      if (seen.maxRowId <= getPosition(dbPath)) continue;

      const workspaceStorageDir = path.dirname(dbPath);
      const workspaceHash = path.basename(workspaceStorageDir);
      staleSessions.push({
        sessionId: workspaceHash,
        workspacePath: getCursorWorkspaceFolderPath(workspaceStorageDir) || workspaceHash,
        dbPath,
        mtimeMs,
      });
    } catch {
      continue;
    }
  }

  staleSessions.sort((a, b) => b.mtimeMs - a.mtimeMs);
  return staleSessions;
}

function findStaleCursorTranscriptFiles(maxAgeMs: number = 7 * 24 * 60 * 60 * 1000): Promise<string[]> {
  return findStaleFiles(
    path.join(process.env.HOME || "", ".cursor", "projects"),
    { fileFilter: (rel) => rel.endsWith(".txt") && rel.includes(`${path.sep}agent-transcripts${path.sep}`) },
    maxAgeMs,
    (f) => f.stat.size !== getPosition(f.path),
  );
}

interface WatchdogDependencies {
  config: Config;
  syncService: SyncService;
  conversationCache: ConversationCache;
  retryQueue: RetryQueue;
  pendingMessages: PendingMessages;
  titleCache: TitleCache;
  updateState: () => void;
  watcher: SessionWatcher;
}

function compareVersions(a: string, b: string): number {
  const partsA = a.split(".").map(Number);
  const partsB = b.split(".").map(Number);
  for (let i = 0; i < Math.max(partsA.length, partsB.length); i++) {
    const numA = partsA[i] || 0;
    const numB = partsB[i] || 0;
    if (numA > numB) return 1;
    if (numA < numB) return -1;
  }
  return 0;
}

async function checkForForcedUpdate(syncService: SyncService): Promise<boolean> {
  try {
    const minVersion = await syncService.getMinCliVersion();
    if (!minVersion) return false;

    const currentVersion = getVersion();
    if (compareVersions(currentVersion, minVersion) < 0) {
      logLifecycle("forced_update_start", `current=${currentVersion} min=${minVersion}`);
      await flushRemoteLogs();
      const result = await performUpdate();
      if (result.success) {
        logLifecycle("forced_update_complete", `Binary replaced from v${currentVersion}, target>=${minVersion}`);
        await flushRemoteLogs();
        restartDaemonProcess(`forced update to >=${minVersion}`);
      } else {
        logLifecycle("forced_update_failed", `current=${currentVersion} target>=${minVersion} error=${result.error}`);
        await flushRemoteLogs();
      }
      return false;
    }
    return false;
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err);
    logError(`Forced update check failed`, err instanceof Error ? err : undefined);
    return false;
  }
}

function checkDiskVersionMismatch(): void {
  try {
    const updateTsPath = path.join(__dirname, "update.ts");
    const updateJsPath = path.join(__dirname, "update.js");
    const filePath = fs.existsSync(updateTsPath) ? updateTsPath : updateJsPath;
    if (!fs.existsSync(filePath)) return;

    const content = fs.readFileSync(filePath, "utf-8");
    const match = content.match(/const VERSION\s*=\s*["']([^"']+)["']/);
    if (!match) return;

    const diskVersion = match[1];
    if (diskVersion !== daemonVersion) {
      log(`Disk version mismatch: running=${daemonVersion} disk=${diskVersion}, restarting`);
      logLifecycle("version_mismatch_restart", `${daemonVersion} -> ${diskVersion}`);
      flushRemoteLogs()
        .then(() => restartDaemonProcess("disk version mismatch"))
        .catch(() => restartDaemonProcess("disk version mismatch"));
    }
  } catch {}
}

// A frozen event loop is invisible after the fact: nothing runs, so nothing
// logs, and the 30s monitor only says "a gap happened". This fine probe ticks
// every 500ms and names the freeze the moment the loop unblocks — how long,
// and how much CPU the process burned meanwhile (near zero = blocked in a
// syscall/child wait; near wall = pinned by our own compute). Paired with the
// per-call [SLOW-SYNC-SPAWN] report from proc.ts, a stall reads as "the loop
// froze 40s, and here are the sync spawns that ran inside it".
const LOOP_FREEZE_PROBE_INTERVAL_MS = 500;
const LOOP_FREEZE_REPORT_MS = 5_000;

// Aggregate JSC sampling-profiler traces into "the functions the loop spent its
// time in", so a freeze report can name the code that pinned it. Counts every
// frame on every stack (not just the leaf): the leaf is often a tiny helper,
// while the frame the reader can act on — the sync sweep driving it — appears
// mid-stack. Self-recursion is deduped per trace so a deep recursive walk
// doesn't count once per level. Exported for tests.
// Rolling ledger of loop freezes so the heartbeat can report how much of the
// last minute the daemon was blocked. The web turns this into an "under load"
// state and the per-message delivery note reads it: a message that has not
// echoed while the loop was frozen 40s of the last 60s is delayed by the
// daemon, not lost by the session, and must not prompt a kill & restart.
export class LoopFreezeLedger {
  private events: Array<{ at: number; ms: number }> = [];
  constructor(private readonly windowMs = 60_000) {}
  record(ms: number, now = Date.now()): void {
    this.events.push({ at: now, ms });
    this.prune(now);
  }
  /** Total ms the loop was blocked inside the trailing window. */
  recentMs(now = Date.now()): number {
    this.prune(now);
    return this.events.reduce((sum, e) => sum + e.ms, 0);
  }
  private prune(now: number): void {
    const cutoff = now - this.windowMs;
    while (this.events.length && this.events[0].at < cutoff) this.events.shift();
  }
}
const loopFreezes = new LoopFreezeLedger();
const daemonStartedAt = Date.now();

// A probe tick that lands minutes late with almost no CPU burned is the machine
// having been asleep, not the loop being pinned: a closed lid yields a 15-minute
// gap with ~6ms of CPU, while a loop genuinely blocked on a busy disk still
// accrues tens of ms per second churning between syscalls (the 42s walk freeze
// of 2026-09-02 burned 928ms). Counting a suspend as a freeze lit "daemon under
// load" for a minute after every wake — ~30 times a day on a laptop — over a
// daemon that was doing nothing wrong. Short gaps always count: a 5s sleep is
// not a thing, and a 5s blocked spawn is real. Exported for tests.
export const SUSPEND_GAP_MIN_MS = 30_000;
export const SUSPEND_CPU_RATE = 0.005;
export function isSuspendGap(lateMs: number, cpuMs: number): boolean {
  return lateMs >= SUSPEND_GAP_MIN_MS && cpuMs < lateMs * SUSPEND_CPU_RATE;
}

export function summarizeSamplingTraces(raw: unknown, top = 5): string {
  let parsed: any = raw;
  if (typeof raw === "string") {
    try { parsed = JSON.parse(raw); } catch { return ""; }
  }
  const traces: any[] = Array.isArray(parsed?.traces) ? parsed.traces : [];
  if (traces.length === 0) return "";
  const counts = new Map<string, number>();
  for (const t of traces) {
    const seen = new Set<string>();
    for (const f of t?.frames ?? []) {
      const name = f?.name || "(anonymous)";
      const url = typeof f?.sourceURL === "string" ? f.sourceURL.split("/").slice(-1)[0] : "";
      const key = url ? `${name}@${url}:${f?.line ?? "?"}` : name;
      if (seen.has(key)) continue;
      seen.add(key);
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, top)
    .map(([key, n]) => `${key} ${Math.round((n / traces.length) * 100)}%`)
    .join(", ");
}

function startLoopFreezeProbe(): NodeJS.Timeout {
  // One sink for both sync spawns and sync filesystem work (slowSync.ts).
  setSlowSyncSink((message) => log(message));
  // JSC's sampling profiler runs on its own thread, so it keeps collecting JS
  // stacks even while the event loop is pinned — exactly the window nothing
  // else can observe. Draining the buffer every tick keeps it bounded; when a
  // tick arrives late, the drained traces cover the freeze and name the code.
  let drainTraces: (() => unknown) | null = null;
  // darwin only: startSamplingProfiler SEGFAULTS bun on Linux (verified on
  // 1.3.14 and 1.4.0, x64 — a native crash the try/catch cannot contain, which
  // killed the remote daemon 300ms into every boot). The freeze probe below
  // still runs without it; it just cannot name the code that pinned the loop.
  if (process.platform === "darwin") {
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const jsc = require("bun:jsc");
      jsc.startSamplingProfiler(process.env.TMPDIR || "/tmp");
      drainTraces = () => jsc.samplingProfilerStackTraces();
      drainTraces(); // discard everything sampled before the probe started
    } catch {}
  }
  let lastProbe = Date.now();
  let lastCpu = process.cpuUsage();
  // Snapshot of lastLogLine at the previous tick: the newest line written
  // before the loop stopped ticking. (Reading lastLogLine at report time would
  // name whatever logged first AFTER the freeze — the wrong side of it.)
  let logAtLastProbe = lastLogLine;
  const t = setInterval(() => {
    const now = Date.now();
    const late = now - lastProbe - LOOP_FREEZE_PROBE_INTERVAL_MS;
    const cpu = process.cpuUsage(lastCpu);
    lastProbe = now;
    lastCpu = process.cpuUsage();
    let traces: unknown = null;
    try { traces = drainTraces?.(); } catch {}
    if (late >= LOOP_FREEZE_REPORT_MS) {
      const cpuMs = Math.round((cpu.user + cpu.system) / 1000);
      const suspend = isSuspendGap(late, cpuMs);
      if (!suspend) loopFreezes.record(late, now);
      const hot = summarizeSamplingTraces(traces);
      log(
        `[LOOP-FREEZE] event loop blocked ${Math.round(late / 1000)}s (${cpuMs}ms CPU during the freeze${suspend ? "; machine was suspended, not counted as load" : ""}); ` +
        `last log before it: ${logAtLastProbe}${hot ? `; hot stacks: ${hot}` : ""}`,
      );
    }
    logAtLastProbe = lastLogLine;
  }, LOOP_FREEZE_PROBE_INTERVAL_MS);
  t.unref?.();
  return t;
}

function startEventLoopMonitor(): NodeJS.Timeout {
  let lastTickTime = Date.now();
  let lastTickCpu = process.cpuUsage();
  startLoopFreezeProbe();

  return setInterval(() => {
    const now = Date.now();
    const elapsed = now - lastTickTime;
    lastTickTime = now;
    const cpuDelta = process.cpuUsage(lastTickCpu);
    lastTickCpu = process.cpuUsage();

    saveDaemonState({ lastHeartbeatTick: now });
    lastEventLoopTick = now;

    if (elapsed > EVENT_LOOP_LAG_THRESHOLD_MS) {
      // Only a genuine suspend gets recovery. A busy stall means the loop was
      // pinned by our own synchronous work; firing the recovery sweep here is what
      // used to turn one stall into a self-sustaining freeze loop (see
      // classifyTickGap). The watcher never died during a stall — the process was
      // running the whole time — so there is nothing to recover.
      const cpuMs = (cpuDelta.user + cpuDelta.system) / 1000;
      if (classifyTickGap(elapsed, cpuMs) === "stall") {
        logLifecycle("event_loop_stall", `Event loop pinned for ${Math.round(elapsed / 1000)}s (${Math.round(cpuMs / 1000)}s CPU) — skipping wake recovery`);
        return;
      }
      logLifecycle("wake_detected", `System was suspended for ${Math.round(elapsed / 1000)}s, recovering`);
      // Re-arm to `now` so the watchdog's 60-min idle path doesn't also fire a
      // redundant restart in the gap before recovery completes. We no longer rely
      // on that path as the safety net: the watcher's FSEvents stream can go silent
      // across a sleep WITHOUT erroring, and a frequently-woken laptop never
      // accumulates a continuous idle hour for the watchdog to notice. Instead drive
      // recovery directly — restart the watcher and sweep for unsynced files. The
      // handler re-arms lastWatcherEventTime again after a successful restart. Null
      // only during early boot, before config/caches/watcher are wired.
      lastWatcherEventTime = now;
      wakeRecoveryHandler?.();
    }
  }, EVENT_LOOP_CHECK_INTERVAL_MS);
}

function startVersionChecker(syncService: SyncService): NodeJS.Timeout {
  checkForForcedUpdate(syncService);
  maybeUpdateDesktopApp(syncService);

  return setInterval(() => {
    checkForForcedUpdate(syncService);
    maybeUpdateDesktopApp(syncService);
  }, VERSION_CHECK_INTERVAL_MS);
}

// Out-of-band updater for the Codecast desktop app: Squirrel.Mac's in-app
// auto-update is wedged on macOS 26 (launchd never runs its ShipIt helper), so
// the daemon — which updates over a Squirrel-independent channel — finishes the
// job. Gated on config (opt-out) and guarded against disrupting a running app.
function maybeUpdateDesktopApp(syncService: SyncService): void {
  const config = readConfig();
  if (config?.desktop_auto_update === false) return;
  // Pull the server-pinned floor: when the installed app is below it,
  // checkForDesktopUpdate applies even while the app is running so always-open
  // clients converge (the routine, unpinned path only swaps when the app is
  // closed). Mirrors checkForForcedUpdate's min_cli_version handling.
  void (async () => {
    let minVersion: string | null = null;
    try {
      minVersion = await syncService.getMinDesktopVersion();
    } catch {}
    await checkForDesktopUpdate((msg) => log(msg), { minVersion });
  })().catch(() => {});
}

async function logHealthReport(retryQueue: RetryQueue, config: Config): Promise<void> {
  const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
  const unsyncedFiles = await findUnsyncedFilesAsync(
    claudeProjectsDir,
    undefined,
    (filePath) => isTranscriptFileInSyncScope(filePath, config),
  );
  const droppedCount = retryQueue.getDroppedOperationCount();
  const queueSize = retryQueue.getLogicalQueueSize();

  if (unsyncedFiles.length > 0 || droppedCount > 0 || queueSize > 10) {
    logWarn(
      `Health: ${unsyncedFiles.length} pending files, ${droppedCount} dropped ops, ${queueSize} in retry queue`
    );
  }
}

function startReconciliation(
  syncService: SyncService,
  retryQueue: RetryQueue,
  conversationCache: ConversationCache,
  config: Config,
): NodeJS.Timeout {
  log("Reconciliation scheduler started (runs every hour)");

  // Run initial reconciliation after 5 minutes (let daemon stabilize first)
  setTimeout(async () => {
    try {
      // Log health report
      await logHealthReport(retryQueue, config);

      const result = await performReconciliation(
        syncService,
        (msg, level) => log(msg, level || "info"),
        conversationCache,
        50,
        config,
      );

      if (result.discrepancies.length > 0) {
        logWarn(`Reconciliation found ${result.discrepancies.length} discrepancies`);
        // Auto-repair by resetting positions
        const repaired = await repairDiscrepancies(result.discrepancies, log);
        log(`Reconciliation: Reset ${repaired} sessions for re-sync`);
        // repairDiscrepancies only rewinds positions; the byte-push is normally
        // watcher-driven, so a silent post-sleep watcher would leave the reset files
        // sitting unsynced. Drive the sweep directly — this is what makes reconciliation
        // a real watcher-independent backstop rather than one that also waits on the watcher.
        if (repaired > 0) {
          await pushUnsyncedFilesHandler?.("Reconciliation");
        }
      }
    } catch (err) {
      logError("Initial reconciliation failed", err instanceof Error ? err : new Error(String(err)));
    }
  }, 5 * 60 * 1000);

  return setInterval(async () => {
    const state = readDaemonState();
    if (state?.authExpired) {
      return;
    }

    try {
      // Log health report
      await logHealthReport(retryQueue, config);

      const result = await performReconciliation(
        syncService,
        (msg, level) => log(msg, level || "info"),
        conversationCache,
        50,
        config,
      );

      if (result.discrepancies.length > 0) {
        logWarn(`Reconciliation found ${result.discrepancies.length} discrepancies`);
        const repaired = await repairDiscrepancies(result.discrepancies, log);
        log(`Reconciliation: Reset ${repaired} sessions for re-sync`);
        // repairDiscrepancies only rewinds positions; the byte-push is normally
        // watcher-driven, so a silent post-sleep watcher would leave the reset files
        // sitting unsynced. Drive the sweep directly — this is what makes reconciliation
        // a real watcher-independent backstop rather than one that also waits on the watcher.
        if (repaired > 0) {
          await pushUnsyncedFilesHandler?.("Reconciliation");
        }
      }
    } catch (err) {
      logError("Reconciliation failed", err instanceof Error ? err : new Error(String(err)));
    }
  }, RECONCILIATION_INTERVAL_MS);
}

// Tier 3 warm pool. Opt-in via config.warm_pool_size (default 0 = off). Re-resumes
// the N most-recently-active sessions whose agent has died, so a follow-up lands on a
// live agent instead of a cold boot. Reuses autoResumeSession in resume-only mode
// (empty content) — and autoResumeSession self-guards against duplicating a live
// agent, so a stale aliveness read here can only cost a cheap no-op, never a double
// spawn. Bounded by cap and a short recency window; runs at the end of the watchdog
// tick, after stale status files are reaped, so just-completed sessions are excluded.
const WARM_POOL_RECENCY_WINDOW_MS = 15 * 60 * 1000;

/**
 * Every hook status record on disk, read off the loop. The watchdog's stale
 * sweep, the warm pool and the hourly cleanup all iterate this directory; a
 * sync readdir plus a read per file held the loop once per pass with a few
 * hundred live sessions. A corrupt record reports `data: null`; a file that
 * vanished between the listing and the read is skipped. `dir` is a parameter
 * because AGENT_STATUS_DIR is fixed from HOME at import, so tests pass a temp dir.
 */
export async function readAgentStatusFiles(dir = AGENT_STATUS_DIR): Promise<Array<{ sessionId: string; filePath: string; mtimeMs: number; data: HookStatusData | null }>> {
  let names: string[];
  try {
    names = (await fs.promises.readdir(dir)).filter((f) => f.endsWith(".json"));
  } catch {
    return [];
  }
  const out: Array<{ sessionId: string; filePath: string; mtimeMs: number; data: HookStatusData | null }> = [];
  await runBounded(names, 16, async (name) => {
    const filePath = path.join(dir, name);
    let mtimeMs: number;
    let raw: string;
    try {
      mtimeMs = (await fs.promises.stat(filePath)).mtimeMs;
      raw = await fs.promises.readFile(filePath, "utf-8");
    } catch {
      return;
    }
    let data: HookStatusData | null = null;
    try {
      data = JSON.parse(raw) as HookStatusData;
    } catch {
      data = null;
    }
    out.push({ sessionId: path.basename(name, ".json"), filePath, mtimeMs, data });
  }, "Agent status read");
  return out;
}

async function prewarmRecentlyActiveSessions(deps: WatchdogDependencies): Promise<void> {
  const cap = deps.config.warm_pool_size ?? 0;
  if (cap <= 0) return;
  if (!hasTmux()) return;

  const now = Date.now();
  // Cheap prefilter (status + recency + has conversation) so the expensive aliveness
  // probe runs on a handful of sessions, not all of them.
  const prefiltered: Array<{ sessionId: string; convId: string; status: string; tsMs: number }> = [];
  for (const { sessionId, data } of await readAgentStatusFiles()) {
    if (!data?.ts) continue;
    const tsMs = data.ts * 1000;
    if (now - tsMs > WARM_POOL_RECENCY_WINDOW_MS) continue;
    if (!WARM_POOL_ACTIVE_STATUSES.has(data.status)) continue;
    const convId = deps.conversationCache[sessionId];
    if (!convId) continue;
    prefiltered.push({ sessionId, convId, status: data.status, tsMs });
  }
  if (prefiltered.length === 0) return;

  const candidates: WarmCandidate[] = [];
  for (const p of prefiltered) {
    let agentAlive = false;
    try {
      const live = await resolveLiveTmuxTarget(p.convId, p.sessionId, "claude");
      agentAlive = !!live.tmuxTarget;
    } catch {}
    candidates.push({
      sessionId: p.sessionId,
      status: p.status,
      tsMs: p.tsMs,
      agentAlive,
      circuitOpen: isSessionCircuitOpen(p.sessionId),
      fatal: resumeFatalReasons.has(p.sessionId),
    });
  }

  const toWarm = selectSessionsToWarm(candidates, now, { recencyWindowMs: WARM_POOL_RECENCY_WINDOW_MS, cap });
  const aliveCount = candidates.filter(c => c.agentAlive).length;
  log(`Warm pool: evaluated ${candidates.length} recent active session(s) — ${aliveCount} already warm, ${candidates.length - aliveCount} dead, warming ${toWarm.length} (cap=${cap})`);
  if (toWarm.length === 0) return;
  log(`Warm pool: re-warming session(s) with dead agents: ${toWarm.map(s => s.slice(0, 8)).join(", ")}`);
  for (const sessionId of toWarm) {
    const convId = deps.conversationCache[sessionId];
    try {
      // Empty content = resume-only: spin up the agent, inject nothing.
      const ok = await autoResumeSession(sessionId, "", deps.titleCache, undefined, convId);
      log(`Warm pool: ${ok ? "re-warmed" : "failed to re-warm"} session ${sessionId.slice(0, 8)}`);
    } catch (err) {
      log(`Warm pool: error re-warming ${sessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
}

// Decide whether the stale-status watchdog should mark a session "completed".
// The watchdog's job is to catch sessions that ended without a SessionEnd hook,
// using idle time as a proxy for "the agent died". But a live agent simply
// waiting for the user's next prompt is indistinguishable from a dead one by
// time alone — so we ONLY reap when the agent process is genuinely gone. Marking
// a live, idle-waiting session completed flips its conversation to "stopped" in
// the UI and stops the web from streaming the next turn until a manual reload
// (root cause of "tmux messages didn't sync to the web UI" after an idle gap).
// `hasLiveAgentProcess` is a positive signal only; when no process is found we
// fall back to the original time-based behavior (never more aggressive).
export function shouldMarkSessionCompleted(args: {
  status: string | undefined;
  ageMs: number;
  hasLiveAgentProcess: boolean;
  idleStaleMs?: number;
  activeStaleMs?: number;
}): boolean {
  if (args.hasLiveAgentProcess) return false;
  const idleStaleMs = args.idleStaleMs ?? 10 * 60 * 1000;
  const activeStaleMs = args.activeStaleMs ?? 30 * 60 * 1000;
  const threshold =
    args.status === "idle" || args.status === "stopped" ? idleStaleMs : activeStaleMs;
  return args.ageMs >= threshold;
}

function startWatchdog(
  deps: WatchdogDependencies
): NodeJS.Timeout {
  log("Watchdog started");
  let watchdogRunning = false;
  let watchdogStartedAt = 0;
  const WATCHDOG_TIMEOUT_MS = 4 * 60 * 1000; // 4 minutes - must complete before next 5-min interval

  return setInterval(async () => {
    if (isInWakeGrace()) return;
    if (watchdogRunning) {
      const elapsed = Date.now() - watchdogStartedAt;
      if (elapsed > WATCHDOG_TIMEOUT_MS) {
        log(`[WARN] Watchdog stalled for ${Math.round(elapsed / 1000)}s, force-resetting`);
        watchdogRunning = false;
      } else {
        return;
      }
    }
    watchdogRunning = true;
    watchdogStartedAt = Date.now();
    try {
    const state = readDaemonState();
    const now = Date.now();

    saveDaemonState({ lastWatchdogCheck: now });

    if (state?.authExpired) {
      return;
    }

    if (isSyncPaused()) {
      return;
    }

    // Validate process cache
    validateProcessCache().catch(() => {});

    // Prune the daemon's internal tracking of started sessions older than
    // STARTED_SESSION_TTL_MS. Two cases:
    //   - tmux has-session fails → the session is genuinely gone, just untrack.
    //   - tmux still exists → stop tracking it but leave the pane alone. The
    //     user may still be using it; "agent process not visible" is the weak
    //     signal we no longer trust as grounds for tearing down a pane.
    for (const [convId, entry] of startedSessionTmux.entries()) {
      if (now - entry.startedAt > STARTED_SESSION_TTL_MS) {
        try {
          await tmuxExec(["has-session", "-t", entry.tmuxSession], { timeout: 3000, killSignal: "SIGKILL" });
          log(`Untracking started session ${entry.tmuxSession} after ${Math.round((now - entry.startedAt) / 3600000)}h (leaving tmux in place)`);
          deleteStartedSession(convId);
        } catch {
          deleteStartedSession(convId);
        }
      }
    }

    // Zombie reaping of untracked cc-resume-*/cc-claude-* tmux sessions has been
    // removed. It used the same weak isTmuxAgentAlive signal that we no longer
    // act on. Orphan accumulation is a manual cleanup — `tmux kill-session` from
    // a shell, or the UI's Kill & restart on a specific conversation.

    // Mark stale agent-status files as completed (session ended without SessionEnd hook)
    try {
      const IDLE_STALE_MS = 10 * 60 * 1000;
      const ACTIVE_STALE_MS = 30 * 60 * 1000;
      for (const { sessionId, filePath, data } of await readAgentStatusFiles()) {
        try {
          if (!data?.ts) continue;
          const ageMs = now - data.ts * 1000;
          // Cheap time gate first, so we only pay for a process lookup on
          // sessions that are actually stale by time.
          const threshold = (data.status === "idle" || data.status === "stopped") ? IDLE_STALE_MS : ACTIVE_STALE_MS;
          if (ageMs < threshold) continue;
          const convId = deps.conversationCache[sessionId];
          if (!convId) { await fs.promises.unlink(filePath).catch(() => {}); continue; }
          // Stale by time — but is the agent actually gone, or just idling for
          // the user? Only reap when no live process remains (see predicate).
          const liveProcess = await findSessionProcess(sessionId, detectSessionAgentType(sessionId)).catch(() => null);
          if (!shouldMarkSessionCompleted({ status: data.status, ageMs, hasLiveAgentProcess: !!liveProcess, idleStaleMs: IDLE_STALE_MS, activeStaleMs: ACTIVE_STALE_MS })) continue;
          log(`Watchdog: stale ${data.status} session ${sessionId.slice(0, 8)} (${Math.round(ageMs / 60000)}min, no live process), marking completed`);
          deps.syncService.markSessionCompleted(convId).catch(logConvexFailure);
          sendAgentStatus(deps.syncService, convId, sessionId, "stopped");
          await fs.promises.unlink(filePath).catch(() => {});
        } catch {}
      }
    } catch {}

    // Tier 3 warm pool (opt-in): after stale files are reaped above, re-warm the most
    // recently-active sessions whose agent has died so a follow-up skips the cold boot.
    try { await prewarmRecentlyActiveSessions(deps); } catch (err) {
      log(`Warm pool tick error: ${err instanceof Error ? err.message : String(err)}`);
    }

    // Check for watcher staleness -- only restart if idle for 60+ min.
    // Short idle periods are normal (no active sessions, nighttime, etc.)
    const watcherIdleMinutes = Math.floor((now - lastWatcherEventTime) / 60000);
    if (watcherIdleMinutes >= 60) {
      log(`Watcher idle for ${watcherIdleMinutes}min, restarting`);
      // Guard with a timeout. The synchronous form of this call previously
      // deadlocked the event loop indefinitely against bun's File Watcher
      // thread on an os_unfair_lock (see recursiveWatcher.restart()).
      // Promise.race lets the watchdog tick recover even if the deadlock recurs.
      try {
        await Promise.race([
          deps.watcher.restart(),
          new Promise((_, reject) =>
            setTimeout(() => reject(new Error("watcher restart timeout after 10s")), 10_000),
          ),
        ]);
        lastWatcherEventTime = now;
        log(`Watcher restarted successfully`);
      } catch (err) {
        logError("Failed to restart watcher", err instanceof Error ? err : new Error(String(err)));
      }
    }

    const WATCHDOG_CONCURRENCY = 20;
    const WATCHDOG_MAX_STALE_PER_TYPE = 200;

    const staleClaudeFiles = (await findStaleSessionFiles()).slice(0, WATCHDOG_MAX_STALE_PER_TYPE);
    const staleCodexFiles = (await findStaleCodexSessionFiles()).slice(0, WATCHDOG_MAX_STALE_PER_TYPE);
    const staleCursorSessions = (await findStaleCursorSessions()).slice(0, WATCHDOG_MAX_STALE_PER_TYPE);
    const staleCursorTranscriptFiles = (await findStaleCursorTranscriptFiles()).slice(0, WATCHDOG_MAX_STALE_PER_TYPE);
    const totalStale =
      staleClaudeFiles.length +
      staleCodexFiles.length +
      staleCursorSessions.length +
      staleCursorTranscriptFiles.length;

    if (totalStale === 0) {
      return;
    }

    log(`Watchdog: Detected ${totalStale} files needing sync (concurrent=${WATCHDOG_CONCURRENCY}, cap=${WATCHDOG_MAX_STALE_PER_TYPE})`);

    const currentRestarts = state?.watchdogRestarts || 0;
    saveDaemonState({ watchdogRestarts: currentRestarts + 1 });

    await runBounded(staleClaudeFiles, WATCHDOG_CONCURRENCY, async (filePath) => {
      const parts = filePath.split(path.sep);
      const sessionId = resolveSessionId(filePath);
      const projectDirName = parts[parts.length - 2];
      const projectPath = resolveTranscriptProjectPath(filePath, projectDirName);

      if (deps.config.excluded_paths && isPathExcluded(projectPath, deps.config.excluded_paths)) {
        return;
      }

      if (!isProjectAllowedToSync(projectPath, deps.config)) {
        return;
      }

      log(`Watchdog: Syncing stale session ${sessionId}`);

      await processSessionFile(
        filePath,
        sessionId,
        projectPath,
        deps.syncService,
        deps.config.user_id!,
        deps.config.team_id,
        deps.conversationCache,
        deps.retryQueue,
        deps.pendingMessages,
        deps.titleCache,
        deps.updateState
      );
    }, "Watchdog worker");

    await runBounded(staleCodexFiles, WATCHDOG_CONCURRENCY, async (filePath) => {
      const filename = path.basename(filePath, ".jsonl");
      const match = filename.match(
        /([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i
      );
      const sessionId = match ? match[1] : filename;

      log(`Watchdog: Syncing stale Codex session ${sessionId}`);

      await processCodexSession(
        filePath,
        sessionId,
        deps.syncService,
        deps.config.user_id!,
        deps.config.team_id,
        deps.conversationCache,
        deps.retryQueue,
        deps.pendingMessages,
        deps.titleCache,
        deps.updateState
      );
    }, "Watchdog worker");

    await runBounded(staleCursorSessions, WATCHDOG_CONCURRENCY, async (cursorSession) => {
      if (deps.config.excluded_paths && isPathExcluded(cursorSession.workspacePath, deps.config.excluded_paths)) {
        return;
      }

      if (!isProjectAllowedToSync(cursorSession.workspacePath, deps.config)) {
        return;
      }

      log(`Watchdog: Syncing stale Cursor session ${cursorSession.sessionId}`);

      await processCursorSession(
        cursorSession.dbPath,
        cursorSession.sessionId,
        cursorSession.workspacePath,
        deps.syncService,
        deps.config.user_id!,
        deps.config.team_id,
        deps.conversationCache,
        deps.retryQueue,
        deps.pendingMessages,
        deps.updateState
      );
    }, "Watchdog worker");

    await runBounded(staleCursorTranscriptFiles, WATCHDOG_CONCURRENCY, async (filePath) => {
      const sessionId = path.basename(filePath, ".txt");
      const workspacePath = findWorkspacePathForCursorConversation(sessionId);

      if (workspacePath) {
        if (deps.config.excluded_paths && isPathExcluded(workspacePath, deps.config.excluded_paths)) {
          return;
        }

        if (!isProjectAllowedToSync(workspacePath, deps.config)) {
          return;
        }
      } else if (deps.config.sync_mode === "selected") {
        return;
      }

      log(`Watchdog: Syncing stale Cursor transcript ${sessionId}`);

      await processCursorTranscriptFile(
        filePath,
        sessionId,
        deps.syncService,
        deps.config.user_id!,
        deps.config.team_id,
        deps.conversationCache,
        deps.retryQueue,
        deps.pendingMessages,
        deps.updateState
      );
    }, "Watchdog worker");

    log(`Watchdog: Sync completed for ${totalStale} files`);
    } catch (err) {
      const errMsg = err instanceof Error ? err.message : String(err);
      const stack = err instanceof Error && err.stack ? `\n${err.stack}` : "";
      log(`Watchdog cycle aborted: ${errMsg}${stack}`);
    } finally { watchdogRunning = false; }
  }, WATCHDOG_INTERVAL_MS);
}

async function main(): Promise<void> {
  // Refuse before any state, lock, or exit-handler setup: on Windows the daemon
  // spawned a visible console window per background child (git, codex, cast) —
  // hundreds within minutes. Exit 0 so Task Scheduler does not retry.
  if (!daemonSupportedOnPlatform()) {
    console.error(WINDOWS_DAEMON_UNSUPPORTED_MESSAGE);
    process.exit(0);
  }

  ensureConfigDir();
  ensureCastAlias();

  if (!acquireLock()) {
    const existingPid = fs.readFileSync(PID_FILE, "utf-8").trim();
    console.error(`Daemon already running (PID: ${existingPid}). Exiting.`);
    process.exit(0);
  }

  // Refresh the session-start hooks on boot when stable mode is enabled: the
  // scripts and the opencode plugin ship with the CLI (they delegate to
  // `codecast stable-context`), so installed copies from an older CLI must be
  // rewritten without waiting for the user to re-run `cast stable`. Also
  // covers a client installed after `cast stable` ran. Idempotent.
  try {
    if (readConfig()?.stable_mode) {
      const { installAllStableHooks } = await import("./stableContext.js");
      installAllStableHooks();
    }
  } catch {}

  // The tmux server may have been started from inside a Claude Code session
  // and be seeding every new pane with that session's markers (see
  // AGENT_SCRUBBED_ENV_VARS). Clear them once per boot.
  scrubTmuxGlobalEnv();

  // Settings-level backstop for the same class: pin transcript persistence ON
  // in ~/.claude/settings.json so even a claude codecast didn't launch keeps
  // its transcript when a leaked CLAUDE_CODE_CHILD_SESSION reaches it
  // (agentEnv.ts). Re-asserted hourly (scheduled beside the heartbeat): a
  // dotfiles sync or another tool rewriting settings.json would otherwise
  // drop the pin until the next daemon restart.
  assertClaudePersistencePin();

  // Exit guard: respawn with backoff if crash looping.
  // Skip self-respawn when running under launchd (KeepAlive handles restarts).
  const underLaunchd = isManagedByLaunchd();
  process.on("exit", (code) => {
    // Reap the opencode serve sidecar on EVERY exit path (crash, self-update respawn,
    // fatal, hard-exit timer) — it isn't spawned detached, but process.exit doesn't
    // kill it either, so without this a dying daemon orphans a live unauthenticated
    // serve. stop() sends SIGTERM synchronously here and is idempotent.
    try { opencodeServerInstance?.stop(); } catch {}
    flushLogBuffer();
    persistLogQueue();
    if (skipRespawn || underLaunchd) return;
    if (code !== 0) {
      const { count, backoffMinutes } = recordCrash();
      if (backoffMinutes > 0) {
        try { fs.appendFileSync(LOG_FILE, `[${new Date().toISOString()}] CRASH LOOP: ${count} crashes, backing off ${backoffMinutes}min before respawn\n`); } catch {}
        try {
          spawn("sh", ["-c", `sleep ${backoffMinutes * 60} && "${process.execPath}" ${process.argv.slice(1).map(a => `"${a}"`).join(" ")}`], {
            detached: true,
            stdio: "ignore",
            env: replacementEnv(),
          }).unref();
        } catch {}
        return;
      }
    } else {
      clearCrashCount();
    }
    try {
      spawn(process.execPath, process.argv.slice(1), {
        detached: true,
        stdio: "ignore",
        env: replacementEnv(),
      }).unref();
    } catch {}
  });

  process.on("uncaughtException", async (err) => {
    // Kill the unauthenticated serve sidecar immediately — don't leave it live during
    // the async log-flush below or after the exit. (The "exit" handler is the
    // catch-all; this shrinks the crash-time exposure window.)
    try { opencodeServerInstance?.stop(); } catch {}
    logError("Uncaught exception", err);
    persistLogQueue();
    sendLogImmediate("error", `UNCAUGHT EXCEPTION: ${err.message}`, {
      error_code: err.name,
      stack: err.stack?.slice(0, 1000),
    });
    await flushRemoteLogs().catch(() => {});
    process.exit(1);
  });

  process.on("unhandledRejection", async (reason) => {
    const err = reason instanceof Error ? reason : new Error(String(reason));
    logError("Unhandled rejection", err);
    await flushRemoteLogs().catch(() => {});
  });

  try {
    daemonVersion = getVersion();
  } catch {
    daemonVersion = "unknown";
  }

  // A version change since the last boot means a self-update restarted us —
  // the interactive `cast update` paths (which refresh snippets) never ran, so
  // shell out to `snippets-refresh` to bring every enabled snippet's text to
  // this binary's versions. Detected BEFORE the version file is overwritten.
  let bootedNewVersion = false;
  try {
    const priorVersion = fs.existsSync(VERSION_FILE) ? fs.readFileSync(VERSION_FILE, "utf-8").trim() : "";
    bootedNewVersion = !!priorVersion && priorVersion !== daemonVersion;
  } catch {}

  try {
    fs.writeFileSync(VERSION_FILE, daemonVersion, { mode: 0o600 });
  } catch {}

  activeConfig = readConfig();
  loadPersistedLogQueue();

  if (bootedNewVersion) {
    log(`[SNIPPET] version changed to v${daemonVersion} — refreshing enabled snippets`);
    runCastCommand(["snippets-refresh"], { timeoutMs: 60 * 1000 }).catch((e) =>
      logError("snippets-refresh after update failed", e instanceof Error ? e : new Error(String(e)))
    );
  }

  // Messaging is on by default for memory installs. Backfill/refresh it here so
  // every daemon distributes the snippet onto its own machine's CLAUDE.md on
  // startup (including after a self-update restart) — no interactive `cast` needed.
  try {
    const msgPatch = ensureMessagingForMemory(activeConfig);
    if (msgPatch) {
      patchConfig(msgPatch);
      Object.assign(activeConfig as object, msgPatch);
      log("Ensured messaging snippet for memory install");
    }
  } catch (e) {
    logError("ensureMessagingForMemory failed", e instanceof Error ? e : new Error(String(e)));
  }

  // Report crash recovery if we had crashes before this successful startup
  let crashRecoveryInfo = "";
  if (fs.existsSync(CRASH_FILE)) {
    try {
      const crashes = JSON.parse(fs.readFileSync(CRASH_FILE, "utf-8"));
      if (crashes.count > 0) {
        crashRecoveryInfo = ` (recovered from ${crashes.count} crashes)`;
      }
    } catch {}
  }
  clearCrashCount();

  const isRestart = process.env.CODECAST_RESTART === "1";
  const startMsg = `v${daemonVersion} PID=${process.pid}${isRestart ? " (restart after update)" : ""}${crashRecoveryInfo}`;
  logLifecycle("daemon_start", startMsg);
  void refreshSessionFileIndex(); // warm the transcript index off the loop before the first lookup
  sendLogImmediate("info", `[LIFECYCLE] daemon_start: ${startMsg}`, { error_code: "daemon_start" });
  log(`PID: ${process.pid}`);

  try {
    if (getMachineKey().rotated) {
      const msg = `machine key rotated: ~/.codecast/.machine_key was cloned from different hardware (Migration Assistant / disk clone) — this machine now has device_id ${deviceId()}`;
      logLifecycle("machine_key_rotated", msg);
      sendLogImmediate("info", `[LIFECYCLE] machine_key_rotated: ${msg}`, { error_code: "machine_key_rotated" });
    }
  } catch {}

  if (isSyncPaused()) {
    log("⚠️  Sync is PAUSED via environment variable (CODE_CHAT_SYNC_PAUSED or CODECAST_PAUSED)");
  }

  saveDaemonState({ connected: false, runtimeVersion: getVersion(), lastHeartbeatTick: Date.now() });

  // Guarantee our supervisor exists. If an upgrade/login race left the watchdog
  // booted out, restore it now so the daemon is never left without a backstop.
  void ensureWatchdogSupervised(true);

  // Start heartbeat immediately so the daemon doesn't appear "blocked" during slow init
  const eventLoopMonitorInterval = startEventLoopMonitor();

  const { config, convexUrl } = await waitForConfig();
  activeConfig = config;

  log(`User ID: ${config.user_id}`);
  log(`Convex URL: ${convexUrl}`);
  if (config.auth_token) {
    log(`Auth token: ${maskToken(config.auth_token)}`);
  }
  if (config.excluded_paths) {
    log(`Excluded paths: ${config.excluded_paths}`);
  }

  const syncService = new SyncService({
    convexUrl,
    authToken: config.auth_token,
    userId: config.user_id,
  });
  syncServiceRef = syncService;
  resumeStartedSessionDiscovery();

  // Register this device EARLY + on its own interval, so device presence never
  // depends on the rest of (potentially slow/headless-stalling) init. Logs the
  // first result for diagnosability.
  // Register this device early + on its own interval, so device presence never
  // depends on later (potentially slow) init steps.
  void sendHeartbeat().catch(() => {});
  setInterval(() => { sendHeartbeat().catch(() => {}); }, 30_000);

  // Hourly re-assert of the settings-level transcript pin (asserted once at
  // boot already) — converges a settings.json rewritten out from under us.
  setInterval(assertClaudePersistencePin, 3_600_000);

  // Check for forced updates immediately on startup before anything else
  // This allows recovery from broken versions by downloading a fix early
  try {
    const didUpdate = await checkForForcedUpdate(syncService);
    if (didUpdate) return; // process.exit already called inside
  } catch (err) {
    log(`Startup update check failed: ${err instanceof Error ? err.message : String(err)}`);
  }

  // Repair any project paths that were stored incorrectly (one-time on startup)
  repairProjectPaths(syncService).catch(err => {
    log(`Failed to repair project paths: ${err instanceof Error ? err.message : String(err)}`);
  });

  // Backfill plan_mode plans from JSONL files that the daemon missed (e.g., sessions completed before daemon started)
  backfillPlanModeFromJSONL(syncService).catch(err => {
    log(`Failed to backfill plan_mode from JSONL: ${err instanceof Error ? err.message : String(err)}`);
  });

  setInterval(() => {
    flushRemoteLogs().catch(() => {});
  }, LOG_FLUSH_INTERVAL_MS);

  setInterval(() => {
    logHealthSummary().catch(() => {});
    sendHeartbeat().catch(() => {});
    checkDiskVersionMismatch();
    ensureWatchdogSupervised().catch(() => {});
  }, HEALTH_REPORT_INTERVAL_MS);

  setInterval(() => {
    pollDaemonCommands().catch(() => {});
  }, 10_000);

  // Keep the remote Mac's copied credential fresh (it can't /login itself).
  setTimeout(() => { pushCredentialToRemoteHosts("daemon start").catch(() => {}); }, 60_000);
  setInterval(() => { pushCredentialToRemoteHosts("periodic").catch(() => {}); }, REMOTE_CRED_REFRESH_INTERVAL_MS);
  // Fast tick: propagate any local credential change (a /login, an account
  // switch, CC's own self-refresh) within ~a minute. Hash-gated, so the
  // common no-change tick costs one keychain read and no ssh.
  setInterval(() => { pushCredentialToRemoteHosts("credential_changed", { onlyIfChanged: true }).catch(() => {}); }, REMOTE_CRED_CHANGE_TICK_MS);

  // Fan the provider-key store out to remotes on the same cadence (pl-207): once at
  // start (backfill a new remote), and a hash-gated fast tick that propagates a
  // `cast keys` change within ~a minute. A watch on the store file (below) makes the
  // common case near-instant; this tick is the backfill/safety net.
  setTimeout(() => { pushProviderKeysToRemoteHosts("daemon start").catch(() => {}); }, 62_000);
  setInterval(() => { pushProviderKeysToRemoteHosts("periodic", { onlyIfChanged: true }).catch(() => {}); }, REMOTE_CRED_CHANGE_TICK_MS);
  // Near-instant sync: when the local store file changes (a `cast keys set/rm`, or a
  // web edit the daemon applied), push immediately. fs.watch can double-fire, so the
  // in-flight lock + hash gate keep it to one real push.
  try {
    fs.mkdirSync(CONFIG_DIR, { recursive: true });
    fs.watch(CONFIG_DIR, (_event, filename) => {
      if (filename === "provider-keys.json") {
        pushProviderKeysToRemoteHosts("store changed", { onlyIfChanged: true }).catch(() => {});
      }
    });
  } catch (err) {
    log(`[REMOTE-KEYS] could not watch the provider-key store: ${err instanceof Error ? err.message : String(err)}`);
  }

  // Keep THIS machine's login from lapsing during idle gaps + propagate a
  // manual /login into its saved profile (primary devices only).
  setTimeout(() => { maintainActiveCcToken("daemon start").catch(() => {}); }, 45_000);
  setInterval(() => { maintainActiveCcToken("periodic").catch(() => {}); }, CC_TOKEN_MAINT_INTERVAL_MS);

  // Per-account usage snapshots for the web's meters + auto-switch decisions.
  setTimeout(() => { maintainCcUsageSnapshots("daemon start").catch(() => {}); }, 75_000);
  setInterval(() => { maintainCcUsageSnapshots("periodic").catch(() => {}); }, CC_USAGE_REFRESH_INTERVAL_MS);
  setTimeout(() => { maintainCodexUsageSnapshot("daemon start").catch(() => {}); }, 75_000);
  setInterval(() => { maintainCodexUsageSnapshot("periodic").catch(() => {}); }, CC_USAGE_REFRESH_INTERVAL_MS);

  // Auto-dispatch: detect active plans with bound workflows that haven't started
  const notifiedPlanWorkflows = new Set<string>();
  async function checkPlanAutoDispatch() {
    if (!config.auth_token) return;
    const siteUrl = (config.convex_url || "").replace(".cloud", ".site");
    try {
      const resp = await fetch(`${siteUrl}/cli/plans/list`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ api_token: config.auth_token, status: "active" }),
      });
      const data = await resp.json() as any;
      const plans = Array.isArray(data) ? data : (data?.plans || []);
      for (const plan of plans) {
        if (plan.workflow_id && !plan.workflow_run_id && !notifiedPlanWorkflows.has(plan.short_id)) {
          notifiedPlanWorkflows.add(plan.short_id);
          log(`[AUTO-DISPATCH] Plan ${plan.short_id} has workflow ready — start from web UI or: cast workflow run --plan ${plan.short_id}`);
        }
      }
    } catch {}
  }

  setInterval(() => {
    checkPlanAutoDispatch().catch(() => {});
  }, 60_000);

  setInterval(() => {
    collectResourceSnapshot().catch(() => {});
  }, RESOURCE_MONITOR_INTERVAL_MS);

  // Re-establish session→pid liveness mapping (esp. for idle sessions that don't
  // write JSONL) so the Sessions page can tell live-idle from dead. Run once
  // shortly after boot so the page recovers fast post-restart, then on a timer.
  setTimeout(() => { reconcileSessionLiveness().catch(() => {}); }, 10_000);
  setInterval(() => {
    reconcileSessionLiveness().catch(() => {});
  }, LIVENESS_RECONCILE_INTERVAL_MS);

  // Send initial heartbeat
  sendHeartbeat().catch(() => {});

  // Start task scheduler
  const taskScheduler = new TaskScheduler({
    syncService,
    config,
    log,
  });
  taskScheduler.start();

  const conversationCache = readConversationCache();
  conversationCacheRef = conversationCache;
  const titleCache = readTitleCache();
  const pendingMessages: PendingMessages = {};
  const activeSessions = new Map<string, ActiveSession>();

  // Warm restart: rebuild in-memory caches from surviving tmux sessions.
  // After daemon restart, in-memory caches are lost but tmux sessions survive.
  // We handle three shapes:
  //   1. Resume tmuxes tagged with @codecast_session_id → restore resumeSessionCache.
  //   2. Fresh tmuxes tagged with @codecast_conversation_id → restore startedSessionTmux.
  //   3. Untagged legacy tmuxes → register anyway so user sees them in the sessions UI.
  // Every recovered tmux is registered with managed_sessions so the UI lists it.
  if (hasTmux()) {
    try {
      const sessions = tmuxExecSync(["list-sessions", "-F", "#{session_name}"], { timeout: 5000 }).trim().split("\n").filter(Boolean);
      const ccSessions = sessions.filter(isManagedTmuxName);
      let recovered = 0;
      // Bounded-parallel, not sequential: each session costs a process-tree
      // aliveness probe plus four tmux option reads, and a fleet of ~100 managed
      // tmuxes walked one at a time held the rest of boot (watcher, watchdog,
      // delivery subscriptions) for 3-4 minutes on 2026-08-20 — every daemon
      // restart was a multi-minute delivery blackout. `continue` became `return`.
      const recoveredAt = Date.now();
      await runBounded(ccSessions, 8, async (tmuxSession) => {
        try {
          const alive = await isTmuxAgentAlive(tmuxSession);
          if (!alive) return;

          const [sessionId, tmuxConvId, tmuxAgentType, tmuxProjectPath] = await Promise.all([
            getTmuxSessionOption(tmuxSession, "@codecast_session_id"),
            getTmuxSessionOption(tmuxSession, "@codecast_conversation_id"),
            getTmuxSessionOption(tmuxSession, "@codecast_agent_type"),
            getTmuxSessionOption(tmuxSession, "@codecast_project_path"),
          ]);

          if (sessionId) {
            resumeSessionCache.set(sessionId, tmuxSession);
            const convId = tmuxConvId || conversationCache[sessionId];
            if (syncServiceRef) {
              syncServiceRef.registerManagedSession(sessionId, process.pid, tmuxSession, (convId || undefined) as any).catch(logConvexFailure);
              ensureManagedSessionHeartbeat(sessionId);
            }
            recovered++;
            return;
          }

          if (tmuxConvId) {
            const agentType = (tmuxAgentType as StartedSessionInfo["agentType"] | null) || "claude";
            const cachedSessionId = findCachedSessionIdForConversation(conversationCache, tmuxConvId);
            if (cachedSessionId) {
              resumeSessionCache.set(cachedSessionId, tmuxSession);
              if (syncServiceRef) {
                registerManagedStartedSession(tmuxConvId, cachedSessionId, tmuxSession);
                if (agentType === "codex") {
                  startCodexPermissionPoller(cachedSessionId, tmuxSession, tmuxConvId, syncServiceRef);
                }
              }
              recovered++;
              return;
            }
            startedSessionTmux.set(tmuxConvId, {
              tmuxSession,
              projectPath: tmuxProjectPath || process.env.HOME || "/tmp",
              startedAt: Date.now(),
              agentType,
            });
            if (syncServiceRef) {
              syncServiceRef.registerManagedSession(tmuxSession, process.pid, tmuxSession, tmuxConvId as any).catch(logConvexFailure);
              ensureManagedSessionHeartbeat(tmuxSession);
            }
            recovered++;
            return;
          }

          if (syncServiceRef) {
            syncServiceRef.registerManagedSession(tmuxSession, process.pid, tmuxSession).catch(logConvexFailure);
            ensureManagedSessionHeartbeat(tmuxSession);
            recovered++;
          }
        } catch {}
      });
      if (recovered > 0) {
        log(`[WARM-RESTART] Recovered ${recovered} live session(s) from tmux in ${Date.now() - recoveredAt}ms`);
        // Scan recovered sessions for undetected interactive prompts
        setTimeout(() => {
          const cache = readConversationCache();
          for (const [sid, tmux] of resumeSessionCache) {
            const convId = cache[sid];
            if (convId && !pendingInteractivePrompts.has(sid) && syncServiceRef) {
              checkForInteractivePrompt(tmux + ":0.0", sid, convId, syncServiceRef, 0).catch(() => {});
            }
          }
        }, 10_000);
      }
    } catch (err) {
      log(`[WARM-RESTART] tmux scan failed: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // Sync skills to user profile on startup (global + per-project)
  {
    const globalSkills = readAvailableSkills();
    if (globalSkills.length > 0) {
      const skillsJson = JSON.stringify(globalSkills);
      log(`Startup: syncing ${globalSkills.length} global skills to user profile`);
      syncService.setAvailableSkills(undefined as any, skillsJson).then(() => {
        log(`Startup: user-level skills synced`);
      }).catch(err => log(`Startup skills sync error: ${err}`));
    }
    const globalNames = new Set(globalSkills.map(s => s.name));
    const projectsDir = path.join(process.env.HOME || "", ".claude", "projects");
    const decodeProjectPath = (dirName: string): string | null => {
      const segments = dirName.replace(/^-/, "").split("-");
      let resolved = "";
      let i = 0;
      while (i < segments.length) {
        let candidate = segments[i];
        i++;
        while (true) {
          const testPath = resolved + "/" + candidate;
          if (i >= segments.length) { resolved = testPath; break; }
          try {
            if (fs.statSync(testPath).isDirectory()) { resolved = testPath; break; }
          } catch {}
          candidate += "-" + segments[i];
          i++;
        }
      }
      return fs.existsSync(resolved) ? resolved : null;
    };
    try {
      const entries = fs.readdirSync(projectsDir);
      for (const entry of entries) {
        const projectPath = decodeProjectPath(entry);
        if (!projectPath) continue;
        const hasCommands = fs.existsSync(path.join(projectPath, ".claude", "commands"));
        const hasSkills = fs.existsSync(path.join(projectPath, ".claude", "skills"));
        if (!hasCommands && !hasSkills) continue;
        const allSkills = readAvailableSkills(projectPath);
        const projectOnly = allSkills.filter(s => !globalNames.has(s.name));
        if (projectOnly.length > 0) {
          log(`Startup: syncing ${projectOnly.length} project skills for ${path.basename(projectPath)}`);
          syncService.setAvailableSkills(undefined as any, JSON.stringify(projectOnly), projectPath).catch(logConvexFailure);
        }
      }
    } catch {}
  }

  const retryQueue = new RetryQueue({
    initialDelayMs: 3000,
    maxDelayMs: 60000,
    maxAttempts: 15,
    concurrency: 12,
    persistPath: `${CONFIG_DIR}/retry-queue.json`,
    droppedPath: `${CONFIG_DIR}/dropped-operations.json`,
    onLog: (message, level) => log(message, level || "info"),
    // Refresh the persisted health snapshot as the queue accumulates, so `cast
    // status` reflects backlog while it piles up — not only after the first
    // drain. updateState is declared just below; onEnqueue only fires from
    // add(), which runs well after setup, so the forward reference is safe.
    onEnqueue: () => updateState(),
  });

  retryQueueRef = retryQueue;

  const updateState = () => {
    const health = retryQueue.getHealth();
    saveDaemonState({
      lastSyncTime: Date.now(),
      pendingQueueSize: health.pending,
      // Honest backlog summary for `cast status` so "synced" stops lying while
      // messages sit in the retry queue. One cheap pass over the queued ops.
      pendingSyncMessages: health.messages,
      pendingSyncConversations: health.conversations,
      pendingSyncOldestMs: health.oldestPendingMs,
    });
  };

  retryQueue.setExecutor(async (op: RetryOperation): Promise<boolean> => {
    if (op.type === "createConversation") {
      // Ops carry the exact params the direct create attempted (including
      // parentConversationId/isSubagent — dropping them minted flat,
      // unparented subagent conversations, jx70pyh 2026-07-29).
      const params = op.params as unknown as CreateConversationParams;
      const conversationId = await syncService.createConversation(params);
      conversationCache[params.sessionId] = conversationId;
      saveConversationCache(conversationCache);
      log(`Retry: Created conversation ${conversationId} for session ${params.sessionId}`);

      // Mirror the direct path's pending-subagent resolution so a child whose
      // queued op predates full params (older daemon's persisted queue) still
      // re-parents via linkSessions.
      for (const link of resolvePendingSubagentLinks(params.sessionId, conversationId, pendingSubagentParents, conversationCache)) {
        syncService.linkSessions(link.parentConvId, link.childConvId, subagentDescriptions.get(link.childSessionId)).then(() => {
          log(`Retry: Linked pending subagent ${link.childSessionId.slice(0, 8)} -> parent ${link.parentSessionId.slice(0, 8)}`);
        }).catch((linkErr) => {
          log(`Retry: Failed to link subagent ${link.childSessionId.slice(0, 8)}: ${linkErr}`);
        });
        pendingSubagentParents.delete(link.childSessionId);
      }

      if (pendingMessages[params.sessionId]) {
        await flushPendingMessagesBatch(pendingMessages[params.sessionId], conversationId, syncService, retryQueue);
        delete pendingMessages[params.sessionId];
      }
      updateState();
      return true;
    }

    if (op.type === "updateSessionId") {
      const params = op.params as { conversationId: string; sessionId: string; projectPath?: string; gitRoot?: string };
      // Superseded while queued: the session resumed under a fresh uuid (or the
      // local mapping was pruned). Executing anyway would clobber the newer
      // binding, so discard — the newer link enqueued its own op.
      const preferred = findCachedSessionIdForConversation(conversationCache, params.conversationId);
      if (preferred !== params.sessionId) {
        log(`Retry: updateSessionId superseded for ${params.conversationId.slice(0, 12)} (queued ${params.sessionId.slice(0, 8)}, live ${preferred ? preferred.slice(0, 8) : "none"})`);
        updateState();
        return true;
      }
      await syncService.updateSessionId(params.conversationId, params.sessionId, params.projectPath, params.gitRoot);
      log(`Retry: Rebound session ${params.sessionId.slice(0, 8)} -> conversation ${params.conversationId.slice(0, 12)}`);
      updateState();
      return true;
    }

    if (op.type === "addMessages") {
      const params = op.params as {
        conversationId: string;
        messages: Array<{
          messageUuid?: string;
          role: "human" | "assistant" | "system";
          content: string;
          timestamp: number;
          thinking?: string;
          toolCalls?: any;
          toolResults?: any;
          images?: any;
          subtype?: string;
        }>;
      };
      // Offload any still-inline images to file storage before re-sending, then
      // persist so the queue stops carrying raw base64 across attempts. Images
      // are normally offloaded at enqueue (syncMessagesBatch), but when the
      // upload mutation is failing (e.g. a backend write-path stall) the base64
      // is kept inline and persisted. The first retry after recovery replaces it
      // with a storageId reference once, instead of re-uploading the same bytes
      // (and re-bloating retry-queue.json / dropped-operations.json) every time.
      const hasInlineImage = params.messages.some(
        (m) => Array.isArray(m.images) && m.images.some((i: any) => i?.data && !i?.storageId),
      );
      if (hasInlineImage) {
        await syncService.offloadImages(params.messages as any);
        retryQueue.persistNow();
      }
      await syncService.addMessages({ ...params, reconcileRemoteExisting: true });
      updateState();
      log(`Retry: Batch synced ${params.messages.length} messages for ${params.conversationId.slice(0, 12)}`);
      return true;
    }

    if (op.type === "addMessage") {
      const params = op.params as {
        conversationId: string;
        messageUuid?: string;
        role: "human" | "assistant" | "system";
        content: string;
        timestamp: number;
        thinking?: string;
        toolCalls?: Array<{ id: string; name: string; input: Record<string, unknown> }>;
        toolResults?: Array<{ toolUseId: string; content: string; isError?: boolean }>;
        images?: Array<{ mediaType: string; data?: string; localPath?: string; storageId?: string }>;
        subtype?: string;
      };
      await syncService.addMessage(params);
      updateState();
      return true;
    }

    return false;
  });

  retryQueue.start();

  // Ingest a dynamic-workflow run from its on-disk snapshot (<session>/workflows/wf_<id>.json).
  // The snapshot is a complete materialized run model, so we map it straight into workflow_runs
  // via the same /cli HTTP channel the routine/graph runner uses — no transcript parsing.
  async function processWorkflowSnapshot(
    filePath: string,
    sessionId: string,
    runId: string,
    projectPath: string
  ): Promise<void> {
    try {
      const raw = fs.readFileSync(filePath, "utf8");
      if (!raw.trim()) return;
      const snap = JSON.parse(raw) as {
        workflowName?: string;
        status?: string;
        phases?: Array<{ title: string; detail?: string }>;
        workflowProgress?: Array<{
          type: string; agentId?: string; label?: string; phaseTitle?: string;
          state?: string; tokens?: number; durationMs?: number; startedAt?: number; resultPreview?: string;
          lastToolName?: string; lastToolSummary?: string;
        }>;
        totalTokens?: number; agentCount?: number; startTime?: number;
      };
      const agents = (snap.workflowProgress || [])
        .filter((e) => e.type === "workflow_agent" && e.agentId)
        .map((e) => ({
          agent_id: e.agentId!,
          label: e.label,
          phase: e.phaseTitle,
          state: e.state || "pending",
          tokens: e.tokens,
          duration_ms: e.durationMs,
          started_at: e.startedAt,
          result_preview: e.resultPreview,
          last_tool_name: e.lastToolName,
          last_tool_summary: e.lastToolSummary,
        }));
      await postWorkflowRunIngest({
        external_run_id: runId,
        session_id: sessionId,
        project_path: projectPath,
        workflow_name: snap.workflowName || "workflow",
        status: snap.status || "running",
        phases: snap.phases || [],
        agents,
        total_tokens: snap.totalTokens,
        agent_count: snap.agentCount ?? agents.length,
        started_at: snap.startTime,
      });
    } catch (err) {
      logError(`processWorkflowSnapshot failed for ${runId}`, err as Error);
    }
  }

  // Shared /cli ingest channel for both snapshot shapes (completion file and
  // the journal-derived live model below).
  async function postWorkflowRunIngest(payload: {
    external_run_id: string;
    session_id: string;
    project_path?: string;
    workflow_name: string;
    status: string;
    phases: Array<{ title: string; detail?: string }>;
    agents: Array<Record<string, unknown>>;
    total_tokens?: number;
    agent_count?: number;
    started_at?: number;
  }): Promise<void> {
    const siteUrl = (config.convex_url || "").replace(".cloud", ".site");
    const token = config.auth_token;
    if (!siteUrl || !token) return;
    const resp = await fetch(`${siteUrl}/cli/workflow-runs/ingest`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ api_token: token, ...payload }),
    });
    const respText = await resp.text().catch(() => "");
    const ok = resp.ok && !respText.includes('"error"');
    log(`Workflow snapshot ${ok ? "synced" : `FAILED(${resp.status}) ${respText.slice(0, 120)}`}: ${payload.external_run_id} (${payload.agents.length} agents, ${payload.status})`);
  }

  // A dynamic-workflow run writes its materialized snapshot (workflows/wf_<id>.json)
  // only when it COMPLETES. While it runs, the only on-disk record is under
  // subagents/workflows/<runId>/ — the agent transcripts plus a journal of
  // started/result entries per agentId. Without a mid-run ingest the run row is
  // born already-completed, so no surface can ever say a workflow is RUNNING —
  // the "session looks idle while 19 agents work" hole (jx70xxy, ct-43094).
  // Derive a running model from the journal whenever an agent transcript under
  // the run dir changes, debounced per run; the completion snapshot later
  // overwrites it with the full model (tokens, previews, phases).
  const liveWorkflowIngestAt = new Map<string, number>();
  const LIVE_WORKFLOW_INGEST_INTERVAL_MS = 30_000;

  function liveWorkflowRunFromPath(filePath: string): { runDir: string; runId: string; hostSessionId: string } | undefined {
    const parts = filePath.split(path.sep);
    // .../<hostSession>/subagents/workflows/<wf_runId>/agent-<id>.jsonl
    if (parts.length < 5) return undefined;
    const [hostSessionId, subagents, workflows, runId, file] = parts.slice(-5);
    if (subagents !== "subagents" || workflows !== "workflows" || !runId.startsWith("wf_")) return undefined;
    if (!file.startsWith("agent-") || !file.endsWith(".jsonl")) return undefined;
    return { runDir: path.dirname(filePath), runId, hostSessionId };
  }

  async function ingestLiveWorkflowRun(runDir: string, runId: string, hostSessionId: string, projectPath: string): Promise<void> {
    const now = Date.now();
    if (now - (liveWorkflowIngestAt.get(runId) ?? 0) < LIVE_WORKFLOW_INGEST_INTERVAL_MS) return;
    liveWorkflowIngestAt.set(runId, now);
    try {
      const hostDir = path.resolve(runDir, "..", "..", "..");
      // Once the completion snapshot exists it is the authoritative model —
      // never re-assert "running" over it.
      if (fs.existsSync(path.join(hostDir, "workflows", `${runId}.json`))) return;
      // Journal: "started"/"result" per agentId, in order. started-without-result = running.
      const startedOrder: string[] = [];
      const started = new Set<string>();
      const done = new Set<string>();
      for (const line of fs.readFileSync(path.join(runDir, "journal.jsonl"), "utf8").split("\n")) {
        if (!line.trim()) continue;
        try {
          const e = JSON.parse(line) as { type?: string; agentId?: string };
          if (!e.agentId) continue;
          if (e.type === "started" && !started.has(e.agentId)) { started.add(e.agentId); startedOrder.push(e.agentId); }
          else if (e.type === "result") done.add(e.agentId);
        } catch {}
      }
      if (startedOrder.length === 0) return;
      const agents = startedOrder.map((id) => ({ agent_id: id, state: done.has(id) ? "done" : "running" }));
      // The script file is named <workflowName>-<runId>.js — the only mid-run
      // source of the run's human name.
      let workflowName = "workflow";
      try {
        const hit = fs.readdirSync(path.join(hostDir, "workflows", "scripts")).find((f) => f.endsWith(`-${runId}.js`));
        if (hit) workflowName = hit.slice(0, -`-${runId}.js`.length);
      } catch {}
      await postWorkflowRunIngest({
        external_run_id: runId,
        session_id: hostSessionId,
        project_path: projectPath,
        workflow_name: workflowName,
        status: "running",
        phases: [],
        agents,
        agent_count: agents.length,
      });
    } catch (err) {
      logError(`ingestLiveWorkflowRun failed for ${runId}`, err as Error);
    }
  }

  const watcher = new SessionWatcher();
  const fileSyncs = new Map<string, InvalidateSync>();
  // One canonical transcript per session UUID. `claude --resume` copies the
  // prior transcript into the new cwd's project dir, so the same UUID can be
  // watched under two slugs and sync the SAME conversation twice. We pick the
  // copy that lives in a real local checkout and skip the stale resume artifact.
  const canonicalTranscripts = new Map<string, TranscriptCandidate>();

  watcher.on("ready", () => {
    log("Session watcher ready (depth=2)");
  });

  watcher.on("session", (event: SessionEvent) => {
    selfHealIfTimersStalled("watcher");
    const filePath = event.filePath;
    lastWatcherEventTime = Date.now();

    const state = readDaemonState();
    if (state?.authExpired) {
      return;
    }

    if (isSyncPaused()) {
      log(`Sync paused, skipping session: ${event.sessionId}`);
      return;
    }

    // event.projectPath is the encoded directory name. Resolve the real path —
    // preferring the transcript's recorded cwd over the (lossy, copyable) slug —
    // so sync_mode:"selected" matching and the project label are both correct.
    const projectPath = resolveTranscriptProjectPath(filePath, event.projectPath);

    if (isPathExcluded(projectPath, config.excluded_paths)) {
      log(`Skipping sync for excluded path: ${projectPath}`);
      return;
    }

    if (!isProjectAllowedToSync(projectPath, config)) {
      log(`Skipping sync for non-selected project: ${projectPath}`);
      return;
    }

    // Dynamic-workflow run snapshot (not a transcript) → ingest into workflow_runs.
    if (event.workflowRunId) {
      void processWorkflowSnapshot(filePath, event.sessionId, event.workflowRunId, projectPath);
      return;
    }

    // Mid-run signal for a dynamic workflow: an agent transcript under
    // subagents/workflows/<runId>/ changed while no completion snapshot exists
    // yet. Ingest the journal-derived running model, then fall through — the
    // transcript itself still syncs as a subagent conversation.
    const liveWf = liveWorkflowRunFromPath(filePath);
    if (liveWf) void ingestLiveWorkflowRun(liveWf.runDir, liveWf.runId, liveWf.hostSessionId, projectPath);

    // Dedup duplicate-UUID transcripts: skip a resume-copy artifact whose
    // resolved project dir doesn't exist locally when another already-watched
    // copy lives in a real checkout. Server dedups by message_uuid, so this only
    // trims redundant writes; it never drops the copy in a real local checkout.
    let projectExists = false;
    try { projectExists = fs.existsSync(projectPath) && fs.statSync(projectPath).isDirectory(); } catch {}
    const incoming: TranscriptCandidate = { filePath, projectPath, projectExists };
    const choice = chooseSessionTranscript(incoming, canonicalTranscripts.get(event.sessionId));
    if (choice.action === "skip") {
      const existing = fileSyncs.get(filePath);
      if (existing) { existing.stop(); fileSyncs.delete(filePath); }
      log(`Skipping duplicate transcript for session ${event.sessionId.slice(0, 8)}: ${choice.reason}`);
      return;
    }
    // Incoming wins. If it supersedes a stale prior copy (the artifact registered
    // first because it changed first), stop that copy's sync too.
    if (choice.supersededFilePath) {
      const stale = fileSyncs.get(choice.supersededFilePath);
      if (stale) { stale.stop(); fileSyncs.delete(choice.supersededFilePath); }
    }
    canonicalTranscripts.set(event.sessionId, incoming);

    let sync = fileSyncs.get(filePath);
    if (!sync) {
      sync = new InvalidateSync(async () => {
        await processSessionFile(
          filePath,
          event.sessionId,
          projectPath,
          syncService,
          config.user_id!,
          config.team_id,
          conversationCache,
          retryQueue,
          pendingMessages,
          titleCache,
          updateState
        );
      }, MESSAGE_SYNC_DEBOUNCE);
      fileSyncs.set(filePath, sync);
    }

    sync.invalidate();
  });

  watcher.on("error", (error: Error) => {
    logError("Watcher error", error);
  });

  watcher.start();

  // Agent status hook file watcher
  fs.mkdirSync(AGENT_STATUS_DIR, { recursive: true });
  const statusWatcher = chokidarWatch(AGENT_STATUS_DIR, {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 50, pollInterval: 20 },
    depth: 0,
  });
  statusWatcher.on("add", handleStatusFile).on("change", handleStatusFile);

  // Process existing status files on startup (chokidar ignoreInitial skips them)
  try {
    for (const file of fs.readdirSync(AGENT_STATUS_DIR)) {
      if (file.endsWith(".json")) {
        handleStatusFile(path.join(AGENT_STATUS_DIR, file));
      }
    }
  } catch {}

  function handleStatusData(sessionId: string, data: HookStatusData, filePath?: string, opts?: { primed?: boolean }) {
    try {
      if (!data.status || !data.ts) return;

      const convId = conversationCache[sessionId];
      if (!convId) return;

      const prev = lastHookStatus.get(sessionId);
      if (prev && prev.ts > data.ts) return;
      if (prev && prev.ts === data.ts && prev.status === data.status) return;

      // The hook record carries transcript_path only on a permission prompt,
      // so the transcript comes from the session file index (a map lookup;
      // staleOk keeps a miss from walking on the hook path).
      const claudeTranscript = (): string | undefined => {
        const file = findSessionFile(sessionId, { staleOk: true });
        return file?.agentType === "claude" ? file.path : undefined;
      };
      // A live hook (no filePath) primes at the front of the queue: after a
      // restart the boot replay queues every cold transcript, and a Stop
      // hook's settle must not wait behind the fleet while lastHookStatus
      // still says working.
      const primeOpts = { front: !filePath };

      // The idle settle below scans the transcript for open background tasks
      // synchronously. For a claude transcript nobody primed yet (a Stop hook
      // landing right after a restart) that scan read the whole file on the
      // loop, 1.4s seen at boot. Prime it off the loop first and re-enter
      // once; the ts guards above drop this idle if a newer status landed
      // meanwhile, and the persist keeps the on disk record equal to what
      // lastHookStatus holds.
      if (data.status === "idle" && !opts?.primed) {
        const transcript = claudeTranscript();
        if (transcript && openTaskScanIsCold(transcript)) {
          const settle = data;
          void primeOpenTaskScan(transcript, sessionId, primeOpts).finally(() => {
            handleStatusData(sessionId, settle, filePath, { primed: true });
            if (!filePath) persistHookStatus(sessionId, settle);
          });
          return;
        }
      }

      // In bypassPermissions mode, Claude Code still emits permission_prompt
      // Notification events for tools it auto-approves. Those notifications do
      // not pause the agent — no real block exists. Treating them as
      // permission_blocked spawns a phantom Approve/Deny dialog in the web UI
      // that has no way to resolve, because the agent has already moved on.
      // The Notification event doesn't carry permission_mode, so fall back to
      // the last mode we observed for this session.
      //
      // EXCEPT while an AskUserQuestion block is open (classifyBypassBlock tracks it):
      // those follow-up Notifications are context-free (no tool name) and look identical
      // to a phantom here, but the agent really IS waiting. Suppressing them downgrades
      // the honest "waiting for input" status to "working" and the web falls behind for
      // the whole wait — worst for raw-iTerm sessions, where the question can't be
      // scraped from a pane or read from the buffered JSONL until it's answered.
      const inheritedMode = data.permission_mode || prev?.permission_mode;
      if (classifyBypassBlock(awaitingAskUserQuestion, sessionId, data.status, inheritedMode, data.message).suppress) {
        log(`Suppressing phantom permission_blocked in bypassPermissions mode for session ${sessionId.slice(0, 8)}`);
        data = { ...data, status: "working" };
      }

      // One-shot sweep for sessions in bypass mode. Catches stale records
      // from before the phantom-suppression fix shipped.
      if (inheritedMode === "bypassPermissions" && !bypassPermissionsCleaned.has(sessionId)) {
        bypassPermissionsCleaned.add(sessionId);
        syncService.cancelPendingPermissions(sessionId, Date.now())
          .then((n) => { if (n > 0) log(`Swept ${n} pre-existing pending permission(s) for bypass-mode session ${sessionId.slice(0, 8)}`); })
          .catch((err) => log(`Bypass-mode permission sweep failed: ${err instanceof Error ? err.message : String(err)}`));
      }

      // A finished turn with open background work (run_in_background command,
      // Monitor) is "waiting", not "idle": the harness will re-invoke the agent
      // when the task ends, so the ball is not in the user's court and the
      // session must not route into needs-input.
      if (data.status === "idle") {
        const settled = resolveTurnEndStatus(sessionId, data.transcript_path);
        if (settled !== "idle") data = { ...data, status: settled };
      }

      const statusChanged = !prev || prev.status !== data.status;
      const modeChanged = data.permission_mode && (!prev || prev.permission_mode !== data.permission_mode);
      // Keep the open task scan offset at the turn's edge while the agent
      // works (one stat when warm; the read runs under the prime semaphore),
      // so the Stop hook's sync scan covers only the turn's delta.
      if (statusChanged && data.status !== "idle") {
        const transcript = claudeTranscript();
        if (transcript) void primeOpenTaskScan(transcript, sessionId, primeOpts);
      }
      // Notification events don't carry permission_mode; preserve the last
      // observed mode so subsequent bypass-mode suppression stays correct.
      if (!data.permission_mode && prev?.permission_mode) {
        data = { ...data, permission_mode: prev.permission_mode };
      }
      lastHookStatus.set(sessionId, data);

      if (data.status === "compacting" || data.status === "thinking" || data.status === "stopped") {
        const existingTimer = idleTimers.get(sessionId);
        if (existingTimer) {
          clearTimeout(existingTimer);
          idleTimers.delete(sessionId);
        }
      }

      // Post-compaction recovery: track compaction events and detect dropped messages.
      // CC sometimes goes idle after compacting instead of continuing the user's turn.
      if (data.status === "compacting") {
        recentCompactionTs.set(sessionId, Date.now());
      }
      // Cancel pending recovery if session becomes active again
      if (data.status !== "idle" && data.status !== "compacting") {
        const recoveryTimer = postCompactionRecoveryTimers.get(sessionId);
        if (recoveryTimer) {
          clearTimeout(recoveryTimer);
          postCompactionRecoveryTimers.delete(sessionId);
          log(`Post-compaction recovery cancelled: session ${sessionId.slice(0, 8)} is now ${data.status}`);
        }
      }
      // Detect compaction -> idle pattern: schedule delayed re-injection
      if (data.status === "idle" && statusChanged) {
        const compactedAt = recentCompactionTs.get(sessionId);
        const injection = recentSessionInjections.get(convId);
        if (compactedAt && (Date.now() - compactedAt) < 60_000 &&
            injection && (Date.now() - injection.ts) < 120_000) {
          log(`Post-compaction idle: session ${sessionId.slice(0, 8)} compacted ${Math.round((Date.now() - compactedAt) / 1000)}s ago, scheduling message recovery in 5s`);
          const timerId = setTimeout(() => {
            postCompactionRecoveryTimers.delete(sessionId);
            const currentStatus = lastHookStatus.get(sessionId);
            if (currentStatus?.status !== "idle") {
              log(`Post-compaction recovery skipped: session ${sessionId.slice(0, 8)} is now ${currentStatus?.status}`);
              return;
            }
            log(`Post-compaction recovery: re-queuing message ${injection.messageId.slice(0, 8)} for session ${sessionId.slice(0, 8)}`);
            compactionRedeliveryBypass.add(injection.messageId);
            syncService.retryMessage(injection.messageId).catch(err => {
              log(`Post-compaction retry failed: ${err instanceof Error ? err.message : String(err)}`);
            });
          }, 5000);
          postCompactionRecoveryTimers.set(sessionId, timerId);
        }
        recentCompactionTs.delete(sessionId);
        recentSessionInjections.delete(convId);
      }

      if (statusChanged || modeChanged || pendingOpenTasksChanged(sessionId)) {
        sendAgentStatus(syncService, convId, sessionId, data.status, data.ts * 1000, data.permission_mode);
        log(`Hook status: ${data.status}${data.permission_mode ? ` mode=${data.permission_mode}` : ''} for session ${sessionId.slice(0, 8)}`);
      } else {
        // Nothing sent, so the open-task report the settle computed must not
        // wait around to ride an unrelated later status.
        pendingOpenTaskReports.delete(sessionId);
      }

      if (data.status === "stopped" && statusChanged) {
        const restartTs = restartingSessionIds.get(sessionId);
        if (restartTs && Date.now() - restartTs < RESTART_GUARD_TTL_MS) {
          log(`Session ended for ${sessionId.slice(0, 8)}, but restart in progress — skipping completion`);
          if (filePath) try { fs.unlinkSync(filePath); } catch {}
        } else {
          log(`Session ended for ${sessionId.slice(0, 8)}, marking completed`);
          syncService.markSessionCompleted(convId).catch(logConvexFailure);
          if (filePath) try { fs.unlinkSync(filePath); } catch {}
        }
      }

      if (data.status === "permission_blocked" && !permissionRecordPending.has(sessionId)) {
        permissionRecordPending.add(sessionId);
        permissionJustResolved.add(sessionId);
        const transcriptPath = data.transcript_path || findTranscriptForSession(sessionId);

        const hookToolName = data.message?.split(/[:\s]/)[0] || null;
        const toolInfo = !hookToolName ? extractPendingToolUseFromTranscript(transcriptPath || "") : null;
        const toolName = hookToolName || toolInfo?.tool_name || extractToolFromMessage(data.message || "");
        const preview = toolInfo?.arguments_preview || data.message || "";

        const SKIP_TOOLS = new Set(["AskUserQuestion", "EnterPlanMode", "ExitPlanMode", "TaskCreate", "TaskUpdate", "TaskList", "TaskGet"]);
        if (toolName && !SKIP_TOOLS.has(toolName)) {
          log(`Creating permission record: ${toolName} for session ${sessionId.slice(0, 8)}`);
          const permPrompt = { tool_name: toolName, arguments_preview: preview };

          syncService.createSessionNotification({
            conversation_id: convId,
            type: "permission_request",
            title: "codecast - Permission needed",
            message: truncateForNotification(`${toolName}: ${preview}`, 150),
          }).catch(() => {});

          handlePermissionRequest(syncService, convId, sessionId, permPrompt, log)
            .then((decision) => {
              permissionRecordPending.delete(sessionId);
              if (decision) {
                const key = decision.approved ? "Enter" : "Escape";
                log(`Permission ${decision.approved ? "approved" : "denied"} for session ${sessionId.slice(0, 8)}, sending '${key}'`);
                findSessionProcess(sessionId, detectSessionAgentType(sessionId)).then((proc) => {
                  if (!proc) { log("No process found for permission injection"); return; }
                  findTmuxPaneForTty(proc.tty).then(async (tmuxTarget) => {
                    try {
                      if (tmuxTarget) {
                        await tmuxExec(["send-keys", "-t", tmuxTarget, key]);
                      } else {
                        await injectViaTerminal(proc.tty, decision.approved ? "\r" : "\x1b", proc.termProgram, { keystrokes: true });
                      }
                      log(`Injected '${key}' for session ${sessionId.slice(0, 8)}`);
                      sendAgentStatus(syncService, convId, sessionId, "working");
                    } catch (err) {
                      log(`Failed to inject permission: ${err instanceof Error ? err.message : String(err)}`);
                    }
                  });
                }).catch((err) => {
                  log(`Failed to find session process: ${err instanceof Error ? err.message : String(err)}`);
                });
              }
            })
            .catch((err) => {
              permissionRecordPending.delete(sessionId);
              log(`Permission handling error: ${err instanceof Error ? err.message : String(err)}`);
            });
        } else {
          log(`Skipped permission record for ${toolName || "unknown"} (SKIP_TOOLS) session ${sessionId.slice(0, 8)}`);
          permissionRecordPending.delete(sessionId);
          if (toolName === "AskUserQuestion") {
            findSessionProcess(sessionId, detectSessionAgentType(sessionId)).then(async (proc) => {
              if (!proc) return;
              const tmuxTarget = await findTmuxPaneForTty(proc.tty) || (resumeSessionCache.get(sessionId) ?? null);
              if (tmuxTarget) {
                checkForInteractivePrompt(tmuxTarget, sessionId, convId, syncService, 3000).catch(() => {});
              }
            }).catch(() => {});
          }
        }
      }

      if (data.status !== "permission_blocked" && prev?.status === "permission_blocked") {
        permissionRecordPending.delete(sessionId);
        // The agent moved past the permission point without the web UI's
        // approval — bypass auto-approved, the user answered in the TUI, or
        // Claude Code emitted a stale permission_prompt for a tool that never
        // actually blocked. Either way, records created up to this transition
        // are stale; pass a cutoff so a freshly created record for the *next*
        // tool can't be racily cancelled by an in-flight mutation.
        const cutoff = Date.now();
        syncService.cancelPendingPermissions(sessionId, cutoff)
          .then((n) => { if (n > 0) log(`Cancelled ${n} stale permission record(s) for session ${sessionId.slice(0, 8)}`); })
          .catch((err) => log(`Failed to cancel pending permissions: ${err instanceof Error ? err.message : String(err)}`));
      }
    } catch {}
  }

  function handleStatusFile(filePath: string) {
    try {
      const basename = path.basename(filePath, ".json");
      if (!basename || !filePath.endsWith(".json")) return;
      const sessionId = basename;
      const raw = fs.readFileSync(filePath, "utf-8");
      const data = JSON.parse(raw) as HookStatusData;
      handleStatusData(sessionId, data, filePath);
    } catch {}
  }

  // Persist the normalized record (with inherited permission_mode) so a
  // daemon restart can correctly classify cached permission_blocked events
  // from sessions running in bypassPermissions mode.
  function persistHookStatus(sessionId: string, data: HookStatusData): void {
    try {
      fs.mkdirSync(AGENT_STATUS_DIR, { recursive: true });
      const persistData = lastHookStatus.get(sessionId) || data;
      fs.writeFileSync(path.join(AGENT_STATUS_DIR, `${sessionId}.json`), JSON.stringify(persistData));
    } catch {}
  }

  // HTTP hook server -- instant push path (file watcher above is the fallback)
  hookServer = startHookServer((sessionId, data) => {
    handleStatusData(sessionId, data);
    persistHookStatus(sessionId, data);

    // Piggyback message sync onto hook events — fs.watch can miss events on macOS,
    // so use the reliable hook path to also trigger a transcript re-read.
    const transcriptPath = data.transcript_path || findTranscriptForSession(sessionId);
    if (transcriptPath) {
      const existingSync = fileSyncs.get(transcriptPath);
      if (existingSync) {
        existingSync.invalidate();
      } else {
        // Session file exists but watcher never saw it — bootstrap the sync
        const parts = transcriptPath.split(path.sep);
        const projectDirName = parts[parts.length - 2];
        const projectPath = resolveTranscriptProjectPath(transcriptPath, projectDirName);

        if (isProjectAllowedToSync(projectPath, config) && !isPathExcluded(projectPath, config.excluded_paths)) {
          const sync = new InvalidateSync(async () => {
            await processSessionFile(
              transcriptPath,
              sessionId,
              projectPath,
              syncService,
              config.user_id!,
              config.team_id,
              conversationCache,
              retryQueue,
              pendingMessages,
              titleCache,
              updateState
            );
          }, MESSAGE_SYNC_DEBOUNCE);
          fileSyncs.set(transcriptPath, sync);
          sync.invalidate();
        }
      }
    }
  });

  function extractToolFromMessage(message: string): string {
    const colonMatch = message.match(/^(\w+):\s/);
    if (colonMatch) return colonMatch[1];
    const m = message.match(/permission to use (\w+)/i) || message.match(/allow (\w+)/i);
    // No "Bash" default: the generic permission_prompt Notification carries an
    // empty message, so the only honest tool source is the transcript. Guessing
    // "Bash" here manufactures a phantom Approve/Deny when extraction finds no
    // genuinely-pending tool (e.g. while a buffered AskUserQuestion is open).
    return m?.[1] || "";
  }

  function findTranscriptForSession(sessionId: string): string | null {
    const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
    try {
      const dirs = fs.readdirSync(claudeProjectsDir);
      for (const dir of dirs) {
        const jsonlPath = path.join(claudeProjectsDir, dir, `${sessionId}.jsonl`);
        if (fs.existsSync(jsonlPath)) return jsonlPath;
      }
    } catch {}
    return null;
  }

  // Clean up stale agent-status files every 30 minutes
  const statusCleanupInterval = setInterval(() => {
    (async () => {
      const cutoff = Date.now() - 60 * 60 * 1000;
      for (const f of await readAgentStatusFiles()) {
        if (f.mtimeMs >= cutoff) continue;
        await fs.promises.unlink(f.filePath).catch(() => {});
        lastHookStatus.delete(f.sessionId);
        bypassPermissionsCleaned.delete(f.sessionId);
      }
    })().catch(() => {});
  }, 30 * 60 * 1000);

  const CLAUDE_PLANS_DIR = path.join(process.env.HOME || "", ".claude", "plans");
  const planFileSynced = new Map<string, number>();

  function findMostRecentSessionId(): string | null {
    const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
    if (!fs.existsSync(claudeProjectsDir)) return null;
    let best: { sessionId: string; mtime: number } | null = null;
    try {
      for (const dir of fs.readdirSync(claudeProjectsDir)) {
        const dirPath = path.join(claudeProjectsDir, dir);
        if (!fs.statSync(dirPath).isDirectory()) continue;
        for (const file of fs.readdirSync(dirPath)) {
          if (!file.endsWith(".jsonl") || file.includes("sessions-index")) continue;
          const fp = path.join(dirPath, file);
          const mtime = fs.statSync(fp).mtimeMs;
          if (!best || mtime > best.mtime) {
            best = { sessionId: file.replace(".jsonl", ""), mtime };
          }
        }
      }
    } catch {}
    return best?.sessionId || null;
  }

  function handlePlanFile(filePath: string) {
    if (!filePath.endsWith(".md")) return;
    try {
      const stat = fs.statSync(filePath);
      const lastSynced = planFileSynced.get(filePath);
      if (lastSynced && stat.mtimeMs <= lastSynced) return;

      const content = fs.readFileSync(filePath, "utf-8");
      if (!content.trim()) return;

      const sessionId = findMostRecentSessionId();
      if (!sessionId) return;

      planFileSynced.set(filePath, stat.mtimeMs);
      syncService.syncPlanFromPlanMode({
        sessionId,
        planContent: content,
      }).then(planShortId => {
        if (planShortId) {
          planModePlanMap.set(sessionId, planShortId);
          savePlanModeCache();
          log(`Synced plan file ${path.basename(filePath)} -> ${planShortId} for session ${sessionId.slice(0, 8)}`);
        }
      }).catch(err => {
        log(`Failed to sync plan file ${path.basename(filePath)}: ${err instanceof Error ? err.message : String(err)}`);
      });
    } catch {}
  }

  if (fs.existsSync(CLAUDE_PLANS_DIR)) {
    const planFileWatcher = chokidarWatch(CLAUDE_PLANS_DIR, {
      ignoreInitial: true,
      awaitWriteFinish: { stabilityThreshold: 300, pollInterval: 50 },
      depth: 0,
    });
    planFileWatcher.on("add", handlePlanFile).on("change", handlePlanFile);
    log(`Plan file watcher started on ${CLAUDE_PLANS_DIR}`);
  }

  // Sweep ~/.claude/projects for files whose synced position trails their size and
  // push the missing bytes directly via processSessionFile — independent of the file
  // watcher. Runs at startup (files missed while the daemon was down), on wake (the
  // watcher's FSEvents stream may have gone silent across a sleep), and after
  // reconciliation rewinds positions (so its repair actually ships, not just resets).
  const runUnsyncedSweepOnce = async (reason: string) => {
    const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");

    // Safety check: ensure directory exists
    if (!fs.existsSync(claudeProjectsDir)) {
      log(`${reason}: No projects directory found, skipping`);
      return;
    }

    let unsyncedFiles: string[] = [];
    try {
      unsyncedFiles = await findUnsyncedFilesAsync(
        claudeProjectsDir,
        undefined,
        (filePath) => isTranscriptFileInSyncScope(filePath, config),
      );
    } catch (err) {
      logError(`${reason} failed to find unsynced files`, err instanceof Error ? err : new Error(String(err)));
      return;
    }

    if (unsyncedFiles.length > 0) {
      log(`${reason}: Found ${unsyncedFiles.length} files needing sync`);

      for (const filePath of unsyncedFiles) {
        // Yield between files: processSessionFile's read+parse is synchronous CPU
        // work, and a backlog sweep runs dozens of files. Without this the sweep
        // monopolizes the loop for minutes and heartbeats/deliveries starve.
        await new Promise((resolve) => setImmediate(resolve));
        const parts = filePath.split(path.sep);
        const sessionId = resolveSessionId(filePath);

        const isSubagentFile = parts.includes("subagents");
        let projectDirName: string;
        if (isSubagentFile) {
          const subagentsIdx = parts.lastIndexOf("subagents");
          projectDirName = parts[subagentsIdx - 2] || parts[parts.length - 2];
        } else {
          projectDirName = parts[parts.length - 2];
        }
        const projectPath = resolveTranscriptProjectPath(filePath, projectDirName);

        if (config.excluded_paths && isPathExcluded(projectPath, config.excluded_paths)) {
          continue;
        }

        if (!isProjectAllowedToSync(projectPath, config)) {
          continue;
        }

        let parentConversationId: string | undefined;
        if (isSubagentFile) {
          const subagentsIdx = parts.lastIndexOf("subagents");
          const parentSessionId = parts[subagentsIdx - 1];
          if (parentSessionId && conversationCache[parentSessionId]) {
            parentConversationId = conversationCache[parentSessionId];
          }
          try {
            const metaPath = filePath.replace(/\.jsonl$/, ".meta.json");
            if (fs.existsSync(metaPath)) {
              const meta = JSON.parse(fs.readFileSync(metaPath, "utf-8"));
              if (meta.description) subagentDescriptions.set(sessionId, meta.description);
            }
          } catch {}
        }

        log(`${reason}: Syncing ${sessionId}${parentConversationId ? ` (subagent of ${parentConversationId})` : ""}`);

        await processSessionFile(
          filePath,
          sessionId,
          projectPath,
          syncService,
          config.user_id!,
          config.team_id,
          conversationCache,
          retryQueue,
          pendingMessages,
          titleCache,
          updateState,
          parentConversationId,
        );
      }

      // Resolve any remaining pending subagent parents after all files processed
      for (const [childSessionId, parentSessionId] of pendingSubagentParents) {
        const parentConvId = conversationCache[parentSessionId];
        const childConvId = conversationCache[childSessionId];
        if (parentConvId && childConvId) {
          syncService.linkSessions(parentConvId, childConvId, subagentDescriptions.get(childSessionId)).then(() => {
            log(`${reason}: Linked subagent ${childSessionId.slice(0, 8)} -> parent ${parentSessionId.slice(0, 8)}`);
          }).catch((err) => {
            log(`${reason}: Failed to link subagent ${childSessionId.slice(0, 8)}: ${err}`);
          });
          pendingSubagentParents.delete(childSessionId);
        }
      }

      log(`${reason}: Completed syncing ${unsyncedFiles.length} files`);
    } else {
      log(`${reason}: All files up to date`);
    }
  };

  // Serialize sweeps: startup, wake recovery, and reconciliation can all fire one, and
  // two overlapping runs would race processSessionFile on the same file (each advances
  // the shared synced position). If one is active, mark that another pass is needed and
  // let the running sweep loop once more — so a wake during a slow startup scan isn't lost.
  let unsyncedSweepRunning = false;
  let unsyncedSweepQueued = false;
  const syncUnsyncedFiles = async (reason: string): Promise<void> => {
    if (unsyncedSweepRunning) { unsyncedSweepQueued = true; return; }
    unsyncedSweepRunning = true;
    try {
      do {
        unsyncedSweepQueued = false;
        await runUnsyncedSweepOnce(reason);
      } while (unsyncedSweepQueued);
    } finally {
      unsyncedSweepRunning = false;
    }
  };

  // Expose the sweep to reconciliation (watcher-independent backstop) and define the
  // wake-recovery handler the event-loop monitor calls. Reentrancy is guarded so a
  // burst of wake ticks collapses to a single restart+sweep in flight, and a
  // completed recovery is not repeated within a floor interval — a second wake
  // minutes after the first has a freshly-restarted watcher and a just-swept
  // backlog, so re-running the full recovery only adds load at the worst time.
  pushUnsyncedFilesHandler = syncUnsyncedFiles;
  const WAKE_RECOVERY_MIN_INTERVAL_MS = 3 * 60 * 1000;
  let wakeRecoveryInProgress = false;
  let lastWakeRecoveryDoneAt = 0;
  wakeRecoveryHandler = () => {
    if (wakeRecoveryInProgress) return;
    if (Date.now() - lastWakeRecoveryDoneAt < WAKE_RECOVERY_MIN_INTERVAL_MS) {
      log("Wake recovery: skipped (previous recovery completed under 3 minutes ago)");
      return;
    }
    wakeRecoveryInProgress = true;
    void runWakeRecovery({
      restartWatcher: () => watcher.restart(),
      sweep: () => syncUnsyncedFiles("Wake recovery"),
      onWatcherRestarted: () => { lastWatcherEventTime = Date.now(); },
      log: (msg) => log(msg),
      logError: (msg, err) => logError(msg, err),
    }).finally(() => {
      wakeRecoveryInProgress = false;
      lastWakeRecoveryDoneAt = Date.now();
    });
  };

  // Run startup scan in background (don't block daemon startup)
  syncUnsyncedFiles("Startup scan").then(async () => {
    // Backfill: detect unlinked plan handoff children.
    //
    // Iterates FILES (one readdir per project dir), not cache entries: the old
    // shape re-listed the projects dir and existsSync-probed every dir for each
    // of ~14k cached sessions, then head-read nearly every transcript — hundreds
    // of thousands of synchronous FS calls that pinned the event loop ~8s per
    // boot (and 30s+ under load), which is what starved message delivery on
    // 2026-08-15. A handoff prompt is the child's FIRST user message, so only
    // recently-modified transcripts can still need linking — old ones were
    // linked when first seen or never will be. All FS via fs.promises, with a
    // yield per directory, so the loop stays responsive throughout.
    const claudeProjectsDir = path.join(process.env.HOME || "", ".claude", "projects");
    const HANDOFF_BACKFILL_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;
    const cutoffMs = Date.now() - HANDOFF_BACKFILL_WINDOW_MS;
    let linked = 0;
    const alreadyLinked = new Set(planHandoffChildren.values());
    const examined = new Set<string>();
    let projDirs: string[] = [];
    try { projDirs = await fs.promises.readdir(claudeProjectsDir); } catch {}
    for (const dir of projDirs) {
      let entries: string[] = [];
      try { entries = await fs.promises.readdir(path.join(claudeProjectsDir, dir)); } catch { continue; }
      for (const entry of entries) {
        if (!entry.endsWith(".jsonl")) continue;
        const childSessionId = entry.slice(0, -".jsonl".length);
        if (examined.has(childSessionId)) continue;
        const childConvId = conversationCache[childSessionId];
        if (!childConvId || alreadyLinked.has(childConvId)) continue;
        const fp = path.join(claudeProjectsDir, dir, entry);
        try {
          const st = await fs.promises.stat(fp);
          if (st.mtimeMs < cutoffMs) continue;
        } catch { continue; }
        examined.add(childSessionId);
        try {
          const headContent = readFileHead(fp, 16384);
          const msgs = parseSessionFile(headContent);
          const userMsgs = msgs.filter(m => m.role === "user").slice(0, 3);
          for (const msg of userMsgs) {
            if (!msg.content) continue;
            const handoffMatch = msg.content.match(/read the full transcript at:\s*([^\s]+\.jsonl)/i);
            if (handoffMatch) {
              const jsonlPath = handoffMatch[1];
              const parentMatch = jsonlPath.match(/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.jsonl$/);
              if (parentMatch) {
                const parentSessionId = parentMatch[1];
                const parentConvId = conversationCache[parentSessionId];
                if (parentConvId && parentConvId !== childConvId) {
                  try {
                    await syncService.linkPlanHandoff(parentConvId, childConvId);
                    planHandoffChildren.set(parentConvId, childConvId);
                    linked++;
                    log(`Backfill: linked plan handoff ${childSessionId.slice(0, 8)} -> parent ${parentSessionId.slice(0, 8)}`);
                  } catch (err) {
                    log(`Backfill: failed to link ${childSessionId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
                  }
                }
              }
              break;
            }
          }
        } catch {}
      }
      // One yield per directory keeps the backfill from monopolizing the loop.
      await new Promise<void>(resolve => setImmediate(resolve));
    }
    if (linked > 0) log(`Backfill: linked ${linked} plan handoff session(s)`);
  }).catch(err => {
    logError("Startup scan failed", err instanceof Error ? err : new Error(String(err)));
  });

  const watchdogInterval = startWatchdog({
    config,
    syncService,
    conversationCache,
    retryQueue,
    pendingMessages,
    titleCache,
    updateState,
    watcher,
  });

  const versionCheckInterval = startVersionChecker(syncService);
  const reconciliationInterval = startReconciliation(syncService, retryQueue, conversationCache, config);

  const cursorWatcher = new CursorWatcher();
  const cursorSyncs = new Map<string, InvalidateSync>();

  cursorWatcher.on("ready", () => {
    log("Cursor watcher ready");
  });

  cursorWatcher.on("session", (event: CursorSessionEvent) => {
    const dbPath = event.dbPath;

    const state = readDaemonState();
    if (state?.authExpired) {
      return;
    }

    if (isSyncPaused()) {
      log(`Sync paused, skipping Cursor session: ${event.sessionId}`);
      return;
    }

    if (isPathExcluded(event.workspacePath, config.excluded_paths)) {
      log(`Skipping sync for excluded path: ${event.workspacePath}`);
      return;
    }

    if (!isProjectAllowedToSync(event.workspacePath, config)) {
      log(`Skipping sync for non-selected project: ${event.workspacePath}`);
      return;
    }

    let sync = cursorSyncs.get(dbPath);
    if (!sync) {
      sync = new InvalidateSync(async () => {
        await processCursorSession(
          dbPath,
          event.sessionId,
          event.workspacePath,
          syncService,
          config.user_id!,
          config.team_id,
          conversationCache,
          retryQueue,
          pendingMessages,
          updateState
        );
      }, MESSAGE_SYNC_DEBOUNCE);
      cursorSyncs.set(dbPath, sync);
    }

    sync.invalidate();
  });

  cursorWatcher.on("error", (error: Error) => {
    logError("Cursor watcher error", error);
  });

  cursorWatcher.on("denied", () => {
    saveDaemonState({ cursorAccess: "denied" });
    log("Cursor sync stopped: macOS denied access to Cursor's data — run `cast doctor` for fix steps");
  });

  // Consent gate (macOS): scanning Cursor's dir is what raises the login-time
  // "codecast would like to access data from other apps" prompt, so only scan
  // when the user opted in or a prior run recorded the grant. `cast cursor on`
  // flips the pref and restarts the daemon, so the one prompt fires while the
  // user is watching that command, not at some future login.
  const cursorDecision = cursorWatcherDecision({
    platform: process.platform,
    pref: config.cursor_sync,
    recordedAccess: readDaemonState().cursorAccess,
  });
  if (cursorDecision === "start") {
    // Fire-and-forget: with an undecided TCC state the probe blocks until the
    // user answers the permission dialog, and daemon startup must not.
    void (async () => {
      const probe = process.platform === "darwin" ? await probeCursorAccess() : "ok";
      if (probe === "denied") {
        saveDaemonState({ cursorAccess: "denied" });
        log("Cursor sync unavailable: macOS denied access to Cursor's data — run `cast doctor` for fix steps");
      } else {
        if (process.platform === "darwin" && probe === "ok") {
          saveDaemonState({ cursorAccess: "granted" });
        }
        cursorWatcher.start();
      }
    })();
  } else if (cursorDecision === "needs-consent" && fs.existsSync(defaultCursorPath())) {
    log("Cursor detected but not synced — run `cast cursor on` to enable (macOS will ask to allow access once)");
  }

  const cursorTranscriptWatcher = new CursorTranscriptWatcher();
  const cursorTranscriptSyncs = new Map<string, InvalidateSync>();

  cursorTranscriptWatcher.on("ready", () => {
    log("Cursor transcript watcher ready");
  });

  cursorTranscriptWatcher.on("session", (event: CursorTranscriptEvent) => {
    const filePath = event.filePath;
    lastWatcherEventTime = Date.now();

    const state = readDaemonState();
    if (state?.authExpired) {
      return;
    }

    if (isSyncPaused()) {
      log(`Sync paused, skipping Cursor transcript: ${event.sessionId}`);
      return;
    }

    const workspacePath = findWorkspacePathForCursorConversation(event.sessionId);
    if (workspacePath) {
      if (isPathExcluded(workspacePath, config.excluded_paths)) {
        log(`Skipping sync for excluded path: ${workspacePath}`);
        return;
      }

      if (!isProjectAllowedToSync(workspacePath, config)) {
        log(`Skipping sync for non-selected project: ${workspacePath}`);
        return;
      }
    } else if (config.sync_mode === "selected") {
      log(`Skipping Cursor transcript with unknown workspace path: ${event.sessionId}`);
      return;
    }

    let sync = cursorTranscriptSyncs.get(filePath);
    if (!sync) {
      sync = new InvalidateSync(async () => {
        await processCursorTranscriptFile(
          filePath,
          event.sessionId,
          syncService,
          config.user_id!,
          config.team_id,
          conversationCache,
          retryQueue,
          pendingMessages,
          updateState
        );
      }, MESSAGE_SYNC_DEBOUNCE);
      cursorTranscriptSyncs.set(filePath, sync);
    }

    sync.invalidate();
  });

  cursorTranscriptWatcher.on("error", (error: Error) => {
    logError("Cursor transcript watcher error", error);
  });

  // ~/.cursor/projects is a dotfile dir (no TCC gate), so only the explicit
  // off switch disables transcript sync.
  if (config.cursor_sync !== "off") {
    cursorTranscriptWatcher.start();
  }

  codexAppServerInstance = new CodexAppServer({
    log,
    onApproval: async (threadId: string, approval: ApprovalRequest) => {
      const entry = appServerThreads.get(threadId);
      if (!entry) return true;
      if (entry.approvalPolicy === "never") {
        log(`[codex-app-server] auto-approving ${approval.method} for thread ${threadId.slice(0, 8)} (approvalPolicy=never)`);
        return true;
      }
      const permissionPrompt = {
        tool_name: approval.method,
        arguments_preview: JSON.stringify(approval.params).slice(0, 200),
      };
      try {
        const decision = await handlePermissionRequest(syncService, entry.conversationId, threadId, permissionPrompt, log);
        return decision?.approved ?? true;
      } catch (err) {
        log(`[codex-app-server] approval error: ${err instanceof Error ? err.message : String(err)}`);
        return true;
      }
    },
  });

  codexAppServerInstance.on("ready", () => {
    if (rehydratePersistedAppServerThreadsPromise) return;
    rehydratePersistedAppServerThreadsPromise = rehydratePersistedAppServerThreads()
      .catch((err) => {
        log(`[codex-app-server] rehydrate failed: ${err instanceof Error ? err.message : String(err)}`);
      })
      .finally(() => {
        rehydratePersistedAppServerThreadsPromise = null;
      });
  });

  codexAppServerInstance.on("exited", () => {
    if (appServerThreads.size > 0 || appServerConversations.size > 0) {
      log(`[codex-app-server] clearing ${appServerThreads.size} live thread registration(s) after exit`);
      // Notify every active conversation that its session has stopped
      // before wiping the maps, so the UI doesn't stay stuck on "working"
      for (const [threadId, entry] of appServerThreads) {
        sendAgentStatus(syncService, entry.conversationId, threadId, "stopped");
        stopManagedSessionHeartbeat(threadId);
      }
    }
    clearLiveAppServerThreadRegistrations();
  });

  codexAppServerInstance.on("turnCompleted", async (threadId: string, turnId: string, messages: any[], status: string) => {
    const entry = appServerThreads.get(threadId);
    try {
      if (!entry) return;
      await syncAppServerTurnMessagesIfChanged(
        turnId,
        entry.conversationId,
        messages as RawMessage[],
        syncService,
        retryQueue,
        threadId.slice(0, 8),
      );
      if (status === "completed") {
        markAppServerConversationResumable(entry.conversationId, threadId);
      }
      sendAgentStatus(syncService, entry.conversationId, threadId, status === "completed" ? resolveTurnEndStatus(threadId) : "working");
    } finally {
      clearAppServerTurnProgress(turnId);
    }
  });

  codexAppServerInstance.on("turnStarted", (threadId: string, turnId: string) => {
    const entry = appServerThreads.get(threadId);
    appServerTurnProgress.set(turnId, makeAppServerTurnProgress(threadId));
    if (entry) {
      sendAgentStatus(syncService, entry.conversationId, threadId, "working");
      // Persist early so mid-turn threads survive an app-server crash
      markAppServerConversationResumable(entry.conversationId, threadId);
    }
  });

  codexAppServerInstance.on("itemStarted", (threadId: string, turnId: string, item: ThreadItem) => {
    const entry = appServerThreads.get(threadId);
    const progress = appServerTurnProgress.get(turnId);
    if (!entry || !progress) return;
    rememberAppServerPartialStart(progress, item);
  });

  codexAppServerInstance.on("itemCompleted", (threadId: string, turnId: string, item: ThreadItem) => {
    const entry = appServerThreads.get(threadId);
    const progress = appServerTurnProgress.get(turnId);
    if (!entry || !progress) return;
    removeAppServerPartial(progress, item.id);
    progress.items.push(item);
    const messages = threadItemsToMessages(progress.items) as RawMessage[];
    syncAppServerTurnMessagesIfChanged(
      turnId,
      entry.conversationId,
      messages,
      syncService,
      retryQueue,
      threadId.slice(0, 8),
    ).catch((err) => {
      log(`[codex-app-server] live sync failed for thread ${threadId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
    });
  });

  codexAppServerInstance.on("messageDelta", (threadId: string, turnId: string, delta: string, itemId: string) => {
    const entry = appServerThreads.get(threadId);
    const progress = appServerTurnProgress.get(turnId);
    if (!entry || !progress || !itemId) return;
    appendAppServerPartialDelta(progress, itemId, delta);
    scheduleAppServerPartialSync(
      turnId,
      entry.conversationId,
      syncService,
      retryQueue,
      threadId.slice(0, 8),
    );
  });

  codexAppServerInstance.on("statusChanged", (threadId: string, status: AppServerThreadStatus) => {
    const entry = appServerThreads.get(threadId);
    if (!entry) return;
    const agentStatus = mapCodexAppServerThreadStatusToAgentStatus(status);
    if (!agentStatus) return;
    const activeFlags = status.activeFlags?.length ? ` flags=${status.activeFlags.join(",")}` : "";
    log(`[codex-app-server] thread ${threadId.slice(0, 8)} status=${status.type}${activeFlags} -> ${agentStatus}`);
    sendAgentStatus(syncService, entry.conversationId, threadId, agentStatus);
  });

  codexAppServerInstance.on("threadNameUpdated", async (threadId: string, name: string | null) => {
    if (!name) return;
    const entry = appServerThreads.get(threadId);
    if (!entry) return;
    try {
      await syncService.updateTitle(entry.conversationId, name);
      log(`[codex-app-server] updated title for thread ${threadId.slice(0, 8)}: ${name}`);
    } catch {}
  });

  codexAppServerInstance.on("approvalRequested", (threadId: string, approval: ApprovalRequest) => {
    const entry = appServerThreads.get(threadId);
    if (entry && entry.approvalPolicy !== "never") {
      sendAgentStatus(syncService, entry.conversationId, threadId, "permission_blocked");
      syncService.createSessionNotification({
        conversation_id: entry.conversationId,
        type: "permission_request" as any,
        title: "codecast - Permission needed",
        message: `${approval.method}: ${JSON.stringify(approval.params).slice(0, 200)}`,
      }).catch(() => {});
    }
  });

  codexAppServerInstance.on("error", (err: Error) => {
    log(`[codex-app-server] error: ${err.message}`);
  });

  codexAppServerInstance.on("binaryNotFound", (binary: string) => {
    log(`[codex-app-server] "${binary}" not installed -- codex sessions will return install instructions`);
  });

  try {
    codexAppServerInstance.start();
    log("[codex-app-server] started");
  } catch (err: any) {
    log(`[codex-app-server] failed to start: ${err?.message ?? err} -- codex features disabled`);
  }

  // Fenced execution is an explicit local rollout only. There is no remote
  // command/UI switch that can activate it; without the exact environment bit
  // the legacy daemon remains byte-for-byte responsible for execution.
  const fencedRuntime = fencedExecutionEnabled()
    ? getProcessExecutionRuntime({
        transport: syncService,
        ownerDeviceId: deviceId(),
        journalDirectory: path.join(CONFIG_DIR, "execution-journal"),
        drivers: (() => {
          const registry = new RuntimeDriverRegistry();
          registry.register(new ManagedTmuxRuntimeDriver({
            io: {
              async createSession({ tmuxSession, cwd }) {
                await tmuxExec(["new-session", "-d", ...TMUX_SIZE_ARGS, "-s", tmuxSession, "-c", cwd]);
              },
              async setSessionOption({ tmuxSession, name, value }) {
                await setTmuxSessionOption(tmuxSession, name, value);
              },
              async launchLiteral({ tmuxSession, command }) {
                await tmuxExec(["send-keys", "-l", "-t", `${tmuxSession}:0.0`, command]);
                await tmuxExec(["send-keys", "-t", `${tmuxSession}:0.0`, "Enter"]);
              },
              async listCandidates({ expectedTmuxSession }) {
                let names: string[];
                try {
                  const { stdout } = await tmuxExec(["list-sessions", "-F", "#{session_name}"]);
                  names = stdout.split("\n").map((name) => name.trim()).filter(Boolean);
                } catch (error) {
                  const message = error instanceof Error ? error.message : String(error);
                  if (/no server running|failed to connect to server/i.test(message)) return [];
                  throw error;
                }
                const candidates = [];
                for (const tmuxSession of names) {
                  if (tmuxSession !== expectedTmuxSession && !tmuxSession.startsWith("cc-f1-")) continue;
                  const tags: Partial<FencedTmuxTags> = {};
                  for (const [key, name] of Object.entries(FENCED_TMUX_TAG_NAMES) as Array<[
                    keyof FencedTmuxTags,
                    string,
                  ]>) {
                    const value = await getTmuxSessionOption(tmuxSession, name);
                    if (value !== null) tags[key] = value;
                  }
                  candidates.push({
                    tmuxSession,
                    tmuxTarget: `${tmuxSession}:0.0`,
                    alive: true,
                    tags,
                  });
                }
                return candidates;
              },
              async injectDelivery({ tmuxTarget, agent, delivery }) {
                const text = delivery.input
                  .map((item) => item.type === "text" ? item.text : `[Image ${item.path}]`)
                  .filter(Boolean)
                  .join("\n");
                await injectViaTmux(tmuxTarget, text, agent);
                return { state: "delivered" as const };
              },
              async stopSession(tmuxSession) {
                await killTmuxSessionAndTree(tmuxSession);
              },
              async quarantineSession(tmuxSession) {
                await killTmuxSessionAndTree(tmuxSession);
              },
            },
            buildLaunch(target, configuration) {
              const { binaryArgs } = buildLaunchArgs({
                agentType: target.requestedAgent,
                configuredArgs: getConfiguredAgentArgs(target.requestedAgent, config),
                permFlags: getPermissionFlags(target.requestedAgent, config),
                defaultFlags: getDefaultParamFlags(target.requestedAgent, config),
                modelAlias: configuration.model,
                requestedEffort: configuration.effort,
                hasCodexPermissionMode: !!config.agent_permission_modes?.codex,
              });
              const tokens = [
                "env",
                "-u",
                "CLAUDECODE",
                "-u",
                "CLAUDE_CODE_ENTRYPOINT",
                launchBinary(target.requestedAgent, { warn: log }),
                ...sanitizeBinaryArgs(binaryArgs),
              ];
              return { command: tokens.map(shellEscapeForSh).join(" ") };
            },
          }));
          if (codexAppServerInstance) {
            registry.register(new CodexAppServerRuntimeDriver({
              io: {
                client: codexAppServerInstance,
                registerThread({ conversationId, threadId, cwd, approvalPolicy }) {
                  registerAppServerConversation(conversationId, threadId, { cwd, approvalPolicy });
                },
                async inspectThread(threadId) {
                  if (!codexAppServerInstance?.running) return "unknown";
                  return appServerThreads.has(threadId) ? "alive" : "unknown";
                },
                async stopThread(threadId) {
                  const entry = appServerThreads.get(threadId);
                  if (!entry) return;
                  await teardownConversationBackendsLive(entry.conversationId, { interruptActiveTurn: true });
                },
                async quarantineThread(threadId) {
                  const entry = appServerThreads.get(threadId);
                  if (!entry) return;
                  await teardownConversationBackendsLive(entry.conversationId, { interruptActiveTurn: true });
                },
              },
            }));
          }
          return registry;
        })(),
        resolveImage: (storageId) => downloadImage(storageId, syncService),
        onLog: log,
      })
    : null;
  if (fencedRuntime) {
    log(`[fenced-execution] enabled protocol=1 boot=${fencedRuntime.daemonBootId}`);
    await fencedRuntime.start();
  } else {
    log("[fenced-execution] disabled (set CODECAST_FENCED_EXECUTION_V1=1 for local rollout)");
  }

  // One registration path for the JSONL-dir CLI watchers (codex, gemini), which now
  // share the generic TranscriptDirWatcher. Claude's sessionWatcher and cursor's
  // SQLite watcher are different kinds and register on their own paths. Each watcher
  // debounces per-file syncs through InvalidateSync; the first event for a file fixes
  // the sync closure (sessionId/projectHash are derived from the path, so later events
  // for the same file carry identical values — same as before the collapse).
  const dirEventWatchers: DirEventWatcher[] = [];
  const registerJsonlDirWatcher = (
    watcher: DirEventWatcher,
    label: string,
    process: (event: TranscriptDirEvent) => Promise<unknown>,
  ): void => {
    const syncs = new Map<string, InvalidateSync>();
    watcher.on("ready", () => {
      log(`${label} watcher ready`);
    });
    watcher.on("session", (event) => {
      const filePath = event.filePath;

      const state = readDaemonState();
      if (state?.authExpired) {
        return;
      }

      if (isSyncPaused()) {
        log(`Sync paused, skipping ${label} session: ${event.sessionId}`);
        return;
      }

      let sync = syncs.get(filePath);
      if (!sync) {
        sync = new InvalidateSync(async () => {
          await process(event);
        }, MESSAGE_SYNC_DEBOUNCE);
        syncs.set(filePath, sync);
      }

      sync.invalidate();
    });
    watcher.on("error", (error: Error) => {
      logError(`${label} watcher error`, error);
    });
    dirEventWatchers.push(watcher);
    watcher.start();
  };

  registerJsonlDirWatcher(
    new TranscriptDirWatcher(transcriptDirWatcherConfig("codex")),
    "Codex",
    (event) => processCodexSession(
      event.filePath,
      event.sessionId,
      syncService,
      config.user_id!,
      config.team_id,
      conversationCache,
      retryQueue,
      pendingMessages,
      titleCache,
      updateState
    ),
  );

  registerJsonlDirWatcher(
    new TranscriptDirWatcher(transcriptDirWatcherConfig("gemini")),
    "Gemini",
    (event) => processGeminiSession(
      event.filePath,
      event.sessionId,
      event.projectHash ?? "",
      syncService,
      config.user_id!,
      config.team_id,
      conversationCache,
      retryQueue,
      pendingMessages,
      titleCache,
      updateState
    ),
  );

  // OpenCode's SQLite-store watcher rides the same registration seam: it emits
  // per-session `session` events (filePath = the session id, which the seam uses
  // only as an opaque per-session debounce key), and processOpencodeSession
  // assembles+syncs the whole session from the DB each pass.
  registerJsonlDirWatcher(
    new OpencodeStorageWatcher(),
    "OpenCode",
    (event) => processOpencodeSession(
      event.sessionId,
      syncService,
      config.user_id!,
      config.team_id,
      conversationCache,
      retryQueue,
      pendingMessages,
      titleCache,
      updateState
    ),
  );

  registerJsonlDirWatcher(
    new TranscriptDirWatcher(transcriptDirWatcherConfig("pi")),
    "pi",
    (event) => processPiSession(
      event.filePath,
      event.sessionId,
      syncService,
      config.user_id!,
      config.team_id,
      conversationCache,
      retryQueue,
      pendingMessages,
      titleCache,
      updateState
    ),
  );

  registerJsonlDirWatcher(
    new TranscriptDirWatcher(transcriptDirWatcherConfig("grok")),
    "grok",
    (event) => processGrokSession(
      event.filePath,
      event.sessionId,
      syncService,
      config.user_id!,
      config.team_id,
      conversationCache,
      retryQueue,
      pendingMessages,
      titleCache,
      updateState
    ),
  );

  const subscriptionClient = syncService.getSubscriptionClient();
  let unsubscribe: (() => void) | null = null;
  let permissionUnsubscribe: (() => void) | null = null;
  let commandUnsubscribe: (() => void) | null = null;
  const processedPermissionIds = new Set<string>();
  const processedCommandIds = new Set<string>();
  const messageRetryTimers = new Set<string>();

  function scheduleMessageRetry(
    messageId: string,
    retryCount: number,
    conversationId: string,
    messageContent: string,
  ) {
    if (messageRetryTimers.has(messageId)) return;
    if (retryCount >= 10) {
      logDelivery(`msg=${messageId.slice(0, 8)} exceeded max retries (10), marking undeliverable`);
      syncService.updateMessageStatus({ messageId, status: "undeliverable" }).catch(logConvexFailure);
      return;
    }
    const delays = [1000, 5000, 15000, 30000, 60000];
    const delay = delays[Math.min(retryCount, delays.length - 1)];
    logDelivery(`Scheduling retry ${retryCount + 1}/10 for msg=${messageId.slice(0, 8)} in ${delay / 1000}s`);
    messageRetryTimers.add(messageId);
    setTimeout(async () => {
      messageRetryTimers.delete(messageId);
      try {
        await syncService.retryMessage(messageId);
        logDelivery(`Retry ${retryCount + 1} triggered for msg=${messageId.slice(0, 8)}`);
      } catch (err) {
        logDelivery(`Retry trigger failed for msg=${messageId.slice(0, 8)}: ${err instanceof Error ? err.message : String(err)}`);
      }
    }, delay);
  }

  // messagesInFlight / injectedMessageTs are module-scoped so kill_session can wipe a
  // conversation's entries — otherwise a forced restart leaves the local dedup convinced
  // the message just landed even though the tmux it landed in was just killed.
  // Hard ceiling on a single deliverMessage attempt. Worst legitimate path is auto-resume
  // of a large JSONL (~90s poll + tmux startup); 180s leaves margin without leaving the
  // in-flight slot wedged forever if a tmux/Convex call hangs.
  const DELIVERY_TIMEOUT_MS = 180_000;

  // Shared by the reactive subscription and the poll fallback below. Feeding the
  // same batch twice is safe: the server-side claim, messagesInFlight, the
  // per-conversation serialization and the injection dedup window all gate re-entry.
  const handlePendingMessagesUpdate = async (messages: any) => {
    selfHealIfTimersStalled("convex");
    if (!messages) {
      return;
    }

    if (Array.isArray(messages)) {
      if (messages.length > 0) {
        logDelivery(`Delivery scan: ${messages.length} pending message(s) received`);
      }
      for (const pendingMsg of messages) {
        try {
          assertLegacyDeliveryEnvelope(pendingMsg);
        } catch {
          logDelivery(
            `[FENCED-BYPASS-BLOCKED] msg=${String(pendingMsg?._id ?? "unknown").slice(0, 12)} reached legacy subscription`,
          );
          continue;
        }
        const claimed = await syncService.claimPendingMessageForDelivery(pendingMsg._id);
        if (!claimed) {
          logDelivery(`Skipping msg=${pendingMsg._id.slice(0, 8)} - not owned by this daemon`);
          continue;
        }
        const msg = { ...pendingMsg, ...claimed };
        if ((msg.retry_count ?? 0) >= 12) {
          logDelivery(`msg=${msg._id.slice(0, 8)} retry_count=${msg.retry_count} exceeds cap, marking undeliverable`);
          syncService.updateMessageStatus({ messageId: msg._id, status: "undeliverable" }).catch(logConvexFailure);
          continue;
        }
        const inFlight = messagesInFlight.get(msg._id);
        if (inFlight !== undefined) {
          const age = Date.now() - inFlight.ts;
          if (age < IN_FLIGHT_HARD_TTL_MS) {
            logDelivery(`Skipping msg=${msg._id.slice(0, 8)} - already in flight (age=${Math.round(age / 1000)}s)`);
            continue;
          }
          logDelivery(`Reclaiming msg=${msg._id.slice(0, 8)} - in-flight ${Math.round(age / 1000)}s exceeds ${IN_FLIGHT_HARD_TTL_MS / 1000}s TTL, retrying`);
          messagesInFlight.delete(msg._id);
        }
        messagesInFlight.set(msg._id, { ts: Date.now(), conversationId: msg.conversation_id });

        // Per-conversation serialization: only one message delivers to a given tmux
        // pane at a time. The subscription fires reactively when the first completes,
        // giving the next message its turn.
        if (conversationDeliveryActive.has(msg.conversation_id)) {
          logDelivery(`Skipping msg=${msg._id.slice(0, 8)} - delivery already active for conv=${msg.conversation_id.slice(0, 12)}`);
          messagesInFlight.delete(msg._id);
          continue;
        }
        conversationDeliveryActive.add(msg.conversation_id);

        const imageIds = msg.image_storage_ids ?? (msg.image_storage_id ? [msg.image_storage_id] : []);
        logDelivery(`Processing: msg=${msg._id.slice(0, 8)} conv=${msg.conversation_id.slice(0, 12)} content="${msg.content.slice(0, 80)}" images=${imageIds.length} retry=${msg.retry_count ?? 0}`);

        let messageContent = msg.content;
        if (imageIds.length > 0) {
          const imagePaths: string[] = [];
          for (const storageId of imageIds) {
            try {
              const imagePath = await downloadImage(storageId, syncService);
              if (imagePath) {
                imagePaths.push(imagePath);
                log(`Downloaded image to ${imagePath}`);
              }
            } catch (err) {
              log(`Failed to download image: ${err instanceof Error ? err.message : String(err)}`);
            }
          }
          if (imagePaths.length > 0) {
            const realText = msg.content.replace(/^\[image\]$/i, "").trim();
            const imageTags = imagePaths.map(p => `[Image ${p}]`).join(" ");
            messageContent = realText ? `${realText} ${imageTags}` : imageTags;
          }
        }

        syncService.updateSessionAgentStatus(msg.conversation_id, "connected").catch(logConvexFailure);

        // If recently injected to tmux, skip re-delivery (prevents retry race causing duplicates).
        // Confirmed entries expire on the short TTL so a genuinely lost injection is redelivered;
        // unconfirmed entries (the "injected" mark never reached Convex, so this row is still
        // "pending" and reappears on every scanner pass) hold much longer — until the mark's
        // background retry confirms, the agent's echo promotes the row, or the hard cap lapses.
        // Exception: compaction recovery bypass allows re-delivery of messages dropped during CC compaction.
        const isCompactionRecovery = compactionRedeliveryBypass.delete(msg._id);
        const lastInjected = injectedMessageTs.get(msg._id);
        if (lastInjected && (Date.now() - lastInjected.ts) < injectionDedupWindowMs(lastInjected) && !isCompactionRecovery) {
          logDelivery(`DEDUP: msg=${msg._id.slice(0, 8)} injected ${Math.round((Date.now() - lastInjected.ts) / 1000)}s ago${lastInjected.confirmed ? "" : " (unconfirmed)"}, updating status only`);
          try {
            await syncService.updateMessageStatus({ messageId: msg._id, status: "injected" });
            lastInjected.confirmed = true; // a served status write IS the confirmation
          } catch {}
          messagesInFlight.delete(msg._id);
          conversationDeliveryActive.delete(msg.conversation_id);
          continue;
        }

        let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
        try {
          const delivered = await Promise.race([
            deliverMessage(
              msg.conversation_id,
              messageContent,
              conversationCache,
              syncService,
              msg._id,
              titleCache
            ),
            new Promise<never>((_, reject) => {
              timeoutHandle = setTimeout(
                () => reject(new Error(`deliverMessage timed out after ${DELIVERY_TIMEOUT_MS / 1000}s`)),
                DELIVERY_TIMEOUT_MS,
              );
            }),
          ]);
          if (delivered) {
            logDelivery(`SUCCESS: msg=${msg._id.slice(0, 8)} injected${isCompactionRecovery ? " (compaction recovery)" : ""}`);
            // The daemon just put a prompt in front of the agent — report the
            // turn start itself instead of waiting for the session's
            // UserPromptSubmit hook, which is lossy under load (5s timeout,
            // discarded output). A lost hook left the session looking
            // dormant/idle for minutes after a successful injection, which is
            // what kept the false "message hasn't reached the agent" banner
            // up. sendAgentStatus updates lastSentAgentStatus so heartbeats
            // carry the new status instead of stomping it; the pane
            // reconcile corrects the rare case where the submit didn't take.
            const injectedSessionId = buildReverseConversationCache(conversationCache)[msg.conversation_id];
            if (injectedSessionId) {
              sendAgentStatus(syncService, msg.conversation_id, injectedSessionId, "thinking");
            } else {
              syncService.updateSessionAgentStatus(msg.conversation_id, "thinking").catch(logConvexFailure);
            }
            // Restamp ts but keep the confirmed flag: markInjectedBestEffort registered the
            // entry pre-paste and may have already confirmed the status write.
            injectedMessageTs.set(msg._id, {
              ts: Date.now(),
              conversationId: msg.conversation_id,
              confirmed: injectedMessageTs.get(msg._id)?.confirmed ?? false,
            });
            // Track for post-compaction recovery: if CC compacts and goes idle,
            // we can re-inject this message. Skip on recovery re-injections to
            // prevent infinite compaction->recovery loops.
            if (!isCompactionRecovery) {
              recentSessionInjections.set(msg.conversation_id, {
                messageId: msg._id,
                content: messageContent,
                ts: Date.now(),
              });
            }
            // GC: evict expired entries to prevent unbounded growth (per-entry window:
            // confirmed = short TTL, unconfirmed = hard cap)
            if (injectedMessageTs.size > 500) {
              const now = Date.now();
              for (const [id, entry] of injectedMessageTs) {
                if (now - entry.ts > injectionDedupWindowMs(entry)) injectedMessageTs.delete(id);
              }
            }
          } else {
            logDelivery(`FAILED: msg=${msg._id.slice(0, 8)} delivery returned false, scheduling retry ${(msg.retry_count ?? 0) + 1}`);
            // The pre-paste dedup entry must not survive a failed delivery — it would
            // block the retry it just scheduled (and abort the mark's background retry,
            // which is correct: an "injected" write for an undelivered message strands it).
            injectedMessageTs.delete(msg._id);
            scheduleMessageRetry(msg._id, msg.retry_count ?? 0, msg.conversation_id, messageContent);
          }
        } catch (err) {
          const errMsg = err instanceof Error ? err.message : String(err);
          injectedMessageTs.delete(msg._id);
          if (err instanceof UndeliverableMessageError) {
            // Terminal by construction: cancel (a status the server never
            // re-pends) instead of burning the retry ladder.
            logDelivery(`CANCELLED: msg=${msg._id.slice(0, 8)} can never be delivered: ${errMsg}`);
            syncService.cancelPendingMessage(msg._id).catch(logConvexFailure);
          } else {
            logDelivery(`ERROR: msg=${msg._id.slice(0, 8)} exception: ${errMsg}`);
            scheduleMessageRetry(msg._id, msg.retry_count ?? 0, msg.conversation_id, msg.content);
          }
        } finally {
          if (timeoutHandle) clearTimeout(timeoutHandle);
          messagesInFlight.delete(msg._id);
          conversationDeliveryActive.delete(msg.conversation_id);
        }
      }
    } else {
      log(`Received non-array: ${typeof messages}`);
    }

    resetReconnectDelay();
  };

  // A subscribed query that errors SERVER-SIDE (e.g. "timed out performing too
  // many system operations" during a backend brownout) becomes a zombie: the
  // client keeps the listener registered, but convex only re-executes an errored
  // query when its recorded read set changes — and a failed execution may leave
  // none. Without an onError handler the error surfaced as a single unhandled
  // rejection and the delivery rail stayed silent until the next daemon restart
  // (2026-08-30: eight hours of stranded pending sends). Tearing down and
  // resubscribing issues a fresh AddQuery, which forces a fresh server execution.
  const makeSubscriptionErrorHandler = (name: string, teardown: () => void, resubscribe: () => void) => {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (err: unknown) => {
      if (timer) return;
      try { teardown(); } catch {}
      const delay = getReconnectDelay();
      const msg = err instanceof Error ? err.message : String(err);
      logDelivery(`${name} subscription errored (${msg.slice(0, 200)}); resubscribing in ${Math.round(delay / 1000)}s`);
      timer = setTimeout(() => {
        timer = null;
        resubscribe();
      }, delay);
    };
  };

  const setupSubscription = () => {
    try {
      logDelivery("Setting up pending messages subscription");
      unsubscribe = subscriptionClient.onUpdate(
        "pendingMessages:getPendingMessagesForDaemon" as any,
        { api_token: config.auth_token, device_id: deviceId() },
        handlePendingMessagesUpdate,
        makeSubscriptionErrorHandler(
          "Pending messages",
          () => { if (unsubscribe) { unsubscribe(); unsubscribe = null; } },
          () => setupSubscription(),
        ),
      );
      logDelivery("Pending messages subscription established");
      // Registering a subscription does NOT prove the WebSocket is up:
      // onUpdate() returns synchronously and silently queues on a dead socket,
      // so asserting connected:true here lies whenever the socket later dies
      // mid-run (e.g. after a sleep) — the flag stays true through real
      // outages. The truthful connected/disconnected flag is driven below by
      // subscribeToConnectionState off the live WebSocket state instead.
      if (reconnectAttempt > 0) {
        sendLogImmediate("info", `[LIFECYCLE] connection_restored: after ${reconnectAttempt} attempts`, { error_code: "connection_restored" });
      }
      resetReconnectDelay();
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      logError("Subscription error", error);
      saveDaemonState({ connected: false });
      if (unsubscribe) {
        unsubscribe();
        unsubscribe = null;
      }

      const delay = getReconnectDelay();
      logWarn(`Connection lost, reconnecting in ${delay}ms (attempt ${reconnectAttempt})`);
      if (reconnectAttempt <= 3 || reconnectAttempt % 10 === 0) {
        sendLogImmediate("warn", `Connection lost, attempt ${reconnectAttempt}: ${error.message}`, {
          error_code: "connection_lost",
          stack: error.stack?.slice(0, 500),
        });
      }
      setTimeout(() => {
        setupSubscription();
      }, delay);
    }
  };

  setupSubscription();

  // Belt and suspenders for the rail above: a reactive subscription can die in
  // ways the onError path never sees (silent half-open socket, a server error
  // state with no read set left to invalidate it). The poll asks the same query
  // directly, so any silent subscription death stalls delivery by at most one
  // interval instead of until the next daemon restart. Duplicate feeds are safe
  // (see handlePendingMessagesUpdate).
  const PENDING_POLL_INTERVAL_MS = 60_000;
  let pendingPollInFlight = false;
  setInterval(() => {
    if (pendingPollInFlight) return;
    pendingPollInFlight = true;
    (async () => {
      const messages = await syncService.getClient().query(
        "pendingMessages:getPendingMessagesForDaemon" as any,
        { api_token: config.auth_token, device_id: deviceId() },
      );
      if (Array.isArray(messages) && messages.length > 0) {
        logDelivery(`Poll: ${messages.length} pending message(s) found by fallback scan`);
        await handlePendingMessagesUpdate(messages);
      }
    })().catch((err) => {
      log(`Pending poll fallback failed: ${err instanceof Error ? err.message : String(err)}`);
    }).finally(() => {
      pendingPollInFlight = false;
    });
  }, PENDING_POLL_INTERVAL_MS);

  const setupPermissionSubscription = () => {
    try {
      log("Setting up permission responses subscription");
      permissionUnsubscribe = subscriptionClient.onUpdate(
        "permissions:getAllRespondedPermissions" as any,
        { user_id: config.user_id, api_token: config.auth_token },
        async (permissions: any) => {
          log(`Permission subscription update received: ${JSON.stringify(permissions)?.slice(0, 200)}`);

          if (!permissions || !Array.isArray(permissions)) {
            log("No permissions in update or invalid format");
            return;
          }

          for (const permission of permissions) {
            if (processedPermissionIds.has(permission._id)) {
              continue;
            }

            log(`New permission response: ${permission._id} status=${permission.status} tool=${permission.tool_name}`);

            // "cancelled" means the daemon itself marked the record resolved
            // because the agent moved past the permission point. Injecting
            // Enter/Escape would land in a TUI that no longer has a prompt
            // open and corrupt the next user input.
            if (permission.status === "cancelled") {
              processedPermissionIds.add(permission._id);
              continue;
            }

            try {
              const approved = permission.status === "approved";
              const key = approved ? "Enter" : "Escape";
              const sessionId = permission.session_id;
              let injected = false;

              if (sessionId) {
                const proc = await findSessionProcess(sessionId, detectSessionAgentType(sessionId));
                if (proc) {
                  const tmuxTarget = await findTmuxPaneForTty(proc.tty);
                  if (tmuxTarget) {
                    try {
                      await tmuxExec(["send-keys", "-t", tmuxTarget, key]);
                      injected = true;
                    } catch {}
                  }
                  if (!injected) {
                    try {
                      await injectViaTerminal(proc.tty, approved ? "\r" : "\x1b", proc.termProgram, { keystrokes: true });
                      injected = true;
                    } catch {}
                  }
                }
              }

              if (injected) {
                log(`Injected permission '${key}' for session ${sessionId?.slice(0, 8)}`);
              } else {
                // Check if the permission is stale (resolved > 60s ago) — no point retrying
                const resolvedAge = permission.resolved_at ? Date.now() - permission.resolved_at : Infinity;
                if (resolvedAge > 60_000) {
                  log(`Skipping stale permission response for session ${sessionId?.slice(0, 8)} (resolved ${Math.round(resolvedAge / 1000)}s ago)`);
                } else {
                  log(`Failed to inject permission response for session ${sessionId?.slice(0, 8)}, will retry on next update`);
                }
              }
              // Always mark as processed — if the session process is gone, retrying won't help
              processedPermissionIds.add(permission._id);
            } catch (err) {
              const errMsg = err instanceof Error ? err.message : String(err);
              log(`Error handling permission response: ${errMsg}`);
            }
          }

          resetReconnectDelay();
        },
        makeSubscriptionErrorHandler(
          "Permission",
          () => { if (permissionUnsubscribe) { permissionUnsubscribe(); permissionUnsubscribe = null; } },
          () => setupPermissionSubscription(),
        ),
      );
      log("Permission subscription established successfully");
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      logError("Permission subscription error", error);
      if (permissionUnsubscribe) {
        permissionUnsubscribe();
        permissionUnsubscribe = null;
      }

      const delay = getReconnectDelay();
      logWarn(`Permission subscription lost, reconnecting in ${delay}ms`);
      setTimeout(() => {
        setupPermissionSubscription();
      }, delay);
    }
  };

  setupPermissionSubscription();

  const setupCommandSubscription = () => {
    try {
      log("Setting up daemon commands subscription");
      commandUnsubscribe = subscriptionClient.onUpdate(
        "users:getMyPendingCommands" as any,
        { api_token: config.auth_token, device_id: deviceId() },
        async (commands: any) => {
          if (!commands || !Array.isArray(commands) || commands.length === 0) {
            return;
          }

          log(`Command subscription update: ${commands.length} pending command(s)`);

          for (const cmd of commands) {
            if (processedCommandIds.has(cmd.id) || processedPollCommandIds.has(cmd.id)) {
              continue;
            }

            processedCommandIds.add(cmd.id);
            processedPollCommandIds.add(cmd.id);
            log(`[SUBSCRIPTION] Executing command: ${cmd.command} (${cmd.id})`);
            await executeRemoteCommand(cmd.id, cmd.command, config, cmd.args);
          }

          resetReconnectDelay();
        },
        makeSubscriptionErrorHandler(
          "Command",
          () => { if (commandUnsubscribe) { commandUnsubscribe(); commandUnsubscribe = null; } },
          () => setupCommandSubscription(),
        ),
      );
      log("Command subscription established successfully");
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      logError("Command subscription error", error);
      if (commandUnsubscribe) {
        commandUnsubscribe();
        commandUnsubscribe = null;
      }

      const delay = getReconnectDelay();
      logWarn(`Command subscription lost, reconnecting in ${delay}ms`);
      setTimeout(() => {
        setupCommandSubscription();
      }, delay);
    }
  };

  setupCommandSubscription();

  // Keep the persisted `connected` flag (what `cast status` shows as
  // "Convex: connected/disconnected") honest by driving it off the live Convex
  // WebSocket state. Without this the flag was set once at subscription
  // registration and only cleared on startup/shutdown, so it couldn't tell a
  // live socket from one that silently died after a sleep — reading "connected"
  // straight through a sync outage. subscribeToConnectionState fires on every
  // transition; ConnectionState also changes on inflight-request counts, so
  // dedupe to socket up/down edges to avoid churning daemon.state on every
  // mutation. Seed from the current state so we don't wait for the first change.
  let lastConnectedWritten: boolean | undefined;
  const publishConnectionState = (cs: { isWebSocketConnected: boolean }) => {
    if (cs.isWebSocketConnected === lastConnectedWritten) return;
    // A genuine false→true edge (not the initial seed from `undefined`) means
    // the socket just came back after an outage — most commonly a laptop wake.
    // Recover gracefully instead of letting the UI sit on scary states: drain
    // the retry backlog now (otherwise queued ops wait out a backoff scheduled
    // against the dead socket — up to 5 min — and surface as "sync stalled"),
    // and refresh the heartbeat immediately so `daemon_last_seen` is current and
    // the web "daemon offline" banner clears at once rather than after the next
    // 30s tick.
    const restored = lastConnectedWritten === false && cs.isWebSocketConnected;
    lastConnectedWritten = cs.isWebSocketConnected;
    saveDaemonState({ connected: cs.isWebSocketConnected });
    if (restored) {
      retryQueueRef?.notifyConnectionRestored();
      sendHeartbeat().catch(() => {});
    }
  };
  try {
    publishConnectionState(subscriptionClient.connectionState());
    subscriptionClient.subscribeToConnectionState(publishConnectionState);
  } catch (err) {
    logWarn(`Could not subscribe to Convex connection state: ${err instanceof Error ? err.message : String(err)}`);
  }

  const shutdown = async () => {
    skipRespawn = true;
    log("Shutting down gracefully");

    // Hard exit guarantee: if graceful shutdown takes too long, force exit.
    // This prevents zombie daemons that hold the event loop open via in-flight retries.
    const hardExitTimer = setTimeout(() => {
      try { fs.appendFileSync(LOG_FILE, `[${new Date().toISOString()}] [CRITICAL] Hard exit after shutdown timeout\n`); } catch {}
      releasePidFileIfOwned(PID_FILE, process.pid);
      try { fs.unlinkSync(VERSION_FILE); } catch {}
      process.exit(1);
    }, 15_000);
    hardExitTimer.unref();

    saveDaemonState({ connected: false });

    if (unsubscribe) {
      unsubscribe();
    }
    fencedRuntime?.stop();

    if (permissionUnsubscribe) {
      permissionUnsubscribe();
    }

    if (commandUnsubscribe) {
      commandUnsubscribe();
    }

    clearInterval(watchdogInterval);
    clearInterval(versionCheckInterval);
    clearInterval(reconciliationInterval);
    clearInterval(eventLoopMonitorInterval);
    clearInterval(statusCleanupInterval);
    log("Watchdog and reconciliation stopped");

    stopHookServer();
    statusWatcher.close();
    watcher.stop();
    cursorWatcher.stop();
    cursorTranscriptWatcher.stop();
    for (const dirEventWatcher of dirEventWatchers) {
      dirEventWatcher.stop();
    }
    codexAppServerInstance?.stop();
    opencodeServerInstance?.stop();

    retryQueue.stop();

    const pendingOps = retryQueue.getQueueSize();
    if (pendingOps > 0) {
      log(`Dropping ${pendingOps} pending retry operations`);
    }

    for (const sync of fileSyncs.values()) {
      sync.stop();
    }
    for (const sync of cursorSyncs.values()) {
      sync.stop();
    }
    for (const sync of cursorTranscriptSyncs.values()) {
      sync.stop();
    }

    if (releasePidFileIfOwned(PID_FILE, process.pid)) {
      log("PID file removed");
    }
    try { fs.unlinkSync(VERSION_FILE); } catch {}

    logLifecycle("daemon_stop", "graceful shutdown");
    sendLogImmediate("info", "[LIFECYCLE] daemon_stop: graceful shutdown", { error_code: "daemon_stop" });
    await flushRemoteLogs();
    persistLogQueue();
    process.exit(0);
  };

  process.on("SIGTERM", () => {
    shutdown().catch((err) => {
      log(`Shutdown error: ${err instanceof Error ? err.message : String(err)}`);
      process.exit(1);
    });
  });

  process.on("SIGINT", () => {
    shutdown().catch((err) => {
      log(`Shutdown error: ${err instanceof Error ? err.message : String(err)}`);
      process.exit(1);
    });
  });

  await new Promise(() => {});
}

// Flag to prevent double execution when imported and called via runDaemon
let daemonStarted = false;

export async function runDaemon(): Promise<void> {
  if (daemonStarted) return;
  daemonStarted = true;
  return main();
}

export async function runWatchdog(): Promise<void> {
  const config = readConfig();
  if (!config?.auth_token || !config?.convex_url) {
    process.exit(0);
  }

  const siteUrl = config.convex_url.replace(".cloud", ".site");
  const version = getVersion();
  const logLine = (msg: string) => {
    try { fs.appendFileSync(LOG_FILE, `[${new Date().toISOString()}] [watchdog] ${msg}\n`); } catch {}
  };

  // 1. Report crash loop info if crash file exists
  if (fs.existsSync(CRASH_FILE)) {
    try {
      const crashes = JSON.parse(fs.readFileSync(CRASH_FILE, "utf-8"));
      if (crashes.count > 3) {
        await fetch(`${siteUrl}/cli/log`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            api_token: config.auth_token,
            level: "error",
            message: `CRASH LOOP: ${crashes.count} crashes since ${new Date(crashes.firstCrash).toISOString()}, watchdog reporting`,
            metadata: { error_code: "crash_loop" },
            cli_version: version,
            platform: process.platform,
          }),
        }).catch(() => {});
      }
    } catch {}
  }

  // 2. Check if daemon is alive (process exists AND event loop is responsive)
  let daemonAlive = false;
  let daemonPid = 0;
  if (fs.existsSync(PID_FILE)) {
    try {
      daemonPid = parseInt(fs.readFileSync(PID_FILE, "utf-8").trim(), 10);
      if (daemonPid > 0) {
        process.kill(daemonPid, 0);
        daemonAlive = true;
      }
    } catch {
      daemonAlive = false;
    }
  }

  // 2b. If process is alive, check if event loop is actually responsive.
  // The tick freezes during system sleep exactly like a wedged loop, and this
  // pass usually runs before the woken daemon's 30s stamp interval fires — so a
  // stale tick only counts when our OWN start-to-start gap shows we've been
  // continuously awake (see daemonTickStale). Killing on tick age alone SIGKILLed
  // a healthy daemon on nearly every wake of a napping laptop.
  const passStampPath = path.join(CONFIG_DIR, WATCHDOG_PASS_STAMP_FILENAME);
  const passNow = Date.now();
  let prevPass = 0;
  try { prevPass = parseInt(fs.readFileSync(passStampPath, "utf-8").trim(), 10) || 0; } catch {}
  try { fs.writeFileSync(passStampPath, String(passNow)); } catch {}
  const passGap = prevPass > 0 ? passNow - prevPass : null;
  if (daemonAlive && daemonPid > 0) {
    try {
      const state = readDaemonState();
      const lastTick = state.lastHeartbeatTick || state.lastWatchdogCheck || 0;
      const staleness = passNow - lastTick;
      if (lastTick > 0 && staleness > DAEMON_HEARTBEAT_STALE_MS) {
        // A busy boot starves the tick stamper but keeps writing daemon.log; a
        // truly wedged loop runs no JS and cannot log (see daemonTickStale).
        let logAgeMs: number | null = null;
        try { logAgeMs = passNow - fs.statSync(path.join(CONFIG_DIR, "daemon.log")).mtimeMs; } catch {}
        if (daemonTickStale(staleness, passGap, logAgeMs)) {
          logLine(`Daemon PID ${daemonPid} is alive but event loop frozen for ${Math.round(staleness / 1000)}s, killing`);
          try { process.kill(daemonPid, 9); } catch {}
          await new Promise(resolve => setTimeout(resolve, 1000));
          daemonAlive = false;
        } else if (logAgeMs !== null && logAgeMs <= DAEMON_HEARTBEAT_STALE_MS) {
          logLine(`Daemon tick stale ${Math.round(staleness / 1000)}s but daemon.log written ${Math.round(logAgeMs / 1000)}s ago — busy, not wedged`);
        } else {
          logLine(`Daemon tick stale ${Math.round(staleness / 1000)}s but watchdog pass gap ${passGap === null ? "unknown" : Math.round(passGap / 1000) + "s"} implies system sleep — deferring one cycle`);
        }
      }
    } catch {}
  }

  // 3. Send heartbeat (keeps server aware even if daemon is dead)
  let commands: Array<{ id: string; command: string }> = [];
  let minCliVersion: string | undefined;
  try {
    const response = await fetch(`${siteUrl}/cli/heartbeat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        api_token: config.auth_token,
        version: daemonAlive ? version : `${version}-watchdog`,
        platform: process.platform,
        pid: 0,
        autostart_enabled: true,
      }),
    });
    if (response.ok) {
      const data = await response.json();
      commands = data.commands || [];
      minCliVersion = data.min_cli_version;
    }
  } catch {}

  // 3b. Check min_cli_version -- if daemon binary is outdated, update it
  // This catches cases where the daemon's own checkForForcedUpdate failed or killed the daemon
  const sendWatchdogLog = async (level: string, message: string) => {
    await fetch(`${siteUrl}/cli/log`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        api_token: config.auth_token,
        level,
        message,
        cli_version: `${version}-watchdog`,
        platform: process.platform,
      }),
    }).catch(() => {});
  };

  if (minCliVersion && compareVersions(version, minCliVersion) < 0) {
    logLine(`Binary outdated: current=${version} min=${minCliVersion}, updating...`);
    await sendWatchdogLog("info", `[LIFECYCLE] watchdog_update_start: current=${version} min=${minCliVersion}`);
    const result = await performUpdate();
    if (result.success) {
      logLine("Watchdog update successful");
      await sendWatchdogLog("info", `[LIFECYCLE] watchdog_update_complete: ${version} -> ${minCliVersion}`);
      clearCrashCount();
      // Kill the running daemon so it restarts with the new binary
      if (daemonAlive && daemonPid > 0) {
        logLine(`Killing outdated daemon PID ${daemonPid}`);
        try { process.kill(daemonPid, 15); } catch {}
        await new Promise(resolve => setTimeout(resolve, 2000));
        daemonAlive = false;
      }
    } else {
      logLine(`Watchdog update failed: ${result.error}`);
      await sendWatchdogLog("warn", `[LIFECYCLE] watchdog_update_failed: current=${version} target>=${minCliVersion} error=${result.error}`);
    }
  }

  // 3c. If daemon is alive but running an older version than the binary, kill it
  if (daemonAlive && daemonPid > 0) {
    try {
      const state = readDaemonState();
      const daemonVersion = state.runtimeVersion;
      // If runtimeVersion is missing, daemon predates this field -- assume outdated if min_cli_version is set
      const needsKill = daemonVersion
        ? compareVersions(daemonVersion, version) < 0
        : !!(minCliVersion && compareVersions(version, minCliVersion) >= 0);
      if (needsKill) {
        logLine(`Daemon running v${daemonVersion || "unknown"} but binary is v${version}, killing to upgrade`);
        await sendWatchdogLog("info", `[LIFECYCLE] watchdog_version_mismatch: daemon=${daemonVersion || "unknown"} binary=${version}, killing`);
        try { process.kill(daemonPid, 15); } catch {}
        await new Promise(resolve => setTimeout(resolve, 2000));
        daemonAlive = false;
      }
    } catch {}
  }

  // 4. If daemon is dead, restart it
  if (!daemonAlive) {
    logLine("Daemon not running, restarting...");

    // Handle force_update before restart so daemon starts with new binary
    const updateCmd = commands.find(c => c.command === "force_update");
    if (updateCmd) {
      logLine("Force update pending, updating before restart...");
      const result = await performUpdate();
      // Report result
      await fetch(`${siteUrl}/cli/command-result`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          api_token: config.auth_token,
          command_id: updateCmd.id,
          result: result.success ? "Updated by watchdog" : undefined,
          error: result.success ? undefined : `Watchdog update failed: ${result.error}`,
        }),
      }).catch(() => {});
      if (result.success) {
        logLine("Update successful");
        clearCrashCount();
      }
      commands = commands.filter(c => c.id !== updateCmd.id);
    }

    // Mark remaining commands as executed (daemon will get fresh ones on reconnect)
    for (const cmd of commands) {
      await fetch(`${siteUrl}/cli/command-result`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          api_token: config.auth_token,
          command_id: cmd.id,
          result: `Handled by watchdog (daemon was dead): restarting`,
        }),
      }).catch(() => {});
    }

    // Spawn daemon
    clearCrashCount();
    const { executablePath, args } = getDaemonExecInfo();
    try {
      const child = spawn(executablePath, args, {
        detached: true,
        stdio: "ignore",
        env: { ...process.env, CODECAST_RESTART: "1" },
      });
      child.unref();
      logLine("Daemon restarted");
    } catch (err) {
      logLine(`Failed to restart daemon: ${err}`);
    }
  } else if (commands.some(c => c.command === "force_update")) {
    // Daemon is alive but has pending force_update -- it should handle it via subscription
    // But if it hasn't within reasonable time, the watchdog can nudge by sending SIGUSR1
    logLine("Daemon alive with pending force_update, daemon should handle via subscription");
  }
}

function getDaemonExecInfo(): { executablePath: string; args: string[] } {
  const execPath = process.execPath;
  const isBinary = !execPath.endsWith("/bun") && !execPath.endsWith("/node") && !execPath.includes("node_modules");
  if (isBinary) {
    return { executablePath: execPath, args: ["--", "_daemon"] };
  }
  return { executablePath: execPath, args: [path.resolve(__dirname, "daemon.js")] };
}

// Only run directly if executed as the main module (not when imported)
if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith("daemon.js")) {
  daemonStarted = true;
  main().catch((err) => {
    logError("Fatal error", err instanceof Error ? err : new Error(String(err)));
    flushRemoteLogs().finally(() => process.exit(1));
  });
}
